return {
  ["Act_E1_1A_CliffFuture_VoiceOver_Max_010"] = "Nunca vi una tormenta como esta en Oregón...",
  ["Act_E1_1A_CliffFuture_VoiceOver_Max_020"] = "Si sigo este rastro, quizá pueda encontrar una salida...",
  ["Act_E1_1A_CliffFuture_VoiceOver_Max_030"] = "Se siente como el fin del mundo...",
  ["Act_E1_1A_CliffFuture_VoiceOver_Max_040"] = "El faro está adelante, si pudiera llegar...",
  ["Act_E1_1A_CliffFuture_VoiceOver_Max_050"] = "Vamos, Max, puedes hacerlo...",
  ["Cue_E1_1A_CliffFuture_IntroStorm_Max_010"] = "¿Dónde estoy? ¿Qué está pasando?",
  ["Cue_E1_1A_CliffFuture_IntroStorm_Max_020"] = "¿Estoy atrapada en una tormenta? ¿Cómo llegué hasta aquí? ¿Y dónde es \"aquí\"?",
  ["Cue_E1_1A_CliffFuture_IntroStorm_Max_030"] = "Un momento... Allí está el faro... Estaré a salvo si puedo llegar allí... Espero... Por favor, que pueda llegar allí...",
  ["Cue_E1_1A_CliffFuture_LighthouseBreak_Max_010"] = "La gran puta.",
  ["Cue_E1_1A_CliffFuture_LighthouseBreak_Max_030"] = "¡NO!",
  ["Cue_E1_1A_CliffFuture_LighthouseBreak_Max_040"] = "¡Vaya! ¡No!",
  ["Cue_E1_1A_CliffFuture_MaxFall_Max_010"] = "Mierda, ni siquiera puedo caminar en línea recta.",
  ["Cue_E1_1A_CliffFuture_MaxFall_Max_020"] = "Este viento podría llevarme volando...",
  ["Act_E1_2A_ArtClass_ArcadiaPicture01_Look01_Max_010"] = "Arcadia Bay luce mucho más majestuosa desde aquí...",
  ["Act_E1_2A_ArtClass_ArcadiaPicture02_Look01_Max_010"] = "Hasta en las fotos, el bosque de la zona luce misterioso...",
  ["Act_E1_2A_ArtClass_ArcadiaPicture03_Look01_Max_010"] = "Nunca podrás escapar del faro aquí...",
  ["Act_E1_2A_ArtClass_Books_Look01_Max_010"] = "Qué bueno poder tomarlos prestado cuando queramos... \"El momento decisivo\", de Henri Cartier-Bresson. Qué raro... Annie Leibovitz, mi ídolo... el increíble Eugene Smith... Es bueno ver a Avedon entre los maestros... Dalí, por supuesto... Mucha gente que aún no escuché nombrar... Imagino que para eso estoy aquí.",
  ["Act_E1_2A_ArtClass_CHJefferson_Look01_Max_010"] = "Esto es ridículo. Siempre me pongo nerviosa y tímida cerca del Sr. Jefferson.",
  ["Act_E1_2A_ArtClass_CHJefferson_Look02_Max_010"] = "Quisiera hablar con el Sr. Jefferson sobre lo que está pasando... pero no puedo.",
  ["Act_E1_2A_ArtClass_CHKate_Look01_Max_010"] = "Kate luce tan triste y callada hoy. Pobre.",
  ["Act_E1_2A_ArtClass_CHKate_Look02_Max_010"] = "Kate no se reiría de mí, pero ¿cómo puedo preguntarle qué está pasando?",
  ["Act_E1_2A_ArtClass_Computer_Interact01_Max_010"] = "Parece que alguien ya estuvo trabajando en esto... fantástico.",
  ["Act_E1_2A_ArtClass_Computer_Look01_Max_010"] = "Es obvio que Blackwell invirtió dinero en las computadoras aquí.",
  ["Act_E1_2A_ArtClass_DanielTable_Look01_Max_010"] = "Mmm, esta sería una gran foto...",
  ["Act_E1_2A_ArtClass_Diary_Interact01_Max_010"] = "Si otra persona mirara esto, ¿qué pensaría?",
  ["Act_E1_2A_ArtClass_Diary_Look01_Max_010"] = "No he actualizado mi diario tanto como debería.",
  ["Act_E1_2A_ArtClass_Diary_Look02_Max_010"] = "¿Qué está pasando? Nada se movió en absoluto.",
  ["Act_E1_2A_ArtClass_Drawer01_Look01_Max_010"] = "Mira esto... ¡disparadores de lujo, lentes más potentes y películas de 35 mm en cajas originales! Incluso con el increíble equipo nuevo, todavía adoro mi cámara hipster y el papel satinado.",
  ["Act_E1_2A_ArtClass_Generic_Look01_Max_010"] = "En marcha, Max. ¡No tienes tiempo!",
  ["Act_E1_2A_ArtClass_Generic_Look02_Max_010"] = "¿Qué estás esperando? ¡Vamos!",
  ["Act_E1_2A_ArtClass_Generic_Look03_Max_010"] = "¡No es tan interesante como la muchacha que está por morir!",
  ["Act_E1_2A_ArtClass_Generic_Look04_Max_010"] = "¡Debes llegar a ese baño!",
  ["Act_E1_2A_ArtClass_Generic_Look05_Max_010"] = "¡Déjate de tonterías y ve a salvar a esa muchacha!",
  ["Act_E1_2A_ArtClass_Generic_Look06_Max_010"] = "¿Cuánto tiempo vas a estar paralizada? ¡Muévete!",
  ["Act_E1_2A_ArtClass_Generic_Look07_Max_010"] = "¡Si no vas, le van a disparar!",
  ["Act_E1_2A_ArtClass_Generic_Look08_Max_010"] = "¡No hay tiempo para estupideces!",
  ["Act_E1_2A_ArtClass_Generic_Look09_Max_010"] = "¡Esa muchacha necesita tu ayuda ahora!",
  ["Act_E1_2A_ArtClass_Generic_Look10_Max_010"] = "¡Tonta, lo estás arruinando! ¡Salva a la muchacha!",
  ["Act_E1_2A_ArtClass_Generic_Look11_Max_010"] = "No tienes tiempo para quedarte mirando. ¡Sal de aquí!",
  ["Act_E1_2A_ArtClass_Generic_Look12_Max_010"] = "¡Deja de perder tiempo! ¡Vamos!",
  ["Act_E1_2A_ArtClass_GroupPhoto_Look01_Max_010"] = "Eso fue genial, cuando la primera semana, el Sr. Jefferson tomó una foto de la clase. Aunque yo no quería estar en la foto, me pareció bastante increíble cómo intentaba que entráramos n el marco.",
  ["Act_E1_2A_ArtClass_Ipad_Interact01_Max_010"] = "Debí haberlo sabido. Obvio, ella tiene un mejor equipo que el de Blackwell.",
  ["Act_E1_2A_ArtClass_Ipad_Look01_Max_010"] = "Por supuesto, Victoria necesita tener lo mejor, lo más nuevo y lo más costoso.",
  ["Act_E1_2A_ArtClass_JeffersonCamera_Look01_Max_010"] = "¡Vaya! El Sr. Jefferson sí que sabe lo que es una cámara. Seguro que pagó veinte mil dólares por ella... Apuesto a que obtiene imágenes digitales impecables. Igual, adoro mi pequeña cámara instantánea.",
  ["Act_E1_2A_ArtClass_MaxBag_Look01_Max_010"] = "El bolso de mi cámara está gastado, pero todavía sirve.",
  ["Act_E1_2A_ArtClass_MaxBag_Look02_Max_010"] = "¡Mierda, todo es igual!",
  ["Act_E1_2A_ArtClass_PaperBall_Interact01_Max_010"] = "Ahora desearía no haber leído esto. ¡Deshazte de eso!",
  ["Act_E1_2A_ArtClass_PaperBall_Look01_Max_010"] = "Sé que no debería leer esto... pero soy entrometida.",
  ["Act_E1_2A_ArtClass_PencilCase_Look01_Max_010"] = "No puedo creer que todavía tenga este estuche. Debería actualizarme y entrar al siglo XXI. Pero me gustan las cosas tradicionales.",
  ["Act_E1_2A_ArtClass_PencilCase_Look02_Max_010"] = "Mi estuche sigue en el mismo lugar...",
  ["Act_E1_2A_ArtClass_PhotoBook_Look01_Max_010"] = "Esta es la única clase en la que tomar notas realmente está bueno.",
  ["Act_E1_2A_ArtClass_PhotoBook_Look02_Max_010"] = "Bien, todo está exactamente igual... ¿Por qué?",
  ["Act_E1_2A_ArtClass_PhotoStuff01_Look01_Max_010"] = "Mierda, aquí tienen trípodes de fibra de carbono. ¿El cabezal incluso tiene un bloqueador de movimiento? Dios, soy una nerd de la fotografía.",
  ["Act_E1_2A_ArtClass_PhotoStuff02_Look01_Max_010"] = "Definitivamente, aquí es donde las cámaras van al cielo... ¡Dios! Tienen esas fantásticas lentes ultrasónicas... ¡y ese telémetro retro! ¡Lo quiero!",
  ["Act_E1_2A_ArtClass_Photo_Look01_Max_010"] = "¡Mira esta basura! ¡No puedo mostrársela al Sr. Jefferson! Puedo oír a la clase riéndose de mí.",
  ["Act_E1_2A_ArtClass_Photo_Look02_Max_010"] = "La misma foto estúpida... Todo parece igual que antes.",
  ["Act_E1_2A_ArtClass_PlasmaTV_Look01_Max_010"] = "Hasta tiene el mejor TV de plasma como monitor de clase. No puedo esperar para ver más documentales en este gigantón.",
  ["Act_E1_2A_ArtClass_Polaroid_Look01_Max_010"] = "Me encanta mi cámara analógica. Debería tomar una foto rápida ahora.",
  ["Act_E1_2A_ArtClass_Polaroid_Look02_Max_010"] = "Lo siento, Max. No más selfis por ahora.",
  ["Act_E1_2A_ArtClass_Polaroid_Look03_Max_010"] = "Increíble, mi vieja cámara rota está nueva otra vez…",
  ["Act_E1_2A_ArtClass_Poster01_Look01_Max_010"] = "Aquí está el cartel para el concurso... El Sr. Jefferson realmente pretende que participe. ¿Por qué? No sé si estoy lista para mis 15 minutos de infamia.",
  ["Act_E1_2A_ArtClass_Poster01_Look02_Max_010"] = "¡Si quiero ser una \"heroína cotidiana\", mejor voy a salvar a esa muchacha!",
  ["Act_E1_2A_ArtClass_Poster02_Look01_Max_010"] = "Es fantástico poder ver las fotos publicadas del Sr. Jefferson. Me da esperanza.",
  ["Act_E1_2A_ArtClass_Poster03_Look01_Max_010"] = "Adoro ver las increíbles fotos del Sr. Jefferson en estas portadas.",
  ["Act_E1_2A_ArtClass_Printer_Look01_Max_010"] = "Esa impresora es fenomenal. Me encantaría ver cómo reproduce mis fotos. Podría armar una galería entera con esa cosa. Cuando deje de ser tan mala. Algún día...",
  ["Act_E1_2A_ArtClass_Taylor_Look01_Max_010"] = "Taylor, una de las mejores amigas de Victoria.",
  ["Act_E1_2A_ArtClass_Taylor_Look02_Max_010"] = "Ya viví eso...",
  ["Act_E1_2A_ArtClass_TextBook_Look01_Max_010"] = "Hasta sus libros escolares están envueltos para regalo. No puedo creer que se burlara de mí en clase. ¿Qué tiene, quince años? Y los demás se rieron...",
  ["Act_E1_2A_ArtClass_Victoria_Look01_Max_010"] = "Cada vez que veo a Victoria siento que está hablando mal de mí.",
  ["Act_E1_2A_ArtClass_Victoria_Look02_Max_010"] = "Victoria no se ha movido de ese lugar...",
  ["Act_E1_2A_ArtClass_VoiceOver01_Max_010"] = "Eso fue tan surrealista.",
  ["Act_E1_2A_ArtClass_VoiceOver01_Max_020"] = "De acuerdo, Max, todo está bien.",
  ["Act_E1_2A_ArtClass_VoiceOver01_Max_030"] = "Relájate. Nadie te ha drogado.",
  ["Act_E1_2A_ArtClass_VoiceOver01_Max_040"] = "Debería tomar una foto para demostrar que sigo aquí...",
  ["Act_E1_2A_ArtClass_VoiceOver01_Max_050"] = "Además, es perfecta para mi currículum.",
  ["Act_E1_2A_ArtClass_VoiceOver01_Max_060"] = "Y tengo que cumplir con mi cuota diaria de selfis.",
  ["Act_E1_2A_ArtClass_VoiceOver02_Max_010"] = "Victoria no pierde un segundo para lamer botas.",
  ["Act_E1_2A_ArtClass_VoiceOver02_Max_020"] = "Otro fracaso diario para que el mundo lo vea.",
  ["Act_E1_2A_ArtClass_VoiceOver02_Max_030"] = "Cómo me gusta lucir como una idiota en la clase de mi profesor favorito.",
  ["Act_E1_2A_ArtClass_VoiceOver03_Max_010"] = "Bien hecho, Max. Idiota.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_010"] = "¡Vaya! ¿Qué carajo...?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_050"] = "¡Dios!, eso fue tan real, tan... extraño.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_060"] = "¿Qué me acaba de pasar?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_080"] = "Estaba en el baño...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_100"] = "Él le disparó a esa pobre muchacha...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_110"] = "levanté la mano... y luego volví a aparecer aquí.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_120"] = "¿Cómo? ¿Cómo pudo pasar?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_130"] = "Max, no te asustes. No aún.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_140"] = "¿Cómo regresé aquí?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_150"] = "¿Esa muchacha de verdad está muerta?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_160"] = "Ya escuché esta lección...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_170"] = "Debo descubrir qué está pasando.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_180"] = "Respira... Tranquila... ¿Qué carajo está pasando?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_200"] = "Tranquila, Max.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_210"] = "Quizás me drogaron...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_220"] = "Fue el deja vu más intenso del mundo...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_240"] = "Ahora le lanza la bola de papel a Kate otra vez…",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_250"] = "Y si suena el teléfono de Victoria... Esto es real.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_260"] = "Esto no es posible.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_270"] = "Está bien... Estoy en clase... Todo es normal... Estoy bien...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_280"] = "Espera... Estoy en clase otra vez...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_290"] = "¡Es exactamente la misma lección!",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_300"] = "¿Y si la muchacha todavía no está muerta? ¿Puedo salvarla?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_310"] = "Debo llegar al baño rápido y descubrirlo...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_320"] = "Cuando me tomé la selfi, Jefferson me hizo una pregunta. Si la vuelve a hacer, sabré que es real.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_330"] = "¡Vaya!, Jefferson me hizo exactamente la misma pregunta... Esto es REAL. ¡Esa muchacha va a morir!",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01_Max_340"] = "Max, no estás loca. No estás soñando. Es momento de ser una heroína cotidiana.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01bis_Max_010"] = "¿La muchacha murió, o tengo tiempo de salvarla?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind01bis_Max_020"] = "¡Debo llegar al baño rápido y fijarme!",
  ["Act_E1_2A_ArtClass_VoiceOverRewind02_Max_010"] = "Bien, si estoy loca, llegaré al fondo del asunto... ¿En verdad puedo retroceder el tiempo?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind03_Max_010"] = "Mierda, Jefferson quiere que me quede después de clase. Y necesito tiempo para salvar a la muchacha...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind03_Max_020"] = "¿Qué pasa si rebobino otra vez y le doy la respuesta correcta?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_010"] = "Entonces, puedo volver en el tiempo...",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_020"] = "Sé que no estoy soñando esto. Es real. Lo sé.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_030"] = "¿Por qué está pasando? ¿Y por qué yo?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_040"] = "Esto es tan extraño.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_060"] = "No puedo decirle a nadie; pensarán que estoy loca.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_100"] = "¿Podré salvar a la muchacha en el baño?",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_110"] = "Debo apresurarme al baño para salvar a la muchacha.",
  ["Act_E1_2A_ArtClass_VoiceOverRewind04_Max_120"] = "Si no llego al baño, la muchacha morirá otra vez.",
  ["Act_E1_2A_ArtClass_Window_Look01_Max_010"] = "Me gusta esta vista panorámica de Blackwell. Todo luce tan verde y sereno...",
  ["Act_E1_2A_ArtClass_Window_Look02_Max_010"] = "Todo luce igual... Siento que estoy en el Día de la Marmota... Pero esto no es gracioso.",
  ["Act_E1_2A_Corridor_Alyssa_Look01_Max_010"] = "Alyssa siempre está enviando mensajes de texto, pero no se junta con mucha gente.",
  ["Act_E1_2A_Corridor_Alyssa_Look02_Max_010"] = "Aquí nadie puede ayudarte. ¡Muévete!",
  ["Act_E1_2A_Corridor_BigfootBanner_Look01_Max_010"] = "El pisotón de los Pies Grandes... Debería desarrollar un poco de espíritu escolar. Vamos, equipo.",
  ["Act_E1_2A_Corridor_Board01_Look01_Max_010"] = "No necesito una PC; me perdí las pruebas para el recital de poesía, y no robé esa mochila.",
  ["Act_E1_2A_Corridor_Board02_Look01_Max_010"] = "Se puede aprender mucho sobre una escuela viendo la mierda que publican en los tableros.",
  ["Act_E1_2A_Corridor_Brooke_Look01_Max_010"] = "He visto a Brooke con Warren. Ella parece ser su tipo.",
  ["Act_E1_2A_Corridor_Brooke_Look02_Max_010"] = "¡Brooke no tiene idea de lo que está pasando!",
  ["Act_E1_2A_Corridor_CHPrincipal_Look01_Max_010"] = "El director Wells siempre parece tan distraído. Nunca sé qué está pensando. ¿Me odia?",
  ["Act_E1_2A_Corridor_Courtney_Look01_Max_010"] = "Creo que esa es Courtney. Actúa como la esclava de Taylor y Victoria...",
  ["Act_E1_2A_Corridor_Courtney_Look02_Max_010"] = "No tienen idea de lo que me está pasando, y no puedo decirles nada.",
  ["Act_E1_2A_Corridor_Dana_Look01_Max_010"] = "Dana también está en mi piso. Es una hermosa porrista arquetípica. Seguro que las fabrican en serie. ... No debería ser tan maliciosa. Dana es amable conmigo.",
  ["Act_E1_2A_Corridor_Dana_Look02_Max_010"] = "Dios, desearía poder hablar con alguien sobre esto... pero todos pensarían que estoy loca.",
  ["Act_E1_2A_Corridor_Daniel_Look01_Max_010"] = "Pobre Daniel. Es tan amable. Desearía poder moler a golpes a Logan.",
  ["Act_E1_2A_Corridor_Daniel_Look02_Max_010"] = "Los bullies la tienen contra Daniel otra vez. Espero que no lo recuerde...",
  ["Act_E1_2A_Corridor_Evan_Look01_Max_010"] = "Evan no me habla mucho, pero sus fotos son muy buenas.",
  ["Act_E1_2A_Corridor_Evan_Look02_Max_010"] = "¡Olvídate de ellos y vete antes de que la muchacha muera!",
  ["Act_E1_2A_Corridor_Grant_Look01_Max_010"] = "La Sra. Grant es una gran maestra de ciencias.",
  ["Act_E1_2A_Corridor_Grant_Look02_Max_010"] = "La Sra. Grant no me puede ayudar ahora.",
  ["Act_E1_2A_Corridor_Halloween01_Look01_Max_010"] = "¡Sí, Halloween, mi época favorita del año!",
  ["Act_E1_2A_Corridor_Halloween01_Look02_Max_010"] = "Nunca me canso de ver fantasmas y esqueletos en el pasillo.",
  ["Act_E1_2A_Corridor_Halloween01_Look03_Max_010"] = "Desearía que octubre durara para siempre...",
  ["Act_E1_2A_Corridor_Halloween01_Look04_Max_010"] = "Eso no parece una decoración... Parece que está aquí desde siempre.",
  ["Act_E1_2A_Corridor_Hayden_Look01_Max_010"] = "Allí está Hayden, otro miembro del club Vortex. Aunque él no es un idiota.",
  ["Act_E1_2A_Corridor_Hayden_Look02_Max_010"] = "¿Para qué voy a mirarlo? ¡No puede ayudarte!",
  ["Act_E1_2A_Corridor_Juliet_Look01_Max_010"] = "Allí esta Juliet, de mi residencia. Otra discípula del club Vortex.",
  ["Act_E1_2A_Corridor_Juliet_Look02_Max_010"] = "No, Max, no pueden salvar a la muchacha en el baño.",
  ["Act_E1_2A_Corridor_Justin_Look01_Max_010"] = "Es... Dana hablando con... Creo que se llama Justin.",
  ["Act_E1_2A_Corridor_Justin_Look02_Max_010"] = "¿Cómo es que todos lucen tan calmados, y yo estoy tan nerviosa?",
  ["Act_E1_2A_Corridor_Logan_Look01_Max_010"] = "Odio a los deportistas machitos, como Logan. Y es miembro del club Vortex.",
  ["Act_E1_2A_Corridor_Logan_Look02_Max_010"] = "No puedes ayudarme ni un poco, Logan.",
  ["Act_E1_2A_Corridor_MPA01_Look01_Max_010"] = "Estos carteles de \"Persona desaparecida\" están por todas partes.",
  ["Act_E1_2A_Corridor_MPA01_Look02_Max_010"] = "\"Rachel Amber\". Tan bella. ¡Odio estos carteles! Es tan triste...",
  ["Act_E1_2A_Corridor_MPA01_Look03_Max_010"] = "Parece que lleva meses desaparecida.",
  ["Act_E1_2A_Corridor_MPA01_Look04_Max_010"] = "Me pregunto qué le ocurrió en verdad...",
  ["Act_E1_2A_Corridor_MPA01_Look05_Max_010"] = "¡Si no me apresuro a ese baño, otra muchacha estará en problemas!",
  ["Act_E1_2A_Corridor_MaxLocker_Interact02_Max_010"] = "Adoro esa foto de mamá y papá... Hola, Jack, mua mua. Andy, siempre tan fabuloso...",
  ["Act_E1_2A_Corridor_MaxLocker_Interact03_Max_010"] = "Bien, todo sigue en el mismo lugar...",
  ["Act_E1_2A_Corridor_MaxLocker_Look01_Max_010"] = "Odio que todos vean el interior de mi casillero.",
  ["Act_E1_2A_Corridor_Plan01_Look01_Max_010"] = "¿Quién pierde el tiempo en memorizar esto? Aunque supongo que hoy en día, todos deberíamos hacerlo.",
  ["Act_E1_2A_Corridor_Poster01_Look01_Max_010"] = "Es un horror. Debería contactarlos para averiguar qué puedo hacer. Mejor lo dejamos.",
  ["Act_E1_2A_Corridor_Poster02_Look01_Max_010"] = "Ahí está el faro otra vez...",
  ["Act_E1_2A_Corridor_Poster03_Look01_Max_010"] = "No debería ser tan tacaña con mi sangre.",
  ["Act_E1_2A_Corridor_Poster04_Look01_Max_010"] = "Qué bueno que dejé mi rifle en casa.",
  ["Act_E1_2A_Corridor_Poster05_Look01_Max_010"] = "Sí, este cartel debe dejar fríos a los bullies.",
  ["Act_E1_2A_Corridor_Poster06_Look01_Max_010"] = "¡Alerta de nerds! ¡Este cartel tiene \"Warren\" escrito por todas partes!",
  ["Act_E1_2A_Corridor_Poster07_Look01_Max_010"] = "Uy, apenas puedo esperar que llegue el día en que sea tan genial como Nathan o Victoria. Aburrido.",
  ["Act_E1_2A_Corridor_PrincipalDoor_Look01_Max_010"] = "El director no sale mucho de su oficina.",
  ["Act_E1_2A_Corridor_PrincipalDoor_Look02_Max_010"] = "¿Qué estás haciendo? ¡Ve a ese baño!",
  ["Act_E1_2A_Corridor_RewindChoice_NathanDenounce_Max_010"] = "Por supuesto, este esclavo académico no hará nada porque la familia Prescott ahora es dueña de Blackwell. ¿Debería rebobinar y cambiar mi historia?",
  ["Act_E1_2A_Corridor_RewindChoice_NathanLie_Max_010"] = "No, no se lo cree ni un poco. ¿Será que acabo de arruinar mi beca? Sí, podría rebobinar y decirle la verdad...",
  ["Act_E1_2A_Corridor_Samuel_Look01_Max_010"] = "Samuel es un poco extraño, pero me cae bien.",
  ["Act_E1_2A_Corridor_Samuel_Look02_Max_010"] = "No puedo hablar con Samuel sobre esto, aunque podría llegar a creerme.",
  ["Act_E1_2A_Corridor_ScienceDoor_Look01_Max_010"] = "Ah, el salón de ciencias. Aquí está el portal hacia el cerebro de Warren...",
  ["Act_E1_2A_Corridor_ScienceDoor_Look02_Max_010"] = "¡Debo dejar de hacer estupideces e ir a ese baño!",
  ["Act_E1_2A_Corridor_Stella_Look01_Max_010"] = "Stella siempre está concentrada en sus notas. No vino a Blackwell a perder el tiempo.",
  ["Act_E1_2A_Corridor_Stella_Look02_Max_010"] = "Stella sigue ahí, inmersa en sus notas. ¡Rápido, muévete, Max!",
  ["Act_E1_2A_Corridor_Taylor_Look01_Max_010"] = "Allí está Taylor, siempre esperando a Victoria.",
  ["Act_E1_2A_Corridor_Taylor_Look02_Max_010"] = "¡Deja de mirar y ve!",
  ["Act_E1_2A_Corridor_Trevor_Look01_Max_010"] = "Es lindo. Me gustan los patinadores. Es una lástima que no les guste yo.",
  ["Act_E1_2A_Corridor_Trevor_Look02_Max_010"] = "Todos están en el mismo lugar que antes. Debo apresurarme.",
  ["Act_E1_2A_Corridor_Trophy01_Look01_Max_010"] = "Mira esos trofeos. Debo reconocer eso de los Pies Grandes. Sí que pisotean.",
  ["Act_E1_2A_Corridor_Trophy02_Look01_Max_010"] = "Blackwell sí que se toma la natación en serio. Pero las nutrias son lindas. ¡Vamos, Nutrias!",
  ["Act_E1_2A_Corridor_VendingMachine_Look01_Max_010"] = "Deberían llamarla \"Máquina de azúcar\"... Sería asombroso si pusieras dinero allí y saliera una bolsa de azúcar.",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_010"] = "Te echaste para atrás con ese concurso de fotografía.",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_020"] = "Es solo una estúpida foto... No es tu alma.",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_030"] = "Max, siempre podrás esconderte en un baño y llorar.",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_040"] = "Todos lucen contentos solo por estar aquí. Como sea.",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_050"] = "Bueno, tranquila. Mójate un poco la cara.",
  ["Act_E1_2A_Corridor_VoiceOver01_Max_060"] = "Necesitas un descanso para ir al baño...",
  ["Act_E1_2A_Corridor_VoiceOver02_Max_020"] = "Primero, necesito ir a mojarme la cara y a refrescarme.",
  ["Act_E1_2A_Corridor_VoiceOver02_Max_030"] = "Me pican los ojos. Primero, vayamos al baño.",
  ["Act_E1_2A_Corridor_VoiceOver02_Max_040"] = "Primero debería ir al baño.",
  ["Act_E1_2A_Corridor_VoiceOverRewind01_Max_020"] = "No puedo decirle a nadie... ¡pensarán que estoy loca!",
  ["Act_E1_2A_Corridor_VoiceOverRewind01_Max_040"] = "No puedo dejar que esa muchacha muera en el baño...",
  ["Act_E1_2A_Corridor_VoiceOverRewindExit01_Max_010"] = "Si me voy ahora, la muchacha morirá.",
  ["Act_E1_2A_Corridor_VoiceOverRewindExit01_Max_030"] = "No seas cobarde, ve al baño.",
  ["Act_E1_2A_Corridor_VoiceOverRewindExit01_Max_040"] = "Si me largo ahora, me arrepentiré para siempre...",
  ["Act_E1_2A_Corridor_Zachary_Look01_Max_010"] = "Parece que Juliet está saliendo con Zachary. El club Vortex atrae a los atletas.",
  ["Act_E1_2A_Corridor_Zachary_Look02_Max_010"] = "Aquí nadie puede ayudarte. ¡Muévete!",
  ["Act_E1_2A_Toilets_Butterfly_Look01_Max_010"] = "Vaya. Mira esa mariposa. Es tan azul y perfecta... Adoro el contraste de sus colores en el azulejo... Esas pequeñas alas son como puntillas... ¿Cuánto viajó para llegar aquí?",
  ["Act_E1_2A_Toilets_Butterfly_Look02_Max_010"] = "Vaya, ¿de dónde salió esa mariposa? No luce como ninguna que haya visto antes... Las alas azules prácticamente brillan... Casi puedo sentir el aire moviéndose a mi alrededor... La mariposa se siente casi como un espíritu...",
  ["Act_E1_2A_Toilets_FireAlarm_Look01_Max_010"] = "Recuerdo cuando alguien hizo sonar la alarma el mes pasado... al menos logré salir de un examen de ciencias.",
  ["Act_E1_2A_Toilets_FireAlarm_Look02_Max_010"] = "¡Necesito un martillo para abrir la caja!",
  ["Act_E1_2A_Toilets_Graffiti_Look01_Max_010"] = "¿Quién se molestaría en escribir esa basura?",
  ["Act_E1_2A_Toilets_Hammer_Look01_Max_010"] = "¡Allí está el martillo! ¡Ahora puedo romper el maldito vidrio!",
  ["Act_E1_2A_Toilets_Poster01_Look01_Max_010"] = "Seguro este cartel incita a la gente a tener sexo.",
  ["Act_E1_2A_Toilets_Poster02_Look01_Max_010"] = "La última vez que me di la vacuna de la gripe, tuve gripe. Vete al diablo.",
  ["Act_E1_2A_Toilets_Poster04_Look01_Max_010"] = "Si tan solo la vida fuera tan simple.",
  ["Act_E1_2A_Toilets_TamponDispenser_Look01_Max_010"] = "Aún no me toca, gracias.",
  ["Act_E1_2A_Toilets_Trolley_Look01_Max_010"] = "Parece que Samuel se olvidó de sacar el carro de limpieza de aquí.",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_010"] = "Vine aquí por una razón.",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_020"] = "Tengo la cara tan grasosa y asquerosa.",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_030"] = "Debería aprovechar para refrescarme.",
  ["Act_E1_2A_Toilets_VoiceOver01_Max_040"] = "¡NO!",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_010"] = "Bien, Max, vuelve sobre cada paso...",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_020"] = "Me lavé la cara...",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_030"] = "Destrocé mi foto...",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_040"] = "Luego la... mariposa entró...",
  ["Act_E1_2A_Toilets_VoiceOverRewind01_Max_050"] = "Y tomé una foto...",
  ["Act_E1_2A_Toilets_VoiceOverRewind02_Max_010"] = "Vaya, está sucediendo otra vez.",
  ["Act_E1_2A_Toilets_VoiceOverRewind02_Max_020"] = "Está es tu oportunidad de salvarla...",
  ["Act_E1_2A_Toilets_VoiceOverRewind02_Max_030"] = "Vamos, Max, haz algo.",
  ["Act_E1_2A_Toilets_VoiceOverRewind03_Max_010"] = "Mierda, no puedo dejar que pase... Si puedo retroceder el tiempo otra vez, puedo ayudarla.",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_010"] = "Ay, Dios mío. Tengo poderes.",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_020"] = "En verdad retrocedí el tiempo...",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_030"] = "¿Qué me está pasando?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_040"] = "Increíble... y ahora me siento cansada...",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_060"] = "Ahora estoy totalmente agotada...",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_070"] = "¡Acabo de ver cómo le disparaban a una chica y luego la salvé! ¿Qué carajo está pasando?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_080"] = "Cálmate, Max... ¡Mierda, cálmate!",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_090"] = "¡Eso no ocurrió! ¡Esto no puede ser real!",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_100"] = "Tú puedes con esto, Max. Eres genial. Solo deja de pensar. No...",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_110"] = "¡Mierda, mierda, mierda!",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_120"] = "No puede estar pasando... ¿Qué está pasando?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_130"] = "No. Te. Alteres.",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_140"] = "¿Por qué me está pasando esto? ¿Por qué?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_150"] = "Max, no te estás volviendo loca. No te estás volviendo loca...",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_160"] = "Por favor, déjame despertarme...",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_170"] = "¿Todo fue una pesadilla? ¿Todavía estoy dormida?",
  ["Act_E1_2A_Toilets_VoiceOverRewind04_Max_180"] = "¿Cómo puede estar pasando esto? ¿Cómo?",
  ["Act_E1_2A_Toilets_VoiceOverRewind05_Max_010"] = "¡No! ¡Tiene un arma! Debo hacer algo más.",
  ["Act_E1_2A_Toilets_VoiceOverRewind05_Max_020"] = "Max, vas a salir lastimada.",
  ["Act_E1_2A_Toilets_VoiceOverRewind05_Max_030"] = "¡Estoy demasiado asustada como para acercarme a ese psicópata!",
  ["Cue_E1_2A_ArtClass_BellRing_Hayden_030"] = "Espera a ver lo que estoy fotografiando. Man Ray se fusiona con manga...",
  ["Cue_E1_2A_ArtClass_BellRing_Jefferson_010"] = "Y no se olviden del plazo para presentar una foto en el concurso Héroes Cotidianos. Viajaré con el ganador a San Francisco, donde el mundo del arte los agasajará. Es buena publicidad y puede catapultar una carrera en la fotografía. Así que, Stella y Alyssa, espabílense. Taylor, no te ocultes, todavía espero tu foto. Y, sí, Max, ya deja de fingir que no me ves.",
  ["Cue_E1_2A_ArtClass_BellRing_Taylor_020"] = "...no hay tiempo. Sabes que Victoria ingresó para ganar. Como siempre.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase01_Jefferson_002"] = "Buen intento, Max. Pero no vas a escapar así de fácil. Podemos hablar más después de clase.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase01_Max_001"] = "Lo siento, no me siento bien. ¿Puedo retirarme?",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase01_Max_003"] = "Lo siento, pero en verdad tengo que ir al baño.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_002"] = "¿Esperas que se presente la oportunidad, el elusivo \"momento justo\"?",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_004"] = "Max, no esperes demasiado. John Lennon dijo una vez: \"La vida es lo que te pasa mientras estás ocupado haciendo otros planes\". Vete ya, no te entretengo más.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_006"] = "Dada tu producción de selfies, seguro que ya debes de tener unas mil fotos tuyas.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_011"] = "Max, hoy estás en llamas. Todas las respuestas correctas. Bien. Asegúrate de terminar de trabajarla para hoy. Tengo fe en ti.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_012"] = "Nunca dejaría que una futura estrella de la fotografía no entregara su foto.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Jefferson_013"] = "Max, eres mejor fotógrafa que mentirosa... Sé que es aburrido que un viejo te dé un sermón... pero la vida no va a esperar a que te pongas al día. Eres joven, el mundo es tuyo, bla, bla, bla, ¿verdad? Pero tienes un don, tienes el ardiente deseo de captar imágenes, de enmarcar el mundo solo en la forma en la que tú lo concibes. Ahora, solo necesitas coraje para compartir tu don con los demás. Eso es lo que separa al artista del aficionado.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_001"] = "No lo estoy evitando, solo...",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_003"] = "Exactamente.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_005"] = "Uh, sí, no estoy segura de tener algo.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_007"] = "Tomará mucho tiempo encontrar una buena...",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_008"] = "Lo tengo bajo control. Creo que John Lennon dijo una vez: \"La vida es lo que te pasa mientras estás ocupado haciendo otros planes\".",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_014"] = "¿Es obligatorio? No creo que sea para tanto.",
  ["Cue_E1_2A_ArtClass_CHJefferson_Phase02_Max_015"] = "No tuve tiempo... Demasiada, demasiada tarea.",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_005"] = "Bueno, Max, ya que captaste nuestro interés y claramente quieres participar,|¿puedes decirnos el nombre del proceso que dio origen a los primeros autorretratos?",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_010"] = "No leíste el texto.",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_011"] = "O lo sabes o no lo sabes, Max.",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Jefferson_016"] = "Alguien ha estado leyendo, además de posar. Buen trabajo, Max.",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Max_006"] = "¿Me pregunta a mí? Déjeme pensar... Mmm...",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Max_007"] = "¡Lo sabía! ... pero lo olvidé.",
  ["Cue_E1_2A_ArtClass_CHJefferson_TalkJefferson_Max_015"] = "El daguerrotipo. Inventado por un pintor francés llamado... Louis Daguerre. Alrededor de 1830.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_001"] = "Ah, hola Max.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_003"] = "Es horrible ser el centro de atención.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_005"] = "No tiene nada contra ti, Max. Bueno, debo irme.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_008"] = "Seguro.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_010"] = "Estoy pensando demasiado...",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_013"] = "Gracias, pero hoy no. Tengo tarea.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_016"] = "Linda respuesta, Max. ¿Estás bien? Te ves pálida.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_018"] = "Es la primera vez. ¿Qué ocurre?",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_020"] = "Sé lo que se siente.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_022"] = "Veré cómo me siento. Gracias, Max.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Kate_024"] = "Seguro.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_002"] = "Kate, espero no haberte avergonzado con mi tonta respuesta.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_004"] = "A menos que seas Victoria.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_007"] = "Sí, yo también. Hablamos más tarde.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_009"] = "Estás muy callada hoy.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_011"] = "Creo que Victoria ya ganó el concurso... Como siempre.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_012"] = "Lo sé. ¿Quieres ir a tomar un té y quejarte de la vida?",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_015"] = "No te preocupes. Nos vemos más tarde.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_017"] = "Kate, em, ¿ya hablamos hoy en algún momento?",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_019"] = "Lo siento, estoy confundida. Demasiado estrés.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_021"] = "Ojalá no fuera así. Debo irme, pero podemos hablar más tarde si quieres.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_023"] = "Debo irme... Están pasando demasiadas cosas.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase01_Max_025"] = "Hola, Kate.",
  ["Cue_E1_2A_ArtClass_CHKate_Phase02_Kate_001"] = "Hablemos luego, Max.",
  ["Cue_E1_2A_ArtClass_Dial01_Daniel_020"] = "Estaba distraída con ese minidrama...",
  ["Cue_E1_2A_ArtClass_Dial01_Stella_010"] = "Siempre aprendo algo nuevo en clase...",
  ["Cue_E1_2A_ArtClass_Dial01_Stella_030"] = "Lo ignoro todo. No quiero que me metan en el medio.",
  ["Cue_E1_2A_ArtClass_Dial02_Taylor_020"] = "Apuesto a que sí.",
  ["Cue_E1_2A_ArtClass_Dial02_Victoria_010"] = "Creo que mi fotografía para el concurso quizás sea demasiado buena.",
  ["Cue_E1_2A_ArtClass_Dial03_Alyssa_040"] = "Demasiada tarea. Demasiada, demasiada tarea.",
  ["Cue_E1_2A_ArtClass_Dial03_Hayden_020"] = "Siento que había mucha energía extraña en la clase de hoy.",
  ["Cue_E1_2A_ArtClass_Dial03_Hayden_030"] = "Estoy agotada... quizás por eso la clase fue tan extraña...",
  ["Cue_E1_2A_ArtClass_Dial03_Victoria_010"] = "Alyssa se ve particularmente emo hoy.",
  ["Cue_E1_2A_ArtClass_Dial04_Courtney_010"] = "¿Por qué alguien querría llevar una estúpida cámara Instamatic?",
  ["Cue_E1_2A_ArtClass_Dial04_Courtney_030"] = "Sí, claro. Tiene un perfil muy bajo.",
  ["Cue_E1_2A_ArtClass_Dial04_Taylor_020"] = "Porque Max quiere que todo el mundo vea lo genial que es.",
  ["Cue_E1_2A_ArtClass_Dial04_Taylor_040"] = "Es tan tímida que se saca selfis con una cámara gigante.",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Jefferson_010"] = "Sí, Victoria, tienes que hacer los deberes esta semana aunque vayas a presentar una foto al concurso. Vamos, como todo el mundo.",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Jefferson_030"] = "Solo debes participar, salir al mundo y que te vean. Bueno, no importa quién gane; es solo una batalla en una guerra más grande. No quiero que nadie se sienta excluido de este proceso. Pero también quiero que sepan que el mundo de la fotografía no es para todos. Tuve mi momento con la cámara, y todos deberían tener esa oportunidad, ¿no?",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Victoria_020"] = "Lo sé, Sr. Jefferson. Es solo que trabajé tan duro para esta foto, y estoy segura de que sabe lo que se siente estar consumido por el trabajo. En verdad creo que Héroes Cotidianos es un evento cultural importante y quiero representar a la Academia Blackwell.",
  ["Cue_E1_2A_ArtClass_DiscussionLoop_Victoria_040"] = "Ah, claro. Solo quiero compartir mi talento con el mundo...",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_010"] = "Ahora, ¿me pueden dar un ejemplo de un fotógrafo que capturó perfectamente la condición humana en blanco y negro? ¿Alguien? ¿Bueller?",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_030"] = "¡Bien, Victoria! ¿Por qué Arbus?",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_050"] = "Veía a la humanidad como una especie torturada, ¿verdad? Y, francamente, eso es pura mierda. Shhh, no lo comenten. Hablando en serio, podría poner a cualquiera de ustedes en un rincón oscuro y plasmarlos en un momento de desesperación. Y cualquiera de ustedes podría hacerme eso a mí. ¿No es demasiado fácil? ¿Demasiado obvio? ¿Qué tal si Arbus elegía capturar a las personas en el apogeo de su belleza o inocencia? Tenía un ojo brillante, así que podría haber adoptado otro enfoque.",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_070"] = "Yo también, Victoria. Él capturó la esencia de los Estados Unidos de posguerra, la generación beat. Y había sinceridad sobre las condiciones económicas de la época, pero también belleza en la lucha. No hay belleza sin el beat. Lo que explica por qué Frank fue la musa fotográfica de Kerouac, y ambos fueron los grandes cronistas de la década de 1950. Bueno... Todos hemos visto esa foto icónica de Kerouac en el balcón —y si no la vieron, mal, mal— que captura la soledad urbana romántica del poeta del siglo XX. ¿Me siguen?",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_080"] = "Ahora, contrasten la profunda Americana de Frank, con fotografías surrealistas de Salvador Dalí. Al igual que Cocteau, era un verdadero hombre renacentista, y sus famosos autorretratos son ejemplos tempranos de esa palabra tan horrible que ustedes aman tanto, la \"selfi\"... Es una gran tradición, y yo lucho con pasión a favor de su derecho a la libre expresión. O selfi-expresión. Eh, lo siento, lo sé.",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Jefferson_090"] = "Así que, si alguien quiere denunciar el retrato como narcisismo moderno, que vuelvan cientos de años atrás para culpar a la sociedad. Hablando de preguntas, apuesto a que pensaron que iba a hablar sin parar hasta que sonara la campana. Es su turno de enseñarnos. Ahora, según los capítulos que seguro que memorizaron, ¿quién me puede decir el nombre del proceso que llevó al nacimiento del autorretrato?",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Victoria_020"] = "Diane Arbus.",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Victoria_040"] = "Por sus imágenes de rostros sin esperanza. Uno se siente totalmente atrapado por los ojos de esas madres e hijos tristes.",
  ["Cue_E1_2A_ArtClass_JeffGivingLesson_Victoria_060"] = "Tengo que admitir que no soy una gran fanática de su trabajo. Prefiero a... Robert Frank.",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Jefferson_030"] = "No, Victoria, discúlpanos.",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Jefferson_040"] = "Max Caulfield, finalmente decidiste presentar una fotografía para el concurso.",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Max_010"] = "Disculpe, señor Jefferson, ¿puedo hablar con usted un momento?",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Max_050"] = "Eh...",
  ["Cue_E1_2A_ArtClass_JeffIntroDial_Victoria_020"] = "Sí, te disculpo.",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_010"] = "¿Nadie? ... Esto no promete nada bueno.",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_020"] = "Sólo den una respuesta.",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_030"] = "Estaba en los capítulos que leyeron.",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_040"] = "Leyeron los capítulos, ¿verdad?",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_060"] = "Este silencio es ensordecedor.",
  ["Cue_E1_2A_ArtClass_JeffWaitingAnswerLoop_Jefferson_070"] = "Si esto fuera una foto, la llamaría naturaleza muerta.",
  ["Cue_E1_2A_ArtClass_JeffersonTalks_Jefferson_010"] = "Te veo, Max Caulfield. No pienses en irte de aquí hasta que hablemos de tu participación.",
  ["Cue_E1_2A_ArtClass_MaxAnswers_Jefferson_010"] = "El Proceso de Daguerre hizo al retrato muy popular, sobre todo porque proporcionó a los sujetos características claras definidas. Podrían aprender más si terminan de leer los capítulos asignados. Max les saca mucha ventaja a todos.",
  ["Cue_E1_2A_ArtClass_MaxAwake01_Jefferson_030"] = "El famoso Alfred Hitchcock dijo que las películas eran \"pequeños trozos de tiempo\", pero podría estar hablando de fotografía, y es probable que lo hiciera. Estos trozos de tiempo nos pueden enmarcar en la gloria y en el dolor; de la luz a la sombra; del color al claroscuro...",
  ["Cue_E1_2A_ArtClass_MaxAwake01_Max_010"] = "¡Vaya!",
  ["Cue_E1_2A_ArtClass_MaxAwake01_Max_020"] = "No me dormí, y... eso no se sintió como un sueño... Qué extraño.",
  ["Cue_E1_2A_ArtClass_MaxSurprised_Max_010"] = "Lo hice... ¡En verdad lo hice!",
  ["Cue_E1_2A_ArtClass_MaxSurprised_Max_020"] = "Soy una máquina del tiempo humana...",
  ["Cue_E1_2A_ArtClass_Polaroid_Broken_Max_010"] = "Dios, no lo puedo creer…",
  ["Cue_E1_2A_ArtClass_Polaroid_Picture01_Jefferson_010"] = "Shhh, creo que Max se ha tomado lo que ustedes llaman una \"selfi\"... Una palabra tonta para una maravillosa tradición fotográfica. Y Max... tiene un don.",
  ["Cue_E1_2A_ArtClass_Polaroid_Picture01_Jefferson_020"] = "Como todos saben, el retrato fotográfico ha sido popular desde el siglo XIX. Su generación no fue la primera en \"selfi-expresarse\". Lo siento. No me pude resistir. El retrato siempre fue y sigue siendo un aspecto vital del arte y de la fotografía, desde que se creó.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke02_Victoria_010"] = "Tal vez Max le tiene miedo a la era digital.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke02_Victoria_020"] = "Es fantástico que Max conozca sus limitaciones.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_010"] = "Lo siento Max, estás fuera del juego.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_020"] = "¿Hay alguien aquí que sepa el tema?",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_050"] = "Muy bien, Victoria. El Proceso de Daguerre logró marcar los finos detalles de los rostros, lo que los volvió extremadamente populares desde el siglo XIX en adelante. El primer autorretrato de daguerrotipo norteamericano fue realizado por Robert Cornelius.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_060"] = "Pueden averiguar todo acerca de él... En el libro de texto.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Jefferson_070"] = "O incluso... en Internet.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Victoria_030"] = "Louis Daguerre fue un pintor francés que creó los \"daguerrotipos\", un proceso que le proporcionó a los retratos un estilo reflexivo bien definido, como un espejo.",
  ["Cue_E1_2A_ArtClass_VictoriaJoke_Victoria_040"] = "Ahora estás totalmente atrapada en la Zona retro. Cara triste.",
  ["Cue_E1_2A_Corridor_ArtClassDoor_Interact04_Max_010"] = "Espero que me alcance el tiempo para llegar al baño... por favor... por favor...",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_010"] = "Todavía no me dijiste lo linda que me veo.",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_030"] = "¿Solo linda?",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_050"] = "Entonces, podría enviarte una foto especial durante la clase.",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_070"] = "Sabes que no bromeo.",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_090"] = "¿Y eso qué tiene que ver?",
  ["Cue_E1_2A_Corridor_Dial05_Juliet_110"] = "Apestas.",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_020"] = "Estaba por hacerlo. Siempre te ves bien.",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_040"] = "Sexi.",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_060"] = "Ni se te ocurra provocarme.",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_080"] = "Odio la clase de ciencias con esos nerds.",
  ["Cue_E1_2A_Corridor_Dial05_Zachary_100"] = "Ah, porque si me envías una foto, no me aburriré.",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_010"] = "Ay, vamos, ten paciencia...",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_020"] = "Dobla esa esquina...",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_030"] = "¡Uuuh, mierda! Lo siento, granjeros.",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_040"] = "¡Vamos, cambia!",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_050"] = "Sal de mi camino, Ferrari, ¿sí?",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_060"] = "Ya casi llegamos...",
  ["Cue_E1_2A_Corridor_Dial06_Brooke_070"] = "¿Tercer lugar? ¡Es una porquería! ¡Imbéciles!",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_010"] = "No me molesta fregar, pero ¿podrían levantar sus malditos pies?",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_020"] = "Dejando huellas sucias por todos lados...",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_030"] = "Aunque me encanta este trapeador, lo deja como los chorros del oro.",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_040"] = "Me siento un fantasma para estos chicos. Apenas me ven.",
  ["Cue_E1_2A_Corridor_Dial07_Samuel_050"] = "Pobre muchacha. Nadie debería desaparecer así...",
  ["Cue_E1_2A_Corridor_Dial08_CitizenM1_020"] = "Sí, día de pago...",
  ["Cue_E1_2A_Corridor_Dial08_CitizenM1_060"] = "Sí, seguro.",
  ["Cue_E1_2A_Corridor_Dial08_CitizenM1_090"] = "Yo no soy el jefe, hermano.",
  ["Cue_E1_2A_Corridor_Dial08_Daniel_040"] = "Me olvidé para qué.",
  ["Cue_E1_2A_Corridor_Dial08_Daniel_070"] = "Logan, en serio, déjame en paz.",
  ["Cue_E1_2A_Corridor_Dial08_Daniel_100"] = "No, estoy... solo estoy tratando de ir a clase.",
  ["Cue_E1_2A_Corridor_Dial08_Logan_010"] = "Oye, Daniel, ¿te acuerdas que hoy es día de pago?",
  ["Cue_E1_2A_Corridor_Dial08_Logan_030"] = "Sé que no olvidaste que nos debes dinero.",
  ["Cue_E1_2A_Corridor_Dial08_Logan_050"] = "Por asegurarnos de que nadie te patee el trasero.",
  ["Cue_E1_2A_Corridor_Dial08_Logan_080"] = "Tú no eres mi jefe, hermano.",
  ["Cue_E1_2A_Corridor_Dial09_Dana_020"] = "¿Cuándo puedes?",
  ["Cue_E1_2A_Corridor_Dial09_Dana_040"] = "Deberías dejar de fumar.",
  ["Cue_E1_2A_Corridor_Dial09_Dana_060"] = "¿Cuál es el punto de venir a clase si estás fumado?",
  ["Cue_E1_2A_Corridor_Dial09_Dana_080"] = "Está bien, rebelde.",
  ["Cue_E1_2A_Corridor_Dial09_Dana_100"] = "Eres tan idiota que no puedo enojarme contigo.",
  ["Cue_E1_2A_Corridor_Dial09_Justin_010"] = "Lo digo en serio. No podía ni salir de la cama.",
  ["Cue_E1_2A_Corridor_Dial09_Justin_030"] = "Cuando tengo que ir a clase. Y a verte.",
  ["Cue_E1_2A_Corridor_Dial09_Justin_050"] = "Dana, ya lo he hecho. No fumo desde... que me desperté a las siete.",
  ["Cue_E1_2A_Corridor_Dial09_Justin_070"] = "¿Pero para qué vienes a clase?",
  ["Cue_E1_2A_Corridor_Dial09_Justin_090"] = "Además, ¿por qué crees que en inglés la secundaria es \"high school\"? \"High\" como fumar marihuana.",
  ["Cue_E1_2A_Corridor_Dial09_Justin_110"] = "¿Quieres una pitada rápida de mi nueva cepa?",
  ["Cue_E1_2A_Corridor_Insertion_ArtClassToCorridor_Max_010"] = "Bienvenida al mundo real...",
  ["Cue_E1_2A_Corridor_Insertion_ArtClassToCorridor_Max_020"] = "Realmente necesito ir al baño. Lavarme la cara y asegurarme de que no me veo como una perdedora total.",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_010"] = "¿Oyes esa alarma de incendios? Significa que debes salir.",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_030"] = "Las muchachas siempre usan esa excusa.",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_050"] = "Para lo que sea que traigas entre manos. Tu rostro te delata.",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_David_070"] = "Entonces fuera de aquí, señorita. ¿O está escondiendo algo? ¿Eh?",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Max_020"] = "Tenía que usar el baño...",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Max_040"] = "¿Excusa para qué?",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Max_060"] = "La alarma me asustó.",
  ["Cue_E1_2A_Corridor_PrincipalAndDavid_Principal_080"] = "Gracias, Sr. Madsen, la situación está bajo control. No hay ninguna emergencia aquí. Deje a la Srta. Caulfield tranquila y, por favor, apague esa alarma: ese es su trabajo.",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_010"] = "Acabo de ver a Nathan Prescott con un arma... en el baño de chicas.",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_030"] = "Sí. Estaba en el baño hablándose a sí mismo, con un arma. ¡Lo vi todo! ¡Farfullaba como un demente!",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_050"] = "Estaba escondida detrás de uno de los cubículos. Tengo derecho a estar allí. Es el baño de mujeres.",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_070"] = "Luego... luego se fue. Salí corriendo y no sabía qué hacer. ¿Va a denunciarlo?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Max_090"] = "¿Eso es todo? Le acabo de decir...",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_020"] = "¿Nathan Prescott? ¿Estás segura?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_040"] = "Está bien, tranquilízate. Lo viste... ¿sin que él te viera?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_060"] = "Lo sé, lo sé. Solo quería estar completamente seguro de lo que pasó. Sucede que Prescott proviene de la familia más distinguida del pueblo. Y es uno de los alumnos más honorables de Blackwell. Así que es difícil para mí imaginarlo con un arma en el baño de mujeres. ¿Qué pasó después?",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_080"] = "Es una acusación grave. Me encargaré del asunto personalmente. Gracias por avisarme.",
  ["Cue_E1_2A_Corridor_PrincipalDenounceNathan_Principal_100"] = "Continuaremos esta conversación más tarde, en mi oficina. Por favor, ahora ve con el resto de tu clase, Caulfield.",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Max_010"] = "Me sentí mal en clase... Mmm, cosas de chicas...",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Max_030"] = "Es la verdad. Me mareé en la clase del Sr. Jefferson...",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Max_050"] = "No hay nada que esconder. Me sentí mal. Suele pasar, ¿no?",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Principal_020"] = "Excepto que estás vagando como un zombi. ¿Y crees que es la primera vez que una estudiante me dice eso como excusa?",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Principal_040"] = "Solo dime lo que estás escondiendo. Puedes confiar en mí.",
  ["Cue_E1_2A_Corridor_PrincipalProtectNathan_Principal_060"] = "Otra vez esa actitud adolescente. Escuché suficiente. No creas que no sé lo que está ocurriendo aquí. Estás aquí desde hace solo tres semanas y ya estás causando problemas. No creo que a tus padres les guste saber esto. Ahora ve afuera con el resto de la clase. Por favor.",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Max_030"] = "Yo... Solo estoy un poco preocupada sobre mi... futuro.",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_010"] = "Espera, Max. Ven aquí.",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_020"] = "Te ves un poco estresada. ¿Estás bien?",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_040"] = "Estás sudando. ¿Seguro que no pasa nada más? Puedes ser sincera conmigo, Max.",
  ["Cue_E1_2A_Corridor_PrincipalTalks_Principal_050"] = "¿O hiciste algo malo...? ¿Es eso? ¿Bien, Max? Cuéntame.",
  ["Cue_E1_2A_Corridor_PrincipalWarning_Principal_010"] = "Max, mejor ve afuera ahora.",
  ["Cue_E1_2A_Corridor_PrincipalWarning_Principal_020"] = "No andes rondando por aquí, ve afuera.",
  ["Cue_E1_2A_Corridor_PrincipalWarning_Principal_040"] = "Max, debes estar afuera, no aquí dentro.",
  ["Cue_E1_2A_Corridor_Random_CitizenF1_010"] = "No es que Blackwell sea una escuela tan diversa.",
  ["Cue_E1_2A_Corridor_Random_CitizenF1_030"] = "Se ven más Pies Grandes que minorías...",
  ["Cue_E1_2A_Corridor_Random_CitizenF1_140"] = "¡Mierda! ¡Dejé mi teléfono en clase!",
  ["Cue_E1_2A_Corridor_Random_CitizenF2_020"] = "No sé. Hay muchos tipos diferentes de personas aquí.",
  ["Cue_E1_2A_Corridor_Random_CitizenF2_150"] = "¡Odio ese puto sonido!",
  ["Cue_E1_2A_Corridor_Random_CitizenF3_040"] = "¡Eres una cualquiera! ¡Sabía que te engancharías con ese perdedor!",
  ["Cue_E1_2A_Corridor_Random_CitizenF3_160"] = "No oigo ningún disparo.",
  ["Cue_E1_2A_Corridor_Random_CitizenF4_050"] = "Escuché que las fiestas del club Vortex son salvajes.",
  ["Cue_E1_2A_Corridor_Random_CitizenF4_070"] = "Te preparan para el mundo real.",
  ["Cue_E1_2A_Corridor_Random_CitizenF5_060"] = "Es como que tienes que pasar algún tipo de prueba para entrar. Mostrar tus tarjetas de crédito platino o los informes de la cuenta bancaria de tus padres.",
  ["Cue_E1_2A_Corridor_Random_CitizenF6_090"] = "Todos mis amigos en Los Ángeles me dijeron que Oregón iba a ser frío y húmedo todos los días. Pero hace 24 °C, y no llovió ni una vez este verano. ¿Será el cambio climático?",
  ["Cue_E1_2A_Corridor_Random_CitizenF7_100"] = "No, son las personas de Oregón tratando de deshacerse de los californianos.",
  ["Cue_E1_2A_Corridor_Random_CitizenM1_010"] = "Odio esa clase. Es tan aburrida.",
  ["Cue_E1_2A_Corridor_Random_CitizenM1_110"] = "¡Oye, espérame!",
  ["Cue_E1_2A_Corridor_Random_CitizenM2_020"] = "Te pone una marca si estás mirando tu teléfono.",
  ["Cue_E1_2A_Corridor_Random_CitizenM2_120"] = "Yo no huelo humo...",
  ["Cue_E1_2A_Corridor_Random_CitizenM3_030"] = "No voy a pagar 150 dólares por un concierto.",
  ["Cue_E1_2A_Corridor_Random_CitizenM3_130"] = "Los espejos convexos a veces se llaman espejos convergentes... una imagen es la ubicación en el espacio donde la luz se desvía...",
  ["Cue_E1_2A_Corridor_Random_CitizenM4_040"] = "¡Hermano, la tarifa del servicio es como el 50 % de eso!",
  ["Cue_E1_2A_Corridor_Random_CitizenM5_050"] = "No vas a fallar... no vas a fallar...",
  ["Cue_E1_2A_Corridor_Random_CitizenM6_060"] = "Hermano, quisiera hacerlo con ella.",
  ["Cue_E1_2A_Corridor_Random_CitizenM6_080"] = "Lo hice con tu madre.",
  ["Cue_E1_2A_Corridor_Random_CitizenM7_070"] = "Lo harías hasta con tu madre.",
  ["Cue_E1_2A_Corridor_Random_CitizenM7_090"] = "Por eso se reía tanto.",
  ["Cue_E1_2A_Corridor_Random_CitizenM8_100"] = "No, te dije que mis suministros de arte costaron más de lo que pensaba. ¿No puedes simplemente depositar 600 dólares en mi cuenta?",
  ["Cue_E1_2A_Corridor_ToiletDoor_Interact03_Max_010"] = "Vacío. Bien. Nadie puede verme relajándome. Excepto yo.",
  ["Cue_E1_2A_Toilets_FireAlarm_Interact01_Chloe_020"] = "¡NUNCA vuelvas a tocarme, loco!",
  ["Cue_E1_2A_Toilets_FireAlarm_Interact01_Nathan_010"] = "De ninguna manera...",
  ["Cue_E1_2A_Toilets_FireAlarm_Interact01_Nathan_030"] = "Otro día de mierda...",
  ["Cue_E1_2A_Toilets_Mirror_Interact01_Max_010"] = "Siento que el universo se burla de mí dondequiera que vaya...",
  ["Cue_E1_2A_Toilets_Mirror_Interact01_Max_020"] = "Todo comenzó con ese extraño sueño en clase... ¿Estoy enloqueciendo?",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_030"] = "Espero que hayas verificado el perímetro, como diría el idiota de mi padrastro. Ahora, hablemos de \"negocios\".",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_050"] = "Incorrecto. Tienes mucha pasta.",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_070"] = "¡Bua, bua!, pobre niño rico. Sé que estuviste pasando droga y porquerías a los chicos de aquí...",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_090"] = "No quiero tus pastillas. Quiero el buen verde americano. No hierba. Efectivo.",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_100"] = "Apuesto a que tu respetable familia me ayudaría si fuera a verlos. Dios, ya puedo ver los titulares...",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_120"] = "Puedo decirles a todos que Nathan Prescott es un marica que habla solo.",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_140"] = "¿De dónde sacaste eso? ¿Qué estás haciendo? ¡Vamos, baja esa cosa!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_160"] = "Te vas a meter en muchos más problemas por esto que por las drogas...",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Chloe_180"] = "¡Aleja esa arma de mí, enfermo!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_010"] = "Está todo bien, Nathan. No te estreses.... Estás bien. Cuenta hasta tres... No tengas miedo... La escuela te pertenece... Si quisieras, podrías volarla por los aires... Eres el jefe...",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_020"] = "¿Y qué quieres?",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_040"] = "No tengo nada para ti.",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_060"] = "Mi familia, no yo.",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_080"] = "Adolescentes, no niños. Escucha... Te puedo compensar...",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_110"] = "No los metas en esto, perra.",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_130"] = "¡No sabes quién mierda soy yo ni con quién te estás metiendo!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_150"] = "NUNCA me digas lo que tengo que hacer. ¡Estoy HARTO de que quieran controlarme!",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_170"] = "Nadie va a extrañar a una pendeja como tú, ¿o sí?",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Nathan_190"] = "Ay... ¡Mierda! No, no, no, no...",
  ["Cue_E1_2A_Toilets_NathanAndChloe_Rewind_Nathan_200"] = "No, Dios, por favor... No fue mi intención... No parabas de presionarme... Siempre todos están presionándome... Lo siento... Lo siento mucho... Mi vida es un infierno... Y estoy tan mal...",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_010"] = "Relájate. Deja de torturarte. Tienes un \"don\".",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_020"] = "Al carajo.",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_030"] = "Cuando se cierra una puerta, se abre una ventana... O algo así.",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_040"] = "Bueno, no tienes una sesión de fotos como esta todos los días...",
  ["Cue_E1_2A_Toilets_Tap_Interact01_Max_050"] = "No esperes para comenzar a vivir...",
  ["Act_E1_3A_CampusA_BigFootBanner_Look01_Max_010"] = "¿Por qué nunca hay carteles gigantes para concursos de arte o proyectos de ciencias?",
  ["Act_E1_3A_CampusA_BigFootStatue_Look01_Max_010"] = "Espero que nuestro Pies Grandes esté cuidando a todos aquí en Blackwell...",
  ["Act_E1_3A_CampusA_Board01_Look01_Max_010"] = "Preferiría ver verdaderos Pies Grandes contra jabalíes, no equipos.",
  ["Act_E1_3A_CampusA_Board01_Look02_Max_010"] = "Sin comentarios.",
  ["Act_E1_3A_CampusA_Board02_Look01_Max_010"] = "Tengo ganas de comer una hamburguesa...",
  ["Act_E1_3A_CampusA_Board02_Look01_Max_020"] = "Sería demasiado increíble fotografiar ese certamen de poesía... Pero estoy asustada.",
  ["Act_E1_3A_CampusA_Board02_Look01_Max_040"] = "Debería ir para aprender más sobre la cultura local... pero no creo que vaya.",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_010"] = "Estoy segura de que este cartel detuvo a millones de bullies.",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_030"] = "No estoy tan desesperada. Por ahora.",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_040"] = "Compro. Definitivamente tendré que probar un trozo.",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_050"] = "Esto luce como la tierra natal de los nerds... debería ir.",
  ["Act_E1_3A_CampusA_Board03_Look01_Max_060"] = "Paso.",
  ["Act_E1_3A_CampusA_BrookeBag_Interact01_Max_010"] = "Qué nombre tan complicado para un pequeño drone.",
  ["Act_E1_3A_CampusA_BrookeBag_Look01_Max_010"] = "¡Estoy bastante segura de que Warren tiene el mismo bolso! Se ve un poco nerd...",
  ["Act_E1_3A_CampusA_BusSign_Look01_Max_010"] = "Siempre podría escaparme y regresar en bus a Seattle...",
  ["Act_E1_3A_CampusA_CHBrooke_Look01_Max_010"] = "¿En verdad Brooke tiene un drone?",
  ["Act_E1_3A_CampusA_CHBrooke_Look02_Max_010"] = "Es un poco distante. Tal vez, podría rebobinar e impresionarla.",
  ["Act_E1_3A_CampusA_CHDaniel_Look01_Max_010"] = "Daniel siempre está dibujando algo. Hace que parezca extrovertida.",
  ["Act_E1_3A_CampusA_CHDaniel_Look02_Max_010"] = "Eso fue tan genial. Me alegra que hayamos hablado. Anímate más seguido, Max.",
  ["Act_E1_3A_CampusA_CHDaniel_Look03_Max_010"] = "Ahora me siento mal. No quería herir los sentimientos de Daniel.",
  ["Act_E1_3A_CampusA_CHEvan_Look01_Max_010"] = "Creo que se llama Evan. Siempre parece muy intenso.",
  ["Act_E1_3A_CampusA_CHEvan_Look02_Max_010"] = "Maldita sea, apesto. Podría rebobinar y obtener la respuesta correcta.",
  ["Act_E1_3A_CampusA_CHGrant_Look01_Max_010"] = "La Sra. Grant está realmente motivada con esa petición.",
  ["Act_E1_3A_CampusA_CHGrant_Look02_Max_020"] = "Espero haber tomado la decisión correcta sobre la petición...",
  ["Act_E1_3A_CampusA_CHHayden_Look01_Max_010"] = "Ahí están Hayden y su harén del club Vortex. Seguro que está \"viviendo el sueño\"...",
  ["Act_E1_3A_CampusA_CHJustin_Look01_Max_010"] = "Ahí están Justin y su pandilla de patinadores. Son tan lindos cuando hacen trucos.",
  ["Act_E1_3A_CampusA_CHJustin_Look02_Max_010"] = "Ahora que sé algunos secretos del mundo del patinaje, podría rebobinar y hacer que Justin me cuente más.",
  ["Act_E1_3A_CampusA_CHLuke_Look01_Max_010"] = "Ese es Lucas Parker... Zachary lo empujó contra un casillero la semana pasada. Así se hace, bullies.",
  ["Act_E1_3A_CampusA_CHStella_Look01_Max_010"] = "Stella siempre se ve tan seria y concentrada. Bien por ella.",
  ["Act_E1_3A_CampusA_CigaretteButts_Look01_Max_010"] = "Puaj, qué asco. Al menos, usen cigarrillos electrónicos.",
  ["Act_E1_3A_CampusA_Coins_Look01_Max_010"] = "Esta es una gran imagen... todas esas monedas verdes que ondulan en el agua... Espero que a todos se les haya cumplido su deseo.",
  ["Act_E1_3A_CampusA_Direction_Look02_Max_010"] = "Tengo que ir y buscar la memoria USB de Warren.",
  ["Act_E1_3A_CampusA_EvanPhotoBook_Look01_Max_010"] = "Estas fotos son estupendas... y el rostro de Rachel Amber es cautivante...",
  ["Act_E1_3A_CampusA_EvanPhotoBook_Look02_Max_010"] = "La carpeta de Evan siempre luce superprofesional. Me encantaría ver sus fotos...",
  ["Act_E1_3A_CampusA_Fountain_Max_010"] = "Hoy ha sido un día de locos...",
  ["Act_E1_3A_CampusA_Fountain_Max_020"] = "Todo está sucediendo demasiado rápido...",
  ["Act_E1_3A_CampusA_Fountain_Max_030"] = "Y nada de esto tiene sentido... las visiones, este... poder.",
  ["Act_E1_3A_CampusA_Fountain_Max_040"] = "Sigo esperando volver a despertarme...",
  ["Act_E1_3A_CampusA_Fountain_Max_050"] = "Pero, si esto es un sueño, no estoy dormida.",
  ["Act_E1_3A_CampusA_Fountain_Max_060"] = "Lo que significa que, de alguna manera,... En verdad retrocedí el tiempo.",
  ["Act_E1_3A_CampusA_Fountain_Max_070"] = "Debe haber una razón... y tengo que averiguar cuál es.",
  ["Act_E1_3A_CampusA_GoingPark_Max_020"] = "Todavía tengo que tomar la memoria de mi habitación antes de encontrarme con Warren.",
  ["Act_E1_3A_CampusA_GoingSchool_Max_010"] = "No volveré allí.",
  ["Act_E1_3A_CampusA_GoingSchool_Max_020"] = "Ahora tengo que ir a mi habitación y tomar la memoria USB de Warren.",
  ["Act_E1_3A_CampusA_GoingStreet_Max_020"] = "Warren está esperando en el estacionamiento a que le lleve su memoria USB, así que tengo que llegar a mi habitación.",
  ["Act_E1_3A_CampusA_Graffiti01_Look01_Max_010"] = "¿Qué habrá sido de la canción \"Tres monedas en la fuente\"?",
  ["Act_E1_3A_CampusA_Graffiti02_Look01_Max_010"] = "Me encantaría alimentarte, pero no tengo ni un centavo en el bolsillo.",
  ["Act_E1_3A_CampusA_Graffiti03_Look01_Max_010"] = "Grafiti para tontos.",
  ["Act_E1_3A_CampusA_Graffiti03_Look01_Max_020"] = "¿Qué idioma es ese?",
  ["Act_E1_3A_CampusA_Graffiti04_Look01_Max_010"] = "Ay, eso no es lindo. Pobre nutria.",
  ["Act_E1_3A_CampusA_Graffiti05_Look01_Max_010"] = "Ingenioso.",
  ["Act_E1_3A_CampusA_JeffersonPhoto01_Look01_Max_010"] = "Es tan genial que Blackwell exhiba el trabajo del Sr. Jefferson.",
  ["Act_E1_3A_CampusA_JeffersonPhoto02_Look01_Max_010"] = "Esa es una de sus fotos famosas. Me encanta cómo captura el momento.",
  ["Act_E1_3A_CampusA_JeffersonPhoto03_Look01_Max_010"] = "El Sr. Jefferson tiene talento para diferentes estilos.",
  ["Act_E1_3A_CampusA_MPA01_Look01_Max_010"] = "¿Carteles sobre carteles? Alguien está empeñada en encontrar a Rachel Amber.",
  ["Act_E1_3A_CampusA_MPA01_Look02_Max_010"] = "Nunca vi tantos carteles de \"Persona desaparecida\" para una misma persona...",
  ["Act_E1_3A_CampusA_MPAGround_Look01_Max_010"] = "Rachel Amber... Se ve tan optimista y linda... Me pregunto qué le ocurrió...",
  ["Act_E1_3A_CampusA_Park_Look02_Max_020"] = "Ahora debo regresar a mi habitación. Este día no tiene fin.",
  ["Act_E1_3A_CampusA_Poster01_Look01_Max_010"] = "¿\"Nutrias al poder\"? No estoy hecha para eso.",
  ["Act_E1_3A_CampusA_Poster02_Look01_Max_010"] = "Sí que sacan partido del \"poder de la nutria\"...",
  ["Act_E1_3A_CampusA_Poster03_Look01_Max_010"] = "Tienes que estar bromeando. Voy a participar.",
  ["Act_E1_3A_CampusA_Poster04_Look01_Max_010"] = "La Sra. Grant está en contra de este sistema de vigilancia.",
  ["Act_E1_3A_CampusA_SignMainBuilding_Look01_Max_010"] = "Gracias a Dios terminaron las clases por hoy.",
  ["Act_E1_3A_CampusA_Statue_Look01_Max_010"] = "Apuesto a que los fundadores de Blackwell se cagarían encima si vieran al cuerpo estudiantil de hoy caminando como autómatas con sus teléfonos.",
  ["Act_E1_3A_CampusA_SwimmingPoolDoor_Look01_Max_010"] = "Y aquí es donde las Nutrias realizan su magia acuática.",
  ["Act_E1_3A_CampusA_Tree_Max_010"] = "Qué extraño estar de vuelta aquí después de cinco años...",
  ["Act_E1_3A_CampusA_Tree_Max_020"] = "Pensé que podría encajar de nuevo en la escuela...",
  ["Act_E1_3A_CampusA_Tree_Max_030"] = "Pero con toda la mierda que está pasando, me siento aún más fuera de lugar...",
  ["Act_E1_3A_CampusA_Tree_Max_040"] = "¿Y en quién puedo confiar, además de en mi diario y mi cámara?",
  ["Act_E1_3A_CampusA_Tree_Max_050"] = "¡Dios!, se supone que estos son los mejores años de mi vida...",
  ["Act_E1_3A_CampusA_Tree_Max_060"] = "Esto es lo que se siente estar y sentirse sola a la vez...",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_010"] = "Bueno, mejor voy a la habitación a buscar esa memoria USB.",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_020"] = "Warren realmente la quiere. Mejor la voy a buscar.",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_030"] = "Es hora de ir a buscar la memoria USB de Warren...",
  ["Act_E1_3A_CampusA_VoiceOver01_Max_040"] = "Mejor leo el mensaje de Warren antes de que haga explotar mi teléfono.",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_010"] = "¿Qué está pasando hoy?",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_020"] = "Esto es tan raro... estas visiones... este poder...",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_030"] = "No puedo creer que vi a esa chica recibir un disparo...",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_040"] = "Ese Nathan Prescott es... aterrador. Me alegra haberlo delatado.",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_050"] = "Nathan Prescott es peligroso... ¿Por qué no le dije al director?",
  ["Act_E1_3A_CampusA_VoiceOver02_Max_070"] = "No puedo creer que de verdad retrocedí el tiempo...",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_010"] = "Qué raro es estar de vuelta aquí después de cinco años...",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_020"] = "Arcadia Bay luce exactamente igual... pero diferente.",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_030"] = "La Academia Blackwell es como... una universidad de escuela secundaria.",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_040"] = "Me gusta la energía de la escuela cerca del bosque primigenio.",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_050"] = "Solía saber todo de esta ciudad cuando era niña y ahora no conozco a nadie...",
  ["Act_E1_3A_CampusA_VoiceOver03_Max_060"] = "Esto es lo que se siente estar y sentirse sola a la vez.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_004"] = "Estás llena de sorpresas. ¿Cómo lo sabes?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_011"] = "Déjame adivinar... ¿Quieres volar mi drone?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_012"] = "No es eso. ¿Siquiera sabes lo que es un drone?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_013"] = "Visitas demasiados sitios de teorías conspirativas. Quizás sea demasiado complicado para ti. Qué loco; Warren dijo que eras inteligente. Por favor, aléjate.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_017"] = "Por supuesto. Nadie lo sabe todavía.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Brooke_021"] = "Muy impresionante, Max. Warren dijo que eras polifacética.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_014"] = "¡Me encantaría! Me encantan los aviones y los globos y...",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_015"] = "¿Es realmente tuyo? ¿Es legal?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_016"] = "Parece un drone HiFly, modelo... ¿B400 EVO? Es una buena tecnología.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_018"] = "Un arma, ¿verdad?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_019"] = "¿No se lo considera un arma de guerra?",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_020"] = "Me encanta la fotografía aérea. Los drones son perfectos para eso, especialmente los de largo alcance. Es una nueva era para las imágenes.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase01_Max_023"] = "Hola, Brooke.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase02_Brooke_001"] = "Lo siento, Max. Tengo que concentrarme para que el drone no choque.",
  ["Cue_E1_3A_CampusA_CHBrooke_Phase02_Brooke_004"] = "Apuesto a que David Madsen adoraría espiarnos con este drone.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_001"] = "Ah, hola, Max. ¿Puedo... eh... preguntarte algo? ¿Me permitirías dibujarte? Lo único: subo mis dibujos a Facebook...",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_005"] = "No importa. Supongo que te daría mucha vergüenza. Ahora debo seguir dibujando...",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_008"] = "Es curioso que digas eso... Justo estaba pensando en mi musa verdadera, Rachel Amber...",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_010"] = "Dejó de venir a clase. Algunos dicen que huyó, otros que saltó de un acantilado. Espero que esté bien.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_011"] = "No, pero una vez que pidió que dibujara su retrato. Oh, tenía un talento natural.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_012"] = "¡No me digas! Eres... una buena musa sustituta.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Daniel_015"] = "Me mata ver su dulce rostro usado en una foto como de criminales... Tenía buen corazón.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_002"] = "Preferiría que no, Daniel. No es que no quiero que...",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_004"] = "¿La conocías?",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_007"] = "Sería un honor, Daniel. Me haces sentir como una musa.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_009"] = "¿Entonces qué le pasó? Tiene que haber una historia.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_013"] = "¿Qué pasa, Daniel?",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_014"] = "Es difícil evitar sus carteles pegados por todo el campus.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase01_Max_016"] = "Bueno, ¿qué tal si empiezas a dibujarme? Aunque no sea tan buena como Rachel...",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase02_Daniel_001"] = "Gracias, Max, me gustaría dibujarte en otra oportunidad, si quieres.",
  ["Cue_E1_3A_CampusA_CHDaniel_Phase02_Daniel_002"] = "¿Te molesta, Max? Estoy dibujando.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_001"] = "Veamos si lo mereces, Max. Tienes que responder una pregunta simple: ¿Quién fotografió el famoso \"Soldado cayendo\"?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_003"] = "Caramba. Calladita, pero sabe cosas.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_007"] = "Caramba, no puedes diferenciar entre la fotografía callejera y el fotoperiodismo... No podrás mirar la carpeta.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_010"] = "Bueno, ambas son imágenes de famosos fotógrafos de guerra, pero debería saber la diferencia. Buen intento, respuesta equivocada.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_012"] = "Nos parecemos, Max. ¿Te gustaría mirar mi carpeta? Es un privilegio que no le otorgo a cualquiera...",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Evan_028"] = "A menos que pudiera viajar en el tiempo, McCurry nació cinco años después de la foto del \"Soldado cayendo\". Además, McCurry toma fotos a color. En otras palabras, no hay carpeta.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_002"] = "Robert Capa, por supuesto. Amo su trabajo, a pesar de la controversia sobre aquella foto.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_004"] = "Para eso estoy aquí.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_006"] = "¿No es Robert Doisneau?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_009"] = "Debe ser... Eugene Smith.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_013"] = "Sería un honor para mí, señor.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_026"] = "Oye, Evan. ¿Te importa si miro tu carpeta?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase01_Max_027"] = "Oh... ¿Steve McCurry?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase02_Evan_001"] = "Por supuesto, tienes el honor. Yo también. Y espero que no juzgues mi trabajo con mucha dureza.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase02_Evan_003"] = "Lo siento, debo seguir con mi carpeta... No tengo tiempo para aficionados. No te ofendas, Max.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase02_Evan_004"] = "Lo siento, debo seguir con mi carpeta...",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_001"] = "Como ves, Rachel Amber era mi modelo favorita aquí. Sabía exactamente qué ángulos funcionaban mejor con mi ojo.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_002"] = "Como compañeros en armas. Ella me entendía y nunca me juzgaba. Odiaba su círculo del club Vortex, pero nunca actuaba como si le importara. Sus amigos eran sus amigos.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_005"] = "Era como el mercurio. ¿Sabes qué significa eso?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Evan_009"] = "Nada bueno, Max... Nada bueno.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_003"] = "Tenían una relación cercana...",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_004"] = "¿Cómo era ella?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_006"] = "Por supuesto que sí, esnob.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_007"] = "Lo sé, puedo ser un poco diva.",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_008"] = "¿Qué crees que le pasó?",
  ["Cue_E1_3A_CampusA_CHEvan_Phase03_Max_010"] = "Hola, Evan.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_001"] = "Perdón, ¿Max? Sé que todos aman cuando les piden que firmen una petición, pero ¿le harías un favor a la señora Grant y me escucharías?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_004"] = "Qué lástima. Están pasando cosas graves en Blackwell, y te afectan a ti más que a todos. Vuelve a verme cuando tengas tiempo, ¿lo prometes?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_005"] = "David Madsen, nuestro jefe de seguridad, quiere poner cámaras de vigilancia en todo el campus. Pasillos, aulas, gimnasio, residencias, etc. La Academia Blackwell es una escuela secundaria, no una penitenciaría de alta seguridad.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_008"] = "La Academia Blackwell tiene una herencia noble, desde los nativos americanos que fundaron esta tierra hasta los pioneros que la compartieron en paz, sin miedo ni violencia.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_009"] = "Es un camino sin retorno. Y depende de ti y de tus compañeros ponerse firmes.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_012"] = "Las tribus que llegaron primero, que dieron la bienvenida a los colonos. Ambas culturas encontraron una simbiosis mutua y prosperaron.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_013"] = "Deberías aprender un poco la historia sobre tu alma mater. Encontrarás datos fascinantes. Hay mucho poder en esta región. Creo que ayuda la vena creativa de aquí...",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_014"] = "Ahora bien, antes de asignarte tarea con esta charla, ¿podrías firmar la petición para evitar que nuestro campus se convierta en 1984?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_017"] = "No estoy en contra de la seguridad, Max. Todos deberíamos preocuparnos cuando el espacio privado se vuelve público. Tu generación fue engañada para pensar que todo debería ser grabado.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_018"] = "Sabía que había una razón para considerarte mi nueva alumna favorita en Blackwell.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_030"] = "Max, no se trata de personalidades. Se trata de proteger los derechos civiles y el legado de libertad de nuestra escuela.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_032"] = "No tienes prejuicios, Max. Y todos rezamos para encontrar a Rachel sana y salva. Pero esta petición no tiene que ver con ella.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_034"] = "La ciencia es historia, Max. Y tengo un deseo secreto de enseñar el folclore y las leyendas locales. Hay muchos hechos únicos relacionados que puedes encontrar fascinantes...",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_035"] = "¿Quieres saber más de la petición ahora, Max?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Grant_038"] = "Todo tiene que ver con el tiempo, ¿verdad? Si cambias de parecer y quieres más información, ven a verme más tarde.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_002"] = "Bueno... Estoy un poco apurada ahora, realmente no tengo el tiempo para...",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_003"] = "Claro, siempre tengo tiempo para usted. ¿Cuál es la petición?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_006"] = "David Madsen no necesita otra excusa para acosar a los estudiantes aquí...",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_007"] = "Es una locura. Entiendo por qué las escuelas tienen que estar muy alertas estos días, pero ¿cámaras en las residencias?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_010"] = "¿Los nativos americanos?",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_011"] = "¿Blackwell es tan antigua? Increíble.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_015"] = "Absolutamente. No me molesta la seguridad, pero no... la vigilancia pura.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_016"] = "Señora Grant, respeto totalmente su pasión y conocimiento, pero cierta cantidad de cámaras me haría sentir un poco más segura.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_029"] = "Hola, Sra. Grant.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_031"] = "Las cámaras podrían haber ayudado a Rachel. Puedo ver ambas posturas.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_033"] = "Sabe mucho sobre Blackwell para ser la profesora de ciencias.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_036"] = "Claro, me gusta tener todos los datos primero.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase01_Max_037"] = "Bueno... Todavía estoy apurada, realmente no tengo el tiempo para...",
  ["Cue_E1_3A_CampusA_CHGrant_Phase02_Grant_002"] = "La petición está tomando forma. Creo que llegaremos a nuestra meta.",
  ["Cue_E1_3A_CampusA_CHGrant_Phase02_Grant_004"] = "Al menos conozco tu postura, Max. Siempre frente a la cámara.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_001"] = "Allí está, la maestra de la selfi retro.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_004"] = "Es una habilidad que se cultiva en Blackwell. Especialmente cuando se representa al club Vortex. Sin alardear.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_005"] = "Ay, por favor. Nathan es un muñeco vudú para todos. \"¡Maten al niño rico!\". Es buena onda, y es divertido estar con él. Odio a los que odian.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_008"] = "Solo si no eres tan genial como para entrar. Y no queda mal en tu currículum.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_010"] = "Sí. Pero deberías venir una noche con nosotros. Entonces no tendrías tantas ganas de chismear.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_013"] = "Solo porque no has salido de fiesta con nosotros. O incluso con Victoria. Que es muy graciosa cuando está fumada.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_014"] = "Relájate, paranoica. No estamos tan desesperados por diversión. Sabemos cómo hacerlo por nuestra cuenta.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_016"] = "Estás drogada. Rachel también solía juntarse con nosotros. Era una bomba. Inteligente, no maldita como... tú sabes.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_021"] = "Nate tiene sus momentos extremos, pero... ¿acaso no los tenemos todos?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_022"] = "Te lo pierdes. Es muy buena onda cuando está puesto. Y siempre tiene lo mejor.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_025"] = "Sabía que a ella le gustaba divertirse. Ajá, divertido estar con ella. Ah sí, y era sexy.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_027"] = "Adiós, Max. Ahora tengo que ponerme químico y estudiar. Deberíamos sacar a pasear a Dana y a ti alguna noche...",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_029"] = "Mmm, lo que sea que les pasa a las personas que desaparecen sin rastro.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_031"] = "No creas que conoces a Victoria tan bien. Respetaba a Rachel, aunque no lo demostrara.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_033"] = "No. Rachel era como un club propio. En realidad, era demasiado genial para nosotros. Y negaré que dije eso.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_035"] = "Eso es todo, Max. Ahora tengo que ponerme químico y estudiar. Deberíamos sacar a pasear a Dana y a ti alguna noche...",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Hayden_037"] = "Hola a ti, Max.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_002"] = "La misma. Te ves relajado como siempre, Hayden.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_003"] = "¿Te parece bien que Nathan Prescott los \"represente\"?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_006"] = "¿Qué demonios es el club Vortex? Parece tan elitista...",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_007"] = "A mí realmente me parece inestable.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_009"] = "Si tú lo dices...",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_011"] = "No lo creo. No soy el alma de una fiesta.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_012"] = "¿Te refieres a juntarme con el club Vortex? Eso suena como el principio de una broma horrible...",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_015"] = "Es raro pensar en fiestas con todos los carteles de Rachel Amber...",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_019"] = "Hola, Hayden.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_020"] = "Es razonable, aunque igual no me juntaré con él.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_023"] = "Todavía no lo sé, Hayden.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_024"] = "Entonces, ¿conocías a Rachel Amber?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_026"] = "Hablemos más tarde, Hayden.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_028"] = "¿Qué crees que le pasó?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_030"] = "¿A Victoria le caía bien Rachel? Parece ser del tipo celoso.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_032"] = "¿Rachel era realmente miembro del club Vortex?",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_034"] = "Estoy más confundida que antes... Es tan misterioso. Hablemos luego, Hayden.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase01_Max_036"] = "Hola otra vez, Hayden.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase02_Hayden_001"] = "En serio. Tengo que estudiar para un examen, así que no puedo hablar ahora.",
  ["Cue_E1_3A_CampusA_CHHayden_Phase02_Hayden_002"] = "Max, me estás amargando.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_001"] = "Aquí viene Max. ¿Vienes a rampear?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_004"] = "¡Qué farsante! Si no puedes nombrar un simple noseslide o un 3 flip, mejor te vas.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_005"] = "¿Cuál va a ser tu primer movimiento?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_008"] = "Caramba, no eres una farsante.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_010"] = "Oh, mira eso. Vamos a romper el asfalto para ti. ¿Qué quieres ver?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Justin_020"] = "Hagamos que Trevor te muestre.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_002"] = "¿Rampear? ¿Te refieres a romper la patineta o...?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_003"] = "Oh, sí. Muéstrame lo que tienes.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_006"] = "Eh... ¿saltar?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_007"] = "Vine a hacer un noseslide, ¡pero me encantaría ver a alguien hacer un 3 flip!",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_009"] = "No, solo que me mato en una patineta.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_018"] = "Me encantaría ver un... noseslide.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_019"] = "Vamos por el 3 flip.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase01_Max_021"] = "Hola, Justin.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_003"] = "Me encanta la idea de esas fotos con marco y todo. Pero no eres una chica patineta.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_006"] = "Qué lástima. Es lindo tener chicas en el grupo también. Rachel Amber y su amiga punk adoraban andar en patineta con nosotros.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_008"] = "Lo sé. Necesitamos más chicas aquí. Rachel Amber y su amiga punk solían andar en patineta con nosotros...",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_010"] = "Solía juntarse con nosotros a veces. Pero un día simplemente desapareció... Espero que esté viviendo el sueño en algún lugar. Si alguien la lastimó, juntaremos a los skaters y los mataremos a patinetas.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_011"] = "No me acuerdo de su nombre... Pero era sexy. Con tatuajes. Cabello azul. Intensa. Dejó de juntarse con nosotros después de que Rachel desapareciera... o huyera.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_015"] = "Max aparece otra vez. ¿Qué pasa?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_018"] = "Siempre que quieras tomas en acción, ven a vernos, Max.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_019"] = "¡Ni loco! Prefiero patinar que juntarme con esnobs como ella.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Justin_020"] = "No eres una chica patineta.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_004"] = "En realidad, no.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_005"] = "Solía serlo, pero ahora tengo la cámara.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_012"] = "¿Conocías a Rachel?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_013"] = "¿Quién era la amiga punk de Rachel?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_014"] = "Oye.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_016"] = "¿Alguna vez te juntaste con Victoria?",
  ["Cue_E1_3A_CampusA_CHJustin_Phase02_Max_017"] = "Nos vemos luego, Justin.",
  ["Cue_E1_3A_CampusA_CHJustin_Phase03_Justin_002"] = "Ya terminamos de hablar. ¡Eres muy falsa!",
  ["Cue_E1_3A_CampusA_CHJustin_Phase04_Justin_001"] = "¡Puedes vernos romper el asfalto!",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_001"] = "Max, no tengo ganas de hablar...",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_004"] = "Nathan Prescott, maldito niño rico. Se cree dueño de las personas como sus padres son dueños de Blackwell... Como es dueño del club Vortex.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_007"] = "Tú... ¿Lo conoces?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_008"] = "Alguien tiene que bajarle los humos a ese engreído...",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_013"] = "¿Qué? ¿En serio?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_014"] = "Parece que sabes más que eso. Max, dime.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_015"] = "Sí, es algo que demuestra la historia, ¿no? Al final se hará justicia para las ovejas.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Luke_017"] = "Eres mi nuevo héroe. Finalmente, el karma llega a Blackwell.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_002"] = "¿Qué ocurre?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_003"] = "Oh, lo siento... No te molestaré.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_006"] = "Sí, realmente es desagradable.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_009"] = "Lo encontré hoy, con un arma.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_010"] = "En realidad, no... Lo vi por ahí.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_011"] = "Va a suceder... El karma no tiene favoritos.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_012"] = "Se arruinará a sí mismo.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_016"] = "Lo vi con un arma hoy y se lo dije al director... Veremos cómo sigue...",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_018"] = "Em, ¿hola?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase01_Max_019"] = "No, es solo una mierda arrogante con mucho dinero. No es mi tipo.",
  ["Cue_E1_3A_CampusA_CHLuke_Phase02_Luke_001"] = "Me alegra que me dijeras eso, Max. Hablemos más tarde, ¿sí?",
  ["Cue_E1_3A_CampusA_CHLuke_Phase02_Luke_002"] = "Hablemos más tarde. ¿Está bien, Max?",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_002"] = "Eso creo. Tenemos suerte de tener un profesor tan famoso. Y en realidad me encanta su trabajo...",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_003"] = "Es frío... Siempre parece superior, no como un esnob, sino como que no sabes lo que está pensando.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_007"] = "¿Y cómo sabes esto?",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_009"] = "Interesante. ¿Lo ves? Siempre se aprende algo nuevo en la escuela.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_010"] = "¿Así que conocías a Rachel?",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_013"] = "Hola, Stella.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_014"] = "Todavía no estoy segura; quiero decir, claramente es un genio. Pero no estoy de acuerdo con todo lo que dice.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_017"] = "Victoria es demasiado obvia. No creo que a Jefferson esté atraído.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_018"] = "Ahora que lo dices, no responde al coqueteo de Victoria. Significa que tiene buen gusto.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Max_020"] = "De ningún modo. Puedes meterlo en serios problemas. Y él no va meterse con una estudiante.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_001"] = "¡Oye, te conozco! Eres la nueva chica, callada, de la clase de Jefferson. ¿No es increíble?",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_004"] = "A mí también. Su material de la Nueva York urbana es fantástico, pero me alegra que haya regresado a sus raíces de Oregón. Al diablo con la élite de la Costa Este. Los pretenciosos de las galerías deben odiar que Mark Jefferson nos esté enseñando fotografía a los pueblerinos de Blackwell... además, es bastante sexy para un hombre maduro.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_005"] = "Quizás. El Sr. Jefferson tiene su propio estilo.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_006"] = "Si Victoria no estuviera tan encima, le echaría los perros.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_008"] = "Eso crees tú.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_011"] = "En realidad, no. La vi con las otras chicas geniales como Victoria. No mi tipo de gente. Pero escuché historias locas sobre Rachel...",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_012"] = "Como dije, tienes mucho que aprender, Max. Te veo en clase.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_015"] = "Se pone un poco pretencioso, pero es apasionado y dice lo que piensa.",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_016"] = "No creo que haya cerrado el trato. Pero no es la única jugadora...",
  ["Cue_E1_3A_CampusA_CHStella_Phase01_Stella_019"] = "Tienes mucho que aprender aquí en Blackwell. Te aseguro que Rachel Amber se acostó con él. Bueno... Lo oí de una buena fuente.",
  ["Cue_E1_3A_CampusA_CHStella_Phase02_Stella_001"] = "Me gustaría estudiar esta foto si no te importa.",
  ["Cue_E1_3A_CampusA_DanielDraws_Daniel_010"] = "Oh, es una buena postura.",
  ["Cue_E1_3A_CampusA_DanielDraws_Daniel_020"] = "Bien, bien...",
  ["Cue_E1_3A_CampusA_DanielDraws_Max_030"] = "El mejor retrato.",
  ["Cue_E1_3A_CampusA_DroneControl_Brooke_010"] = "Ten, haz que el drone dé una vuelta alrededor del campus.",
  ["Cue_E1_3A_CampusA_FactNathan_Principal_010"] = "Nathan Prescott, favor de presentarse en la oficina del director. Gracias.",
  ["Cue_E1_3A_CampusA_Idle_Grant_010"] = "¿Alguien quiere firmar una petición para evitar que Blackwell se convierta en un estado de vigilancia?",
  ["Cue_E1_3A_CampusA_Idle_Grant_020"] = "Es un tema muy importante que los afecta a todos ustedes aquí.",
  ["Cue_E1_3A_CampusA_Idle_Grant_030"] = "Solo necesitamos juntar 100 firmas más para que nos den una audiencia pública...",
  ["Cue_E1_3A_CampusA_Idle_Grant_040"] = "Todos queremos estar seguros, no que nos espíen.",
  ["Cue_E1_3A_CampusA_Idle_Grant_050"] = "Y no se trata de política, solo se trata de mantener nuestra gran tradición de libertad de expresión de Blackwell...",
  ["Cue_E1_3A_CampusA_Idle_Grant_060"] = "Sé que están apurados por mandar mensajes antes de su próxima clase pero esto es importante también...",
  ["Cue_E1_3A_CampusA_Idle_Grant_070"] = "¿Y si el Gran Hermano estuviera mirando lo que escriben? ¿Les parece bien?",
  ["Cue_E1_3A_CampusA_Idle_Grant_080"] = "¿Alguien me escucha?",
  ["Cue_E1_3A_CampusA_Idle_Grant_090"] = "¿Alguien?",
  ["Cue_E1_3A_CampusA_StellaFriend_CitizenF1_020"] = "Me encantan los contrastes.",
  ["Cue_E1_3A_CampusA_StellaFriend_Stella_010"] = "Oh, su trabajo es tan sensible.",
  ["Cue_E1_3A_CampusA_StellaFriend_Stella_030"] = "El Sr. Jefferson es un maestro de la luz y la sombra...",
  ["Act_E1_3B_CampusB_BrokenWindow_Look01_Max_010"] = "¡Eso definitivamente es karma instantáneo!",
  ["Act_E1_3B_CampusB_Bucket_Interact02_Max_010"] = "No puedo; Samuel está demasiado cerca.",
  ["Act_E1_3B_CampusB_Bucket_Look01_Max_010"] = "Mmm, un cubo de pintura junto a Victoria. Tengo un plan.",
  ["Act_E1_3B_CampusB_Bucket_Look02_Max_010"] = "De acuerdo, que empiece la fiesta.",
  ["Act_E1_3B_CampusB_CHAlyssa_Look01_Max_010"] = "Creo que Alyssa y yo tendríamos que ser mejores amigas.",
  ["Act_E1_3B_CampusB_CHAlyssa_Look02_Max_010"] = "Ay, pobre Alyssa. Eso dejará un moretón.",
  ["Act_E1_3B_CampusB_CHAlyssa_Look03_Max_010"] = "Ahora Alyssa puede disfrutar de su mala novela en paz.",
  ["Act_E1_3B_CampusB_CHKate_Look01_Max_010"] = "Ahí está Kate, luce más triste que de costumbre.",
  ["Act_E1_3B_CampusB_CHLogan_Look01_Max_010"] = "Eh, Logan Robertson: El Gran Idiota Americano.",
  ["Act_E1_3B_CampusB_CHSamuel_Look01_Max_010"] = "El viejo Samuel. A algunas personas les parece tenebroso. No lo es, solo es raro como los \"Expedientes secretos X\".",
  ["Act_E1_3B_CampusB_CHSamuel_Look02_Max_010"] = "Ahí va Samuel Da Vinci a pintar la ventana...",
  ["Act_E1_3B_CampusB_CHVictoria_Look01_Max_010"] = "Oh, mierda, allí están Victoria y sus \"muchachas malas\".",
  ["Act_E1_3B_CampusB_CHVictoria_Look02_Max_010"] = "Es la primera y última vez que espero escuchar eso.",
  ["Act_E1_3B_CampusB_CHVictoria_Look03_Max_010"] = "Luce como un gato mojado y enojado. Pero sigue siendo elegante.",
  ["Act_E1_3B_CampusB_CHVictoria_Look04_Max_010"] = "Victoria no está entendiendo la indirecta.",
  ["Act_E1_3B_CampusB_CHVictoria_Look05_Max_010"] = "¡Vaya!, luce tan triste y solitaria sentada allí sola.",
  ["Act_E1_3B_CampusB_CHVictoria_Look06_Max_010"] = "Debería sentirme mal por Victoria, pero, en realidad, no me importa un comino. Karma.",
  ["Act_E1_3B_CampusB_CHVictoria_Look07_Max_010"] = "Espero que Victoria no me odie tanto ahora.",
  ["Act_E1_3B_CampusB_CHZachary_Look01_Max_010"] = "Zachary siempre luce como si prefiriera estar tomando una cerveza que tirando una pelota de fútbol.",
  ["Act_E1_3B_CampusB_CHZachary_Look02_Max_010"] = "Casi que podría darme lástima, si no fuera un completo idiota. Pobre Juliet.",
  ["Act_E1_3B_CampusB_Graffiti01_Look01_Max_010"] = "No te desquites con el árbol, perdedor.",
  ["Act_E1_3B_CampusB_Graffiti02_Look01_Max_010"] = "Todo esto es buen material para fotografiar en el futuro.",
  ["Act_E1_3B_CampusB_Graffiti03_Look01_Max_010"] = "La gente sí que escribe estupideces en las paredes aquí.",
  ["Act_E1_3B_CampusB_Graffiti04_Look01_Max_010"] = "Siento que estoy leyendo jeroglíficos antiguos...",
  ["Act_E1_3B_CampusB_Ladder_Look01_Max_010"] = "No quiero hacer algo con esa escalera y que el pobre Samuel termine herido. Solo quiero correr a Victoria de ahí.",
  ["Act_E1_3B_CampusB_MPA01_Look01_Max_010"] = "No me sentiré bien hasta no ver otro de estos carteles.",
  ["Act_E1_3B_CampusB_Pipe_Look01_Max_010"] = "La válvula principal de rociadores parece fácil de usar...",
  ["Act_E1_3B_CampusB_Plaque_Look01_Max_010"] = "\"Residencia estudiantil Prescott\". Dios mío. ¡¿La familia de Nathan es dueña de mi residencia?!",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver01_Max_010"] = "Está bien, encontraré una forma de hacer que esta maldita se vaya.",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver01_Max_020"] = "Misión aceptada: Sacar a Victoria de la escalerilla.",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver01_Max_030"] = "Oh, sí, Victoria, sacaré tu huesudo trasero de mi camino.",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver02_Max_010"] = "Bien, veamos si esto funciona.",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver03_Max_020"] = "¡Tan cerca! Pero no fue suficiente. Tienen que estar justo debajo de la cubeta.",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver04_Max_020"] = "Eso no funcionó. Piensa, Max, piensa: ¿qué más...?",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver05_Max_010"] = "¡Funcionó! No se metan con Max, malditas.",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver06_Max_030"] = "Tal vez, no debería haber hecho eso... Ahora tengo que ir a mi habitación, y luego ver a Warren.",
  ["Act_E1_3B_CampusB_PuzzleVoiceOver07_Max_040"] = "Victoria probablemente me engañó. Debí haberla engañado yo... Espero llegar a mi habitación antes de encontrar a Warren.",
  ["Act_E1_3B_CampusB_RecycleBin_Look01_Max_010"] = "Es bueno saber que nuestro campus es ecológico.",
  ["Act_E1_3B_CampusB_RewindChoice_KateIntervene_Max_010"] = "Me sentí como una heroína cotidiana al ayudar a Kate, pero ahora el imbécil del oficial David me tiene entre cejas. ¿Debería rebobinar y no entrometerme?",
  ["Act_E1_3B_CampusB_RewindChoice_KatePhoto_Max_010"] = "¡Vaya!, debería haber intervenido entre Kate y David... Ese imbécil se pasó de la raya... Podría rebobinar y probar algo diferente...",
  ["Act_E1_3B_CampusB_RewindChoice_VictoriaComfort_Max_010"] = "No me creo ni por un minuto la porquería de \"seamos amigas\" de Victoria. Debo rebobinar y engañarla.",
  ["Act_E1_3B_CampusB_RewindChoice_VictoriaPhoto_Max_010"] = "Victoria se ganó ese insulto... pero no debo rebajarme a su nivel. Podría usar mi nuevo poder para decirle algo lindo...",
  ["Act_E1_3B_CampusB_Sign_Look01_Max_010"] = "Siempre me emociona un poco pensar que tengo mi propia habitación aquí.",
  ["Act_E1_3B_CampusB_Sprinkler01_Look01_Max_010"] = "Con toda la lluvia de Oregón, uno creería que no se necesita agua para regar el césped. Supongo que Blackwell tiene que mantener el césped y las plantas bien cuidados para que luzcan bien en un catálogo.",
  ["Act_E1_3B_CampusB_Sprinkler01_Look02_Max_010"] = "Con tanta sequía, es hasta insultante desperdiciar toda esta agua.",
  ["Act_E1_3B_CampusB_Sprinkler01_Look03_Max_010"] = "Podría aumentar la intensidad del rociador y darles a Victoria y sus clones un incentivo para largarse...",
  ["Act_E1_3B_CampusB_Sprinkler01_Look04_Max_010"] = "Está bien, ¿dónde está la válvula del rociador?",
  ["Act_E1_3B_CampusB_Sprinkler01_Look05_Max_010"] = "Sería hipócrita decir que hoy no estoy agradecida por el sistema de riego de Blackwell.",
  ["Act_E1_3B_CampusB_Sprinkler01_Look06_Max_010"] = "Sería bueno si el agua hiciera que Victoria floreciera en una mejor persona.",
  ["Act_E1_3B_CampusB_Squirrel_Look01_Max_010"] = "Esto va a ser demasiado tierno. Al menos no es la foto de un gato.",
  ["Act_E1_3B_CampusB_SupplyOffice_look01_Max_010"] = "Me encantaría escabullirme como un ninja y ver cómo vive el director.",
  ["Act_E1_3B_CampusB_Totem_look01_Max_010"] = "Warren me dijo que el tótem se llama \"Tobanga\" por una razón que nadie conoce.",
  ["Act_E1_3B_CampusB_Umbrella_Look01_Max_010"] = "Turista.",
  ["Act_E1_3B_CampusB_VoiceOver01_Max_010"] = "Tengo que ir a mi habitación y devolverle a Warren la memoria USB.",
  ["Act_E1_3B_CampusB_VoiceOver02_Max_020"] = "Si le dijera a Warren lo que está pasando, ¿se reiría?",
  ["Act_E1_3B_CampusB_VoiceOver03_Max_010"] = "Todos decían que me encantaría estar por mi cuenta en una residencia. Error.",
  ["Act_E1_3B_CampusB_VoiceOver03_Max_020"] = "Este lugar parece un centro de alegría escolar. \"Parece\".",
  ["Act_E1_3B_CampusB_VoiceOver03_Max_030"] = "Mis amigos y familiares dijeron que \"florecería\" si estaba por mi cuenta. Me siento muy mal.",
  ["Act_E1_3B_CampusB_VoiceOver04_Max_010"] = "¡Vaya!, no costó mucho que Juliet y Dana se abrieran conmigo... Solo tuve que ayudarlas con sus problemas amorosos. Este sí que es un superpoder...",
  ["Act_E1_3B_CampusB_VoiceOver04_Max_020"] = "Podría ser muy popular con solo convertirme en la ninja de los chismes de todos. ¿Para eso tengo las visiones y el poder?",
  ["Act_E1_3B_CampusB_VoiceOver05_Max_010"] = "¡De eso estoy hablando! Ayudé a alguien.",
  ["Cue_E1_3B_CampusB_AlyssaHurt_Alyssa_020"] = "¡Ay! ¡Eso dolió!",
  ["Cue_E1_3B_CampusB_AlyssaHurt_Zachary_010"] = "¡A la mierda con esto!",
  ["Cue_E1_3B_CampusB_AlyssaMoveSit_Alyssa_020"] = "Si insistes, Max.",
  ["Cue_E1_3B_CampusB_AlyssaMoveSit_Max_010"] = "Alyssa, mueve la cabeza.",
  ["Cue_E1_3B_CampusB_BucketFall_Samuel_030"] = "No puedo hacerlo, no puedo...",
  ["Cue_E1_3B_CampusB_BucketFall_Victoria_010"] = "¡Por Dios! ¿Qué carajo?",
  ["Cue_E1_3B_CampusB_BucketFall_Victoria_020"] = "Muchas gracias por casi arruinar mi ropa.",
  ["Cue_E1_3B_CampusB_BucketFall_Victoria_040"] = "Tienen tanta suerte de que les cayó a ustedes. Te demandaríamos...",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax02_Alyssa_001"] = "Gracias otra vez; hablamos más tarde.",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_001"] = "Max, eso fue fantástico. ¡Gracias!",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_004"] = "Años de práctica de evasión. Los bullies nunca cambian.",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_005"] = "Estúpidos deportistas. Si fuera un miembro del club Vortex, nunca habrían...",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Alyssa_008"] = "Eres inteligente. Deberíamos juntarnos más seguido... Ahora tengo que terminar este estúpido libro.",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_002"] = "No hay problema. Tienes reflejos rápidos.",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_003"] = "Estuvo cerca.",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_006"] = "Por eso estás mejor así.",
  ["Cue_E1_3B_CampusB_CHAlyssa_AlyssaThanksMax_Max_007"] = "¿Te gustaría ser miembro?",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa02_Alyssa_001"] = "Lo siento, tengo que descubrir qué pasa.",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_001"] = "Ah, hola Max.",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_005"] = "\"Ama hoy o muere para siempre\"... No digas nada.",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_006"] = "Fantástico. Estoy sola leyendo novelas románticas. Pronto seré la mejor amiga de Victoria en el club Vortex...",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Alyssa_009"] = "Buen punto. Ahora, si me disculpas...",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_003"] = "¿Qué estás leyendo?",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_004"] = "¿Cómo estás?",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_007"] = "Es un éxito. ¿Qué decir?",
  ["Cue_E1_3B_CampusB_CHAlyssa_MaxTalkAlyssa_Max_008"] = "Creo que estás mejor leyendo novelas de chicas.",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_001"] = "Hola, Max...",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_004"] = "No recuerdo... Supongo que no me importa mucho de nada hoy.",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_005"] = "Hoy estoy como más allá de la humanidad... Perdón por ser tan dramática.",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Kate_007"] = "Max, quisiera estar sola, si no te importa. Lo siento...",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_002"] = "¿Te fue bien en clase hoy?",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_003"] = "Pareces depre. ¿Estás bien?",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_006"] = "¿Hay algo que pueda...?",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate01_Max_008"] = "Hola, Kate.",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate02_Kate_001"] = "En serio, Max. No quiero hablar.",
  ["Cue_E1_3B_CampusB_CHKate_MaxTalkKate02_Kate_002"] = "Max, despabílate.",
  ["Cue_E1_3B_CampusB_CHLogan_MaxTalkLogan_Logan_001"] = "No, no puedes sacar una foto. Tendrás que esperar al juego del viernes.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_002"] = "Pareces ocupado, Samuel.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_003"] = "¿Qué pasa con todos los carteles de Rachel Amber?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_006"] = "Solo no pintes sobre los carteles de Rachel Amber.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_007"] = "... Em, supongo. ... Hace que el campus se vea triste.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_009"] = "¿Conocías a Rachel?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_011"] = "¿Qué tal, Samuel?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_012"] = "¿Qué crees que le pasó?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_013"] = "¿Cómo era ella? Debe haber sido popular.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Max_014"] = "Hasta luego, Samuel.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_001"] = "Hola.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_004"] = "Oh, siempre estoy haciendo algo. Hoy me toca barrer y pintar las ventanas.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_005"] = "Solo ella lo sabría, ¿no?",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_008"] = "No puedes pintar la luz del sol...",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_010"] = "¿Cómo puedes conocer un prisma? Solo lo miras absorto... Ahora tengo que ir a pintar las ventanas.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_015"] = "Es mejor no quedarse en el pasado. Samuel mira hacia adelante. Como un reloj.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_016"] = "Incluso la luz del sol puede hacer sombra. Rachel hacia las dos cosas al mismo tiempo, ¿sabes? Era como una batería. Positiva y negativa.",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel01_Samuel_017"] = "Cuidado cuando camines por aquí, Max. Luego de barrer, pinto...",
  ["Cue_E1_3B_CampusB_CHSamuel_MaxTalkSamuel02_Samuel_001"] = "Lo siento, Max. No más charla. Tengo que terminar esto antes de pintar.",
  ["Cue_E1_3B_CampusB_CHVictoria_Stained_Max_001"] = "Em... hola, Victoria...",
  ["Cue_E1_3B_CampusB_CHVictoria_Stained_Victoria_002"] = "¿Qué quieres, Max?",
  ["Cue_E1_3B_CampusB_CHZachary_MaxTalkZachary2_Zachary_001"] = "Piérdete, hipster. No doy entrevistas.",
  ["Cue_E1_3B_CampusB_CHZachary_MaxTalkZachary_Zachary_001"] = "Pelota, Max. Una gran pelota. Hazte a un lado.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_010"] = "Lo siento. Tienes un hermoso abrigo de casimir...",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_030"] = "Bueno, siempre sabes cómo elegir los mejores conjuntos.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_050"] = "Vi tus fotos. Tienes buen ojo, muy al estilo de Richard Avedon.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_090"] = "Eso fue malo... pero muy gracioso.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Max_110"] = "Sé a lo que te refieres, Victoria. Hasta luego.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_020"] = "Lo fue. Pero habrá otros.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_040"] = "Tengo algo de talento. El Sr. Jefferson me dijo...",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_060"] = "Es uno de mis ídolos... Gracias, Max.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_070"] = "Espero que esas putas me traigan una toalla antes de que me cuelguen un cartel.",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_080"] = "Te mereces otra oportunidad. Perdón por bloquearte y por lo de... \"A la mierda con tu selfi\".",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_100"] = "Es uno de esos días, ¿sabes?",
  ["Cue_E1_3B_CampusB_ComfortVictoria_Victoria_120"] = "Au revoir.",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_David_020"] = "Disculpa, este es un tema oficial del campus...",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_David_040"] = "Oye, nadie está molestando a nadie. Solo hago mi trabajo.",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_David_060"] = "Tú eres parte del problema, señorita. Me acordaré de esta conversación.",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Kate_080"] = "Oh, Max, eso fue fantástico. Creo que lo asustaste, finalmente... Me tengo que ir, pero gracias. Significa mucho para mí.",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_010"] = "Oye, ¿por qué no la dejas en paz?",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_030"] = "Discúlpame a mí, pero no tendrías que gritarles a los estudiantes. Ni intimidarlos.",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_050"] = "No, no lo haces.",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_070"] = "¿\"Señorita\"?",
  ["Cue_E1_3B_CampusB_KateAndDavidIntervene_Max_090"] = "Cuando quieras, Kate.",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_David_010"] = "...no puedes engañarme. Sé todo sobre esta escuela. Tengo toda la información. Así que mejor te decides de qué lado vas a estar...",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_David_020"] = "Piensa en mí como en una tormenta. Una tormenta que va en tu camino. Prepárate.",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_Kate_030"] = "¡Por favor, déjeme en paz!",
  ["Cue_E1_3B_CampusB_KateAndDavidPhoto_Kate_040"] = "Espero que hayas disfrutado del show. Gracias por nada, Max.",
  ["Cue_E1_3B_CampusB_KateAndDavid_David_010"] = "¡No creas que estoy ciego! Veo todo lo que sucede en Blackwell. ¿Entiendes?",
  ["Cue_E1_3B_CampusB_KateAndDavid_Kate_020"] = "No... ¡y déjeme en paz!",
  ["Cue_E1_3B_CampusB_PipeActivated_Taylor_020"] = "Relájate, Victoria. Es solo agua.",
  ["Cue_E1_3B_CampusB_PipeActivated_Taylor_040"] = "Te ves... bien.",
  ["Cue_E1_3B_CampusB_PipeActivated_Victoria_010"] = "¿Qué carajo? ¿En serio? Mira esto…",
  ["Cue_E1_3B_CampusB_PipeActivated_Victoria_030"] = "¡Sí, agua en mi casimir! ¿Tienes idea de cuánto cuesta este conjunto?",
  ["Cue_E1_3B_CampusB_PipeActivated_Victoria_050"] = "Ni siquiera puedo relajarme en la escalera...",
  ["Cue_E1_3B_CampusB_TauntVictoria_Max_020"] = "Oh, espera, ¡mantén esa pose!",
  ["Cue_E1_3B_CampusB_TauntVictoria_Max_030"] = "Y no hace falta ningún filtro cuando publique esto.",
  ["Cue_E1_3B_CampusB_TauntVictoria_Max_040"] = "Ahora, muévete. Tuve un día difícil y me voy a mi habitación.",
  ["Cue_E1_3B_CampusB_TauntVictoria_Victoria_010"] = "No... No digas nada, Max.",
  ["Cue_E1_3B_CampusB_TauntVictoria_Victoria_050"] = "Hazlo... Sé dónde vives... Y también Nathan...",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_010"] = "Oh, miren, es Max Cauldfield, la puta de las selfis de Blackwell.",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_020"] = "¡Qué truco tan lamentable! Incluso Mark —el Sr. Jefferson— se traga tu mierda de hipster abandonada.",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_030"] = "\"El proceso de Daguerre, Señor\". Apenas podías pronunciarlo. Supongo que hoy te tomaste todos los medicamentos.",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_040"] = "Ya que sabes todas las respuestas, supongo que tendrás que encontrar otra forma de entrar al dormitorio. Nosotras no nos vamos a mover.",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_050"] = "Oh, espera, ¡mantén esa pose!",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_060"] = "Tan original. No te preocupes, Max. Le podré un filtro de época antes de publicarlo en todos los medios sociales.",
  ["Cue_E1_3B_CampusB_VictoriaBitch_Victoria_070"] = "Ahora, ¿por qué no te vas a la mierda con tu selfi?",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Courtney_020"] = "¿Estás bien, Victoria?",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Courtney_060"] = "Espera, espera, buscaremos algunas toallas... ¡Ya volvemos!",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Samuel_040"] = "El viejo Samuel está apenado. La pintura fresca no es buena para el cabello, no, señor. Lo siento.",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_010"] = "¡No me digas! ¡Mierda!",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_030"] = "¡Tengo pintura sobre mi casimir y mi maquillaje, idiotas!",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_050"] = "¡No me toques, loco!",
  ["Cue_E1_3B_CampusB_VictoriaHurt_Victoria_070"] = "¡Muevan sus culos antes de que me seque!",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_010"] = "Sigue caminando, hippie.",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_020"] = "¿Entiendes español? Piérdete.",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_030"] = "Lo siento, sin paparazzi.",
  ["Cue_E1_3B_CampusB_VictoriaStopsMax_Victoria_040"] = "Nadie pasará, ¿capiche?",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_020"] = "Oh, Zach, ¡está traído, hermano!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_110"] = "¡Amigo!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_120"] = "¡Uhhh, amigo!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_130"] = "¡Solo!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_140"] = "¡No!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_150"] = "¡No!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_160"] = "¡Bien!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_170"] = "¡Sí!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_180"] = "¡Sí!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_190"] = "¡Sí!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_200"] = "¡Sí!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_210"] = "¡Sí!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_220"] = "Así es.",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_230"] = "¡Hermano!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_240"] = "¡Hermano!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_250"] = "¡Vamos!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Logan_260"] = "¡Amigo!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_010"] = "¡Vamos, Logan! ¡Tráelo, hermano!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_030"] = "¡Fantástico!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_040"] = "¡Fantástico!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_050"] = "¡Hermano!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_060"] = "¡Bien!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_070"] = "¡Bien, hermano!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_080"] = "¡Buen tiro, hermano!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_090"] = "¡Excelente!",
  ["Cue_E1_3B_CampusB_ZacharyAndLogan_Zachary_100"] = "¡Excelente!",
  ["Act_E1_3C_Corridor_BlackwellMap_Look01_Max_010"] = "Blackwell no es tan grande, aunque se siente como un laberinto.",
  ["Act_E1_3C_Corridor_BrookeSlate_Look01_Max_010"] = "Warren y Brooke tendrían que estar juntos. Son perfectos el uno para el otro.",
  ["Act_E1_3C_Corridor_CHJuliet_Look01_Max_010"] = "Juliet está a punto de explotar.",
  ["Act_E1_3C_Corridor_CHJuliet_Look02_Max_010"] = "Nota mental: Vale la pena recordar nombres.",
  ["Act_E1_3C_Corridor_CHJuliet_Look03_Max_010"] = "Debo encontrar la manera de poner fin a este estúpido enfrentamiento.",
  ["Act_E1_3C_Corridor_CHJuliet_Look04_Max_010"] = "Pobre Juliet, la verdad está por aniquilarla.",
  ["Act_E1_3C_Corridor_DanaSlate_Look01_Max_010"] = "Dana todavía tiene el corazón de una porrista...",
  ["Act_E1_3C_Corridor_DormMap_Look01_Max_010"] = "Bienvenidos al infierno Blackwell...",
  ["Act_E1_3C_Corridor_ExpressionPanel02_Look01_Max_010"] = "Vaya, la gente de aquí es despiadada.",
  ["Act_E1_3C_Corridor_ExpressionPanel02_Look01_Max_020"] = "Podría ser divertido. Me alegra no ser la única nerd solitaria de aquí.",
  ["Act_E1_3C_Corridor_ExpressionPanel02_Look01_Max_030"] = "Gracias por la advertencia.",
  ["Act_E1_3C_Corridor_ExpressionPanel_Look01_Max_010"] = "Este es como un ADN público de nuestra residencia...",
  ["Act_E1_3C_Corridor_ExpressionPanel_Look01_Max_020"] = "¡Vamos, Sra. Grant! No creo que yo lo haga... Soy una perdedora.",
  ["Act_E1_3C_Corridor_JulietSlate_Look01_Max_010"] = "Juliet: reportera extrema.",
  ["Act_E1_3C_Corridor_KateSlate_Look01_Max_010"] = "Bueno, esto es solo cruel y estúpido.",
  ["Act_E1_3C_Corridor_KateSlate_Look02_Max_010"] = "El símbolo universal de \"Por favor, déjame sola, idiota\".",
  ["Act_E1_3C_Corridor_MPA01_Look01_Max_010"] = "Esta muchacha debía ser popular, está en todas partes.",
  ["Act_E1_3C_Corridor_MPA02_Look01_Max_010"] = "Lo entendemos: está desaparecida. Alguien se ha vuelto loco con estos carteles.",
  ["Act_E1_3C_Corridor_MaxSlate_Look01_Max_010"] = "Qué triste. No escribí nada. No tengo nada que decir.",
  ["Act_E1_3C_Corridor_MaxSlate_Look02_Max_010"] = "Es obvio, pero es la verdad.",
  ["Act_E1_3C_Corridor_ModernAlarm_Look01_Max_010"] = "Al menos esta alarma es de este siglo.",
  ["Act_E1_3C_Corridor_Poster01_Look01_Max_010"] = "Muy atmosférico. Hay que quitarle el polvo.",
  ["Act_E1_3C_Corridor_Poster02_Look01_Max_010"] = "Sí, claro.",
  ["Act_E1_3C_Corridor_Poster03_Look01_Max_010"] = "\"¡Viven!\"",
  ["Act_E1_3C_Corridor_Poster04_Look01_Max_010"] = "Pero ¿qué está tratando de decirme este cartel?",
  ["Act_E1_3C_Corridor_ScoreBoard_Look01_Max_010"] = "Me encantaría hacer un collage de fotos de cada persona que publicó estos carteles.",
  ["Act_E1_3C_Corridor_StellaSlate_Look01_Max_010"] = "¿Habitación 217? Nunca voy a entrar.",
  ["Act_E1_3C_Corridor_TaylorSlate_look01_Max_010"] = "¿Esta es una iniciación del club Vortex o del club Victoria? Muy patético.",
  ["Act_E1_3C_Corridor_ToiletPaper_Look01_Max_010"] = "Parece que nadie ganó esta guerra de papel higiénico. No queda nada más que fantasmas.",
  ["Act_E1_3C_Corridor_VictoriaSlate_Look01_Max_010"] = "Ay, Victoria, baja un poco la intensidad.",
  ["Act_E1_3C_Corridor_VoiceOver01_Max_010"] = "Solo ve a tu habitación y toma la memoria USB de Warren.",
  ["Act_E1_3C_Corridor_VoiceOver01_Max_020"] = "Luego de hacer todo esto, todavía debo tomar la memoria USB de Warren.",
  ["Act_E1_3C_Corridor_VoiceOver02_Max_010"] = "Puedo ayudar a Dana... y mirar en la habitación de Victoria para comprobar si es la clase de persona que espero que no sea.",
  ["Act_E1_3C_Corridor_VoiceOver02_Max_020"] = "Debo llegar a la habitación de Victoria, ahora.",
  ["Act_E1_3C_DanaRoom_AbortionClinicList_Look01_Max_010"] = "Supongo que Dana fue a la cita...",
  ["Act_E1_3C_DanaRoom_BigfootBanner_Look01_Max_010"] = "Dana se toma muy en serio el espíritu Blackwell.",
  ["Act_E1_3C_DanaRoom_CHDana_Look01_Max_010"] = "Dana realmente parece estresada por todo esto.",
  ["Act_E1_3C_DanaRoom_CHDana_Look02_Max_010"] = "Fantástico. Hice que Dana se estrese más.",
  ["Act_E1_3C_DanaRoom_CheerleaderOutfit_Look01_Max_010"] = "No puedo ni imaginarme cómo sería la vida si fuera porrista. Dramática, supongo.",
  ["Act_E1_3C_DanaRoom_ClubSticker01_Look01_Max_010"] = "Sería una etiqueta genial sin las palabras.",
  ["Act_E1_3C_DanaRoom_DanaLaptop_Interact01_Max_010"] = "Por supuesto, una porrista popular como Dana tiene un millón de amigos. Es fascinante echar un vistazo a las redes sociales de Dana... y sí, Max, está muy mal.",
  ["Act_E1_3C_DanaRoom_DanaLaptop_Look01_Max_010"] = "Uuuh, el muro de Facebook de Dana está muy activo... No debería mirar...",
  ["Act_E1_3C_DanaRoom_LoganNote_Look01_Max_010"] = "Esto es triste y patético.",
  ["Act_E1_3C_DanaRoom_MaternityBook_Look01_Max_010"] = "Dios mío. Dana de verdad estaba por su cuenta.",
  ["Act_E1_3C_DanaRoom_PregnancyTest_Look01_Max_010"] = "Eso parece una prueba de embarazo casera...",
  ["Act_E1_3C_DanaRoom_PregnancyTest_Look02_Max_010"] = "La la la, no veo esa prueba de embarazo.",
  ["Act_E1_3C_DanaRoom_USBKey_Interact01_Max_010"] = "Debo proteger mi tesoro, para que Max no deba perseguirlo otra vez.",
  ["Act_E1_3C_DanaRoom_USBKey_Look01_Max_010"] = "Allí está la maldita memoria USB.",
  ["Act_E1_3C_DanaRoom_VoiceOver01_Max_010"] = "Casi listo... Tomaré la memoria USB e iré a ver a Warren.",
  ["Act_E1_3C_DanaRoom_VoiceOver01_Max_020"] = "Bien hecho, Max. Heriste sus sentimientos por ser tan entrometida otra vez. Pero podría rebobinar y compensarla...",
  ["Act_E1_3C_MaxRoom_Artbooks_Look01_Max_010"] = "Cartier-Bresson, Doisneau, Hamilton... ¡Los mejores!",
  ["Act_E1_3C_MaxRoom_Binder_Interact01_Max_010"] = "¡Philip-Lorca diCorcia, mi hombre! No creo que pueda llevar mi cámara a esos lugares, mira esa foto... Adoro el estilo victoriano de Julia Cameron. Hablando de cámaras analógicas... Ah, Dalí, ¡qué buen ojo! Él sí que podía congelar el tiempo...",
  ["Act_E1_3C_MaxRoom_Binder_Look01_Max_010"] = "Aquí está mi fuente de inspiración instantánea para tomar fotos.",
  ["Act_E1_3C_MaxRoom_Book_Look01_Max_010"] = "Me alegra que Kate me prestara su copia de \"El país de octubre\"... Debería conseguir todos los libros de Bradbury.",
  ["Act_E1_3C_MaxRoom_Cookies_Look01_Max_010"] = "Qué hermoso que mamá me haya enviado una gran caja de bocados de coco y chocolate por mi cumpleaños, y que haya metido un certificado de regalo por 200 dólares. Sí que sabe cómo alegrar un cumpleaños triste.",
  ["Act_E1_3C_MaxRoom_Cushion_Look01_Max_010"] = "Es cursi, pero me hace sonreír pensar en el día en el que mamá y yo lo cosimos juntas.",
  ["Act_E1_3C_MaxRoom_DVD_Look01_Max_010"] = "Algún día organizaré mi colección de pelis... Algún día tendré una tele de alta definición.",
  ["Act_E1_3C_MaxRoom_DanaNote_Look01_Max_010"] = "Parece que Dana me dejó una notita…",
  ["Act_E1_3C_MaxRoom_Guitar_Look01_Max_010"] = "Es una guitarra muy bonita. Debo tocarla más.",
  ["Act_E1_3C_MaxRoom_Hifi_Look01_Max_010"] = "Debería ir a la tienda de segunda mano y comprar algunos vinilos de un dólar... ¿Es demasiado hipster? No me importa. La música me inspira, y mi fotografía...",
  ["Act_E1_3C_MaxRoom_InstantFilm_Look01_Max_010"] = "Las películas instantáneas son carísimas y difíciles de encontrar. Pero no puedo evitarlo, soy analógica, no digital.",
  ["Act_E1_3C_MaxRoom_Laptop_Look01_Max_010"] = "Mi vieja computadora... debería cambiarla.",
  ["Act_E1_3C_MaxRoom_MaxChloePhoto_Look01_Max_010"] = "Max y Chloe: mejores amigas para siempre. ¿Quién dice eso hoy en día? Voy a tener que llamar a Chloe en algún momento y averiguar lo que va a decir. Cuanto más tiempo espere, peor será. Idiota.",
  ["Act_E1_3C_MaxRoom_MaxClothing_Look01_Max_010"] = "No es el vestuario de una princesa, pero me importa un carajo. Me gusta mi vestuario.",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact01_Max_010"] = "Luzco tan patética.",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact02_Max_010"] = "Daniel tiene mucho talento. Espero que nadie lo odie solo porque soy yo.",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact03_Max_010"] = "Soy tan adicta a este sitio... Mira estas bellezas de época...",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Interact04_Max_010"] = "Warren me hace reír. Es agradable sentir que ya hice un amigo de verdad aquí.",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Look01_Max_010"] = "Ahí está mi pobre computadora rogándome que la encienda.",
  ["Act_E1_3C_MaxRoom_MaxLaptop_Look02_Max_010"] = "Mejor me aseguro de que todo sigue ahí... Creo que Warren se olvidó de ocultar la carpeta Fiestas sensuales... No la abriré sin importar la tentación. Tengo dignidad.",
  ["Act_E1_3C_MaxRoom_MaxRoomDoor_Interact01_Max_010"] = "Tengo que tomar una memoria USB de mi escritorio antes de ver a Warren.",
  ["Act_E1_3C_MaxRoom_Mirror_Look01_Max_010"] = "No puedo creer que tengo 18 años. ¿Me veo mayor? Solo más estresada.",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_010"] = "Esa es la única foto turística que dejé que me tomaran en la Aguja Espacial...",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_020"] = "Fue un buen partido de hockey, una gran pelea.",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_030"] = "Me encanta esta foto que tomé de mamá...",
  ["Act_E1_3C_MaxRoom_PhotoPanel_Look01_Max_040"] = "Vaya, Kristen y Fernando estaban tan borrachos en el Fremont Troll...",
  ["Act_E1_3C_MaxRoom_PhotoWall_Look01_Max_010"] = "\"La pared conmemorativa de fotos de Max Caulfield\".",
  ["Act_E1_3C_MaxRoom_Plant_Interact01_Max_010"] = "Estás sedienta. Soy la peor madre soltera. Toma, bebe...",
  ["Act_E1_3C_MaxRoom_Plant_Look01_Max_010"] = "No te he olvidado, pequeña Lisa. Por ahora.",
  ["Act_E1_3C_MaxRoom_PostCard01_Look01_Max_010"] = "No me puedo creer que ahora tenga 18 años. Tengo suerte de que mis padres me hayan permitido seguir haciendo fotos.",
  ["Act_E1_3C_MaxRoom_Poster07_Look01_Max_010"] = "Me encanta ese viejo póster de rave. Es tan primitivo.",
  ["Act_E1_3C_MaxRoom_Poster08_Look01_Max_010"] = "¿Man Ray las llamaría selfis?",
  ["Act_E1_3C_MaxRoom_Scarf_Look01_Max_010"] = "Echaré de menos ir a los juegos con mi papá. ¡Vamos, Thunderbirds!",
  ["Act_E1_3C_MaxRoom_TeddyBear_Look01_Max_010"] = "A la vista, capitán. Al menos sé que me apoyas. Cuando me tragué tu ojo y mis papás me llevaron a la sala de emergencias, sabía que estábamos unidos para siempre...",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_010"] = "Hogar dulce hogar. Mi capullo favorito...",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_020"] = "Amo a mi espacio, pero echo de menos a mis amigos y a mi familia en Seattle...",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_030"] = "Me gustaría poder cerrar la puerta y nunca irme, pero mejor le llevo la memoria USB a Warren. Tengo que cuidar al único amigo que tengo aquí...",
  ["Act_E1_3C_MaxRoom_VoiceOver_Max_040"] = "Fantástico. Ahora tengo que buscar la memoria USB en la habitación de Dana.",
  ["Act_E1_3C_MaxRoom_WarrenNote_Look01_Max_010"] = "Warren incluso me dejó un pequeño mensaje en la memoria USB. Es tan bobo.",
  ["Act_E1_3C_MaxRoom_Window_Look01_Max_010"] = "Si no miro por un visor, miro por una ventana... Siempre mirando.",
  ["Act_E1_3C_VicRoom_ClubSticker02_Look01_Max_010"] = "Sí, lo entendí: \"Entra al club Vortex\". No.",
  ["Act_E1_3C_VicRoom_GalleryLetter_Look01_Max_010"] = "Ay. Al menos ella publica sus fotografías. No como yo.",
  ["Act_E1_3C_VicRoom_Gazette_Look01_Max_010"] = "Apuesto que Victoria puso a Juliet en su lista negra después de este artículo...",
  ["Act_E1_3C_VicRoom_JeffersonBook_Look01_Max_010"] = "Victoria es una verdadera fanática de Jefferson...",
  ["Act_E1_3C_VicRoom_Jewelry_Look01_Max_010"] = "Bueno, si llegara a usar joyas caras, de seguro usaría esto.",
  ["Act_E1_3C_VicRoom_MPAVictoria_Look01_Max_010"] = "¿Victoria odia tanto a Rachel Amber? Qué insegura...",
  ["Act_E1_3C_VicRoom_Mail_Look01_Max_010"] = "Ni siquiera es papel reciclado. Victoria no está haciendo su parte para \"salvar a la Tierra\"... Pero esto también es por una buena causa.",
  ["Act_E1_3C_VicRoom_Mail_Take_Max_010"] = "Espero que convenza a Juliet de que Dana es inocente...",
  ["Act_E1_3C_VicRoom_Photos_Interact01_Max_010"] = "Hagamos un Tetris de fotos y dejemos un mensaje para Victoria. Movemos esta aquí... y esta otra allí... Mmm... Emerge un patrón...",
  ["Act_E1_3C_VicRoom_Photos_Look01_Max_010"] = "Hablando de selfis...",
  ["Act_E1_3C_VicRoom_Photos_Look02_Max_010"] = "Es malo de mi parte, pero ella se lo merece.",
  ["Act_E1_3C_VicRoom_Pictures_Look01_Max_010"] = "Esta serie debería llamarse \"Distante\". Fría y sin alma, como Victoria.",
  ["Act_E1_3C_VicRoom_PlasmaTV_Look01_Max_010"] = "Lindo plasma. Quizás podría escabullirme y mirar \"Final Fantasy: El espíritu en nosotros\". No me importa lo que digan, es una de las mejores películas de ciencia ficción.",
  ["Act_E1_3C_VicRoom_Poster06_Look01_Max_010"] = "Vaya, no sabía que The Chase Space era de los padres de Victoria. Estoy impresionada.",
  ["Act_E1_3C_VicRoom_Tablet_Interact01_Max_010"] = "¿Le van a dar una impresora 3D para su habitación? Quizás sí me uno a su pandilla…",
  ["Act_E1_3C_VicRoom_Tablet_Look01_Max_010"] = "No, oficial, no estoy espiando; solo admiro la tecnología de vanguardia de Victoria.",
  ["Act_E1_3C_VicRoom_VicPhotoStuff_Look01_Max_010"] = "¿Realmente tiene una cámara clásica de formato medio con ese increíble objetivo fijo? Te odio, Victoria.",
  ["Act_E1_3C_VicRoom_VictoriaClothing_Look01_Max_010"] = "Dior, Givenchy... Podrías pagar mi educación con ese vestuario.",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact01_Max_010"] = "¡Ah! Eso me da miedo. El siguiente.",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact02_Max_010"] = "Ah, muy bien, Victoria. ¿Y quién decía que soy una hipster?",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact03_Max_010"] = "Admito que Victoria estuvo bien al no publicar mi foto... Y al realizar esta toma, también.",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Interact04_Max_010"] = "¡Eureka! Este es el correo que le tengo que mostrar a Juliet. Tengo que imprimirlo rápido y largarme de aquí...",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Look01_Max_010"] = "Sí, Victoria tiene la mejor computadora con pantalla de Retina. Déjame ver si publicó mi foto...",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Look02_Max_010"] = "Una vez que imprima este correo, habré terminado aquí.",
  ["Act_E1_3C_VicRoom_VictoriaLaptop_Look03_Max_010"] = "Bien, Max, estás lista para ir. Ahora saca tu trasero ninja de aquí.",
  ["Act_E1_3C_VicRoom_VictoriaShoes_Look01_Max_010"] = "Estas botas están hechas para las pasarelas...",
  ["Act_E1_3C_VicRoom_VoiceOver01_Max_010"] = "Oh, no, esto está tan mal... Mejor encuentro evidencia rápido.",
  ["Act_E1_3C_VicRoom_VoiceOver01_Max_020"] = "Recuerda, no eres una criminal, eres una ninja. Vamos.",
  ["Act_E1_3C_VicRoom_VoiceOver01_Max_030"] = "Me siento terrible haciendo esto... pero podría rebobinar si hiciera falta...",
  ["Act_E1_3C_VicRoom_VoiceOver02_Max_010"] = "Ahora solo necesito imprimir la evidencia...",
  ["Act_E1_3C_VicRoom_VoiceOver03_Max_010"] = "Max, toma la hoja de la impresora y lárgate de aquí para siempre.",
  ["Act_E1_3C_VicRoom_VoiceOver04_Max_005"] = "Deja de distraerte, Max. Tienes la hoja. ¡Vete de aquí!",
  ["Act_E1_3C_VicRoom_VoiceOver04_Max_010"] = "He terminado aquí. Y no haré esto nunca más.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_001"] = "Oh, sí, Max. Encerré a Dana en la habitación porque estamos bien.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_003"] = "¿Qué no hizo? Dana se estuvo enviando mensajes sexuales con mi novio.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_010"] = "Gracias... Encerré a Dana porque se estaba enviando mensajes sexuales con Zach, mi novio. Increíble.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_013"] = "Victoria Chase. La conoces.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_015"] = "Las amigas no envían mensajes sexuales a los novios de sus mejores amigas...",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_016"] = "Eh... ¿por qué te importa? ¿Por qué me estás preguntando en primer lugar? Nunca hablas, vives distraída con tu cámara.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_020"] = "¿Cuál es mi apellido?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_024"] = "Según Victoria, Dana haría lo que fuera por salir con un mariscal de campo.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_027"] = "Ella vio el mensaje. Y Zachary no responde su teléfono. Una vez que lo admita, Dana se puede ir. Derecho al infierno.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_030"] = "Me siento halagada. Pensé que ni sabías mi nombre.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_033"] = "Eso fue triste. Gracias por tu interés, \"Max Caulfield\". Por cierto, Juliet Watson.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Juliet_037"] = "Me siento halagada. Pensé que ni sabías mi nombre.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_002"] = "¿Qué hizo?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_004"] = "Es tu amiga.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_011"] = "¿Cómo lo sabes?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_014"] = "Hola, Juliet. ¿Todo bien?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_017"] = "Ay. ¿Cómo te enteraste?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_018"] = "No, probablemente no... ¿Cómo te enteraste?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_019"] = "Por eso estoy hablando contigo ahora.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_022"] = "Uy. Claro que sí.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_023"] = "¿Dana haría eso?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_025"] = "Podrías decir eso... Pero, ¿por qué Dana iría tras tu novio?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_028"] = "Juliet Pats... Juliet Patson.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_029"] = "Juliet Watson. ¡Puf!",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_031"] = "Claro que sí. Solo porque no hable no significa que no me importe. ¿Cómo te enteraste de lo que pasaba entre ellos?",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_034"] = "Juliet... Juliet... Olson.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_035"] = "Uy. Juliet... Mason.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_036"] = "¿Según Victoria? Ay...",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase01_Max_038"] = "Juliet Watson, ¡sé buena!",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase02_Juliet_002"] = "Déjame en paz, Max. Despabílate.",
  ["Cue_E1_3C_Corridor_CHJuliet_Phase02_Juliet_004"] = "No la dejaré salir hasta que me diga la verdad.",
  ["Cue_E1_3C_Corridor_CourtneyAndTaylorTowel_Courtney_020"] = "Victoria se va a enojar porque tardamos tanto...",
  ["Cue_E1_3C_Corridor_CourtneyAndTaylorTowel_Taylor_010"] = "¡Apúrate, Courtney!",
  ["Cue_E1_3C_Corridor_DanaYells_Dana_010"] = "¡Max, te juro que no hice NADA! ¡Pero apuesto que Victoria sí! Sé que la evidencia está en su habitación.",
  ["Cue_E1_3C_Corridor_DanaYells_Dana_020"] = "¡Déjame salir, Juliet! ¡Esto es tan estúpido!",
  ["Cue_E1_3C_Corridor_DanaYells_Dana_030"] = "¡Eres ridícula!",
  ["Cue_E1_3C_Corridor_JulietLocksDoor_Dana_020"] = "¡Déjame salir, Juliet! ¡Esto es tan estúpido! ¡Eres ridícula!",
  ["Cue_E1_3C_Corridor_JulietLocksDoor_Juliet_010"] = "No puedes salir ahora, Dana. ¡O me dices la verdad o te pudres allí!",
  ["Cue_E1_3C_Corridor_JulietLocksDoor_Max_030"] = "Bienvenida a \"Las verdaderas reinas del drama de Blackwell\"...",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_020"] = "Si no me dejas salir, voy a gritar.",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_060"] = "Lo harás. Así lo espero. ¿Realmente crees que me metería con Zachary?",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_090"] = "Y me lavas la ropa.",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Dana_120"] = "¡Me liberaste! Gracias. La memoria USB de Warren está en mi escritorio.",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_010"] = "Responde, cobarde...",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_040"] = "Por supuesto.",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_050"] = "Soy una idiota. Lo siento, Dana.",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_070"] = "No. Pero me pongo celosa como una estúpida.",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_080"] = "Te debo una cena. ¿Todavía me quieres?",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_100"] = "Gracias, Max. Eres la ninja de Blackwell.",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Juliet_110"] = "Veamos qué tiene para decir Zach sobre Victoria...",
  ["Cue_E1_3C_Corridor_JulietUnlocksDana_Max_030"] = "Juliet, lee esto.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_014"] = "De verdad, gracias otra vez. No puedo creer que Juliet me haya encerrado en mi propia habitación. Muy maduro.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_016"] = "Solo porque están en el club Vortex no significa que sean las mejores amigas. Yo soy miembro, y Victoria me da miedo.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_018"] = "Zachary también debería preocuparse. Como si fuera a dejar que ese deportista narcisista me tocara. Pero apuesto que Victoria lo hubiera hecho varias veces. O lo ha hecho...",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_020"] = "¿Qué? ¿Quién te dijo que estaba embarazada?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_021"] = "Max, eres inteligente por ser tan solitaria. Aunque es obvio que a Warren le gusta estar contigo...",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_024"] = "¿Viste los archivos que tiene en su memoria USB? Un montón de mierda loca. Películas que nunca escuché nombrar. ¿Y en una carpeta especial llamada \"Max\"?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_025"] = "Oh, nada. Cuando abriste la memoria USB, ¿no viste una carpeta especial llamada \"Max\"?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_027"] = "¿Te estás sonrojando? ¡Ja! Ve y toma la memoria USB cuando quieras...",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_029"] = "Es como un maldito reality show aquí... ¿Te puedo contar un secreto, Max?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_032"] = "Sí. Yo tampoco, pero lo estuve. Como sea.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_033"] = "Estuve... embarazada. Estuve.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_035"] = "¿Padre ausente? Podrás verlo en la línea de 40 yardas este viernes. Y no es Zachary.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Dana_045"] = "Me gusta tu espíritu, Max. Como sea, mejor te llevas la memoria USB, así Warren tiene una excusa para molestarte...",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_015"] = "Victoria no es agradable. No lo entiendo. Tiene todo. Y hace esa broma a una amiga.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_017"] = "La pobre Juliet sí que se enfurece. Espero que no mate a Victoria...",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_019"] = "Dana, no quiero ser entrometida, pero oí un rumor sobre ti.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_022"] = "Es un buen tipo. Es un sabelotodo, como yo.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_023"] = "¿Qué quieres decir?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_026"] = "Sí, está bien. Te entiendo.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_028"] = "Nadie importante. Se comportaron como si fuera mierda. Solo quería saber...",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_030"] = "Por supuesto.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_031"] = "Estás embarazada. Lo siento, no debería decir nada.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_034"] = "Oh. ¿Y qué pasó con...?",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_043"] = "Siento entrometerme. No me incumbe. Y no voy a ir al juego el viernes. No tengo mucho espíritu escolar.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_044"] = "¿Quién, entonces? No me tienes que decir. De hecho, mejor no me lo digas.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase01_Max_046"] = "Hola, Dana.",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase02_Dana_001"] = "Ahora me siento demasiado cansada para irme...",
  ["Cue_E1_3C_DanaRoom_CHDana_Phase02_Dana_006"] = "Se terminaron los rumores para ti, Max. Ve.",
  ["Cue_E1_3C_DanaRoom_DanaSad_Dana_010"] = "Dije que te vayas.",
  ["Cue_E1_3C_DanaRoom_DanaSad_Dana_020"] = "Max, suficiente.",
  ["Cue_E1_3C_DanaRoom_DanaSad_Dana_030"] = "Eres densa. Ve.",
  ["Cue_E1_3C_DanaRoom_PregnancyTest_Dana_010"] = "¿Eh, Max? ¡Eso es mío, gracias!",
  ["Cue_E1_3C_DanaRoom_PregnancyTest_Dana_020"] = "No estás ayudando, solo eres entrometida. Mejor te vas...",
  ["Cue_E1_3C_MaxRoom_BedLie_Max_010"] = "Ah, se siente tan bien solo relajarse. El día de hoy ha sido tan extraño y parece que nunca termina... Quizás me despierte ahora y me dé cuenta de que lo había estado soñando... O, como dijo Poe, \"Un sueño en un sueño\"...",
  ["Act_E1_3D_CampusPark_Bike_Interact01_Max_010"] = "No es una mala toma.",
  ["Act_E1_3D_CampusPark_Bike_Look01_Max_010"] = "¿Quién envolvería una bicicleta en papel higiénico?",
  ["Act_E1_3D_CampusPark_CHJuliet_Look01_Max_010"] = "Juliet todavía está triste por Zach y Victoria. No la culpo.",
  ["Act_E1_3D_CampusPark_CHWarren_Look01_Max_010"] = "Y allí está Warren... ¿De verdad se compró un auto usado?",
  ["Act_E1_3D_CampusPark_ChloeCar_Look01_Max_010"] = "Esto realmente me exaspera. Tan arrogante. \"Perdón, discapacitados, mi camión necesita estos dos lugares más que ustedes\". Desgraciado.",
  ["Act_E1_3D_CampusPark_DinerSign_Look01_Max_010"] = "Mejor voy pronto para ver si Joyce sigue allí... y comerme una hamburguesa.",
  ["Act_E1_3D_CampusPark_DirtyWindow_Interact01_Max_010"] = "No es una ventana sucia a menos que alguien escriba \"Límpiame\" en el vidrio...",
  ["Act_E1_3D_CampusPark_DirtyWindow_Look01_Max_010"] = "Esa capa de polvo ruega que escriba algo.",
  ["Act_E1_3D_CampusPark_DirtyWindow_Look02_Max_010"] = "Listo. Ahora oficialmente es una ventana sucia.",
  ["Act_E1_3D_CampusPark_DirtyWindow_Photo01_Max_010"] = "Podría usar esta foto para una serie sobre los estacionamientos de Arcadia Bay.",
  ["Act_E1_3D_CampusPark_Dog_Look01_Max_010"] = "Ese perro se ve muy tranquilo durmiendo pero si me acerco... ¡Cujo!",
  ["Act_E1_3D_CampusPark_GoingCampus_Interact01_Max_010"] = "Ya que estoy aquí, mejor voy a hablar con Warren.",
  ["Act_E1_3D_CampusPark_GoingTown_Interact01_Max_010"] = "No hay forma de ir caminando a la ciudad desde aquí. Además, necesito ver a Warren.",
  ["Act_E1_3D_CampusPark_Graffiti01_Look01_Max_010"] = "Por suerte no tengo un auto. Por ahora.",
  ["Act_E1_3D_CampusPark_Graffiti02_Look01_Max_010"] = "Ahora bien, ¿quién escribe algo así y por qué?",
  ["Act_E1_3D_CampusPark_JeffersonCar_Look01_Max_010"] = "Jefferson debe mantener esta belleza bien guardada. El arte paga.",
  ["Act_E1_3D_CampusPark_MPA01_Look01_Max_010"] = "Toda la ciudad se está convirtiendo en un cartel gigante de \"Persona desaparecida\".",
  ["Act_E1_3D_CampusPark_MPA01_Look02_Max_010"] = "Qué mal que los carteles van a terminar ignorados y en la basura.",
  ["Act_E1_3D_CampusPark_MPA01_Look03_Max_010"] = "Al menos Rachel Amber tiene a alguien que se preocupa por ella...",
  ["Act_E1_3D_CampusPark_MPAPile_Look01_Max_010"] = "Mierda, alguien está realmente empeñado en poner esos carteles.",
  ["Act_E1_3D_CampusPark_OldVan_Look01_Max_010"] = "Algo tan sucio por fuera debe ser inmundo por dentro...",
  ["Act_E1_3D_CampusPark_Poster01_Look01_Max_010"] = "¿Un nuevo sistema de vigilancia? Así es como empieza...",
  ["Act_E1_3D_CampusPark_RetardedSign_Look01_Max_010"] = "¿Cuánto tiempo pasará hasta que Samuel deba volver pintarlo?",
  ["Act_E1_3D_CampusPark_VoiceOver_Max_010"] = "Me alegro de haber intervenido. No tolero que se metan con las personas.",
  ["Act_E1_3D_CampusPark_VoiceOver_Max_030"] = "Debería haber hecho algo. ¡El tipo era un imbécil!",
  ["Act_E1_3D_CampusPark_VoiceOver_Max_050"] = "Tengo que encontrar a Warren y devolverle su memoria USB.",
  ["Act_E1_3D_CampusPark_WarrenCar_Look01_Max_010"] = "Mira a Warren y su máquina del tiempo. Qué valiente.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_001"] = "Ay... Hola, Max. Lo siento, todavía estoy destruida.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_005"] = "Mejor ahora que más tarde. Esa idiota de Victoria ya no se reirá de mí a mis espaldas.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_007"] = "El Sr. Héroe del Fútbol rudo es un cagón. Dijo que le envió un mensaje sexual a Victoria en broma. Ja ja. Creo que Warren busca tu atención...",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_009"] = "Sí, estoy segura de que todos estaremos de fiesta luego con Zach y Victoria... y el club Vortex...",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Juliet_011"] = "Nos vemos, Max.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_003"] = "Siento que te enteraras lo de Zachary de esa manera... o de cualquier manera.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_004"] = "Entonces, no te molestaré... Debo ir a ver a Warren antes de que se derrita. Nos vemos.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_006"] = "¿Ya has hablado con Zach?",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_008"] = "En general, lo hace... Sé fuerte, Juliet.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_010"] = "Eh, sí, claro.",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase01_Max_012"] = "Hola, Juliet. ¿Qué haces?",
  ["Cue_E1_3D_CampusPark_CHJuliet_Phase02_Juliet_001"] = "No tengo ganas de hablar ahora, Max.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_003"] = "Solo una mariposa.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_004"] = "¿De qué estás hablando?",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_005"] = "Le dije la verdad. Un estudiante tenía un arma.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_009"] = "¿Y qué hizo? ¿Te dio un severo sermón?",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_010"] = "No soy nueva. He vivido aquí durante años.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_011"] = "No necesito tu respeto...",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_015"] = "Debes hablar con alguien, Nathan...",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_016"] = "No debes preocuparte por mí... Preocúpate por ti.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_017"] = "En realidad, tengo una buena idea de quién eres...",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_019"] = "Da un paso hacia atrás, Nathan Prescott.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Max_020"] = "Podría llamar a la policía.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_001"] = "Será mejor que me digas qué le dijiste al director. Ahora.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_002"] = "Será mejor que me digas qué viste. ¡Ahora!",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_006"] = "No, tú le dijiste que YO tenía un arma. Por eso me arrastró a su oficina.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_007"] = "Sé que eres nueva aquí, pero no te hagas la estúpida conmigo.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_008"] = "Mentirosa de mierda. Te respetaría más si me dijeras la verdad.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_012"] = "Nadie. Nadie me da un sermón. Aunque todos lo intentan... Entonces, inténtalo...",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_013"] = "Entonces deberías saber que los Prescott son dueños de este basurero.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_014"] = "No tienes idea. No tienes idea de quién soy ni de lo que puedo hacer.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_018"] = "¡No me analices! Les pago a personas por hacer eso. Preocúpate por ti, Max Caulfield.",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_030"] = "¡Respóndeme, puta!",
  ["Cue_E1_3D_CampusPark_CHNathan_Phase01_Nathan_031"] = "¿Algo para decir, eh?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_002"] = "No te preocupes, Warren. Tomé una dulce foto de Victoria que no puedo esperar para compartir...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_004"] = "Supongo que se lo merece por todas la mierda que le hace a la gente de aquí.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_005"] = "No quiero hablar de eso.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_007"] = "No tentaría a la suerte, Warren. No estoy de humor hoy.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_009"] = "¿En serio? Ojalá lo hubiera sabido...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_011"] = "Si lo hubiera sabido... De todos modos, Victoria borró mi foto. Así que el drama terminó bien.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_014"] = "¿Puedes dibujar? Creía que adorabas la ciencia, no el arte.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_016"] = "Intenso. Así que debes usar una computadora para dibujar.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_018"] = "Eso no suena mal. Te aviso.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_019"] = "¿Daniel ya lo publicó? Eso fue lindo...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_021"] = "No te pongas celosa. Estoy seguro de que te invitará pronto.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_023"] = "Es la compañía que tengo, Warren.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_025"] = "No, he estado muy ocupada con las clases... y con la vida.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_026"] = "O una semana. Miré todos los títulos, reina del drama.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_027"] = "Sí, gracias. Tenías unas buenas cosas allí, de \"Akira\" a \"La dimensión desconocida\". Lo que parece pertinente al día de hoy...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_028"] = "Eso suena mejor que \"ladrón\".",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_032"] = "De ninguna manera miraré eso. Mi mente es lo suficientemente retorcida...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_033"] = "Entonces eres sensible...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_034"] = "La vi. Me perturbaron más esas películas emo de vampiros.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_038"] = "No, me impresionó que tuvieras \"Faster pussycat. Kill! Kill!\".",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_039"] = "Para nada. Ser sensible es algo bueno, a menos que te dejes controlar. Tienes un gusto sofisticado y una mente rápida.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_040"] = "La chica correcta también los tendrá...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_041"] = "Que patearían tu trasero sensible.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_045"] = "No quiero hablar de eso. Es un día un poco loco para mí. Es decir, de verdad creo que me estoy volviendo loca...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_046"] = "Necesito hablar con alguien... solo para sacármelo de la cabeza...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_049"] = "¿Cómo?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Max_051"] = "Ay, Dios. Necesitas a una mujer sensible que te patee el trasero.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_001"] = "Dios, vi que Victoria no quitó esa foto tuya de Facebook... Es una gran puta.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_003"] = "¡Oh, punto para el Equipo Max! Será tan de karma ver su cara de payaso en la Internet...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_006"] = "Cielos, eres la Señorita Sensible hoy...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_008"] = "Seguro. Oí que a Victoria le llenaron la cara de pintura... Pagaría por ver una foto de eso...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_010"] = "Podrías haber iniciado un fondo Kickstarter con esa sola imagen.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_012"] = "Por cierto, vi en línea el bosquejo que Daniel hizo de ti... No está mal, pero yo podría hacerlo mejor.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_015"] = "El arte ES una ciencia. La música es matemática, etc., etc. Stephen Hawking ganaría contra Picasso cualquier día.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_017"] = "Por supuesto. Me encantaría retorcer una de tus selfis con algunas gráficas estupendas...",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_020"] = "¡Felicitaciones! Eres parte de su pandilla de retratos en línea.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_022"] = "Qué ingeniosa, Max.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_024"] = "Entonces, ¿viste las pelis del USB?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_029"] = "Mierda, nena, la tuviste como un año.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_030"] = "Me considero conocedor... pirata pop cultural.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_031"] = "Ja, ja. Asegúrate de ver \"Holocausto caníbal\".",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_035"] = "Auch... Suena horrible la forma en que lo dijiste.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_036"] = "Me reí muchísimo.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_037"] = "¿Un estudiante sensible no puede también adorar a los vampiros sensibles?",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_042"] = "Russ Meyer era un genio del blanco y negro. Además, tetonas sensuales.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_043"] = "Si tuviera suerte... Hablando de sofisticado y rápido, deberíamos ir a ver una peli con mi nave esta semana... Pero pareces distraída.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_044"] = "Gracias por notarlo, Max.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_047"] = "El Dr. Warren Graham está aquí. Ni siquiera te recetaré medicamentos... Cuéntame todo.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_048"] = "Puede que sea molesto, pero... Soy bueno para escuchar.",
  ["Cue_E1_3D_CampusPark_CHWarren_Phase01_Warren_050"] = "Sensible por lo general significa: \"No tendré sexo contigo\".",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_020"] = "Aquí está tu memoria USB. Gracias.",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_050"] = "Estupendo. Muy de la vieja escuela.",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_070"] = "Estás en el tiempo equivocado, Warren.",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_080"] = "Pero, bueno, yo también...",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Max_100"] = "Ha sido un maldito extraño día.",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_010"] = "¿Qué dices, Max? ¿Cómo estás?",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_030"] = "No hay problema.",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_040"] = "Mira mis nuevas ruedas...",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_060"] = "1978, para ser exactos. Podemos ir al autocine. Hay uno en Newberg, a solo 60 millas de aquí.",
  ["Cue_E1_3D_CampusPark_IntroDialWarren_Warren_090"] = "¿Estás bien?",
  ["Cue_E1_3D_CampusPark_JulietLoop_Juliet_010"] = "No lo entiendo... ¿cómo pudieron Zach y Victoria hacerme eso?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_010"] = "En serio, Warren, esto es entre tú y yo, no las redes sociales.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_030"] = "Tuve una experiencia muy rara en la clase del Sr. Jefferson hoy... Quiero decir, me cambió la vida.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_040"] = "¿Alguna vez tuviste un sueño tan real que parecía una película?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Max_070"] = "Soy una de sus estudiantes.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_060"] = "Max Caulfield, ¿no?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_065"] = "Eres una de las fanáticas fotográficas de Jefferson...",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_080"] = "Qué mierda me importa. Sé que te gusta tomar fotografías, en especial cuando te estás escondiendo en los baños.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_090"] = "Será mejor que me digas qué viste. ¡Ahora!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_100"] = "Escucha, puta, Max, o sea cual sea tu maldito nombre, sé que le dijiste algunas cosas importantes al director.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Nathan_110"] = "Será mejor que me digas qué le dijiste al director. Ahora.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Warren_020"] = "No me insultes. Max, vamos.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part01_Warren_050"] = "Ay, no.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Chloe_070"] = "¿Max?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Chloe_120"] = "¡Entra, Max!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Chloe_140"] = "Más tarde, psicópata de mierda. Trágate el humo.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_040"] = "¡Ey, déjalo en paz!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_050"] = "¡Basta! ¡Ahora!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_080"] = "¿Chloe?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Max_100"] = "¡Warren!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_010"] = "Ay, mierda, ¿me estás diciendo lo que tengo que hacer?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_020"] = "Hazlo. Los Prescott son dueños de la puta policía.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_060"] = "Nadie me dice lo que tengo que hacer. Ni mis padres, ni el director, ni esa puta del baño.",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_090"] = "De ningún modo. ¿Tú de nuevo?",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Nathan_130"] = "¡Traigan sus traseros aquí ahora! ¡Ni intenten escaparse! ¡Nadie se mete conmigo! ¡NADIE!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Warren_030"] = "¡Aléjate de ella!",
  ["Cue_E1_3D_CampusPark_NathanArrives_Part02_Warren_110"] = "¡Vete, vete! Yo me encargo.",
  ["Cue_E1_3D_CampusPark_WarrenLoop_Warren_010"] = "¡Ey, Max! ¡Mira esto!",
  ["Cue_E1_3D_CampusPark_WarrenLoop_Warren_020"] = "¡Max! ¡Trae tu trasero aquí!",
  ["Cue_E1_3D_CampusPark_WarrenLoop_Warren_030"] = "¡Ven aquí! ¿Por favor?",
  ["Cue_E1_4A_CHouseFront_HouseReveal01_Chloe_010"] = "Vamos, entra, no seas tímida.",
  ["Cue_E1_4A_CHouseFront_HouseReveal01_Chloe_030"] = "Hogar, maldito hogar.",
  ["Cue_E1_4A_CHouseFront_HouseReveal01_Max_020"] = "La casa aún luce... linda.",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_020"] = "Vaya, no escuchaba eso hace un tiempo...",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_040"] = "Mi padrastúpido tiene muchas herramientas. Quizás la puedes reparar en mi casa...",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_060"] = "¡Alerta de nerds! Mi padrastro tiene un garage completamente equipado. Y a él, en realidad, le falta un tornillo.",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_070"] = "Bienvenida a casa, Max.",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Chloe_080"] = "Ajústate el cinturón.",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Max_010"] = "Rota. Mierda, ¿de verdura?",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Max_030"] = "No todo cambia. Excepto que mi cámara oficialmente pasó a mejor vida.",
  ["Cue_E1_4A_ChloeCar_BrokenCamera_Max_050"] = "Necesito herramientas específicas muy pequeñas.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_001"] = "¿Qué quería ese trastornado contigo?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_004"] = "Y un idiota. Tu amigo realmente te defendió...",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_005"] = "Es solo otro idiota de Arcadia... Tu amigo recibió una paliza por ti.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_007"] = "No eres la única en deuda y ya estás causando problemas.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_009"] = "¿Entonces Seattle fue malísimo?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_012"] = "Sí, debe ser difícil regresar a un pueblo rústico como Arcadia otra vez...",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_013"] = "Pensé que encajarías rápidamente con los hipsters artísticos...",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_016"] = "Al menos, sigues siendo una sabelotodo.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_018"] = "Por favor... Volviste por la Academia Blackwell.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_021"] = "Entonces, regresaste a Arcadia por un profesor... no por tu mejor amiga.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_022"] = "Los que no pueden triunfar, enseñan. Me alegra que hayas encontrado una buena razón para regresar.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_024"] = "No. No tuviste problema en esperar cinco años sin una llamada ni un mensaje de texto.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_028"] = "Supongo que esos cambios incluyeron echarme de tu vida.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_029"] = "Ay, por favor. Seguro que tu teléfono y tu laptop estaban congelados en el tiempo.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_030"] = "¿Cómo lo sabes? Ni siquiera estabas aquí.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_032"] = "Mentira. Creíste que te juntarías con todos esos idiotas del arte en Seattle. Pero no fue así.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_035"] = "Estás en Blackwell hace casi un mes y no me lo habías dicho. ¿Hace falta decir más?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Chloe_037"] = "Apuesto a que no usas estas malas excusas con el Sr. Jefferson... No las uses conmigo, Max.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_002"] = "No tengo idea. Sé que es un Prescott.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_003"] = "Espero que nada después de hoy. Entonces, ¿cómo conoces a Nathan?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_006"] = "¿Warren? Sí, le debo mucho.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_008"] = "Pensé que este lugar sería tranquilo. Se siente tan extraño haber vuelto.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_010"] = "No, parecía una verdadera ciudad para artistas, grande y brillante. Fantástica para tomar fotografías.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_011"] = "Supongo. Era estupenda pero... Me sentía un poco sola, fuera de mi ámbito.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_014"] = "No tras verte a ti.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_015"] = "Claro. Luces como la portada de Chica Hipster punto com.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_017"] = "Para eso estoy aquí.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_019"] = "Por supuesto. Es uno de los mejores programas de fotografía del país... y está mi profesor favorito, Mark Jefferson.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_020"] = "Solo por Mark Jefferson. Era un fotógrafo bastante famoso en los noventa... Siempre me encantó su trabajo.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_023"] = "¿No crees que estoy feliz de verte?",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_025"] = "Dame un respiro. Estaba atravesando cambios... como tú.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_026"] = "Quería hacerlo. Estaba muy confundida por irme de Arcadia...",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_027"] = "Lo siento. Sé que fue difícil para ti cuando me fui.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_031"] = "No es así, Chloe.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_033"] = "No le ordené a mis padres que se mudaran específicamente para molestarte, Chloe.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_034"] = "Eres despiadada.",
  ["Cue_E1_4A_ChloeCar_CHChloe_TalkChloe_Max_036"] = "Solo quería acomodarme primero, no ser la tímida chica cliché. Claro que te hubiese contactado...",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_020"] = "\"¡Oh, y gracias, Chloe!\".",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_030"] = "Después de cinco años, sigues siendo Max Caulfield.",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_040"] = "No pongas esa cara de culpable. Al menos simula que te agrada verme.",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Chloe_070"] = "Sí, ha sido ese tipo de día.",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Max_010"] = "Vaya, Nathan Prescott tiene problemas. Y es peligroso... Este día nunca termina...",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Max_050"] = "De verdad me alegra verte...",
  ["Cue_E1_4A_ChloeCar_FirstReunion_Max_060"] = "Oh, y gracias, Chloe. Tiene todo el sentido que te haya visto hoy.",
  ["Act_E1_5A_BathRoom_Pills_Look01_Max_010"] = "Me pregunto si Chloe toma esas pastillas. Espero que esté bien...\n",
  ["Act_E1_5A_Bathroom_Cabinet_Interact01_Max_010"] = "Me gusta el nuevo color de pelo de Chloe. Es lo opuesto a la timidez... A mí.",
  ["Act_E1_5A_Bathroom_Dark_Look01_Max_010"] = "¡Vaya! Qué oscuro. No veo nada.",
  ["Act_E1_5A_Bathroom_Drawer01_Interact01_Max_010"] = "Espero que Chloe no esté tomando estas pastillas...",
  ["Act_E1_5A_Bathroom_MakeUpStuff_Look01_Max_010"] = "Definitivamente es el maquillaje de Joyce. Chloe no usaría productos animales.",
  ["Act_E1_5A_Bathroom_Scale_Interact01_Max_010"] = "Sin comentarios.",
  ["Act_E1_5A_Bathroom_Scale_Look01_Max_010"] = "Ya me pesé la semana pasada.",
  ["Act_E1_5A_Bathroom_Shower_Interact01_Max_010"] = "Está tan limpio que lo quiero probar. Pero necesito las herramientas de la cochera.",
  ["Act_E1_5A_Bathroom_Shower_Look01_Max_010"] = "Linda ducha... limpia.",
  ["Act_E1_5A_ChloeRoom_Bed_Interact01_Max_010"] = "Ya no soy una niña. ¡No puedo esconderme debajo de la cama! ¿Dónde más?",
  ["Act_E1_5A_ChloeRoom_BlueDrawer01_Interact01_Max_010"] = "La pasamos tan bien cuando los dibujamos.",
  ["Act_E1_5A_ChloeRoom_BlueDrawer01_Look01_Max_010"] = "Recuerdo este mueble. Nos pasamos todo el día pintándolo de azul. Chloe adoraba ese azul.",
  ["Act_E1_5A_ChloeRoom_Box_Interact01_Max_010"] = "Chloe tiene razón. Debería guardar esto.",
  ["Act_E1_5A_ChloeRoom_Box_Look01_Max_010"] = "Cajas viejas de cartón...",
  ["Act_E1_5A_ChloeRoom_BrokenGlobe_Look01_Max_010"] = "Bien hecho, Max. Podría arreglarlo si rebobino rápido...",
  ["Act_E1_5A_ChloeRoom_BrokenGlobe_Look02_Max_010"] = "Mierda, es demasiado tarde para rebobinar y arreglarlo.",
  ["Act_E1_5A_ChloeRoom_BrokenGlobe_Look03_Max_010"] = "Mierda, es demasiado tarde para rebobinar y arreglarlo. Necesito aprender qué puedo y qué no puedo hacer con este poder.",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look01_Max_010"] = "Es difícil de creer que Chloe era mi mejor amiga hace cinco años.",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look02_Max_010"] = "No ha cambiado tanto. Todavía puede ser mi mejor amiga...",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look03_Max_010"] = "Es lindo ver feliz a Chloe. Me alegra haber recibido un golpe por el equipo.",
  ["Act_E1_5A_ChloeRoom_CHChloe_Look04_Max_010"] = "Chloe parece enojadísima porque no asumí la culpa.",
  ["Act_E1_5A_ChloeRoom_Closet_Interact01_Max_010"] = "Cerrado con llave.",
  ["Act_E1_5A_ChloeRoom_Closet_Interact02_Max_010"] = "Esto no abre. Aunque seguro que no guarda su música ahí.",
  ["Act_E1_5A_ChloeRoom_Closet_Look01_Max_010"] = "Ay, ¡viejos recuerdos! ¡Nuestra \"supersecreta guarida en el armario\"!",
  ["Act_E1_5A_ChloeRoom_ClothDrawer01_Interact01_Max_010"] = "Chloe cambió su estilo por completo. Casi no la reconozco.",
  ["Act_E1_5A_ChloeRoom_ClothDrawer01_Look01_Max_010"] = "El padre de Chloe construyó esta cómoda.",
  ["Act_E1_5A_ChloeRoom_Desk_Interact01_Max_010"] = "Creo que esta porquería se tragó sus discos.",
  ["Act_E1_5A_ChloeRoom_Desk_Look01_Max_010"] = "¿Esto es un escritorio o un lugar de almacenamiento?",
  ["Act_E1_5A_ChloeRoom_Door_Interact01_Max_010"] = "Espero no tener que volver a enfrentarme a David.",
  ["Act_E1_5A_ChloeRoom_DuffleBag_Interact01_Max_010"] = "Y apesta como ropa sucia. ¡Asqueroso!",
  ["Act_E1_5A_ChloeRoom_DuffleBag_Look01_Max_010"] = "Parece una bolsa de ropa sucia.",
  ["Act_E1_5A_ChloeRoom_EmptyHiFi_Look01_Max_010"] = "Houston, tenemos energía. Pero necesitamos encontrar un disco para poner...",
  ["Act_E1_5A_ChloeRoom_FloorLamp_Look01_Max_010"] = "Esta lámpara es inestable. Se puede caer si la toco...",
  ["Act_E1_5A_ChloeRoom_HeightGauge_Look01_Max_010"] = "Chloe siempre fue más alta que yo. Hicimos que su padre llevara un registro de nuestra altura.",
  ["Act_E1_5A_ChloeRoom_Hifi_Look01_Max_010"] = "No va a encender si no tiene electricidad.",
  ["Act_E1_5A_ChloeRoom_Hifi_Look02_Max_010"] = "Veamos qué música le gusta a Chloe estos días.",
  ["Act_E1_5A_ChloeRoom_Hifi_Look03_Max_010"] = "No esperaba algo tan melancólico por parte de Chloe. ¿Quizás le recuerda a Rachel?",
  ["Act_E1_5A_ChloeRoom_Joint_Interact01_Max_010"] = "Puedes esconder un porro, pero no el olor... olvídalo.",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact01_Max_010"] = "Se ve muy feliz.",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact02_Max_010"] = "Se ve muy triste.",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact03_Max_010"] = "Se ve muy drogada.",
  ["Act_E1_5A_ChloeRoom_Laptop_Interact04_Max_010"] = "Estas fotos capturan la esencia de Chloe. Me preguntó quién las sacó.",
  ["Act_E1_5A_ChloeRoom_Laptop_Look01_Max_010"] = "Es una pena que no pueda transmitir música desde la computadora de Chloe. Pero me encanta lo extravagante y antigua que es... Incluso la cubrió con pegatinas punk porque a Chloe no le importa un carajo.",
  ["Act_E1_5A_ChloeRoom_Letter01_Look01_Max_010"] = "Rachel y Chloe eran muy unidas. Debe extrañarla.",
  ["Act_E1_5A_ChloeRoom_MPA_Look01_Max_010"] = "Así que fue Chloe la que imprimió esos volantes.",
  ["Act_E1_5A_ChloeRoom_MetalBox_Look01_Max_010"] = "Está bien, Chloe, una caja de metal debajo de la cama es lo mismo que un secreto.",
  ["Act_E1_5A_ChloeRoom_MetalBox_Look02_Max_010"] = "Ya no es una caja de metal secreta.",
  ["Act_E1_5A_ChloeRoom_Multisocket_Look01_Max_010"] = "Allí está el enchufe.",
  ["Act_E1_5A_ChloeRoom_Multisocket_Look02_Max_010"] = "Ahora tiene electricidad.",
  ["Act_E1_5A_ChloeRoom_Paper01_Look01_Max_010"] = "Mierda, Chloe de verdad necesita mucho dinero para salir de Arcadia...",
  ["Act_E1_5A_ChloeRoom_Picture01_Look01_Max_010"] = "¿Tres mil dólares para arreglar esa mierda? Chloe debe haber roto su chanchito...",
  ["Act_E1_5A_ChloeRoom_PostCard01_Look01_Max_010"] = "Esta postal es de Rachel Amber...",
  ["Act_E1_5A_ChloeRoom_Poster_Look01_Max_010"] = "No me gustan. Demasiado pretenciosos.",
  ["Act_E1_5A_ChloeRoom_ReportCard_Look01_Max_010"] = "Mierda, a Chloe la echaron de Blackwell hace dos años. Solía ser una excelente estudiante... cuando le importaba.",
  ["Act_E1_5A_ChloeRoom_RewindChoice_InterveneTakeBlame_Max_010"] = "Vaya, eso no salió bien. Si quiero mantener mi beca de Blackwell, no puedo mentir por nadie,|ni siquiera por Chloe. Tengo que pensar en mi propio futuro...",
  ["Act_E1_5A_ChloeRoom_RewindChoice_InterveneTakeBlame_Max_020"] = "Me siento mejor en cuanto a Chloe, pero ahora me va a vigilar este intento de guardia. Tal vez debería rebobinar y compensárselo a Chloe luego.",
  ["Act_E1_5A_ChloeRoom_RewindChoice_NotHidden_Max_010"] = "Eso fue terrible. David está furioso. Tal vez, pueda rebobinar y esconderme en el armario...",
  ["Act_E1_5A_ChloeRoom_RewindChoice_StayHiddenBlameChloe_Max_010"] = "David se comportó terrible con Chloe. ¿Y si yo hubiera intervenido?",
  ["Act_E1_5A_ChloeRoom_ShoeBox_Interact01_Max_010"] = "Mira eso... Chloe y su padre eran muy cercanos.",
  ["Act_E1_5A_ChloeRoom_ShoeBox_Look01_Max_010"] = "Me pregunto qué guarda Chloe aquí...",
  ["Act_E1_5A_ChloeRoom_ShoeBox_Look02_Max_010"] = "Chloe intenta actuar como si hubiera superado lo de su padre, pero no creo que pueda lograrlo...",
  ["Act_E1_5A_ChloeRoom_SuitCase_Look01_Max_010"] = "Nada más que basura en esta maleta.",
  ["Act_E1_5A_ChloeRoom_TV_Look01_Max_010"] = "Eh, ese televisor antes se encontraba en la sala de estar.",
  ["Act_E1_5A_ChloeRoom_TrashCan_Interact01_Max_010"] = "¿Quién habría pensado que Chloe no pagaba sus multas de estacionamiento? Sí que ama los problemas.",
  ["Act_E1_5A_ChloeRoom_TrashCan_Look01_Max_010"] = "La basura de Chloe rebasa.",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_010"] = "Chloe está muy disgustada conmigo. Mejor busco un CD...",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_020"] = "Supongo que ya no le gustan Las pistas de Blue ni los Teletubbies…",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_030"] = "¿Cuándo fue la última vez que tuve que hurgar entre las cosas de Chloe?",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_040"] = "Qué día extraño... y ahora estoy buscando la música de Chloe.",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_050"] = "Me gustaría poder contarle todo... pero podría asustarse.",
  ["Act_E1_5A_ChloeRoom_VoiceOver01_Max_060"] = "Ups. Chloe ya estaba de mal humor. Y lo empeoré. Tal vez pueda arreglarlo...",
  ["Act_E1_5A_ChloeRoom_VoiceOver02_Max_010"] = "No debería molestar a Chloe ahora. Además, necesito esas herramientas...",
  ["Act_E1_5A_ChloeRoom_VoiceOver02_Max_020"] = "Parece que Chloe necesita una pausa mientras busco las herramientas...",
  ["Act_E1_5A_ChloeRoom_VoiceOver02_Max_060"] = "La mamá de Chloe siempre nos regañaba por hacer demasiado ruido. Ahora apenas estamos hablando.",
  ["Act_E1_5A_ChloeRoom_VoiceOver03_Max_010"] = "Este día no podría volverse más extraño...",
  ["Act_E1_5A_ChloeRoom_VoiceOver03_Max_020"] = "Chloe, bailando. Esta sería una gran toma...",
  ["Act_E1_5A_ChloeRoom_VoiceOverHelpChloe_Max_010"] = "Estoy un poco agotada, pero podría ayudar a Chloe.",
  ["Act_E1_5A_ChloeRoom_VoiceOverHelpChloe_Max_020"] = "Si usara mi poder, podría ayudar.",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_010"] = "Justo cuando teníamos un momento de tranquilidad...",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_020"] = "Simplemente, podría intentar rebobinando...",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_030"] = "Maldita sea, ¿debo usar mi poder para esto?",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_040"] = "¡Mejor me escondo rápido!",
  ["Act_E1_5A_ChloeRoom_VoiceOverMaxStress_Max_050"] = "¿Dónde mierda me voy a esconder?",
  ["Act_E1_5A_ChloeRoom_VoiceOverNotHurtChloe_Max_010"] = "Podría cambiarlo, para no lastimar a Chloe.",
  ["Act_E1_5A_ChloeRoom_VoiceOverNotHurtChloe_Max_020"] = "Está bien, Max, puedes arreglarlo todo.",
  ["Act_E1_5A_ChloeRoom_VoiceOverRewind_Max_010"] = "¡Vaya!, David da miedo... podría perjudicar mi beca de Blackwell. Todavía me siento débil, pero podría cambiarlo.",
  ["Act_E1_5A_ChloeRoom_VoiceOverRewind_Max_020"] = "Me siento muy agotada, pero podría rebobinar y arreglar esto.",
  ["Act_E1_5A_ChloeRoom_Window_Interact01_Max_010"] = "Esto no funciona. Mejor busco en otro sitio.",
  ["Act_E1_5A_ChloeRoom_Window_Look01_Max_010"] = "Solíamos desafiarnos a bajar, pero nunca lo hicimos.",
  ["Act_E1_5A_Corridor_AuroraPicture_Look01_Max_010"] = "\"No puedes volver a casa\", dijo Thomas Wolfe. Pero... aquí estoy.",
  ["Act_E1_5A_Corridor_Books_Look01_Max_010"] = "Estos libros no se han tocado desde la década pasada. Entiendo por qué.",
  ["Act_E1_5A_Corridor_Closet_Look01_Max_010"] = "Cerrado.",
  ["Act_E1_5A_Corridor_ExitCorridor_Interact01_Max_010"] = "Ahora que tengo las herramientas, no necesito bajar.",
  ["Act_E1_5A_Corridor_GuestRoom_Look01_Max_010"] = "Cerrado 2: La venganza. Interesante...",
  ["Act_E1_5A_Corridor_ParentsRoom_Look01_Max_010"] = "Los padres de Chloe deben dormir aquí.",
  ["Act_E1_5A_Corridor_Window_Look01_Max_010"] = "Nada ha cambiado. Solo Chloe y yo.",
  ["Act_E1_5A_ParentsRoom_Bird_Look01_Max_010"] = "¡Ay, mierda! ¡Pobrecito! Apuesto a que podría hacer algo para salvarlo...",
  ["Act_E1_5A_ParentsRoom_Bird_Look02_Max_010"] = "Adiós, pajarito. Podría haber rebobinado para salvar al pobrecito, pero supongo que todo poder tiene un límite...",
  ["Act_E1_5A_ParentsRoom_Bird_Look03_Max_010"] = "Adiós, pajarito. Podría haber rebobinado para salvar al pobrecito, pero fue demasiado tarde...",
  ["Act_E1_5A_ParentsRoom_Bird_Look04_Max_010"] = "Has sido resucitado, pajarito. Vuela, sé libre.",
  ["Act_E1_5A_ParentsRoom_Book_Look01_Max_010"] = "\"Actúa, reacciona o muere: Una guía de supervivencia del siglo XXI\". Vaya. Autoayuda para el apocalipsis.",
  ["Act_E1_5A_ParentsRoom_Closet_Interact01_Max_010"] = "Joyce todavía trabaja en el restaurante. ¿Su esposo es policía? Pobre Chloe.",
  ["Act_E1_5A_ParentsRoom_Drawer01_Interact01_Max_010"] = "Chapas de identificación, genial. \"David Madsen\".",
  ["Act_E1_5A_ParentsRoom_Drawer02_Interact01_Max_010"] = "Oh, Joyce tiene un pequeño santuario de William. Quizás su nuevo esposo no sea tan idiota...",
  ["Act_E1_5A_ParentsRoom_JoycePhoto_Max_010"] = "Joyce se ve feliz. El padrastro de Chloe quizás no sea un idiota después de todo.",
  ["Act_E1_5A_ParentsRoom_Magazine_Look01_Max_010"] = "Joyce siempre amó sus catálogos de basura inútil que le llegan por correo.",
  ["Act_E1_5A_ParentsRoom_Necklace_Look01_Max_010"] = "Ay, Dios... Chloe hizo esto para Joyce en el Día de la Madre, hace años. Ya veo por qué lo guardó.",
  ["Act_E1_5A_ParentsRoom_Papers_Look01_Max_010"] = "Ay, no. Los \"Price\" están atrasados en sus facturas.",
  ["Act_E1_5A_ParentsRoom_Uniform_Look01_Max_010"] = "Joyce todavía trabaja en el restaurante y el nuevo papá de Chloe es un guardia de seguridad... Oh, oh.\n",
  ["Act_E1_5A_ParentsRoom_VoiceOver_Max_010"] = "Esta debe ser la habitación de los padres de Chloe... Sí que estoy entrometida hoy...",
  ["Act_E1_5A_ParentsRoom_VoiceOver_Max_020"] = "Vaya. Ya llevo dos vidas salvadas hoy... ¿Qué significa esto?",
  ["Act_E1_5A_ParentsRoom_Window_Look01_Max_010"] = "Pensar que vivía a menos de un kilómetro...",
  ["Cue_E1_5A_ChloeRoom_Box_Chloe_010"] = "Amiga, rompiste mi globo de nieve. Gracias.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_CDObj_Chloe_001"] = "Ey, ¿ya encontraste el disco?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_CDObj_Chloe_002"] = "Sé que mi habitación es un desastre, pero puedes encontrar un disco.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_CDObj_Chloe_003"] = "Aquí está, Max. Busca un poco mejor.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion2_Chloe_001"] = "¿Podrías poner un poco de música?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion3_Chloe_001"] = "Eres ridícula. No te veo por cinco años, y lo primero que haces es romper mi globo de nieve. Gracias, Max... Ahora pon algo de música y déjame fumar tranquila un rato.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_001"] = "Entonces, dime, ¿qué hace Max Caulfield para divertirse ahora que es adulta?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_006"] = "No puedo decir que todavía te conozco. Quizás te encante salir a bailar todas las noches.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_007"] = "No la muchacha que se queda mirando a todos. Apuesto a que nunca fuiste a una fiesta.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_008"] = "Cielos, gracias. Esperaba escuchar algo positivo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_009"] = "No suena tan triste.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_014"] = "Invitaría a esos idiotas drogadictos y los miraría retorcerse en una batalla del baile de la muerte... Toma una foto de eso.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_015"] = "Max, tenías 12 años. Eso es...triste. Debes seguir tomando fotos.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_016"] = "No, sobre mí. ¡Puf! Creí que al menos serías feliz tomando fotos... Olvídalo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Chloe_017"] = "Eso es más inspirador. No me siento tan desesperanzada...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_002"] = "No mucho. Me conoces. Me gusta observar el mundo más que participar en él.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_003"] = "Fiesta noche y día.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_004"] = "No me siento adulta. Solo más confundida a medida que crezco. Especialmente luego de hoy...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_005"] = "Tomo fotos. De mí, del mundo, de todo. Quizás suena triste, pero la paso bomba.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_010"] = "¿Te imaginas a mí en un reventón?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_011"] = "Sí, claro. Fui a tu fiestazo de cumpleaños.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_012"] = "¿Sobre mí?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ChloeQuestion_Max_013"] = "Soy más feliz cuando tengo una buena imagen en mi lente. No soy solitaria, ni tengo miedo de...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_DeskObj_Chloe_001"] = "¿Encontraste las herramientas? Excelente. Puedes sentarte en mi escritorio y arreglar tu cámara.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_001"] = "Me estás mirando de una forma que no veía hace tiempo. ¿Cuál es el problema?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_004"] = "O alguien como Nathan me meterá una bala. A la mierda con eso. Necesito cuidar mis espaldas.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_005"] = "Solo si alguien se interpone en mi camino otra vez.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_008"] = "¿Para qué carajo necesita otra arma? ¿Para bajar a las porristas de Pies Grandes?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_009"] = "¿Crees que quiero hacer eso? Preferiría estar en Los Ángeles con Rachel, en lugar de esconder un arma...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_011"] = "Lo sé, Max. Pero la verdad es que me siento más segura con una nueve milímetros en mis pantalones.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_014"] = "Cuando los malditos dejen de amenazarme con armas, entonces dejaré de jugar con la mía.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_015"] = "¿Después de cientos de juegos en línea? Claro que sí.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Chloe_018"] = "Max, no estoy buscando problemas. Solo es por protección. Si alguien en este país debe tener armas son las mujeres...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_002"] = "¿Por qué le robaste un arma a tu padrastro? Sabes que te atraparán.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_003"] = "Deberías regresar el arma. Demasiado peligroso...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_006"] = "Tu padrastro no te dejará escapar tan fácilmente.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_007"] = "Por favor, no hables así...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_010"] = "Esto me da tanto miedo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_012"] = "Bueno, a mí no. Las armas me ponen nerviosa. Deberías estar tocando la guitarra, no jugando con un arma.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_013"] = "¿Sabes usarla?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_016"] = "Tu arma no te protege de una bala por la espalda.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun01_Max_017"] = "Solo no la guardes en tus pantalones, ¿está bien?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Gun02_Chloe_001"] = "Salgamos por la ventana.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_001"] = "Adelante, es un mp3, no un disco de vinilo. Puedes ponerla...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_002"] = "Supongo que prefieres el silencio incómodo a la música.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_003"] = "Todavía no oigo nada.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_004"] = "Max, el reproductor está allí.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_005"] = "Ahora, ¿puedes poner alguna canción?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_006"] = "Max, este silencio me está matando. Debo. Escuchar. Música.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_HifiObj_Chloe_007"] = "Escuchemos ese CD.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_001"] = "Sí, los puse yo... Era mi ángel. Después de que papá muriera, y tú te mudaras, me sentí abandonada. Rachel me salvó la vida.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_004"] = "Rachel Amber. Era mi... ángel. Después de que papá muriera, y tú te mudaras, me sentí abandonada. Rachel me salvó la vida.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_006"] = "Bueno, nunca te esforzaste mucho por saber. Tenía 14 años, éramos mejores amigas.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_009"] = "Rachel me cuidaba. Íbamos a conquistar el mundo. Te reirías de lo diferente que éramos... Ella quería ser una estrella.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_011"] = "Ese era su plan. Nuestro plan. Salir de la ciudad de los Pies Grandes e irnos a Los Ángeles.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_015"] = "Mamá estaba demasiado ocupada corriendo detrás del Sargento Hijodeputa.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_016"] = "Estaba satisfecha por casarse con un Nazi. La razón número 356 para escapar.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_017"] = "No podía esperar a casarse de nuevo. El idiota de mi padrastro es una razón por la cual quería huir.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_019"] = "Hace seis meses. Ella simplemente... se fue de Arcadia. Sin decir una palabra. Sin... mí.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_022"] = "A diferencia de ti, ella me lo hubiera dicho, ¿sabes? Le pasó algo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_023"] = "Están en negación. Max, sé que está desaparecida.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_026"] = "Como todos en mi vida. Mi papá, tú... y Rachel. Se fueron... ¿Puedes poner un poco de música ahora?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Chloe_028"] = "Antes de irse, dijo que había conocido a alguien que le había cambiado la vida... Luego, puf.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_002"] = "Esa es Rachel Amber... Sus carteles de \"Persona desaparecida\" están en todo Blackwell.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_003"] = "¿Y quién es ella? ¿Te molesta hablar de ella?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_005"] = "Vaya, no tenía idea.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_007"] = "Nunca te olvidé. Incluso si fui una idiota y no te llamé. Pero tú tenías a Rachel...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_008"] = "Así que Rachel tomó mi lugar... Me alegro que ella haya estado para ti.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_010"] = "Parece una modelo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_012"] = "¿Y qué paso? ¿Tus padres, tu mamá, trataron de detenerte?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_013"] = "Entiendo por qué... Apuesto que tu mamá no estaba muy contenta...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_014"] = "¿Y tu mamá? ¿Qué pensaba Joyce de todo esto?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_018"] = "Siento el amor... ¿Cuándo desapareció Rachel exactamente?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_020"] = "¿Cómo sabes que desapareció? Quizás quería empezar una vida nueva...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_021"] = "¿Y sus padres? ¿La están buscando?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_024"] = "Te creo. Solo trato de hacerme deductiva...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_025"] = "Seguro que sabes más que eso...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_Rachel_Max_027"] = "¿Y no has oído nada de ella desde entonces?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_001"] = "Ahora, dime la verdad, Max.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_004"] = "Mierda. Eres una ninja.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_005"] = "¡Vamos! Incluso después de cinco años, sé cuándo mientes.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_009"] = "De puta madre.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_012"] = "Entonces, ¿me reconociste?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_014"] = "Eso espero. Estoy segura de que debe ser muy raro para haber regresado.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_016"] = "Sé que me veo muy diferente.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_018"] = "No te culpo, Max.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_020"] = "Debes haber escuchado nuestra conversación...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_022"] = "¿Y? ¿Nos escuchaste?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_024"] = "No hay forma de que no hayas escuchado hasta la última palabra.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_026"] = "Ahora, la gran pregunta: ¿Le contaste a alguien?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_031"] = "Maldito cobarde... eso dio miedo. ¿A quién le contaste?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_032"] = "¡Como a cualquiera! Deja de intentar ganar tiempo, hermana.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_033"] = "No te culpo... Es intenso.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_034"] = "Nathan intenta parecer un tipo violento, pero es una puta malcriada.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_038"] = "¿El director? ¿Tienes doce años? A ese estúpido borracho solo le importa el dinero para la Academia Blackwell... No confíes en él.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Chloe_040"] = "Gracias a Dios... Te contaré más otro día; de verdad, estoy en deuda contigo, Max.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_002"] = "Estaba allí... Escondida en la esquina.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_003"] = "No estaba allí...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_006"] = "Un ninja le habría cortado la cabeza a Nathan. Solo tomé una foto de la mariposa...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_007"] = "Está bien, estaba allí, Sherlock.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_010"] = "Ah, sí. Casi me hago pis encima cuando vi el arma...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_013"] = "Para nada. Tu pelo y tu ropa están tan diferentes...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_015"] = "No estaba segura...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_017"] = "Además estaba asustada. No podía pensar con claridad.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_019"] = "Como tú dijiste, ha sido esa clase de día.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_021"] = "¡Estaba asustadísima! Solo podía oír a Nathan gritando...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_023"] = "Solo un poco...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_025"] = "Está bien, solo escuché algo sobre dinero... drogas... pero eso es todo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_027"] = "Absolutamente. Nathan Prescott te estaba apuntando con un arma, carajo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_028"] = "¿Como a quién?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_029"] = "No. No sabía qué hacer...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_030"] = "Quería hacerlo... ¿Y si se vuelve loco?",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_035"] = "El director... pero no pareció creerme.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_036"] = "Quizás debería ir a ver al director.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_037"] = "Te habría disparado, Chloe. Es un hecho. Debería contarle al director.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_039"] = "No te mencioné. Lo juro.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_RepairFail_Max_041"] = "En serio, no hablé con nadie. De verdad.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ToolsObj_Chloe_001"] = "Mi maldito padrastro guarda las herramientas en el garage. Apuesto a que puedes encontrar algo para reparar tu cámara.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ToolsObj_Chloe_002"] = "No, Max, esto no es un cobertizo para herramientas. Como ya dije, fíjate en el garage.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_ToolsObj_Chloe_003"] = "¿Puedes dejarme descansar un poco? ¿Sola? Las herramientas siguen estando abajo.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObjBis_Chloe_001"] = "Nos iremos por la ventana. Ver al padrastro de mierda no está en los planes.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObjBis_Chloe_002"] = "¿Puedes ir de una vez? Mierda, quiero irme de aquí.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObjBis_Chloe_003"] = "Demonios, ¿qué estás esperando? ¡Abre la ventana!",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObj_Chloe_001"] = "Vamos, ¡escapémonos por la ventana! Está bien, lo hago todas las noches...",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObj_Chloe_002"] = "Max, abre la ventana y podremos volar este puesto de paletas.",
  ["Cue_E1_5A_ChloeRoom_CHChloe_WindowObj_Chloe_003"] = "¡Si abres la ventana, podremos largarnos de aquí!",
  ["Cue_E1_5A_ChloeRoom_ChloeDanceLoop_Chloe_010"] = "Este es mi momento, Max. No dejes que se escabulla...",
  ["Cue_E1_5A_ChloeRoom_ChloeDanceLoop_Chloe_020"] = "Solo puedo hacer mil poses, nena...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_AlreadyOut_Max_010"] = "Uh, sí. Mi hierba...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_030"] = "¿Por qué no me dejas en paz? Deja de desquitarte con muchachas de secundaria.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_050"] = "Vete al diablo, maldito policía.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_090"] = "Escucha, idiota, si me vuelves a poner una mano encima, mandaré tu trasero a prisión. Allí podrás vigilarte a ti mismo toda la noche...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_110"] = "Mírense, jóvenes guerreras.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_150"] = "Escucha, David. Tengo pruebas de que te metiste con Kate Marsh hoy. Pruebas de vigilancia.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_170"] = "Sabes de lo que hablo.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_210"] = "Como sea. Todos me abandonan. Hasta mi \"mejor amiga\" Max... ¿No?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Chloe_220"] = "Estoy harta de toda la gente de esta ciudad... Ojalá ni te hubiera visto. Como si te importara. Me voy de aquí...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_020"] = "Claro que no. Seguro que Chloe consigue lo mejor, ¿no? Seguro que te dio tarifas por \"amistad\"...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_040"] = "No viste la rabia, pequeña—",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_060"] = "Yo... Oye, tú lo pediste. Sabes exactamente lo que estás haciendo.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_070"] = "Por lo que ocurrió hoy, ya sé que traes problemas, Max. Espero que esto no afecte tu estatus en Blackwell.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_080"] = "No regreses aquí jamás.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_100"] = "Ustedes son quienes terminarán en prisión.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_120"] = "Son fuertes y listas solo en su cabeza. Esto también pasará...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_130"] = "Ahora, limpien esta pocilga.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_140"] = "Por tu propio bien, deberías alejarte de Chloe. Es una perdedora y solo te arrastrará con ella. Limítate a hacer la tarea.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_160"] = "¿De qué estás hablando?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_180"] = "Son fuertes y listas solo en su cabeza. Esto también pasará...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_David_190"] = "Ahora, limpien esta pocilga.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Max_010"] = "De ningún modo. No es mía.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_BlameChloe_Max_200"] = "Lo siento, Chloe. No sabía qué hacer...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeHappy_Chloe_010"] = "Gracias por soportar la rabieta. Sí que golpeamos su maldito trasero, Max. Ya no puede contra nosotras... Ese fue un triunfo épico.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeHappy_Chloe_020"] = "Como sea. Escapémonos por la ventana... Hay un lugar fantástico adonde podemos ir en este agujero...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Chloe_020"] = "Bienvenida a \"Los verdaderos padrastúpidos de Arcadia Bay\"...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Chloe_040"] = "¿Por qué? Se habría comportado aún más idiota si te hubiera encontrado ahí.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Chloe_060"] = "Como sea. Escapémonos por la ventana... Hay un lugar fantástico adonde podemos ir en este agujero...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Max_010"] = "Oye, ¿estás bien?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Max_030"] = "Lo siento...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChloeSad_Max_050"] = "Es difícil de creer.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChoiceHidden_David_010"] = "¿De quién es?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChoiceNotHidden_Chloe_010"] = "¡No es mi hierba, es de Max!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ChoiceNotHidden_David_020"] = "¿Es cierto?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_Chloe_020"] = "Oh, cielos, no tomé tu estúpida arma. ¿Sabes que estoy a favor del control de las armas, no?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_Chloe_040"] = "Ay, sí, armas, marihuana... Estás enloqueciendo.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_010"] = "Falta una de mis armas.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_015"] = "¿Tú la tomaste?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_030"] = "Espera, ¿eso es hierba? ¡Has estado drogándote aquí de nuevo!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_DavidDesk_David_050"] = "¡Estoy harto de tu falta de respeto! ¡Dime la verdad, es una orden!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_FileGarage_Chloe_020"] = "No toqué tus archivos, David. Tus archivos me importan un carajo.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_FileGarage_David_010"] = "Te ordené que nunca revises mis archivos. Y obviamente lo has hecho.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_FileGarage_David_030"] = "Te importa empezar peleas, Chloe. Y ya no es gracioso.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_GetOut_David_020"] = "Bien, bien. No me gustan los extraños en mi casa. En especial los que se drogan.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_GetOut_Max_010"] = "Lo siento... Ese era mi porro.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_Chloe_010"] = "¡Mierda!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_Chloe_030"] = "Cielos, solo estoy probándome ropa. Eres tan paranoico.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_David_020"] = "¿Qué está pasando aquí?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_Hidden_David_040"] = "Sí, el combate te hace eso.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_Chloe_010"] = "¡Mierda!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_Chloe_030"] = "No es asunto tuyo.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_Chloe_050"] = "Tranquilízate, no es una extraña. Es mi amiga.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_David_020"] = "¿Qué está pasando aquí? ¿Por qué está aquí?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_David_040"] = "No me gustan los extraños aquí.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_NotHidden_David_060"] = "Fantástico, otra de tus \"amigas\".",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_010"] = "Porque eres tan ruda, Max... Déjame mostrarte mi nuevo juguete...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_020"] = "Soy Price... ¡Chloe Price! ¡Bum!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_040"] = "Tranquila, hermana. Ni siquiera está cargada... todavía.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Chloe_060"] = "Sí, a favor de que yo debo tener el control del arma. Los hombres son los que necesitan ser revisados. ¿Confías en Nathan o en David?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Max_030"] = "Cielos, ¡guarda esa cosa!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_ShowGun_Max_050"] = "Creí que estabas a favor del control de armas.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_010"] = "Deja de tratarnos a mamá y a mí como si fuéramos tu pelotón familiar.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_020"] = "Ojalá abandonaras a Joyce. Como ahora.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_040"] = "No me vuelvas a tocar, maldito. Esa fue la última vez. O la policía vendrá tan rápido...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_060"] = "Sería inteligente si lograra que te atraparan.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_080"] = "Por cierto, tengo pruebas de que te metiste con Kate Marsh hoy. Pruebas de vigilancia.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_Chloe_100"] = "Entonces, mantente fuera de mi vida.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_010"] = "Ey, deja a Joyce fuera de esto.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_030"] = "Chloe, lo siento. Me importa tu mamá y... No paras de presionarme...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_050"] = "No eres tan tonta.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_070"] = "Chloe... Algún día crecerás.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_090"] = "¿Qué? Te conviene no meterte en mi trabajo.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_StayHidden_David_110"] = "Chloe... Algún día crecerás.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_050"] = "¡Aléjate de ella, loco de mierda! ¡Deja de acosar a mis amigas!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_070"] = "Como si supieras. ¡Ni siquiera eres un policía de verdad, eres un maldito guardia de seguridad!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_110"] = "¡Aléjate de ella, carajo! ¡Tengo pruebas de que te metiste con Kate Marsh hoy!",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_Chloe_130"] = "Tengo pruebas de vigilancia. Ahora, por favor, déjanos en paz.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_010"] = "Así que traes drogas a mi casa. ¿Y si llamo a la policía? Eso mancharía tu inmaculado historial en Blackwell...",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_020"] = "Pareces que encajas bien... \"Max\".",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_030"] = "Estoy harto de que ustedes, perdedores, arrastren a Chloe.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_040"] = "Señorita, sí que te gusta aparecer y causar problemas. Como esta tarde. ¿No tienes nada inteligente para decir ahora? ¿No? ¿Eh?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_060"] = "No tienes amigos.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_080"] = "Era soldado, Chloe.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_090"] = "Y, Max, si te veo de nuevo aquí... Sabrás lo que son los verdaderos problemas.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_100"] = "Hoy estás en llamas. Entre la alarma de incendios y ahora esto... ¿No tienes nada inteligente para decir ahora? ¿No? ¿Eh?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_120"] = "¿Qué? ¿De qué estás hablando?",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_140"] = "Está bien, Chloe. Tú sabes todo.",
  ["Cue_E1_5A_ChloeRoom_DavidFurious_TakeBlame_David_150"] = "Y, Max, si te encuentro aquí de nuevo... Será la última vez.",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_010"] = "¡Esta canción es lo máximo! ¿No puedes bailar, hippie? ¡Vamos!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_020"] = "¡Muévete, nena!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_030"] = "¡Sí! ¡Muévelo, Max!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_050"] = "¡Oh, apágalo, apágalo!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_070"] = "¡Oye, la música ni siquiera está encendida!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_080"] = "Idiota.",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_100"] = "¡Mierda!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_110"] = "Debes esconderte. ¡Ahora! ¡Mi padrastro me matará si te encuentra aquí!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_130"] = "Tranquila, me estoy cambiando, ¿está bien?",
  ["Cue_E1_5A_ChloeRoom_DavidHome_Chloe_140"] = "Max, encuentra un lugar para esconderte, ¡AHORA!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_040"] = "Chloe, ¿estás ahí arriba?",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_060"] = "¿Cuántas veces te dije que no pongas a todo volumen esa porquería punk?",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_090"] = "¡Estoy subiendo, debemos hablar!",
  ["Cue_E1_5A_ChloeRoom_DavidHome_David_120"] = "Chloe, ¿qué está pasando? Abre esta puerta, por favor.",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_Chloe_020"] = "¡Ya va!",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_Chloe_040"] = "¡Me estoy cambiando! ¡Dame un momento!",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_Chloe_060"] = "Un segundo... mi sostén está atorado.",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_010"] = "Chloe... ¿Qué estás haciendo?",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_030"] = "Chloe, estás intentando ganar tiempo.",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_050"] = "No te pases de lista, déjame pasar. Ahora. Por favor.",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_070"] = "No estoy bromeando, soldado. Chloe. Abre esta puerta.",
  ["Cue_E1_5A_ChloeRoom_DoorLoop_David_080"] = "Te doy exactamente tres segundos para que abras la puerta. Uno... dos... tres...",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_010"] = "Yo, eh... sé que fue tu cumpleaños el mes pasado...",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_020"] = "Esta era la cámara de papá... Quiero que la tengas.",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_040"] = "Claro que puedes. Papá estaría muy enojado si no la usara nunca. Y ahora sé que será muy bien usada.",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_050"] = "Tomaré esta foto como un símbolo de nuestra unión. ¿Bien?",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_070"] = "¡Suficientes cursilerías, siento ganas de arrojarme de un escenario! ¡Destrocemos este lugar!",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Chloe_090"] = "¡Sip, estoy loca de remate! ¡Bailemos! ¡Mueve el trasero! ¡O toma una foto con tu nueva cámara!",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Max_030"] = "Es tan genial que recordaras mi cumpleaños. Pero no puedo quedarme con esto.",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Max_060"] = "¡Sí, claro que es estupendo! Gracias... Esta cámara es fantástica.",
  ["Cue_E1_5A_ChloeRoom_FriendAgain_Max_080"] = "Estás loca.",
  ["Cue_E1_5A_ChloeRoom_Idle_Chloe_010"] = "Qué bueno encontrarte otra vez revisando mis cosas.",
  ["Cue_E1_5A_ChloeRoom_Idle_Chloe_020"] = "Allí va Max, la Curiosa, buscando problemas...",
  ["Cue_E1_5A_ChloeRoom_Idle_Chloe_030"] = "Solo tómate tu tiempo, Max.",
  ["Cue_E1_5A_ChloeRoom_MetalBox_Chloe_010"] = "¡Oye, dame eso!",
  ["Cue_E1_5A_ChloeRoom_MetalBox_Chloe_030"] = "Mucho más que eso en realidad.",
  ["Cue_E1_5A_ChloeRoom_MetalBox_Max_020"] = "Lo siento. No quería ser entrometida. Obviamente, era una buena amiga...",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Chloe_010"] = "¿Y?",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Chloe_030"] = "¿Estas son tus nuevas fotos?",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Chloe_050"] = "Déjame ver...",
  ["Cue_E1_5A_ChloeRoom_RepairFail_DavidTake_Chloe_010"] = "¿Me estás jodiendo? Ese idiota está en todas partes.",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_010"] = "Un momento... La vi antes. ¡No me digas! ¿Cuándo la tomaste?",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_030"] = "¡TÚ tomaste esta foto, mocosa!",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_040"] = "Hoy en el baño... ¡Tú activaste la alarma! Por eso Nathan se enojó contigo... Todo tiene sentido.",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_050"] = "Salvaste mi vida...",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Chloe_060"] = "Ahora, dime la verdad, Max.",
  ["Cue_E1_5A_ChloeRoom_RepairFail_End_Max_020"] = "Oh...",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Max_020"] = "No puedo arreglar esta cosa.",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Max_040"] = "Sí... Las tomé hoy.",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Victoria_Chloe_010"] = "¡Sí, perra! El karma es una puta.",
  ["Cue_E1_5A_ChloeRoom_RepairFail_Victoria_Chloe_020"] = "Buen encuadre, también.",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Chloe_010"] = "Mi habitación luce un poco distinta de la última vez que la viste.",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Chloe_030"] = "No es exactamente mi \"zona de relajación\"... Mi padrastro nazi se aseguró de que así fuera. Entra y cierra la puerta.",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Chloe_040"] = "Pon algo de música mientras me medico.",
  ["Cue_E1_5A_ChloeRoom_Reveal01_Max_020"] = "Es genial. Al menos podemos relajarnos.",
  ["Cue_E1_5A_ChloeRoom_SadChloe_Chloe_010"] = "Como sea... Puedes encontrar herramientas para tu cámara en el garage...",
  ["Cue_E1_5A_ChloeRoom_SadChloe_Chloe_030"] = "Claro, me siento increíble. Solo quiero fumar y estar sola un momento…",
  ["Cue_E1_5A_ChloeRoom_SadChloe_Max_020"] = "Chloe, ¿estás bien?",
  ["Cue_E1_5A_ChloeRoom_Window_Interact02_Chloe_010"] = "Sal de ahí. Estoy justo detrás de ti.",
  ["Cue_E1_5A_ChloeRoom_Window_Interact03_Max_010"] = "¡Chloe, espérame!",
  ["Act_E1_5B_Garage_BlackWellMap_Look01_Max_010"] = "Mmm, un mapa de la Academia Blackwell. Me pregunto por qué.",
  ["Act_E1_5B_Garage_Box01_Look01_Max_010"] = "Claramente fue difícil para Joyce deshacerse de las cosas de William.",
  ["Act_E1_5B_Garage_Car_Look01_Max_010"] = "¡Mira ese auto! El padrastro de Chloe debe ser un fanático de los autos.",
  ["Act_E1_5B_Garage_Computer_Interact01_Max_010"] = "No hay contraseña. Como si fuera a ayudarme a encontrar las herramientas.",
  ["Act_E1_5B_Garage_Computer_Look01_Max_010"] = "Esto debe pertenecer al padrastro de Chloe.",
  ["Act_E1_5B_Garage_Cupboard01_Look01_Max_010"] = "Tal vez debería mirar dentro.",
  ["Act_E1_5B_Garage_Cupboard02_Look01_Max_010"] = "Las herramientas pueden estar en este armario.",
  ["Act_E1_5B_Garage_Drawer01_Interact01_Max_010"] = "Tal vez no.",
  ["Act_E1_5B_Garage_Drawer01_Look01_Max_010"] = "Tal vez este cajón revele todo.",
  ["Act_E1_5B_Garage_Drawer02_Interact01_Max_010"] = "Apuesto a que el padre de Chloe tiene la llave guardada en otro cajón. Adelante.",
  ["Act_E1_5B_Garage_Drawer02_Look01_Max_010"] = "Una unidad de almacenamiento...",
  ["Act_E1_5B_Garage_Drawer03_Interact01_Max_010"] = "Uf, todavía no encuentro las herramientas.",
  ["Act_E1_5B_Garage_Drawer03_Look01_Max_010"] = "Espero que las herramientas estén aquí.",
  ["Act_E1_5B_Garage_Drawer04_Interact01_Max_010"] = "¡El padrastro de Chloe es el jefe de seguridad de Blackwell! ¿Quiere poner cámaras de vigilancia en toda la academia? ¿Cuán paranoico puede ser?",
  ["Act_E1_5B_Garage_Drawer04_Look01_Max_010"] = "¿Hola, herramientas?",
  ["Act_E1_5B_Garage_Drawer05_Interact01_Max_010"] = "¿El padrastro de Chloe es un veterano y un guardia de seguridad? De verdad debe odiarla.",
  ["Act_E1_5B_Garage_Drawer05_Look01_Max_010"] = "Por favor, por favor, que las herramientas estén aquí...",
  ["Act_E1_5B_Garage_File_Interact01_Max_010"] = "¡Mierda! ¡Qué torpe!",
  ["Act_E1_5B_Garage_File_Interact02_Max_010"] = "¡Ah, siempre tiro todo!",
  ["Act_E1_5B_Garage_File_Look01_Max_010"] = "¿Me pregunto qué hay en esos archivos de ahí arriba?",
  ["Act_E1_5B_Garage_FoodCan_Look01_Max_010"] = "Al parecer, están bien preparados para el fin del mundo.",
  ["Act_E1_5B_Garage_Food_Look01_Max_010"] = "¡Mira toda esa comida! Hay suficiente carne enlatada para durar 100 años...",
  ["Act_E1_5B_Garage_GarageDoor01_Interact01_Max_010"] = "¡Estupendo! Ahora está abierta.",
  ["Act_E1_5B_Garage_GarageDoor01_Look01_Max_010"] = "Supongo que podría abrir la puerta desde este lado.",
  ["Act_E1_5B_Garage_GunRack_Look01_Max_010"] = "Mmm, falta una de estas armas... Espero que el padrastro de Chloe no porte armas de fuego.",
  ["Act_E1_5B_Garage_IDcard_Look01_Max_010"] = "¿El padrastro de Chloe es el idiota de Blackwell? Debe ser una broma.\n",
  ["Act_E1_5B_Garage_Medals_Look01_Max_010"] = "Por Dios, qué gran colección de medallas. Hay que reconocer que el padrastro de Chloe es un héroe de guerra...",
  ["Act_E1_5B_Garage_Monitor_Interact01_Max_010"] = "¿Qué carajo...? ¿El padrastro de Chloe instaló cámaras en las habitaciones? ¿De verdad? ¡Este tipo tiene graves problemas de confianza! ¿Chloe y Joyce lo sabrán?",
  ["Act_E1_5B_Garage_Monitor_Look01_Max_010"] = "¿Debería encenderla? Tal vez, tal vez no…",
  ["Act_E1_5B_Garage_Picture01_Look01_Max_010"] = "¿Kate Marsh? ¿Por qué demonios tendría fotos de ella? Está bien, esto se está poniendo cada vez más raro.",
  ["Act_E1_5B_Garage_Picture01_Look02_Max_010"] = "No quiero mirar esas fotos espeluznantes otra vez. ¿Por qué las tiene David?",
  ["Act_E1_5B_Garage_PizzaBox_Interact01_Max_010"] = "Uy, debería haberlo hecho antes de que se cayeran.",
  ["Act_E1_5B_Garage_PizzaBox_Interact02_Max_010"] = "¡Sí! Tienes unas habilidades increíbles, Max.",
  ["Act_E1_5B_Garage_PizzaBox_Look01_Max_010"] = "Sí, aquí hay un cartón viejo...",
  ["Act_E1_5B_Garage_Shelf01_Interact01_Max_010"] = "¡Nada! Esto es tan absurdo...",
  ["Act_E1_5B_Garage_Shelf01_Look01_Max_010"] = "Estantes. Huelo la sangre de las herramientas...",
  ["Act_E1_5B_Garage_Target_Look01_Max_010"] = "¡SÍ! ¡En el blanco!",
  ["Act_E1_5B_Garage_Tool01_Interact01_Max_010"] = "¡Estas son demasiado grandes! Necesito herramientas pequeñas para la cámara.",
  ["Act_E1_5B_Garage_Tool01_Look01_Max_010"] = "Aquí hay herramientas para todos los gustos...",
  ["Act_E1_5B_Garage_ToolBox_Look01_Max_010"] = "¡Sí! ¡Destornilladores de precisión! Pero... no puedo alcanzarlos...",
  ["Act_E1_5B_Garage_ToolBox_Look02_Max_010"] = "Veamos, las herramientas están atascadas, fuera de alcance y no hay manera de conseguirlas. Brillante, Max, brillante.",
  ["Act_E1_5B_Garage_ToolBox_Take01_Max_010"] = "Excelente, estoy lista para una gran sesión de reparación de cámara. Mejor me largo de aquí.",
  ["Act_E1_5B_Garage_Trophy_Look01_Max_010"] = "Pobre ciervito... No les alcanza con matarte; también tienen que colgar tu cabeza.",
  ["Act_E1_5B_Garage_VoiceOver_Max_010"] = "Debería encontrar las herramientas que necesito aquí.",
  ["Act_E1_5B_Garage_VoiceOver_Max_020"] = "Tengo las herramientas, debería volver arriba antes de que Chloe se moleste.",
  ["Act_E1_5B_Garage_VoiceOver_Max_030"] = "Será mejor que suba a arreglar mi cámara.",
  ["Act_E1_5B_Garage_WashingMachine_Interact01_Max_010"] = "Muy inteligente, idiota. No alcanzo.",
  ["Act_E1_5B_Garage_WashingMachine_Interact02_Max_010"] = "Ven con mamá... casi...",
  ["Act_E1_5B_Garage_WashingMachine_Look01_Max_010"] = "Eso no luce estable.",
  ["Act_E1_5B_Garden_BBQ_Look01_Max_010"] = "William nos solía hacer unas hamburguesas fantásticas. Me pregunto si fue el último en usar esto...",
  ["Act_E1_5B_Garden_Drawing_Look01_Max_010"] = "Nos llevó todo el día a Chloe y a mí dibujar eso. Ahora es casi invisible.",
  ["Act_E1_5B_Garden_Grave_Look01_Max_010"] = "Hicimos esta tumba para el gatito de Chloe. Pobre Bongo. No vio venir al auto...",
  ["Act_E1_5B_Garden_Swing_Look01_Max_010"] = "Ay, me encantaba este columpio. William lo hizo para Chloe y para mí.",
  ["Act_E1_5B_Garden_VoiceOver_Max_010"] = "Brrr... Puedo sentir cómo el otoño empuja al verano...",
  ["Act_E1_5B_Garden_VoiceOver_Max_020"] = "Es tan tranquilo aquí. Como un jardín japonés en Oregón.",
  ["Act_E1_5B_LivingRoom_AnsweringMachine_Look01_Max_010"] = "Me encanta que tengan la misma máquina contestadora. Hay un mensaje...",
  ["Act_E1_5B_LivingRoom_BayWindow_Look01_Max_010"] = "La puerta del jardín...",
  ["Act_E1_5B_LivingRoom_Books_Look01_Max_010"] = "Supongo que están añejando estos libros.",
  ["Act_E1_5B_LivingRoom_Couch_Look01_Max_010"] = "¡Mierda, es el sofá! Solíamos jugar a que era un barco pirata... Ahora parece un naufragio.",
  ["Act_E1_5B_LivingRoom_EntryDoor_Interact01_Max_010"] = "Bien, concéntrate, Max. Necesitas encontrar las herramientas para arreglar la cámara.",
  ["Act_E1_5B_LivingRoom_EntryDoor_Look01_Max_010"] = "Cielos, creo que debería haber algunos candados más... Esta puerta siempre solía estar abierta.",
  ["Act_E1_5B_LivingRoom_ExitHouse_Interact02_Max_010"] = "Debo encontrar las herramientas y no quiero dejar sola a Chloe.",
  ["Act_E1_5B_LivingRoom_ExitLivingRoom_Interact01_Max_010"] = "No puedo subir hasta no encontrar esas herramientas.",
  ["Act_E1_5B_LivingRoom_FakeMagazines_Interact01_Max_010"] = "Qué rico. Luce delicioso. Extraño la comida de Joyce...",
  ["Act_E1_5B_LivingRoom_FakeMagazines_Look01_Max_010"] = "Joyce siempre tenía una revista sobre la mesa.",
  ["Act_E1_5B_LivingRoom_GarageDoor01_Interact01_Max_010"] = "No. Alguien la cerró del otro lado.",
  ["Act_E1_5B_LivingRoom_GarageDoor01_Look01_Max_010"] = "La puerta parece cerrada desde el otro lado.",
  ["Act_E1_5B_LivingRoom_Mail_Look01_Max_010"] = "No parece que la familia \"Price\" tenga mucho dinero estos días...",
  ["Act_E1_5B_LivingRoom_MoneyBox_Look01_Max_010"] = "Oh, también me encantaría ir a París. A este paso, con suerte si llegan a Portland.",
  ["Act_E1_5B_LivingRoom_OfficeDoor_Interact01_Max_010"] = "Cerrada, por supuesto...",
  ["Act_E1_5B_LivingRoom_OfficeDoor_Look01_Max_010"] = "Mmm, la puerta de la oficina.",
  ["Act_E1_5B_LivingRoom_Picture01_Look01_Max_010"] = "Esta es la Chloe que recuerdo... Siempre con una sonrisa en la cara... Ya no es la misma.",
  ["Act_E1_5B_LivingRoom_Picture02_Look01_Max_010"] = "Joyce todavía trabaja en el restaurante Two Whales. Las mejores hamburguesas de Arcadia. Tendría que comer una pronto.",
  ["Act_E1_5B_LivingRoom_Picture03_Look01_Max_010"] = "Si hubiera tomado esta foto, el ciervo te habría pisoteado.",
  ["Act_E1_5B_LivingRoom_Stain_Look01_Max_010"] = "¡Oye, recuerdo esa mancha! Chloe y yo tiramos la botella de vino de Joyce y restregamos como locas, pero nunca salió. ¡Cómo nos descubrieron!",
  ["Act_E1_5B_LivingRoom_VoiceOver_Max_010"] = "No he estado aquí en cinco años... parece una eternidad.",
  ["Act_E1_5B_LivingRoom_Window_Look01_Max_010"] = "¿Cuántas veces Joyce nos gritó desde esta ventana?",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_010"] = "¡Vamos, ábrela, gallina!",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_030"] = "¡Pruébalo! ¡Tú bebe primero, Max!",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_050"] = "Como sea. Dame esa botella.",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_070"] = "Sabroso. Muy sabroso.",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_090"] = "Lo siento, esto no es para niños.",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_110"] = "¡Oh, mierda, la alfombra!",
  ["Cue_E1_5B_Garden_CouchSit_Chloe_130"] = "¡Mis padres están viniendo! ¡Cúbrelo!",
  ["Cue_E1_5B_Garden_CouchSit_Max_020"] = "Espera. ¡Y no soy una gallina!",
  ["Cue_E1_5B_Garden_CouchSit_Max_040"] = "¡No me digas! ¡Fue idea tuya, Chloe!",
  ["Cue_E1_5B_Garden_CouchSit_Max_060"] = "¿Bien?",
  ["Cue_E1_5B_Garden_CouchSit_Max_080"] = "¡Ten, quiero un sorbo!",
  ["Cue_E1_5B_Garden_CouchSit_Max_100"] = "¡No seas golosa! ¡Dame un poco!",
  ["Cue_E1_5B_Garden_CouchSit_Max_120"] = "¡Hay vino por todas partes! ¿Qué hacemos ahora?",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_020"] = "Max, ya crecí. ¿Y tú?",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_040"] = "¿Lejos de mí? Muchas gracias, amiga.",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_060"] = "Sería como Lara Croft, solo que real. Eso sería muy fantástico.",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_080"] = "Cuenta conmigo. ¿Qué harías mientras te protejo?",
  ["Cue_E1_5B_Garden_SwingSit_Chloe_100"] = "¿De qué estás hablando? Max, eres fotógrafa. Tus fotografías podrían estar en un museo. Algún día lo estarán. Creo en ti...",
  ["Cue_E1_5B_Garden_SwingSit_Max_010"] = "¿Qué quieres hacer de verdad cuando crezcas?",
  ["Cue_E1_5B_Garden_SwingSit_Max_030"] = "Viajar. Eso sería fabuloso. Explorar el mundo. Ir lejos de aquí...",
  ["Cue_E1_5B_Garden_SwingSit_Max_050"] = "¡Amiga, tú vendrás conmigo! ¡Necesito una guardaespaldas para nuestras aventuras!",
  ["Cue_E1_5B_Garden_SwingSit_Max_070"] = "¡Por supuesto! ¡Tendríamos autos, botes y aviones alrededor para un escape instantáneo! ¡Y ningún adulto podría decirnos qué hacer!",
  ["Cue_E1_5B_Garden_SwingSit_Max_090"] = "Podríamos tomar fotografías de nuestras aventuras. Me encantaría ser fotógrafa. Como si algún día fuera a lograrlo...",
  ["Cue_E1_5B_LivingRoom_AnsweringMachine_Interact01_David_010"] = "Chloe, si estás escuchando... Pete estaba volviendo a casa al terminar el servicio y me dijo que te vio cerca de ese basurero. Te ordené... te pedí que te alejes de ese lugar. Es peligroso y no tienes idea de qué tipo de escoria está viviendo allí. Aléjate. Lo digo en serio.",
  ["Act_E1_6A_CliffNow_Bird02_Look01_Max_010"] = "Los pájaros tienen suerte, siempre pueden escapar...",
  ["Act_E1_6A_CliffNow_Bird_Interact01_Max_010"] = "¡Te tengo!",
  ["Act_E1_6A_CliffNow_Bird_Look01_Max_010"] = "¡Oh, esta será una fantástica toma natural! Quédate quietito, pajarito.",
  ["Act_E1_6A_CliffNow_Bush01_Look01_Max_010"] = "Me encanta cómo la maleza y las plantas crecen donde quieren...",
  ["Act_E1_6A_CliffNow_Butterfly_Look01_Max_010"] = "Las mariposas son libres...",
  ["Act_E1_6A_CliffNow_CHChloe_Look01_Max_010"] = "Esta sería una linda foto de Chloe enmarcada por el sol...",
  ["Act_E1_6A_CliffNow_CHChloe_Look02_Max_010"] = "Se ve muy enojada. No debería haberla delatado antes...",
  ["Act_E1_6A_CliffNow_CampFire_Look01_Max_010"] = "Parece que la juventud de Arcadia Bay sigue viniendo aquí a divertirse. Yo nunca vine...",
  ["Act_E1_6A_CliffNow_Fence01_Look01_Max_010"] = "El viejo cerco ahora es parte del paisaje... El camino trasero lleva al estacionamiento...",
  ["Act_E1_6A_CliffNow_FootPrints_Look01_Max_010"] = "Esto no es de un Pies Grandes... ¿Qué animal dejó esas huellas?",
  ["Act_E1_6A_CliffNow_Graffiti01_Look01_Max_010"] = "¿Cuánto tiempo ha estado aquí?",
  ["Act_E1_6A_CliffNow_Graffiti02_Look01_Max_010"] = "Este lugar es bonito y misterioso...",
  ["Act_E1_6A_CliffNow_Graffiti03_Look01_Max_010"] = "Evidentemente, los Pies Grandes están en todas partes.",
  ["Act_E1_6A_CliffNow_Graffiti04_Look01_Max_010"] = "Qué extraño, esos glifos me recuerdan... al viento.",
  ["Act_E1_6A_CliffNow_LightHouse_Look01_Max_010"] = "Lástima que está cerrado... Recuerdo subir y bajar corriendo esos escalones...",
  ["Act_E1_6A_CliffNow_OrientationMap_Look01_Max_010"] = "Vaya, Chloe dibujó eso para marcar nuestra casa del árbol... Así, siempre nos podríamos encontrar en caso de emergencia... Ay...",
  ["Act_E1_6A_CliffNow_SMSWarren01_Max_010"] = "Me alegro de haber ayudado a Warren. Solo espero que no me afecte después...",
  ["Act_E1_6A_CliffNow_Sign01_Look01_Max_010"] = "Siento que estoy en mi pesadilla otra vez...",
  ["Act_E1_6A_CliffNow_Sign02_Look01_Max_010"] = "En todos estos años, nunca me tomé el tiempo de leer esta pizarra.",
  ["Act_E1_6A_CliffNow_Squirrel_Look01_Max_010"] = "Hola, ardillita linda. Tú y yo: concurso de miradas.",
  ["Act_E1_6A_CliffNow_Totem_Look01_Max_010"] = "No me acuerdo nada de esto, pero parece que ha estado aquí mucho tiempo...",
  ["Act_E1_6A_CliffNow_TrashCan_Look01_Max_010"] = "La gente puede ser tan sucia.",
  ["Act_E1_6A_CliffNow_Tree01_Look01_Max_010"] = "Este árbol ha vivido durante siglos... yo tendré suerte si llego viva al viernes...",
  ["Act_E1_6A_CliffNow_TreeGraffiti01_Look01_Max_010"] = "¿Un haiku en un árbol? Qué bonito...",
  ["Act_E1_6A_CliffNow_TreeGraphiti_Look01_Max_010"] = "¡Ay, Dios mío! ¡Me había olvidado de esto! Lástima que no puedo rebobinar tanto...",
  ["Act_E1_6A_CliffNow_VoiceOver02_Max_010"] = "Vaya, debí haber ayudado a Chloe. Me siento muy mal...",
  ["Act_E1_6A_CliffNow_VoiceOver02_Max_040"] = "Espero que el padrastúpido de Chloe no me cause problemas.",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_010"] = "Vaya, hace siglos que no vengo aquí...",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_020"] = "Me encanta el mes de octubre...",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_030"] = "Esto es mucho más tranquilo que mi pesadilla.",
  ["Act_E1_6A_CliffNow_Voiceover01_Max_040"] = "Si tan solo Chloe y yo estuviéramos aquí de niñas otra vez...",
  ["Act_E1_6A_CliffNow_WildLifePanel_Look01_Max_010"] = "No han actualizado este cartel desde los ochenta...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_001"] = "Siéntate, si quieres.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_003"] = "Toma asiento.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_008"] = "Solo... quería un poco de apoyo.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_009"] = "No te preocupes. Sé que mi padrastro bobo puede ser escalofriante.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_010"] = "Ver que engañan a mi padrastro bobo me hace feliz.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_011"] = "De verdad, te arriesgaste por el Equipo de Chloe.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_013"] = "Siento que tuvieras que vivir eso de primera mano.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_015"] = "¡Desde que la desesperada de mamá lo arrastró a casa! Nunca confié en David.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_020"] = "¿Por qué estaba tan metido en sus cosas?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_021"] = "Sí, lo es. ¿Por qué estaba molestando a Kate? Es más bien aburrida.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_022"] = "La conozco. Es estupenda. Solo ese cerdo la molestaría.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_023"] = "Ese sería un fantástico material de chantaje. Vamos a joderlo.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_025"] = "Tiene un montón de archivos secretos. Rambo todavía cree que está juntando inteligencia del enemigo.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_027"] = "¿Echaste un vistazo?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_032"] = "Nunca cambies. ¿Qué encontraste?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_033"] = "Conozco esa mirada. Lo miraste. Entonces, cuéntame. ¿Videos violentos?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_034"] = "Me gustaría averiguarlo. Apuesto a que tiene mucha pornografía allí.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_035"] = "¡No Max, la que se queda mirando!",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_039"] = "Este hombre se toma su trabajo demasiado en serio. Cree que sigue en la guerra o algo así.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_040"] = "Qué bueno que no miraste.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_042"] = "No es sorpresa que esté tan deprimida. Todos en esta ciudad saben los secretos de todos...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_043"] = "Es un idiota de élite que vende mierda con laxantes... y me drogó con algo en su habitación.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_044"] = "Ya no.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_049"] = "Lo conocí en un bar de mala muerte donde no me pidieron identificación. Era demasiado rico para ese lugar, y estaba en muy mal estado. Seguía tirando billetes...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_051"] = "Ese fue el último error de Nathan...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_056"] = "Oh, qué bueno que se lo dijiste al director. Ya me siento más segura...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_057"] = "Qué bueno que no se lo dijiste a nadie. Será mejor que Nathan Prescott se cuide a partir de ahora...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_058"] = "A la mierda con eso. Qué bueno que no le dijiste a nadie, ahora se enfrentará con mi Walter White interno.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_060"] = "Estabas aquí hoy, Max. ¡Me salvaste! Todavía estoy intentando entenderlo... Verte después de todos estos años se siente como...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_064"] = "Me encantaría. Deben ser importantes, o no los escondería en su refugio del garage.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_065"] = "David esconde sus archivos secretos X allí. Los vi una vez, pero ahora los tiene bajo llave.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_067"] = "Seguramente, pero es bueno que no hayas encontrado sus archivos. Se volvería loco.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_068"] = "Tiene un fetiche con la vigilancia. Me preocupa que haya cámaras espía en la casa.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_070"] = "¿De qué estás hablando?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_072"] = "¡Lo sabía! ¡Es tan jodido y paranoico! Mantendré esto en secreto por ahora...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_082"] = "En realidad, sí. Debo mucho dinero. Y creí que tendría suficiente para mí y Rachel si aparecía...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_086"] = "Fuimos a su habitación en Blackwell. Bebimos y nos reímos de su mierda de niño rico. Él se me adelantó y puso algo en mi cerveza...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_087"] = "Tres mil más intereses. Y antes de que Nathan me diera una parte... puso algo en mi bebida...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_088"] = "Sé que me desmayé en el piso. Me desperté, y ese pervertido estaba sonriendo, se arrastraba hacia mí con una cámara...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_090"] = "Todo estaba borroso... Traté de patearlo en las bolas y rompí una lámpara. Nathan se asustó, y me las arreglé para llegar a la puerta y largarme de allí. Max, fue una locura.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_093"] = "Se me ocurrió obligarlo a que me pague por quedarme callada. Así que nos reunimos en el baño.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_095"] = "A la mierda con eso. Ya le dijiste al director, y estoy segura de que es inútil.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Chloe_097"] = "Fui una idiota. Pensé que estaba tan drogado que sería un blanco fácil.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_004"] = "¿Estás... enojada conmigo?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_005"] = "Lamento haberme acobardado.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_006"] = "Estás de buen humor.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_007"] = "Sería un placer. Se siente bien estar aquí afuera luego de todo ese drama...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_012"] = "No soy tan valiente como tú. Y David es sin duda un padrastúpido.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_014"] = "Tú tienes que vivir con él. ¿Siempre ha sido así?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_016"] = "Me alegro de haber tomado su foto con Kate. Por si acaso...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_017"] = "Me sentí rara de haber tomado su foto con Kate. Pero la estaba molestando.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_018"] = "Perdió la cabeza con la pobre Kate Marsh hoy.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_019"] = "Debí haberle tomado una foto cuando perdió la cabeza con Kate hoy.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_024"] = "Tiene algún propósito extraño.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_028"] = "Bueno, sí. No pude evitarlo.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_029"] = "Oh... ¿Archivos?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_030"] = "Sabes que quería hacerlo, pero... Me di cuenta de que ya tenía suficiente misterio en mi vida.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_031"] = "Yo no.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_036"] = "Fotos espeluznantes de Kate Marsh... otros estudiantes de Blackwell...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_037"] = "Puaj.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_038"] = "Cállate.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_045"] = "¿Cuál es el secreto de Nathan?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_046"] = "¿Incluso el tuyo?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_047"] = "¿Qué tienes sobre Nathan?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_048"] = "¿Qué?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_054"] = "Sigue siendo peligroso, Chloe. No solo para ti.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_055"] = "¿Qué vas a hacer? ¿Meterle una bala en el culo? Llamemos a la policía...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_059"] = "No siempre estaré allí para salvarte...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_061"] = "¿Destino?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_062"] = "Ojalá. Sabes que los habría leído.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_063"] = "¿Qué archivos?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_066"] = "Me da un poco miedo. Apuesto que la verdad está allí en sus archivos.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_069"] = "¡Sabía que no sabías! Chloe, tu casa está siendo vigilada.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_071"] = "Hay cámaras en toda la casa. Lo vi en un monitor en el garage.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_073"] = "A veces la ignorancia es una bendición.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_074"] = "Solo dime lo que pasó, Chloe. Ahora.",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_079"] = "¿De verdad, Chloe?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_081"] = "¿Necesitabas el dinero con tanta desesperación?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_083"] = "¿Y qué hay de ti y Nathan?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_084"] = "¿Cuánto debes?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_085"] = "Dios, Chloe, no lo puedo creer... Digo, sí. ¿Y luego qué?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_089"] = "Continúa...",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_091"] = "Chloe, es tan retorcido... ¿Qué hiciste, entonces?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_092"] = "Estoy tan furiosa que no puedo hablar... ¿Qué hiciste, entonces?",
  ["Cue_E1_6A_CliffNow_CHChloe_Phase01_Max_094"] = "Y él trajo un arma.",
  ["Cue_E1_6A_CliffNow_DialEnd_Chloe_010"] = "Si esto es el destino, espero que podamos encontrar a Rachel. La extraño, Max.",
  ["Cue_E1_6A_CliffNow_DialEnd_Chloe_020"] = "Este hoyo de mierda se ha llevado a todos los que he amado... Me gustaría tirar una bomba en Arcadia Bay y dejarla en ruinas…",
  ["Cue_E1_6A_CliffNow_IntroDialChloe_Max_010"] = "¿Estás segura de que no quieres estar sola?",
  ["Cue_E1_6A_CliffNow_Reveal01_Chloe_010"] = "¡Vamos, aburrida!",
  ["Cue_E1_6A_CliffNow_Reveal01_Chloe_030"] = "¿No es increíble? Me recuerda a cuando éramos niñas…",
  ["Cue_E1_6A_CliffNow_Reveal01_Max_020"] = "¡Espera!",
  ["Cue_E1_6A_CliffNow_Reveal01_Max_040"] = "No he estado aquí en siglos... ¿Por qué me siento como si hubiera estado aquí hace tan poco?",
  ["Cue_E1_6A_CliffNow_Reveal01_Max_050"] = "Vaya, este es el camino exacto en el que estaba en mi pesadilla hoy...",
  ["Cue_E1_6A_CliffNow_Reveal02_Max_010"] = "Chloe sabe cómo albergar resentimiento.",
  ["Cue_E1_6A_CliffNow_Reveal02_Max_020"] = "No he estado aquí en siglos... ¿Por qué me siento como si hubiera estado aquí hace tan poco?",
  ["Cue_E1_6A_CliffNow_Reveal02_Max_030"] = "Vaya, este es el camino exacto en el que estaba en mi pesadilla hoy...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_010"] = "Ay, no, no otra vez...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_020"] = "¿Chloe sigue ahí arriba? ¡Tengo que averiguarlo!",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_030"] = "¿Por qué me está pasando esto?",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_040"] = "Tengo que ver si Chloe está a salvo...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_060"] = "¿Por qué estoy aquí de nuevo?",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_070"] = "Esa venada... Me resulta tan familiar...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_080"] = "Siento que la venada me está guiando...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_095"] = "Debo llegar al otro lado... Siento que la venada me está guiando...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_100"] = "¡Ay, Dios! ¡El tornado regresó! ¿Es esto real?",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_110"] = "Nunca vi una tormenta como esta en Oregón...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_120"] = "Se siente como el fin del mundo...",
  ["Act_E1_6B_CliffFuture_VoiceOver01_Max_130"] = "Vamos, Max, puedes hacerlo...",
  ["Cue_E1_6B_CliffFuture_LightHouseFalling_Max_010"] = "¡Mierda!",
  ["Cue_E1_6B_CliffFuture_LightHouseFalling_Max_020"] = "Ese tornado se dirige directamente al pueblo...",
  ["Cue_E1_6B_CliffFuture_LocalPaper_Max_010"] = "¿11 de octubre? ¡Es este viernes!",
  ["Cue_E1_6B_CliffFuture_LocalPaper_Max_020"] = "Es dentro de cuatro días...",
  ["Cue_E1_6B_CliffFuture_LocalPaper_Max_030"] = "Ay, no...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_020"] = "Max, ¿qué sucede? Te desmayaste…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_040"] = "Hay solo cinco tornados cada 20 años en Oregón. Quedaste en blanco.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_060"] = "Vamos, respira, ¿sí?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_080"] = "Te escucho, Max.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_110"] = "Pero drogada, ¿no?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_130"] = "¿Retrocediendo el tiempo? Sí, seguro.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_140"] = "¿De verdad?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_160"] = "Está bien. Veo que eres una sabelotodo con una gran imaginación, pero esto no es un anime ni un videojuego. Las personas no tienen esos poderes, Max.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_180"] = "Necesitas fumar uno. Ha sido un día de locos…",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_190"] = "¿Qué mierda es esto?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_210"] = "Hace como 26 °C... ¿Cómo?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_240"] = "Max, comienza desde el principio.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Chloe_250"] = "Cuéntame todo...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_010"] = "Chloe... estás aquí. Volví. Ay, Dios mío. Es real... es real. Vaya, esto apesta.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_030"] = "No me desmayé... Tuve otra visión... el pueblo será borrado del mapa por un tornado.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_050"] = "No, no. Lo vi. Pude sentir la electricidad en el aire.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_070"] = "Chloe, no estoy loca. Pero hay algo más que debo decirte. Algo... Intenso.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_090"] = "Tuve la misma visión más temprano en la clase... Cuando salí, descubrí que podía retroceder el tiempo.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_100"] = "Como dije: No estoy loca.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_120"] = "Escúchame. ¿Cómo crees que te salvé en el baño?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_150"] = "Vi que te disparaban, Chloe. En realidad, te vi... morir. Fui capaz de regresar y hacer sonar la alarma...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_170"] = "No sé lo que tengo... Pero lo tengo. Y estoy cagada de miedo.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_200"] = "Copos de nieve...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_220"] = "Cambio climático.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart01_Max_230"] = "O una tormenta acercándose.",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_010"] = "Ayúdame...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_020"] = "Por favor, ayuda...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_030"] = "Que alguien me ayude...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_040"] = "¡No, detente!",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_050"] = "¿Por qué haces esto?",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_060"] = "Por favor, detente... detente...",
  ["Cue_E1_6B_CliffFuture_ShootBinkEndingPart02_Max_070"] = "No hagas esto...",
  ["Act_E2_1A_Bathroom_CHKate_Look01_Max_010"] = "Kate no está bien. Desearía que David \"deje de castigarla\", como diría Chloe.",
  ["Act_E2_1A_Bathroom_CHKate_Look02_Max_020"] = "Después de bañarme, le devolveré el libro: será una buena excusa para platicar. Tal vez solo hablar con una amiga la haga sentir mejor...",
  ["Act_E2_1A_Bathroom_Faucet_Look01_Max_010"] = "El agua es casi tan buena como una taza de té fuerte cuando estoy en mi modo de sueño.",
  ["Act_E2_1A_Bathroom_Faucet_Look02_Max_020"] = "Ups. Cierto. La presión del agua.",
  ["Act_E2_1A_Bathroom_Faucet_Look03_Max_030"] = "Ahora puedes disfrutar las duchas en paz. De nada.",
  ["Act_E2_1A_Bathroom_KateVideoLink_Interact01_Max_020"] = "Aunque solo pueda evitar que una persona lo vea, vale la pena.",
  ["Act_E2_1A_Bathroom_KateVideoLink_Look01_Max_010"] = "¿Es ese el enlace al video de Kate? Mierda, Victoria es tan malvada.",
  ["Act_E2_1A_Bathroom_Poster01_Look01_Max_010"] = "¿\"Nutrias al poder\"? No estoy hecha para eso.",
  ["Act_E2_1A_Bathroom_Poster02_Look01_Max_010"] = "La última vez que me vacuné contra la gripe, me dio gripe. Vete al diablo.",
  ["Act_E2_1A_Bathroom_TamponDispenser_Look01_Max_010"] = "Aún no me toca, gracias.",
  ["Act_E2_1A_Corridor_BlackwellMap_Look01_Max_010"] = "Blackwell no es tan grande, aunque se siente como un laberinto.",
  ["Act_E2_1A_Corridor_CHAlyssa_Look01_Max_010"] = "Alyssa es un blanco tan fácil para esos cretinos. Debería ayudarla...",
  ["Act_E2_1A_Corridor_CHAlyssa_Look02_Max_020"] = "Si ayudo a Alyssa, podría ser como \"la madrina de Blackwell\"...",
  ["Act_E2_1A_Corridor_CHBrooke_Look01_Max_010"] = "Ahí está Brooke, luce más lista que todos.",
  ["Act_E2_1A_Corridor_CHBrooke_Look02_Max_020"] = "Al menos es aplicada con su trabajo escolar.",
  ["Act_E2_1A_Corridor_CHJuliet_Look01_Max_010"] = "Sea lo que sea que estén viendo, debe ser algo picante...",
  ["Act_E2_1A_Corridor_CHJuliet_Look02_Max_020"] = "Juliet no tiene idea de cuánto lastima a Kate.",
  ["Act_E2_1A_Corridor_Doors_VoiceOver01_Max_010"] = "Claramente no es una persona mañanera.",
  ["Act_E2_1A_Corridor_Doors_VoiceOver02_Max_020"] = "Despierta, Max. Juliet está aquí en el pasillo... no en su habitación.",
  ["Act_E2_1A_Corridor_Doors_VoiceOver03_Max_030"] = "Sin duda, Taylor está con Victoria, bajo su control, como de costumbre.",
  ["Act_E2_1A_Corridor_Doors_VoiceOver04_Max_040"] = "Brooke no está aquí...",
  ["Act_E2_1A_Corridor_DormMap_Look01_Max_010"] = "Bienvenidos al infierno Blackwell...",
  ["Act_E2_1A_Corridor_ExpressionPanel02_Look01_Max_010"] = "Vaya, la gente de aquí es despiadada.",
  ["Act_E2_1A_Corridor_ExpressionPanel02_Look01_Max_020"] = "Podría ser divertido. Me alegra no ser la única nerd solitaria de aquí.",
  ["Act_E2_1A_Corridor_ExpressionPanel02_Look01_Max_030"] = "Gracias por la advertencia.",
  ["Act_E2_1A_Corridor_ExpressionPanel_Look01_Max_010"] = "Este es como un ADN público de nuestra residencia...",
  ["Act_E2_1A_Corridor_ExpressionPanel_Look01_Max_020"] = "¡Vamos, Sra. Grant! No creo que vaya... Soy una perdedora.",
  ["Act_E2_1A_Corridor_KateDoor_VoiceOver01_Max_010"] = "Kate es madrugadora. Es posible que se haya despertado y se haya ido.",
  ["Act_E2_1A_Corridor_KateSlate_Look01_Max_010"] = "Las marcas de Satanás.",
  ["Act_E2_1A_Corridor_KateSlate_Look02_Max_020"] = "Me encantaría atrapar a este grafitero de pasillos...",
  ["Act_E2_1A_Corridor_MPA01_VoiceOver01_Max_010"] = "Parece que Rachel me estuviera viendo fijo...",
  ["Act_E2_1A_Corridor_MPA01_VoiceOver03_Max_030"] = "Me encantaría creer que Rachel Amber solo está jugando a las escondidas.",
  ["Act_E2_1A_Corridor_MPA01_VoiceOver04_Max_040"] = "Chloe está tan decidida a encontrarte, Rachel.",
  ["Act_E2_1A_Corridor_MaxSlate_Look01_Max_010"] = "¿Por qué habría de importarle a alguien? Pensé que los artistas se ayudaban entre sí...",
  ["Act_E2_1A_Corridor_MaxSlate_Look02_Max_020"] = "Donde las dan, las toman, Moriarty. Quizás no lo crean, pero no estarán seguros.",
  ["Act_E2_1A_Corridor_Poster01_Look01_Max_010"] = "Creo que estaré demasiado asustada como para ir.",
  ["Act_E2_1A_Corridor_Poster02_Look01_Max_010"] = "Linda toma atmosférica. Necesita limpieza.",
  ["Act_E2_1A_Corridor_Poster03_Look01_Max_010"] = "\"¡Viven!\".",
  ["Act_E2_1A_Corridor_Poster04_Look01_Max_010"] = "Pero ¿qué está tratando de decirme este cartel?",
  ["Act_E2_1A_Corridor_ScoreBoard_Look01_Max_010"] = "Me encantaría hacer un collage de fotos de cada persona que publicó estos carteles.",
  ["Act_E2_1A_Corridor_ToiletPaper_Look01_Max_010"] = "Podría evitar el ataque de papel higiénico si rebobino rápido...",
  ["Act_E2_1A_Corridor_TrashCan_Look01_Max_010"] = "Samuel es realmente extraño... pero es muy bueno para la limpieza.",
  ["Act_E2_1A_Corridor_VictoriaDoor_VoiceOver01_Max_010"] = "Bueno, no te molestaré.",
  ["Act_E2_1A_DanaRoom_BigfootBanner_Look01_Max_010"] = "Dana se toma muy en serio el espíritu Blackwell.",
  ["Act_E2_1A_DanaRoom_BirthControl_Look01_Max_010"] = "Mmmmm...",
  ["Act_E2_1A_DanaRoom_CHDana_Look01_Max_010"] = "Nunca he visto a Dana tan animada y contenta sin una jarra entera de café.",
  ["Act_E2_1A_DanaRoom_CheerleaderOutfit_Look01_Max_010"] = "No puedo ni imaginarme cómo sería la vida si fuera porrista. Dramática, supongo.",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look01_Max_010"] = "La curiosidad mató a Max...",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look02_Max_020"] = "¿Quién sobrevivirá? ¿Y qué quedará de ellos? No digas eso en voz alta, idiota.",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look03_Max_030"] = "Me encantaría poner esqueletos y fantasmas por todo Blackwell...",
  ["Act_E2_1A_DanaRoom_DanaLaptop_Look04_Max_040"] = "Como si pudiera verme bien en ese estilo... ¡Hola, Victoria!",
  ["Act_E2_1A_DanaRoom_HalloweenStuff_Look01_Max_010"] = "Es tan tierno lo emocionada que Dana está por la fiesta de Halloween.",
  ["Act_E2_1A_DanaRoom_LoganNote_Look01_Max_010"] = "Esto es triste y patético a la vez.",
  ["Act_E2_1A_DanaRoom_MakeUp_Look01_Max_010"] = "Hablando de la Noche de Brujas, mira todo este maquillaje. Al menos Dana sabe usarlo.",
  ["Act_E2_1A_DanaRoom_Rollers_Look01_Max_010"] = "¡Patines! Quería ser una \"muchacha derby\", pero casi me quiebro los pies con solo ponérmelos...",
  ["Act_E2_1A_DanaRoom_TrevorJacket_Look01_Max_010"] = "Trevor se está poniendo cómodo. Espero que no los descubran.",
  ["Act_E2_1A_Dormitory_BookKate_VoiceOver01_Max_010"] = "Kate necesita recuperar su libro y será mejor que no la defraude, como piensa que lo hice ayer...",
  ["Act_E2_1A_Dormitory_BookKate_VoiceOver02_Max_020"] = "Kate necesita recuperar su libro, y, como voy a ser su nueva aliada, mejor me pongo manos a la obra.",
  ["Act_E2_1A_Dormitory_ChloeSMS_VoiceOver01_Max_010"] = "A pesar de la mierda que está pasando, es tan estupendo tener a Chloe en mi vida de nuevo. Como si fuera ayer...",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver01_Max_010"] = "Bueno, es hora de vestirme.",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver02_Max_020"] = "Será mejor que me vista y vaya a devolverle el libro a Kate.",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver03_Max_030"] = "Necesito vestirme antes de salir.",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver04_Max_040"] = "¡Ay, mierda! La venganza de Nathan. Hasta Chloe me dijo que no hablara con el director...",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver05_Max_050"] = "Victoria. Por supuesto. Eso me pasa por burlarme de ella... Perra.",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver07_Max_070"] = "Vamos, Max. Piensa dónde pusiste el libro la última vez...",
  ["Act_E2_1A_Dormitory_MaxRoom_VoiceOver08_Max_070"] = "¡Mierda! ¿Ahora me llegan amenazas anónimas? No tiene fin... Debe ser Nathan... pero podría ser cualquiera... Será mejor que tenga mucho más cuidado por aquí, o podría correr en grave peligro... Si es que sigue siendo seguro.",
  ["Act_E2_1A_Dormitory_Shower_VoiceOver01_Max_010"] = "Ser una superheroína es un trabajo sucio. Necesito una ducha.",
  ["Act_E2_1A_Dormitory_Shower_VoiceOver02_Max_020"] = "El rebobinar no me limpiará. Necesito una ducha.",
  ["Act_E2_1A_Dormitory_Shower_VoiceOver03_Max_030"] = "Será mejor que lleve mis productos de tocador.",
  ["Act_E2_1A_KateRoom_AbstinenceFlyer_Look01_Max_010"] = "Tal vez Kate tenga una doble personalidad... ¿Santurrona de día y fiestera de noche?",
  ["Act_E2_1A_KateRoom_AuntLetter_Look01_Max_010"] = "Ay. Se olvidó de agregar \"perdición\".",
  ["Act_E2_1A_KateRoom_Bible_Look01_Max_010"] = "Kate incluso hace anotaciones en su Biblia... Mis padres no me llevaron a una iglesia ni una sola vez. No tenía nada contra qué revelarme. Ahora no sé en qué creer...",
  ["Act_E2_1A_KateRoom_CHKate_Look01_Max_010"] = "Pobre Kate, no se ve bien...",
  ["Act_E2_1A_KateRoom_CHKate_Look02_Max_020"] = "Dios, esto es intenso. Si Kate no estaba alucinando y realmente está diciendo la verdad...",
  ["Act_E2_1A_KateRoom_ChildrenDrawings_Look01_Max_010"] = "Los dibujos de Kate son perfectos para un libro de niños. Todo se ve tan divertido y colorido y... positivo.",
  ["Act_E2_1A_KateRoom_CreepyDrawings_Look01_Max_010"] = "Dios mío. Kate debe haber entrado en una etapa \"H. R. Giger\"…",
  ["Act_E2_1A_KateRoom_FamilyPortrait_Look01_Max_010"] = "¡Cielos! Es la típica familia americana zombi.",
  ["Act_E2_1A_KateRoom_FatherPostCard_Look01_Max_010"] = "Kate realmente tiene un padre que la adora.",
  ["Act_E2_1A_KateRoom_GroupPhoto_Look01_Max_010"] = "No tenía idea de que Kate se juntaba con Alyssa y Stella...",
  ["Act_E2_1A_KateRoom_KateBook_VoiceOver03_Max_030"] = "Pausa un momento, Max. Realmente le dijiste a Kate que lo denuncie ante la Policía y el director... después de recibir una escalofriante amenaza por mensaje de texto. Ahora la Policía definitivamente va a meterte en esta mierda.",
  ["Act_E2_1A_KateRoom_KateBook_VoiceOver04_Max_040"] = "Buen trabajo, Dra. Max. No le gustó lo que tenía para decirle, pero necesitamos más pruebas de lo que pasó.",
  ["Act_E2_1A_KateRoom_KateTablet_Look01_Max_010"] = "Kate está lidiando con esta mierda del video completamente sola. Espero que su madre no la repudie...",
  ["Act_E2_1A_KateRoom_MessyClothes_Look01_Max_010"] = "La habitación de Kate suele estar impecable. Para ella, esto debe ser un chiquero...",
  ["Act_E2_1A_KateRoom_Mirror_Look01_Max_010"] = "¿Por qué cubrió el espejo? ¿No puede mirarse a sí misma?",
  ["Act_E2_1A_KateRoom_Pictures_Look01_Max_010"] = "Oye, estoy tratando de usar mis poderes para el bien.",
  ["Act_E2_1A_KateRoom_Rabbit_Look01_Max_010"] = "Es el conejo más adorable que haya visto. Apuesto que Kate es una buena madre.",
  ["Act_E2_1A_KateRoom_SistersPhoto_Look01_Max_010"] = "Casi había olvidado la sonrisa de Kate...",
  ["Act_E2_1A_KateRoom_Tissues_Look01_Max_010"] = "Es un río de lágrimas. Va a necesitar muchos pañuelos.",
  ["Act_E2_1A_KateRoom_Violin_Look01_Max_010"] = "Kate solía tocar el violín todas las mañanas... Dejó de hacerlo la semana pasada...",
  ["Act_E2_1A_KateRoom_Windows_Look01_Max_010"] = "La decoración está demasiado emo. Kate no suele ser así de sombría... solo últimamente.",
  ["Act_E2_1A_MaxRoom_Artbooks_Look01_Max_010"] = "Cartier-Bresson, Doisneau, Hamilton... ¡Los mejores!",
  ["Act_E2_1A_MaxRoom_BookRoomClean_Look01_Max_010"] = "Este libro es tan sabio y nostálgico. Tengo que leer más de Bradbury...",
  ["Act_E2_1A_MaxRoom_BookRoomSacked_Interact01_Max_020"] = "Finalmente puedo llevárselo a Kate antes de que se me haga tarde. Como si me tuviera que seguir preocupando por llegar tarde... Ahora sí que tengo todo el tiempo del mundo.",
  ["Act_E2_1A_MaxRoom_BookRoomSacked_Look01_Max_010"] = "¡Ajá, libro escurridizo! ¡Eres mío!",
  ["Act_E2_1A_MaxRoom_Desk_Interact01_Max_010"] = "Mi escritorio es un chiquero, pero... sé que no está ahí.",
  ["Act_E2_1A_MaxRoom_FacebookMeme_Look01_Max_010"] = "Gracias, Victoria. Siempre quise ser un meme. Va a publicar esta mierda por todos lados.",
  ["Act_E2_1A_MaxRoom_Katebook_Interact03_Max_010"] = "Mejor lo arreglo rápido. Kate necesita el libro, y no quiero sumarle un problema a su larga lista.",
  ["Act_E2_1A_MaxRoom_Katebook_Interact04_Max_010"] = "¡Fuera de aquí, bebida infame!",
  ["Act_E2_1A_MaxRoom_MaxBed_Interact01_Max_020"] = "Me falta tanto para ser una rebelde. Me gusta tener siempre la cama bien tendida y ordenada. Gracias, mamá.",
  ["Act_E2_1A_MaxRoom_MaxBed_Look01_Max_010"] = "Cómo me recuerda a cuando era niña. Perdón, mamá. Puedo tender mi cama cuando quiera. ¡Así es!",
  ["Act_E2_1A_MaxRoom_MaxBooks_Look01_Max_010"] = "Podría rebobinar días enteros y leer todos estos libros. ¿Encontraré alguna explicación para mi poder?",
  ["Act_E2_1A_MaxRoom_MaxCamera_Interact01_Max_020"] = "Sin sonreír. Tómate tu poder en serio.",
  ["Act_E2_1A_MaxRoom_MaxCamera_Look01_Max_010"] = "Esta foto capturará este loco momento histórico en mi vida...",
  ["Act_E2_1A_MaxRoom_MaxClothes_Interact01_Max_020"] = "Tal vez debería ponerme jeans, una camiseta, y ya. Vamos, Einstein vestía siempre igual. Y él ni siquiera podía rebobinar el tiempo.",
  ["Act_E2_1A_MaxRoom_MaxClothes_Look01_Max_010"] = "\"Buenos días, ¡ropa! Espero que hayas dormido bien... Ahora, ¿mi camiseta Gucci con la chaqueta Vuitton?\".",
  ["Act_E2_1A_MaxRoom_MaxClothes_Look02_Max_010"] = "\"Me voy a poner esas hermosas botas acordonadas para cruzar los pasillos de Blackwell con estilo... Ay, Victoria, ¡eres la reina de la moda!\".",
  ["Act_E2_1A_MaxRoom_MaxDVDS_Look01_Max_010"] = "Ahora me tengo que preguntar si estas películas se basan en historias reales...",
  ["Act_E2_1A_MaxRoom_MaxDoor_Voiceover_Max_010"] = "Espera, necesito encontrar el libro antes de ir a ver a Kate.",
  ["Act_E2_1A_MaxRoom_MaxGuitar_Look01_Max_010"] = "Mientras tanto, mi guitarra sigue descansando.",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact01_Max_020"] = "Es tan descabellado que hasta me parece lógico...",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact02_Max_030"] = "Esa teoría de los agujeros de gusano tiene todo el sentido del mundo, pero no explica que yo pueda hacer lo que ningún científico ha logrado...",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact03_Max_040"] = "Siempre pensé que esto era para locos de mierda, pero ahora ya no estoy tan segura... ¿Debería firmar?",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact04_Max_050"] = "Warren va a hacer explotar mi bandeja de entrada. Pero mientras me ayude a descifrar esto...",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Interact05_Max_060"] = "Y yo pensaba que era una fanática de Halloween. Dana sí que se lo toma en serio.",
  ["Act_E2_1A_MaxRoom_MaxLaptop_Look01_Max_010"] = "Uf, podría perderme investigando los viajes en el tiempo. El motor de búsqueda y yo ya somos uno. Si pudiera ser así de aplicada en mi tarea...",
  ["Act_E2_1A_MaxRoom_MaxNotes_Look01_Max_010"] = "No puedo mantener los ojos abiertos, pero sé que hay una explicación científica...",
  ["Act_E2_1A_MaxRoom_MaxObject01_Interact01_Max_010"] = "¡Ay, no! Me pregunto si alguna vez volveré a usar un reloj...",
  ["Act_E2_1A_MaxRoom_MaxObject02_Interact01_Max_020"] = "Sería genial hacer una reunión de amigos para jugar de verdad, en vez de jugar a la obra dramática...",
  ["Act_E2_1A_MaxRoom_MaxPlant_Interact01_Max_020"] = "Bebe... Tiene electrolitos.",
  ["Act_E2_1A_MaxRoom_MaxPlant_Interact02_Max_040"] = "Bebe... Puedo resucitarte... Tengo poder sobre la vida misma...",
  ["Act_E2_1A_MaxRoom_MaxPlant_Look01_Max_010"] = "Buenos días, Lisa. Tus hojas se ven estupendas hoy. No seré jardinera, pero me doy maña con las plantas...",
  ["Act_E2_1A_MaxRoom_MaxPlant_Look02_Max_030"] = "¡Ay, Lisa, te he dejado al borde de la sequía!",
  ["Act_E2_1A_MaxRoom_MaxSchedule_Look01_Max_010"] = "La Sra. Hoida sigue enferma. Alguien dijo que sufría de depresión severa. Pobre.",
  ["Act_E2_1A_MaxRoom_Mirror_Interact01_Max_020"] = "Vaya. Hola, cara de zombi. Esto es lo que pasa cuando uno se queda investigando sobre física cuántica toda la noche...",
  ["Act_E2_1A_MaxRoom_PhotoPanel_Look01_Max_010"] = "Esa es la única foto turística que dejé que me tomaran en la Aguja Espacial...",
  ["Act_E2_1A_MaxRoom_PhotoPanel_Look01_Max_020"] = "Fue un buen partido de hockey, una gran pelea.",
  ["Act_E2_1A_MaxRoom_PhotoPanel_Look01_Max_040"] = "Vaya, Kristen y Fernando estaban tan borrachos en el Fremont Troll...",
  ["Act_E2_1A_MaxRoom_PhotoWall_Look01_Max_010"] = "\"La pared conmemorativa de fotos de Max Caulfield\".",
  ["Act_E2_1A_MaxRoom_PostCard01_Look01_Max_010"] = "No puedo creer que ahora tenga 18 años. Tengo suerte de que mis padres me hayan permitido mantener el hábito de tomar fotos en la adultez.",
  ["Act_E2_1A_MaxRoom_Poster08_Look01_Max_010"] = "¿Man Ray los llamaría \"selfi retratos\"?",
  ["Act_E2_1A_MaxRoom_RoomSacked_Interact01_Max_020"] = "¡Ta tán! Me encanta tener la habitación ordenada. Muy zen. Salvo por ese grafiti de mierda.",
  ["Act_E2_1A_MaxRoom_RoomSacked_Look01_Max_010"] = "Mi pobre Donnie Darko... ¿Quién querría romper al hermoso Jake Gyllenhaal?",
  ["Act_E2_1A_MaxRoom_RoomSackedbyNathan_Look01_Max_010"] = "Vaya, casi que podría ser arte... si no fuera tan jodidamente enfermo y retorcido.",
  ["Act_E2_1A_MaxRoom_Scarf_Look01_Max_010"] = "Echaré de menos ir a los juegos con papá. ¡Vamos, Thunderbirds!",
  ["Act_E2_1A_MaxRoom_Search_Interact01_Max_010"] = "Ningún libro por aquí...",
  ["Act_E2_1A_MaxRoom_Search_Interact04_Max_010"] = "Y nada por aquí.",
  ["Act_E2_1A_MaxRoom_Search_Interact05_Max_010"] = "Prometo limpiar esto, si encuentro el libro.",
  ["Act_E2_1A_MaxRoom_Search_Interact06_Max_010"] = "Obvio que derramaste el refresco en el libro de Kate.",
  ["Act_E2_1A_MaxRoom_ShowelGel_Interact01_Max_020"] = "Bien, Max, ¡a la ducha!",
  ["Act_E2_1A_MaxRoom_ShowelGel_Look01_Max_010"] = "Tenemos que custodiar nuestros productos de tocador. Todo por un idiota se hizo el divertido, alteró el champú de una muchacha e hizo que se quedara calva. Tan de campamento de verano.",
  ["Act_E2_1A_MaxRoom_VictoriaPhoto_Look01_Max_010"] = "Lo admito, es muy divertido, pero... no debería rebajarme al nivel de Victoria.",
  ["Act_E2_1A_MaxRoom_VoiceOverReveal_Max_010"] = "Quedarme despierta toda la noche me dejó hecha trizas... Podría usar mi poder y dormir un poco más, pero mejor guardo mis fuerzas…",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_010"] = "Max, usa el cerebro. ¡Piensa!",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_020"] = "No se esconda de mí, Sr. Bradbury... Lo amo.",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_030"] = "Si tan solo pudiera rebobinar mi memoria...",
  ["Act_E2_1A_MaxRoom_VoiceOver_Max_040"] = "Bueno, ¿dónde puse el libro? ¡¿Dónde?!",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_010"] = "¡Hola, Max!",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_040"] = "Estoy aquí. Gracias de nuevo por haberme defendido ayer. Lo necesitaba.",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_060"] = "¿Acaso no todos aquí tienen problemas?",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_070"] = "¡Max!",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_100"] = "Sí, lamento que no hayas hecho nada para ayudar. Es que eres igual a todos aquí...",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_120"] = "Como sea, ya pasó...",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_130"] = "Por cierto, Max, ¿aún tienes mi copia de \"El país de octubre\"?",
  ["Cue_E2_1A_Bathroom_DialKate_Kate_150"] = "¿Podrías llevarla a mi habitación esta mañana, por favor? Necesito tomar unas notas para clase.",
  ["Cue_E2_1A_Bathroom_DialKate_Max_020"] = "Hola, Kate.",
  ["Cue_E2_1A_Bathroom_DialKate_Max_030"] = "¿Cómo estás?",
  ["Cue_E2_1A_Bathroom_DialKate_Max_050"] = "¡Obvio! Ese tipo tiene problemas.",
  ["Cue_E2_1A_Bathroom_DialKate_Max_080"] = "¡Oh! Ah... Hola, Kate.",
  ["Cue_E2_1A_Bathroom_DialKate_Max_090"] = "Perdón por lo de ayer.",
  ["Cue_E2_1A_Bathroom_DialKate_Max_110"] = "Eso no es cierto, quería ayudarte, pero... pero...",
  ["Cue_E2_1A_Bathroom_DialKate_Max_140"] = "Oh. Sí, por supuesto. Por ahora va genial. No sabía que Bradbury era tan poético.",
  ["Cue_E2_1A_Bathroom_DialKate_Max_160"] = "Absolutamente. Te la llevaré luego.",
  ["Cue_E2_1A_Bathroom_FaucetWater_Girl_010"] = "¡¿Hola?! ¡Agua!",
  ["Cue_E2_1A_Bathroom_FaucetWater_Max_020"] = "¡Lo siento, se me olvidó!",
  ["Cue_E2_1A_Bathroom_TakeShower_Kate_020"] = "Cosas escolares.",
  ["Cue_E2_1A_Bathroom_TakeShower_Kate_050"] = "Victoria, esa no era yo...",
  ["Cue_E2_1A_Bathroom_TakeShower_Kate_080"] = "Algún día lo lamentarás.",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_030"] = "¿Eso es todo?",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_060"] = "Ay, Dios mío. Claro.",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_100"] = "Eso parece.",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_120"] = "Ya lo creo, hermana.",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_140"] = "Eso fue muy mala onda.",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_160"] = "Sí que es un bicho raro, siempre con su cámara.",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_180"] = "Sí que eres diabólica, ¿eh? ¡Me encanta!",
  ["Cue_E2_1A_Bathroom_TakeShower_Taylor_200"] = "Fuimos corriendo...",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_010"] = "¿Qué pasa, Kate?",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_040"] = "En el video, estabas de fiesta, no haciendo la tarea...",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_070"] = "No seas tímida. Es genial que hayas marcado un récord de lengua en video...",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_090"] = "¡Bua, bua! Siento que seas una perra viral. Seguro que se divirtió.",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_110"] = "Apuesto que Nathan le consiguió algo. Y sabes que tiene mierda de la buena.",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_130"] = "Aj. Todavía tengo esa pintura de mierda en toda la cara. \"Selfi Max\" se creyó muy ruda tomando esta foto. Debería darle una paliza.",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_150"] = "Está celosa porque Mark... el Sr. Jefferson... sabe que voy a ganar el concurso Héroes Cotidianos. Piensa que Max es patética.",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_170"] = "Odio esa mierda de \"qué peculiar que soy\". Como sea. Dejemos el enlace al video de Kate para que todas puedan verla en acción...",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_190"] = "Qué asco. Todavía tengo esa pintura de mierda en la cara. Menos mal que mis secuaces se no se apresuraron en traer una toalla...",
  ["Cue_E2_1A_Bathroom_TakeShower_Victoria_210"] = "Olvídalo, Taylor. Ahora sé que, si tengo un accidente, no puedo contar contigo ni con Courtney. Puedes juntarte con Kate... o Max.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_001"] = "Está bien, Max. Es la segunda vez que me salvas de un proyectil. ¿Eres mi ángel de la guarda?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_004"] = "Vaya, eso sí que es pensar rápido, Max.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_007"] = "A Blackwell le sobran idiotas.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_009"] = "Warren y tú sí que saben de ciencia ficción. Ten cuidado, Brooke podría ponerse celosa...",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_010"] = "Por cierto, Warren dijo que te prestó su memoria USB de películas. No sabía que también eras una fanática de la ciencia ficción. ¿Cuál es tu favorita?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_011"] = "¿Te imaginas lo que sería viajar al pasado y estar en el Blackwell de los años ochenta?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Alyssa_013"] = "Apenas tengo ganas de que el tiempo siga avanzando, muchas menos de retroceder.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_003"] = "Ah, hola de nuevo, Alyssa.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_005"] = "Para nada, solo tengo un sexto sentido para los problemas. Me alegra poder ayudarte.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_006"] = "Me alegra que mis habilidades psíquicas te hayan salvado de ese ataque higiénico.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_014"] = "Me encanta \"Volver al futuro\", por supuesto. Pero a quién no, ¿verdad?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_015"] = "Me encanta la idea de retroceder en el tiempo para corregir errores como en \"El día de la marmota\".",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_016"] = "\"Looper\" es genial. Sí que te jode la cabeza. Todavía estoy tratando de entenderla...",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_018"] = "Nos ahogaríamos con toda la laca que utilizaban.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_020"] = "Definitivamente. Pero todo está en las elecciones que tomes ahora.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase01_Max_021"] = "Haré de cuenta que no tengo idea de lo que hablas.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase02_Alyssa_002"] = "Idiotas inmaduros... Lo siento, Max. No estoy de humor para conversar ahora.",
  ["Cue_E2_1A_Corridor_CHAlyssa_Phase02_Max_001"] = "¿Estás bien, Alyssa?",
  ["Cue_E2_1A_Corridor_CHAlyssa_Quick01_Alyssa_001"] = "Max, hablemos luego. ¡Suerte con Warren!",
  ["Cue_E2_1A_Corridor_CHAlyssa_Quick01_Alyssa_002"] = "En serio, Max. No quiero hablar.",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_002"] = "Ah, hola, Max.",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_008"] = "Me quedé asombrada con la extraña nieve de ayer.",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_009"] = "Lo digo en serio. Ni los meteorólogos pueden explicar la nieve. Seguro que Warren puede. ¿Ya has hablado con él?",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_015"] = "Cierto. Y a Warren le encanta hablar de meteorología conmigo porque soy una de las pocas personas con las que puede tener una conversación real. Hablamos más tarde, Max.",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Brooke_016"] = "Qué suerte tienes. Seguro te encontrará, Max. Nos vemos.",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_001"] = "Hola, Brooke.",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_003"] = "¿Viste esa nevada extraña ayer?",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_004"] = "Pareces distraída. ¿Todo bien?",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_005"] = "No entiendo si me estás hablando en serio o no... Mmm, como soy un cero en ciencia pensé que podrías explicarme algo...",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_013"] = "No, para nada. Es mi amigo, no mi madre.",
  ["Cue_E2_1A_Corridor_CHBrooke_Phase02_Max_014"] = "Luego.",
  ["Cue_E2_1A_Corridor_CHBrooke_Quick02_Brooke_001"] = "No tengo tiempo, Max. No puedo hablar ahora.",
  ["Cue_E2_1A_Corridor_CHBrooke_Quick02_Brooke_002"] = "¿En serio, Max?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_001"] = "Oye, Max. ¿Ya viste el video picante de Kate?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_004"] = "Yo no fui la que se emborrachó en cámara y estuvo con todos los miembros del club Vortex.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_005"] = "Porque es divertido, carajo. \"La santurrona se vuelve salvaje\".",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_007"] = "¿En serio? Mírala y ahí me dices.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_009"] = "Touché. Ahora me siento terrible. Gracias por descubrir la verdad ayer.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_013"] = "Nada... por el momento. Mi mente también puede ser retorcida.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_014"] = "Cuando se porta como un gusano, dejo que se retuerza.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_015"] = "No contigo. Parte de mí casi que estaba decepcionada; había acumulado tanta rabia.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_017"] = "Tienes un buen corazón, Max. Y no volveré a ver el video de Kate. Ni lo pasaré.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Juliet_019"] = "Seguro, hablamos más tarde.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_002"] = "Es tan mala onda.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_003"] = "¿Por qué debería?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_006"] = "Kate no es así, y lo sabes.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_008"] = "¿Crees todo lo que ves? ¿Cómo que Zachary le mandaba mensajes sexuales a Dana?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_010"] = "¿Qué hiciste sobre Victoria y su forma de actuar de mierda?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_011"] = "¿Estás segura? Pensé que estarías enojada...",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_012"] = "¿Y Zachary? ¿Lo perdonaste?",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_016"] = "Me alegra saber que volviste al ruedo.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_018"] = "¡Esa es la actitud! Gracias, Juliet.",
  ["Cue_E2_1A_Corridor_CHJuliet_Phase01_Max_020"] = "Hola, Juliet.",
  ["Cue_E2_1A_Corridor_CHJuliet_Quick01_Juliet_001"] = "No voy a ver el video, Max.",
  ["Cue_E2_1A_Corridor_CHJuliet_Quick01_Juliet_002"] = "Disculpa, estoy enviándole un texto a Zach.",
  ["Cue_E2_1A_Corridor_CourtneyHomework_Courtney_020"] = "Sí, por supuesto, Victoria. Te llevaré los exámenes y la tarea esta tarde. Obvio que me encargo. Considéralo hecho.",
  ["Cue_E2_1A_Corridor_CourtneyHomework_Victoria_010"] = "Courtney, en serio, no olvides que necesito la tarea antes de esta noche. Más bien, ¡para ayer! Gracias, dulce.",
  ["Cue_E2_1A_Corridor_KateVideo_Brooke_020"] = "No pensé que Kate fuera así... ¿Seduciendo a esos tipos? Puaj.",
  ["Cue_E2_1A_Corridor_KateVideo_Brooke_040"] = "Ya lo deben haber visto todos...",
  ["Cue_E2_1A_Corridor_KateVideo_Juliet_010"] = "Qué asco. Los miembros del club Vortex son tan asquerosos. Me alegra haberlos molestado.",
  ["Cue_E2_1A_Corridor_KateVideo_Juliet_030"] = "No deberíamos estar viendo esto...",
  ["Cue_E2_1A_Corridor_Knock02_Kate_020"] = "Sí, aquí estoy. Entra, Max...",
  ["Cue_E2_1A_Corridor_Knock02_Max_010"] = "¿Kate? ¿Estás ahí?",
  ["Cue_E2_1A_Corridor_Warn_Alyssa_Alyssa_020"] = "Ah, bueno, Max. Si te hace feliz...",
  ["Cue_E2_1A_Corridor_Warn_Alyssa_Alyssa_030"] = "Vaya, eso estuvo cerca. Gracias, Max.",
  ["Cue_E2_1A_Corridor_Warn_Alyssa_Max_010"] = "Alyssa, ¿podrías pararte ahí?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_002"] = "No, Max. No te odio. No es que no me gusten los chismes jugosos... Pero me gustaría que no fueras tan entrometida.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_005"] = "O es un don. Se te da muy bien lo de ser entrometida.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_009"] = "Al menos nos estamos mostrando juntos en público... Así que, sin duda, deberías ir con nosotros. Toma uno de mis vestidos y ven con tu esclavo Warren como la pareja friki perfecta...",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_021"] = "Por cierto, la noticia más jugosa del día es que Trevor me invitó a ir con él a la juerga de Halloween.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_036"] = "Mucho mejor que ayer. Me alegra que hayamos hablado.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_037"] = "Ah, sí. Gracias de nuevo por liberarme del cautiverio.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_041"] = "Es casi como si fueras una vidente. Tenía la impresión de que ya sabías todo...",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_042"] = "Normalmente me reiría, pero en verdad me salvaste ayer. Así que digamos que estamos a mano.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_052"] = "No dejes que se te pase la vida, Max. ¿Vienes a la fiesta o no?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_056"] = "¡Esa es la actitud, Max! Después, estarás lista para un reventón...",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Dana_057"] = "Viniste a Blackwell para descubrir quién eres, no para esconderte en tu habitación.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_001"] = "Oh, hola, Dana. ¿Me odias?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_003"] = "Es mi peor defecto.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_007"] = "¿Sí? No quiero entrometerme...",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_022"] = "Eso es genial, Dana.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_034"] = "Hola, Dana. ¿Cómo estás?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_035"] = "¿Qué pasa, Dana? ¿Está todo bien entre Juliet y tú?",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_038"] = "Porque me importa.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_039"] = "A mí también. Sé que es bueno que hablemos... de estas cosas.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_044"] = "Eh, no soy buena con los disfraces.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_049"] = "No voy a descubrir quién soy esquivando vómitos de tipos. Pero gracias.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_053"] = "¿Por qué no? Si no me gusta, siempre puedo regresar... a mi habitación.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_054"] = "No, lo siento. Es que... no es lo mío.",
  ["Cue_E2_1A_DanaRoom_CHDana_Phase01_Max_055"] = "En verdad, suena divertido. Ahora debo ir a meditar sobre mi futuro de fiestas...",
  ["Cue_E2_1A_DanaRoom_CHDana_Quick01_Dana_001"] = "Hablemos luego, Max.",
  ["Cue_E2_1A_KateRoom_Believe_Kate_020"] = "Dios te bendiga, Max. Hablaré con la Policía... y también con el director Wells. Teniéndote a ti como testigo, deberán tomarnos en serio.",
  ["Cue_E2_1A_KateRoom_Believe_Kate_040"] = "¿Por qué? ¿Cuidado de qué?",
  ["Cue_E2_1A_KateRoom_Believe_Max_010"] = "Sí, definitivamente deberías hablar con la Policía, Kate. Estoy convencida de que estás diciendo la verdad. Nathan Prescott es muy peligroso.",
  ["Cue_E2_1A_KateRoom_Believe_Max_030"] = "¿Testigo? Bueno... quiero decir... te creo y todo pero... para la Policía y los profesores, no somos más que unas niñas chifladas... Creo que debemos tener mucho cuidado...",
  ["Cue_E2_1A_KateRoom_Believe_Max_050"] = "Nada... solo que los Prescott son una familia poderosa. Es solo que no quiero que nos salga el tiro por la culata. Aunque ese maldito ricachón ya se ha ganado una buena dosis de mal karma. Lo recibirá...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_001"] = "Max, ¿por qué ayer te interpusiste entre David y yo?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_002"] = "Max, ¿por qué no hiciste nada ayer cuando David me estaba acosando?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_008"] = "Sí, debería. Al menos es lindo saber que tú te preocupas por mí…",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_009"] = "No espero que te metas en problemas por mí. Es solo que siento que a nadie le importa...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_010"] = "Pensé que él era diferente. Me alegra saber que alguien se preocupa por mí...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_011"] = "Podrías haber decidido no meterte. Parece que todos aquí solo se preocupan por sí mismos...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_013"] = "Bueno...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_014"] = "¡Es un imbécil paranoico! Piensa que soy parte del club Vortex. Sí, claro.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_018"] = "Ni siquiera puedo verlo, Max.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_019"] = "Fui a una fiesta del club Vortex, muy a mi pesar. No es para nada lo mío.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_020"] = "Porque vio el video.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_023"] = "Gracias, Max.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_024"] = "¿Estás bromeando?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_025"] = "¿Tienes idea de lo humillante que es para mí?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_033"] = "Básicamente, fui a una fiesta del club Vortex y terminé besuqueando a un montón de gente... y no recuerdo nada...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_037"] = "¿Un fallo de cordura? Pensé que podría conocer gente nueva.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_038"] = "No fue así.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_039"] = "Es una larga historia. Todavía sigo tratando de juntar las piezas...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_041"] = "Juro por Dios que solo tomé un trago de vino tinto. Y luego bebí agua.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_044"] = "Yo no me emborracho. Nunca.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_045"] = "Bebo un sorbo en la iglesia y no termino en un video viral, ¿está bien?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_048"] = "Recuerdo... Recuerdo sentirme mal y mareada...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_049"] = "Y Nathan Prescott dijo que me llevaría al hospital...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_054"] = "Fue bueno conmigo, para variar, cuando se ofreció a ayudarme.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_055"] = "Definitivamente no. No sé bien adónde me llevó...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_056"] = "Suficientemente mal como para necesitar un doctor. Pensé que me iba a morir, Max.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_061"] = "Lo único que recuerdo es viajar en auto un rato largo... luego me desperté en una habitación... Pensé que era un hospital, porque todo era muy blanco y había mucha luz...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_065"] = "¡Eso es todo lo que recuerdo! No sé qué ocurrió... Al día siguiente, desperté en la puerta de mi habitación. No tenía marcas ni moretones, pero me sentía sucia.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_066"] = "Por supuesto, ¿crees que estoy inventando toda esto? ¿Por qué?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_069"] = "No tengo idea. Victoria, seguro. Estaba ahí, diabólica, como de costumbre.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_071"] = "¿Cómo hago para eliminar un video viral? Sé que ya se está propagando por todos lados. ¿Y si lo ven en mi iglesia? Tengo que hacer algo... ¿pero qué?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Kate_077"] = "Alguien me hablaba en voz baja... Pensé que era un doctor... hasta que escuché a Nathan y sentí un pinchazo en el cuello... y... y...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_003"] = "Continúa, te escucho.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_004"] = "Odio a los acosadores. David Madsen debería ser más consciente.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_005"] = "Lo siento. Estaba asustada. Puedo ser bastante cobarde.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_006"] = "Quería una prueba de que David estaba siendo agresivo.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_007"] = "No tenía otra opción. David Madsen es un imbécil.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_012"] = "Kate, de verdad me importas. ¿Qué pasa entre David y tú?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_015"] = "¿Qué pasa con el video? Y juro que no lo he visto.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_016"] = "¿Te fuiste de fiesta con ellos?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_017"] = "¿Por qué piensa eso?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_021"] = "Yo tampoco lo haré.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_022"] = "¿Debería verlo? ¿Para la... posteridad?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_026"] = "Sé que esto apesta, Kate, pero... cuéntame del video y tal vez pueda ayudarte.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_034"] = "¿Por qué fuiste?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_035"] = "No es propio de ti. No te imagino de fiesta con Victoria...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_036"] = "Eso es terrible. ¿Cómo fue que pasó?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_040"] = "Tienes que decirme más que eso. ¿Qué pasó en la fiesta? ¿Bebiste?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_042"] = "No lo suficiente como para emborracharte, ¿verdad?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_043"] = "¿Estás segura de que fue solo un sorbo?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_046"] = "¿Acaso alguien te drogó?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_047"] = "Continúa...",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_050"] = "¿Nathan Prescott? ¡Ay, mierda!",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_052"] = "¿Qué tan mal te sentías?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_053"] = "¿Fuiste?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_058"] = "Es todo lo contrario a bueno. ¿Y luego?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_059"] = "¿Entonces Nathan no te llevó a la sala de emergencias?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_060"] = "¿Qué recuerdas de eso?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_063"] = "¿Y?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_067"] = "No, solo... estoy deduciendo. Como siempre. ¿Y qué pasó luego?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_068"] = "¿Quién grabó tu video en la fiesta?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_070"] = "Dios, Kate. Lo siento. Esto sí que es una gran mierda.",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_072"] = "Kate, vamos a resolverlo. Volveré más tarde, ¿de acuerdo?",
  ["Cue_E2_1A_KateRoom_CHKate_Phase01_Max_076"] = "¿Estás segura?",
  ["Cue_E2_1A_KateRoom_DialKate_Kate_020"] = "Gracias, Max... Puedes dejar mi libro ahí, cerca de mi bolso.",
  ["Cue_E2_1A_KateRoom_DialKate_Max_010"] = "Eh, hola, Kate. Traje tu libro...",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_020"] = "Pero sé que me drogaron...",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_040"] = "Me haces sentir tan desesperanzada...",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_060"] = "Parece imposible en este punto. ¿Esa es tu respuesta?",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Kate_080"] = "Pero no ahora. Solo tendré que seguir soportando que la gente me llame puta viral por los pasillos. Gracias, Max.",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_010"] = "Si lo haces, no te creerán. Estás en un video con todos esos tipos... lo usarán en tu contra. Es malo.",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_030"] = "Eso es lo que tú debes demostrar. No ellos. Solo te estoy diciendo cómo la Policía y la escuela verán este asunto. El video no es algo que precisamente te ayude...",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_050"] = "No, no, Kate. Es solo que no quiero que te sigan lastimando...",
  ["Cue_E2_1A_KateRoom_DontBelieve_Kate_Max_070"] = "Creo que debemos esperar. Están pasando algunas cosas que podrían ayudarte.",
  ["Cue_E2_1A_KateRoom_KateBook_Kate_010"] = "Max, ¿puedo hacerte una pregunta? Sé sincera, por favor.",
  ["Cue_E2_1A_KateRoom_KateBook_Kate_030"] = "Necesito averiguar si Nathan Prescott me ayudó... o si me lastimó después de la fiesta.",
  ["Cue_E2_1A_KateRoom_KateBook_Kate_050"] = "¿Debería ir a la policía?",
  ["Cue_E2_1A_KateRoom_KateBook_Max_020"] = "Por supuesto, Kate. Lo que sea.",
  ["Cue_E2_1A_KateRoom_KateBook_Stella_010"] = "¡Baja el chingado volumen! ¡Hay gente tratando de dormir!",
  ["Cue_E2_1A_KateRoom_KateBook_Stella_020"] = "¡Lárgate! ¡Hay gente tratando de dormir!",
  ["Cue_E2_1A_MaxRoom_FindRoomSacked_Max_010"] = "¡Mierda!",
  ["Cue_E2_1A_MaxRoom_FindRoomSacked_Max_020"] = "No vine a Blackwell para esto. ¿Y encima tengo que limpiar toda esta mierda?",
  ["Cue_E2_1A_MaxRoom_FindRoomSacked_Max_030"] = "Después de encontrar el libro de Kate...",
  ["Act_E2_1B_CampusB_Birds_Look01_Max_010"] = "Las aves se juntan alrededor de Samuel...",
  ["Act_E2_1B_CampusB_BrokenWindow_Look01_Max_010"] = "Mierda, la ventana sigue rota desde que le advertí a Alyssa de la pelota invasora. Una nimiedad lo cambió todo para esa ventana...",
  ["Act_E2_1B_CampusB_CHSamuel_Look01_Max_010"] = "Ah, allí está Samuel. Se despertó temprano y ya está conversando con los animalejos…",
  ["Act_E2_1B_CampusB_CHSquirrel_VoiceOver_Max_010"] = "Si me acerco al banco, seguro que la ardilla deja de comer.",
  ["Act_E2_1B_CampusB_CHTaylor_Look01_Max_010"] = "Creo que nunca había visto a Taylor por su cuenta, sin el séquito de Victoria.",
  ["Act_E2_1B_CampusB_CHTaylor_Look02_Max_020"] = "Bueno, esa charla no fue un desastre total. Dale una oportunidad a la paz...",
  ["Act_E2_1B_CampusB_CHWarren_Look01_Max_010"] = "Warren también ya está listo para el día. Parece que está esperando a alguien.",
  ["Act_E2_1B_CampusB_CHWarren_Look02_Max_020"] = "Ese chico me hace morir de la risa. Me alegra que esté de mi lado.",
  ["Act_E2_1B_CampusB_FootBall_Look01_Max_010"] = "Blackwell podría tener al menos una \"zona libre de fútbol\"...",
  ["Act_E2_1B_CampusB_MPA04_Look01_Max_010"] = "Veo que Samuel está preocupado, pero... ¿necesita un cartel?",
  ["Act_E2_1B_CampusB_Object01_Look01_Max_010"] = "Nunca había visto a Samuel con lentes de sol... ¿y qué es esta basura?",
  ["Act_E2_1B_CampusB_Pipe_Look01_Max_010"] = "Definitivamente no voy a volver a jugar con esto...",
  ["Act_E2_1B_CampusB_Plaque_Look01_Max_010"] = "\"Residencia estudiantil Prescott\". ¡Dios mío! ¡¿La familia de Nathan es dueña de mi residencia?!",
  ["Act_E2_1B_CampusB_RachelPhotos_Look01_Max_010"] = "¿Cómo hizo Samuel para tener fotos con poses de Rachel?",
  ["Act_E2_1B_CampusB_Scaffolding_Look01_Max_010"] = "La pintura se ve genial. Samuel sí que sabe de colores.",
  ["Act_E2_1B_CampusB_Squirrel_Interact01_Max_010"] = "¡Sí! ¡Otro Pulitzer para mi carpeta!",
  ["Act_E2_1B_CampusB_Squirrel_Look01_Max_010"] = "Vaya, es difícil acercarse a una ardilla...",
  ["Act_E2_1B_CampusB_Tools_Look01_Max_010"] = "Samuel debería dejar esto bajo llave. De verdad. Es un accidente a punto de suceder. Y es demasiado fácil meterse...",
  ["Act_E2_1B_CampusB_Totem_Look01_Max_010"] = "Warren me dijo que el tótem se llama \"Tobanga\" por una razón que nadie conoce.",
  ["Act_E2_1B_CampusB_TrashFood_Interact01_Max_010"] = "¡Liberen al kraken! Vamos, ardillita, es hora de tu 15 min de fama...",
  ["Act_E2_1B_CampusB_TrashFood_Look01_Max_010"] = "¿Es tan difícil tirar la basura en el cesto? Pero podría usarlo para atraer a las ardillas...",
  ["Act_E2_1B_CampusB_VoiceOver01_VoiceOver_Max_010"] = "Debo ir al campus principal para tomar el autobús. Chloe me está esperando en el restaurante.",
  ["Act_E2_1B_CampusB_VoiceOver02_VoiceOver_Max_020"] = "Debo ir al campus principal para tomar el autobús e ir al restaurante. Chloe me está esperando.",
  ["Act_E2_1B_CampusB_VoiceOver03_VoiceOver_Max_030"] = "Blackwell es tan tranquilo temprano en la mañana...",
  ["Act_E2_1B_CampusB_VoiceOver04_VoiceOver_Max_040"] = "El campus está lleno de posibles fotografías...",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_001"] = "Hola, Samuel, te despertaste temprano.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_003"] = "Realmente me encanta eso de Arcadia Bay, los hermosos animales del bosque.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_007"] = "No te rías, pero... vi una venada que parecía estar mirándome... como si estuviera tratando de decirme algo...",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_015"] = "Lo de siempre... Ya sabes.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_017"] = "¿Qué opinas de la extraña nevada de ayer?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_021"] = "No quiero entrometerme, Samuel, pero... ¿por qué tienes fotos de Rachel Amber en tu cobertizo? Me intriga...",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_025"] = "¿Pero la conocías?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_027"] = "Oh. Hablaste con la Policía. Rachel quería ser modelo.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_028"] = "Conozco a personas que sí. Personas que la están buscando.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_030"] = "No es un misterio que tengas sus fotos...",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_034"] = "No quiero interrumpir tu ritual matutino. Hasta luego.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_040"] = "Hola, de nuevo, Samuel.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_042"] = "Entonces, ¿la conocías?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Max_043"] = "Conozco a personas que la querían. Personas que la están buscando.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_002"] = "Oh, hola, joven Max. Me encantan las primeras horas del día. Todo está tan calmado y tranquilo... y siento que los animales se despiertan conmigo.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_004"] = "Las ardillas siempre vienen por la mañana... a buscar comida. Puedo oír que me susurran... ¿Qué animales viste en el bosque?",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_008"] = "¡Ah, es tu animal espiritual! No es para nada extraño, solo que viste al tuyo. Podría ser una señal acerca de tu destino... ¿Qué voy a saber? Mi animal espiritual es una ardilla.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_016"] = "Parece que sabes más.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_020"] = "Otra advertencia de la Tierra para que nos dejemos de fregaderas. Diría que Samuel nunca había visto algo así...",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_022"] = "\"Disculpa que me entrometa\", dice ella mientras lo hace. Ahora todo el mundo quiere saber de ella.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_026"] = "Como le dije a la Policía, era una buena chica. Y me dio esas fotos.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_029"] = "Si es que se la puede encontrar. Como tú, esa es la naturaleza del misterio.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_031"] = "Sí. Repartía sus fotos a todo el mundo, como las ardillas cuando buscan la comida. Sigue entrometiéndote, Max. Parece que tienes todo el tiempo del mundo...",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_035"] = "Por supuesto que sí.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase01_Samuel_041"] = "Hola de nuevo, Max.",
  ["Cue_E2_1B_CampusB_CHSamuel_Phase02_Samuel_001"] = "Cuídate, Max... y sigue escuchando a los animales.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_001"] = "Hola, Taylor...",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_004"] = "No quiero pelear ni contigo ni con Victoria. En lugar de tratarnos mal... solo hablemos. Para variar.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_006"] = "Kate está muy alterada por lo del video... Todos esos chismes son muy crueles.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_008"] = "¿Por qué te juntas con Victoria? Se porta bastante mal contigo y con Courtney.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_010"] = "Supongo que yo también he tenido amigos malos y mandones. Es mejor que tener padres malos y mandones...",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_012"] = "No importa, Taylor.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_014"] = "Me enteré que tu madre estaba enferma. Lo siento mucho. ¿Qué...? ¿Qué le pasó?",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_016"] = "Lo sé. Por eso quería hablar.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Max_027"] = "Bueno, perdón por existir, Taylor.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_002"] = "¿Cómo se te ocurre venir a hablar conmigo después de la mierda de ayer con Victoria?",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_003"] = "\"Hola, Taylor\". Que hayas sido buena con Victoria no quiere decir que ahora yo lo sea contigo.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_005"] = "Qué graciosa. Pero, bueno, no estoy haciendo nada por el momento... así que hablemos.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_007"] = "Ay, qué pena. Eso es lo que pasa cuando sermoneas a los demás sobre el sexo. Lo superará.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_009"] = "¡Y es tan mandona! Mira, no la conoces. Yo sí. Y es una de las mejores amigas que podría tener.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_011"] = "Ojalá mi mamá fuera mala o mandona, en vez de estar enferma... pero qué importa. Ya charlamos.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_013"] = "Fue una linda charla, Max. Que no se vuelva a repetir. Ahora, si me disculpas...",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_015"] = "Bueno, si de verdad quieres saber... Mamá tuvo una cirugía de espalda. Victoria me apoyó en todo momento. Como tú con Kate. Destruir a la gente no es lo mío, Max.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_017"] = "Me alegra... que lo hayamos hecho.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase01_Taylor_028"] = "En eso estamos de acuerdo. ¿Te importaría? ¿Irte? Gracias.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase02_Max_001"] = "¿Taylor?",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase02_Taylor_002"] = "La plática terminó.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase03_Max_001"] = "Hola de nuevo, Taylor.",
  ["Cue_E2_1B_CampusB_CHTaylor_Phase03_Taylor_002"] = "Oye. Esa plática no estuvo tan mal. Que se repita. Hasta luego.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_002"] = "Warren, ¿qué haces aquí?",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_005"] = "Por cierto, gracias por intervenir. Estuviste muy rudo, Warren. Te debo una.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_007"] = "Fue intenso. Todo pasó tan rápido. Te debo una.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_009"] = "Eres un \"Héroe cotidiano\" de verdad. Te enfrentaste a un bravucón, y fue genial.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_010"] = "Una vieja amiga. ¿Chloe Price? Hace tiempo que no nos veíamos.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_015"] = "Una pirata que solía conocer.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_018"] = "Ayer lo pesqué en el baño con un arma. No pude decirle nada al director Wells de lo asustada que estaba. No digas nada, por favor. Luego te cuento más.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_022"] = "Ayer lo pesqué en el baño con un arma. Luego te cuento la historia completa. El director Wells ya se está encargando de eso, espero.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_028"] = "Es peligroso. No quiero que te involucres. Me ayudaste, pero mantente al margen de esto. Pronto el karma se encargará de Nathan Prescott.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_036"] = "Sí, es justo lo que necesito. Me encantan esas películas retro de simios.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Max_040"] = "No, no creo que pueda concentrarme en una película. Solo tengo ganas de escaparme.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_001"] = "Oh, nada. Estoy esperando. ¿Una llamada? Es decir, ya contesté la llamada... Como sea. Quería hablar de lo que pasó ayer.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_006"] = "Oh, sí que me la debes. Ese idiota me dio una paliza. Soy como un superhéroe personal.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_016"] = "Seguro te gustó verla acelerar en esa camioneta como toda una estrella de rock. Lo que lleva a la pregunta... ¿Por qué Nathan Prescott se puso psicópata contigo?",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_031"] = "Pinche semana extraña. Como esa nevada de ayer. Hablando de distopías, en el autocinema pasarán una maratón de \"El planeta de los simios\" de los años setenta. ¡Volvámonos simios!",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_037"] = "Bueno, eso fue más fácil de lo que esperaba. Estupendo. Te enviaré los datos por texto.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_041"] = "De acuerdo. Sigue siendo una mugrosa humana. Me volveré simio solo.",
  ["Cue_E2_1B_CampusB_CHWarren_Phase01_Warren_044"] = "Aunque me dejaste con el bravucón y te fuiste corriendo con la chica esa... Es bastante \"punk rock\", ¿de dónde la conoces?",
  ["Cue_E2_1B_CampusB_CHWarren_Phase02_Warren_001"] = "Debo decirle a Brooke que iré contigo al cine en su lugar. ¿Te escribo más tarde?",
  ["Cue_E2_1B_CampusB_CHWarren_Phase03_Warren_001"] = "Eh, tengo que ver si Brooke quiere ir al autocinema, Max. Tal vez te vea luego.",
  ["Cue_E2_1B_CampusB_MeetWarren_IGE_Max_010"] = "Hola, Warren, ¿qué haces aquí?",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_010"] = "¡Max! ¡Mira esto!",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_020"] = "Max, ven aquí.",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_030"] = "¡Max! ¡Ven aquí!",
  ["Cue_E2_1B_CampusB_WarrenLoop_Warren_040"] = "¿Qué dices, Max? ¿Cómo estás?",
  ["Act_E2_1C_CampusA_VoiceOver01_Max_010"] = "¡Al fin! Un poco de tiempo para mí. Necesito distraerme con un poco de música...",
  ["Act_E2_1C_CampusA_VoiceOver02_Max_010"] = "David y Nathan hablando... eso no puede ser bueno. Seguro tiene que ver con Kate... o Rachel...",
  ["Act_E2_2A_Diner_AfterFrank_VoiceOver01_Max_010"] = "Ese hombre y su perro me dieron escalofríos...",
  ["Act_E2_2A_Diner_CHCop_Look01_Max_010"] = "Ese policía parece más agradable que ese imitador barato de David Madsen...",
  ["Act_E2_2A_Diner_CHDinerFemale01_Look01_Max_010"] = "Parece ocupada y estresada.",
  ["Act_E2_2A_Diner_CHDinerFemale02_Look01_Max_010"] = "Siempre me pregunto qué piensa la gente cuando come sola.",
  ["Act_E2_2A_Diner_CHDinerMale01_Look01_Max_010"] = "Puaj, ese tipo se ve desagradable...",
  ["Act_E2_2A_Diner_CHDinerMale02_Look01_Max_010"] = "Seguro que ha visto muchos cambios en Arcadia Bay durante su vida...",
  ["Act_E2_2A_Diner_CHFisherman01_Look01_Max_010"] = "Es el arquetipo de un pescador malhumorado de Arcadia Bay...",
  ["Act_E2_2A_Diner_CHFisherman02_Look01_Max_010"] = "Estos pescadores son de lo más callados...",
  ["Act_E2_2A_Diner_CHHomeless_Look01_Max_010"] = "Pobre mujer. Espero que haya un refugio para ella.",
  ["Act_E2_2A_Diner_CHHomeless_Look02_Max_010"] = "Apuesto que ha visto muchos cambios en Arcadia Bay... y muchos secretos...",
  ["Act_E2_2A_Diner_CHJustin_Look01_Max_010"] = "Justin es muy relajado.",
  ["Act_E2_2A_Diner_CHNewsPaperMan_Look01_Max_010"] = "Los periódicos pronto van a ser retro...",
  ["Act_E2_2A_Diner_CHTrevor_Look01_Max_010"] = "Trevor se ve tan feliz como Dana...",
  ["Act_E2_2A_Diner_CHTrucker01_Look01_Max_010"] = "Los camioneros tienen una vida tan romántica, siempre viajando...",
  ["Act_E2_2A_Diner_CHTrucker02_Look01_Max_010"] = "No duraría ni un día como camionera. Esos remolques son demasiado enormes.",
  ["Act_E2_2A_Diner_Carving_Look01_Max_010"] = "Grafiti nerd. Warren debe haber estado aquí.",
  ["Act_E2_2A_Diner_ChloeStuff_Look01_Max_010"] = "Bien, Max, ¡analiza cada objeto detenidamente y no te olvides de nada!",
  ["Act_E2_2A_Diner_Coffee_Interact01_Max_010"] = "Esto es como un deja vu en cuatro dimensiones... Sigo retrocediendo en el tiempo...",
  ["Act_E2_2A_Diner_Coffee_Look01_Max_010"] = "Ay, sí, café negro, serás mío...",
  ["Act_E2_2A_Diner_CounterFood_Look01_Max_010"] = "Baba. Quiero todo.",
  ["Act_E2_2A_Diner_DinerMenu_Look01_Max_010"] = "Lo único que ha cambiado en el menú son los precios...",
  ["Act_E2_2A_Diner_DinerSign_Look01_Max_010"] = "Ese letrero me recuerda tantas veces que comimos con Chloe y mi familia... cuando éramos felices.",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_010"] = "Graba los objetos en tu mente, Max.",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_020"] = "Enmarca cada objeto como si fuera una fotografía, Max.",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_030"] = "Estás lista, Max. ¡Ahora rebobina y deja a Chloe boquiabierta!",
  ["Act_E2_2A_Diner_Divination_VoiceOver01_Max_040"] = "Debes observar los objetos y rebobinar para que Chloe te crea.",
  ["Act_E2_2A_Diner_FishermanPetitionStand_Look01_Max_010"] = "Cuántos volantes. Lástima que nadie los vaya a leer...",
  ["Act_E2_2A_Diner_FishingWallOfFame01_Look01_Max_010"] = "Me había olvidado del Muro de los Pescadores...",
  ["Act_E2_2A_Diner_Flyer01_Look01_Max_010"] = "Tal vez le diga a Chloe que lo veamos juntas.",
  ["Act_E2_2A_Diner_Flyer02_Look01_Max_010"] = "Este tipo sí que tiene huevos.",
  ["Act_E2_2A_Diner_Flyer03_Look01_Max_010"] = "¿Soy yo o eso no suena ni remotamente divertido?",
  ["Act_E2_2A_Diner_FrankRVWindow_Look01_Max_010"] = "Claramente, nadie me hizo caso.",
  ["Act_E2_2A_Diner_FrankRV_Look01_Max_010"] = "Ahí está esa caravana mugrienta del otro día...",
  ["Act_E2_2A_Diner_Graffiti01_Look01_Max_010"] = "Ese grafiti ha estado aquí desde siempre...",
  ["Act_E2_2A_Diner_Graffiti03_Look01_Max_010"] = "Qué asco.",
  ["Act_E2_2A_Diner_Graffiti05_Look01_Max_010"] = "Gracias, poeta pueblerino.",
  ["Act_E2_2A_Diner_GumballStand_Look01_Max_010"] = "Oh, Dios. Apuesto que es la misma goma de mascar de la última vez que estuve aquí...",
  ["Act_E2_2A_Diner_Jukebox_Interact01_Max_010"] = "\"I Got You Babe\". Qué oportuno... Pero de ninguna manera.",
  ["Act_E2_2A_Diner_KateChoicePhone_VoiceOver01_Max_010"] = "Es una mierda que Chloe y Joyce discutan...",
  ["Act_E2_2A_Diner_KateChoicePhone_VoiceOver02_Max_020"] = "Espero que Kate no se haya enojado porque no le contesté...",
  ["Act_E2_2A_Diner_MaxFood_VoiceOver01_Max_010"] = "Me encanta la deleitosa anticipación del desayuno...",
  ["Act_E2_2A_Diner_MiscObject01_Look01_Max_010"] = "Me compraría una camiseta, pero son tan de turista.",
  ["Act_E2_2A_Diner_MiscObject02_Look01_Max_020"] = "¡Vaya, Ken Kesey con Joyce! Es tan perfecto.",
  ["Act_E2_2A_Diner_NewsPaperBox_Interact01_Max_010"] = "\"Nieve\". Bueno, es un buen comienzo para el artículo...",
  ["Act_E2_2A_Diner_NewsPaperBox_Look01_Max_010"] = "Me pregunto si pudieron explicar la nieve...",
  ["Act_E2_2A_Diner_OffBus_VoiceOver01_Max_010"] = "Hablando de retroceder en el tiempo... el restaurante no cambió ni un poquito.",
  ["Act_E2_2A_Diner_PostCardRack_Look01_Max_010"] = "Mirando estas postales, ¿quién se va a imaginar lo extraña que es esta ciudad?",
  ["Act_E2_2A_Diner_Poster01_Look01_Max_010"] = "El cartel no menciona alumnos desquiciados con armas.",
  ["Act_E2_2A_Diner_Poster02_Look01_Max_010"] = "Eso me trae recuerdos... A Chloe y a mí nos encantaba el desfile...",
  ["Act_E2_2A_Diner_Poster03_Look01_Max_010"] = "Dios mío. Eso sí que es apocalíptico...",
  ["Act_E2_2A_Diner_Predilection_VoiceOver01_Max_020"] = "Ahora debería rebobinar y contarle a Chloe todo lo que acaba de suceder.",
  ["Act_E2_2A_Diner_ProvedPower_VoiceOver01_Max_010"] = "Chloe finalmente me cree... me pregunto qué locuras estará planeando.",
  ["Act_E2_2A_Diner_PuzzleDivination01_VoiceOver01_Max_010"] = "Tengo que estudiar de verdad las cosas de Chloe.",
  ["Act_E2_2A_Diner_PuzzleDivination02_VoiceOver01_Max_010"] = "Ahora presta atención a todo lo que ocurra a continuación y sorprende a Chloe con tus increíbles poderes.",
  ["Act_E2_2A_Diner_RecallMemories_VoiceOver01_Max_010"] = "Vaya, ese aroma a desayuno y el sonido de los cubiertos... me siento de trece años otra vez...",
  ["Act_E2_2A_Diner_WhalesPictures_Look01_Max_010"] = "Qué curioso, nuestra familia nunca fue a observar a ballenas. Parece divertido.",
  ["Act_E2_2A_Diner_Window_Look01_Max_010"] = "El faro se ve tan misterioso... Me gustaría quedarme en este momento para siempre... De hecho, ahora sí podría hacerlo. Pero dejaría de ser un momento...",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_021"] = "Casi. ¿Sabes si ya pasó el autobús? Los horarios en línea no sirven.",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_024"] = "No puedo perderme esta entrevista de trabajo. Pero tengo que tomar el autobús de Arcadia Bay a Newport solo para encontrar trabajo.",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_025"] = "Oh, qué alivio. No puedo llegar tarde a mi entrevista de trabajo. No puedo creer que tenga que tomar un autobús hasta Newport para encontrar un segundo empleo.",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_027"] = "¿Y dónde está bien? Ni siquiera puedo darme el lujo de vivir aquí.",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_AdultFem_029"] = "¡Gracias, en verdad la necesitaré!",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_022"] = "No lo sé... Pasa con bastante frecuencia.",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_023"] = "Acabo de bajar del autobús escolar, pero seguro el normal también está pasando.",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_026"] = "¿Tan mal está la cosa aquí?",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_028"] = "Bueno, ¡suerte!",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase01_Max_030"] = "Hola, parece... perdida.",
  ["Cue_E2_2A_DinerPark_CHAdultFem_Phase02_AdultFem_001"] = "Me quedaré aquí con la esperanza de que venga el autobús.",
  ["Cue_E2_2A_DinerPark_CHAdultMal02_Phase01_AdultMal02_001"] = "No tengo tiempo para hablar de tonterías. Sip. Soy millonario. Tengo mi billete de lotería aquí mismo. Estoy esperando el autobús para poder ir a cambiarlo.",
  ["Cue_E2_2A_DinerPark_CHAdultMal02_Phase02_AdultMal02_001"] = "Este billete es mío. Compra uno para ti.",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_001"] = "¿Puedes creer lo que pasa en esta ciudad? El mundo está en llamas, pero nuestro gran titular es \"¡Nieve!\". No puedo esperar a leer la gran primicia de la próxima semana: \"¡Nubes!\".",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_004"] = "Oh, esa mierda del calentamiento global. Estamos en el noroeste, es normal que nieve.",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_005"] = "Lo suficiente como para saber que Arcadia Bay va a ser una ciudad fantasma en unos años.",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_006"] = "De lo único que puede hablar el periódico es de eso o de chicas desaparecidas.",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_010"] = "Supongo. Apuesto que se escapó porque estaba aburrida. ¿Quién no lo estaría aquí?",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_AdultMale_011"] = "Eres joven. Lo superarás.",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_002"] = "Lo de la nieve fue bastante extraño... Nevó en un día cálido y soleado.",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_003"] = "¿Cuánto hace que vives aquí?",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_007"] = "Siempre leo que Arcadia Bay está en auge.",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_008"] = "¿Te refieres a... Rachel Amber?",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_009"] = "Esta ciudad es como un misterio para mí...",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase01_Max_012"] = "Disculpe... ¿señor?",
  ["Cue_E2_2A_DinerPark_CHAdultMale_Phase02_AdultMale_001"] = "Disculpa, debo leer mi horóscopo.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_002"] = "Ojalá, jovencita. Arcadia Bay ya no es el mismo pueblo de pescadores en el que crecí.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_005"] = "¿Tienes alguna pregunta?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_008"] = "¡Por las barbas de Neptuno! ¡Por supuesto! Siento que ha pasado una eternidad desde que era el rey del puerto.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_010"] = "Oh, los peces saltaban a mi barco... Hasta que los Prescott y sus demonios financieros se quedaron con todos los derechos portuarios...",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_013"] = "La llamo \"Bali Hai\". Me las arreglé para conservarla en estos tiempos difíciles... puede que no por mucho...",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_031"] = "No me sorprendería que le cambiaran el nombre a Prescott Bay, para que te des una idea.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_033"] = "Quedan demasiado grandes para los trabajadores como yo. Los conozco por sus malas acciones...",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_035"] = "Los estafadores ganan respeto poniendo sus nombres a escuelas y bibliotecas...",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Fisherman_037"] = "No nos deprimamos. Escucho a los peces llamando a Bali Hai... ¡No olvides que los pescadores viejos nunca mueren, solo olemos así!",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_001"] = "Buenos días de nuevo.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_003"] = "Buenos días. Parece listo para atrapar muchos peces.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_006"] = "Me encantaría que me cuente más, pero debo irme. ¡Qué tenga una buena pesca!",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_007"] = "¿El pueblo ha cambiado mucho?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_009"] = "Se las arregló bien para haber durado todo este tiempo...",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_012"] = "¿Tiene su propio bote?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_014"] = "Pensé que una de las mayores exportaciones de Arcadia Bay era el pescado...",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_030"] = "Los Prescott tienen mucho poder.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_032"] = "¿Los conoce?",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase01_Max_034"] = "Son dueños de mi escuela.",
  ["Cue_E2_2A_DinerPark_CHFisherman_Phase02_Fisherman_001"] = "Creo que he hablado como para todo el año.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_002"] = "Oh, mírate. Un perfecto ejemplo de juventud. Apuesto que estás en tu último año de secundaria.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_004"] = "Mil años. Viví los mismos cambios que el pueblo...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_006"] = "Cambios que requieren una vida entera para ser vistos.|Hay mucha belleza aquí, pero también mucha oscuridad. Malditos codiciosos que arruinaron el pueblo, dejaron a su gente sin trabajo... y sin hogar. Como a mí.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_008"] = "¿Qué no me pasó? A veces uno empieza su vida con el pie izquierdo... Me casé mal, cometí errores, me estafaron los ahorros, perdí mi casa y ahora ando por aquí...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_010"] = "¿Adónde más podría ir? Odio el sol, y me encanta la niebla. No tendré casa, pero Arcadia Bay sigue siendo mi hogar.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_012"] = "Me alimenta más que mi propia familia. Tiene una hija de tu edad que siempre anda en problemas. Se casó con un verdadero imbécil.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_016"] = "Ese una vez me mandó a \"buscar trabajo\". Idiota. No entiendo qué le ve Joyce, pero más vale que la trate bien.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_018"] = "Linda chica. Enojada. Solía verla con su amiga bonita, eh... Rachel, todo el tiempo por aquí...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_024"] = "Toda esa familia está podrida. Hubo un tiempo en el que hacían cosas buenas por Arcadia Bay... esos días murieron. Como todo lo que se cruza en su camino...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_028"] = "Entonces sé su ángel de la guarda, porque nada se interpone en el camino de esa familia, especialmente la ley. Maldita sea, hasta tu escuela, Blackwell, es de ellos. Casi.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_036"] = "Sé que está desaparecida. Y sé que andaba por aquí a veces. A veces la veía caminando sola, perdida en sus pensamientos. Demasiado joven y bonita para verse tan pero tan preocupada...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_038"] = "Habló conmigo un par de veces... de los problemas en la escuela, de que quería ser modelo en California... siempre se mantenía distante. Pero era agradable.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_040"] = "Como dije, parecía muy amiga de la hija de Joyce. Una vez me pareció verla con un hombre más grande, tal vez era su padre. Debe ser horrible para sus padres.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_042"] = "Rezo porque la pobre esté bien... pero no se puede salvar a todo el mundo.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_046"] = "Sabía que eras una joven sabia. Sé todo sobre Blackwell y este pueblo...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_HomelessFem_048"] = "Así parece.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_001"] = "Hola.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_003"] = "¿Cuánto hace que vives en Arcadia Bay?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_005"] = "¿Qué cambios en el pueblo?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_007"] = "¿Qué te pasó?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_009"] = "Lo siento... ¿Viviste fuera del pueblo alguna vez?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_011"] = "Debes conocer a Joyce Price, del restaurante Two Whales...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_015"] = "Se llama David Madsen...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_017"] = "¿Conociste a la hija de Joyce?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_023"] = "Apuesto que conoces los secretos de la familia Prescott.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_027"] = "Sé de alguien a quien están amenazando...",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_035"] = "¿Sabes algo de Rachel Amber, la chica desaparecida?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_037"] = "¿Hablaste con ella?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_039"] = "¿Pasaba mucho tiempo sola o con amigos?",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_045"] = "Sí. Voy a la Academia Blackwell.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_047"] = "Hola, volví.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase03_Max_100"] = "Debo irme. Adiós.",
  ["Cue_E2_2A_DinerPark_CHHomelessFem_Phase04_HomelessFem_001"] = "Puedes venir a hablar conmigo cuando quieras, jovencita.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopAdultFem_020"] = "Qué suerte tienen algunos...",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopAdultFem_040"] = "No me atrevo ni a soñarlo.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_010"] = "Sip. Listo para cobrar mi billete de lotería.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_030"] = "No trates de robármelo. Es mío.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_050"] = "Voy a ser millonario.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_060"] = "Espero que nadie me robe mi billete de lotería.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_BusStopOldMan_070"] = "No puedo esperar a ser rico. Sip.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_DegueuAdultMale_100"] = "¿Puedes traerme cerveza y tocino antes de que me muera?",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_DegueuAdultMale_120"] = "¿No hay cerveza?",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_DegueuAdultMale_140"] = "No tienen cerveza... ¿qué clase de lugar es este?",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_Joyce_110"] = "Esto es un restaurante, no un bar.",
  ["Cue_E2_2A_DinerPark_Citizens_IGE_Joyce_130"] = "Parece que ya bebiste suficiente. Confórmate con el tocino.",
  ["Cue_E2_2A_DinerPark_FrankSleeping_Frank_010"] = "Basta, basta. No ladres.",
  ["Cue_E2_2A_Diner_CHAdultFem02_Phase01_AdultFem02_001"] = "Buenos días para ti. Qué día tan hermoso, ¿no? Oh, sí, va a ser un día espectacular. Disfruta tu desayuno, ¿sí?",
  ["Cue_E2_2A_Diner_CHAdultFem02_Phase02_AdultFem02_001"] = "Oh, sí. Hola de nuevo. Desayunando de vuelta, ¿eh?",
  ["Cue_E2_2A_Diner_CHAdultMal_Phase01_AdultMal_001"] = "¿Qué quieres? Me siento como la mierda. Demasiada cerveza. Así que no me molestes, por favor. Déjame sufrir en silencio.",
  ["Cue_E2_2A_Diner_CHAdultMal_Phase02_AdultMal_001"] = "Déjame en paz o vomitaré encima de ti.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_002"] = "Muy bien, Max. Estoy más que lista.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_008"] = "¡Dah! ¡Demasiado fácil! ¡Necesito detalles! Describe mi llavero...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_014"] = "Sí, sabes que fumo. ¿Pero cuántos cigarros?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_015"] = "Obvio, si soy millonaria... ¿cuánto tengo?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_016"] = "Me conoces bien. Pero... ¿me puedes decir la hora exacta en la que me la hicieron?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_017"] = "Nada...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_018"] = "La dejé en la camioneta.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_020"] = "No me impresionas.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_025"] = "Completamente... incorrecto.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_037"] = "De acuerdo, chica vidente, te mostraré lo que tengo en los bolsillos.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_086"] = "Estuviste... tan equivocada, Max.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_087"] = "¡Bzzz! ¡Respuesta incorrecta!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_088"] = "¿Tienes poderes o no?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_089"] = "¿Un qué? ¿Siquiera me conoces?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_090"] = "¿Parezco una friki de Linux como tu amigo Warren?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_091"] = "¡Nada mal, SuperMax!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_092"] = "Esa es suerte de irlandesa, Caulfield. ¿Qué más?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_098"] = "Hasta un reloj descompuesto marca bien la hora dos veces al día. Lo que sea que signifique.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_099"] = "Eso fue genial, ¡quiero más!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_100"] = "¡Sorprendente! ¿Algo más en mis bolsillos?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_101"] = "Un superpoder que te permite contar cigarros. ¡Estupendo!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_102"] = "Fumo demasiado como para tener 13 cigarros...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_103"] = "Perdiste...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_104"] = "Ojalá.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_105"] = "¡Así es! ¡Estoy viviendo a lo grande en Arcadia Bay!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_106"] = "Totalmente... incorrecto.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_107"] = "¡Así es! ¡Max sabe decir la hora!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_108"] = "Ni siquiera pasa por mi mente despertarme tan temprano.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Chloe_109"] = "Impactante. Veamos si acertaste.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_003"] = "Muy bien, voy a decirte lo que tienes en tus bolsillos.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_005"] = "¡Las llaves de tu auto!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_006"] = "¿Goma de mascar vieja?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_007"] = "Veamos... ¿un arma?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_011"] = "Estoy muy segura de que tienes cigarros.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_012"] = "¿Algo de dinero?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_013"] = "Una multa de estacionamiento.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_021"] = "Seis cigarros...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_022"] = "Siete cigarros...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_023"] = "Trece cigarros...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_026"] = "Veinticinco centavos...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_027"] = "Ochenta y dos centavos...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_029"] = "Ochenta y seis centavos...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_030"] = "11:10 a.m.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_031"] = "10:34 a.m.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_032"] = "06:42 a.m.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_078"] = "No lo sé...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_079"] = "¡Es un llavero de calavera, bien punk como tú!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_080"] = "No hay duda: es un llavero de hoja de afeitar...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_081"] = "¡Es una bala, como la de tu collar!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_083"] = "Es un llavero de corazón pixelado...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_084"] = "Es un llavero de pingüino...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_085"] = "¡Es un llavero de un adorable panda robot!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle01_Max_110"] = "Tienes brillo labial, ¿verdad?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_033"] = "¿Y qué pasa después?",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_034"] = "Bueno, veamos qué pasa.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_036"] = "Esto se está poniendo bueno, ¡no puedo esperar a ver qué pasa!",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_037"] = "Bastante espeluznante, Max. Pero veamos si todo pasa como dijiste...",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_045"] = "Max, dijiste que ibas a predecir cuatro sucesos, no estamos ni cerca.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_049"] = "Max, dijiste que ibas a predecir cuatro sucesos. Eso son dos, güey.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Chloe_050"] = "Sí, todavía debes decirme un suceso más, Max.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_003"] = "Al camionero se le cae la taza, y Joyce lo insulta.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_004"] = "A Trevor se le cae el vaso, y Justin se burla de él.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_005"] = "Al policía se le cae el vaso, y Joyce discute con él.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_010"] = "El policía recibe una llamada de emergencia por radio y la responde.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_011"] = "El policía recibe una llamada de emergencia por radio y sale corriendo del restaurante.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_012"] = "El policía recibe una llamada de emergencia por radio, y su compañero se va en el coche sin esperarlo.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_017"] = "Justin y Trevor discuten, y Joyce los golpea.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_018"] = "Justin y Trevor discuten, y Joyce los alienta.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_019"] = "Justin y Trevor discuten, y Joyce no hace nada.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_025"] = "La rocola se vuelve loca cuando una cucaracha se mete en ella.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_026"] = "La rocola se vuelve loca cuando una mosca se posa sobre ella.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_027"] = "La rocola se vuelve loca cuando el camionero trata de cambiar de canción.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_044"] = "A Joyce se le cae el plato, y los camioneros se burlan de ella.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_046"] = "El policía recibe una llamada de emergencia por radio, no hace nada y se come una dona.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_047"] = "Justin y Trevor discuten, y Joyce los separa.",
  ["Cue_E2_2A_Diner_CHChloe_Puzzle02_Max_048"] = "La rocola se vuelve loca cuando una mariposa se posa sobre ella.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_002"] = "Hola, jovencita. Te ves algo perdida.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_005"] = "Me encantaría que Two Whales fuera mi primer hogar. Joyce podría hacerme los excelentes cafés y las jugosas hamburguesas en cualquier momento... Tú te ves de la edad de Chloe.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_008"] = "Eso es todo un problema en Two Whales. Nunca me puedo decidir... ¿El pastel de calabaza de Joyce o macarrones con queso?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_011"] = "Conozco sus delicias. Todos los de la estación vienen aquí. Cuidamos este lugar como si fuera nuestra propia cocina. Y a Joyce como si fuera nuestra... nuestra madre.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_017"] = "Por desgracia, todos conocemos a Chloe en la estación. Pobre Joyce.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_020"] = "Bien. No es una mala persona, ha pasado por momentos difíciles, pero eso no es excusa para andar quemando cosas por ahí.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_021"] = "Entonces sabrás que es una muchacha problemática.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_023"] = "Mi papá murió cuando tenía 13. Nunca quemé contenedores de basura ni arruiné letreros. Joyce es una excelente madre, pero Chloe no lo ve.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_029"] = "Debes crear tu propia suerte. Creo que Chloe es más bien destructiva. Pero no soy más que un policía, no psicólogo, así que...",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_031"] = "Parece que eres una buena amiga. Desearía que ella fuera mejor hija y no le causara tantos problemas a Joyce.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_034"] = "Acabo de escuchar que Chloe llevó a un vendedor de marihuana a su habitación...",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_035"] = "Acabo de escuchar que encontraron marihuana en su habitación.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_037"] = "¿Cómo sabes que se estaba \"relajando\" en su habitación?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_039"] = "No lo escuché en la radio. Joyce dijo que la marihuana era de un amigo de Chloe, pero... Lo dudo mucho.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_050"] = "Por cierto, algo que puedo decirte con certeza es que no te conviene acercarte a esa van de afuera.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_052"] = "Sabia regla. El tipo que vive ahí, Frank, es bastante sospechoso. Eso es todo lo que puedo decir por ahora... Debería terminar mi café e ir a trabajar.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_057"] = "No quiso. Tenía miedo de que fuera a arrestar a alguien. Como si fuera a hacerlo. Solo le hubiera dicho a ese perdedor que se mantuviera bien alejado de Chloe. De lo contrario... Estoy bromeando. Además, David Madsen los está vigilando.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_058"] = "¿Es amiga tuya?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_059"] = "Tal vez estaba drogándose o preparando sus latas de aerosol o lo que sea. Me gustaría tener una mejor opinión de ella, pero ahora está en la base de datos de la Policía de Arcadia Bay.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_060"] = "Yo no usaría esa palabra. Nos conocemos. ¿Por qué lo preguntas?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_063"] = "Respeto a David. Prestó servicio a su país. Encontró su vocación en Blackwell. En la estación, nos alegra que David esté donde está... No todos pueden ser policía.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Cop_064"] = "¿SÍ?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_001"] = "Hola, señor.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_003"] = "No, he estado aquí muchas veces. Es como mi cuarto hogar.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_004"] = "Solo tengo hambre y estoy pensando qué comer.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_010"] = "¿Conoce bien a Joyce?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_016"] = "¿Entonces conoce a Chloe?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_018"] = "En realidad, no...",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_019"] = "La conozco.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_022"] = "Sé que su papá murió...",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_028"] = "No, solo creo que tuvo mala suerte.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_030"] = "Puede serlo, pero también puede ser una gran amiga con la que siempre se puede contar.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_032"] = "Eh, ¿quién le dijo eso?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_033"] = "Ah... Eso no es bueno. Como sea. Mmm, ese tocino sí que huele bien...",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_036"] = "¿Realmente para tanto? Al menos se estaba relajando en su habitación.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_038"] = "Seguro que es amigo de David Madsen, ¿verdad?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_049"] = "Debo irme. Disfrute de su desayuno.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_051"] = "Suelo mantenerme alejada de vehículos estacionados que parecen sospechosos.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_055"] = "¿Joyce no le dijo quién era?",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_056"] = "Acaba de decirlo.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_061"] = "Solo tengo curiosidad... Me sorprende que no sea policía en Arcadia Bay.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_062"] = "Tiene cierta fama en Blackwell.",
  ["Cue_E2_2A_Diner_CHCop_Phase01_Max_065"] = "Hola de nuevo, oficial.",
  ["Cue_E2_2A_Diner_CHCop_Phase02_Cop_001"] = "Me encantaría enseñarte un par de cosas mientras tomamos café, pero prefiero beber solo y en silencio.",
  ["Cue_E2_2A_Diner_CHFisherman02_Phase01_Fisherman02_002"] = "Si con \"grande\" te refieres a \"ninguno\", por supuesto, atrapé muchos grandes hoy. Ahora déjame lamentarme en paz.",
  ["Cue_E2_2A_Diner_CHFisherman02_Phase01_Max_001"] = "¿Atrapó alguno grande hoy?",
  ["Cue_E2_2A_Diner_CHFisherman02_Phase02_Fisherman02_001"] = "Sigo lamentándome, gracias.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_001"] = "Hiciste lo correcto. Seguiste con tu vida. Yo lo hice, tras la muerte de William. Chloe... Chloe decidió seguir enojada... Como sea, espero que te veamos más seguido. Chloe necesita volver a tener a una vieja amiga.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_002"] = "Buen intento, Nancy Drew. Pero aparte de ti, hay una sola estudiante que me preocupa. Y ya ni siquiera está en la escuela.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_005"] = "Me alegra, Max. Ese fue su regalo... Recuerdos maravillosos. Aunque Chloe todavía no lo entienda.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_006"] = "Ahora, termina tu café.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_013"] = "¿No te pusiste en contra de tu amiga cuando la dejaste sufrir sola por lo de la marihuana?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_015"] = "¿Por qué? ¿Qué te contó Chloe?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_017"] = "Nadie se mete en problemas por un churrito, Max. Y admiro que hayas asumido la culpa por Chloe... como una gran amiga.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_019"] = "Oh, pasó por todas las fases... expulsión, escaparse, drogas, muchachos malos, tatuajes, piercings, cabello azul... Y ahora se rebela contra su padrastro.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_022"] = "Se siente muy mal... Y será castigado.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_025"] = "¿En serio? No es tan malo como crees. Pero le dijiste que tenías un cigarro de marihuana, ¿verdad? ¿Te hiciste cargo de eso?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_027"] = "Sabes lo que ocurrió... David le pegó a Chloe. La regó.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_028"] = "David la mencionó, pero no me meto en sus asuntos. Yo no patrullo Blackwell, y él no cocina en el restaurante, ¿me entiendes?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_030"] = "Pero Chloe se la pasa provocando a David, y no es justo. Él ya tuvo lo suyo con la guerra. Sí se preocupa por ella, y por todos los estudiantes de Blackwell.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_032"] = "Bueno. Vamos al grano. ¿Qué quieres comer?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_034"] = "Sí, suele provocar a la gente. Especialmente a David. Solo quiero que pronto podamos ser una familia. Supongo que es cuestión de tiempo...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Joyce_036"] = "A mí tampoco me gusta, Max. David juró que nunca volvería a suceder. Él cumple su palabra. Solo quiero que pronto podamos ser una familia. Supongo... Supongo que es cuestión de tiempo...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_003"] = "Sé que fue difícil para ti y para Chloe. Me siento mal de no haberlas llamado. Ahora mis papás están en Seattle, y yo estoy aquí sola en Blackwell. Es mi karma.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_004"] = "Joyce, siento mucho lo de William. Tengo recuerdos maravillosos de él.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_008"] = "Creo que tienes razón, Joyce.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_009"] = "La última vez que comí un buen waffle belga fue aquí, cuando tenía 13 años. Así que tráemelo.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_012"] = "David me asustó cuando dijo que podría hacer que me quiten la beca por ese estúpido cigarro...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_014"] = "Sí. Y lo siento. No quiero más problemas para Chloe... Ni para mí.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_016"] = "Joyce, ayer le pegó a Chloe.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_018"] = "Chloe lo entiende. Solo necesita... tiempo. Sé que es muy difícil para ti.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_020"] = "Debería haber asumido la culpa por lo de la hierba. Tal vez nada de esto hubiera pasado...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_021"] = "Chloe no tiene que contarme nada. Ya sé cómo es David en Blackwell.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_024"] = "Chloe debe haber cambiado mucho en todo ese tiempo...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_026"] = "Entiendo por qué... Es decir...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_029"] = "Bueno, ayer Chloe me mandó un texto y me contó que David le había pegado...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_031"] = "¿Se preocupa por Kate Marsh?",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_033"] = "Entiendo, Joyce. Sé que a Chloe le gusta armar lío...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_035"] = "No es excusa para golpear a una muchacha. Es un adulto.",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_056"] = "Soñaba con tu omelette de tocino...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_057"] = "Ayer tomé una foto de él mientras peleaba con Kate... Pensé que quizás sabías el motivo...",
  ["Cue_E2_2A_Diner_CHJoyce_Phase01_Max_058"] = "Lo vi discutiendo con Kate... Pensé que quizás sabías el motivo...",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_002"] = "Tomando café antes de faltar a clase para romper el asfalto. ¿No deberías estar tomando fotos?",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_004"] = "Con un poco de verde es el cóctel hippie perfecto.",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_007"] = "Me matas de la risa, Maxster. Claro que, como estoy volado, me río por cualquier cosa.",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_009"] = "¿Y dónde están tus deberes, colegiala?",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Justin_011"] = "Trevor finalmente me contó lo de él y Dana. Él llegó primero, así que el que pestañea, pierde... Nos vemos luego, Max.",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_001"] = "¿Qué tal, Justin?",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_003"] = "Todavía no. También tengo que... tomar mi dosis de café.",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_005"] = "No tienes nada de hippie.",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_006"] = "Siempre estoy tomando fotos. Soy una cámara.",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_008"] = "Deberías estar estudiando, muchacho malo.",
  ["Cue_E2_2A_Diner_CHJustin_Phase01_Max_010"] = "En la escuela. Hablando de eso, vi a tu amigo Trevor saliendo a escondidas de la habitación de Dana.",
  ["Cue_E2_2A_Diner_CHJustin_Phase02_Justin_001"] = "Hablemos luego, cuando no esté tan drogado...",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_001"] = "Hola, Trevor.",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_003"] = "Sí, te vi saliendo de la habitación de Dana.",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_004"] = "A decir verdad, no.",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Max_008"] = "¿Cómo lo tomó Justin?",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_002"] = "Hola, Max. Por cierto, sé que me viste en la habitación.",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_005"] = "Sí, y le tuve que decir a Justin porque, bueno, a él también le gustaba ella.",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_006"] = "Me pareció que estabas mirándome a los ojos. Supongo que ahora ya lo sabes... y Justin también.",
  ["Cue_E2_2A_Diner_CHTrevor_Phase01_Trevor_007"] = "Lo agarré volado, no tuvo problema. De todos modos, no hay secretos en Blackwell... Nos vemos en clase, Max.",
  ["Cue_E2_2A_Diner_CHTrevor_Phase02_Trevor_001"] = "¡Nos vemos, Max!",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_004"] = "Ah... lo siento.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_005"] = "¿No está todo aquí a la vista?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_006"] = "¿Cómo suena Joyce?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_008"] = "Joyce es genial. Quiero ser igual a ella cuando sea grande.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_009"] = "¿Por qué eres tan grosero?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_010"] = "Ese es su estilo. Por eso admiro cada cosa que hace.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Max_014"] = "Eh... ¿hola?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_001"] = "\"Pardonne-moi\", pero estás bloqueando mi vista.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_002"] = "No es nada, solo necesito ver mi camión en el estacionamiento. Fue una noche larga en la carretera, debo asegurarme de que mi bebé esté durmiendo bien...",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_003"] = "No me gusta tu tono. Suenas igual que Joyce.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_007"] = "Mandona y sabelotodo... como tú.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_011"] = "Parece que vas por el buen camino. Hace tres años que vengo a este lugar, y Joyce me molesta todo el tiempo a más no poder.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_012"] = "Porque estuve 12 horas seguidas en la carretera, dopado de café y pastillas para adelgazar, llevando dos toneladas de nitrato, y ahora lo único que quiero hacer es desayunar en paz y mirar por la ventana. ¿Te importaría?",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase01_Trucker1_013"] = "Bien, no puedo esperar a verte friendo tocino grasiento en un restaurante cuando seas grande... exactamente igual que Joyce. Ahora, si me disculpas, seguiré con mi café.",
  ["Cue_E2_2A_Diner_CHTrucker1_Phase02_Trucker1_001"] = "No más cotorreo, por favor.",
  ["Cue_E2_2A_Diner_CHTrucker2_Phase01_Trucker2_001"] = "No tengo ganas de hablar ahora. Tengo que entregar un gran desayuno a mi estómago. Cambio y fuera.",
  ["Cue_E2_2A_Diner_CHTrucker2_Phase02_Trucker2_001"] = "Dije... cambio... ¡y fuera!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_050"] = "Juro lealtad a Max y al poder que representa...",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_070"] = "¡A la mierda con eso! ¡Claro que es un juguete! ¡El mejor del mundo! Te acuestas con quien quieras, rebobinas y ¡bum! ¡Como si nunca hubiera ocurrido!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_090"] = "¡Tal vez me intentaste seducir, y nunca lo sabré!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_110"] = "Puedes rebobinar el tiempo, Max. Es demasiado loco. ¡Tenemos que jugar!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_130"] = "No acabas de decir eso.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_140"] = "Ah... Mira tu nariz. ¿Demasiada cocaína?",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_150"] = "Oye, ¿estás bien?",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_170"] = "Entonces... vayamos a mi guarida secreta para probar tu poder a fondo.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_180"] = "Necesitas una mano derecha que te guíe.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_200"] = "¡Amiga, estabas en lo cierto!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_210"] = "¡Oh, esto es tan genial!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_220"] = "¡Está loquísimo!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_230"] = "¡De puta madre!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_240"] = "¡Oh, así se hace, mamá!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_250"] = "Tú lo has dicho, apuesto que se fue a atrapar patinadores...",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_260"] = "Trevor y Justin deben estar enamorados.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Chloe_270"] = "¡Predijiste que había una cucaracha en la rocola!",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_060"] = "No es un juguete, Chloe. Tengo que tener cuidado con cómo lo uso...",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_080"] = "Madura.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_100"] = "Sí, es lo que hice.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_120"] = "No tengo tiempo.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_160"] = "Demasiada emoción. ¿Ves lo que pasa cuando volvemos a juntarnos?",
  ["Cue_E2_2A_Diner_ChloePuzzle02Happy_IGE_Max_190"] = "Muy bien, muchacha maravilla... Muéstrame el camino hacia la Cueva de Chloe.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_030"] = "Totalmente incorrecto.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_040"] = "No lo creo, Max.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_050"] = "En verdad le estás pifiando.",
  ["Cue_E2_2A_Diner_ChloePuzzle02Sad_IGE_Chloe_060"] = "Es un día triste en la villa de Max.",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_020"] = "¿Y ahora qué?",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_030"] = "No te quedes ahí viendo.",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_050"] = "Apuesto que tienes memoria fotográfica... ¿Entiendes?",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_060"] = "¿Y ahora qué?",
  ["Cue_E2_2A_Diner_ChloeSitting_IGE_Chloe_070"] = "¿Qué estás esperando?",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_050"] = "¡Mamá y Max, juntas de nuevo!",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_090"] = "No necesito que nadie me rescate.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_110"] = "Ay, Dios, ya empezamos. Tú y el Sargento Pepper ya me sermonearon ayer, ¿no fue suficiente?",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_140"] = "Por Dios, mamá, no jodas a Max con eso. Ya se disculpó.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_160"] = "Ya está grande para sermones de ti y del Sgto. Pimienta...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_200"] = "Otro motivo para abandonar este pueblo.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_205"] = "¿Qué es esta música de mierda?",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_210"] = "Ahora que esto está resuelto...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_220"] = "Hablemos de tu superpoder...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_240"] = "Ya, estabas soñando despierta. Quiero pruebas de que puedes retroceder en el tiempo.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Chloe_260"] = "Empezaremos poco a poco. Aquí mismo. Ahora.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_010"] = "Puedo oír tu estómago rugiendo desde aquí, Max. Ten. Te va a encantar.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_030"] = "Todavía no puedo creer que ya seas una mujer. Cuando miro las fotos de Chloe...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_040"] = "Hablando del rey de Roma...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_060"] = "Y Chloe, buscando una comida gratis. Tu cuenta aquí se quedó con todos tus fondos para la universidad.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_080"] = "Por supuesto que no. Es mi manera de agradecerte que hayas vuelto a rescatar a mi hija.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_100"] = "A menos que prendas fuego a tu habitación de tanto fumar...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_130"] = "¿Quieres reivindicarte por lo de ayer?",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_150"] = "Sé que lo hizo. Max es una buena muchacha... mujer. Ya tiene 18.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_170"] = "Llámalo David si no quieres escuchar sermones.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Joyce_180"] = "Hoy te mereces solo una mísera rebanada de tocino.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_020"] = "Se me hace agua la boca.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_070"] = "Yo le invito el desayuno a Chloe.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_120"] = "Yo le invito el desayuno a Chloe.",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_190"] = "Veo que no han cambiado...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_230"] = "No puedo explicarlo... Ni tampoco mi visión de ese maldito tornado...",
  ["Cue_E2_2A_Diner_Chloe_Arrives_Max_250"] = "Todo está pasando tan rápido...",
  ["Cue_E2_2A_Diner_Citizens_Trucker1_010"] = "Creo que estoy listo para el tercer plato.",
  ["Cue_E2_2A_Diner_Citizens_Trucker1_030"] = "Mi estómago piensa con anticipación.",
  ["Cue_E2_2A_Diner_Citizens_Trucker2_020"] = "Pero recién va por el primero.",
  ["Cue_E2_2A_Diner_Citizens_Trucker2_040"] = "Su estómago se está preparando para el invierno.",
  ["Cue_E2_2A_Diner_DinerTV_IGE_TVReporter_010"] = "Este mediodía, Noticias KBAY 7 explorará el misterio de la extraña nevada de ayer en una tarde cálida y soleada, que dejó a los residentes de Arcadia Bay tan sorprendidos como confundidos.",
  ["Cue_E2_2A_Diner_DinerTV_IGE_TVReporter_020"] = "Hablaremos con meteorólogos de Portland de la zona y veremos algunos de sus videos de reacciones divertidas ante la inusual nevisca.",
  ["Cue_E2_2A_Diner_DinerTV_IGE_TVReporter_030"] = "Quién sabe... ¿La Madre Naturaleza nos habrá jugado una broma? Estén atentos a Noticias KBAY 7 para enterarse de la verdadera historia...",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Cook_035"] = "¡Tocino a las 12 en punto!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Cook_040"] = "¡Un waffle belga a las 12 en punto!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Cook_050"] = "¡Pedido listo!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Joyce_010"] = "Un omelette de tocino para la jovencita. ¡De inmediato!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Joyce_020"] = "Un waffle belga para la chica hambrienta. ¡Pronto!",
  ["Cue_E2_2A_Diner_JoyceLoop_IGE_Joyce_060"] = "¡En camino!",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_010"] = "Y aquí estás, una joven hermosa. ¿Cómo estás, Max?",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_030"] = "¿Te refieres a que sigo siendo mesera de Two Whales después de todos estos años?",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_050"] = "Buena atrapada, niña. Sigues siendo lista.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_060"] = "Pero desearía que hubieras estado ahí para salvar a Chloe. Ayer la pescamos fumando. De nuevo.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_080"] = "Lamento que hayas conocido a David de esa manera. Espero que puedas conocerlo por ti misma, no por lo que dice Chloe. Es un buen hombre... Es solo que...",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_100"] = "Es bueno tenerte aquí. Esperaba que fueras una buena influencia en su vida ahora...",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_110"] = "Buena atrapada, niña. Sigues siendo lista.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_120"] = "Pero no tanto... Ahora te atrapan fumando marihuana.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_130"] = "David me contó todo el escándalo. Lamento que lo hayas conocido de esa manera. Es un buen hombre... más allá de lo que diga Chloe.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Joyce_150"] = "Me dejó muy sorprendida. Esperaba que fueras una buena influencia en su vida ahora...",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_020"] = "Hola, Joyce, es bueno volver a verte. Te ves igual.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_040"] = "No, a que sigues igual de bella.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_070"] = "Lo sé. Chloe me contó que su padrastro la golpeó...",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_075"] = "Lo sé. Su padrastro la golpeó...",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_090"] = "Sí, estoy segura de eso porque te casaste con él, pero... no seas tan dura con Chloe.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_140"] = "Sí, estoy segura. Ni siquiera fumo... nunca. Fue casi por accidente. Muy estúpido. Lo siento.",
  ["Cue_E2_2A_Diner_Joyce_MeetMax_Max_160"] = "Lo seré. Lo prometo.",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_030"] = "Por favor, no dejes que tu mejor amiga te estorbe.",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_060"] = "Gracias, Max.",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_070"] = "Si prefieres juntarte con Kate, hazlo.",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Chloe_090"] = "Por ahora. Que empiece el baile.",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_010"] = "Hola, Kate, ¿qué tal?",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_020"] = "¿Estás bien?",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_040"] = "Lo prometo, Kate. No lo olvidaré.",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_050"] = "Lo juro. Concéntrate en tu tarea y no te alteres... No creo que debamos hablar de esto ahora... Te llamaré más tarde, ¿de acuerdo?",
  ["Cue_E2_2A_Diner_MaxAnswer_ChloeUnhappy_Max_080"] = "Eres ridícula. Estoy aquí contigo, ¿cierto?",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_010"] = "¡Hasta luego, mamá!",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_030"] = "¡Libertad!",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_050"] = "No se va a morir porque no contestes una llamada.",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Chloe_060"] = "Ahora sígueme, mi escudera Max, para que podamos usar tu poder al máximo y conquistar el mundo...",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Max_020"] = "Adiós, Joyce.",
  ["Cue_E2_2A_Diner_MaxDontAnswer_ChloeHappy_Max_040"] = "Me siento mal por Kate.",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_010"] = "Muy bien, superchica, ¡vamos a mi lugar secreto!",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_020"] = "Ni se te ocurra responder. Tenemos lugares a los que ir y gente con la que acostarnos...",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_030"] = "Vamos, antes de que mamá empiece de nuevo. ¡Huyamos!",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Chloe_050"] = "Gran cosa. ¿No me llamas ni una vez en cinco años y ahora te preocupas por una perra cualquiera que ves todos los días en la escuela? Entiendo cómo eres. Anda, ve a hablar con Kate Marsh, de Blackwell. Yo también tengo otras personas con quienes juntarme.",
  ["Cue_E2_2A_Diner_MaxPhone_RTC_Max_040"] = "Es Kate Marsh, de Blackwell...",
  ["Cue_E2_2A_Diner_PowerProof01_Chloe_020"] = "¿Tienes visión de rayos X? Ni yo sé qué tengo en los bolsillos.",
  ["Cue_E2_2A_Diner_PowerProof01_Chloe_030"] = "Déjame ver...",
  ["Cue_E2_2A_Diner_PowerProof01_Max_010"] = "Mmm... Puedo decirte todo lo que tienes en los bolsillos.",
  ["Cue_E2_2A_Diner_PowerProof02_Chloe_020"] = "¡No puede ser!",
  ["Cue_E2_2A_Diner_PowerProof02_Chloe_040"] = "Muy bien, Max, ¡sorpréndeme!",
  ["Cue_E2_2A_Diner_PowerProof02_Max_010"] = "Voy a predecir el futuro.",
  ["Cue_E2_2A_Diner_PowerProof02_Max_030"] = "Voy a predecir cuatro cosas que van a pasar más o menos en los próximos 30 segundos...",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Cop_030"] = "Mierda, tengo que dejar mi desayuno por esta llamada... Oye, ¿dónde está mi compañero?",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Joyce_020"] = "¿Rompiste otra copa? ¿En serio? ¡No más refill para ti!",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Joyce_080"] = "Me parece que la rocola está en las últimas...",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Trucker1_010"] = "Ups.",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Trucker1_070"] = "¡Mucho mejor que la basura de antes!",
  ["Cue_E2_2A_Diner_Puzzle02_IGE_Trucker2_060"] = "¡Esa es la mejor canción que he escuchado!",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Joyce_030"] = "¡Vayan a pelearse afuera!",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Joyce_050"] = "Y yo lo termino.",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Justin_020"] = "¡No me toques, zorra!",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Trevor_010"] = "¡Eres un imbécil!",
  ["Cue_E2_2A_Diner_Puzzle02_PredictionSequence_Trevor_040"] = "Él empezó.",
  ["Cue_E2_2A_Diner_ShowItemsGood_Puzzle01_Chloe_010"] = "Increíble. Literalmente, acabo de sentir escalofríos.",
  ["Cue_E2_2A_Diner_ShowItemsGood_Puzzle01_Chloe_020"] = "Déjame desglosar toda esta mierda para probar que, en verdad, eres lo máximo.",
  ["Cue_E2_2A_Diner_ShowItemsGood_Puzzle01_Chloe_030"] = "Tienes poderes.",
  ["Cue_E2_2A_Diner_ShowItems_Puzzle01_Chloe_010"] = "Qué fracaso monumental. Y pretendías que te creyera...",
  ["Cue_E2_2A_Diner_TiddyTable_Chloe_020"] = "Sí, mamá.",
  ["Cue_E2_2A_Diner_TiddyTable_Chloe_060"] = "Dios, me podría comer una vaca entera.",
  ["Cue_E2_2A_Diner_TiddyTable_Chloe_080"] = "Lo que acaba de pasar me puso los pelos de punta. Tienes que mostrarme más, algo mucho más asombroso para que te crea sin dudas...",
  ["Cue_E2_2A_Diner_TiddyTable_Joyce_010"] = "Saca esas porquerías de la mesa, Chloe.",
  ["Cue_E2_2A_Diner_TiddyTable_Joyce_030"] = "¿Qué tal está la comida, Max?",
  ["Cue_E2_2A_Diner_TiddyTable_Joyce_050"] = "Buena atrapada.",
  ["Cue_E2_2A_Diner_TiddyTable_Max_040"] = "Mejor de como la recordaba.",
  ["Cue_E2_2A_Diner_TiddyTable_Max_070"] = "Se nota.",
  ["Act_E2_3A_Junkyard_Bottle01_Interact01_Max_010"] = "¡Maldita botella!",
  ["Act_E2_3A_Junkyard_Bottle01_Look01_Max_010"] = "¿Qué tenemos aquí...? Una pequeña botella bonita esperando a que la recojan...",
  ["Act_E2_3A_Junkyard_Bottle02_Look01_Max_010"] = "Oh, sí, se puede usar como blanco.",
  ["Act_E2_3A_Junkyard_Bottle03_Look01_Max_010"] = "¡Estupendo! Al menos no está todo roto por aquí.",
  ["Act_E2_3A_Junkyard_Bottle03_Look01_Max_020"] = "Apuesto que puedo subirme a ese bote desde un punto más alto...",
  ["Act_E2_3A_Junkyard_Bottle04_Look01_Max_010"] = "\"Próximamente... Max Caulfield, cazadora de botellas. Solo en cines\".",
  ["Act_E2_3A_Junkyard_Bottle05_Look01_Max_010"] = "Oh, ahí estás, botellita... ¿querías jugar a las escondidas?",
  ["Act_E2_3A_Junkyard_Bottle1_VoiceOver01_Max_010"] = "¡Hola, botella número uno! ¡Solo cuatro más!",
  ["Act_E2_3A_Junkyard_Bottle2_VoiceOver01_Max_010"] = "¡Bum! Solo faltan tres botellas...",
  ["Act_E2_3A_Junkyard_Bottle3_VoiceOver01_Max_010"] = "Tres fuera, quedan dos más. Es como encontrar una botella en un pajar...",
  ["Act_E2_3A_Junkyard_Bottle4_VoiceOver01_Max_010"] = "¡Queda una más!",
  ["Act_E2_3A_Junkyard_Bottle5_VoiceOver01_Max_010"] = "¡Voila! Ahora podemos llevarle este botín de botellas a la capitana Chloe...",
  ["Act_E2_3A_Junkyard_Bracelet_Look01_Max_010"] = "Eso duele...",
  ["Act_E2_3A_Junkyard_CHChloe_Look01_Max_010"] = "Esa es mi Chloe...",
  ["Act_E2_3A_Junkyard_CHChloe_Look02_Max_010"] = "Mírala. Chloe puede estar relajada hasta jugando con un arma...",
  ["Act_E2_3A_Junkyard_CHChloe_Look03_Max_010"] = "Chloe está esperando para ir a caminar. Ambas necesitamos un descanso, salir de este lugar...",
  ["Act_E2_3A_Junkyard_CHMax_VoiceOver01_Max_010"] = "Vaya, ¿por qué Frank tenía el brazalete de Rachel? Vamos a tener que hablar de eso después, ahora mejor sigo a Chloe.",
  ["Act_E2_3A_Junkyard_CampFire_Look01_Max_010"] = "Seguro que es un lugar popular para fiestas.",
  ["Act_E2_3A_Junkyard_CarWreck01_Look01_Max_010"] = "Cada auto tiene su propia historia...",
  ["Act_E2_3A_Junkyard_CarWreck02_Look01_Max_020"] = "Toda esta chatarra me da paz... ¿Seré morbosa o solo gótica?",
  ["Act_E2_3A_Junkyard_CarWreck03_Look01_Max_030"] = "Me pregunto si Chloe piensa en su padre al ver estos autos destrozados...",
  ["Act_E2_3A_Junkyard_ChairSit_Max_010"] = "Aunque este depósito de chatarra es un asco, entiendo por qué a Chloe le gusta pasar el tiempo aquí...",
  ["Act_E2_3A_Junkyard_ChairSit_Max_020"] = "Ella es steampunk...",
  ["Act_E2_3A_Junkyard_ChairSit_Max_030"] = "Se siente como si Chloe y yo fuéramos niñas de nuevo, escondiéndonos y planeando nuestro futuro...",
  ["Act_E2_3A_Junkyard_ChairSit_Max_040"] = "A pesar de todo el caos y la mierda, me pone contenta volver a juntarme con ella...",
  ["Act_E2_3A_Junkyard_ChairSit_Max_050"] = "Tan feliz... Como si ambas hubiéramos vuelto al pasado...",
  ["Act_E2_3A_Junkyard_ChloeEnd_VoiceOver01_Max_010"] = "Otro día más en la retorcida vida de Max. Es hora de ir a buscar a Chloe.",
  ["Act_E2_3A_Junkyard_ChloeEnd_VoiceOver01_Max_020"] = "Así comienza otro capítulo de mi drama sin fin. Es hora de buscar a Chloe y salir de aquí.",
  ["Act_E2_3A_Junkyard_Crate_Look01_Max_010"] = "Quizás puedo usarlo para alcanzar la botella.",
  ["Act_E2_3A_Junkyard_DoeEncounter_VoiceOver01_Max_010"] = "Vaya, esa venada es la copia exacta de la de mi visión del tornado...",
  ["Act_E2_3A_Junkyard_DoeEncounter_VoiceOver01_Max_020"] = "Esa venada es perfecta para una foto...",
  ["Act_E2_3A_Junkyard_DoeEncounter_VoiceOver01_Max_030"] = "Me está mirando fijamente como si tuviéramos una conexión...",
  ["Act_E2_3A_Junkyard_DoeRewind_VoiceOver01_Max_010"] = "¿Qué? ¿Mi poder de volver el tiempo atrás no funciona en ella? No lo entiendo.",
  ["Act_E2_3A_Junkyard_Flyer_Look01_Max_010"] = "Se habrían ido hasta Los Ángeles por un reventón. Parece divertido.",
  ["Act_E2_3A_Junkyard_Graffiti02_Look01_Max_010"] = "Gracias por el consejo.",
  ["Act_E2_3A_Junkyard_Graffiti05_Look01_Max_010"] = "Ay.",
  ["Act_E2_3A_Junkyard_Graffiti07_Interact01_Max_010"] = "Ahora somos oficialmente un trío... solo tenemos que encontrar a Rachel.",
  ["Act_E2_3A_Junkyard_Graffiti07_Look01_Max_010"] = "No quiero entrometerme, pero... Estuve aquí.",
  ["Act_E2_3A_Junkyard_Makeup_Look01_Max_010"] = "No me imagino a Chloe con maquillaje...",
  ["Act_E2_3A_Junkyard_MaxAfterEllipse_VoiceOver01_Max_010"] = "Dios, este poder sí que me confunde. Me alegra volver a sentirme normal. Será mejor que vaya a hablar con Chloe.",
  ["Act_E2_3A_Junkyard_MessageInBottle_Look04_Max_040"] = "¿Qué pasa con esta extraña relación secreta? Parece que Rachel estaba confundida, o incluso avergonzada... Lástima que no dio nombres. Mejor no se lo muestro o la voy a lastimar seriamente.",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_010"] = "¿Dónde podré encontrar botellas? Tal vez en un refrigerador viejo...",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_020"] = "Quizás haya botellas viejas en ese cobertizo...",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_030"] = "Donde hay un barco, hay un pirata... lo que significa botellas de alcohol.",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_040"] = "Sé que hay un lugar por aquí donde la gente hace fiestas alrededor de una fogata...",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_050"] = "Tal vez alguien haya dejado botellas en alguno de los cacharros...",
  ["Act_E2_3A_Junkyard_MessageInBottle_VoiceOver01_Max_060"] = "Maldita sea, casi le disparo a este tipo, y ahora Chloe y yo corremos aún más peligro.",
  ["Act_E2_3A_Junkyard_Mixtape_Look01_Max_010"] = "\"Canciones para Rachel\". Me pregunto si Chloe haría una mezcla de canciones para mí.",
  ["Act_E2_3A_Junkyard_NoShootFrank_VoiceOver01_Max_010"] = "Ay, diablos, Frank se llevó el arma de Chloe por mi culpa...",
  ["Act_E2_3A_Junkyard_Object01_Look01_Max_010"] = "Oh, pobre. Te abandonaron aquí, solita...",
  ["Act_E2_3A_Junkyard_Object02_Look01_Max_010"] = "Irreparable. Que en paz descanses...",
  ["Act_E2_3A_Junkyard_Object03_Look01_Max_010"] = "Esto es lo más aterrador de este lugar...",
  ["Act_E2_3A_Junkyard_Object04_Look01_Max_010"] = "Los Pies Grandes estuvieron aquí...",
  ["Act_E2_3A_Junkyard_Object05_Look01_Max_010"] = "Estos cartuchos se ven bastante nuevos...",
  ["Act_E2_3A_Junkyard_ObjectiveBottles_VoiceOver01_Max_010"] = "Hora de encontrar esas botellas.",
  ["Act_E2_3A_Junkyard_ObjectiveBottles_VoiceOver01_Max_020"] = "Imaginemos que soy Lara Croft y que encuentro esas botellas.",
  ["Act_E2_3A_Junkyard_ObjectiveBottles_VoiceOver01_Max_030"] = "Oh, botellas... sé que se están escondiendo de mí... pero no por mucho tiempo.",
  ["Act_E2_3A_Junkyard_ObjectivePuzzle_VoiceOver01_Max_010"] = "Debería rebobinar y ayudar a Chloe a darle a esas botellas.",
  ["Act_E2_3A_Junkyard_ObjectivePuzzle_VoiceOver01_Max_020"] = "Eso fue fantástico, pero Chloe quiere derribar las botellas.",
  ["Act_E2_3A_Junkyard_ObjectivePuzzle_VoiceOver01_Max_030"] = "Vamos, Max. Rebobina y ayuda a Chloe a apuntar.",
  ["Act_E2_3A_Junkyard_OldSmallBoat_Look01_Max_010"] = "Es tan triste ver un barco encallado... Me pregunto quiénes habrán sido sus dueños y dónde estarán ahora...",
  ["Act_E2_3A_Junkyard_OldWashingMachine_Look01_Max_010"] = "Me pregunto cuántas generaciones de moda habrán pasado por esa lavadora...",
  ["Act_E2_3A_Junkyard_Paper_Look01_Max_010"] = "\"Quiero morir\". Dios. ¿Quién escribió esto?",
  ["Act_E2_3A_Junkyard_Photo_Look01_Max_010"] = "Realmente eran mejores amigas. Podría haber sido yo en lugar de Rachel...",
  ["Act_E2_3A_Junkyard_PieceRachelClothing_Look01_Max_010"] = "Esta era una blusa punk de la vieja escuela...",
  ["Act_E2_3A_Junkyard_SchoolBus_Look01_Max_010"] = "Es difícil pensar que alguna vez recorría las carreteras, lleno de estudiantes...",
  ["Act_E2_3A_Junkyard_Shack_VoiceOver01_Max_010"] = "Parece un museo de grafitis de Chloe y Rachel... Apuesto que puedo averiguar más sobre Rachel aquí...",
  ["Act_E2_3A_Junkyard_Sign01_Look01_Max_010"] = "De ninguna manera... Recuerdo ir allí de niña, como si fuera ayer. Me encantaban las croquetas de maíz. Ahora no es más que basura de Arcadia Bay...",
  ["Act_E2_3A_Junkyard_Syringes_Look01_Max_010"] = "¡Asqueroso! Es tan desagradable ver jeringas viejas en el suelo...",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_010"] = "Este lugar es tan tranquilo y prístino...",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_020"] = "Siempre siento que el bosque me susurra...",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_030"] = "Como si Arcadia Bay intentara decirme algo...",
  ["Act_E2_3A_Junkyard_TrunkSit_Max_040"] = "Solo tengo que descifrar el mensaje...",
  ["Act_E2_3A_Junkyard_VortexFlyer_Look01_Max_010"] = "Entonces Rachel sí fue a la fiesta del club Vortex... La fecha de este volante es justo antes que desapareciera...",
  ["Act_E2_3A_Junkyard_WoodenPlankRewind_VoiceOver01_Max_010"] = "Fantástico. Ahora tengo que saltar desde aquí para salir del bote.",
  ["Act_E2_3A_Junkyard_WoodenPlank_Interact01_Max_010"] = "Mucho más pesada de lo que pensaba... ¡Uf!",
  ["Act_E2_3A_Junkyard_WoodenPlank_Look01_Max_010"] = "Mmmm... Podría usar esta tabla como puente. No parece muy pesada...",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Chloe_010"] = "Sí que me asustaste. ¿Te sientes mejor?",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Chloe_030"] = "¿Demasiada acción para Arcadia?",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Chloe_050"] = "Dime cuando te sientas mejor.",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Max_020"] = "Un poco. Gracias por ayudarme, solo... dame un minuto...",
  ["Cue_E2_3A_Junkyard_AfterEllipse_Max_040"] = "Tal vez no lo suficiente. Esto es un poco divertido. Escalofriante y estúpido, pero divertido.",
  ["Cue_E2_3A_Junkyard_Bottle01Fail01_IGE_Chloe_020"] = "Estoy en ello.",
  ["Cue_E2_3A_Junkyard_Bottle01Fail01_IGE_Max_010"] = "Apunta un poco más a tu izquierda.",
  ["Cue_E2_3A_Junkyard_Bottle01Fail02_IGE_Chloe_020"] = "Objetivo a la vista.",
  ["Cue_E2_3A_Junkyard_Bottle01Fail02_IGE_Max_010"] = "Apunta un poco más arriba.",
  ["Cue_E2_3A_Junkyard_Bottle01Fail03_IGE_Chloe_020"] = "Sí, señora.",
  ["Cue_E2_3A_Junkyard_Bottle01Fail03_IGE_Max_010"] = "Apunta un poquitín más abajo.",
  ["Cue_E2_3A_Junkyard_Bottle01FailChloe_IGE_Chloe_010"] = "¿Y, Max?",
  ["Cue_E2_3A_Junkyard_Bottle01FailChloe_IGE_Chloe_020"] = "Guíame, Max.",
  ["Cue_E2_3A_Junkyard_Bottle01FailChloe_IGE_Max_030"] = "Primero tengo que verte disparar.",
  ["Cue_E2_3A_Junkyard_Bottle01Success_IGE_Chloe_020"] = "¡Señor! ¡Sí, señor!",
  ["Cue_E2_3A_Junkyard_Bottle01Success_IGE_Max_010"] = "Apunta un poco más a la derecha.",
  ["Cue_E2_3A_Junkyard_Bottle02Fail01_IGE_Chloe_010"] = "Chloe Bond se encargará.",
  ["Cue_E2_3A_Junkyard_Bottle02Fail02_IGE_Chloe_010"] = "Bip, bip, rastreador láser activado.",
  ["Cue_E2_3A_Junkyard_Bottle02Fail03_IGE_Chloe_010"] = "Lista para disparar...",
  ["Cue_E2_3A_Junkyard_Bottle02FailChloe_IGE_Chloe_010"] = "¿Adónde apunto, Max?",
  ["Cue_E2_3A_Junkyard_Bottle02FailChloe_IGE_Max_030"] = "Está en tu mira, presiona el gatillo.",
  ["Cue_E2_3A_Junkyard_Bottle02Success_IGE_Chloe_010"] = "Justo al blanco...",
  ["Cue_E2_3A_Junkyard_Bottle03Fail01_IGE_Chloe_020"] = "Odio los tablones viejos.",
  ["Cue_E2_3A_Junkyard_Bottle03Fail01_IGE_Max_010"] = "Apunta a este tablón azul viejo.",
  ["Cue_E2_3A_Junkyard_Bottle03Fail02_IGE_Chloe_020"] = "¡Las reiniciaremos de un balazo!",
  ["Cue_E2_3A_Junkyard_Bottle03Fail02_IGE_Max_010"] = "Apuesto que quieres volar esos monitores viejos.",
  ["Cue_E2_3A_Junkyard_Bottle03Fail03_IGE_Chloe_020"] = "Lo siento, Sr. Barril, ha llegado su hora.",
  ["Cue_E2_3A_Junkyard_Bottle03Fail03_IGE_Max_010"] = "Veamos si puedes con ese barril oxidado.",
  ["Cue_E2_3A_Junkyard_Bottle03FailChloe_IGE_Chloe_010"] = "Dime a qué le disparo, Max.",
  ["Cue_E2_3A_Junkyard_Bottle03FailChloe_IGE_Chloe_020"] = "¡Hola! ¿a qué le disparo?",
  ["Cue_E2_3A_Junkyard_Bottle03FailChloe_IGE_Chloe_040"] = "Bien, ya que no quieres jugar, le dispararé a este barril. Aburrido.",
  ["Cue_E2_3A_Junkyard_Bottle03Success_IGE_Chloe_020"] = "Llanta en la mira...",
  ["Cue_E2_3A_Junkyard_Bottle03Success_IGE_Max_010"] = "Dale a esa llanta a tu izquierda.",
  ["Cue_E2_3A_Junkyard_Bottle04Fail01_IGE_Chloe_020"] = "¡Atrás, el tanque va a explotar!",
  ["Cue_E2_3A_Junkyard_Bottle04Fail01_IGE_Max_010"] = "Veamos qué pasa si le disparas al tanque de gas.",
  ["Cue_E2_3A_Junkyard_Bottle04Fail02_IGE_Chloe_020"] = "Adiós, parachoques cruel...",
  ["Cue_E2_3A_Junkyard_Bottle04Fail02_IGE_Max_010"] = "Dale una buena abolladura a ese parachoques delantero.",
  ["Cue_E2_3A_Junkyard_Bottle04Fail03_IGE_Chloe_020"] = "¡Cuidado, vuelan vidrios!",
  ["Cue_E2_3A_Junkyard_Bottle04Fail03_IGE_Max_010"] = "Quiero ver volar ese parabrisas.",
  ["Cue_E2_3A_Junkyard_Bottle04FailChloe_IGE_Chloe_020"] = "Amiga, necesito un objetivo para disparar.",
  ["Cue_E2_3A_Junkyard_Bottle04FailChloe_IGE_Chloe_040"] = "Bueno, ya que no me ayudas, volaré ese parachoques.",
  ["Cue_E2_3A_Junkyard_Bottle04Fail_IGE_Chloe_020"] = "Y la botella sigue en pie.",
  ["Cue_E2_3A_Junkyard_Bottle04Fail_IGE_Chloe_030"] = "Se siente bien, pero no le di ni a una botella.",
  ["Cue_E2_3A_Junkyard_Bottle04Fail_IGE_Chloe_050"] = "Debo librar al mundo de estas botellas.",
  ["Cue_E2_3A_Junkyard_Bottle04Success_IGE_Chloe_020"] = "Adiós, rueda de la muerte...",
  ["Cue_E2_3A_Junkyard_Bottle04Success_IGE_Max_010"] = "¿Qué tal si le damos al neumático izquierdo?",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_001"] = "Podemos tener el mundo a nuestros pies... ¿Estás lista?",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_003"] = "Amiga, si lo jodes, rebobinas y lo arreglas. Haz tu magia. ¡Bum!",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_005"] = "Ya cambiaste la historia cuando me salvaste la vida, sabelotodo. Veamos qué más puedes hacer...",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_006"] = "Tengo que preparar el campo de tiro, llorona. Aún me pregunto cómo conseguiste ese poder...",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Chloe_009"] = "Amén. Y, mientras construyes tu imperio, yo estaré ahí para mantenerte en un camino bien chingón. Y divertido.",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_002"] = "De ningún modo. Ni siquiera sé cómo funciona mi poder ni por cuánto tiempo...",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_004"] = "Oh, sí. Cuando entienda cómo funciona mi poder exactamente. Un dios debe saber esas cosas.",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_007"] = "De Dios. O los dioses. Ponte de rodillas.",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_008"] = "Así que tengo que buscar botellas cochinas mientras tú te relajas. No es justo.",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase01_Max_010"] = "Borrón y cuenta nueva... No hago más que alterar el tiempo y el espacio. Ah, sí, y el curso de la historia. Nada del otro mundo.",
  ["Cue_E2_3A_Junkyard_CHChloe_Phase02_Chloe_001"] = "Yo preparo el campo de tiro; tú busca unas botellas.",
  ["Cue_E2_3A_Junkyard_FrankConflict_AlternateStart_Chloe_010"] = "¿Estás lista para hacerlo?",
  ["Cue_E2_3A_Junkyard_FrankConflict_AlternateStart_Chloe_030"] = "¡Tenemos todo el tiempo del mundo para hacer lo que queramos, cuando se nos dé la gana!",
  ["Cue_E2_3A_Junkyard_FrankConflict_AlternateStart_Max_020"] = "Larguémonos antes de que...",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_040"] = "Déjanos, Frank.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_060"] = "No nos parecemos en nada.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_080"] = "Tendrás tu dinero.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_110"] = "¿De dónde sacaste ese brazalete?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_130"] = "Es el brazalete de Rachel. ¿Por qué chingados tienes su brazalete?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Chloe_150"] = "Por supuesto que no. Lo robaste. Dámelo ahora mismo, pendejo.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_020"] = "Vaya, pero si son Thelma y Louise.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_030"] = "¿O Bonnie y Clyde tal vez?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_050"] = "Oh, lo siento, Chloe. No quise interrumpir tu reunión. Escuché disparos y ruido de vidrios rotos. Qué simpática, jugando con armas. Como yo cuando tenía tu edad.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_070"] = "Ambos necesitamos dinero. De hecho, lo necesitas de verdad. Me debes un chingo. ¿No es así, Chloe? ¿Eh?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_090"] = "Todos dicen lo mismo, ¿no? Hasta cuando están arruinados y se hacen los rudos...",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_100"] = "¿Qué escondes ahí, chiquilla? ¡Muéstrame!",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_120"] = "De un amigo. Y no es de tu maldita incumbencia. Ahora estamos hablando de ti y...",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_140"] = "¿Cálmate, sí? Fue un regalo.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_160"] = "Te aconsejo que te apartes antes de que te arrepientas, niña. Hablo en serio. ¿Quieres un corte, perra?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Frank_180"] = "Estás bromeando. Baja eso.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Max_010"] = "Hazme sentir orgullosa, hermana.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Arrival_Max_170"] = "Vamos... hazte a un lado, por favor.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_060"] = "Te mantuviste muy firme.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_080"] = "Va a ser difícil defenderme de Nathan. Mi maldito padrastro ya debe tener el resto de sus armas en un búnker electrificado.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_100"] = "Lo sé, Max. En serio. A decir verdad, es un alivio que haya resultado así...",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_110"] = "Y siempre habrá más armas.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Chloe_120"] = "Vámonos. Mi guarida secreta no fue secreta para nada hoy. Al menos Frank se fue, no volverá a meterse con nosotras. Solo quiere su dinero.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_010"] = "Vamos, niñita. Dispara.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_020"] = "Ay, Dios. Son más bien como Abbot y Costello.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_040"] = "Linda fusca. Lo tomaré como interés de tu préstamo. Gracias.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Frank_050"] = "Tienes hasta el viernes para pagarme. O te iré a buscar con este interés. Jueguen bien, niñas.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Max_070"] = "Entré en pánico. No me gustan las armas.",
  ["Cue_E2_3A_Junkyard_FrankConflict_DropTheGun_Max_090"] = "Lo siento, Chloe. Nunca le había apuntado a nadie en mi vida. Muy mala onda.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Chloe_070"] = "Estuviste genial. Gracias por defenderme...",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Chloe_080"] = "Vámonos. Mi guarida secreta no fue secreta para nada hoy. Al menos Frank se fue, no volverá a meterse con nosotras. Solo quiere su dinero.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_010"] = "¡Qué gracioso! Ay, Dios...",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_030"] = "No me olvidaré de ti, niña. No olvidaré que estuviste a punto de dispararme. Y mi memoria es tan buena que vas a desear que se me borre por completo.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_045"] = "Tienes hasta el viernes para pagarme. Ni se te ocurra volver a hacer estas chingaderas... porque será lo último que hagas.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Frank_050"] = "La próxima prueben con balas, cerebritos.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Shoot_Max_060"] = "Lo siento.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Chloe_010"] = "Bien, parece que ya estás lista para la acción.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Chloe_030"] = "¿Tienes miedo de meterte en problemas?",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Chloe_040"] = "Oh, bua, bua. ¡Max tiene miedo! Sé que puedes manejarlo. Y estoy aquí para guiarte.",
  ["Cue_E2_3A_Junkyard_FrankConflict_Start_Max_020"] = "No lo sé...",
  ["Cue_E2_3A_Junkyard_Gun01_Fail_Chloe_010"] = "¡Patético!",
  ["Cue_E2_3A_Junkyard_Gun01_Fail_Chloe_030"] = "Tienes que concentrarte de verdad para guiarme. Usa tus poderes maravillosos para el bien, oh, SuperMax.",
  ["Cue_E2_3A_Junkyard_Gun01_Fail_Max_020"] = "¡Oye, no es mi culpa!",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Chloe_010"] = "¡Oh, sí! ¿Viste eso, Max?",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Chloe_030"] = "¡Eso fue espectacular!",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Chloe_040"] = "Ahora a la segunda botella.",
  ["Cue_E2_3A_Junkyard_Gun01_Success_Max_020"] = "Puf.",
  ["Cue_E2_3A_Junkyard_Gun02_Fail_Chloe_010"] = "¡Esto apesta!",
  ["Cue_E2_3A_Junkyard_Gun02_Success_Chloe_010"] = "¡Ya verás, Nathan!",
  ["Cue_E2_3A_Junkyard_Gun02_Success_Chloe_020"] = "Esto sí que es divertido. Vayamos por más, dame otro objetivo. Me quiero poner creativa...",
  ["Cue_E2_3A_Junkyard_Gun03_Fail01_Chloe_010"] = "Me aburro...",
  ["Cue_E2_3A_Junkyard_Gun03_Fail02_Chloe_010"] = "De la vieja escuela...",
  ["Cue_E2_3A_Junkyard_Gun03_Fail02_Chloe_020"] = "¡Patético!",
  ["Cue_E2_3A_Junkyard_Gun03_Fail03_Chloe_020"] = "¡Escucha esos balazos terribles!",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Chloe_010"] = "¡Ay, sí!",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Chloe_030"] = "¡De eso estoy hablando!",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Chloe_050"] = "Nunca. Solo quiero un supertiro mágico más...",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Max_020"] = "Buen tiro, Tex.",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Max_040"] = "¿Satisfecha?",
  ["Cue_E2_3A_Junkyard_Gun03_Success_Max_060"] = "¿Qué tal si ahora usamos ese montón de chatarra como blanco?",
  ["Cue_E2_3A_Junkyard_Gun04_Fail01_Chloe_010"] = "¡Bum! El coche quedó totalmente destruido, ¡pero las botellas siguen sanas y salvas!",
  ["Cue_E2_3A_Junkyard_Gun04_Fail02_Chloe_010"] = "¡Dios mío, me disparé! ¡Me disparé a mí misma! ¡Rebobina, rebobina!",
  ["Cue_E2_3A_Junkyard_Gun04_Fail02_Max_020"] = "¡Pistola de mierda! ¡Resiste, Chloe!",
  ["Cue_E2_3A_Junkyard_Gun04_Fail03_Chloe_010"] = "Será mejor que vayan buscando un refugio.",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Chloe_010"] = "Megaincreíble.",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Chloe_020"] = "No puedo creer que esto sea real. ¡Mi mejor amiga es una superheroína! Ahora es tu turno de disparar.",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Chloe_040"] = "Max, tu nariz. Mierda...",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Max_030"] = "No lo sé...",
  ["Cue_E2_3A_Junkyard_Gun04_Success_Max_050"] = "Yo... no... me siento tan súper...",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_020"] = "¡Esto va a ser tan genial, amiga!",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_040"] = "Puedes retroceder el tiempo... ¡Ahora vamos a tener que ponerte a prueba para asegurarnos!",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_060"] = "Sígueme.",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_080"] = "Eso depende de ti. Y de cómo te vaya en esta parte de la prueba...",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_090"] = "Bienvenida a American Rust, mi refugio del infierno.",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_110"] = "Max, ¿entiendes lo asombroso que es esto? Mi mejor amiga volvió... y mejorada.",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_130"] = "Por eso mismo debemos divertirnos ahora.",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_150"] = "Uff...",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_160"] = "¿No confías en mí?",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_180"] = "Tienes más poder que un ejército entero. No le tengas miedo a mi juguetito. Además, lo necesitamos para la prueba...",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_200"] = "Solo las personas que no deberían. Como el Sgto. Imbécil. Hasta ahora.",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_220"] = "Tú eres la revolución, Max. Así que tendremos que aprender a usar y abusar de tus poderes con una prueba.",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_230"] = "¿Un trago?",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_250"] = "Eres tan tierna... no has cambiado en nada.",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_255"] = "Muy bien, hagámoslo. ¿Puedes buscar cinco botellas mientras preparo el campo de tiro?",
  ["Cue_E2_3A_Junkyard_Insertion_Chloe_270"] = "Tú puedes. Ve a buscar nuestras cinco botellas. ¿Porfis?",
  ["Cue_E2_3A_Junkyard_Insertion_Max_010"] = "¡Espera, Speedy González!",
  ["Cue_E2_3A_Junkyard_Insertion_Max_030"] = "Ve más despacio, espérame.",
  ["Cue_E2_3A_Junkyard_Insertion_Max_050"] = "¿Es una carrera?",
  ["Cue_E2_3A_Junkyard_Insertion_Max_070"] = "¿Cuántas veces vas a enojarte conmigo esta semana?",
  ["Cue_E2_3A_Junkyard_Insertion_Max_100"] = "Salvaje y áspero. Te queda...",
  ["Cue_E2_3A_Junkyard_Insertion_Max_120"] = "No sabemos por cuánto tiempo.",
  ["Cue_E2_3A_Junkyard_Insertion_Max_140"] = "¿Estás bromeando? Después de lo de ayer, no quiero saber nada de armas, Chloe. Me asusta que tengas una.",
  ["Cue_E2_3A_Junkyard_Insertion_Max_170"] = "Sí, pero no en el arma.",
  ["Cue_E2_3A_Junkyard_Insertion_Max_190"] = "David será un idiota, pero al final robaste su arma... ¿Ahora todos portan armas en Arcadia Bay?",
  ["Cue_E2_3A_Junkyard_Insertion_Max_210"] = "Todavía no estoy en la revolución, Che.",
  ["Cue_E2_3A_Junkyard_Insertion_Max_240"] = "Qué asco.",
  ["Cue_E2_3A_Junkyard_Insertion_Max_260"] = "Cerveza y armas, qué buena combinación.",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_005"] = "Gracias, Max.",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_010"] = "Espera... uno más para el camino.",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_030"] = "¡Vamos a disparar a todas estas botellas sin desperdiciar ni una sola bala!",
  ["Cue_E2_3A_Junkyard_IntroGun_Chloe_040"] = "Max, tienes que ayudarme a apuntar.",
  ["Cue_E2_3A_Junkyard_IntroGun_Max_020"] = "Hablas en serio...",
  ["Cue_E2_3A_Junkyard_Preparing_Chloe_010"] = "¡Hora de destruir!",
  ["Act_E2_3B_Railroad_BreakingMechanism_VoiceOver01_Max_010"] = "Tengo que ayudar a subir a Chloe.",
  ["Act_E2_3B_Railroad_CHChloe_Interact01_Max_010"] = "No quiero usar esta hacha... Dios mío, Max, no es un zombi, ¡busca otra solución!",
  ["Act_E2_3B_Railroad_CHChloe_Look01_Max_010"] = "Max, no puedes sacar a Chloe de un tirón como si fueras una superheroína. ¡Muévete!",
  ["Act_E2_3B_Railroad_CHChloe_Look02_Max_010"] = "Max, la regaste. ¡Ahora saca a Chloe de ahí por tu cuenta, superheroína!",
  ["Act_E2_3B_Railroad_CHMax_Interact01_Max_010"] = "¿Qué alambre cortar?",
  ["Act_E2_3B_Railroad_CHMax_Look01_Max_010"] = "Como si supiera qué alambre cortar...",
  ["Act_E2_3B_Railroad_CHMax_VoiceOver01_Max_010"] = "Será mejor que encuentre una herramienta para cortar los alambres...",
  ["Act_E2_3B_Railroad_CableDrum_Interact01_Max_010"] = "Vaya, destruí por completo la palanca de desvío. Debería ayudarme a liberar a Chloe, pero podría haberlo hecho de otra manera…",
  ["Act_E2_3B_Railroad_CableDrum_Interact02_Max_010"] = "¡Maldición! ¡Algo está bloqueando el tambor!",
  ["Act_E2_3B_Railroad_CableDrum_Look01_Max_010"] = "No sé. Se ve muy pesado... y justo sobre la palanca de desvío…",
  ["Act_E2_3B_Railroad_CableGreen_Interact01_Max_010"] = "Estúpida luz. No hay caso. Mierda.",
  ["Act_E2_3B_Railroad_CableRed_Interact01_Max_010"] = "¡Ese es el cable correcto!",
  ["Act_E2_3B_Railroad_CableYellow_Interact01_Max_010"] = "¡Vaya, la ciudad de los cortocircuitos!",
  ["Act_E2_3B_Railroad_Cables_Interact01_Max_010"] = "Tal vez un hacha no sea la mejor herramienta de precisión para electrónica...",
  ["Act_E2_3B_Railroad_Cables_Interact02_Max_010"] = "¿Qué cable cortar?",
  ["Act_E2_3B_Railroad_Cables_Look01_Max_010"] = "Como si supiera qué cable cortar...",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver01_Max_010"] = "¡Otra visión de tornado, y ahora Chloe necesita ayuda!",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver01_Max_020"] = "¡Ay, mierda! ¡Tengo que sacar a Chloe de ahí!",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver02_Max_010"] = "¡Tengo que encontrar la manera de ayudar a Chloe!",
  ["Act_E2_3B_Railroad_ChloeStuck_VoiceOver03_Max_010"] = "Tal vez en el cobertizo encuentre herramientas para salvar a Chloe...",
  ["Act_E2_3B_Railroad_Crowbar_Interact01_Max_010"] = "¡Sí! ¡Definitivamente me será útil!",
  ["Act_E2_3B_Railroad_Crowbar_Look01_Max_010"] = "¡Una barreta! ¡Es justo lo que necesito!",
  ["Act_E2_3B_Railroad_DoorLock_Interact01_Max_010"] = "Adentro y afuera. No hay problema.",
  ["Act_E2_3B_Railroad_DoorLock_Look01_Max_010"] = "¡Eh, genial! Ahora no tengo que forzar la puerta desde el otro lado.",
  ["Act_E2_3B_Railroad_FuseBox_Interact01_Max_010"] = "¡Fantástico! ¡Está abierta!",
  ["Act_E2_3B_Railroad_FuseBox_Look01_Max_010"] = "Mmm, tal vez pueda abrir esta caja de fusibles.",
  ["Act_E2_3B_Railroad_Hatchet_Interact01_Max_010"] = "Bien, ¿qué puedo cortar con esto?",
  ["Act_E2_3B_Railroad_Hatchet_Look01_Max_010"] = "Vaya, esa hacha se ve filosa... demasiado filosa... Espera un momento...",
  ["Act_E2_3B_Railroad_Pliers_Interact01_Max_010"] = "¡Ahora puedo ser como MacGyver!",
  ["Act_E2_3B_Railroad_Pliers_Look01_Max_010"] = "¡Sí! ¡Pinzas!",
  ["Act_E2_3B_Railroad_ReleasingMechanism_VoiceOver01_Max_010"] = "Vamos, Max... tú puedes... ¡tira de la maldita palanca!",
  ["Act_E2_3B_Railroad_ShedDoor_Interact01_Max_010"] = "¡En el blanco!",
  ["Act_E2_3B_Railroad_ShedDoor_Interact02_Max_010"] = "¡Mierda! ¡No puedo moverla ni un poco!",
  ["Act_E2_3B_Railroad_ShedDoor_Look01_Max_010"] = "Obvio que la puerta está cerrada. Tengo que entrar a la fuerza.",
  ["Act_E2_3B_Railroad_Switching_Interact01_Max_010"] = "¡No puedo moverla ni un centímetro!",
  ["Act_E2_3B_Railroad_Switching_Interact02_Max_010"] = "¡Ni siquiera puedo moverla con esta barreta! ¿En serio?",
  ["Act_E2_3B_Railroad_Switching_Interact03_Max_010"] = "¡Sí! ¡Lo hice!",
  ["Act_E2_3B_Railroad_Switching_Look01_Max_010"] = "¡Tengo que tirar de la palanca de desvío ahora mismo!",
  ["Act_E2_3B_Railroad_Wedge_Interact01_Max_010"] = "Ahora finalmente puedo mover el tambor.",
  ["Act_E2_3B_Railroad_Wedge_Interact02_Max_010"] = "¡Mierda! ¡Esta atorada! Necesito algo para moverla...",
  ["Act_E2_3B_Railroad_Wedge_Look01_Max_010"] = "Esta cuña lo mantiene en su lugar...",
  ["Cue_E2_3B_Railroad_CHChloe_ChloeStuck_Chloe_001"] = "¡Sácame de aquí, Max!",
  ["Cue_E2_3B_Railroad_CHChloe_ChloeStuck_Chloe_002"] = "¡Encuentra algo! ¡Sácame!",
  ["Cue_E2_3B_Railroad_CHChloe_ChloeStuck_Chloe_003"] = "¡No quiero morir aquí!",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_039"] = "Necesitamos un nuevo escondite... En el que Frank no pueda encontrarnos. ¿Estás bien, Max?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_044"] = "Lo siento. Frank no es tan malo como parece. Lo único que le importa es su dinero, sus drogas y su perro sarnoso.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_047"] = "Lo sé, Max. La mierda sin sentido ya es común en mi vida... Por eso planeaba irme de Arcadia Bay sin devolverle el dinero a Frank...",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_049"] = "Frank Bowers. Un traficante de drogas. Es quien me da mi hierba. La de tu cigarro, ¿recuerdas? Como sea, Frank y yo medio que salíamos.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_050"] = "Frank Bowers. Obvio que no eres mi contacto, ¿recuerdas? Como sea, Frank y yo medio que salíamos.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_053"] = "No, no tuvimos sexo. Dios, qué asco. Ni siquiera lo intentó. Simplemente cometí el error de pedirle dinero para que Rachel y yo pudiéramos largarnos de aquí...",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_054"] = "No, es mi etapa de \"trataré de conseguir dinero fácil para que Rachel y yo podamos largarnos de este lugar\". Frank podía dármelo. Eso es todo.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_056"] = "No. Quiero saber cómo es que el brazalete de Rachel terminó en manos de Frank... ¿Qué piensas?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_062"] = "No son tan distintas. Ella tenía... tiene muy buen ojo para la fotografía y el arte. Además, es sabelotodo como tú. Seguro que las tres seríamos \"mejores amigas por siempre\".",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Chloe_064"] = "Es tan raro estar hablándote de esta mierda. No habíamos pasado tanto tiempo juntas desde que éramos niñas... y parece que fuera ayer. Desearía que Rachel estuviera aquí y se conocieran...",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_041"] = "¿No podemos construir un nuevo fuerte pirata y mantenernos alejadas del mundo?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_042"] = "Todavía tengo los pelos de punta por lo que acaba de pasar. Fue horrible, Chloe.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_043"] = "¿En verdad piensas que Frank va a tratar de encontrarnos?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_045"] = "¿Neta, Chloe? ¡Frank acaba de llevarse tu arma y nos amenazó! Está armado y claramente es peligroso.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_046"] = "Chloe, ¿no viste lo que acaba de pasar? ¡Casi le disparo! Sé que podría rebobinar, pero Chloe, esto no es un juego. No más armas.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_048"] = "Ahora dime exactamente qué es lo que pasa entre Frank y tú... ¿Tiene apellido?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_051"] = "¿Salían? No querrás decir...",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_052"] = "¿Es tu etapa de \"chicos malos\"?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_055"] = "¿Eso es todo?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_057"] = "Creo que tenemos que tener cuidado. Y estar atentas a este tipo. Sin que lo sepa, ¿de acuerdo?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_058"] = "Ya no sé nada. Tengo el cerebro quemado de todo esto. Necesito un enema mental.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_060"] = "¿Crees que Rachel y yo hubiéramos sido amigas?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_061"] = "¿Por qué? Apuesto que me odiaría.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_063"] = "No habíamos pasado tiempo juntas desde que éramos chicas y parece que fuera ayer. Así sabes que alguien es tu amiga de verdad.",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_065"] = "En serio, Chloe, esto es aterrador. ¿Y si Frank trata de encontrarnos?",
  ["Cue_E2_3B_Railroad_CHChloe_FrankTalk_Max_066"] = "Apuesto que es tan genial como tú. Seguro nos conoceremos pronto.",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Chloe_020"] = "Volviste a salvarme. Qué loco. ¡Ahora estamos unidas para siempre!",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Chloe_040"] = "Tengo astillas hasta el culo. Me podrías haber salvado de una manera menos violenta.|Y ahora los trenes no podrán llegar al aserradero... Ups.",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Max_010"] = "Diablos, eso estuvo cerca.",
  ["Cue_E2_3B_Railroad_CHChloe_Interact02_Max_030"] = "¿Estás bien?",
  ["Cue_E2_3B_Railroad_Extraction_Chloe_010"] = "¿No te alegra que te haya traído a un lugar tranquilo y desolado?",
  ["Cue_E2_3B_Railroad_Extraction_Chloe_030"] = "Ya que tú eres la superheroína misteriosa... Yo seré tu chofer y compañera fiel.",
  ["Cue_E2_3B_Railroad_Extraction_Chloe_050"] = "No importa... nosotras sí. Para siempre.",
  ["Cue_E2_3B_Railroad_Extraction_Max_020"] = "Fue genial pasar tiempo en tu guarida. Pero debo regresar a la escuela para mi próxima clase...",
  ["Cue_E2_3B_Railroad_Extraction_Max_040"] = "Tal vez mis poderes no duren mucho, Chloe.",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Chloe_050"] = "¿Max? ¡Ayuda! ¡Estoy atorada!",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_010"] = "Perfecto...",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_020"] = "Oh, pinche hijo de...",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_030"] = "Ese tornado de mierda no fue un sueño...",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_040"] = "¿Qué es ese ruido? El tren... ¡Ay, mierda!",
  ["Cue_E2_3B_Railroad_Insertion_ChloeTrapped_Max_060"] = "¡Resiste, Chloe!",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_010"] = "Todavía no puedo creer que hayas amenazado a Frank con un arma. Eso fue épico.",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_030"] = "Puedes rebobinar y dársela en el culo a Frank con el arma. ¡Tienes el poder!",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_050"] = "No puedo creer que prácticamente le hayas regalado mi arma. \"Aquí tienes, Frank\".",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_070"] = "No estoy enojada. Solo te sumas a mi lista de personas que me han decepcionado. Y me gustaba tener esa arma, amiga.",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_090"] = "Me alegra que estuvieras conmigo.",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_110"] = "Tomémonos un descanso, y te lo explico.",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Chloe_120"] = "Parece otro mundo, ¿no? Desearía que nos pudiéramos quedar aquí para siempre.",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_020"] = "Fue horrible. Menos mal que no estaba cargada...",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_040"] = "Qué asquerosa. ¡No te caigas!",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_060"] = "Puedes dejar de enojarte conmigo. Especialmente por tonterías.",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_080"] = "Ahora estoy aquí para protegerte.",
  ["Cue_E2_3B_Railroad_Insertion_Dial01_Max_100"] = "A mí también... Creo.|Chloe, ¿por qué diablos te juntas con perdedores siniestros como Frank? Es raro.",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Chloe_010"] = "Las vías del tren siempre me hacen sentir mejor. No tengo idea de por qué...",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Chloe_030"] = "Parece que tenemos una poeta posmoderna.",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Chloe_050"] = "Lo eres. Solo tienes que dejar de tener miedo...",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Max_020"] = "Kerouac sí sabía. Es la sensación romántica de los viajes y el movimiento... El sonido del silbato del tren por las noches...",
  ["Cue_E2_3B_Railroad_Insertion_PostDial1_Max_040"] = "Prefiero ser una buena fotógrafa.",
  ["Cue_E2_3B_Railroad_Switching_Interact03_Chloe_030"] = "Espero que el tren tenga un buen viaje... porque como que le cambiamos la ruta...",
  ["Cue_E2_3B_Railroad_Switching_Interact03_Max_020"] = "Absolutamente.",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_010"] = "¡Vamos, Max! ¡Apúrate!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_020"] = "¡Por favor, sácame de aquí!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_030"] = "¡Max!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_040"] = "¡El tren se está acercando! ¡Max, por favor!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_050"] = "¡Max, sácame de aquí!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_060"] = "¡Por favor!",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_070"] = "Por favor...",
  ["Cue_E2_3B_Railroad_TrainLoop_Chloe_080"] = "¡¡¡Por favor!!!",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_002"] = "Mira, tu poder de rebobinar debe estar relacionado con la nevada de ayer. Eso podría explicar tu visión del tornado...",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_005"] = "Abre los ojos, Max. Ya me salvaste la vida dos veces. Alteraste el curso de mi destino, el tuyo y quién sabe el de quién más. ¿Sabes algo sobre la teoría del caos?",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_020"] = "Hace cinco años, babas. Algunas personas cambian... y tu situación es el peor escenario para la física cuántica.",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_021"] = "No, \"locuras pasan\". Porque puede pasar. Y pasará.",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Chloe_023"] = "Es un ejemplo perfecto de \"atractores extraños\". ¿Acaso no les enseñan nada en Blackwell? Tenemos un tornado, el poder de rebobinar y una nevada extraña... ¡Bienvenido, fin del mundo! Así que divirtámonos con tu poder, estrella de rock.",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_001"] = "Nunca nos pasa nada emocionante, ¿verdad?",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_003"] = "No entiendo cómo. Es tan aleatorio, chingado...",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_004"] = "¿Explicar qué? ¿Que haya nevado quiere decir que un tornado descomunal destruirá Arcadia Bay? Estás drogada.",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_018"] = "¿Y tú qué sabes sobre la teoría del caos, señorita \"odio la matemática\"?",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_019"] = "Ah... Quiere decir que \"son cosas que pasan\", ¿verdad?",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_022"] = "¿Por qué a mí? No soy más que una ñoña de pueblo.",
  ["Cue_E2_4A_CampusA_CHChloe_Phase01_Max_024"] = "Tal como usted dijo, profesora Price... toda superheroína necesita una mano derecha.",
  ["Cue_E2_4A_CampusA_CarArriving_Chloe_020"] = "Gracias por venir conmigo. Siento ser tan aburrida...",
  ["Cue_E2_4A_CampusA_CarArriving_Chloe_040"] = "¿Cómo puede ser una semana tan de mierda y a la vez la mejor de mi vida?",
  ["Cue_E2_4A_CampusA_CarArriving_David_060"] = "Compañeras en el crimen, chingado.",
  ["Cue_E2_4A_CampusA_CarArriving_Max_010"] = "Gracias por traerme, Chloe. Justo a tiempo para mi clase de arte.",
  ["Cue_E2_4A_CampusA_CarArriving_Max_030"] = "Nunca nos pasa nada emocionante, ¿verdad?",
  ["Cue_E2_4A_CampusA_CarArriving_Max_050"] = "¡Porque volvimos a la acción!",
  ["Act_E2_4B_ArtClass_ArcadiaPicture01_Look01_Max_010"] = "Arcadia Bay luce mucho más majestuosa desde aquí...",
  ["Act_E2_4B_ArtClass_ArcadiaPicture02_Look01_Max_010"] = "Hasta en las fotos, el bosque de la zona luce misterioso...",
  ["Act_E2_4B_ArtClass_CHAlyssa_Look01_Max_010"] = "Alyssa sí que vive para sus clases...",
  ["Act_E2_4B_ArtClass_CHDana_Look01_Max_010"] = "Dana está lista para sus 15 minutos de fama.",
  ["Act_E2_4B_ArtClass_CHDaniel_Look01_Max_010"] = "Daniel siempre es un espectador, nunca participante...",
  ["Act_E2_4B_ArtClass_CHHayden_Look01_Max_010"] = "Es difícil no querer a Hayden porque... todo le vale un carajo.",
  ["Act_E2_4B_ArtClass_CHMax_VoicesOver01_Max_010"] = "Tengo algo de tiempo antes de la clase del Señor Jefferson, así que... puedo recorrer un poco.",
  ["Act_E2_4B_ArtClass_CHMax_VoicesOver01_Max_020"] = "Estos idiotas de élite no paran de planear grandes fiestas... Otra oportunidad para que Nathan Prescott drogue a alguien...",
  ["Act_E2_4B_ArtClass_CHNathan_Look01_Max_010"] = "No puedo creer que el director lo deje quedarse en la escuela después de que le conté lo que ocurrió.",
  ["Act_E2_4B_ArtClass_CHNathan_Look02_Max_010"] = "Debería haberle contado al director lo de Nathan y el arma como seguro de vida...",
  ["Act_E2_4B_ArtClass_CHStella_Look01_Max_010"] = "Stella hace bien en mantenerse fuera de todo el drama.",
  ["Act_E2_4B_ArtClass_CHTaylor_Look01_Max_010"] = "Me gusta el lado artístico de Taylor, no su personalidad.",
  ["Act_E2_4B_ArtClass_CHTrevor_Look01_Max_010"] = "Trevor inspecciona su territorio.",
  ["Act_E2_4B_ArtClass_CHVictoria_Look01_Max_010"] = "Me siento tan rara después de haberme portado mal con Victoria ayer...",
  ["Act_E2_4B_ArtClass_CHVictoria_Look02_Max_010"] = "Aunque Victoria me ignore, me alegra que hayamos hablado ayer.",
  ["Act_E2_4B_ArtClass_DanielDrawing_Look01_Max_010"] = "Ese dibujo de Dana es genial. Daniel de verdad tiene talento.",
  ["Act_E2_4B_ArtClass_EverydayHeroesPoster_Look01_Max_010"] = "Creo que ya no tengo tiempo para entregar una foto para el concurso. ¡Qué irónico!",
  ["Act_E2_4B_ArtClass_GroupPhoto_Look01_Max_010"] = "Eso fue genial, cuando la primera semana, el Sr. Jefferson tomó una foto de la clase. Aunque yo no quería estar en la foto, me pareció bastante increíble verlo en acción.",
  ["Act_E2_4B_ArtClass_JeffPoster01_Look01_Max_010"] = "Adoro ver las increíbles fotos del Sr. Jefferson en estas portadas.",
  ["Act_E2_4B_ArtClass_JeffPoster02_Look01_Max_010"] = "Es fantástico poder ver las fotos publicadas del Sr. Jefferson. Me da esperanza.",
  ["Act_E2_4B_ArtClass_JeffersonCamera_Look01_Max_010"] = "¡Vaya! El Sr. Jefferson sí que sabe lo que es una cámara. Seguro que pagó veinte mil dólares por ella... Apuesto a que obtiene imágenes digitales impecables. Igual, adoro mi pequeña cámara instantánea.",
  ["Act_E2_4B_ArtClass_KateChair_Look01_Max_010"] = "Creo que Kate ya no vendrá a clase... Me preocupa.",
  ["Act_E2_4B_ArtClass_ObjectOnMaxDesk_Look01_Max_010"] = "Es genial que el Sr. Jefferson haya publicado su propio libro de consejos sobre fotografía.",
  ["Act_E2_4B_ArtClass_Printer_Look01_Max_010"] = "Esa impresora es fenomenal. Me encantaría ver cómo reproduce mis fotos. Podría armar una galería entera con esa cosa. Cuando deje de ser tan mala. Algún día...",
  ["Act_E2_4B_ArtClass_SeeDavid_VoiceOver01_Max_010"] = "Bien, ¿por qué David está tomando fotos de Kate? Está muy mal. Y es extraño...",
  ["Act_E2_4B_Corridor_BlackwellNotice01_Look01_Max_010"] = "Debería sentirme afortunada de estar aquí.",
  ["Act_E2_4B_Corridor_BlackwellNotice02_Look01_Max_010"] = "De todos modos, traer un arma a clase tiene su onda.",
  ["Act_E2_4B_Corridor_BlackwellNotice03_Look01_Max_010"] = "¿Desesperados? Ya estamos aquí...",
  ["Act_E2_4B_Corridor_Board02_Look01_Max_010"] = "Se puede aprender mucho sobre una escuela por la mierda rara que publican en los tableros.",
  ["Act_E2_4B_Corridor_CHCourtney_Look01_Max_010"] = "Courtney haría cualquier cosa por Victoria y el club Vortex...",
  ["Act_E2_4B_Corridor_CHDavid_Look01_Max_010"] = "Si tan solo supiera los planes de David Madsen...",
  ["Act_E2_4B_Corridor_CHEvan_Look01_Max_010"] = "Me encanta que Evan actúe tan por encima del club Vortex y todo lo demás.",
  ["Act_E2_4B_Corridor_CHJefferson_Look01_Max_010"] = "Apuesto que el Sr. Jefferson ha tenido que lidiar con muchos alumnos con problemas.",
  ["Act_E2_4B_Corridor_CHJuliet_Look01_Max_010"] = "Juliet está dándole una paliza a Zachary.",
  ["Act_E2_4B_Corridor_CHJustin_Look01_Max_010"] = "Justin siempre parece drogado.",
  ["Act_E2_4B_Corridor_CHLogan_Look01_Max_050"] = "Espero que este estúpido piense usar protección la próxima vez.",
  ["Act_E2_4B_Corridor_CHLuke_Look01_Max_010"] = "Luke siempre usa su teléfono para evitar a la gente.",
  ["Act_E2_4B_Corridor_CHPrincipal_Look01_Max_010"] = "El director Wells siempre se ve afligido...",
  ["Act_E2_4B_Corridor_CHZachary_Look01_Max_010"] = "Zachary siempre parece estar listo para lanzar la pelota.",
  ["Act_E2_4B_Corridor_GlobalWarmingNote_Look01_Max_010"] = "Debería ir a ver qué puedo aprender...",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_010"] = "¿Por qué Frank Bowers tendría tu brazalete?",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_020"] = "Quizás tú también le debías dinero a Frank...",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_030"] = "Desearía que Chloe y tú se hubieran escapado antes.",
  ["Act_E2_4B_Corridor_MPA01_Look01_Max_040"] = "Voy a averiguar qué te pasó, Rachel.",
  ["Act_E2_4B_Corridor_MaxLocker_Look01_Max_010"] = "Odio que todos vean el interior de mi casillero.",
  ["Act_E2_4B_Corridor_Plan01_Look01_Max_010"] = "¿Quién pierde el tiempo en memorizar esto? Aunque supongo que hoy en día, todos deberíamos hacerlo.",
  ["Act_E2_4B_Corridor_Poster01_Look01_Max_010"] = "No debería ser tan tacaña con mi sangre.",
  ["Act_E2_4B_Corridor_Poster02_Look01_Max_010"] = "Sí, este cartel debe dejar fríos a los bullies.",
  ["Act_E2_4B_Corridor_Poster03_Look01_Max_010"] = "Qué bueno que dejé mi rifle en casa.",
  ["Act_E2_4B_Corridor_Trophy01_Look01_Max_010"] = "Mira esos trofeos. Debo reconocer eso de los Pies Grandes. Sí que pisotean.",
  ["Act_E2_4B_Corridor_Trophy02_Look01_Max_010"] = "Blackwell sí que se toma la natación en serio. Pero las nutrias son lindas. ¡Vamos, Nutrias!",
  ["Act_E2_4B_Corridor_VortexBanner_Look01_Max_010"] = "¡Únete... o muere!",
  ["Act_E2_4B_Corridor_VortexPoster01_Look01_Max_010"] = "¿Alguien realmente se cree esta mierda?",
  ["Act_E2_4B_Corridor_VortexPoster02_Look01_Max_010"] = "Es la \"invasión del club Vortex\"...",
  ["Act_E2_4B_Corridor_VortexPoster03_Look01_Max_010"] = "No quisiera ir a una fiesta de \"fin del mundo\" con Nathan Prescott. Realmente sería el fin del mundo.",
  ["Act_E2_4B_Corridor_VortexPoster05_Look01_Max_010"] = "Si fuera normal, estaría superemocionada de ir a una juerga de esas.",
  ["Act_E2_4B_Corridor_VortexPoster06_Look01_Max_010"] = "Si mi visión del tornado se hiciera realidad, sería el \"fin del mundo\"...",
  ["Act_E2_4B_Corridor_VortexPoster07_Look01_Max_010"] = "Así que uno puede dispararle a alguien un lunes y salir de fiesta un viernes... Todo un Prescott.",
  ["Act_E2_4B_Corridor_WarrenText_VoiceOver01_Max_010"] = "Aún tengo tiempo, podría ver a Warren jugar a ser científico loco en el laboratorio.",
  ["Act_E2_4B_SciClass_Beckers_Look01_Max_010"] = "\"¡Tráeme el cerebro, Igor!\".",
  ["Act_E2_4B_SciClass_CHBrooke_Look01_Max_010"] = "Brooke siempre finge que... no existo. ¿Por qué?",
  ["Act_E2_4B_SciClass_CHGrant_Look01_Max_010"] = "La Sra. Grant es tan genial e inteligente. Es una \"maestra\" con todas las letras.",
  ["Act_E2_4B_SciClass_CHWarren_Look01_Max_010"] = "Ahí está el señor mago, concentrado en su trabajo.",
  ["Act_E2_4B_SciClass_CHWarren_Look02_Max_010"] = "No quiero reírme, pero se ve tan gracioso...",
  ["Act_E2_4B_SciClass_CHWarren_Look03_Max_010"] = "Es solo un fracaso menor.",
  ["Act_E2_4B_SciClass_CHWarren_Look04_Max_010"] = "¡Eureka! ¡Lo hizo!",
  ["Act_E2_4B_SciClass_FishTank_Interact01_Max_010"] = "O no pasará nada...",
  ["Act_E2_4B_SciClass_FishTank_Look01_Max_010"] = "Apuesto que, si toco el vidrio, empezarán a salir todos estos bichos marinos.",
  ["Act_E2_4B_SciClass_PeriodicTable_Look01_Max_010"] = "Una tabla periódica... Si supiera el significado de \"periódica\"...",
  ["Act_E2_4B_SciClass_SciencePoster01_Look01_Max_010"] = "Me gustaría tener un mini-Warren para mis exámenes de ciencia...",
  ["Act_E2_4B_SciClass_SciencePoster02_Look01_Max_010"] = "Da Vinci sí que sabía.",
  ["Act_E2_4B_SciClass_Skeleton_Look01_Max_010"] = "Me pregunto por qué no usan esqueletos de verdad...",
  ["Act_E2_4B_SciClass_WarrenPhoto_Photo_Max_010"] = "Ayudar a Warren fue divertido. Es bastante lindo cuando se pone en modo friki...",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Dana_010"] = "Que quede hermosa, Hayden. Moda, moda, moda...",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Dana_030"] = "¿Cómo me veo, Taylor?",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Hayden_020"] = "Dana, estás fuera de control. Gira a la izquierda, luego a la derecha... ¡Hazle el amor a la cámara!",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Nathan_060"] = "Oh, seguro le va ir a decir al director.",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Nathan_070"] = "Como si me importara.",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Nathan_090"] = "Como si a alguien le importara. Max no es más que una pequeña...",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Taylor_040"] = "Te ves horrible.",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Victoria_050"] = "¿Crees que Max se enoje porque estemos sentados en su lugar?",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Victoria_080"] = "Tal vez salga corriendo a buscar al Sr. Jefferson. Como si le importara.",
  ["Cue_E2_4B_ArtClass_BeforeLesson_IGE_Victoria_100"] = "¡Shh! Creo que nos está escuchando...",
  ["Cue_E2_4B_ArtClass_BeginLesson_Jefferson_110"] = "¡Nada de teléfonos en clase, Max! Guarda eso.",
  ["Cue_E2_4B_ArtClass_CHAlyssa_Phase01_Alyssa_001"] = "Ahora no, Max. Estoy en modo de contemplación.",
  ["Cue_E2_4B_ArtClass_CHDanaDial_Phase01_Dana_056"] = "No tengo tiempo para hablar, Max. Estoy posando.",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_002"] = "Estoy esperando para dibujar a Dana cuando Hayden deje de hacerse el paparazzi.",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_010"] = "Créeme, lo entiendo.",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_013"] = "Espero que te haya gustado el dibujo de ti que hice ayer...",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_014"] = "No te preocupes, Max. No te voy a pedir que poses para mí.",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_017"] = "Excelente. Tengo millones de \"Me gusta\" en Facebook. ¡Ah, te hice sonrojar!",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Daniel_019"] = "Algún día exhibirán tus retratos en el ala \"Daniel da Costa\" del Louvre. Hablaremos de eso luego.",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_001"] = "¿Qué pasa, Daniel?",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_009"] = "¿Estás enojado porque no te dejé dibujarme ayer? Soy tímida. Me da tanta vergüenza...",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_015"] = "Me encantó. Y es mi nuevo avatar.",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_016"] = "Por supuesto. Pero, aunque no lo creas, me da vergüenza pensar que la gente me mira...",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_018"] = "¡Cállate!",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_020"] = "Por favor, no te ofendas. Me siento una idiota cuando alguien talentoso me pide que pose.",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase01_Max_021"] = "Me encantaría tener otra oportunidad en la historia del arte contigo...",
  ["Cue_E2_4B_ArtClass_CHDanielDial_Phase02_Daniel_001"] = "¿Quieres el retrato ahora? ¿En serio? Hablemos luego.",
  ["Cue_E2_4B_ArtClass_CHHayden_Phase01_Hayden_001"] = "Estoy algo ocupado ahora, Max.",
  ["Cue_E2_4B_ArtClass_CHTaylor_Phase01_Taylor_001"] = "No tengo tiempo para hablar, Max. Estoy creando arte.",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale01_020"] = "No me lo perdería por nada del mundo. Tengo el atuendo más lindo...",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale02_030"] = "Vi a Victoria y compañía haciendo compras para la fiesta.",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale03_050"] = "Esa nevada fue una locura.",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenFemale04_060"] = "En serio. ¡Hola, cambio climático!",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenMale02_010"] = "¿Y? ¿Vas a ir a la fiesta del club Vortex?",
  ["Cue_E2_4B_ArtClass_CorridorInsertion_IGE_TeenMale02_040"] = "Eso me recuerda que tengo que pedirle hierba a Nathan.",
  ["Cue_E2_4B_ArtClass_Interrupt01_Zachary_010"] = "¡Oigan, está pasando algo muy loco en la residencia de chicas! ¡Vengan a verlo!",
  ["Cue_E2_4B_ArtClass_Interrupt02_Jefferson_010"] = "Zachary, no vuelvas a interrumpir mi clase de esa manera...",
  ["Cue_E2_4B_ArtClass_Interrupt05_Jefferson_010"] = "¡Escuchen! Permanezcan en sus lugares...",
  ["Cue_E2_4B_ArtClass_Interrupt06_Jefferson_010"] = "Pueden salir.",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Alyssa_040"] = "No se siente bien.",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_010"] = "Muy bien, sé que me adoran, pero, si no están en mi clase, adiós. Los demás, por favor, a sus lugares. Hoy tenemos que ver bastante y tenemos muy poco tiempo, como de costumbre... Veo que llegaron los sospechosos de siempre...",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_020"] = "¿Alguien ha visto a Kate Marsh?",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_050"] = "Esas risitas parecen ser por un video que se hizo viral. Quizás involucre a un alumno, o a un amigo. Me pregunto cómo se sentirían si se publicaran imágenes falsas de ustedes por todo el mundo para que la gente los juzgue... Las personas siempre necesitan tener algo que juzgar, así no tienen que hacer introspección.",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_060"] = "En parte, podemos agradecer a los reality shows. Al final, la culpa es nuestra por participar...",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_070"] = "Hablando de participar, algunos de ustedes todavía no han entregado su fotografía para el concurso.",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_080"] = "Como Max Caulfield, por ejemplo. Que se muere de ganas de participar, ¿verdad?",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_090"] = "Seguro que memorizaron el programa como si fuera un libro de Harry Potter, así que deberán saber que hoy vamos a estudiar el \"claroscuro\", una hermosa palabra que describe el contraste entre la luz y la oscuridad, el juego de sombras que le da a la fotografía su... poder visual.",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Jefferson_100"] = "Es como el yin y el yang. Las imágenes en blanco y negro son buenas precisamente por su contraste. Aunque técnicamente no \"vemos\" en blanco y negro...",
  ["Cue_E2_4B_ArtClass_JeffEnter_IGE_Victoria_030"] = "Creo que a esta altura todo el mundo vio a Kate Marsh...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_010"] = "Sí...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_020"] = "Hablemos luego, ¿de acuerdo? Debo irme...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_030"] = "Porque no puedo hablar contigo de eso ahora, ¿de acuerdo? ¿Podrías colgar el teléfono?",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_040"] = "Está bien.",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_060"] = "Por supuesto, de acuerdo...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_070"] = "Escucha, tengo que ir a dar clase, me tengo que ir...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_080"] = "Ajá. De acuerdo, eso haré...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_090"] = "Oh, lo sé. Suena lógico...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_100"] = "Hablemos de eso luego...",
  ["Cue_E2_4B_ArtClass_JeffPhoneLoop_IGE_Jefferson_110"] = "En serio, tengo que cortar la llamada...",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_030"] = "Demasiado tarde.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_050"] = "Claro. ¿Puedo sentarme en mi lugar?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_080"] = "Idiotas.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_110"] = "Demasiado tarde.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_130"] = "¿Me dejan sentarme, por favor?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_190"] = "Para nada, Victoria.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_210"] = "Tú sabrás. ¿Me dejan sentarme?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Max_260"] = "Qué bien que me conoces.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_010"] = "Silencio, Victoria. Que llegó la soplona y mentirosa del pueblo.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_040"] = "¡Oh, qué dolor! Max es tan valiente cuando tiene apoyo.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_070"] = "Es más, todo recién empieza, Max.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_090"] = "Aquí viene la misteriosa Max, disfrazada de hada hipster.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_120"] = "Miau. Saca las garras. Me encantan las peleas de chicas.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_150"] = "Dejémosle su lugar. Es todo lo que tiene...",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_200"] = "Max no es más que una zorra en busca de atención.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Nathan_220"] = "Sí, Max. Así que no te olvidaré.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_020"] = "Y de paparazzi. Quiero esa foto, perra. O me pondré violenta.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_060"] = "No te pongas altanera. Esto no ha terminado.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_100"] = "O de paparazzi. Quiero esa foto, perra. O me pondré violenta.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_140"] = "No lo sé... ¿Podrás?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_180"] = "¿Pensaste que éramos mejores amigas o algo así?",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_210"] = "Oh, sí, por favor. Toma una selfi de este momento.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_250"] = "Como todos los otros artistas cursis aquí.",
  ["Cue_E2_4B_ArtClass_VictoriaNathanDial_Victoria_290"] = "Max pensó que íbamos a ser amigas. Me muero de risa.",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Max_008"] = "¡Hola, Warren!",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Max_020"] = "Kate está con muchos problemas...",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_005"] = "¿Qué dices, Max?",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_010"] = "Vi a Kate hace un rato y tenía los ojos hinchados de tanto llorar.",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_030"] = "No supe qué decir, y ella tampoco me dijo nada...",
  ["Cue_E2_4B_ArtClass_WarrenComeIn_Warren_040"] = "¿Nos vemos luego?",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_001"] = "Ciao, Max. Nada de fotos por favor. Tengo que hacer una lista de invitados para una velada del club Vortex.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_010"] = "Oh, como si te importara.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_012"] = "Pero pareces antimoda. Las fiestas del club Vortex tienen un código de vestimenta estricto. Ni siquiera tienes un vestido, ¿verdad? Lo siento, pero fue un buen intento.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_014"] = "Podré terminar mi lista antes de tiempo. Ciao.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_016"] = "Gracias, Max. No sabía que te interesaba la alta costura. ¿Sabes qué? Te pondré en la lista de invitados y te daré algunos consejos antes de la fiesta.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Courtney_018"] = "Te enviaré la información de la fiesta más tarde. ¡A seguir con la lista!",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_008"] = "Hola, Courtney.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_009"] = "¿En serio?",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_011"] = "No soy antiveladas.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_013"] = "Tienes razón, en verdad no me importa.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_015"] = "Apuesto que el club Vortex tiene un código de vestimenta. Como podrás ver, necesito que me ayudes para saber qué ponerme.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase01_Max_017"] = "Estupendo. Gracias, Courtney.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase02_Courtney_001"] = "Olvídalo, Max. No estarás en la velada.",
  ["Cue_E2_4B_Corridor_CHCourtneyDial_Phase02_Courtney_002"] = "No puedo esperar a arreglarte. Hablamos pronto.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_035"] = "Max, ¿podemos hablar?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_036"] = "Sé que las cosas se pusieron un poco tensas ayer en la habitación de Chloe... ¿Esa hierba en verdad era tuya?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_037"] = "¿Podríamos hablar de lo que pasó ayer en la habitación con Chloe?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_040"] = "Ni yo soy tan maldito... Y siento mucho lo de ayer. Me equivoqué, pero estaba molesto. Puede que la marihuana no sea un problema para ti, pero lo es para Chloe.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_044"] = "Me enfrentó y me llamo \"maldito\". De todas formas, estuve mal. Tendré que compensárselo a Chloe. Lo siento.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_045"] = "Seguro te dijo el motivo. ¿No mencionó...? Seguro que robó una de mis armas, ¿no?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_046"] = "Si no la quisiera, no me importaría nada. Cuando tenía su edad, hacía cosas mucho peores... Ella es mejor que eso. Todos ustedes lo son. Incluso Kate Marsh.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_049"] = "No llegaste en el mejor momento. Ella es todo un caso aparte.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_050"] = "No debería haber dicho nada. Sabes lo de ese video que anda circulando...",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_053"] = "Max, no se trata solo de Kate Marsh. Me preocupo por la seguridad de todos los alumnos de Blackwell. Tú incluida.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_054"] = "No sabes los detalles, soldado. ¿Crees que soy hipócrita por querer cámaras para la seguridad de los alumnos?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_057"] = "La petición de la Sra. Grant no va a ayudar a encontrar a alumnos desaparecidos.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_David_059"] = "No quiero seguir discutiendo contigo. No quiero discutir con nadie más... eso es todo, Max.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_038"] = "Sí. Sabe que la marihuana es casi legal en Oregón. Hasta puedo conseguirla en Blackwell. ¿Va a arrestarme, Sr. Madsen?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_039"] = "No... Era de un amigo mío. ¿Va a arrestarme, Sr. Madsen?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_041"] = "Usted es un veterano de guerra. Ella no es ninguna amenaza para usted.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_042"] = "No lo creo. Y golpeó a Chloe.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_043"] = "Golpeó a Chloe.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_047"] = "Pero a Kate la trata bastante mal...",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_048"] = "¿Y Kate?",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_051"] = "Kate no hizo nada malo.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_052"] = "¿Por eso se metió con Kate ayer? Tomé una foto por cuestiones de seguridad.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_055"] = "Para eso se necesitarán más que cámaras de seguridad.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_060"] = "Disculpe, Sr. Madsen.",
  ["Cue_E2_4B_Corridor_CHDavid_Phase01_Max_061"] = "¿Acaso no es su responsabilidad como jefe de seguridad? A menos que sepa algo de Rachel Amber que los demás no saben...",
  ["Cue_E2_4B_Corridor_CHDavid_Phase02_David_001"] = "No me molestes con tu charla ahora.",
  ["Cue_E2_4B_Corridor_CHEvanDial_Phase01_Trevor_002"] = "Ey, Maxwell lista. Hablamos luego, ¿sí?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_008"] = "Solo me molesta que no quieras entregar fotos. Pero ya lo sabes. ¿Qué puedo hacer por ti, Max?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_042"] = "No es ningún secreto. Se dice por ahí que Kate y tú han tenido una pequeña confrontación con nuestro jefe de seguridad ayer.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_043"] = "No eres la única. ¿Hay algo que me quieras decir?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_047"] = "Claro que no. El Sr. Madsen no es la persona más amable del mundo. ¿Tienes pruebas de que él generó la situación?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_048"] = "Puedes hablar conmigo cuando quieras. Y, Max, ¿puedo hablar contigo sobre Kate?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_049"] = "El Sr. Madsen confunde el miedo con la seguridad. Siento que Kate haya sido víctima de su paranoia. Si tuvieras pruebas, podría hablar con el director Wells...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_052"] = "Nunca dejes pasar una oportunidad. Es mi regla número uno en fotografía.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_053"] = "Muéstrame la foto después de la clase. Ya estás pensando como una fotógrafa profesional.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_054"] = "Y, Max, prometo que los profesores están hablando de este asunto.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_055"] = "Supongo que sabes de ese video viral...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_058"] = "¿Y si Kate se buscó todo esto? Tiene buenas intenciones, pero tal vez sí protesta demasiado... Parece que estuviera ocultando la verdad. ¿Hablaste con ella?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_064"] = "¿Rachel Amber? ¿Qué tiene que ver con Kate?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_066"] = "También extraño a Rachel. Pero piensa en ti, Max. El director Wells me contó lo que le dijiste del baño...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_067"] = "Rachel no se parecía en nada a Kate. El director Wells me dijo que le parecía que no le habías dicho todo. ¿Quieres hablar conmigo?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_072"] = "Esa es una acusación seria, Max.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_074"] = "Eso espero, Max. Pero echar culpas es fácil.|¿Entonces debería creerle al Sr. Madsen cuando dice que traficas drogas?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Jefferson_075"] = "Me gustaría creer eso, Max. Parece que hay mucho drama a tu alrededor esta semana.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_007"] = "Disculpe que lo moleste, Sr. Jefferson...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_044"] = "En verdad, no. No se preocupe, lo siento. Tengo que ir a trabajar... en mi foto.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_045"] = "Tuve que intervenir entre David Madsen y Kate porque él le estaba gritando, estaba muy agresivo, no sé por qué... Ella no se merece eso.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_046"] = "Vi a David Madsen molestando a Kate Marsh. La estaba asustando.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_050"] = "¿Mi palabra no es suficiente? La única vez que decido no tomar una foto...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_051"] = "Oh, sí. Tengo una foto, para variar.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_056"] = "Todos lo saben. Por eso quería verlo. Kate está siendo humillada a diario.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_057"] = "Todo esto tiene a Kate muy asustada. No puede concentrarse en su tarea si la están atormentando a diario.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_059"] = "Lo haré. Está enojada porque hoy me llamó y no le contesté. No quiero que Kate Marsh termine como Rachel Amber...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_061"] = "No... No quiero que Kate Marsh termine como Rachel Amber...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_062"] = "Sí, hablé con ella hoy.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_063"] = "Sí, hablé con ella esta mañana.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_065"] = "Lo que necesita ahora son amigos y apoyo. No quiero que Kate Marsh termine como Rachel Amber...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_068"] = "Esa fue una conversación privada. No es que no quiera contarle...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_069"] = "Pasó de verdad. Ayer Nathan Prescott entró al baño de mujeres con un arma.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_070"] = "Por ahora no. Le diré todo en cuanto logre entenderlo.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_071"] = "Ayer vi a Nathan Prescott con un arma en el baño de mujeres. No pude decirle nada al director Wells de lo asustada que estaba.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_073"] = "¿Entonces no me cree? Nunca inventaría algo así.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_076"] = "Escuche, ¿debería...?",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_080"] = "Con estos carteles de \"Persona desaparecida\" por todos lados es difícil no pensar en ella...",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase01_Max_081"] = "Aquí entre nos, estoy preocupada por Kate Marsh.",
  ["Cue_E2_4B_Corridor_CHJeffDial_Phase02_Jefferson_001"] = "Max, estoy ocupado. Por favor. Hablaremos más tarde.",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_002"] = "¿Supuesto? Nathan tenía un arma. ¿Ya habló con él?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_003"] = "Estuvieron pasando muchas cosas con lo de la alarma de incendio y demás...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_030"] = "¿Señor?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_031"] = "No... No importa.",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_033"] = "No. Es decir, no tengo nada para decirle...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_035"] = "El Sr. Madsen ya nos trata a todos como si estuviéramos bajo vigilancia...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_036"] = "Ayer vi al Sr. Madsen molestando a Kate Marsh...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_038"] = "No puedo concentrarme cuando estoy asustada...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Max_040"] = "Probablemente no el mismo que usted.",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_001"] = "Oh, hola, Max. Espero que esto no se trate del supuesto incidente del arma...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_004"] = "Sí. Está muy perturbado por esta acusación... No lo culpo. Hablaremos cuando sepa todos los hechos. Por el momento, concéntrate en tu tarea.",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_005"] = "Sí, pero estabas pensando algo más...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_032"] = "Ah, hola, Max. ¿Quieres contarme lo que no me quisiste decir ayer?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_034"] = "Más secretos. Si me disculpas, tengo que asistir a una reunión.",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_037"] = "Espera, espera. ¿No ves un patrón, Max?",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_039"] = "No digas eso, por favor. No hay nada que temer en la Academia Blackwell. Gracias a nuestro jefe de seguridad, el campus está entrando en toda una nueva era de seguridad.",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_045"] = "No quieres decirme la verdad sobre lo de ayer, pero quieres hablarme del Sr. Madsen. Me suena a resentimiento... Ahora, si me disculpas...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_048"] = "Es muy fácil para ti acusar a la gente de cosas terribles sin pensar. Nathan, el Sr. Madsen... ¿quién será el próximo? Ahora, si me disculpas, tengo una reunión.",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase01_Principal_068"] = "Me alegra que no sigas acusando a alumnos. Ahora, si me disculpas...",
  ["Cue_E2_4B_Corridor_CHPrinDial_Phase02_Principal_001"] = "Max, tengo una reunión. Disculpa.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_001"] = "Hola, Zach.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_003"] = "Tomo fotos con los ojos todo el tiempo.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_005"] = "Obvio que no. Eso es lo que Victoria quería.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_007"] = "Aunque no lo necesita.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_009"] = "Ya pasó. Solo fue otro minidrama de Blackwell.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Max_011"] = "Probablemente que todos hablemos de ella. Como ahora.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_002"] = "¿Qué tal, Max? Qué raro verte sin tu cámara.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_004"] = "Seguro. Mientras no andes hablando con todos sobre esa mierda de los mensajes sexuales y Victoria...",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_006"] = "Sí, me di cuenta que le gusta crear sus propios dramas. Aunque se vuelvan en su contra. Qué extraño.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_008"] = "Eso es lo que no entiendo ni un poco. Es sexy, rica y talentosa. ¿Qué más quiere? Como sea, nos vemos en el juego del viernes, Max.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_010"] = "Querrás decir otra estupidez. Dios, no puedo entender a Victoria. ¿Qué es lo que quiere?",
  ["Cue_E2_4B_Corridor_CHZachary_Phase01_Zachary_012"] = "Entonces no lo hagamos. Eres bastante lista, Max. Nos vemos en el juego del viernes.",
  ["Cue_E2_4B_Corridor_CHZachary_Phase02_Zachary_001"] = "Hola, amigo, nos vemos.",
  ["Cue_E2_4B_Corridor_JeffDial_Jefferson_010"] = "Disculpa, Max.",
  ["Cue_E2_4B_Corridor_JeffDial_Jefferson_020"] = "¿Hola? ¿SÍ? Eh... espera.",
  ["Cue_E2_4B_Corridor_JeffDial_Jefferson_030"] = "Debo contestar. Ve al salón, estaré allí en seguida.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_010"] = "Tienes que hablar conmigo, Kate.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_030"] = "Deja de hacerte la mártir.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_050"] = "Quiero que seas honesta.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_070"] = "Deja de ser tan susceptible.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Jefferson_090"] = "Quizás esta sea tu manera de llamar la atención.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_020"] = "¿Por qué? Todo está perdido, como yo.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_040"] = "¿Qué quiere que haga?",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_060"] = "De todos modos, nadie me cree.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_080"] = "Es lo que pasa cuando uno está en un video viral.",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_100"] = "Es muy cruel que diga eso, Sr. Jefferson. No entiende nada...",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_130"] = "¡Déjeme en paz!",
  ["Cue_E2_4B_Corridor_JeffKateDial_IGE_Kate_150"] = "Oh, entiendo... Ya no importo... Nadie se preocupa por mí. Nadie...",
  ["Cue_E2_4B_Corridor_JeffKateDial_Jefferson_020"] = "Lo intento. Pero tienes que ponerte en mi lugar...",
  ["Cue_E2_4B_Corridor_JeffKateDial_Kate_010"] = "¿Entonces no me puede ayudar?",
  ["Cue_E2_4B_Corridor_JeffKateDial_Kate_030"] = "¿Por qué? Usted no se pone en el mío. Nadie lo hace... nadie...",
  ["Cue_E2_4B_Corridor_JeffersonStopsMax_Jefferson_010"] = "Disculpa, Max... ¿puedes venir un momento?",
  ["Cue_E2_4B_Corridor_JeffersonStopsMax_Jefferson_030"] = "Te ves preocupada... ¿está todo bien?",
  ["Cue_E2_4B_Corridor_JeffersonStopsMax_Max_020"] = "Seguro.",
  ["Cue_E2_4B_Corridor_KateLeaves_Kate_010"] = "¡Por favor, déjeme en paz!",
  ["Cue_E2_4B_Corridor_KateLeaves_Kate_020"] = "¡Basta! ¡No te me acerques!",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_001"] = "Hola, Max. ¿Estás haciendo tus rondas diarias?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_004"] = "Lo siento, Max. Lo mío es la robótica, no la química. Prefiero mil veces más un drone que un vaso de precipitado.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_005"] = "La Sra. Grant me pescó usándolo en el estacionamiento. Anda toda alterada con toda esa mierda de la vigilancia. Como si estuviera espiando el coche nuevo de Warren.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_007"] = "Oh. Supongo prefiere una asistente neófita para no sentirse amenazado. Pero, de todos modos, acudiste a su rescate.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_010"] = "No quiero estorbar. Hasta luego.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_013"] = "Sin embargo, Warren ignora a los expertos frente a él... Ni que fuera a pedirme ayuda.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_014"] = "Sabe algunas cosas.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_016"] = "Tomé prestado el que te puso a ti.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Brooke_018"] = "Es verdad, Max.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_002"] = "Me pregunto si podrías ayudarme con un experimento de potasio.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_003"] = "¿Cómo anda tu drone?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_006"] = "Estoy ayudando a Warren con su último experimento.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_008"] = "Buenas, Brooke.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_009"] = "Siento andar de prisa, pero...",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_011"] = "Aparentemente es mi naturaleza.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_012"] = "Yo no. Warren no necesita mi ayuda.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_015"] = "¿Ya le instalaste un GPS?",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase01_Max_017"] = "Nos vemos de nuevo, Brooke.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase02_Brooke_001"] = "Pensé que estabas ayudando a Warren con sus tubos. Disculpa.",
  ["Cue_E2_4B_SciClass_CHBrookeDial_Phase02_Brooke_002"] = "Tengo que terminar esta ronda, Max. Lo siento.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_001"] = "Qué curioso, justo estaba pensando en ti, Max.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_012"] = "Me gusta que siempre estés pensando en el futuro.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_013"] = "Gracias de nuevo por oponerte a las cámaras de seguridad. Cada firma es importante.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_014"] = "Qué mal que no hayas firmado la petición. Cada firma es importante, y la tuya podría haber marcado la diferencia.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_016"] = "La mayoría de las personas prefieren mandar un texto a firmar una petición. Así es como nos mantienen distraídos. Nadie notará las cámaras cada dos metros.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_018"] = "Max, con alumnos como tú, seguro lo lograremos.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_020"] = "Pero otros, como David Madsen, las quieren para espiar.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_022"] = "Lo sé, Max. Pero la idea es asegurarnos que la Academia Blackwell no termine como él...",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_023"] = "Oh, esta es mi época favorita del año. Me encanta el cambio de estación. Todo el campus es un placer para los ojos. Sé que al Sr. Jefferson le encanta tomar fotos por aquí.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_025"] = "Sé que es un artista talentoso y un excelente profesor. He estado aquí un poco más de tiempo que él, pero él ha dejado una marca más fuerte...",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_027"] = "Sí, pero definitivamente no soy ninguna artista. Lo mío es la ciencia. Con los números, no hay lugar a dudas.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_028"] = "Tengo que decir que no parece otoño del todo aún.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_031"] = "Nuestro clima está cambiando más allá de toda explicación. Pero seguro que las tribus de aquí lo ven de otra manera...",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_032"] = "Tú eres artista; yo, científica... somos como el yin y el yang.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_034"] = "Sabes mi respuesta de profesora: ninguna pregunta es tonta. Pregunta.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_036"] = "Ninguno de los dos, a menos que quieras llenarte la cara de polvo. Añadiría cloro.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_040"] = "Hola de nuevo, Max.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_041"] = "Firmaste la petición, así que ahora también es tu campaña. Agradezco tu participación.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Grant_042"] = "Falta alguien a quien debería importarle, pero no quiero acusar a nadie, Max.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_010"] = "Hola, Sra. Grant.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_011"] = "Estoy pensando en todas las fotos que quiero sacar en otoño...",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_015"] = "¿Cómo va su campaña?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_017"] = "Lo sé. En verdad espero que se pueda evitar que las cámaras invadan Blackwell.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_019"] = "Algunos queremos usar las cámaras para el bien...",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_021"] = "Por Dios, no soy como él, Sra. Grant.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_024"] = "Debe conocer al Sr. Jefferson bastante bien.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_026"] = "Le debe gustar la fotografía.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_029"] = "¿Qué piensa de la nevada de ayer? ¿Cuál es la explicación científica?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_030"] = "Yo tampoco puedo esperar a que el otoño llegue de verdad. Es algo del ambiente.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_033"] = "Sra. Grant, ¿puedo hacerle una pregunta tonta sobre ciencia?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_035"] = "¿Usted le agregaría potasio o sodio a la mezcla química del experimento de esta semana?",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_037"] = "Lo siento, Sra. Grant, pero me tengo que ir.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase01_Max_039"] = "Hola de nuevo, Sra. Grant.",
  ["Cue_E2_4B_SciClass_CHGrant_Phase02_Grant_001"] = "Ve, Max. Volveremos a hablar. Muy pronto.",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_008"] = "Hola, Warren. ¿Estás bien? Te ves pensativo, confundido.",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_009"] = "Si me estás pidiendo ayuda a mí, de verdad estás en problemas.",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_011"] = "No entiendo por qué quieres poner tu destino en mis manos, pero... ¡pota-sí-o!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_013"] = "Tengo una visión... ¡sí-sodio!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_015"] = "Warren, esto parece algo peligroso. Podrías perder el control, Frankenstein.",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_017"] = "Creo que deberías usar mucho potasio. Un montón de potasio.",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Max_019"] = "¡No, Warren, no tienes que agregar ni sodio ni potasio, lo que necesitas es cloro!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_007"] = "¡Maxwell Silver Hammer! ¡Justo a tiempo! Necesito ayuda con este experimento de química...",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_010"] = "Tengo que agregar un poco de sodio o de potasio. Tú dirás, doctora Max.",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_012"] = "Potasio será. Si funciona, tendrás un abrazo gratis...",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_014"] = "¿\"Sí-sodio\"? El peor juego de palabras que escuché en mi vida. Pero Max ha hablado. ¡Sodio será!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_016"] = "Soy el único científico loco que no tiene un Igor leal. Usaré el método científico: de tín marín... ¡Potasio!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_018"] = "¿Ves? Mira esa sonrisa. Serás una científica... ¡Hagámoslo!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase01_Warren_020"] = "¿Cloro? No había pensado en eso... Imposible discutir con una científica segura de sí misma. ¡Intentémoslo!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase02_Warren_001"] = "Chingado. Cero. Nada. Nada de nada.",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase02_Warren_002"] = "¡Mira el cerebrote que tiene Max! ¡Podrías ser la próxima Heisenberg de Blackwell!",
  ["Cue_E2_4B_SciClass_CHWarrenDial_Phase02_Warren_003"] = "Sí, estuvo genial, pero que sea un secreto profesional, ¿te parece?",
  ["Cue_E2_4B_SciClass_WarrenDial_Brooke_060"] = "Vaya, ustedes sí que sobrepasaron los límites de la ciencia.",
  ["Cue_E2_4B_SciClass_WarrenDial_Max_040"] = "No, tú lo hiciste.",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_010"] = "Piensa, cerebro, piensa.",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_020"] = "No puede ser tan difícil.",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_030"] = "¡Eureka! ¡Lo hiciste!",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_050"] = "No sea tan modesta, doctora Caulfield.",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_080"] = "Ciencia loca.",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_100"] = "Me cegó a pura ciencia.",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_110"] = "Sí, soy un científico. Chingado.",
  ["Cue_E2_4B_SciClass_WarrenDial_Warren_120"] = "Me rindo.",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_010"] = "No puede morir. No puede.",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_020"] = "Tengo que utilizar todo mi poder para retroceder y detenerla...",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_030"] = "No otra vez, no ahora...",
  ["Act_E2_4C_CampusB_BeginsRewind_VoiceOver01_Max_040"] = "Debo intentar algo... No puedo rebobinar una y otra vez...",
  ["Act_E2_4C_CampusB_VoiceOver_Max_010"] = "Debo llegar a la puerta del dormitorio para alcanzar el techo...",
  ["Act_E2_4C_CampusB_VoiceOver_Max_020"] = "Hazlo, Max, debes salvar a Kate...",
  ["Act_E2_4C_CampusB_VoiceOver_Max_030"] = "Dios, se me parte la cabeza... pero tengo que llegar a la residencia ahora.",
  ["Act_E2_4C_CampusB_VoiceOver_Max_040"] = "Vamos, Max, no te acobardes... Kate te necesita.",
  ["Act_E2_4C_CampusB_VoiceOver_Max_050"] = "Olvídate del dolor de cabeza... Kate está sufriendo más que tú...",
  ["Act_E2_4C_CampusB_VoiceOver_Max_060"] = "Max, ve al dormitorio para tener un acceso rápido al techo.",
  ["Act_E2_4C_CampusB_VoiceOver_Max_070"] = "¡Kate! ¡No! Ay, Dios. ¡Debo hacer algo para ayudarla!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_001"] = "¿Viniste a tomar otra foto para el Pulitzer como ayer, Max?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_002"] = "Max, en serio, no te me acerques. Saltaré.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_008"] = "Sé que solo te preocupas por ti misma. Por eso dejaste que David me gritara. Como todos aquí...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_009"] = "¿En serio? ¿Entonces tomaste una foto para averiguarlo?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_010"] = "Sé que le temes a David. Da miedo. Y sé que quieres ayudar.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_011"] = "Lo único que estabas buscando era otra foto para el libro de recuerdos de Max. ¿Quieres otra? ¿Eh?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_013"] = "Lo sabrás si salto ahora mismo... Todos lo sabrán...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_018"] = "Sí, ellos quieren ayudar a matarme. Y puedo cumplir su deseo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_019"] = "Vete Max, no me vas a hacer cambiar de opinión. Mi vida es un desastre, y quiero que termine. Ahora.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_020"] = "Desearía que pudieras... Es demasiado tarde. Ya no queda nada para mí...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_021"] = "Sí quiero. Mi vida ya está acabada...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_023"] = "Ay, Max, sé que quieres ayudarme... Me encantó que enfrentaras a David, pero eso ya no importa. Nada importa.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_025"] = "Quisiera creerlo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_027"] = "¡Qué mentirosa eres! ¿Quisiste ayudar cuando no contestaste mi llamada?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_028"] = "Me alegra saber que te preocupas por mí... Me hace sentir mejor...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_034"] = "Aparentemente su problema es más importante que el mío. ¿Entonces por qué siquiera molestarte conmigo? De todos modos, estoy acabada.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_035"] = "Necesitaba que respondas, Max. Ahora todos piensan que soy una puta viral.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_036"] = "Obviamente no tienes problema alguno en ignorar a tus amigos. Como a mí. ¿A quién le importa si Kate vive o muere?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_037"] = "¡Yo también juro, juro que esto es una mierda! ¡Es lo que todos dicen para desentenderse del tema!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_039"] = "¡No digas nada si vas a culpar al teléfono! Solo dime que no quisiste contestar.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_045"] = "Me hizo bien hablar contigo por teléfono. Siempre siento que de verdad me escuchas.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_047"] = "El que no te importe el video y vengas hasta aquí|significa mucho para mí...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_053"] = "¡Ya te dije lo que sucedió! Bueno, es demasiado tarde para ayudar, Max. Demasiado tarde.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_054"] = "¿Nathan Prescott? Suena lógico... Es un cabrón. ¿Ahora tienes pruebas?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_055"] = "¡Tú puedes \"tener cuidado\", pero soy yo la que aparece en el maldito video! Demasiado tarde, Max. Llegas demasiado tarde.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_056"] = "Sí, claro, el mundo gira alrededor de Max Caulfield. ¡No puedo confiar ni en ti ni en nadie! ¿Y para qué?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_057"] = "Suenas tan convincente, Max... Si tan solo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_060"] = "Sí que me proteges, Max. Es la primera vez que me siento optimista en la semana...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_067"] = "No conoces a mi madre. En lo más mínimo. Ya está convencida de que Satanás tiene un lugar reservado para mí en el Infierno. Vamos a probarlo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_068"] = "No me conoces en lo más mínimo, Max. Te dije que solo tengo hermanas. ¡Nunca escuchas, porque todo te vale madre! ¡Ahora sí te importará!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_069"] = "A papá sí le importa... aunque lo lastime. Es la única persona que cree en mí.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_071"] = "Esa es Lynn... tiene apenas diez... Tiene la mejor sonrisa de todas... Odiaría verla triste...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_074"] = "Buen intento, Max. Pero Dios me puso en esta azotea.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_079"] = "No creo en la justicia, Max. Ya no creo en nada.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_080"] = "¿Y qué diferencia hay? De todas formas, ya estoy en el infierno...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_081"] = "\"Mateo 11:28\"... No puedo creer que citaras uno de mis pasajes favoritos.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_085"] = "No... No le importo a nadie, a nadie...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_094"] = "No puedes borrar mi video de Internet... y así es cómo seré recordada. A menos que salte...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_095"] = "Me gustaría... No me molestaría volver a ser una estudiante más... ¿Es posible retroceder y empezar de nuevo, Max?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_096"] = "Dios mío. Por favor, Max. No has visto las miradas que recibo... ni escuchado las risas.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_099"] = "Sí, mi vida es una pequeñez. Blackwell me enseñó que soy insignificante. Y le daré la razón ahora mismo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_105"] = "No, Max, no... me drogaron, y nadie me cree, ni siquiera los alumnos que, supuestamente, son mis amigos.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_111"] = "No sabes nada, Max. Brooke se burla de mí porque no soy atea. Quizás ahora lo sea...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_112"] = "Vi a Dana mirando el video con Trevor. Vaya amigos. Falsos. Como toda mi estúpida vida...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_113"] = "Lo sé... tienes razón Ella nunca me juzgó. Ni dudó de mí.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_114"] = "No. En todo caso fue aún más dulce. Creo que no debería juzgar a todo el mundo, ¿no crees?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_121"] = "Gracias por eso, pero te necesitaba más cuando te llamé para hablar. Ahí es cuando necesitaba una amiga.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_124"] = "Eso es lo que dices ahora. ¿Cómo podría confiar en ti? ¿Y qué de esta mañana cuando necesitaba ayuda? ¡Me dijiste que no hiciera nada!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_125"] = "¿De verdad? Muchas gracias...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_130"] = "¿En realidad podríamos, Max? Yo también dejé de creer en milagros.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_133"] = "Como todos en Blackwell, es todo sobre ti. Aun cuando la víctima soy yo.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_134"] = "Max, estoy en una pesadilla y no puedo despertar... a menos que me sacrifique. Así, todo Blackwell podrá publicar fotos de mi cadáver... Ya estaré en Internet para siempre. Con razón la llaman la \"red\", nada puede escapar de allí. Como mi video... Como me gustaría retroceder en el tiempo y borrarlo todo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_136"] = "Eres tan buena, Max. Aunque mientas. Pero iré contigo... eres mi amiga.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_137"] = "Ay, Max... cuando lo dices así, dan ganas de creerte...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Kate_138"] = "¡Ay, por favor! ¿Ahora quieres ayudarme? ¿Y qué de esta mañana cuando lo necesitaba? ¡Me dijiste que no hiciera nada!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_004"] = "Yo también fui víctimas de bravucones, Kate. Y aun cuando se metían conmigo, me defendía.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_005"] = "¡Solo estaba buscando pruebas de que David te molestaba!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_006"] = "No tenía idea de lo que sucedía entre David y tú...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_007"] = "Lo siento tanto, Kate. Creí que podía ayudarte, pero no tomando una foto. Me da vergüenza...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_012"] = "¿De qué otra manera podría averiguarlo?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_014"] = "Eso no es cierto. La gente quiere ayudarte.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_015"] = "¡Kate, no! ¡Por favor!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_016"] = "Te decepcioné y lo siento. Solo quiero ayudarte.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_017"] = "¡No! Por favor, Kate, me conoces... y yo sé que no quieres saltar.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_022"] = "Bueno, bueno. Aquí estoy. Kate, por favor...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_024"] = "Eres importante. Y no solo para mí.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_026"] = "Kate, tu vida sigue siendo tuya. Y podemos lidiar con todo esto juntas... Déjame ayudarte.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_029"] = "Estaba con Chloe, y ella también tenía un problema grave. Lo siento.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_030"] = "¡Lo juro, estaba en modo silencioso, y no lo vi; si no, hubiera contestado sin dudar!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_031"] = "Mi teléfono se quedó sin batería, y no tenía mi cargador. Lo juro...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_032"] = "Por supuesto que me preocupo. Eres mi amiga, Kate.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_033"] = "¡Creí que era Warren! Me viene reventando el teléfono desde que le di mi número...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_038"] = "Yo no. De hecho, me iba a comprar un teléfono nuevo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_040"] = "No hay ningún \"todos\", solo amigos y familia que te aman.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_041"] = "Por supuesto que no. Y yo estoy aquí para ti.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_042"] = "Lo eché a perder y lo siento. Mira, estoy aquí para ti ahora.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_043"] = "¡A mí! ¡Solo baja y escúchame!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_044"] = "Kate, por favor, confía en mí. Ven a mi lado, ¿sí? Ahora puedo ayudarte... Sé que puedo.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_049"] = "Kate, estoy juntando evidencia para probar que Nathan Prescott te drogó. Y tú no eres la única víctima. Así que debes ayudarme a desenmascarar a Nathan.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_051"] = "No estaba segura sobre qué hacer. Han sucedido tantas cosas raras, ni... Ni sé por dónde empezar...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_052"] = "Por supuesto. Como dije esta mañana, creo que Nathan está involucrado. Solo necesito tiempo para probarlo. Y el tiempo está de mi lado...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_058"] = "Kate, te creo. ¿Me podrías creer?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_059"] = "Pronto. Luego directo a la Policía. Piénsalo como si estuviéramos limpiando Blackwell...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_061"] = "Bien. Necesitamos protegernos entre nosotras. Así que ahora quiero que vengas conmigo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_063"] = "¿Y tu madre, Kate? La vas a destruir. A ella no le importa el video. Te ama.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_064"] = "Espera, Kate, piensa en tus hermanos. Necesitan a su hermana...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_065"] = "Kate, vi esa tarjeta de tu padre. Puedes contar con él, claramente te ama más allá de todo.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_066"] = "Esta mañana, en tu habitación, vi esa adorable foto de tus hermanas y de ti. La sonrisa de tu hermanita me hace ver cuánto te ama.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_070"] = "¿Ves? No estás sola. Y nadie allí abajo quiere verte aquí arriba.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_072"] = "Entonces haz feliz a Lynn y acércate a mí. Si ella estuviese aquí, sabrías qué hacer.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_073"] = "¡No! Kate, por favor, detente... Escucha...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_075"] = "¿Cómo es qué decía aquel proverbio? \"Alegría es para el justo practicar la justicia, pero un desastre para los que cometen iniquidad\".",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_076"] = "Quizás yo esté aquí para ayudarte, Kate. Y quizás tú estás aquí para ayudarme a mí. Eres mucho más de lo que puedo poner en palabras...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_077"] = "\"Venid a mí todos los que estáis trabajados y cargados, y yo os haré descansar\".",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_078"] = "El suicidio es pecado, ¿no es así? Si crees en el infierno... podrías terminas allí. No quiero que eso suceda...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_082"] = "Créelo, Kate. Ahora, baja y ven conmigo...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_083"] = "Kate, esto destruirá a tu padre. ¿Piensas que le importa el video? Te ama incondicionalmente...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_084"] = "Me hablaste de tus hermanas, sobre todo de la más pequeña... ¿Cómo se llama?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_086"] = "Este no es el fin, Kate. Es imposible que Dios no tenga grandes planes para ti...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_088"] = "Kate, detente... Déjame hablarte...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_089"] = "A nadie le importa, Kate. Mañana habrá otro video viral de Victoria, y todos se olvidarán.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_090"] = "Kate, hay miles de millones de videos dando vueltas. El tuyo se perderá entre tantos.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_092"] = "Una vez que salga a la luz que fuiste drogada, todos te creerán.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_093"] = "Kate, esta es nuestra oportunidad para vencer a los bravucones. Es la única manera de derrotarlos.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_098"] = "Lo entiendo, de verdad. ¡A mí también me hostigan! Pero esto es una pequeñez...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_100"] = "Kate, si hay algo en lo que creo... es justamente eso. ¿Lo sellamos con un abrazo?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_101"] = "Para siempre. ¿Lo sellamos con un abrazo?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_102"] = "¡Kate! ¡No puedes hacerle esto a toda la gente que piensa en ti!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_103"] = "Sé que es terrible para ti, pero, como dice la Biblia, esto también pasará...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_106"] = "Brooke es tu amiga, ¿no es así?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_107"] = "Sé que Alyssa te cree. ¿O acaso comenzó a tratarte distinto?",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_108"] = "¡Desde luego que Stella cree en ti! ¡Nunca creyó en la mentira del video!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_109"] = "¿Y Dana? Ella cree en ti...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_110"] = "Como dije antes, me importas. Sé que ese pasaje significa mucho para ti.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_119"] = "No te preocupes, Kate, todo mejorará. Lo prometo.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_120"] = "Te ayudé borrando toda esa basura que escribieron en la pizarra de tu habitación...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_122"] = "Siempre estaré aquí, Kate. Mi nuevo lema es \"los amigos, primero\".",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_123"] = "Esta mañana borré el enlace del video... Estaba escrito en el espejo de las duchas...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_126"] = "Me preocupo por ti porque creo que fuiste drogada. Vamos a averiguar quién hizo esto, y le haremos pagar.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_127"] = "Sí... Sé que metí la pata. Lo siento tanto, Kate.",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_128"] = "¡Espera, Kate! ¡Lo siento!",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_129"] = "Por favor... no tienes que hacer esto...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_131"] = "Te creo, Kate. Pero es peligroso para las dos si me involucro...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_132"] = "Necesitaba más tiempo para investigar por mi cuenta... pero debemos tener cuidado...",
  ["Cue_E2_4C_CampusB_CHKate_Phase01_Max_135"] = "Ahora sí. Eres parte de la razón. Si vienes conmigo, te diré más...",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Alyssa_050"] = "No puedo creerlo, Brooke...",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Brooke_060"] = "Pobre Kate. Ese maldito video viral...",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Courtney_090"] = "No sabía que tenía tantos problemas...",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Courtney_160"] = "¡Ay, Dios mío!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Daniel_020"] = "Oh, no. ¿Es esa Kate?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Daniel_110"] = "Dios, definitivamente no vine a Blackwell para esto...",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Juliet_120"] = "¿Es esto real?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy01_040"] = "¡Mierda, esa chica está en el borde!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy01_170"] = "¡Mierda!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_010"] = "¿Quién está ahí arriba?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_030"] = "Espero que no...",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_150"] = "Lo suficiente...",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy02_200"] = "¿Lo viste?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenBoy03_140"] = "¿Cuánto tiempo ha estado allí arriba?",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl01_070"] = "Si salta, quizás no muera.",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl01_190"] = "¡No!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl02_080"] = "Por supuesto que sí.",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_TeenGirl02_180"] = "¡No!",
  ["Cue_E2_4C_CampusB_CommentingKate_IGE_Zachary_210"] = "¡Vaya!",
  ["Cue_E2_4C_CampusB_Freeze_RTC_Max_010"] = "Sigue... Max...",
  ["Cue_E2_4C_CampusB_Freeze_RTC_Max_020"] = "Tú... puedes... hacerlo...",
  ["Cue_E2_4C_CampusB_Insertion_TeenBoy01_070"] = "¡La puta perdió un tornillo!",
  ["Cue_E2_4C_CampusB_Insertion_TeenGirl01_010"] = "¡No! ¡Baja! ¡Que bajes!",
  ["Cue_E2_4C_CampusB_KateIsAlive_RTC_Kate_010"] = "Lo siento... lo siento...",
  ["Cue_E2_4C_CampusB_KateIsAlive_RTC_Max_020"] = "¿De qué estás hablando? ¡Me salvaste de hablar en clase!",
  ["Cue_E2_4C_CampusB_KateIsDead_Max_010"] = "¡No! ¡¡¡Kate!!!",
  ["Cue_E2_4C_CampusB_NoMoreRewind_Max_010"] = "No ahora...",
  ["Cue_E2_4C_CampusB_NoMoreRewind_Max_020"] = "No funcionará... No tengo ningún poder...",
  ["Cue_E2_4C_CampusB_NoMoreRewind_Max_030"] = "Tengo que hacerlo por mi cuenta...",
  ["Cue_E2_4C_CampusB_RoofArrival_Kate_020"] = "¿Qué haces aquí, Max?",
  ["Cue_E2_4C_CampusB_RoofArrival_Kate_030"] = "¡Basta! ¡No te me acerques!",
  ["Cue_E2_4C_CampusB_RoofArrival_Max_010"] = "Sí...",
  ["Act_E2_5A_PrinOffice_AfterMajorChoice_Max_010"] = "La cabeza me está matando, pero creo que puedo volver a usar mi poder.",
  ["Act_E2_5A_PrinOffice_CHMax_VoiceOver01_Max_010"] = "Cuanto antes firme este papel de mierda, más rápido podré salir de aquí.",
  ["Act_E2_5A_PrinOffice_CHMax_VoiceOver01_Max_020"] = "Fírmalo y podrás ponerle fin a este episodio de \"La ley y el orden\".",
  ["Act_E2_5A_PrinOffice_CHMax_VoiceOver01_Max_030"] = "Cuando quieras, Max. Es tan lindo pasar tiempo en esta oficina.",
  ["Cue_E2_5A_PrinOffice_Insertion_David_090"] = "Sí. Toda una \"heroína\".",
  ["Cue_E2_5A_PrinOffice_Insertion_Jefferson_080"] = "Es modesta. Como una verdadera heroína.",
  ["Cue_E2_5A_PrinOffice_Insertion_Max_070"] = "No hice demasiado...",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_010"] = "Sé que esto no es placentero para ninguno de nosotros, pero tenemos que repasar lo sucedido antes de que la señorita Marsh... antes de que hiciera lo que hizo.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_020"] = "El oficial Berry tomará las notas para el informe policial. Estoy seguro de que todos le brindarán su total cooperación.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_030"] = "Una tragedia... Pero tiene que haber un motivo para todo esto.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_040"] = "Tenemos que averiguar qué llevó a Kate Marsh a tomar tan terrible decisión.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_050"] = "Escuchen, sé que hoy fue un día difícil para todos, pero estoy orgulloso de la manera en que Blackwell actuó para salvar la vida de una jovencita.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_060"] = "Desde ya, eres toda una heroína por lograr que Kate bajara, Max.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_100"] = "Como director de la Academia Blackwell, tomo mi trabajo muy en serio. Y más aún el bienestar de los alumnos. Nunca debió haber sucedido esto en un establecimiento de sabiduría y conocimiento.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_110"] = "Señor Madsen, siendo nuestro jefe de seguridad, sabrá que|las puertas de la azotea debían estar cerradas. Estaban abiertas. Y esa es su responsabilidad.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_120"] = "Señor Jefferson, no se le puede exigir que sepa todo sobre sus estudiantes, pero Kate lo ayudaba en clase, así que debió haber notado algo raro.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_130"] = "Señor Prescott, debido a que usted es el responsable de las fiestas del club Vortex... Y debido a que la señorita Marsh concurrió a su última fiesta, tendrá que responder algunas preguntas más.",
  ["Cue_E2_5A_PrinOffice_Insertion_Principal_140"] = "Señorita Caulfield, ¿por qué estaba usted en la azotea con la señorita Marsh? ¿Le había contado lo que planeaba hacer? ¿Algo por el estilo? Por favor, cuéntenos todo.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_020"] = "Oh, madura...",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_040"] = "No tienes idea de lo que viste. Kate Marsh estaba involucrada con mala gente. Estaba intentando descubrir quiénes...",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_070"] = "Pequeña mentirosa...",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_080"] = "¿Va a priorizar la palabra de esta drogadicta antes que la de su oficial de seguridad? Sé que fuma y vende... marihuana.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_120"] = "¿Va a priorizar la palabra de esta alborotadora antes que la de su oficial de seguridad?",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_160"] = "Eso no es... no es prueba.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_David_230"] = "¿Es una maldita broma? ¡Esto es pura mierda! ¿Yo comandé tropas a batalla y usted deja que esta mocosa le diga qué hacer?",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Jefferson_250"] = "Disculpe, creo que Max y Nathan necesitan un descanso antes de seguir respondiendo.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Jefferson_260"] = "Una amiga y compañera ha muerto... No necesitan un foro ahora.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Jefferson_270"] = "Una amiga y estudiante ha intentado suicidarse... No necesitan un foro ahora.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_010"] = "El Sr. Madsen molestaba a Kate.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_030"] = "¡Perdón, yo estaba allí! ¡Te vi gritándole!",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_060"] = "No, tú eras parte de la muchedumbre. Y como dije, vi personalmente a David molestando a Kate Marsh físicamente.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_090"] = "¿Qué? ¡Eso no tiene nada que ver con Kate!",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_130"] = "¿Y debe él creerle a alguien que acosa estudiantes?",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_150"] = "Pero yo tengo pruebas.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_155"] = "Esta es una foto que tomé ayer de David y Kate.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Max_180"] = "Y todavía ni mencionamos lo que hay en tus archivos...",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Nathan_050"] = "Kate llevaba una doble vida. Estaba tan estupefacto cuando me enteré...",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Nathan_280"] = "Sí, en verdad estoy devastado. Me gustaría estar con mi familia.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_100"] = "Max, acusar falsamente a otros parece ser costumbre contigo. Yo confío en mi oficial de seguridad.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_110"] = "Tendré que investigar si esta acusación es verdadera.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_115"] = "Por lo tanto, Max, estoy obligado a contactar a tus padres y suspenderte por unos días.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_140"] = "Max, temo que no resolveremos esto sin pruebas ni una investigación profunda. Entonces, si no hay más nada que decir...",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_170"] = "Un momento, esto no es un tribunal. Pero creo que ponerte en suspensión temporal sería lo mejor tanto para Blackwell como para esta situación...",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_190"] = "Seguiremos con esta conversación luego.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_200"] = "Si Dios quiere, con la señorita Marsh, una vez que salga del hospital.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_210"] = "Seguiremos con esta conversación luego.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_220"] = "Cuando la Policía termine con su investigación.",
  ["Cue_E2_5A_PrinOffice_MaxChoice01_Principal_240"] = "No. Lo siento, David...",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_David_020"] = "Incluyéndome.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_David_080"] = "No puede. ¡Ella fuma y vende drogas, no salva vidas!",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_David_110"] = "No puede. Es una perdedora.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_001"] = "Todo lo que sé es que Kate estaba en una fiesta, y Nathan la drogó. Se emborrachó y besó a unos chicos en un video viral, sin saberlo.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_003"] = "Estás mintiendo. ¡Le dijiste a Kate que la llevaste a la sala de emergencias!",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_005"] = "¡Mentira! Algo le sucedió, y lo sabes. Qué tal si hablamos del arma que anduviste mostrando en el baño de mujeres.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_060"] = "Ayer tenía miedo, pero hoy debo decir la verdad.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_090"] = "¡No, no es cierto y eso no tiene nada que ver con Kate Marsh!",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Max_120"] = "Solo los perdedores golpean a las chicas.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_002"] = "¿La drogué? ¿Sin saberlo? ¿Viste el video? Como sea. Kate estaba ebria y buscaba...",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_004"] = "Dije que la iba a llevar a la sala de emergencias. Al rato volvió en sí.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_006"] = "¡Ey, eso es difamación! ¡Podría demandarte a ti y a esta escuela en un abrir y cerrar de ojos! Ya tengo un abogado personal.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Nathan_040"] = "Como sea. Nos veremos en la corte.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_010"] = "Con cuidado, Sr. Prescott. Me habían comentado sobre este supuesto incidente con un arma. Y debo admitir que este video en cuestión me fue enviado desde varias fuentes.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_030"] = "Y como el Señor Prescott aparece prominentemente en el video, y era responsable de la fiesta, no me queda más remedio que suspenderlo hasta nuevo aviso.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_050"] = "Espera, Max. Me dijiste que no había sucedido nada ayer. ¿Estás inventando todo? ¿Cómo podría confiar en ti?",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_070"] = "Lo entiendo.",
  ["Cue_E2_5A_PrinOffice_MaxChoice02_Principal_100"] = "Por favor, cálmense.",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_030"] = "Kate... La señorita Marsh... ha estado muy inhibida últimamente. Y asumo que este horrible video fue la causa. Detestaba ver a los estudiantes reírse de ella.",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_040"] = "Me dijo que Max era la única que le creía, que contestaba sus llamadas, y quien realmente la escuchaba.",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_050"] = "Estaba enojada porque la señorita Caulfield no le devolvía las llamadas. Se sentía rechazada por la escuela...",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_080"] = "No, al contrario. Max estuvo bien en mencionar esto. Bien, yo quería ayudar, pero creo que llegué demasiado tarde...",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_100"] = "¿Está hablando en serio?",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_120"] = "Entiendo. Hay cosas más importantes que yo en juego. Por ejemplo, la vida de una jovencita...",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Jefferson_130"] = "Quizás habría que investigar al resto de los empleados. Max me dijo que sabía cosas sobre el Sr. Madsen...",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Max_010"] = "Vi al Sr. Jefferson hablándole a Kate justo antes de nuestra clase... luego ella escapó llorando...",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Max_070"] = "Idiota. Ella no quiso nada de esto...",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Nathan_060"] = "No se hubiera dejado filmar besando desconocidos…",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_020"] = "Mark, sé que la señorita Marsh te ayudaba en algunas clases.",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_090"] = "Bueno, esto es problemático. Esto se está volviendo cada vez más público y quizás... no deberías representar a Blackwell en el concurso Héroes Cotidianos en San Francisco...",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_110"] = "Así es. No necesitamos prensa negativa sobre ese evento. Y necesitamos consultar a la Academia sobre posibles medidas disciplinarias para ti.",
  ["Cue_E2_5A_PrinOffice_MaxChoice03_Principal_140"] = "Dejemos que Max hable por sí misma. Todo lo que se dijo aquí se tendrá en consideración.",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_010"] = "De acuerdo, señorita Caulfield, por favor, firme aquí para confirmar lo que nos ha dicho. Continuaré esta investigación a partir de aquí.",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_030"] = "Bueno, creo que sabemos menos que cuando empezamos. Asistiremos a la Policía con futuras investigaciones.",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_040"] = "Desde este momento, cancelo la fiesta del club Vortex. Sé que los estudiantes se han esforzado mucho, pero... tenemos padres preocupados que nos llaman a cada minuto. No vamos dejar nada librado al azar hasta que este asunto se haya investigado a fondo.",
  ["Cue_E2_5A_PrinOffice_PrinSoloEnd_Principal_050"] = "Sé que fue un día estresante... me gustaría tener el poder de cambiar todo para mejor... gracias por venir.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_010"] = "Simplemente... no puedo creerlo. Es como si no fuera real... Verla caer... realmente pensé que podría salvarla... como un superhéroe.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_030"] = "Mi mano se estiró...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_050"] = "Sí, seguro que marqué una maldita diferencia. Quizás si más gente se hubiese preocupado... gente mejor que yo...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_070"] = "Warren, lo arruiné hoy.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_090"] = "No podía creer lo que estaba sucediendo. Todo pasaba en cámara lenta cuando tomé su mano... y luego pude sentirla agarrando la mía.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_110"] = "Ni tanto. Mírame, soy un desastre.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_130"] = "Sigo preocupada por Kate. De verdad intentó suicidarse. Todo por un video...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_150"] = "¿Entonces lo viste?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_170"] = "Warren, no quiero que suene extraño, pero algo siniestro está sucediendo en Blackwell...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_190"] = "Y estoy buscando pruebas que conecten a Kate Marsh con Rachel Amber... de algún modo. Tanto como con Nathan y el Sr. Madsen.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_210"] = "¿Qué diablos es esto?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_230"] = "Brrr... Sí que tengo frío.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_250"] = "Qué lindo, gracias. Estoy bien.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_260"] = "El clima confirma este día raro. Siente ese frío...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_270"] = "Hablando de \"claroscuro\".",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Max_290"] = "Te creo, Warren... Creería cualquier cosa esta semana...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_020"] = "Vamos, Max. No te culpes ni por un instante. Kate estaba en esa azotea por ella, no por ti.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_040"] = "Basta. Fuiste la única con los huevos suficientes como para correr hacia la azotea. Fuiste la única a la que le importó.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_060"] = "Eres la mejor persona de aquí...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_080"] = "Eso no tiene sentido.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_100"] = "Max, eso fue lo mejor que he visto. Jamás. Tú te estiraste, ella se estiró... Abrazos, lágrimas, aplausos... ¡Como una superheroína!",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_120"] = "Brillas. En serio. Un halo humano. Estoy seguro de que hoy te volviste un ángel.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_140"] = "\"Viral\" es la palabra correcta. Como una enfermedad.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_160"] = "Solo una vez... y media...",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_180"] = "El día de hoy lo prueba.",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_200"] = "No soy fanático de las conspiraciones, pero no lo dudo. Nathan sí que me asustó ayer, y Madsen es un completo cabrón. Entonces... ¿qué crees que está pasando?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_220"] = "¿Sientes cómo bajó la temperatura?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_240"] = "¿Quieres mi chaqueta?",
  ["Cue_E2_6A_CampusA_Insertion_RTC_Warren_280"] = "Max, no había ningún eclipse anunciado para hoy... Lo sabría. Realmente lo sabría.",
  ["Act_E3_1A_Bathroom_AbstinencePoster_Look01_Max_010"] = "Me imagino que Kate no va a querer ni ver estos carteles cuando vuelva...",
  ["Act_E3_1A_Bathroom_AbstinencePoster_Look02_Max_010"] = "Nadie puede culpar este cartel de la muerte de Kate...",
  ["Act_E3_1A_Bathroom_CHTaylor_Look01_Max_010"] = "Válgame Dios, parece que Taylor está realmente preocupada por Kate...",
  ["Act_E3_1A_Bathroom_CHTaylor_Look02_Max_010"] = "No debería ser tan criticona. Es obvio que Taylor está triste por lo de Kate...",
  ["Act_E3_1A_Bathroom_Mirror2_Look01_Max_010"] = "Espero que Victoria se sienta de la mierda por publicar ese enlace.",
  ["Act_E3_1A_Bathroom_Shower_Look01_Max_010"] = "Arj. Max de las cavernas quiere bañarse, pero no hay tiempo. Debe encontrarse con Chloe.",
  ["Act_E3_1A_Corridor_DanaSlate_Look01_Max_010"] = "Dana está sufriendo mucho por todo esto.",
  ["Act_E3_1A_Corridor_DeathShrine_Interact01_Max_010"] = "Esta es mi oración para ti, Kate. Descansa en paz...",
  ["Act_E3_1A_Corridor_DeathShrine_Look01_Max_010"] = "Kate, renunciaría a mi poder por otra oportunidad de rebobinar para salvarte... No descansaré hasta que descubramos la verdad... y que alguien las pague.",
  ["Act_E3_1A_Corridor_Enter_VoiceOver01_Max_010"] = "Bueno, está demasiado oscuro. Que se haga la...",
  ["Act_E3_1A_Corridor_KateDoor_Look01_Max_010"] = "Dios, es como una de esas horribles escenas de crimen de la tele, solo que en nuestra residencia.",
  ["Act_E3_1A_Corridor_KateDoor_Look02_Max_010"] = "¿Es necesario que esa mierda esté en la puerta? Kate aún sigue viva...",
  ["Act_E3_1A_Corridor_KateSlate_Look01_Max_010"] = "Tanta hipocresía.",
  ["Act_E3_1A_Corridor_MPA_Look01_Max_010"] = "¿Dónde chingados estás, Rachel Amber?",
  ["Act_E3_1A_Corridor_MPA_Look02_Max_010"] = "Siento que nos estás guiando... pero ¿adónde?",
  ["Act_E3_1A_Corridor_MPA_Look04_Max_010"] = "Sí, te voy a encontrar, Rachel... por Chloe y Kate.",
  ["Act_E3_1A_Corridor_MaxSlate_Look01_Max_010"] = "Espero que Kate ya sea un ángel...",
  ["Act_E3_1A_Corridor_MaxSlate_Look02_Max_010"] = "Espero que tu luz se encienda pronto, Kate.",
  ["Act_E3_1A_Corridor_NathanGraffiti_Look01_Max_010"] = "No hay forma de que limpie esa mierda. Es hora de que Samuel Da Vinci vuelva a pintar...",
  ["Act_E3_1A_Corridor_Poster1_Look01_Max_010"] = "Que siga la pachanga, pendejos.",
  ["Act_E3_1A_Corridor_Poster2_Look01_Max_010"] = "El fin del mundo quizás llegue antes de su fiesta...",
  ["Act_E3_1A_Corridor_Scripted2_Max_030"] = "Considerando las locuras que hice en los últimos días, escabullirme no es nada.",
  ["Act_E3_1A_Corridor_Scripted4_Max_010"] = "Será mejor que vaya a reunirme con Chloe.",
  ["Act_E3_1A_Corridor_Scripted4_Max_020"] = "Tengo que ser supercuidadosa para que no me cachen fuera de la residencia a estas horas.",
  ["Act_E3_1A_Corridor_Scripted_Max_010"] = "Bolas, realmente lo dice en serio... Ahora me doy cuenta de que la pendejez es hereditaria.",
  ["Act_E3_1A_Corridor_Scripted_Max_020"] = "Es retorcido. Sí, tengo un poder, pero Nathan está fuera de control...",
  ["Act_E3_1A_Corridor_Scripted_Max_030"] = "Victoria no está aquí... Podría hacer tiempo... mientras reviso su mierda.",
  ["Act_E3_1A_Corridor_TaylorSlate_Look04_Max_010"] = "Increíble. Taylor no tiene ni una pizca de vergüenza.",
  ["Act_E3_1A_Corridor_VictoriaSlate_Look01_Max_010"] = "Esa es una reflexión deprimente. Y siempre se trata de Victoria...",
  ["Act_E3_1A_Corridor_VortexPoster_Look01_Max_010"] = "Sí, el club Vortex es malísimo.",
  ["Act_E3_1A_Corridor_VortexPoster_Look03_Max_010"] = "Primero Rachel y ahora Kate... Este es el final del club Vortex.",
  ["Act_E3_1A_DanaRoom_CHDana_Look01_Max_010"] = "Dana se ve tan triste, aunque se esfuerza por no demostrarlo...",
  ["Act_E3_1A_DanaRoom_CHDana_Look02_Max_010"] = "Dana parece culpable y aliviada por lo Kate... De verdad le importa.",
  ["Act_E3_1A_DanaRoom_DanaLaptop_Interact01_Max_010"] = "Ayyy, Trevor es un encanto. Bien por Dana.",
  ["Act_E3_1A_DanaRoom_DanaLaptop_Interact02_Max_010"] = "Dana se va a arrepentir si llega a hablar con Juliet sobre lo que pasó...",
  ["Act_E3_1A_DanaRoom_DanaLaptop_Look01_Max_010"] = "A Dana claramente no le importa que revise su compu...",
  ["Act_E3_1A_DanaRoom_HalloweenStuff_Max_010"] = "Es tan tierno lo emocionada que Dana está por la fiesta de Halloween.",
  ["Act_E3_1A_DanaRoom_LoganNote_Max_010"] = "Esto es triste y patético.",
  ["Act_E3_1A_MaxRoom_Bed_Look01_Max_010"] = "Jebús, estoy tan agotada, carajo... Sueno como una idiota... Pero el crimen no descansa... Necesito mantener esta investigación bajo control...",
  ["Act_E3_1A_MaxRoom_DavidPicture_Look01_Max_010"] = "Soy tan idiota, Kate. Pude habérsela mostrado al director y amolar a David... Pude...",
  ["Act_E3_1A_MaxRoom_Drawer01_Look01_Max_010"] = "Kate, te juro que voy a hacer todo lo que pueda para descubrir quién fue la persona que realmente te empujó de esa azotea...",
  ["Act_E3_1A_MaxRoom_Drawer01_Look02_Max_010"] = "Es increíble lo feliz que se ve Kate, en comparación con lo de hoy... Prácticamente la empujaron hasta esa azotea. Y voy a usar mi poder para averiguar por qué. Debo ponerle fin a esto.",
  ["Act_E3_1A_MaxRoom_Hifi_Interact01_Max_010"] = "Creo que esto no me servirá de mucho para escabullirme...",
  ["Act_E3_1A_MaxRoom_Hifi_Look01_Max_010"] = "Sabes que estás depre cuando la música te vale madre.",
  ["Act_E3_1A_MaxRoom_Laptop_Interact01_Max_010"] = "Qué bueno que las noticias no desperdicien ni un minuto en aprovecharse de una tragedia. Ahora la familia de Kate tiene que ver la muerte de su hija en Internet como si fuera el video de un gatito... y hasta yo aparezco en él. Me da náuseas.",
  ["Act_E3_1A_MaxRoom_Laptop_Interact02_Max_010"] = "Qué bueno que las noticias no desperdicien ni un minuto en aprovecharse de Kate. Ahora hay otro video de ella en Internet... y ahora aparezco yo en él. Al menos las noticias no mencionan mi nombre... por ahora.",
  ["Act_E3_1A_MaxRoom_Laptop_Interact03_Max_010"] = "Mmmm. Aparte de Rachel, pasó bastante tiempo desde la última vez que alguien desapareció de Arcadia Bay... No debería sonar tan decepcionada.",
  ["Act_E3_1A_MaxRoom_Laptop_Interact04_Max_010"] = "Solo es un copiar pegar muy emotivo de la mierda de Blackwell. Nadie aquí se preocupa por Kate de verdad. Demasiado poco y demasiado tarde...",
  ["Act_E3_1A_MaxRoom_Laptop_Interact05_Max_010"] = "Sí, ahora todos aman a Kate Marsh. Primero la maltrataban; ahora, publican sentimientos. Hipócritas.",
  ["Act_E3_1A_MaxRoom_Laptop_Interact06_Max_010"] = "Más les vale que la traten mejor cuando regrese a la escuela... si es que vuelve.",
  ["Act_E3_1A_MaxRoom_Laptop_Interact07_Max_010"] = "Qué desmadre, hice una montaña de un grano de arena... Me siento mal por el Sr. Jefferson...",
  ["Act_E3_1A_MaxRoom_Laptop_Interact08_Max_010"] = "Ahora David verá lo que se siente estar vigilado todo el tiempo.",
  ["Act_E3_1A_MaxRoom_Laptop_Interact09_Max_010"] = "Puedo o borrar mi página o bloquear a todos. No hay lugar donde ocultarse estos días...",
  ["Act_E3_1A_MaxRoom_Laptop_Look01_Max_010"] = "¿Cómo es que Sherlock Holmes deducía todo sin usar Internet?",
  ["Act_E3_1A_MaxRoom_Mirror_Look01_Max_010"] = "Vamos, Max. Deja de llorar. Debes actuar, no reaccionar.",
  ["Act_E3_1A_MaxRoom_Mirror_Look02_Max_010"] = "Kate está bien, Max. Toma un descanso y espabílate. Tienes tiempo.",
  ["Act_E3_1A_MaxRoom_NathanPhoto_Look01_Max_010"] = "Puaj, gracias por la imagen, Nathan... y todo el mundo aquí piensa que Samuel es el tenebroso...",
  ["Act_E3_1A_MaxRoom_Plant_Interact01_Max_010"] = "Bebe, mi preciosa...",
  ["Act_E3_1A_MaxRoom_Plant_Look01_Max_010"] = "Pobre Lisa. Creo que soy mejor con las personas que con las plantas...",
  ["Act_E3_1A_MaxRoom_Plant_Look02_Max_010"] = "¡Ay, no! Si ni siquiera puedo cuidar de una planta, mucho menos puedo cuidar de una persona... ¿Para qué sirvo?",
  ["Act_E3_1A_MaxRoom_Plant_Look03_Max_010"] = "Ves, Lisa, al menos que a ti sí te mantuve viva... Soy mejor con las plantas que con las personas...",
  ["Act_E3_1A_MaxRoom_Plant_Look04_Max_010"] = "Primero salvo a Chloe, después a Kate y ahora a ti, Lisa. No es un mal logro para una semana.",
  ["Act_E3_1A_MaxRoom_Plant_Look05_Max_010"] = "Lo siento, Lisa... Salvo a Kate, pero ahogo mi propia planta...",
  ["Act_E3_1A_MaxRoom_Plant_Look06_Max_010"] = "Lo siento, Lisa. Demasiada agua. Si ni siquiera puedo mantener mi planta viva, mucho menos a Kate...",
  ["Act_E3_1A_MaxRoom_Rabbit_Interact01_Max_010"] = "¿Eres un conejito hambriento? Ten, come esto...",
  ["Act_E3_1A_MaxRoom_Rabbit_Look01_Max_010"] = "Oye, conejito, no te deprimas, pero de ahora en adelante... soy tu nueva mamá.",
  ["Act_E3_1A_MaxRoom_Rabbit_Look02_Max_010"] = "Oye, conejito, Kate estará de regreso pronto; mientras tanto, te trataré como a un rey.",
  ["Act_E3_1A_MaxRoom_Schedule_Look01_Max_010"] = "A ver a qué clases no iré esta semana...",
  ["Act_E3_1A_MaxRoom_Schedule_Look02_Max_010"] = "Se me complica concentrarme en el horario de esta semana... ¿Por qué será?",
  ["Act_E3_1A_MaxRoom_Scripted_Max_010"] = "Todavía no puedo dejar de pensar en Kate... Es como estar despierta en una pesadilla...",
  ["Act_E3_1A_MaxRoom_Scripted_Max_020"] = "Es una mierda, estoy tan cansada... pero no puedo parar ahora.",
  ["Act_E3_1A_MaxRoom_Scripted_Max_030"] = "Todo el mundo va a hablar de Kate ahora. Blackwell bien podría cerrar por el próximo mes.",
  ["Act_E3_1A_MaxRoom_Scripted_Max_040"] = "Órale, la puerta de Dana está abierta. No voy a amolarla por hablar con ella.",
  ["Act_E3_1A_MaxRoom_Window_Look01_Max_010"] = "Pasaron tantas cosas que casi me olvido del eclipse... Toda esta acción atmosférica no puede ser una coincidencia... y todos los caminos conducen a mi visión del tornado...",
  ["Act_E3_1A_VicRoom_Cookies_Look01_Max_010"] = "¿Mis galletas? ¡Victoria se robó mis galletas! ¡Ahora no puedo llevármelas porque sabrá lo hice! Victoria es... el ComeGalletas.",
  ["Act_E3_1A_VicRoom_Desk_Interact01_Max_010"] = "Llamaré esta foto \"Retrato de los pendejos\".",
  ["Act_E3_1A_VicRoom_Desk_Interact02_Max_010"] = "Vaya, ahí está Kate, totalmente drogada. Parece confundida, no de reventón.",
  ["Act_E3_1A_VicRoom_Drawer1_Interact01_Max_010"] = "Aquí están de reventón con Satanás...",
  ["Act_E3_1A_VicRoom_Drawer2_Interact01_Max_010"] = "Estos calcetines cuestan más que mi armario completo.",
  ["Act_E3_1A_VicRoom_Object01_Interact01_Max_010"] = "¿El secreto de Victoria? Es una ñoña.",
  ["Act_E3_1A_VicRoom_Object02_Interact01_Max_010"] = "Victoria tiene tanta \"calle\"... como yo. Pero sí que aprecia el estilo.",
  ["Act_E3_1A_VicRoom_Poster06_Look01_Max_010"] = "Vaya, no sabía que The Chase Space era de los padres de Victoria. Estoy impresionada.",
  ["Act_E3_1A_VicRoom_SchoolBag_Interact01_Max_010"] = "Definitivamente, \"un punto de vista único\". Gracias a Courtney Wagner que lo escribió.",
  ["Act_E3_1A_VicRoom_Scripted3_Max_020"] = "Ya que pasé de fisgona a detective, también podría buscar pistas sobre lo que realmente le sucedió a Kate en la fiesta del club Vortex.",
  ["Act_E3_1A_VicRoom_Scripted3_Max_030"] = "Nada hay que ver aquí. Supongo que no debería estar tan decepcionada. Aunque Victoria podría ocultar toda su mierda... Mierda, me estoy poniendo paranoica.",
  ["Act_E3_1A_VicRoom_Trash_Interact01_Max_010"] = "Es demasiada lana para sacar pintura de un suéter...",
  ["Act_E3_1A_VicRoom_Trash_Interact02_Max_010"] = "Felicidades Max, estás husmeando en la basura de otra persona. Mmmm, lindo lápiz labial.",
  ["Act_E3_1A_VicRoom_VicPicture_Look01_Max_010"] = "Victoria debe tener su propio poder si encontró tiempo para robar la foto de mi habitación... Buen trabajo.",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Interact01_Max_010"] = "Órale. Quizás Victoria no sea un monstruo después de todo...",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Interact02_Max_010"] = "Órale. Victoria y Taylor de verdad parecen sentir remordimiento...",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Interact03_Max_010"] = "Esto es como una cadena de sociópatas. ¿\"Max Crackfield\"? Aburrido. Que siga la fiesta, güey.",
  ["Act_E3_1A_VicRoom_VictoriaLaptop_Look01_Max_010"] = "Aquí tiene que haber algo que comprometa a Victoria...",
  ["Act_E3_1A_VicRoom_VictoriaShoes_Look01_Max_010"] = "Estas botas están hechas para las pasarelas...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_007"] = "¿Dónde fue?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_009"] = "Yo también tengo mente propia. Hasta luego.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_010"] = "Deberías creerlo... Saltó porque todos aquí, incluso tú, la maltrataban.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_011"] = "Yo sí. Desearía haber podido detenerla... ¿Estás bien?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_012"] = "¡Deberías creerlo! Casi saltó porque todos aquí, incluso tú, la maltrataban.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_013"] = "Yo sí. Solo estoy contenta de que no lo haya hecho. ¿Estás bien?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_018"] = "Yo tampoco. No pensé que te iba a afectar tanto, considerando todas las chingaderas que tú y Victoria le hacían a Kate...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_037"] = "Por supuesto. Hasta luego.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_040"] = "Por supuesto. Espero que tu mamá mejore. Avísame si necesitas algo.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_041"] = "No diré nada. Lo juro por Bongo.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_043"] = "Lo sé... Victoria debe estar bastante agitada, ya que la vi escabullirse de la residencia después de la hora límite...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_044"] = "De hecho, sí.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_048"] = "Al infierno, probablemente. Bueno, a la cama. Fue un día complicado.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Max_052"] = "Yo también tengo mente propia. Avísame si necesitas algo.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_001"] = "Hola, Max... Vi que subiste a la azotea para intentar ayudar a Kate... No puedo creer que haya saltado...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_004"] = "Hola, Max... Vi que subiste a la azotea y salvaste a Kate... No puedo creer que haya intentado saltar...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_008"] = "Tengo mente propia, no soy la esclava de Victoria. ¿Hola? O sea, a ella también se le heló la sangre. Si hasta salió después de la hora límite... ¡Chingado! No debía contárselo a nadie.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_014"] = "O sea, estoy algo así como shockeada. Nunca vi a nadie tratar de suicidarse antes...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_015"] = "¿Qué? O sea, ¿me culpas a mí?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_016"] = "O sea, estoy algo así como paralizada. Yo... Nunca había visto a nadie morir...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_017"] = "¿Qué? O sea, ¿me culpas a mí?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_019"] = "Haz de cuenta que mis labios están sellados. O Victoria los sellará por mí.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_032"] = "Espero poder creerte, Max.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_036"] = "Te creo, Max. Además de Victoria, eres la única que me preguntó cómo estaba mamá. Eso significó mucho para mí...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_038"] = "Gracias... Max, o sea, eres rara, pero genial. Sobre todo después de verte en la azotea. Victoria está equivocada sobre ti. Ahora quiero estar sola para mi ataque de ansiedad nocturna. Hablamos más tarde...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_039"] = "Sé que puedo confiar en ti porque fuiste muy agradable cuando me preguntaste por mamá. Pero Victoria como que hará de mi vida un infierno si se entera que le conté a alguien, ¿entiendes?",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_045"] = "Entonces, ¿por qué no te largas? O sea, deja de estarme jodiendo. Tengo mi propia mierda familiar con la que debo lidiar. Suficiente por hoy.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_046"] = "Entonces, ¿por qué no te largas? O sea, deja de estarme jodiendo. Ya te dije que mamá está en el hospital. Suficiente por hoy.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_047"] = "Vaya, ¿la viste? O sea, estaba tan nerviosa cuando salió de la residencia... Ni siquiera me dijo adónde iba.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_049"] = "Victoria estaba equivocada sobre ti. Ahora quiero estar sola para mi ataque de ansiedad nocturna. Hablamos más tarde...",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_050"] = "Gracias, Max... Y fue... o sea, estuvo de pelos cuando subiste a la azotea para salvar a Kate.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Phase01_Taylor_051"] = "Gracias, Max. Y espero que tú también estés mejor. Fuiste la única a que intentó salvar a Kate.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Quick01_Taylor_001"] = "O sea, Max, me harté, en serio. Por favor, déjame en paz.",
  ["Cue_E3_1A_Bathroom_CHTaylor_Quick01_Taylor_002"] = "O sea, la verdad es que necesito dormir, Max.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_003"] = "No puedo dejar de pensar en Kate... y si también es culpa mía...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_004"] = "Debe haber sido bastante serio para que se tirara de una azotea...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_005"] = "Mejor que Kate. Me cuesta creer que siquiera intentara suicidarse...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_006"] = "Tú no, Max, tú eras su amiga...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_012"] = "Es verdad... pero eres la única que subió a esa azotea con Kate.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_014"] = "Definitivamente se merece un buen cate en la cara por subir ese video. No hice lo suficiente para evitarlo.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_017"] = "Definitivamente se merece un buen cate en la cara por subir ese video. No hice lo suficiente para evitarlo.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_021"] = "O sea, ¿por qué yo sabría algo más?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_023"] = "¿Qué quieres decir, Max?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_025"] = "Y, Max, no me gusta que me trates como si fuese una sospechosa. Tengo un chingado dolor de cabeza ahora, así que, por favor, déjame ir a dormir.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_028"] = "Tal vez Kate estaba tan avergonzada por haberse emborrachado en ese video... No la culpo, pero fue bastante repugnante.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_030"] = "Diles eso a Victoria y al club Vortex.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_032"] = "Lo entiendo, eres mejor persona que todos aquí... Oye, Max, creo que necesito dormir ahora. Todo lo de hoy me agotó...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_033"] = "Lo sé, Kate podría haber mandado a todos a la chingada, pero era una chica extremadamente agradable e inocente...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_037"] = "No, querida, eso no fue suerte. Tomaste una decisión, la de salvarla, ¡como una superheroína!",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_039"] = "¿Crees que esto tenga algo que ver con la expulsión de Nathan?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_040"] = "Sé que el director regañó feo a Jefferson... ¿Crees que están involucrados?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_041"] = "¿Crees que David Madsen sea parte de esto? Al fin de cuentas, también consiguió que lo pescaran por cabrón.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_044"] = "Me estoy asustando... Pero la gente aquí sigue escapándose de noche...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_047"] = "Victoria se peló de aquí hace un rato, y ahora tú, Sherlock...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Dana_048"] = "¿Esto tiene algo que ver con que te hayan suspendido ayer? Dime la verdad.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_001"] = "Hola, Dana... ¿Cómo estás?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_002"] = "Sabía que estaba deprimida, pero nunca imaginé que llegara a esto…",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_008"] = "Creo que todos somos responsables por lo que pasó...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_009"] = "Vamos, no te culpes. Hay otras personas involucradas. Como Victoria Chase.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_010"] = "Porque Victoria no iba a dejar de torturar a Kate con ese video.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_011"] = "Vamos, no te culpes. Hay otras personas involucradas. Como Victoria Chase.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_015"] = "¿En serio solo sabes eso?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_016"] = "Llegó el momento de darle lo que se merece. En otras palabras, venganza.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_022"] = "Kate no estaba jugando. Pero no fue todo culpa de ese video...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_024"] = "¿Por qué crees que ella estaba en la azotea en primer lugar?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_026"] = "¡Eso fue una chingadera! ¿Dónde estaba todo el mundo?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_027"] = "Tuve suerte, eso es todo.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_029"] = "¿Realmente crees que Kate Marsh quería emborracharse en una fiesta del club Vortex?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_031"] = "Sí, es una pena que yo haya sido la única.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_034"] = "Dana, creo que el que Victoria y el club Vortex se portaran mal no es todo.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_035"] = "Fuiste buena con Kate. Eso es lo único que necesitaba del resto de nosotros.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_036"] = "Pero no importa ahora. Kate murió.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_038"] = "Así que tal vez es momento de atrapar a los malos...",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_042"] = "No estoy segura aún, pero ya lo descubriré. Están pasando cosas muy raras en Blackwell, y voy a averiguar por qué.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_043"] = "Es complicado... No quiero arrastrarte en esto, ¿está bien? Al menos todavía no.",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_045"] = "¿Qué? ¿Quién?",
  ["Cue_E3_1A_DanaRoom_CHDana_Phase01_Max_046"] = "Yo no. Necesito tomarme un descanso de este día... Tú también descansa, Dana. Hasta luego.",
  ["Cue_E3_1A_DanaRoom_CHDana_Quick01_Dana_001"] = "Estoy muerta, Max. Hablemos más tarde.",
  ["Cue_E3_1A_DanaRoom_DanaCall_Dana_010"] = "Oye, Max, ven aquí.",
  ["Cue_E3_1A_DanaRoom_DanaCall_Dana_020"] = "Oye, ¿puedes venir aquí por un minuto?",
  ["Cue_E3_1A_MaxRoom_MaxWakesUp_Max_010"] = "¡Kate!",
  ["Cue_E3_1A_MaxRoom_MaxWakesUp_Max_050"] = "Sabía que Chloe se iba a entusiasmar... Mejor salgo a verla.",
  ["Act_E3_1B_CampusB_Bench_Look01_Max_010"] = "Es tan extraño que Kate estuviera sentada aquí mismo ayer...",
  ["Act_E3_1B_CampusB_Bench_Zen01_Max_010"] = "Me siento emocionada, incluso después de que Kate casi saltara.",
  ["Act_E3_1B_CampusB_Bench_Zen01_Max_020"] = "Tal vez sea la adrenalina...",
  ["Act_E3_1B_CampusB_Bench_Zen01_Max_030"] = "Pero, en este momento, me siento medio... invencible.",
  ["Act_E3_1B_CampusB_Bench_Zen02_Max_010"] = "¿Qué chingados estoy haciendo aquí?",
  ["Act_E3_1B_CampusB_Bench_Zen02_Max_020"] = "Kate está muerta, y yo me estoy escabullendo...",
  ["Act_E3_1B_CampusB_Bench_Zen02_Max_030"] = "Este campus parece un cementerio...",
  ["Act_E3_1B_CampusB_BrokenLamp_Look01_Max_010"] = "Quizás Samuel debería arreglar esa lámpara...",
  ["Act_E3_1B_CampusB_BrokenWindow_Look01_Max_010"] = "Dondequiera que vaya, veo cómo altero la historia... de a poquito y a montones.",
  ["Act_E3_1B_CampusB_CHPrincipal_Look01_Max_010"] = "El director Wells estaba totalmente borracho. Debe estar triste por Kate...",
  ["Act_E3_1B_CampusB_CHPrincipal_Look02_Max_010"] = "Por suerte, nadie más lo vio en ese estado, solo yo.",
  ["Act_E3_1B_CampusB_Cardboard_Interact01_Max_010"] = "Veamos qué esconde...",
  ["Act_E3_1B_CampusB_Cardboard_Look01_Max_010"] = "Nada por aquí.",
  ["Act_E3_1B_CampusB_Drawers_Look01_Max_010"] = "Tuercas y tornillos... como el garage del abuelo.",
  ["Act_E3_1B_CampusB_Fireflies_Look01_Max_010"] = "Ah, los insectos más mágicos... resplandecen con inmenso brillo.",
  ["Act_E3_1B_CampusB_GirlStuff_Look01_Max_010"] = "Sé que Samuel no usa bufandas de seda... entonces, ¿quién lo hace?",
  ["Act_E3_1B_CampusB_GotCaught_Scripted_Max_010"] = "Genial, me vio. Quizás podría escurrirme cuando él intentaba abrir la puerta...",
  ["Act_E3_1B_CampusB_JanitorDoor_Interact01_Max_010"] = "Oh, ¡está sin llave! Espero que Samuel no esté cerca...",
  ["Act_E3_1B_CampusB_JanitorDoor_Look01_Max_010"] = "Ahí está la puerta de la habitación de suministros de Samuel.",
  ["Act_E3_1B_CampusB_KateSuicideTraces_Look01_Max_010"] = "Dios, todavía no puedo creer que haya saltado…",
  ["Act_E3_1B_CampusB_KateSuicideTraces_Look02_Max_010"] = "No hay nada que pueda hacer para traerla de vuelta...",
  ["Act_E3_1B_CampusB_LD_PrinReprimandMax_RTC_VoiceOver01_Max_010"] = "¡Max la Ninja ataca de nuevo!",
  ["Act_E3_1B_CampusB_LD_PrinReprimandMax_RTC_VoiceOver02_Max_010"] = "¡Ese astuto hijo de puta me tiene atrapada!",
  ["Act_E3_1B_CampusB_LD_PrinReprimandMax_RTC_VoiceOver03_Max_010"] = "¡Ahora no tengo salida!",
  ["Act_E3_1B_CampusB_Magazine01_Look01_Max_010"] = "¿Quién hubiera creído que a Samuel le interesaba la moda?",
  ["Act_E3_1B_CampusB_Shelves_Look01_Max_010"] = "Sip, estantes. Aburrido.",
  ["Act_E3_1B_CampusB_Squirrel_Look01_Max_010"] = "Hola, amiguito, ¿quieres acompañarme?",
  ["Act_E3_1B_CampusB_Squirrel_Photo01_Max_010"] = "Mira la lente y dí \"¡nuez!\".",
  ["Act_E3_1B_CampusB_Squirrel_Photo01_Max_020"] = "¡Listo!",
  ["Act_E3_1B_CampusB_Switch_Look01_Max_010"] = "Esto nos dará la luz.",
  ["Act_E3_1B_CampusB_Toolbox_Look01_Max_010"] = "Nada más que herramientas...",
  ["Act_E3_1B_CampusB_Totem_Look01_Max_010"] = "El Tobanga se ve bastante tenebroso por la noche... No me destruyas, por favor.",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_010"] = "Blackwell se ve muy siniestro de noche...",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_020"] = "Espero que David no esté merodeando por aquí a estas horas de la noche...",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_030"] = "Por lo menos, ya no debo preocuparme por encontrarme con David...",
  ["Act_E3_1B_CampusB_VoiceOverGlobal_Max_040"] = "La verdad, que no me gustaría ver a Victoria aquí afuera tampoco...",
  ["Act_E3_1B_CampusB_VoiceOverJanitor_Max_010"] = "No deberías estar aquí, Max. Apúrate.",
  ["Act_E3_1B_CampusB_VoiceOverJanitor_Max_020"] = "Sé que Samuel es excéntrico... pero ¿hay una conexión entre él, Kate y Rachel?",
  ["Act_E3_1B_CampusB_VoiceOverObjective_Max_010"] = "Así que Chloe está esperándome frente a la sala principal.",
  ["Act_E3_1B_CampusB_VoiceOverObjective_Max_020"] = "Que no te pesquen, Max. Enciende tu modo ninja.",
  ["Act_E3_1B_CampusB_VoiceOverStealth_Max_010"] = "Director Wells... ¿En serio? Estoy frita si me ve...",
  ["Act_E3_1B_CampusB_VoiceOverStealth_Max_020"] = "Fantástico. ¿Cómo hago para pasar sin que me vea y encontrarme con Chloe?",
  ["Cue_E3_1B_CampusB_LD_PRinLoopSit_IGE_Principal_010"] = "Aquí estoy, sintiendo lástima por mí, cuando la familia de Kate Marsh está en pleno luto... Seguro que van a demandar a Blackwell por cada ladrillo que tiene. Ahora entiendo por qué los estudiantes llaman a este lugar \"Blackdel infierno\"...",
  ["Cue_E3_1B_CampusB_LD_PRinLoopSit_IGE_Principal_020"] = "Qué día... Blackwell casi pierde otra estudiante... Hubiera deseado que Kate Marsh también se hubiera ido de la ciudad... Ahora tengo que lidiar con más padres encabronados que creen tener el derecho de culparme por sus errores... Salud.",
  ["Cue_E3_1B_CampusB_LD_PRinLoop_IGE_Principal_010"] = "Sé que tengo las llaves ... en alguna parte... ¡Ah! ¡Listo! Ahora, ¿por qué no entran? ¡Estas llaves están rotas! ¿O seré yo?",
  ["Cue_E3_1B_CampusB_LD_PRinMove_IGE_Principal_010"] = "Ah, ¡a la chingada! Mi culo se queda aquí. ¡Nadie puede expulsarme! Al menos, todavía no...",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_IGE_Principal_010"] = "Max, ¡te dije que volvieras a la residencia!",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_IGE_Principal_020"] = "Max, ¡deja de dar vueltas y vuelve a la residencia!",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Max_030"] = "Lo siento, director Wells... Sigo mal por lo de Kate... Necesitaba salir a caminar y tomar un poco de aire...",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Max_050"] = "Lo siento, director Wells... Sigo temblando, pensé que Kate iba a saltar... Solo necesitaba salir a caminar y tomar un poco de aire...",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_010"] = "Srta. Caulfield, para escabullirse, debe ser mucho más sigilosa. No debería estar fuera de la residencia a estas horas. Ya lo sabe.",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_020"] = "Srta. Caulfield, para escabullirse, debe ser mucho más sigilosa. No debería estar fuera de la residencia a estas horas. Además, está suspendida.",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_040"] = "Lamento mucho que haya tenido que pasar por todo eso hoy. Hizo lo posible por ayudar, pero ¡maldita sea!... Blackwell es mi responsabilidad y yo... Le fallé a Kate y a la academia... Vamos, regrese, descanse un poco. Hoy fue un día horrible. Buenas noches, Max.",
  ["Cue_E3_1B_CampusB_LD_PrinReprimandMax_RTC_Principal_060"] = "No... no necesita explicarlo. Ver a Kate aparecer en la azotea... y luego verla bajar con usted... Le salvó la vida. Puf, hasta puede que haya salvado a Blackwell. Pero que no se le suban los humos. Vamos, vuelva a la residencia. Se ganó sueños bonitos esta noche.",
  ["Act_E3_1C_CampusA_ChloeFearsMax_VoiceOver01_Max_010"] = "Más le vale a Chloe no haberse acobardado... o peor aún, que la haya pescado David... Después de lo que le sucedió a Kate, no creo poder aguantar más malas noticias este año...",
  ["Act_E3_1C_CampusA_ChloeFearsMax_VoiceOver02_Max_010"] = "Más le vale a Chloe no haberse acobardado... o peor aún, que la haya pescado David... Parece que el universo no va a dejarme rescatar a Chloe otra vez...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_037"] = "Ah, sí, y encontrar la forma de evitar que el tornado se lleve consigo a toda Arcadia Bay... ¿verdad?",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_041"] = "El pueblo entero es un mal augurio. Y Blackwell parece estar en el ojo de la tormenta.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_042"] = "Max, no me estoy riendo de ti. Mi antiguo consejero dijo que mi sarcasmo era una \"evasión\". Por eso dejó de ser mi consejero.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_043"] = "Ah, claro, sin contar tu capacidad para, ¡ah, sí!, manipular el tiempo y el espacio. Nada del otro mundo.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_052"] = "Vamos, no te tortures de esa forma. Concentrémonos en encontrar algunas pistas, ¿de acuerdo?",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_053"] = "¿Como mi padrastro cabrón y Nathan Prescott?",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_054"] = "Era capaz de llevarse bien con todos. Incluso con las personas que odiaba.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_061"] = "Más bien, psicópatas. El oficial de seguridad de Blackwell hasta golpea a su propia hijastra...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_062"] = "Sip... Me encantaría golpear a esos dos cabrones...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_063"] = "Sip... Me encantaría golpear a esos dos cabrones... Todavía puedo sentir la mano de David en mi rostro...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_064"] = "Me vale madre la verdad, por ahora solo quiero encontrar a mi amiga... Me asusta el solo pensar dónde podría estar... ¿Piensas que está...?",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_068"] = "No tanto como yo odio siquiera pensarlo. Max, debemos encontrar a Rachel pronto. De verdad debemos hacerlo...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_069"] = "Tal vez demasiado poderoso. Max, debemos encontrar a Rachel pronto. De verdad debemos hacerlo...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_070"] = "No se iría sin mí, ¿entiendes? ¿Cada cuánto aparecen las muchachas desaparecidas? Debemos encontrar a Rachel pronto. De verdad debemos hacerlo...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Chloe_071"] = "Más bien, psicópatas. Al menos David no intenta golpear mujeres como lo hace Nathan...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_035"] = "Y averiguar quién fue el responsable de la muerte de Kate. Tenemos que evitar que esto le vuelva a suceder a alguien.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_036"] = "Y averiguar quién casi mata a Kate. Tenemos que evitar que esto le vuelva a suceder a alguien.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_038"] = "Eso espero, Chloe... pero ¿cómo? La nieve y el eclipse son malos augurios.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_039"] = "Por favor, no bromees sobre esto, Chloe. No ahora.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_040"] = "¿No mencionaste que estaba relacionado con \"la teoría del caos\"? Bueno, no veo nada de control sobre este caos...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_044"] = "Chloe, me siento mal por algunas de mis decisiones...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_046"] = "Sobre todo después de haber hecho que expulsaran a Nathan...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_047"] = "Sobre todo después de ver los resultados... y que luego sea demasiado tarde para rebobinar.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_048"] = "Sobre todo después de hacer que suspendan al bravucón de tu padrastro...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_050"] = "Sobre todo después de meter al Sr. Jefferson en ese desmadre...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_051"] = "Quiero decir, hasta fui tan idiota de hacer que me suspendieran...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_055"] = "Bueno, por un lado, hay demasiadas coincidencias entre la gente que rodeaban a Kate y a Rachel.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_056"] = "Necesitamos averiguar más sobre las personas con las que Rachel se juntaba aquí.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_057"] = "Te prometo que lo haremos. Tal como dices, es hora de buscar pistas. Ahora, dime, ¿cuál es tu secreto?",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_058"] = "Aunque no la conozca, siento que Rachel nos está llevando por el camino hacia la verdad...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_059"] = "Por supuesto. Los dos son sociópatas.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_060"] = "No solo ellos.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_065"] = "¿Muerta? Lo siento, me odio solo por haberlo dicho, Chloe.",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_066"] = "¿Viva? Tengo que pensar eso, Chloe. Su espíritu es tan poderoso aquí...",
  ["Cue_E3_1C_CampusA_CHChloeDial_MaxChloe01_Max_067"] = "¿Pasándola de lujo en Los Ángeles? Sería la mejor opción...",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_010"] = "¡BUUU AHHH!",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_020"] = "¿Lo entiendes? ¿\"Buuu ahhh\"? Como si fuese una tenebrosa fantasma punk...",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_040"] = "Yo... lo siento, Max. Yo... Ni siquiera lo pensé. Apesto.",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_060"] = "Sé que ver a Kate caer fue horrible. Ni siquiera sé cómo lidiar con eso, así que solo... me comporto como una idiota. Pero tu superpoder le pondrá fin a todo esto. Solo debemos unir los puntos.",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_080"] = "Lo siento, ¡pero que me parta un rayo si ella no sigue entre nosotros de no ser por ti!",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Chloe_100"] = "No seas tan modesta, Mujer Maravilla. Kate está viva gracias a ti. Evidentemente, dijiste lo correcto... Y tu súper poder va a salvarnos a todos. Solo debemos unir los puntos.",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_030"] = "Más bien como una imbécil insensible que me pone los pelos de punta. Chloe, hoy vi a mi amiga saltar de una azotea. No creo que sea necesario que me hagas bromas esta noche. Siempre te encabronas conmigo por no apoyarte, pero... ¿así es como me apoyas?",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_050"] = "No quiero portarme como una pendeja, pero... es que no puedo dejar de ver a Kate saltando de la azotea... Todo porque mi poder no funcionó... Sirvió para pura chingada...",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_070"] = "Más bien como una imbécil que me pone los pelos de punta... Oye, Chloe, no tuve lo que podría llamar el mejor día intentando que mi amiga no saltara de la azotea. No creo que sea necesario que me gastes bromas esta noche, ¿entiendes?",
  ["Cue_E3_1C_CampusA_ChloeFearsMax_Max_090"] = "Kate se salvó a sí misma. Ni siquiera pude usar mi poder... sentía como que me aplastaran la cabeza... Y entonces no tenía ni idea de que decir ahí arriba...",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_010"] = "Redobles, por favor... He aquí las llaves de repuesto de Blackwell. Gracias, padrastúpido.",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_030"] = "Mira la cantidad de problemas que surgen en Arcadia Bay. A este punto, ¿a quién chingados le importa? Ya estás suspendida, Max. Muéstrame el rumbo.",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_040"] = "Mira la cantidad de problemas que surgen en Arcadia Bay. A este punto, ¿a quién chingados le importa? Estamos aquí para ganar, Max. Muéstrame el rumbo...",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Chloe_060"] = "Siempre y cuando seamos compañeras en el tiempo.",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Max_020"] = "Eres lo máximo, Chloe. Pero es que no quiero que te sigas metiendo el problemas...",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Max_050"] = "Estoy tan contenta de que seamos compañeras en el crimen.",
  ["Cue_E3_1C_CampusA_ChloeShowsKeys_Max_070"] = "Arj, inserta gruñidos aquí...",
  ["Cue_E3_1C_CampusA_EnteringBuilding_Chloe_010"] = "De acuerdo, ¡qué comience la función!",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Chloe_340"] = "Por supuesto. Jefferson es un mandilón.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Chloe_360"] = "Está por llegar la hora de la verdad a Blackwell.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_020"] = "Esperemos que el resto de la clase siga tu ejemplo. Perdón, estaba distraído. Como sabes, hoy no fue un buen día para Blackwell.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_040"] = "Gracias, Victoria. Me imagino que tú también estás bastante triste por Kate...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_070"] = "Gracias, Victoria. Me alegro que al menos haya tenido un final relativamente feliz.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_090"] = "¿\"Katie\"? No tenía idea de ustedes fueran tan amigas... ¿ella lo sabía?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_110"] = "De ningún modo. El concurso se llevará a cabo según lo previsto, y voy a elegir al mejor representante de Blackwell. Tengo las fotos de todos, salvo la de Max ...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_120"] = "El concurso se llevará a cabo, solo que no voy a representar a Blackwell en el evento porque Max afirma que comparto la culpa de la condición psicológica de Kate Marsh solo porque escuché sus problemas.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_140"] = "Supongo que estarás al tanto de eso, Victoria.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_160"] = "Sí, Max es famosa por sus técnicas bravuconas. Vamos, Victoria.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_200"] = "¿Hay alguien a quien David Madsen no esté investigando?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_220"] = "Oficialmente, de licencia. Pero no me voy a poner a llorar al respecto.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_240"] = "Voy a comenzar el proceso de selección una vez que tenga la foto de Max.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_260"] = "No me tutees, Victoria. ¿Por favor? Y, eh... No he elegido un ganador todavía.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_270"] = "No me tutees, Victoria. No voy a ir a San Francisco, ¿recuerdas?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_290"] = "Voy a hacer de cuenta que no dijiste eso.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Jefferson_310"] = "Y, por el bien de tu futuro, también haré de cuenta que no escuché esa ridiculez. Esta conversación está oficialmente terminada, señorita Chase, y le aconsejo que regrese a su dormitorio ahora.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Max_330"] = "Justo cuando pensaba que Victoria no podía ser más malvada.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Max_350"] = "No me sorprende que lo llamen el club Vortex...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Max_370"] = "Vamos a investigar.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_010"] = "De nuevo, muchas gracias por ayudarme a formar mi portafolio.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_030"] = "Sé que hoy fue día horrible. Puede contar conmigo, señor Jefferson.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_050"] = "O sea, todavía estoy como estupefacta. Nunca había visto a nadie morir. Realmente quería a Katie.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_060"] = "Sé que hoy fue un día estresante; si tiene ganas de hablar al respecto, aquí estoy, Sr. Jefferson.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_080"] = "No sé qué habría hecho si Katie hubiera saltado...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_100"] = "Bueno... ¿Cómo afecta esto al concurso de Héroes Cotidianos?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_130"] = "Detesto a Max Caulfield. ¿No se da cuenta lo falsa que es con su basura de \"soy tan tímida y frágil\"? Solo quiere llamar la atención.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_150"] = "A Max la suspendieron, no a mí. Seguro que estaba troleando a Kate en la azotea...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_170"] = "Solo sé que, el otro día, Max me sacó una foto cuando Samuel derramó pintura sobre mí... ¿Por qué debería alguien confiar en ella?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_180"] = "Está bien, sé que fue amable el otro día cuando Samuel derramó pintura sobre mí... Me sorprende que no me haya tomado una foto solo para humillarme...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_190"] = "Escuché que David Madsen la está investigando...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_210"] = "Escuché que hizo que despidieran a David Madsen.",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_230"] = "¿Así que todavía no ha elegido al ganador del concurso?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_250"] = "Le voy a dar una pista de la foto de Max: selfi. Vamos, has visto mi foto, sabes muy bien que es superior. Mark, ¿no estaría chido pasar un tiempo juntos en San Francisco?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_280"] = "De por sí, le encanta mi trabajo, así que no es como si tuviera favoritos. Solo imagínese qué pasaría si escogiera mi foto... pasaríamos mucho tiempo juntos. Eso podría ser... divertido, ¿no te parece?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_300"] = "Será mejor que me elija... Si no, podría contarle a todos que me ofreció seleccionar mi foto a cambio de ciertos favorcitos o quién sabe qué...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_320"] = "Espere, solo...",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_330"] = "¿Es una chingada broma?",
  ["Cue_E3_1C_CampusA_JeffersonVictoria_Victoria_340"] = "¡Qué estupidez!",
  ["Act_E3_2A_ArtClass_ArcadiaPicture02_Look01_Max_010"] = "Nunca podrás escapar del faro aquí...",
  ["Act_E3_2A_ArtClass_CamerasCabinet_Look01_Max_010"] = "Ya has robado demasiado para una semana, Max.",
  ["Act_E3_2A_ArtClass_GroupPhoto_Look01_Max_010"] = "Eso estuvo genial, cuando la primera semana, el Sr. Jefferson tomó una foto de la clase. Aunque yo no quería estar en la foto, me pareció bastante increíble cómo intentaba que entráramos en el marco.",
  ["Act_E3_2A_ArtClass_Letter_Look01_Max_010"] = "Menciono un detalle pequeñísimo, y meto la pata con el Sr. Jefferson... Bien hecho, Max.",
  ["Act_E3_2A_ArtClass_PackOfCigarettes_Look01_Max_010"] = "¿Los cigarros de Victoria? Seguro que el Sr. Jefferson estará impresionado.",
  ["Act_E3_2A_ArtClass_StrongScotchTape_Interact01_Max_010"] = "¡La cinta es mía!",
  ["Act_E3_2A_ArtClass_StrongScotchTape_Look01_Max_010"] = "¡Es justo lo que necesito!",
  ["Act_E3_2A_Corridor_EverydayHeroPhoto1_Look01_Max_010"] = "Victoria... eso es muy bueno. ¿Cómo puedo odiar a alguien que es capaz de tomar estas fotos?",
  ["Act_E3_2A_Corridor_EverydayHeroPhoto2_Look01_Max_010"] = "Ya con ver las fotos de Nathan me dan ganas de vomitar, aunque tiene algo de estilo...",
  ["Act_E3_2A_Corridor_EverydayHeroPhoto3_Look01_Max_010"] = "Daniel es mejor dibujante que fotógrafo, según Max, la crítica de arte.",
  ["Act_E3_2A_Corridor_EverydayHeroPhoto5_Look01_Max_010"] = "Ah, Kate... hasta deprimida intentaste ver la bondad en el mundo... Mierda.",
  ["Act_E3_2A_Corridor_EverydayHeroPoster_Look01_Max_010"] = "Me hace sentir estúpida pensar en mí misma como una \"heroína cotidiana\" por haber ayudado a Kate... pero está de pelos que otras personas lo hagan. Si tan solo pudiera encontrar a Rachel...",
  ["Act_E3_2A_Corridor_EverydayHeroPoster_Look02_Max_020"] = "Si Kate estuviera viva, tal vez sí sería una \"heroína cotidiana\"... ¿Podré compensárselo si encuentro a Rachel?",
  ["Act_E3_2A_Corridor_KateLocker_Look01_Max_010"] = "Oh, Kate, tu casillero se ve tan solitario...",
  ["Act_E3_2A_Corridor_KateLocker_Look02_Max_010"] = "¡Qué bueno que aún mantengas tu casillero, Kate!",
  ["Act_E3_2A_Corridor_LadiesRoomDoor_Look01_Max_010"] = "Hace mucho tiempo, en el baño de chicas, justo aquí…",
  ["Act_E3_2A_Corridor_LadiesRoomDoor_Look02_Max_010"] = "Hace mucho tiempo... a Nathan lo molieron a golpes.",
  ["Act_E3_2A_Corridor_MPA01_Look01_Max_010"] = "¿Dónde chingados estás, Rachel Amber?",
  ["Act_E3_2A_Corridor_MPA02_Look01_Max_010"] = "Siento que nos estás guiando... pero ¿adónde?",
  ["Act_E3_2A_Corridor_MPA03_Look01_Max_010"] = "Ah, Rachel, sé que Kate y tú están conectadas por todo esto...",
  ["Act_E3_2A_Corridor_MPA04_Look01_Max_010"] = "Sí, te voy a encontrar, Rachel... por Chloe y Kate.",
  ["Act_E3_2A_Corridor_Poster05_Look01_Max_010"] = "Sí, este cartel debe dejar fríos a los bravucones.",
  ["Act_E3_2A_Corridor_Poster06_Look01_Max_010"] = "¡Alerta de nerds! ¡Este cartel tiene \"Warren\" escrito por todas partes!",
  ["Act_E3_2A_Corridor_Scripted_Max_010"] = "Chloe está esperándome frente a la oficina del director.",
  ["Act_E3_2A_Corridor_Scripted_Max_030"] = "Warren es un típico nerd. A ver si puedo encontrar esos objetos...",
  ["Act_E3_2A_Corridor_Scripted_Max_040"] = "¡Solo me faltan tres objetos!",
  ["Act_E3_2A_Corridor_Scripted_Max_050"] = "¡Ya vas por la mitad, Max!",
  ["Act_E3_2A_Corridor_Scripted_Max_060"] = "Solo falta un ingrediente...",
  ["Act_E3_2A_Corridor_Scripted_Max_070"] = "¡Esta puerta antigua no es rival para Max la Maga!",
  ["Act_E3_2A_Corridor_Scripted_Max_090"] = "Como una escena de una película de terror...",
  ["Act_E3_2A_Corridor_Scripted_Max_100"] = "Cada sonido aquí se magnifica...",
  ["Act_E3_2A_Corridor_Scripted_Max_110"] = "Probablemente debería encontrar esos objetos ahora...",
  ["Act_E3_2A_Corridor_Scripted_Max_120"] = "¿Qué fue ese sonido? Max, no te me asustes...",
  ["Act_E3_2A_Corridor_Scripted_Max_130"] = "Qué horrible, odio ese olor a formol...",
  ["Act_E3_2A_Corridor_Scripted_Max_140"] = "Tiene que haber algo que pueda utilizar aquí.",
  ["Act_E3_2A_Corridor_Scripted_Max_160"] = "Mierda, mierda, ¡haz algo, Max!",
  ["Act_E3_2A_Corridor_Scripted_Max_170"] = "Revisa en todos lados, Max, debe haber algo de información importante en los archivos de los estudiantes.",
  ["Act_E3_2A_Corridor_Scripted_Max_180"] = "Sé que ese dinero nos habría ayudado a Chloe y a mí...",
  ["Act_E3_2A_Corridor_Scripted_Max_190"] = "Me siento de la chingada por haber tomado ese dinero...",
  ["Act_E3_2A_Corridor_Scripted_Max_200"] = "Creo que ya encontramos todo aquí... Debería ir con Chloe.",
  ["Act_E3_2A_Corridor_SodaCan_Interact01_Max_010"] = "Ahora eres toda mía.",
  ["Act_E3_2A_Corridor_SodaCan_Look01_Max_010"] = "¿Puedo beber esto?",
  ["Act_E3_2A_Corridor_SodaMachine_Interact01_Max_010"] = "¡Liberen la laten!",
  ["Act_E3_2A_Corridor_SodaMachine_Look01_Max_010"] = "No soy muy fanática de los refrescos, pero ahorita tengo la garganta muy seca...",
  ["Act_E3_2A_Corridor_TrashCan04_Interact01_Max_010"] = "Y nada por aquí.",
  ["Act_E3_2A_Corridor_TrashCan07_Interact01_Max_010"] = "Asqueroso...",
  ["Act_E3_2A_Corridor_TrashCan09_Interact01_Max_010"] = "Nada. Esto es tan estúpido.",
  ["Act_E3_2A_Corridor_Trashcans_Look01_Max_010"] = "Lo acaban de vaciar, nada por aquí.",
  ["Act_E3_2A_Corridor_Trashcans_Look03_Max_010"] = "Vacío. Vamos...",
  ["Act_E3_2A_Corridor_Trashcans_Look04_Max_010"] = "Nop. ¿Nadie bebe refrescos aquí?",
  ["Act_E3_2A_Corridor_TrophyCabinet_Look01_Max_010"] = "Ningún trofeo podrá salvar la reputación de Blackwell ahora...",
  ["Act_E3_2A_Corridor_VendingMachine_Look01_Max_010"] = "Entonces puedo usar mi poder para llevarme todas las latas aquí con solo una sola moneda... Mmm. Un abanico de posibilidades. Pero no vayas hacia lado oscuro, joven Pada-Max...",
  ["Act_E3_2A_Corridor_VortexClub01_Look01_Max_010"] = "Así que uno puede dispararle a alguien un lunes y salir de fiesta un viernes... Todo un Prescott.",
  ["Act_E3_2A_Corridor_VortexClub02_Look01_Max_010"] = "Sus días de peda son cosa del pasado.",
  ["Act_E3_2A_Corridor_VortexClub03_Look01_Max_010"] = "Primero Rachel y ahora Kate... Este es el final del club Vortex.",
  ["Act_E3_2A_Corridor_VortexPoster_Look01_Max_010"] = "Puede que Kate haya comenzado una revolución...",
  ["Act_E3_2A_PrinOffice_BronzeHawk_Look01_Max_010"] = "No eres tan naco de cerca...",
  ["Act_E3_2A_PrinOffice_ChloeFile_Look01_Max_010"] = "Órale, no culpo al director por expulsar Chloe... ¡Chloe mala!",
  ["Act_E3_2A_PrinOffice_Cupboard02_Look01_Max_010"] = "Papeles...",
  ["Act_E3_2A_PrinOffice_Cupboard_Look01_Max_010"] = "No hay llaves aquí.",
  ["Act_E3_2A_PrinOffice_Desk_Look01_Max_010"] = "Sí, no hay absolutamente nada aquí.",
  ["Act_E3_2A_PrinOffice_Drawer01_Look01_Max_010"] = "Nada por aquí...",
  ["Act_E3_2A_PrinOffice_Drawer02_Look01_Max_010"] = "Callejón sin salida...",
  ["Act_E3_2A_PrinOffice_Drawer1_Look01_Max_010"] = "Desolación.",
  ["Act_E3_2A_PrinOffice_FilesCabinets_Look01_Max_010"] = "Los archivos de los estudiantes deben estar aquí...",
  ["Act_E3_2A_PrinOffice_Framing01_Look01_Max_010"] = "Parece un derrame de pintura al óleo... Horrible.",
  ["Act_E3_2A_PrinOffice_Framing02_Look01_Max_010"] = "Debería estar colgado en una tienda de segunda mano.",
  ["Act_E3_2A_PrinOffice_GrantMail_Look01_Max_010"] = "No hay manera de que David se meta con la Sra. Grant. Ella lo habría callado de inmediato.",
  ["Act_E3_2A_PrinOffice_HoldenCaulfieldHat_Look01_Max_010"] = "Solo un falso usaría ese chingado sombrero.",
  ["Act_E3_2A_PrinOffice_KeysBoard_Look01_Max_010"] = "¡Aquí están las llaves! Ninguna es de la oficina del director.",
  ["Act_E3_2A_PrinOffice_KeysBoard_Look02_Max_010"] = "No se puede usar esa.",
  ["Act_E3_2A_PrinOffice_MaxFisherHat_Look01_Max_010"] = "Me siento mal por el pobre hipster que perdió esta boina. Seguro que es lindo.",
  ["Act_E3_2A_PrinOffice_MaxStudentFiles_Interact01_Max_010"] = "Como si no fuera a leer mi propio archivo personal...",
  ["Act_E3_2A_PrinOffice_RandomFiles_Interact01_Max_010"] = "Si hubiera firmado la petición, podría haber hecho la diferencia.",
  ["Act_E3_2A_PrinOffice_RandomFiles_Interact02_Max_010"] = "Es genial que mi firma haya servido de algo... ¡Vamos, Sra. Grant!",
  ["Act_E3_2A_PrinOffice_RandomFiles_Interact03_Max_010"] = "Así que el padre de Nathan Prescott también es un bravucón... ¡Vaya sorpresa!",
  ["Act_E3_2A_PrinOffice_RandomFiles_Interact04_Max_010"] = "Supongo que ser un bravucón es parte del ADN Prescott.",
  ["Act_E3_2A_PrinOffice_RandomFiles_Interact05_Max_010"] = "Buen viaje, David.",
  ["Act_E3_2A_PrinOffice_RandomFiles_Look01_Max_010"] = "Mira este rejunte...",
  ["Act_E3_2A_PrinOffice_SamuelMail_Look01_Max_010"] = "Si las ardillas están locas por las nueces... ¿entonces Samuel está loco...? Nel.",
  ["Act_E3_2A_PrinOffice_Scripted_Max_010"] = "Solo me faltan dos archivos.",
  ["Act_E3_2A_PrinOffice_Scripted_Max_020"] = "Secuestremos este último archivo, Sherlock. Siempre quise decir \"secuestrar\".",
  ["Act_E3_2A_PrinOffice_StudentsFiles_Interact01_Max_010"] = "Rachel no parece tan \"afligida\" según todo esto... pero aquí no dice mucho sobre la investigación policial...",
  ["Act_E3_2A_PrinOffice_StudentsFiles_Interact02_Max_010"] = "¡Qué extraño! Este imbécil tiene un historial impecable.",
  ["Act_E3_2A_PrinOffice_StudentsFiles_Interact03_Max_010"] = "Esto resumen bastante bien a Kate... tímida y dulce. Y en el lugar equivocado.",
  ["Act_E3_2A_PrinOffice_StudentsFiles_Look01_Max_010"] = "¡Bingo!",
  ["Act_E3_2A_PrinOffice_SugarPowder_Interact01_Max_010"] = "Necesito una solución rápida.",
  ["Act_E3_2A_PrinOffice_SugarPowder_Look01_Max_010"] = "Uhhh, azúcar.",
  ["Act_E3_2A_PrinOffice_VictoriaStudentFiles_Interact01_Max_010"] = "Este archivo va estar tan impecable que me dan nauseas.",
  ["Act_E3_2A_PrinOffice_WarrenStudentFiles_Interact01_Max_010"] = "Tengo que asegurarme de que Warren no tenga antecedentes criminales...",
  ["Act_E3_2A_PrinOffice_WhiskyBottle_Look01_Max_010"] = "Yo también bebería si fuese directora de Blackwell.",
  ["Act_E3_2A_SciClass_Bin01_Look01_Max_010"] = "Nada por aquí.",
  ["Act_E3_2A_SciClass_Bin02_Look01_Max_010"] = "Ninguna lata aquí.",
  ["Act_E3_2A_SciClass_Bin03_Interact01_Max_010"] = "Bien, tengo la lata.",
  ["Act_E3_2A_SciClass_Blackboard_Look01_Max_010"] = "Biología de culos... puaj, ¡es asqueroso!",
  ["Act_E3_2A_SciClass_Desk2_Look01_Max_010"] = "Nunca dije que fueran lo máximo, guasón.",
  ["Act_E3_2A_SciClass_FishTank_Interact01_Max_010"] = "Gracias, peces, buen trabajo.",
  ["Act_E3_2A_SciClass_FishTank_Interact01_Max_020"] = "Ahora vuelvan a dormir.",
  ["Act_E3_2A_SciClass_FishTank_Interact02_Max_010"] = "Buenas noches, pececitos.",
  ["Act_E3_2A_SciClass_FishTank_Look01_Max_010"] = "Todos duermen... Odio despertarlos, pero quiero tomarles una foto.",
  ["Act_E3_2A_SciClass_PeriodicTable_Look01_Max_010"] = "Una tabla periódica... Si supiera el significado de \"periódica\"...",
  ["Act_E3_2A_SciClass_SciencePoster_Look01_Max_010"] = "Da Vinci sí que sabía.",
  ["Act_E3_2A_SciClass_Scripted_Max_050"] = "¡Ahora es el momento de mostrarle a Chloe que Max es lo máximo!",
  ["Act_E3_2A_SciClass_Scripted_Max_060"] = "Azúcar... Azúcar... Estamos en Oregón, carajo... ¿Dónde está la máquina de café de Blackwell para conseguir un poco de azúcar?",
  ["Act_E3_2A_SciClass_Scripted_Max_070"] = "Max, si no eres capaz de encontrar clorato de sodio en el laboratorio de ciencias... date por vencida.",
  ["Act_E3_2A_SciClass_Scripted_Max_080"] = "Encontrar una lata de refresco en la escuela no debería ser una búsqueda épica... ni un fracaso épico. Como en una máquina expendedora... ¿Podría ser?",
  ["Act_E3_2A_SciClass_Scripted_Max_090"] = "Juraría que la semana pasada usamos un poco de cinta en la clase de Jefferson...",
  ["Act_E3_2A_SciClass_Skeleton_Look01_Max_020"] = "Puaj, qué asco. Al menos, usa cigarros electrónicos. ",
  ["Act_E3_2A_SciClass_SodiumChlorate_Interact01_Max_010"] = "Sabes que eres torpe, Max, no desperdicies tu poder. ¡Usa la maldita silla!",
  ["Act_E3_2A_SciClass_SodiumChlorate_Look01_Max_010"] = "Aquí está la caja de clorato de sodio.",
  ["Act_E3_2A_SciClass_Trash_Look01_Max_010"] = "¿Adivina qué? Basura.",
  ["Act_E3_2A_SciClass_WarrenBook_Look01_Max_010"] = "Así que el clorato de sodio es... ¿un herbicida? ¿Warren no me tendría que haber dicho ese detallito?",
  ["Act_E3_2A_SciClass_WarrenTest_Interact01_Max_010"] = "Mereces mucho más que esto por enfrentarte a Nathan, pero cada nota suma...",
  ["Act_E3_2A_SciClass_WarrenTest_Look01_Max_010"] = "¿Solo una \"B-\"? Warren hizo trizas mis esperanzas. Por supuesto, yo apenas sí apruebo Ciencia.",
  ["Act_E3_2A_SciClass_WarrenTest_Look02_Max_010"] = "¿Una \"A-\"? Está bien, está bien, ¡así que la Dra. Max sí ayudó a Warren esta mañana!",
  ["Act_E3_2A_SciClass_WarrenTest_Look03_Max_010"] = "Sí, me gusta este \"más\" mejor que aquel \"menos\".| Gracias por la ayuda, Warren...",
  ["Act_E3_2A_SciClass_WrongChemicals_Look01_Max_010"] = "No, esta mezcla no funciona.",
  ["Act_E3_2A_SciClass_WrongChemicals_Look03_Max_010"] = "Eres una artista, maldita sea, no una científica. Pero esto no es para nada clorato de sodio.",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look01_Max_010"] = "Aburrido.",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look02_Max_010"] = "Mierda.",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look03_Max_010"] = "Por supuesto... que no me sirve.",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look04_Max_010"] = "Nada por aquí.",
  ["Act_E3_2A_SciClass_WrongSearchPlaces_Look05_Max_010"] = "Vaya, esto sí que será inútil.",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_005"] = "Sé que no debería hacerlo, pero revisar los archivos del director está de lujo.",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_008"] = "Como si no pudieras rebobinar y arreglarlo.",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_009"] = "Ah, sí, me duele mucho no poder ir de fiesta con el club Vortex.",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_012"] = "Lo que digas, fumada. Ya estás bien enganchada.",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_013"] = "Especialmente contigo a mi lado, ¿verdad?",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Chloe_015"] = "Ahhh, me gusta cuando te pones bien mandona. Finalmente aprendes de la maestra...",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_006"] = "Solo trata de no borrar su disco duro ni nada por el estilo.",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_007"] = "Esta es tu oportunidad de vengarte de Blackwell...",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_010"] = "No quiero que se vuelva un hábito, ¿sabes?",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_011"] = "Todavía queda tiempo...",
  ["Cue_E3_2A_Corridor_CHChloe_PrinChair01_Max_014"] = "No hables. Busca.",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase01_Chloe_001"] = "Chingado güey, no te apures, ¿eh? total yo estoy parada aquí como una delincuente.",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase02_Chloe_001"] = "Está bien, Max, hora de encontrar algunos archivos secretos, y espero que tengan información bien jugosa.",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase03a_Chloe_001"] = "Está bien, Max, nada de dinero para Chloe. Seguro que Frank lo entenderá antes de que me mate. ¿Feliz?",
  ["Cue_E3_2A_Corridor_CHChloe_QPhase03b_Chloe_001"] = "Max, gracias por dejar que me quede con este dinero. Ahora pelemos...",
  ["Cue_E3_2A_Corridor_ChloeDoesntTakeMoney_Chloe_020"] = "Este fajo de lana nos abre mil puertas y posibilidades... pero sí, Max la Moral está en lo correcto. Supongo... Salgamos de una vez de esta oficina que huele a morgue.",
  ["Cue_E3_2A_Corridor_ChloeDoesntTakeMoney_Max_010"] = "¿En serio quieres robar del fondo de discapacitados? Sé que le debes lana a Frank, pero... Tengo mi poder como para protegerte, ¿no?",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_020"] = "Bueno, ¿qué tenemos aquí?",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_030"] = "A la mierda, ¡Bingo! ¡Cachín!",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_050"] = "Oye, hay cinco mil dólares aquí. ¡Con esto le podría pagar Frank esta misma noche! Esto seguro lo calma luego de que tú, ya sabes, le dispararas.",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_060"] = "Oye, hay cinco mil dólares aquí. Le podría pagar Frank esta misma noche... Esto seguro lo calma luego de la batalla de cuchillos de ayer.",
  ["Cue_E3_2A_Corridor_ChloeMoney_Chloe_070"] = "¿Vas a hacer todo un pedo por esto? ¿O vas a rebobinar y quedarte con la lana? Espero que hagas eso, en lugar de regañarme.",
  ["Cue_E3_2A_Corridor_ChloeMoney_Max_010"] = "Definitivamente debemos irnos de aquí. Nos arriesgamos demasiado.",
  ["Cue_E3_2A_Corridor_ChloeMoney_Max_040"] = "Vaya, es mucho dinero para un \"fondo de discapacitados\"",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Chloe_020"] = "Eres SuperMax.",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Chloe_030"] = "Y, con lo que sobre, haremos una escapada a Portland por el día. Y nos retacaremos de tatuajes, cerveza, hierba y donas.",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Chloe_050"] = "Y estripers... ¡Solo bromeo! Pero nunca se sabe...",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Max_010"] = "Frank sabe cosas de Rachel y, si le pagamos, quizás las cuente... ¿No?",
  ["Cue_E3_2A_Corridor_ChloeTakesMoney_Max_040"] = "Y libros de la librería Powell's.",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_020"] = "¿Qué te parece una zambullida nocturna? La alberca de Blackwell es toda nuestra.",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_040"] = "Ha sido una semana bastante loquita, nos merecemos un poco de diversión en el agua... Terminamos por la noche, somos ricas, y nadie nos pescó. Y, ¿te aguantas unas salpicadas?",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_045"] = "Ha sido una semana particular.",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_050"] = "No me dejaste llevarme el dinero para saldar mi deuda con Frank. Si van a encontrar mi cuerpo tirado al costado de la carretera, me gustaría un poco de diversión despreocupada al menos durante unos minutos... ¿Te aguantas unas salpicadas?",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Chloe_070"] = "¿Acabas de decir \"con madre\"? Creo que soy una buena mala influencia.",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Max_010"] = "Esa mirada pícara me asusta.",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Max_030"] = "¿Nadar? ¿Quieres correr ese riesgo ahora?",
  ["Cue_E3_2A_Corridor_ExitPrincipalOffice_Max_060"] = "Tienes razón, estaría con madre. ¡Salpicadas!",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_020"] = "Exactamente.",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_040"] = "Ni hablar de la hierba que trajiste a mi habitación... ¡Es broma!",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_050"] = "Siempre puedes dejar que me pesquen como lo hiciste con la hierba.",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_070"] = "No es una entrada forzada si tengo una llave. ¡No nos pueden acusar solo por la entrada!",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_090"] = "No si soy pariente del jefe de seguridad de Blackwell. El pendejo de mi padrastro no querrá que me agarre la Policía... Así que averigüemos qué esconde el director en su oficina. Puedes rebobinar si nos cachan, ¿verdad? Tu poder está con madre, Max.",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_100"] = "No si el ex jefe de seguridad de Blackwell está en casa llorando en su búnker... Así que primero averigüemos qué esconde el director en su oficina. Puedes rebobinar si nos cachan, ¿verdad? Tu poder está con madre, Max.",
  ["Cue_E3_2A_Corridor_Insertion_Chloe_130"] = "Vamos. Una puerta más y nuestro trabajo aquí está listo.",
  ["Cue_E3_2A_Corridor_Insertion_Max_010"] = "Eres buena cerrajera, Chloe.",
  ["Cue_E3_2A_Corridor_Insertion_Max_030"] = "Güey, no estoy segura de esto... ya ambas estamos metidas en tantos problemas ...",
  ["Cue_E3_2A_Corridor_Insertion_Max_060"] = "Lo digo en serio. Ya no somos niñas. Esto es entrada forzada...",
  ["Cue_E3_2A_Corridor_Insertion_Max_080"] = "Lo digo en serio. Podríamos ir a la cárcel...",
  ["Cue_E3_2A_Corridor_Insertion_Max_110"] = "Díselo a Kate...",
  ["Cue_E3_2A_Corridor_Insertion_Max_120"] = "Pero mis poderes no salvaron a Kate... Tal vez lo hice por mi cuenta...",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Chloe_100"] = "¡Esto es horrible! ¡Pinche puerta!",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Chloe_120"] = "Perdón, Max, no se me ocurre nada. ¿Y tu plan?",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Chloe_140"] = "Quizás te gane al otro lado de la puerta, Lupin.",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_010"] = "Oye, Warren, ¿estás ocupado?",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_012"] = "Usa una burbuja petrificada, vas a estar bien. Escucha, necesito de tu conocimiento de física. Ya. Hipotéticamente, si alguien tuviera acceso a los laboratorios de arte y ciencia, y deseara construir un dispositivo que, digamos, pudiera abrir una puerta cerrada con llave, ¿sabrías cómo hacerlo?",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_014"] = "¿Eh? ¡No! Es solo por curiosidad.",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_016"] = "Gracias, te mereces un Nobel. Ah, n-no no, quédate. Te necesitamos como refuerzo. Solo envíanos las instrucciones por texto ahora.",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_020"] = "Sí, todavía sigue en pie lo del autocinema... Gracias por la ayuda.",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_030"] = "Lo siento, no tengo muchas ganas de ver una película esta noche. No me odies. Y gracias por la ayuda.",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_110"] = "Intenta no despertar a todo Blackwell.",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_130"] = "Voy a buscar todo esto. ¿Será posible que te deje aquí sin que te pesquen?",
  ["Cue_E3_2A_Corridor_MaxCallWarren_Max_150"] = "Empieza la carrera. Nos vemos pronto.",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_010"] = "Si logro que esta chingadera se abra, no va a poder hacer trampa y rebobinar...",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_020"] = "¡Ah, mierda! ¡Vete a la chingada, pinche puerta!",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_040"] = "Eres magistral. No tengo ni idea de cómo diablos llegaste ahí, pero lo hiciste, ¡maravilloso!",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_060"] = "Vaya, ahora entiendo por qué el director cierra con llave la oficina. Pedazo de basura ostentosa. Debe querer que todo el mundo sepa que tiene dinero. Pero le falta el gusto.",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_070"] = "¿Cómo confiar en alguien que tiene un pinche pájaro de bronce en su despacho? ¡Qué suerte que me hayan expulsado!",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_090"] = "Sóplamela. Decidí que voy a llevarme los documentos sobre este pinche escritorio.",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_130"] = "Bueno, claro, ¡es horrible, pero que me parta un rayo, ¡es tan cómoda!",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Chloe_150"] = "Esta es la oportunidad perfecta de poner en práctica tus conocimientos deductivos, joven Sherlock. Encuentra algunas pistas sobre Rachel... o Kate... o Nathan... o quien sea.",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_030"] = "Bienvenida a mi humilde morada.",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_050"] = "Yo me entiendo. Es momento de buscar lo que necesitamos y pelarnos. Mis poderes tienen sus límites.",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_080"] = "Claro, si el director tuviese un Monet o un Picasso, aún estarías en Blackwell.",
  ["Cue_E3_2A_Corridor_MaxOpensDoor_Max_160"] = "Yo me encargo.",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_040"] = "¡Sí! ¡Es hora de explotar todo!",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_060"] = "Es tan chido...",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_080"] = "¡Eso fue espectacular!",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Chloe_100"] = "Ah... ¿Qué deberíamos hacer?",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_020"] = "No te descargues con la puerta, Chloe. Mejor probemos esto.",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_030"] = "¡Bum! Literalmente.",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_050"] = "Si enciendes la vela...",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_070"] = "Prepárate para desaparecer al instante.",
  ["Cue_E3_2A_Corridor_MaxPlantsBomb_Max_090"] = "Ah, estamos fritas. ¡Aquí vienen los departamentos de bomberos y policías de Arcadia Bay!",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_010"] = "Listo.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_015"] = "¿Qué carajo...? El oficial de seguridad debería tener la llave de la oficina del director.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_030"] = "Bueno, ahora definitivamente debemos abrir esta puerta. Lo creas o no, aprendí algo sobre forzar cerraduras, gracias a Frank. De paso, podría probar mis habilidades delictivas...",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_050"] = "Bueno, podrías buscar la llave... por si acaso.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Chloe_080"] = "Supongo que no pasé suficiente tiempo con Frank. Pero puedo usar mi técnica de forzar cerraduras de hágalo usted mismo mientras piensas un plan mejor.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_020"] = "Está ocultando chingaderas. Como todos aquí.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_040"] = "Probemos. Ya estamos hasta el cuello.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_060"] = "Pues sí, podría.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_070"] = "La llave no está aquí... Debemos encontrar otra forma de entrar.",
  ["Cue_E3_2A_Corridor_PrincipalLocked_Max_090"] = "Mi plan tiene nombre...",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_010"] = "Max, mejor ven a ver estos archivos...",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_040"] = "¿Nathan acusó a Rachel de meter drogas en el campus? Y mi padrastúpido le creyó porque, según él, Rachel era mala influencia para mí. Idiotas.",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_060"] = "\"Nathan Prescott III\". Es obvio que los Prescott desembolsaron un chingo de lana para enmascarar al verdadero Nathan... Mira, digno de un rapero: malas notas, quejas de sus profesores, periodo de prueba secreto... ¿Y a mí me expulsaron?",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_090"] = "Es solo un dibujo bastante retorcido...",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_110"] = "Qué espeluznante. ¿Qué significa? Deberían internar a Nathan en un psiquiátrico. Seguro que tiene algo que ver con la desaparición de Rachel…",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_130"] = "No, parece que formaron un dúo dinámico bizarro.",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_150"] = "Ahora sí que debemos revisar los archivos escondidos del garage... Además, me estoy poniendo un poco paranoica aquí. Pelémonos. Pero no sin llevarnos algún souvenir...",
  ["Cue_E3_2A_Corridor_RachelFile_Chloe_180"] = "Max, ¿también puedes leer la mente? ¿O rebobinaste porque intenté robar la silla? Mierda, estoy confundida.",
  ["Cue_E3_2A_Corridor_RachelFile_Max_050"] = "Si David está uniendo fuerzas con Nathan Prescott... Es un mal augurio.",
  ["Cue_E3_2A_Corridor_RachelFile_Max_070"] = "Por lo menos, por fin suspendieron a Nathan. Échale un vistazo a esa nota... Ábrela.",
  ["Cue_E3_2A_Corridor_RachelFile_Max_080"] = "Los Prescott siempre recuperan su inversión... Échale un vistazo a esa nota. Ábrela.",
  ["Cue_E3_2A_Corridor_RachelFile_Max_100"] = "No es un dibujo... Mira: \"Rachel en el cuarto oscuro... Rachel en el cuarto oscuro...\". Una y otra vez. Solo eso.",
  ["Cue_E3_2A_Corridor_RachelFile_Max_120"] = "Vaya, escucha esto: \"David M. siempre me pregunta qué estoy pensando... David M. me ayuda a seguir a los que él sigue...\". Qué críptico.",
  ["Cue_E3_2A_Corridor_RachelFile_Max_140"] = "Dios, David acechaba a Kate, a mí me fastidiaba, y ahora sabemos que también se metía con Rachel...",
  ["Cue_E3_2A_Corridor_RachelFile_Max_170"] = "No, esa silla tan cómoda no será tuya.",
  ["Cue_E3_2A_Corridor_RachelFile_Max_190"] = "Son los beneficios de las mejores amigas. Ya veo cómo eres...",
  ["Cue_E3_2A_PrinOffice_ChloeCallsOut_Chloe_010"] = "¡Max! ¡Ya has visto el maldito pasillo! ¡Ahora ven aquí a ver algo nuevo!",
  ["Cue_E3_2A_PrinOffice_ChloeCallsOut_Chloe_020"] = "Sí, Max, ¡solo camina por el pasillo como una sonámbula! ¡Olvídate de la oficina del director!",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_020"] = "Por favor, llavecitas...",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_030"] = "Me estás jodiendo.",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_040"] = "Nada de nada...",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_050"] = "Claramente esto es \"La venganza del padrastúpido 2: la revancha\".",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_060"] = "Estoy lista para patear esta puerta a la mierda.",
  ["Cue_E3_2A_PrinOffice_ChloeKeys_Chloe_100"] = "¡Cuanto antes mejor, Max! ¡Avísame, o doro mota mientras espero!",
  ["Cue_E3_2A_PrinOffice_Computer_Chloe_040"] = "Vaya, sé que ocultas cosas...",
  ["Cue_E3_2A_PrinOffice_Computer_Chloe_050"] = "Tiene que haber un archivo supersecreto...",
  ["Cue_E3_2A_PrinOffice_Computer_Chloe_070"] = "Incluso el cesto de la basura está vacío...",
  ["Cue_E3_2A_PrinOffice_ScarfaceReference_Chloe_020"] = "\"¡Díganle buenas noches al malo!\".",
  ["Cue_E3_2A_PrinOffice_ScarfaceReference_Max_010"] = "Chloe... \"¡Saluden a mi pequeña amiga!\".",
  ["Act_E3_3A_SwimPool_CHChloe_Look01_Max_010"] = "Chloe no va a esperar mucho a que encienda las luces.",
  ["Act_E3_3A_SwimPool_CHChloe_Look02_Max_010"] = "Chloe fue incapaz de esperar para zambullirse en la alberca.",
  ["Act_E3_3A_SwimPool_CHChloe_Look03_Max_010"] = "Mierda, Chloe se está escondiendo allí. Ahora tengo que encontrar otro lugar...",
  ["Act_E3_3A_SwimPool_Drawer01_Look01_Max_010"] = "Sí, lo entendemos. Nutrias.",
  ["Act_E3_3A_SwimPool_Flippers_Look01_Max_010"] = "¿Aletas en una alberca? ¿Acaso están entrenando a buceadores de la Marina aquí?",
  ["Act_E3_3A_SwimPool_FloatingDummy_Look01_Max_010"] = "Ni sueñes con que te voy a seducir.",
  ["Act_E3_3A_SwimPool_Floats_Look01_Max_010"] = "Eso debe ser para enseñar a niños.",
  ["Act_E3_3A_SwimPool_Graffiti01_Look01_Max_010"] = "El ingenio, ¡duele... tanto!",
  ["Act_E3_3A_SwimPool_Graffiti02_Look01_Max_010"] = "Eso espero, amigo...",
  ["Act_E3_3A_SwimPool_Graffiti03_Look01_Max_010"] = "La gente mala apesta.",
  ["Act_E3_3A_SwimPool_Graffiti04_Look01_Max_010"] = "A veces...",
  ["Act_E3_3A_SwimPool_Graffiti05_Look01_Max_010"] = "Bueno, a nosotros nos importa, imbécil.",
  ["Act_E3_3A_SwimPool_Graffiti05_Look02_Max_010"] = "Un milagro que salvara a Kate hubiera sido lindo...",
  ["Act_E3_3A_SwimPool_Graffiti06_Look01_Max_010"] = "No es que le guste la atención o nada parecido.",
  ["Act_E3_3A_SwimPool_Graffiti07_Look01_Max_010"] = "Apuesto que lo haces...",
  ["Act_E3_3A_SwimPool_Graffiti08_Look01_Max_010"] = "El vestuario de los chicos, pues claro…",
  ["Act_E3_3A_SwimPool_Graffiti09_Look01_Max_010"] = "Ay, es bueno saber que Victoria ama algo que no sea ella misma.",
  ["Act_E3_3A_SwimPool_Graffiti10_Look01_Max_010"] = "Amigos serán los amigos.",
  ["Act_E3_3A_SwimPool_Graffiti11_Look01_Max_010"] = "Bienvenidos a 1950.",
  ["Act_E3_3A_SwimPool_Jacket_Look01_Max_010"] = "Supongo que alguien olvidó su espíritu estudiantil de Blackwell.",
  ["Act_E3_3A_SwimPool_LightControlCabinet_Look01_Max_010"] = "Ahora tengo el poder sobre la luz y la muerte.",
  ["Act_E3_3A_SwimPool_MessageBoard01_Look01_Max_010"] = "Si tan solo pudiera resolver \"El misterio de las fotos del gato\".",
  ["Act_E3_3A_SwimPool_MessageBoard03_Look01_Max_010"] = "La verdad, no tengo tiempo de investigar a este bandido...",
  ["Act_E3_3A_SwimPool_Mirror02_Interact01_Max_010"] = "Qué tal, preciosa... Sí, claro, Max. Solo te ves como una fisgona…",
  ["Act_E3_3A_SwimPool_Mirror02_Interact01_Max_020"] = "Max Caulfield, vengadora moral. O mosca muerta hipócrita...",
  ["Act_E3_3A_SwimPool_MiscObject01_Look01_Max_010"] = "Parece que Brooke tiene ganas de ir al autocinema con Warren...",
  ["Act_E3_3A_SwimPool_MiscObject03_Look01_Max_010"] = "¿Un pasaje de autobús? ¿Iba a huir? ¿Como Rachel Amber?",
  ["Act_E3_3A_SwimPool_MiscObject04_Look01_Max_010"] = "Así que el secreto de Victoria son... las selfis. \"A la mierda con tu...\". No, Jefferson dijo que \"no confundamos el arte con el artista\". Estas fotos son bastante geniales.",
  ["Act_E3_3A_SwimPool_MiscObject06_Look01_Max_010"] = "Está bien que Nathan tome estos medicamentos, ¿no?",
  ["Act_E3_3A_SwimPool_MiscObject08_Look01_Max_010"] = "Supongo que podría tomarlo con un progreso.",
  ["Act_E3_3A_SwimPool_MiscObject11_Look01_Max_010"] = "Ay, mira la calabaza bebé de Halloween...",
  ["Act_E3_3A_SwimPool_MiscObject12_Look01_Max_010"] = "¿Chloe estuvo aquí?",
  ["Act_E3_3A_SwimPool_MiscObject13_Look01_Max_010"] = "¿Dónde desaparece el otro calcetín?",
  ["Act_E3_3A_SwimPool_MiscObject14_Look01_Max_010"] = "Lo siento, Rachel...",
  ["Act_E3_3A_SwimPool_MiscObject16_Look01_Max_010"] = "Un pobre hipster perdió su vapeador...",
  ["Act_E3_3A_SwimPool_MiscObject17_Look01_Max_010"] = "Por ninguna razón voy a tocar la camiseta de Zach...",
  ["Act_E3_3A_SwimPool_MiscObject18_Look01_Max_010"] = "Justo cuando pensaba que iba a estar a salvo si volvía al agua...",
  ["Act_E3_3A_SwimPool_MiscObject19_Look01_Max_010"] = "Café y natación. Buen combo.",
  ["Act_E3_3A_SwimPool_Necklace_Look01_Max_010"] = "Solo Victoria es capaz de tener joyas caras en su casillero.",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_010"] = "Chloe está tan mentalizada en su \"noche de mujeres\" que mejor obedezco su plan diabólico.",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_020"] = "Sí, necesito ver a Chloe, pero primero le doy un pequeño vistazo al vestidor de hombres.",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_030"] = "Sé que Chloe me está esperando, pero no puedo resistirme a echar un vistazo al vestidor de mujeres.",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_040"] = "Tiene que haber algún panel de control para las luces por aquí...",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_050"] = "¡Ahora o nunca, Max!",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_060"] = "¡Debemos irnos ahora!",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_070"] = "¡Muévete, Max, no desperdicies tu poder en que nos atrapen!",
  ["Act_E3_3A_SwimPool_ObjectiveLines_VoiceOver01_Max_080"] = "Podría usar mi poder... o solo buscar un escondite. O ambos.",
  ["Act_E3_3A_SwimPool_ObjectivesBoard_Look01_Max_010"] = "Entonces, el plan detallado es... \"Ganar\".",
  ["Act_E3_3A_SwimPool_OxygenKit_Look01_Max_010"] = "En caso de que me quede sin aire, ya sé adónde ir.",
  ["Act_E3_3A_SwimPool_Phone_Interact01_Max_010"] = "¡Demasiada de información! Ya tengo demasiadas visiones horribles...",
  ["Act_E3_3A_SwimPool_Phone_Look01_Max_010"] = "Zach es muy descuidado. ¿No sabe lo que sucede cuando estoy cerca?",
  ["Act_E3_3A_SwimPool_Picture01_Look01_Max_010"] = "Apuesto a que la reveló en la clase de Jefferson…, pero ¿por qué?",
  ["Act_E3_3A_SwimPool_PoolGlasses_Look01_Max_010"] = "Uhhh, estas gafas sí que son lujosas.",
  ["Act_E3_3A_SwimPool_PoolGlasses_Look02_Max_010"] = "¡Ta tán! \"El caso de las gafas perdidas\" está resuelto. Pero estoy muy ocupada ahora.",
  ["Act_E3_3A_SwimPool_Poster02_Look01_Max_010"] = "Espero que las Nutrias sobrevivan.",
  ["Act_E3_3A_SwimPool_Poster03_Look01_Max_010"] = "Si pudiera rebobinar a la década de los cuarenta, me metería en graves problemas.",
  ["Act_E3_3A_SwimPool_RescueBoard_Look01_Max_010"] = "Creo que nadie jamás se ahogó aquí... Eso espero.",
  ["Act_E3_3A_SwimPool_Scripted_Max_010"] = "Bueno, si vuelvo por allí, no cabe duda de que el guardia me pillará.",
  ["Act_E3_3A_SwimPool_SoapDispenser02_Look01_Max_010"] = "Este está casi vacío. A los muchachos les debe gustar el moco rosa.",
  ["Act_E3_3A_SwimPool_SoapDispenser_Look01_Max_010"] = "Puaj, moco rosa. Ahora entiendo por qué todas traen su propio jabón.",
  ["Act_E3_3A_SwimPool_TShirts_Look01_Max_010"] = "Camisetas con mucho hongo... ¡qué asco!",
  ["Act_E3_3A_SwimPool_Towels_Look01_Max_010"] = "Esas deben ser las toallas más cómodas y suavecitas en la historia de las toallas. ¡Las quiero!",
  ["Act_E3_3A_SwimPool_Trophies_Look01_Max_010"] = "Vamos, Nutrias.",
  ["Act_E3_3A_SwimPool_VendingMachine_Look01_Max_010"] = "Me encantaría un refresco, pero me pondría nerviosa.",
  ["Act_E3_3A_SwimPool_VortexClubPartyList_Interact01_Max_010"] = "Ah, lo que daría por una foto de su expresión cuando vean mi nombre ahí...",
  ["Act_E3_3A_SwimPool_VortexClubPartyList_Interact02_Max_010"] = "Ah, lo siento, no están en la lista... Así que váyanse a la mierda.",
  ["Act_E3_3A_SwimPool_VortexClubPartyList_Look01_Max_010"] = "Me siento como el sacaborrachos del Vortex club... Decisiones, decisiones...",
  ["Cue_E3_3A_SwimPool_CHChloe_ChooseSide_Max_002"] = "Chicas, ¡por supuesto!",
  ["Cue_E3_3A_SwimPool_CHChloe_ChooseSide_Max_003"] = "Chicos, ¡por supuesto!",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_001"] = "No tropezaste cuando me salvaste, Max.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_005"] = "Así que es hora de empezar a avanzar en el tiempo. Y, obviamente, estamos conectadas: sin mí, nunca habrías descubierto tu poder, ¿no?",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_011"] = "Y me haces sentir como que tengo una razón para quedarme un tiempo en Arcadia Bay.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_012"] = "Bueno, yo sí. ¿Entiendes? Así que limítate a escuchar a la capitana Chloe.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_013"] = "Y deja de actuar con tanta chingada humildad. Eres como la persona más inteligente y talentosa que he conocido.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_015"] = "Mira, no soy su grupi, ¿de acuerdo? Y seguro que los chicos se babean por ti en todo Blackwell, como Warren...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_016"] = "No estés tan triste. Nunca te voy a dejar...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_023"] = "¿Agradable? Ay. Directo a la \"Friendzone\".",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_024"] = "No acabas de decir eso. Además, los nacos de Arcadia Bay no son mi tipo.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_025"] = "Ah, los nerds tienen su atractivo. Te falta tener más confianza en ti misma, nada más.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Chloe_026"] = "No te preocupes. Cuando bajes de tu nube, el mundo entero comerá de tu mano.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_002"] = "Gracias a Dios. Pero... ¿y si lo hubiera hecho? ¿Y si...? Tanto Kate como tú estarían muertas...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_003"] = "Gracias a Dios. Pero... ¿y si lo hubiera hecho? ¿Y si...? Kate no saltó, pero tu estarías... muerta...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_004"] = "No esa vez. Pero, si no hubieras estado allí, mi poder nunca hubiera aparecido...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_007"] = "Absolutamente. Me haces sentir como si en realidad supiera qué estoy haciendo.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_008"] = "No lo sé...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_009"] = "Eso espero...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_010"] = "Lo intento. Siempre y cuando no desperdiciemos este poder...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_014"] = "¿Más que Rachel Amber?",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_017"] = "Warren es agradable...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_018"] = "Eres la mujer fatal. Los tatuajes, la actitud...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_019"] = "¡Puaj! No quiero a ningún güey de Blackwell sobre mí. Algunos güeyes sí están guapos por aquí, pero de seguro piensan que soy demasiado nerd.",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_020"] = "No, realmente es buena onda. Fue tan dulce cuando se enfrentó a Nathan... Pero nunca le conté de mi poder de rebobinar...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_021"] = "No te culpo... En fin, tenemos asuntos más importantes que atender, ¿no?",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_022"] = "Por desgracia, no vino en combo con mi poder de rebobinar...",
  ["Cue_E3_3A_SwimPool_CHChloe_Phase01_Max_027"] = "Mientras estés a mi lado...",
  ["Cue_E3_3A_SwimPool_CHChloe_QuickPhase01_Chloe_001"] = "Hola, ¡aún espero la luz!",
  ["Cue_E3_3A_SwimPool_CHChloe_QuickPhase02_Chloe_001"] = "¡Max, no hay espacio, güey! ¡Busca otro lugar para esconderte!",
  ["Cue_E3_3A_SwimPool_CHChloe_QuickPhase03_Chloe_001"] = "Max, vistámonos y dejemos de este lugar.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_010"] = "¡Así es, bebé! ¡Se siente como un jacuzzi! ¡Y ahora, con mi reserva de dinero, soy la reina del mundo! ¡Inclínate ante mí!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_020"] = "¡Así es, bebé! ¡Se siente como un jacuzzi! Lástima que me hiciste sentir como la reina de los pendejos solo porque quería ese montón de dinero...",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_025"] = "Toooon ton, tooooon ton, ton ton ton ton ton ton...",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_030"] = "Dime que no vas a quedarte ahí mirándome como una pendeja.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_070"] = "¡Ven a detenerme, hippie!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_100"] = "Mira, ¡una nutria en el agua!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_130"] = "¡Tramposa!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_150"] = "Desearía que Rachel estuviera aquí. Le encantaría estar aquí de noche. Me encantaría que se hubieran conocido...",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_190"] = "Tu poder está cambiando todo, Max. Especialmente a ti. Ya me di cuenta. Ya no eres tan rajona.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_210"] = "Sabes lo que quise decir. Te estás convirtiendo en algo como una fuerza de la naturaleza.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Chloe_240"] = "Porque estamos hablando sin sentido, en vez de atacarnos como nutrias contra tiburones... Creo que ya tuve mi cuota de alberca por el año, mejor pelémonos.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_060"] = "Ni te atrevas...",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_080"] = "Oye, ¡tú lo pediste!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_090"] = "¡Cowabunga!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_110"] = "Eres tan obvia. Y todavía me asusta esa película, así que basta. Ya ni puedo ver los programas con tiburones.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_120"] = "Rebobinaré y te clavaré un arpón. ¡La venganza de las nutrias!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_140"] = "Sí, ¡mira quién habla!",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_160"] = "Nos vamos a conocer. Con todo lo que está sucediendo, comienzo a creer que todo está conectado...",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_170"] = "Y quiero descubrir por qué, por el bien de Kate. No se merecía morir...",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_180"] = "Y quiero descubrir la verdad, por el bien de Kate. Casi se muere hoy...",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_200"] = "Gracias, nena.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_220"] = "Más como una coincidencia de la naturaleza. Vamos, mi poderes no me ayudaron a rescatar a Kate... Y si estoy tropezando en el tiempo... ¿por alguna razón?",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_230"] = "Me está dando frío ahora.",
  ["Cue_E3_3A_SwimPool_ChloeDiveIntoPool_Max_250"] = "Digamos que fue un empate. Me voy a poner chinita cuando salga...",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Chloe_020"] = "Te ves linda con el pelo empapado en químicos.",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Chloe_070"] = "¡Escóndete!",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Max_010"] = "Puaj, me siento como si hubiéramos nadado en la alberca municipal, mitad cloro mitad agua.",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Max_030"] = "Gracias, voz de la experiencia.",
  ["Cue_E3_3A_SwimPool_GuardsArrive_Max_060"] = "¡Escóndete!",
  ["Cue_E3_3A_SwimPool_GuardsArrive_SecurityGuard1_040"] = "Más vale que no se les ocurra jugarme una broma de Halloween después de lo de hoy... Lo digo en serio.",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_010"] = "¿Hola?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_020"] = "¿Dónde están?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_030"] = "¡Escuché un ruido por aquí!",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_040"] = "¿Hola?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_050"] = "¿Quién está aquí?",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_060"] = "¡Tengo una linterna y una macana!",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_070"] = "¡¿Hay alguien ahí?!",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard1_080"] = "¡Ey!",
  ["Cue_E3_3A_SwimPool_GuardsPatrol_SecurityGuard3_010"] = "¡Asegúrate de cubrir todo el perímetro!",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_020"] = "¡Gran cosa! ¡Quiero meterme al agua bien calentita!",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_050"] = "Una vez que domines tu poder de rebobinar, serás la dueña de este cuchitril...",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_060"] = "¿Chicos o chicas?",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_070"] = "Obvio. Pervertida.",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_080"] = "¿Chicas? Oh la la...",
  ["Cue_E3_3A_SwimPool_Insertion_Chloe_090"] = "Déjame comprobar si el agua está caliente...",
  ["Cue_E3_3A_SwimPool_Insertion_Max_010"] = "¡Estamos en la guarida de las Nutrias!",
  ["Cue_E3_3A_SwimPool_Insertion_Max_030"] = "Todavía debemos ser precavidas, ¿de acuerdo? Aunque ya esté suspendida.",
  ["Cue_E3_3A_SwimPool_Insertion_Max_040"] = "Todavía debemos ser precavidas, ¿de acuerdo? Todavía sigo en esta escuela.",
  ["Cue_E3_3A_SwimPool_MaxLocker_Chloe_020"] = "¡Huyamos!",
  ["Cue_E3_3A_SwimPool_MaxLocker_Max_010"] = "¡Somos tan invisibles!",
  ["Cue_E3_3A_SwimPool_MaxOpenDoorFromInside_Chloe_020"] = "Vamos, ¡ya no es gracioso! ¡Intenta renovar tu repertorio!",
  ["Cue_E3_3A_SwimPool_MaxOpenDoorFromInside_Max_010"] = "¡Presto!",
  ["Cue_E3_3A_SwimPool_OpensMainDoor_Chloe_030"] = "Vamos, ¡escóndete! ¡Como cuando éramos niñas!",
  ["Cue_E3_3A_SwimPool_OpensMainDoor_David_010"] = "¡Asegúrate de cubrir todo el perímetro!",
  ["Cue_E3_3A_SwimPool_OpensMainDoor_Max_020"] = "¡No jodas!",
  ["Cue_E3_3A_SwimPool_Pool_Chloe_Chloe_010"] = "Max, trata de encontrar las luces de la alberca. ¡Quiero ver a los tiburones!",
  ["Cue_E3_3A_SwimPool_Pool_Chloe_Chloe_030"] = "Y yo también... ¡Prende esa luz!",
  ["Cue_E3_3A_SwimPool_Pool_Chloe_Max_020"] = "A las nutrias no les gustan los tiburones. Muerden.",
  ["Cue_E3_3B_CampusPark_ExitGirls_Chloe_020"] = "¡Ah, son chingaderas!",
  ["Cue_E3_3B_CampusPark_ExitGirls_Chloe_040"] = "¡A la mierda con esos chicos!",
  ["Cue_E3_3B_CampusPark_ExitGirls_Max_010"] = "Espera, date la vuelta, ¡están viniendo!",
  ["Cue_E3_3B_CampusPark_ExitGirls_Max_030"] = "¡Regresa!",
  ["Cue_E3_3B_CampusPark_ExitGirls_Max_050"] = "¡Tenemos que encontrar otra salida!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_010"] = "No puedes volver a la residencia ahora, ¡eres una fugitiva! Quédate en mi casa esta noche.",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_040"] = "¡Vamos al carro!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_050"] = "Ayúdame empujar al bebe y salgamos de aquí...",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_060"] = "¡Ahora!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_070"] = "¡Entra!",
  ["Cue_E3_3B_CampusPark_GetAway_Chloe_080"] = "¡Jajaja! ¡Hasta la vista, pendejos! Max, ¡eres lo máximo! ¡Somos tan increíbles, carajo!",
  ["Cue_E3_3B_CampusPark_GetAway_Max_020"] = "¿Quieres que me quede donde vive el oficial de seguridad Blackwell para que esté a salvo? ¡Está bien!",
  ["Cue_E3_3B_CampusPark_GetAway_Max_030"] = "¿Quieres que me quede donde vive el oficial de seguridad al que acusé? ¡Está bien!",
  ["Cue_E3_3B_CampusPark_GetAway_Max_090"] = "Sí, lo somos...",
  ["Act_E3_5A_Bathroom_Bird_Look01_Max_010"] = "De ninguna manera... Ese es el pájaro que salvé el lunes en la habitación de Joyce...",
  ["Act_E3_5A_Bathroom_ChildishSponge_Look01_Max_010"] = "Chloe tiene esta toalla mugrienta de pirata desde que éramos niñas... Tremendo flashback.",
  ["Act_E3_5A_Bathroom_HairDye_Look01_Max_010"] = "Ahora que lo pienso, aún no pasé por la etapa de \"teñir mi cabello de azul\"... tal vez sea el momento.",
  ["Act_E3_5A_Bathroom_Mirror_Interact01_Max_010"] = "¡Y aquí tienen a Mad Max! ¡Vamos a la tocada! Soy tan dura.",
  ["Act_E3_5A_Bathroom_Tap_Interact01_Max_010"] = "Qué bien se siente lavarme la cara después de todo ese cloro... y de andar escondida.",
  ["Act_E3_5A_Bathroom_TeethBrush_Interact01_Max_010"] = "Lo irónico es que siempre me molestaba que Chloe usara mi cepillo de dientes...",
  ["Act_E3_5A_Bathroom_TeethBrush_Look01_Max_010"] = "A Chloe nunca le importó que tomara prestado su cepillo de dientes.",
  ["Act_E3_5A_ChloeRoom_Bills_Look01_Max_010"] = "Lo sé, podría ir al infierno por esto, pero si sirve para salvar a Chloe... Lo devolveremos... de alguna manera.",
  ["Act_E3_5A_ChloeRoom_CHChloe_Look01_Max_010"] = "Chloe no parece tan encabronada por no habernos llevado el dinero del fondo de discapacitados...",
  ["Act_E3_5A_ChloeRoom_CHChloe_Look02_Max_010"] = "Chloe parece más relajada ahora que tiene dinero... del fondo de discapacitados...",
  ["Act_E3_5A_ChloeRoom_Camera_Interact01_Max_010"] = "Nunca te olvides de este momento...",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look01_Max_010"] = "Pensé que Chloe usaría una foto mía... No se puede competir con Rachel.",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look02_Max_010"] = "Bien, Chloe puso mi foto en su teléfono... Debo haber demostrado que era digna...",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look03_Max_010"] = "Dios, ahora me alegra que Chloe haya tomado ese dinero. Este tipo es un culero. Y da miedo.",
  ["Act_E3_5A_ChloeRoom_ChloePhone_Look04_Max_010"] = "¡Chingado! Frank es aterrador. Debería haber dejado que Chloe tomara el dinero...",
  ["Act_E3_5A_ChloeRoom_ChloeRoomDoor_Interact01_Max_010"] = "Ponte algo de ropa primero, salvaje.",
  ["Act_E3_5A_ChloeRoom_ChloeWallet_Look01_Max_010"] = "Es tan conmovedor que haya puesto la foto junto a la de Rachel...",
  ["Act_E3_5A_ChloeRoom_ClosetDoor_Interact01_Max_010"] = "Bueno, es hora de disfrazarnos de Chloe...",
  ["Act_E3_5A_ChloeRoom_Closet_Look01_Max_010"] = "Si me hubiera quedado escondida, nunca me habrían suspendido...",
  ["Act_E3_5A_ChloeRoom_Closet_Look02_Max_010"] = "Tal vez debería haberme escondido en el armario, así no habría forma de que me suspendieran...",
  ["Act_E3_5A_ChloeRoom_Closet_Look03_Max_010"] = "Todavía me siento culpable por no haber salido con toda de aquí y evitar que David madreara a Chloe...",
  ["Act_E3_5A_ChloeRoom_Closet_Look04_Max_010"] = "Dios, si me hubiera quedado escondida, no estaría en la mira de David.",
  ["Act_E3_5A_ChloeRoom_Closet_Look05_Max_010"] = "Si me hubiera escondido en el armario, David no me estaría vigilando.",
  ["Act_E3_5A_ChloeRoom_DavidGun_Look01_Max_010"] = "Frank lo pensará dos veces antes de meterse con Chloe ahora, pero, si David se entera... va a regar la mierda.",
  ["Act_E3_5A_ChloeRoom_Drawer01_Interact01_Max_010"] = "Vaya... ¡Recuerdo este viejo teléfono! Lo decoramos juntas.",
  ["Act_E3_5A_ChloeRoom_Drawer02_Interact01_Max_010"] = "No creo que hoy vaya a una tocada.",
  ["Act_E3_5A_ChloeRoom_HiFi_Look01_Max_010"] = "Amo este tema.",
  ["Act_E3_5A_ChloeRoom_HiFi_Look02_Max_010"] = "Ey, ¿puedes poner el tema de nuevo?",
  ["Act_E3_5A_ChloeRoom_Joint_Look01_Max_010"] = "Debería haber prendido esa bacha frente a David, así no habría golpeado a Chloe...",
  ["Act_E3_5A_ChloeRoom_Joint_Look02_Max_010"] = "Podría empezar a fumar mota ya que logré que me suspendieran como una idiota...",
  ["Act_E3_5A_ChloeRoom_Joint_Look03_Max_010"] = "Tengo suerte de que David no me atrapó por actuar como si fuera mi bacha.",
  ["Act_E3_5A_ChloeRoom_Joint_Look04_Max_010"] = "Fui tan cobarde al esconderme en el armario mientras David la golpeaba...",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact01_Max_010"] = "¿Se supone que funciona?",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact02_Max_010"] = "Por lo menos, no nos identificaron... por ahora.",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact02_Max_020"] = "Debo irme. Sobre todo porque los padres de Kate no van a enterrarla aquí...",
  ["Act_E3_5A_ChloeRoom_Laptop_Interact02_Max_030"] = "Gracias a Dios que está bien. Me pregunto cuándo podré visitarla...",
  ["Act_E3_5A_ChloeRoom_Laptop_Look01_Max_010"] = "¿Puedo ver las noticias en esta vieja laptop?",
  ["Act_E3_5A_ChloeRoom_MajorChoice_DontKiss_Max_010"] = "Me encanta que Chloe sea tan valiente...",
  ["Act_E3_5A_ChloeRoom_MajorChoice_Kiss_Max_010"] = "Órale, fue genial cuando besé a Chloe. No creyó que me animaría...",
  ["Act_E3_5A_ChloeRoom_MaxClothes_Look01_Max_010"] = "¡Es hora de ponerte tu armadura diaria, Max!",
  ["Act_E3_5A_ChloeRoom_MaxClothes_Look02_Max_010"] = "Puaj. Todavía apesta a fábrica de cloro.",
  ["Act_E3_5A_ChloeRoom_Paper01_Look01_Max_010"] = "Chloe es una ñoña tierna. Se está esforzando mucho para descifrar el significado de mi visión...",
  ["Act_E3_5A_ChloeRoom_Photo01_Look01_Max_010"] = "Vaya... Eso fue cuando cumplí diez años. No sabía que Chloe guardaba estas cosas...",
  ["Act_E3_5A_ChloeRoom_RachelClothes_Look01_Max_010"] = "Creo que el estilo de Rachel es un poco más sutil... Como yo.",
  ["Act_E3_5A_ChloeRoom_VoiceOverBed_Max_010"] = "Está tan pacífico después de anoche...",
  ["Act_E3_5A_ChloeRoom_VoiceOverBed_Max_015"] = "¡Qué bueno que volvimos a ser mejores amigas con Chloe!",
  ["Act_E3_5A_ChloeRoom_VoiceOverBed_Max_020"] = "¡Momento de foto!",
  ["Act_E3_5A_ChloeRoom_VoiceOverClothes_Max_010"] = "Bueno, es hora de vestirme.",
  ["Act_E3_5A_Corridor_ArcadiaBayPoster_Look01_Max_010"] = "Nadie en esta ciudad tiene idea de lo que está sucediendo... ¿o sí?",
  ["Act_E3_5A_Corridor_ParentsRoomDoor_Look01_Max_010"] = "Mejor no entro allí... David podría estar en la cama. Puaj.",
  ["Act_E3_5A_Corridor_VoiceOverBreakfast_Max_020"] = "Oh, Dios mío, huele tan sabroso... Como cuando éramos niñas.",
  ["Act_E3_5A_Corridor_Window_Look01_Max_010"] = "Para el resto del vecindario, es otra mañana normal...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_002"] = "¿No estaría con madre si pudiésemos quedarnos aquí para siempre, como cuando éramos niñas?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_006"] = "Ah, está bien, Srta. reina del mundo. Voy a intentar no recordarte los días en que éramos mejores amigas. Rachel adoraba pasar el rato aquí conmigo, habría entendido... Olvídalo.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_007"] = "Al menos puedes tener citas ahora, ¿no? Papá vivía aterrorizado del día en que me empezaran a gustar los chicos.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_008"] = "Exactamente. Me recordaba a ti cuando fingíamos estar dormidas para que nuestros padres no nos obligaran a levantarnos muy temprano los sábados a la mañana...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_010"] = "Tantas como pudimos. Pero era más divertido en su casa. El padrastúpido quería que nos despertáramos con el canto del gallo... Está padre estar de nuevo aquí contigo.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_012"] = "Nada serio. Bastante estúpido, por lo general. Pasé por una etapa de \"boy toy\". Entre otras...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_014"] = "Y muy asquerosos. Lo descubrirás pronto.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_017"] = "Porque tienes buen gusto. Por eso me puse tan contenta cuando Rachel llegó a rescatarme.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_018"] = "Lo siento, lo siento. No quise incomodarte. Solo... creo que nadie es lo suficientemente bueno para ti... aparte de mí.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_021"] = "A ti también te hubiera pasado. Inteligente, sexy y atrevida... Como yo, ¿no?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_022"] = "Se fundía como un camaleón. Claramente, mucho más de lo que sabía... o quería saber...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_025"] = "¡En tus sueños! Por otra parte, tal vez... eres fotógrafa, y ella quería ser modelo.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Chloe_026"] = "Entonces, ¿dónde está?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_001"] = "Me encanta esta luz mañanera, es tan serena...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_003"] = "No, demasiado fácil. Y hay demasiada mierda sucediendo en este momento...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_004"] = "Sí, pero... por desgracia, ya no somos niñas.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_005"] = "Sip. Seguro que a Rachel y a ti les gustaba pasar el rato aquí también...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_009"] = "¿Tuvieron muchas pijamadas?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_011"] = "Bueno... en realidad, nunca me dijiste si tuviste un novio serio mientras yo no estaba...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_013"] = "Y Blackwell es el ejemplo perfecto de que los muchachos solo traen problemas.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_015"] = "No te veo con ninguno de los chicos de aquí...",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_016"] = "Bueno, señorita experimentada. Por favor, ¡explícame lo que se siente ese mágico contacto llamado primer beso!",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_019"] = "Parece que sentías algo muy especial por Rachel.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_020"] = "¿Tan popular era Rachel con todos aquí?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_023"] = "¡Bueno, obvio! Tal vez Rachel se habría peleado por nosotras.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_MaxChloe_Max_024"] = "Tu sabías que ella quería ir a Los Ángeles contigo.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_001"] = "Más te vale no rebobinar ese beso. Sabes que soy más atractiva que esos fresas de Seattle, ¿verdad?",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_002"] = "Seguro usaste tu poder de rebobinar para besarme y ahora actuar como si nada... Vamos, güey, ¡confiésalo!",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_003"] = "Si quieres, fíjate si encuentras ropa limpia en el armario.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_004"] = "No seas huevona, ponte algo de ropa. Entonces podremos devorar el suave desayuno que Joyce está preparando.",
  ["Cue_E3_5A_ChloeRoom_CHChloe_QuickPhase_Chloe_005"] = "¡Mírate, Max! Lista para la pasarela. Baja y muéstrale a Joyce, le va a encantar.",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Chloe_010"] = "Estoy tan destruida de anoche. Pero fue lo máximo.",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Chloe_030"] = "Anoche fue solo el comienzo.",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Chloe_050"] = "Hoy conquistamos el gimnasio; mañana, el mundo. Necesitamos subir de nivel.",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Max_020"] = "Tengo que pensar en qué tipo de criminal me convertí.",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Max_040"] = "Debo admitirlo: fue muy chingón apoderarse del gimnasio Blackwell.",
  ["Cue_E3_5A_ChloeRoom_ChitChat_Max_060"] = "Igual debemos ser cuidadosas con cómo uso mi poder... No quiero atorarme en el tiempo.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_010"] = "¡Photobomb!",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_040"] = "Dejamos una marca en el asfalto en Blackwell anoche.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_060"] = "Todo gran artista sufre el rechazo antes de que lo acepten. Así que debes presentar una foto.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_080"] = "Vamos, no quiero ver a Arcadia Bay hecho cenizas, solo digo esas cosas porque estoy tratando de salir de aquí desde... desde que te fuiste, básicamente. Si llego a encontrar a Rachel y saldar mi deuda con Frank, voy a irme para comenzar una vida nueva.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_100"] = "No, no tienes que ir. Estás suspendida, delincuente.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Chloe_120"] = "Ah, ¿la colegiala tiene una prueba hoy?",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_020"] = "Robando cámara...",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_030"] = "Parece un mundo distinto al de ayer…",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_050"] = "Como si necesitara una más.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_055"] = "Me gustaría hacer algo bueno por la escuela y por Arcadia Bay. Pero ni siquiera puedo presentar mi foto para el concurso... Solo que no quiero que me rechacen.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_070"] = "¿Aunque me esfuerce por mejorar la escuela y el pueblo que deseas ver en llamas?",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_090"] = "Ojalá pudiéramos pasar toda la mañana juntas como hacíamos antes... Tal vez deberíamos levantarnos, tengo que regresar a Blackwell pronto.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_110"] = "No suspendieron la tarea. Si no la entrego, la escuela se comunicará con mis papás otra vez. Y Max se meterá en aún más problemas.",
  ["Cue_E3_5A_ChloeRoom_Insertion_Max_130"] = "Comienzo a pensar que el solo asistir a Blackwell es una prueba. Solo debo regresar a mi horario normal de clases.",
  ["Cue_E3_5A_ChloeRoom_KissChoice_Max_010"] = "Hazlo y dejas de ser mi mejor amiga.",
  ["Cue_E3_5A_ChloeRoom_Kiss_Chloe_010"] = "¡Órale, eres intensa, Max! Voy a mensajear a Warren y decirle que no tiene oportunidad alguna... a menos que disfrute ver tortilleras.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_020"] = "Fíjate si puedes encontrar un atuendo adecuado en mi montaña de moda.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_030"] = "Oye, ¡aquí tienes! Rachel me dejó algo de su ropa... Es de tu talla.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_050"] = "Max, aún no tienes un estilo. Al menos pruébalo. Siempre puedes rebobinar y usar tu aburrida camiseta y el pantalón genérico.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_070"] = "¡Ten un poco de fe en ti, Max! ¡Pruébatelo y libera a tu punketa interior! ¡Puedes darte el lujo de correr riesgos! Puedes probar lo que quieras cuando quieras... a ver, te reto a que me beses",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Chloe_100"] = "Te requetedesafío. Bésame ahora.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_010"] = "Puaj. Todavía apesta a fábrica de cloro.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_040"] = "Pero no es mi estilo.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_060"] = "Apestas. Me gustan mi camiseta y mi pantalón... pero sí estaría chido probarme la ropa de Rachel, solo para ver si me queda bien.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed01_Max_090"] = "¿Qué?",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_010"] = "Te ves con madre, Max. Un par de tatuajes, algunos piercings y te haremos metalera.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_030"] = "Tal vez no. Ve abajo y saluda a Joyce. ¡Desayuno gratis! Tengo que... darme un gallito antes.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_050"] = "No rebobinemos para averiguarlo, ¿sí?",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Chloe_070"] = "Entonces apresúrate a salir, estructurada. Sí, claro.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Max_020"] = "¿Dónde es el toquín? Vamos a roquear.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Max_040"] = "Prometo no decirle a nadie.",
  ["Cue_E3_5A_ChloeRoom_MaxGetDressed02_Max_060"] = "Mira que no voy a asumir la culpa esta vez, loca.",
  ["Cue_E3_5A_ChloeRoom_NoKiss_Chloe_020"] = "Ah, claro, ¿yo sí? ¡Solo admite que ya intentaste ligarme y luego te rajaste! Ahora puedo mensajear a Warren y contarle que te estás reservando para él...",
  ["Cue_E3_5A_ChloeRoom_NoKiss_Max_010"] = "Lo siento, pero no soy tan fácil.",
  ["Cue_E3_5A_ChloeRoom_NoKiss_Max_030"] = "Eres tan ñoña.",
  ["Act_E3_5B_ChloeRoom_BigPadlock_Max_010"] = "¡Obvio! David consiguió un candado militar bien grueso...",
  ["Act_E3_5B_ChloeRoom_BigPadlock_Max_020"] = "Hasta puedo ver la combinación... Esa podría ser una contraseña útil...",
  ["Act_E3_5B_Garage_BlackwellCamerasProject_Look01_Max_010"] = "Mmmm, tal vez este número de identificación funcione...",
  ["Act_E3_5B_Garage_Car_Look01_Max_010"] = "Listo para quemar el asfalto. Es un mejor pasatiempo que la vigilancia.",
  ["Act_E3_5B_Garage_Cupboard01_Interact01_Max_010"] = "Nada por aquí.",
  ["Act_E3_5B_Garage_Cupboard02_Interact01_Max_010"] = "Nada interesante.",
  ["Act_E3_5B_Garage_DavidLaptop_Interact06_Max_010"] = "No, ni madre, Max. Congelaste la laptop.",
  ["Act_E3_5B_Garage_DavidLaptop_Look03_Max_010"] = "Así parece, está bloqueada. No puedo ingresar ninguna contraseña. Chingado.",
  ["Act_E3_5B_Garage_DeerHead_Look01_Max_010"] = "¿David viene jalando esta cabeza desde el 2001?",
  ["Act_E3_5B_Garage_DinerSign_Look01_Max_010"] = "Joyce casi que escribió: \"Casémonos\"...",
  ["Act_E3_5B_Garage_DinerSign_Look01_Max_020"] = "Esa podría ser una contraseña útil...",
  ["Act_E3_5B_Garage_Drawer02_Interact01_Max_010"] = "Tal vez intento \"Padrastro\" de contraseña...",
  ["Act_E3_5B_Garage_Laptop_Interact01_Max_010"] = "Neta, necesita una contraseña... Si pruebo con \"pendejo\"... ¡A intentarlo de nuevo! Necesito más pistas...",
  ["Act_E3_5B_Garage_Laptop_Interact02_Max_010"] = "Todavía necesitas la contraseña, Max la Hacker. Sigue buscando...",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_020"] = "Nop.",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_030"] = "¡Chingado!",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_040"] = "Muy equivocada.",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_050"] = "La bola 8 mágica dice... no.",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_060"] = "La Peor. Hacker. De la historia.",
  ["Act_E3_5B_Garage_Laptop_Interact03_Max_070"] = "A intentarlo de nuevo...",
  ["Act_E3_5B_Garage_Laptop_Interact04_Max_010"] = "¡En el blanco! ¡Max la Hacker ataca de nuevo!",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_010"] = "Lástima que seguiste a la gente equivocada. Kate podría seguir viva...",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_020"] = "En lugar de acechar Kate, David podría haberla ayudado...",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_030"] = "Esto está tan mal... Maldito gacho.",
  ["Act_E3_5B_Garage_Laptop_Interact05_Max_040"] = "Vaya, ¡alerta de spoiler! Rachel definitivamente se ligó a Frank... Pero, ¿por qué le importa a David?",
  ["Act_E3_5B_Garage_Laptop_Look01_Max_010"] = "Apuesto a que David guarda todos los secretos de vigilancia en su laptop.",
  ["Act_E3_5B_Garage_Laptop_Look02_Max_010"] = "Revisemos a este monstruo a ver si encontramos algunas respuestas...",
  ["Act_E3_5B_Garage_Object01_Look01_Max_010"] = "Incluso David Madsen puede ser un ángel para otra persona...",
  ["Act_E3_5B_Garage_Object02_Look01_Max_010"] = "Qué chido... podríamos tener una contraseña aquí.",
  ["Act_E3_5B_Garage_Object03_Look01_Max_010"] = "Por supuesto, los padres de David se preocupan por él... Esa fecha podría ser una buena contraseña...",
  ["Act_E3_5B_Garage_Object04_Look01_Max_010"] = "Chido. No me puedo imaginar a David paseando con Joyce con esta cosa en su carro...",
  ["Act_E3_5B_Garage_Object05_Look01_Max_010"] = "Parece que David leyó esto demasiadas veces. ¿Qué aprendió?",
  ["Act_E3_5B_Garage_Scripted_Max_010"] = "Mejor le cuento a Chloe ahora... Otra cosita que la va a dar un bajón. Y la va a hacer enloquecer.",
  ["Act_E3_5B_Garage_WeaponClosetLock_Look01_Max_010"] = "Chloe no puede conseguir otra arma, a menos que la recupere la otra de Frank.",
  ["Act_E3_5B_Garage_WeaponClosetLock_Look02_Max_010"] = "No hay manera que Chloe ahora pueda devolver el arma...",
  ["Act_E3_5B_Garage_WeaponCloset_Look01_Max_010"] = "Podría probar su número de licencia como contraseña...",
  ["Act_E3_5B_Garden_DeadBird01_Look01_Max_010"] = "Ay, un pajarito muerto. Pobrecito.",
  ["Act_E3_5B_Garden_DeadBird02_Look01_Max_010"] = "Me pregunto cómo murieron estos pájaros.",
  ["Act_E3_5B_Garden_DeadBirds_Look01_Max_010"] = "Tres pájaros muertos en línea... Es demasiado siniestro.",
  ["Act_E3_5B_Garden_Swing_Look01_Max_010"] = "No hay nada más reconfortante que sentarse en un columpio.",
  ["Act_E3_5B_Garden_Swing_Zen_Max_010"] = "Recuerdo cuando Chloe y yo nos turnábamos para empujar...",
  ["Act_E3_5B_Garden_Swing_Zen_Max_020"] = "Nos empujábamos tan fuerte para que saliéramos disparadas por el aire...",
  ["Act_E3_5B_Garden_Swing_Zen_Max_030"] = "Chloe siempre quería dar la vuelta entera...",
  ["Act_E3_5B_Garden_Swing_Zen_Max_040"] = "Yo siempre me asustaba y saltaba antes de volar por los aires…",
  ["Act_E3_5B_Garden_Swing_Zen_Max_050"] = "Pero Chloe sigue intentando estar briseada...",
  ["Act_E3_5B_LivingRoom_Bird_Interact01_Max_010"] = "¡Vete, pájaro! ¡Vuela, tonto!",
  ["Act_E3_5B_LivingRoom_Bird_Look02_Max_010"] = "Oh, mira al pobre pajarito... Parece un poco asustado...",
  ["Act_E3_5B_LivingRoom_CHChloe_Look01_Max_010"] = "Chloe sabe que siempre cuidaré de ella ahora.",
  ["Act_E3_5B_LivingRoom_CHDavid_Look01_Max_010"] = "Lo siento, David, pero ya no te tengo miedo.",
  ["Act_E3_5B_LivingRoom_CHJoyce_Look01_Max_010"] = "Joyce se ve tan diferente en su ropa de diario.",
  ["Act_E3_5B_LivingRoom_CHJoyce_Look02_Max_010"] = "Espero que Joyce no me odie por atacar a David...",
  ["Act_E3_5B_LivingRoom_CHJoyce_Look03_Max_010"] = "Tal vez fui muy poco dura con David por el bien de Joyce...",
  ["Act_E3_5B_LivingRoom_DinnerPlate_Look01_Max_010"] = "¡Esos sí que son hot cakes!",
  ["Act_E3_5B_LivingRoom_DinnerPlate_Look02_Max_010"] = "¡Tengo un pasaje para que esos huevos con tocino viajen a mi barriga!",
  ["Act_E3_5B_LivingRoom_Eggs_Interact01_Max_010"] = "\"Los huevos primero\", como Joyce solía decir...",
  ["Act_E3_5B_LivingRoom_Flyer_Look01_Max_010"] = "Esta podría ser la única vez que tienen razón...",
  ["Act_E3_5B_LivingRoom_Fridge_Interact01_Max_010"] = "Debería evolucionar y volverme vegana, pero... Mmmm, tocino.",
  ["Act_E3_5B_LivingRoom_Fridge_Look01_Max_010"] = "Me encanta que tengan el mismo refrigerador...",
  ["Act_E3_5B_LivingRoom_GarageDoor_Interact01_Max_010"] = "No puedo irme hasta hablar con Joyce... y filiar.",
  ["Act_E3_5B_LivingRoom_GarageDoor_Interact02_Max_010"] = "Todavía debo encontrar la contraseña de la computadora de David...",
  ["Act_E3_5B_LivingRoom_Milk_Interact01_Max_010"] = "Ahora, la leche de mamá...",
  ["Act_E3_5B_LivingRoom_NewsPaper_Look01_Max_010"] = "La vida de Kate sí que valió un buen titular provechoso.",
  ["Act_E3_5B_LivingRoom_NewsPaper_Look02_Max_010"] = "Ay, vamos, no quiero ser famosa por esto...",
  ["Act_E3_5B_LivingRoom_Object04_Look01_Max_010"] = "Vaya, Chloe aún come el mismo cereal... Y yo también...",
  ["Act_E3_5B_LivingRoom_Object05_Look01_Max_010"] = "Supongo que nadie riega las plantas aquí...",
  ["Act_E3_5B_LivingRoom_Phone_Interact02_Max_010"] = "Hasta la vista, mensaje. Me parece que Chloe se merece un descanso de toda esta mierda.",
  ["Act_E3_5B_LivingRoom_Phone_Interact02_Max_020"] = "Hasta la vista, mensaje",
  ["Act_E3_5B_LivingRoom_Phone_Look01_Max_010"] = "Parece un mensaje de voz...",
  ["Act_E3_5B_LivingRoom_Phone_Look03_Max_010"] = "Al carajo con este mensaje. Chloe ya tiene suficiente de que preocuparse.",
  ["Act_E3_5B_LivingRoom_Phone_Look04_Max_010"] = "Ups. Espero que el mensaje no fuera para Joyce ni Chloe...",
  ["Act_E3_5B_LivingRoom_TV_Interact01_Max_010"] = "¿Qué demonios está pasando? ¿Será real el tornado?",
  ["Act_E3_5B_LivingRoom_VoiceOverCook_Max_010"] = "Huevos y leche, perfecto.",
  ["Act_E3_5B_LivingRoom_VoiceOverCook_Max_020"] = "Puedo conseguir huevos y tocino.",
  ["Act_E3_5B_LivingRoom_VoiceOverLaptop_Max_010"] = "Necesito entrar en la computadora de David. Seguro esconde alguna mierda.",
  ["Act_E3_5B_LivingRoom_Window_Look01_Max_010"] = "Sigo esperando que el cielo se tiña de rojo...",
  ["Cue_E3_5B_Kitchen_BeerBottle_Max_010"] = "¿Quién toma cerveza tan temprano por aquí?",
  ["Cue_E3_5B_Kitchen_PeanutButter_Max_010"] = "Me alegro de que sea cremosa y no crujiente...",
  ["Cue_E3_5B_LivingRoom_BirdPuzzle_Joyce_010"] = "¡Qué lata! ¿Puedes ayudarme a sacar a este pájaro de aquí?",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Chloe_170"] = "Que tengas un buen día.",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_020"] = "Ehm... estabas fumando mota en la habitación de Chloe. Es ilegal.",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_050"] = "Chloe se estaba drogando. Es ilegal.",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_100"] = "No tengo por qué soportar esta clase de interrogatorio. ¡Menos de dos delincuentes como ustedes!",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_120"] = "Ah, ¿con que ahora tú estás en mi contra? Por supuesto, las mujeres siempre se apoyan unas a la otras. Bueno, ¡sáquense a la chingada!",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_140"] = "¡No puedes echarme de mi propia casa!",
  ["Cue_E3_5B_LivingRoom_BlameDavid_David_160"] = "Creo saber muchas cosas... como cuando me flanquean.",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_070"] = "¿Qué? ¿Es cierto, Max? Sí, David, ¿por qué tienes esos archivos? Me parece muy inquietante.",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_110"] = "Tal vez deberías calmarte...",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_130"] = "David... mejor quédate en un hotel hasta que resolvamos esta...",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_150"] = "Es mi casa, David. Que yo pago, y que está a mi nombre. Conoces la ley, ¿no?",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Joyce_180"] = "Chloe, solo esta vez... Cállate, por favor.",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Max_010"] = "Eres un bravucón, David. Te vi molestar a Kate Marsh justo cuando estaba angustiada. Tenías la opción de ayudarla. Para ti, todos en Blackwell son sospechosos. Todos excepto Nathan Prescott... Por eso no le caes bien ni a los estudiantes ni a los profesores. Llegaste a amenazarme. Respeto que hayas servido en el Ejército, pero tú no tienes respeto por nadie.",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Max_030"] = "También lo es espiar a tu familia y a las personas tu trabajo. ¿Por qué tienes fotos de Kate Marsh y Rachel Amber en tus archivos?",
  ["Cue_E3_5B_LivingRoom_BlameDavid_Max_040"] = "Eres un bravucón, David. Te vi molestar a Kate Marsh justo cuando estaba angustiada. Tenías la opción de ayudarla. Para ti, todos en Blackwell son sospechosos. Todos excepto Nathan Prescott... Por eso no le caes bien ni a los estudiantes ni a los profesores. Llegaste a golpear a tu propia hijastra. Respeto que hayas servido en el Ejército, pero tú no tienes respeto por nadie.",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_001"] = "¡Aquí viene SuperMax al rescate!",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_002"] = "¿Disculpa? ¡Eso fue épico! ¡Ahogaste por completo a ese cabrón! ¿Cómo te sientes?",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_004"] = "¿No? Estoy muy orgullosa de ti. Y de Joyce, que finalmente lo mandó a la chingada.",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Chloe_005"] = "Estuvo demasiado tiempo en negación. Pero estoy muy orgullosa que finalmente lo mandó a la chingada.",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_006"] = "Discúlpame por haber explotado...",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_007"] = "Me siento bien por ponerlo como camote.",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_008"] = "Me siento mal por haberlo hecho frente a tu mamá...",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeAccusedDavid_Max_009"] = "Te entiendo. Pero no se trata de David en este momento. Se trata de Rachel... y de Frank.",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_001"] = "¿Que deseas arreglar ahora, Max?",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_002"] = "No puedo creer que hayas defendido al cabrón que me golpeó. ¿Qué clase de mejor amiga eres?",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_003"] = "No puedo creer que hayas defendido a ese cabrón. ¿Qué clase de mejor amiga eres?",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Chloe_004"] = "¡Que me hayas salvado la vida no te da derecho a que te portes como si fueras mi niñera todo el día! David...",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_005"] = "Mira, no necesito rebobinar para saber lo que vas decir...",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_006"] = "Una que te quiere lo suficiente como para impedir que empieces a regarla.",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_007"] = "No lo entiendes. No era el momento decirle nada.",
  ["Cue_E3_5B_LivingRoom_CHChloe_MaxChloeDefendDavid_Max_008"] = "Sí, Chloe, David es un idiota. Pero todavía no se trata de él. Se trata de Rachel... y de Frank.",
  ["Cue_E3_5B_LivingRoom_CHChloe_QuickPhase_Chloe_001"] = "Gracias por decepcionarme otra vez, Max. ¿Por qué no rebobinas, así puedo borrar la imagen de ti mientras defiendes a ese cabrón?",
  ["Cue_E3_5B_LivingRoom_CHChloe_QuickPhase_Chloe_002"] = "Max, me diste escalofríos. ¡Más te vale que no rebobines!",
  ["Cue_E3_5B_LivingRoom_CHChloe_QuickPhase_Chloe_003"] = "Cuando estés lista, salgamos.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_001"] = "Bueno, bueno... Solo... espero que te haga feliz arruinar mi matrimonio.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_002"] = "Bueno, bueno... espero que te haga feliz haber hecho que me despidieran y arruinar mi matrimonio...",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_003"] = "Sí, tengo que admitirlo, Max. Sí que tienes pelotas. Bueno, si fueras hombre...",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_004"] = "No estoy amenazando a nadie. Esto es defensa propia.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_005"] = "Ah, sí, puedo ver la influencia de Chloe ahora.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_David_009"] = "¿\"Ya veré\"? ¿Esa fue una amenaza? Ah, me encantaría ver qué haces al respecto, soldadito. Cuando quieras...",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_Max_006"] = "Un verdadero hombre no se la pasa haciendo amenazas.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_Max_007"] = "Pero no lo soy. ¿Por qué dirías eso?",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxAccusedDavid_Max_008"] = "Solo mantente alejado de mí. Y de Chloe. O ya verás.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_001"] = "Max... Sé que no era necesario que me apoyaras. ¿Por qué lo hiciste?",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_005"] = "Eso no es culpa mía. Siempre quise darles un hogar seguro y cariñoso.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_006"] = "Bueno... gracias. Solo intento mantener segura a mi familia.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_David_008"] = "Max, cuando estás en una zona de guerra, nunca estás seguro. Eres joven, aún no entiendes que este pueblo puede... Por eso me pasé de la raya. A veces...",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_Max_002"] = "Porque Chloe y Joyce ya han sufrido bastante.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_Max_003"] = "No lo sé. Sentí que era lo correcto.",
  ["Cue_E3_5B_LivingRoom_CHDavid_MaxDefendDavid_Max_007"] = "Tal vez demasiado segura...",
  ["Cue_E3_5B_LivingRoom_CHDavid_QuickPhase_David_001"] = "Gracias de nuevo por defenderme, Max. Pero esta es mi familia ahora.",
  ["Cue_E3_5B_LivingRoom_CHDavid_QuickPhase_David_002"] = "No quiero volver a verte ni escucharte, Max. Ya nos lastimaste a mí y a mi familia demasiado.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_002"] = "Pensamos lo mismo, Max. Sigo esperando que Rachel aparezca como si nada, o incluso que le mande un mensaje a Chloe desde Hollywood... o de donde sea que esté...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_003"] = "Dios, eso espero. Ella era... es inteligente y siempre caía de pie. Tal vez no la conozco tanto como creía... Tal vez, Chloe tampoco.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_004"] = "Chloe hacía enojar a todos, menos a Rachel. Eran uña y carne. Me recordaba a Chloe contigo... Pero Rachel no tenía los pies sobre tierra como tú.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_005"] = "Lo sé. Miro esos horribles programas de crímenes verdaderos y me enferma pensar que Rachel podría aparecer en uno... Prefiero ni pensar en el asunto.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_012"] = "Max Caulfield, ¿estás celosa de Rachel?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_015"] = "No, solo diferente. La última vez que las vi a Chloe y a ti en sus disfraces de piratas, supe que nunca iba a conseguir otra amiga tan buena.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_016"] = "¿Eso crees? Entonces, ¿por qué Chloe lleva cinco años diciendo que deseaba ser más como tú?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_018"] = "Y cuando asumiste la culpa por la bacha, lo demostraste.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_019"] = "Solo desearía que hubieras podido evitar que David pescara a Chloe con esa bacha.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Joyce_023"] = "Y eso me hace, ¿qué?, ¿una vieja de cien años? Solo tienes 18, Max. Ah, la juventud... Si tan solo pudiera volver... ",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_001"] = "Me encantaría pensar eso también, Joyce. Pero...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_006"] = "Siendo honesta, Joyce... ¿crees que Rachel está bien?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_007"] = "¿Hay alguna razón por la que Rachel se podría haber enojado con Chloe e irse sin ella?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_008"] = "Ni siquiera quiero pensar eso, y mucho menos decirlo en voz alta... pero creo que Rachel está metida en serios problemas.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_009"] = "A veces siento que no conozco a Chloe tanto como creía...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_010"] = "¿Tengo los pies en la tierra? ¿Desde cuándo? Quizás por eso Chloe quiere tanto Rachel...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_011"] = "Ahora entiendo la obsesión de Chloe por encontrarla...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_013"] = "¿Qué? De ningún modo. Sé que fui egoísta cuando me fui. Me alegra que Chloe haya encontrado una amiga mejor.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_014"] = "Quizás. Rachel era mucho más buena onda que yo...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_017"] = "Lo dudo. Eh... ¿De verdad? \"Hace cinco años\"; se sienten como un millón...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_020"] = "Gracias...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_021"] = "Lo sé...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_022"] = "Siento que pasaron mil años desde que Chloe y yo nos disfrazamos de piratas...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyce01_Max_024"] = "No todo lo que brilla, Joyce...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_001"] = "Hola, Max...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_003"] = "Ay, Max. Me odio a mí misma. Siento mucho haberte involucrado en todo esto...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_006"] = "Yo fui la que se enamoró de David y lo trajo a su hogar. Era muy duro con Chloe, pero a la vez tan gentil conmigo. Como si estuviese agradecido...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Joyce_008"] = "Ahora se le acabó la suerte. ¿Cómo puedo confiar en él luego de todo esto?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_002"] = "Joyce, ¿estás bien? ¿Estás enojada conmigo?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_004"] = "Dios, Joyce, no es tu culpa.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_005"] = "Es mi culpa por haberte involucrado.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceAccusedDavid_Max_007"] = "Tuvo demasiada suerte por encontrarte.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_001"] = "Hola, Max...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_003"] = "¿Por qué? Hiciste lo correcto y defendiste a David cuando él no podía. Chloe nunca lo haría...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_006"] = "¿Con quién no está enojada Chloe? ¿Cómo iba a aguantar un día entero sin encabronarse?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_007"] = "A veces yo también lo hago. Pero si tratas a todos como si fueran el enemigo, en eso los conviertes.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Joyce_009"] = "Créase o no, David me hace feliz. Chloe nunca le dio la esa oportunidad.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_002"] = "Joyce, lamento lo que acaba de suceder...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_004"] = "Creo que está encabronada conmigo por lo que hice.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_005"] = "Entiendo el motivo.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_MaxJoyceDefendDavid_Max_008"] = "Te entiendo, Joyce. Solo quiero que ella y tú sean felices.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_001"] = "Vamos, Max, encuentra los ingredientes para empacarnos.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_002"] = "Vamos, siéntate, Max. Ya casi termino de producir este increíble desayuno.",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_003"] = "Ya debería saber que Chloe no puede pasar una hora sin un tango...",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_004"] = "Max, no te culpes. David se buscó esto él solo, ¿entiendes?",
  ["Cue_E3_5B_LivingRoom_CHJoyce_QuickPhase_Joyce_005"] = "Max, agradezco que hayas defendido a David... y a nuestra familia. Aunque Chloe no lo haga.",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_010"] = "¿Tuvieron una reunión de \"Chloe está de la chingada\" Anónimos?",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_050"] = "Mantengo a la carcelera ocupada mientras revisas el garage.",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_070"] = "Deja de ser tan entrometida, mamá. Por Dios, no puedo hacer nada por aquí sin que todos se alteren por mis chingaderas...",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_100"] = "Claro, corre y ve al baño justo cuando deberías darme apoyo.",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Chloe_120"] = "¡Nadie más lo hace!",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_040"] = "Chloe, por favor... Es muy temprano para discutir. ¿Por qué mejor no comes algo?",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_060"] = "Dejen de susurrar o sabré que hablan de mí.",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_080"] = "No se puede ni bromear contigo, Chloe, te alteras con cualquier cosa...",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_110"] = "¿Ahora quién es la paranoica?",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Joyce_115"] = "Solo escucha lo que dices...",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Max_030"] = "No siempre se trata de ti...",
  ["Cue_E3_5B_LivingRoom_ChloeArrives_Max_090"] = "Disculpen, necesito usar el baño.",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Chloe_020"] = "Ah, ¿neta? Qué generosa, Princesa Max. De pronto, ya no importa lo siniestro que se estuvo comportando David, o el hecho de que guarde todos esos extraños archivos de tus compañeros de clase, ni que siempre repitas lo espeluznante que David...",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Chloe_060"] = "Tengo que hacer del dos. ¿Vienes, Max?",
  ["Cue_E3_5B_LivingRoom_DefendDavid_David_050"] = "No podría estar más de acuerdo. Ahora bien, si a ninguna le molesta, me gustaría olvidarme del trabajo, sentarme y comer un poco de esta increíble comida...",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Joyce_040"] = "¡Basta! No quiero que se acuse a nadie de nada. Ya estamos con demasiadas chingaderas aquí últimamente, y hoy no quiero saber nada de eso en mi propia casa.",
  ["Cue_E3_5B_LivingRoom_DefendDavid_Max_010"] = "Escucha, no sabemos si David hizo algo, y nadie tiene pruebas contra él. Por lo que sabemos, la amenaza real es Nathan Prescott por ahora. Quisiera dejársela pasar a David...",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Chloe_190"] = "Los amenaza con las cámaras de vigilancia. Así puede espiar a todo el mundo... como nos espía aquí.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Chloe_210"] = "Sí, vivo para provocarte, ¿no? ¡Eres un completo paranoico, David!",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Chloe_230"] = "Decías que era una fracasada porque me expulsaron de Blackwell... Dime, ¿quién es el fracasado ahora, David? ¿A quién no has acusado u hostigado? Entre tus investigaciones sobre Rachel y Kate, ¿qué más lograste que no sea meterte en problemas?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_010"] = "Lindo desayuno.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_030"] = "Eso es lo que pasa cuando pierdes tu trabajo como jefe de seguridad en Blackwell.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_050"] = "¿Qué puede esperarse de la chingada educación liberal? El director cree más en las palabras de estudiantes drogones que en las de un veterano y profesional legal.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_060"] = "Bueno, esta será la última vez. Voy a buscar un abogado para demandarlos por todo lo que tienen.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_065"] = "Me imaginé que estarías aquí. ¿Ese es tu disfraz de Halloween de Rachel Amber?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_080"] = "No, Chloe y tú piensan que saben más que el resto. Como todos los adolescentes.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_100"] = "Necesito dormir un poco después de redactar todos esos informes de vandalismo de anoche.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_120"] = "Unos culeros se metieron en la alberca. Esto es lo que sucede en estas escuelas liberales chingadas. ¡Los estudiantes creen tener derecho de hacer lo que se les plazca en el campus!",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_140"] = "¿Quién más lo haría? Y juro que voy a pescarlos.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_150"] = "Me imaginé que estarías aquí. ¿Ese es tu disfraz de Halloween de Rachel Amber?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_170"] = "Debe ser chido que te suspendan y tengas algo de tiempo libre fuera de Blackwell.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_200"] = "No me provoques, Chloe. Ahora no.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_David_220"] = "Ahora. No. Chloe.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_020"] = "David, ¿ya volviste?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_040"] = "¿Qué pasó?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_055"] = "Uh, ¿de nuevo? No es la primera vez que te metes en problemas allí...",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_090"] = "Deja a Max en paz, David. No puedo creer que te despidieron. En realidad no, no me sorprende mucho. ¿Acaso amenazaste de muerte a algún estudiante?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_130"] = "¿Estás seguro de que eran estudiantes de Blackwell?",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Joyce_180"] = "Deja a Max en paz, David. Deja de amenazar estudiantes.",
  ["Cue_E3_5B_LivingRoom_FamilyArgues_Max_070"] = "¡Sabes más que yo de ella!",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_020"] = "¡Rachel! Ah... D-Digo, Max. Órale, me sorprendiste. Te queda bien esa ropa. Gracias a Dios que no eres tan problemática como ella o Chloe. Ahora dime exactamente lo que quieres comer.",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_040"] = "Me imaginé que los extrañabas. Comías más que William, y eso que él los amaba...",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_060"] = "Esta vez puedes ayudarme con los ingredientes. Necesito que me traigas los huevos y la leche.",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_080"] = "¡Ah! ¿Recuerdas cuando dormían hasta tarde, pero corrían apenas las llamaba a comer?",
  ["Cue_E3_5B_LivingRoom_Insertion_Joyce_100"] = "Esta vez puedes ayudarme con los ingredientes. Necesito que me traigas los huevos y el tocino.",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_010"] = "Buenos días, Joyce...",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_030"] = "Me muero por uno de tus famosos hot cakes.",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_050"] = "Me acuerdo. Competíamos para agarrar los más que pudiéramos.",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_070"] = "Huevos y tocino hasta el cansancio.",
  ["Cue_E3_5B_LivingRoom_Insertion_Max_090"] = "Por supuesto. Nos despabilábamos tan rápido.",
  ["Cue_E3_5B_LivingRoom_MaxAndJoyceCooking_Joyce_005"] = "Gracias.",
  ["Cue_E3_5B_LivingRoom_MaxAndJoyceCooking_Joyce_010"] = "Después de todos estos años y todo lo que pasó, es muy chido verlas juntas. No ha tenido una buena amiga desde tú o Rachel... Esa ropa me recuerda tanto a ella. Una chica tan dulce. Solo espero que esté viviendo la gran vida en Los Ángeles.",
  ["Cue_E3_5B_LivingRoom_MaxAndJoyceCooking_Joyce_020"] = "Voilá, un desayuno de campeonas... y un campeón. Ve a sentarte a la mesa.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_020"] = "Bien. Puedes limpiar.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_030"] = "Verte de nuevo... ahh, me hizo recordar tanto...",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_040"] = "Sé que estas fotos no se comparan con tu obra, Max...",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_070"] = "Él quiere que todos seamos felices, Max. Solo que no es muy bueno demostrándolo.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_090"] = "Tú tienes tu propio estilo genial.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_110"] = "Me alegra... William tomó esta foto con su cámara instantánea. Fue la última foto que tomó... Se fue en el carro justo después y... y...",
  ["Cue_E3_5B_LivingRoom_MaxSits_Joyce_130"] = "No te la mostré para ser morbosa. De hecho, quiero que la conserves... Mi bebé estaba tan llena de vida y luz. Era tan esperanzada y positiva... todo lo que ahora no es. Esta fue la última vez que vi a Chloe verdaderamente feliz.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_010"] = "Te agradezco tanto, Joyce... Nunca voy a dejar esta mesa.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_050"] = "Mis fotógrafos favoritos probablemente toman fotografías como las tuyas.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_060"] = "Haces de David un hombre feliz, Joyce.",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_080"] = "Ahh, no creo que pueda estar a la altura de Rachel usando esto...",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_100"] = "Vaya, recuerdo ese día por completo...",
  ["Cue_E3_5B_LivingRoom_MaxSits_Max_120"] = "Lo sé, Joyce. Lo siento...",
  ["Cue_E3_5B_LivingRoom_Phone_AnsweringMachine_010"] = "Mensaje borrado.",
  ["Cue_E3_5B_LivingRoom_Phone_Interact01_Joyce_010"] = "¡¿Qué?! ¿Te metiste en problemas otra vez, Chloe? ¿Acaso no duermes?",
  ["Cue_E3_5B_LivingRoom_Phone_Interact01_OfficerCorn_010"] = "David, este es el oficial Corn... Solo quería avisarte que se identificó el carro de tu hijastra anoche cerca del campus de Blackwell más o menos a la hora en que se produjo la entrada forzada... Llámame pronto…",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_020"] = "Ah, ¿así que no estás más de su lado? Decídete...",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_050"] = "Eso suena como un mal augurio. No sé si puedo lidiar con más malas noticias...",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_065"] = "Claro. De ninguna manera, Max. Solo estaba posando para provocar a Frank.",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_080"] = "¿Y qué prueba eso?",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Chloe_100"] = "Más le vale a ese cabrón que no tenga nada. Por su propio bien.",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_010"] = "Escucha, tengo que contarte sobre lo que encontré en los archivos de David...",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_030"] = "Definitivamente necesitas saber esto.",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_040"] = "Escucha, tengo que contarte sobre lo que encontré en los archivos de David...",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_060"] = "Definitivamente necesitas saber esto.",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_062"] = "Mira, cuando revisé la laptop de David, encontré fotos de Rachel y Frank... demasiado amigables.",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_067"] = "Claro, Chloe, ¿qué sé yo de fotografía? No eran fotos para Hollywood. Estás en negación. Vamos a ver la casa rodante de Frank así lo compruebas… Mira, ¡está al lado del restaurante!",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_070"] = "Si no me crees, ¿por qué no vemos lo que esconde en su casa rodante?",
  ["Cue_E3_6A_ChloeCar_InsideChloeCar_Max_090"] = "Frank tiene el brazalete de Rachel. ¿Qué más tendrá allí?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_006"] = "Debo culpar a alguien. De lo contrario, es mi culpa. ¡Ni madres!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_007"] = "Sí, Kate Marsh se suicidó. Está muerta. Es tan triste. ¿De acuerdo? Eso no me hace sentir mejor sobre mi chingada vida, ¿entiendes?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_008"] = "Sí, Kate Marsh casi se suicidó. Es tan triste. ¿De acuerdo? Eso no me hace sentir mejor sobre mi chingada vida, ¿entiendes?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_009"] = "Dios, ¡se estaba revolcando con ese naco de Frank! ¡La puta me mintió a la cara, Max! No puedo volver a confiar en nadie. Todos mienten y fingen que les importo. ¡Incluso tú!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_016"] = "Bueno, está bien... Es que pareces no entender. Es como si el universo me estuviera castigando...",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_017"] = "El cabrón de mi papá, por supuesto,... ¡¿Hola?!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_018"] = "Sí, no lo dudes ni un momento. Eligió cruzar esa puerta y abandonarme para siempre.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_019"] = "Dije ¡\"mi papá\"! ¡Mi verdadero papá, el que terminó muerto por nada! No el repuesto humano que se consiguió Joyce.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_023"] = "Lo sé, Max. Mi mamá se culpa a sí misma... solo porque ella quería que la buscara del trabajo. A veces, hasta yo la culpo...",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_024"] = "Sí, Max, lo hago. ¿Sabes lo que se siente ser una niña esperando a que papá vuelva... y que nunca regrese?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_027"] = "Ojalá me hiciera sentir mejor. Pero, desde que murió, mi vida se transformó en una mierda.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_030"] = "Tienes razón. No quiero escucharlo.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_031"] = "La verdad que me encantaría creerlo... Me gustaría al menos creer en algo luego de lo que pasó...",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Chloe_033"] = "Max, ¡si tuviera tu poder iría a ese momento y cambiaría todo! ¡Todo...!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_005"] = "Chloe, no puedes seguir culpándome a mí y a todo el mundo por todo lo malo de tu vida. No es justo.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_010"] = "Así es la vida, es dura; no es culpa de nadie, etcétera, etcétera, como diría el Sr. Jefferson. Y Kate Marsh...",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_011"] = "Madura. No quiero ser mala. Pero no eres la única en Arcadia Bay con problemas. Kate Marsh se suicidó, ¿sabes?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_012"] = "Madura. Dios, no eres la única en Arcadia Bay con problemas. Kate Marsh casi...",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_013"] = "¿Así que ahora Rachel también tiene la culpa?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_014"] = "¿Entonces quién tiene la mayor culpa?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_015"] = "Chloe Price, retráctate en este instante. ¡Ahora mismo!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_020"] = "¿Culpas a William? ¿En serio?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_021"] = "¿Culpas a David?",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_022"] = "Chloe, tu papá no eligió... \"abandonarte\".",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_025"] = "No, no es cierto.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_026"] = "No, claro que no. Pero estaba contigo ese día. ¡Y solo fue un terrible accidente!",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_028"] = "No quieres escuchar esto, pero todavía estás aquí. Viva. Conmigo. Y eso no es ningún accidente.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_029"] = "Lo sé... pero mira todo lo que pasó la semana pasada. Tu vida cambió la mía, eso no es una mierda.",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_032"] = "Chloe, no puedo seguir por mi cuenta. Te necesito conmigo. Y Rachel te necesita...",
  ["Cue_E3_6A_TownCar_CHChloe_Phase01_Max_034"] = "Si tan solo pudiera...",
  ["Act_E3_6B_DinerPark_Bird01_Look01_Max_010"] = "Qué tal eso... tan triste, perturbador y hermoso a la vez... ¡qué foto impresionante!",
  ["Act_E3_6B_DinerPark_Bird01_Photo_Max_010"] = "Tan siniestro...",
  ["Act_E3_6B_DinerPark_CHCloe_Look01_Max_010"] = "Espero que encuentre un buen filete que mantenga al perrito ocupado...",
  ["Act_E3_6B_DinerPark_CHCloe_Look02_Max_010"] = "Digno de Scooby, Chloe.",
  ["Act_E3_6B_DinerPark_CHCloe_Look03_Max_010"] = "No te asustes, Max... Tienes el poder.",
  ["Act_E3_6B_DinerPark_CHFisherman_Look01_Max_010"] = "Me parte el alma cada vez que veo a alguien con una petición.",
  ["Act_E3_6B_DinerPark_CHHomeless_Look01_Max_010"] = "Y me pone muy mal que haya mujeres grandes en la calle, viviendo así... hermoso mundo el nuestro.",
  ["Act_E3_6B_DinerPark_CHTrucker_Look01_Max_010"] = "Estaría de lujo conducir un camión durante un tiempo... Siempre en la carretera…",
  ["Act_E3_6B_DinerPark_Deadbirds_Look02_Max_020"] = "¿Qué está pasando?",
  ["Act_E3_6B_DinerPark_Deadbirds_Look03_Max_030"] = "Es tan espeluznante...",
  ["Act_E3_6B_DinerPark_Deadbirds_Look04_Max_040"] = "Tornados, nevadas, eclipses... y ahora se nos mueren los animales. Chingado.",
  ["Act_E3_6B_DinerPark_FrankRV_Look01_Max_010"] = "Cuidado, Max. Hay un Cujo en frente...",
  ["Act_E3_6B_DinerPark_NewspaperKateAlive_Look01_Max_010"] = "Por Dios, ¡qué vergüenza! | Me van a trolear de lo lindo.",
  ["Act_E3_6B_DinerPark_NewspaperKateDead_Look01_Max_010"] = "Así es, otro día hermoso en Arcadia Bay.",
  ["Act_E3_6B_DinerPark_RVDoor_Interact01_Max_010"] = "Cerrada.",
  ["Act_E3_6B_DinerPark_RVWindow_Look01_Max_010"] = "Déjà vu. Ahora la suciedad está sucia.",
  ["Act_E3_6B_DinerPark_Truck_Look01_Max_010"] = "Me encantaría hacer una serie de fotos que sea toda de \"Rines grandes\"...",
  ["Act_E3_6B_DinerPark_Truck_Look02_Max_010"] = "Hice feliz al camionero y puedo fotografiar este Needham modelo 1977 padrísimo. Mensaje recibido, Max.",
  ["Act_E3_6B_Diner_BeansPlate_Look01_Max_010"] = "Frank Bowers protagoniza \"Por un puño de frijoles\".",
  ["Act_E3_6B_Diner_BeerPrint_Look01_Max_010"] = "Podría tomarme la cerveza o tirársela a Frank. La cerveza es asquerosa, entonces…",
  ["Act_E3_6B_Diner_Blocker01_Max_010"] = "No debería haber dicho eso, voy a tener que rebobinar.",
  ["Act_E3_6B_Diner_Blocker01_Max_020"] = "Maldita sea, lo encabroné en serio, tengo que volver.",
  ["Act_E3_6B_Diner_CHCop_Look01_Max_010"] = "No se preocupe por mí, oficial... Solo paso por aquí para robarle las llaves a un narcotraficante.",
  ["Act_E3_6B_Diner_CHFrank_Look01_Max_010"] = "Enciende el cerebro, Max. ¿Cómo puedes echar mano de las llaves de Frank?",
  ["Act_E3_6B_Diner_CHFrank_Look02_Max_010"] = "Ja, ¡se va a volver loco cuando no pueda encontrar las llaves!",
  ["Act_E3_6B_Diner_CHNathan_Look01_Max_010"] = "¿Nathan y Frank juntos? Una mala combinación, si las hay.",
  ["Act_E3_6B_Diner_CHNathan_Look02_Max_010"] = "Nathan tiene tiempo para conseguir drogas de Frank porque fue expulsado...",
  ["Act_E3_6B_Diner_CHRudeDude_Look01_Max_010"] = "Ser un hijo de la chingada y borracho no puede ser una buena forma de comenzar la jornada.",
  ["Act_E3_6B_Diner_CopKeys_Max_010"] = "Tengo las llaves, ahora mejor pelarse.",
  ["Act_E3_6B_Diner_Counterfood_Look01_Max_010"] = "Se ve sabroso, pero las llaves tienen prioridad.",
  ["Act_E3_6B_Diner_FishermanPetitionStand_Look01_Max_010"] = "Cuántos volantes. Lástima que nadie los vaya a leer...",
  ["Act_E3_6B_Diner_FishingWallOfFame01_Look01_Max_010"] = "Me había olvidado del Muro de los Pescadores...",
  ["Act_E3_6B_Diner_FrankLeave_Max_010"] = "He terminado aquí, Frank.",
  ["Act_E3_6B_Diner_Graffiti01_Look01_Max_010"] = "Capaz esto aplique a todos...",
  ["Act_E3_6B_Diner_Graffiti01_Look02_Max_010"] = "Tú deberías haber saltado, idiota.",
  ["Act_E3_6B_Diner_Graffiti02_Look01_Max_010"] = "Mierda, ¿entonces cuáles son los otros signos?",
  ["Act_E3_6B_Diner_Jukebox_Look01_Max_010"] = "No es momento de elegir canciones. Llaves.",
  ["Act_E3_6B_Diner_Keys_Interact01_Max_010"] = "Lo siento, Frank, es hora de revelar algunos secretitos...",
  ["Act_E3_6B_Diner_Keys_Look01_Max_010"] = "¡Las llaves mágicas al reino rodante de Frank!",
  ["Act_E3_6B_Diner_MaxSearch_Max_080"] = "En resumen, no hay llaves para Max. Tal vez podría conversar con ese oficial, o con Nathan, y hacer como en \"Hechizo del tiempo\" hasta que me den la información que necesito.",
  ["Act_E3_6B_Diner_MaxSearch_Max_100"] = "\"Trate de interrogar a otra persona, teniente Caulfield\".",
  ["Act_E3_6B_Diner_NathanDickhead_Max_010"] = "Gracias por la ayuda, imbécil.",
  ["Act_E3_6B_Diner_PostCardRack_Look01_Max_010"] = "Mirando estas postales, ¿quién se va a imaginar lo extraña que es esta ciudad?",
  ["Act_E3_6B_Diner_Poster01_Look01_Max_010"] = "El cartel no menciona alumnos desquiciados con armas.",
  ["Act_E3_6B_Diner_Poster04_Look01_Max_010"] = "Sería muy divertido pasear en el carro con Warren e ir al autocinema... Max necesita más diversión.",
  ["Act_E3_6B_Diner_Poster04_Look02_Max_010"] = "Sí parece divertido... Pero ahora no estoy en \"modo de diversión\"... Pobre Warren.",
  ["Act_E3_6B_Diner_Scripted_Max_010"] = "Ahora hay que encontrar una manera rápida y fácil de volarme las llaves de Frank.",
  ["Act_E3_6B_Diner_Scripted_Max_020"] = "Llaves conseguidas. Ahora, a volver con Chloe.",
  ["Act_E3_6B_Diner_Scripted_Max_030"] = "Tiene que haber alguna evidencia que vincule a Frank con Rachel...",
  ["Act_E3_6B_Diner_Scripted_Max_040"] = "Vamos, ninja, apúrate. Antes de que Frank regrese...",
  ["Act_E3_6B_Diner_Scripted_Max_060"] = "Ay, Dios mío, tocino... Estoy lista para comer de nuevo. Pero tengo que conseguir las llaves de Frank.",
  ["Act_E3_6B_Diner_Scripted_Max_070"] = "Frank es tan acumulador que tendría que tener su reality show. Este lugar es asqueroso.",
  ["Act_E3_6B_Diner_Scripted_Max_080"] = "Ay, por favor, que ese perro no salga lastimado... o peor...",
  ["Act_E3_6B_Diner_Scripted_Max_090"] = "El perrito está ocupado ahora, pero puede volver.",
  ["Act_E3_6B_FrankRV_BaseballBat_Look01_Max_010"] = "Dudo que Frank esté practicando para unirse al equipo Cerveceros de Arcadia Bay.",
  ["Act_E3_6B_FrankRV_BeerEmptyBottle_Look01_Max_010"] = "No puedo imaginarme a Frank y Chloe bebiendo cerveza y pasando el rato juntos...",
  ["Act_E3_6B_FrankRV_BrokenKnife_Look01_Max_010"] = "Mierda, el cuchillo está roto.",
  ["Act_E3_6B_FrankRV_CHChloe2_Look01_Max_010"] = "Chloe no tiene miedo, le encanta esto.",
  ["Act_E3_6B_FrankRV_DirtyPlates_Look01_Max_010"] = "Los arquetípicos platos sucios de hombres sucios...",
  ["Act_E3_6B_FrankRV_DogFood_Look01_Max_010"] = "Creo que al perrito le gusta más su hueso...",
  ["Act_E3_6B_FrankRV_DogFood_Look02_Max_010"] = "Me voy a sentir horrible toda la vida por este pobre perro...",
  ["Act_E3_6B_FrankRV_DogPhoto_Look01_Max_010"] = "Diría que casi es chido ver a Frank posando con su perro.",
  ["Act_E3_6B_FrankRV_DogPhoto_Look02_Max_010"] = "Restriégamelo en la cara, Frank. Si se entera, seremos las primeras de la lista negra.",
  ["Act_E3_6B_FrankRV_DogPlate_Look01_Max_010"] = "\"Pompidou\"... ¿De verdad? Ese es nombre de caniche...",
  ["Act_E3_6B_FrankRV_DogPlate_Look02_Max_010"] = "Lo siento tanto, \"Pompidou\". Y también siento lo de tu nombre...",
  ["Act_E3_6B_FrankRV_DrugRelatedItem_Look01_Max_010"] = "Ese sí que es un encendedor extremo...",
  ["Act_E3_6B_FrankRV_EmptyCupboard1_Look01_Max_010"] = "Nada interesante por aquí.",
  ["Act_E3_6B_FrankRV_EmptyCupboard2_Look01_Max_010"] = "No hay más secretos...",
  ["Act_E3_6B_FrankRV_EmptyDrawer1_Look01_Max_010"] = "Cero. Nada de nada. Nada.",
  ["Act_E3_6B_FrankRV_FrankGun_Interact01_Max_010"] = "Podría lamentar esto, pero no puedo dejar que Frank lastime a alguien...",
  ["Act_E3_6B_FrankRV_FrankGun_Interact02_Max_010"] = "Podría lamentar esto, pero no puedo dejar que Chloe lastime a alguien.... o que la lastimen.",
  ["Act_E3_6B_FrankRV_FrankGun_Look01_Max_010"] = "Abracadabra, el arma de Chloe. ¿Debería devolvérsela?",
  ["Act_E3_6B_FrankRV_Hifi_Look01_Max_010"] = "¡Qué buen reproductor! Me alegro que al menos Frank trate algo con respecto...",
  ["Act_E3_6B_FrankRV_Knife_Interact01_Max_010"] = "Casi tan bueno como un juego de llaves.",
  ["Act_E3_6B_FrankRV_Knife_Look01_Max_010"] = "Es bueno saber que Frank tiene un cuchillo por aquí...",
  ["Act_E3_6B_FrankRV_Knife_Look02_Max_010"] = "En realidad, es bueno saber que Frank tiene un cuchillo...",
  ["Act_E3_6B_FrankRV_Numbers_Look01_Max_010"] = "Lástima que no tenga mi anillo decodificador de Frank Bowers...",
  ["Act_E3_6B_FrankRV_Object10_Look01_Max_010"] = "Por supuesto, a Frank le agarran los antojos...",
  ["Act_E3_6B_FrankRV_Object1_Look01_Max_010"] = "Frank debe gastar todas tus ganancias en bolsitas... Recicla, güey.",
  ["Act_E3_6B_FrankRV_Object2_Look01_Max_010"] = "¿Cómo puede alguien vivir así?",
  ["Act_E3_6B_FrankRV_Object4_Look01_Max_010"] = "Frank debe tener una razón para tener siempre un radar de policía a mano...",
  ["Act_E3_6B_FrankRV_Object5_Look01_Max_010"] = "¿Frank va a traficar en línea ahora?",
  ["Act_E3_6B_FrankRV_Object8_Look01_Max_010"] = "Ooooh, las reservas de Frank...",
  ["Act_E3_6B_FrankRV_Object9_Look01_Max_010"] = "¿Serán para Frank o las está vendiendo? ¿O ambas?",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Interact01_Max_010"] = "Chloe se va a encabronar, pero... Tengo que mostrárselo...",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look01_Max_010"] = "Estoy conociendo más de Rachel de lo que me gustaría...",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look02_Max_010"] = "¡Oh, vamos!, Rachel y el perro de Frank...",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look03_Max_010"] = "Parece que Rachel realmente era novia de Frank.",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look04_Max_010"] = "Qué chido que Rachel haya podido conducir esta bestia. Se ve feliz de verdad.",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look05_Max_010"] = "No sé si deba sentirme conmovida o perturbada...",
  ["Act_E3_6B_FrankRV_PicturesOfRachel_Look06_Max_010"] = "Hmm, parece que no todo es color rosa.",
  ["Act_E3_6B_FrankRV_SteeringWheel_Look01_Max_010"] = "Estaría chido poder pasear este carro por la ruta con Chloe...",
  ["Act_E3_6B_FrankRV_VentShaft2_Interact01_Max_010"] = "Carajo. Nada por aquí.",
  ["Act_E3_6B_FrankRV_VentShaft2_Look01_Max_010"] = "Podría hacer palanca para abrir el respiradero con la herramienta adecuada...",
  ["Act_E3_6B_FrankRV_VentShaft_Interact01_Max_010"] = "¡Mi espada abrirá cualquier portal!",
  ["Act_E3_6B_FrankRV_VentShaft_Look01_Max_010"] = "Bueno, este respiradero está medio suelto. Necesito algo para abrirlo...",
  ["Cue_E3_6B_DinerPark_AlyssaWarn_Max_010"] = "Alyssa, ¡cuidado!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_GotHurt_Alyssa_002"] = "Me encantaría hablar, Max, pero tengo que ahogarme en un charco de desgracia.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_GotHurt_Max_001"] = "Ay. ¿Estás bien, Alyssa?",
  ["Cue_E3_6B_DinerPark_CHAlyssa_IGE_Alyssa_010"] = "¡¿Mierda, en serio?!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_IGE_Alyssa_020"] = "¡Buenos reflejos, Max!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_QPhase01_Alyssa_001"] = "¡Gracias de nuevo, Max! Hablamos más tarde.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_QPhase02_Alyssa_001"] = "De todos modos, gracias por salvar otra alma en pena, Max.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_QPhase03_Alyssa_001"] = "No te culpes. Muchos están muy orgullosos de ti.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_002"] = "Gracias, Max, ojalá me hubieras podido ayudar el otro día cuando me golpearon con un balón y un rollo de papel higiénico.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_003"] = "¡Es la segunda vez que me salvas, Max! ¡Gracias!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_004"] = "Está bien, Max, esta es la tercera vez que me salvas de otra desgracia. Debes ser mi ángel guardián.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_007"] = "Ya hiciste más que suficiente cuando salvaste la vida de Kate en la azotea. Realmente eres la heroína de Blackwell, Max.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_008"] = "Te vi tratando de salvar a mi amiga Kate en esa azotea. Fuiste la única... Los otros se dedicaban a tomar fotografías.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_016"] = "¡Qué jodido! Pero eres una amiga increíble. Quiero asegurarme de que, de ahora en más, sepa cuáles son sus amigos de verdad.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_017"] = "Bueno, no lo hizo porque tenía una amiga a la que le importó lo suficiente como para ayudarla. Espero que todos en Blackwell empiecen a preocuparse por el prójimo...",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_018"] = "Bueno, todos te lo agradecemos. Estoy segura de que fue mucho estrés para ti.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_020"] = "¡No puede ser! ¡Eso es una total mierda! Vaya, tal vez deberíamos comenzar una petición...",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_021"] = "Max, deberíamos armar un grupo para ir a verla al hospital. Encontrémonos de nuevo para charlar un poco más.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_022"] = "Sí, de seguro lo fuiste. Y lo sabes. Bueno, me tengo que ir... Nos vemos, Max.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_023"] = "Tal vez podríamos tomar una foto para Kate, como un regalo... Oye, me tengo que ir, pero hablemos más tarde.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_028"] = "Todo el mundo lo vio. Estoy orgullosa de ti por ser tan valiente. Sí que eres buena onda, Max.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_029"] = "Olvídate de esa mierda. Toda la escuela te vio intentando convencerla de bajar. Pero nadie podría... Sigues siendo una heroína, Max.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_030"] = "Bueno, es difícil ser fuerte cuando toda una escuela e Internet se dedican a acosarte.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_031"] = "¡No puede ser! ¡Eso es una total mierda! Vaya, tal vez deberíamos comenzar una petición...",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_035"] = "Tenemos que juntarnos más seguido, beber un poco de vino... Me tengo que ir, pero hablemos más tarde, ¿te parece?",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_036"] = "Pero no lo hizo. No podemos retroceder y solucionarlo, Max. Nos vemos luego.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Alyssa_037"] = "Me gusta tu actitud, Max. Tenemos que juntarnos. Me tengo que ir, pero hablemos más tarde.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_001"] = "Vaya, Alyssa, ¡estuvo cerca!",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_005"] = "La próxima me aseguro que no te golpeen. Espero.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_006"] = "No me agradezcas. No hice nada fuera de lo común.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_009"] = "Me alegro de que haya bajado. Kate es una buena persona... es mi amiga, y casi logran matarla con tanto acoso.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_010"] = "No, solo soy afortunada. Si Kate hubiera querido saltar, lo hubiera hecho...",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_011"] = "Cierto. Quiero decir, nadie más hizo nada para ayudarla. Ni siquiera lo pensé.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_012"] = "Soy tal heroína que el director Wells me suspendió... todo gracias a David Madsen y los Prescott...",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_013"] = "Amén a eso.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_014"] = "Obviamente, y para Kate también. Fui solo un canal para salvar... ayudarla.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_015"] = "No te preocupes. Ya está hecho. Además, ahora tengo una excusa para tomar un chingo de fotos esta semana.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_024"] = "Kate también era mi amiga. Habría hecho cualquier cosa para salvarla.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_025"] = "Sí, lo intenté... y Kate murió.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_026"] = "Kate estaba demasiado asustada como para alzarse contra todos. Ojalá me hubiera escuchado... No fue lo suficientemente fuerte.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_027"] = "Soy tal heroína que el director Wells me suspendió... todo gracias a David Madsen y los Prescott...",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_032"] = "No es como me siento hoy, pero gracias.",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_033"] = "Tal vez ella podría...",
  ["Cue_E3_6B_DinerPark_CHAlyssa_Thanks_Max_034"] = "¡Me vale madre! Me harté de Blackwell por el momento.",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_002"] = "Ni preguntes. Primero, la nieve; luego, un eclipse... ¿Qué sigue, un tornado?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_007"] = "El clima sí que ha cambiado por aquí. Acabo de ver al pendejo Prescott teniendo un ataque en el estacionamiento...",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_008"] = "Soy un pescador, no un científico. Me doy cuenta de que la temperatura del mar está subiendo, pero esto... Esto es algo nuevo, y tal vez peor.",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_009"] = "No es el único. Si supieras lo que ocurre con los peces en Arcadia Bay... Lo siento, estoy muy encabronado como para hablar de ello. Nos vemos, niña.",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_010"] = "Si supieras lo que ocurre con los peces en Arcadia Bay... Lo siento, estoy muy malhumorado como para hablar de ello. Nos vemos, niña.",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_012"] = "Podría ser peor, podríamos sufrir uno de esos terremotos californianos.",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_013"] = "Ojalá... ya es demasiado tarde para cambiar de carrera. Nos vemos, niña.",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_015"] = "Bueno, ya que lo mencionas... ¡No hay ni un pez en Arcadia Bay!",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_017"] = "Ni uno que valga la pena pescar y comer, la neta… Salmón, trucha, lubina... todos murieron o migraron. Incluso las malditas almejas están muriendo…",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Fisherman02_019"] = "Lo siento, estoy muy malhumorado como para hablar de ello. Nos vemos, niña.",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_001"] = "¡Buenos días! ¿Cómo lo tratan los peces hoy?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_003"] = "¿No cree que podría ser algo como el cambio climático?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_004"] = "Espero que no...",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_005"] = "Me contaron que estaba pasando algo con los peces en Arcadia Bay...",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_006"] = "¿No es normal que tenga ataques?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_011"] = "¿Qué quiere decir con \"peor\"?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_014"] = "Es cierto... bueno, me siento un poco mareada ahora. ¡Espero que pesque uno enorme hoy!",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_016"] = "¿Qué? Vamos... ¿Ninguno?",
  ["Cue_E3_6B_DinerPark_CHFisherman_Phase01_Max_018"] = "Oh, Dios mío... Y...",
  ["Cue_E3_6B_DinerPark_CHFisherman_QuickPhase01_Fisherman02_001"] = "Como dije, no quiero seguir hablando de esto...",
  ["Cue_E3_6B_DinerPark_CHFisherman_QuickPhase02_Fisherman02_001"] = "No puedo hablar ahora, tengo que concentrarme en los peces.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_002"] = "Te recuerdo...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_003"] = "Bueno, sigo sin hogar. Aparte de eso, estoy fantástica. ¿Quién eres?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_005"] = "Me enteré de la chica que se suicidó en Blackwell... ¡Qué horrible!",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_006"] = "Me enteré de esa chica que casi salta de la azotea de Blackwell...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_012"] = "Ay, niña, fue su elección, no la tuya. No cargues con esa culpa.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_013"] = "¿Fuiste tú? Si tuviera una botella, haría un brindis.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_014"] = "Muchas cosas en Arcadia Bay están conectadas a Rachel...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_015"] = "Quizás estés mejor así.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_016"] = "Es un mundo triste, Max.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_021"] = "Pero eres tan joven. Ah, si pudiera retroceder y volver a tener tu edad...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_022"] = "Cuanto más poder piensas que tienes, menos tienes realmente.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_023"] = "En especial cuando se trata de otras personas...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_024"] = "Kate Marsh probablemente sintió que ya no tenía nada por que vivir... Sé lo que se siente.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_027"] = "Lo hiciste la última vez que hablamos... Ahora parece que eres tú quien necesita algo de ayuda.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_029"] = "Parece que tú necesitas algo de ayuda.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_031"] = "Seguro que soy más entrometida que tú. Las personas fingen no verme, así que yo veo a todos. Y todo.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_036"] = "Finalmente expulsaron al pendejo malcriado de la escuela de su papito...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_037"] = "Ese pendejo malcriado tiene una mala aura, como solíamos decir...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_038"] = "Cuando lo vi hoy parecía más nervioso que de costumbre...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_039"] = "Lo escuché presumiendo que había arrebatado un arma de algunos intrusos.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_043"] = "Lo vi ayer caminando sin dirección, más encabronado que de costumbre...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_044"] = "Es un cabrón apretado, pero me parece que solo busca estar ocupado.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_047"] = "Me da la impresión que sabes mucho más que yo, niña.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_050"] = "¿Te gustaría contarme lo que sea que ocultas?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_053"] = "Es demasiado tarde para que ande juzgando a otros. Además, no estás chiflada.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_054"] = "Si no deseas contarlo, no tienes por qué hacerlo. Solo soy una pordiosera sin hogar.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_056"] = "Puede ser. El aire está lleno de mala energía esta semana. Gracias por la advertencia, Max.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_HomelessWoman_057"] = "Una advertencia... cuando decidas contarme lo que sabes.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_001"] = "Hola, ¿cómo estás?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_004"] = "Max. ¿Quieres que te traiga algo del restaurante?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_007"] = "Kate Marsh. Estaba con ella... cuando saltó... Intenté salvarla, lo juro.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_008"] = "Kate Marsh. Logré convencerla de que bajara de la azotea...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_009"] = "Creo que todo se relaciona con la desaparición de Rachel Amber.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_010"] = "Fue una semana triste. Ni siquiera me importa que me expulsaran de Blackwell...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_011"] = "Fue una semana triste en Blackwell...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_017"] = "Demasiado tarde... aunque tenía el poder de cambiarlo.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_018"] = "Lo sé... Estoy empezando a darme cuenta de que no puedo cambiarlo todo...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_019"] = "Gracias. Igual, no evitó que me expulsaran de Blackwell.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_020"] = "Gracias. Ojalá tuviera una botella para usted.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_025"] = "Pero necesito saber quién más está involucrado en esto.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_026"] = "Ojalá pudiera ayudarla. De verdad.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_030"] = "Solo para conseguir algunas respuestas...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_032"] = "Frank Bowers conocía a Rachel... ¿Lo viste por aquí?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_033"] = "¿Incluso Nathan Prescott?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_034"] = "Creo que el esposo de Joyce, David, está involucrado en todo esto.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_035"] = "Solo diré esto: Tuve una visión de Arcadia Bay destruida por un tornado... De verdad.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_040"] = "No entiendo por qué todavía no lo han arrestaron.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_041"] = "También drogó a la chica que saltó.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_042"] = "También drogó a la chica que intentó saltar...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_045"] = "Porque prácticamente hice que lo expulsen de Blackwell.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_046"] = "¿Como hacerle la vida imposible a todo el mundo?",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_048"] = "Solo creo que Arcadia Bay está en problemas...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_051"] = "Siento que puedo confiar en ti tanto como confío en Chloe... y que tampoco vas a creer que estoy chiflada.",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_052"] = "No hay nada que decir...",
  ["Cue_E3_6B_DinerPark_CHHomeless_Phase01_Max_055"] = "Por favor, avísame si necesitas algo.",
  ["Cue_E3_6B_DinerPark_CHHomeless_QuickPhase01_HomelessWoman_001"] = "Gracias por advertirme de la tormenta, Max. Te avisaré si me entero de algo.",
  ["Cue_E3_6B_DinerPark_CHHomeless_QuickPhase02_HomelessWoman_001"] = "Realmente necesito estar sola. Solo vete, por favor...",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_001"] = "Hola, ¿cómo está?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_003"] = "¿Mal día en la oficina?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_004"] = "La peor. Entrevista. Jamás.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_005"] = "En realidad, quería preguntarle si ese es su padrísimo camión Needham modelo 1977 de dieciocho ruedas.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_008"] = "Ah... claro, sí, apesta...",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_009"] = "Eso apesta.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_012"] = "Espere, Kate Marsh no era ninguna perra. Sufría una gran depresión, con razones válidas. Ni siquiera la conoció, ¿verdad?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_013"] = "Entonces tal vez debería irse.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_016"] = "¿Conocía a Rachel Amber? ¿Puede contarme de ella?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_019"] = "Tomé una clase en Blackwell sobre la historia de... los camioneros. Siempre quise conducir uno de esos monstruos en la carretera.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_020"] = "Mi amiga Rachel Amber me contó de este camionazo que estaba en el pueblo porque sabía que me encanta tomar fotos de camioneros.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Max_023"] = "Ah, ¿usted también debe haberla conocido?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_002"] = "Magnífico. Fin de la entrevista.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_006"] = "Unos pendejos rompieron las vías del tren, y ahora debo esperar tres días para recibir mi carga. El tiempo es dinero para alguien como yo.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_007"] = "El trabajo ya no abunda por aquí, y tengo cuentas que pagar. El tiempo es dinero para alguien como yo.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_010"] = "Ojalá pudiera irme lo más lejos posible de la pinche Arcadia Bay. El pueblo entero se desmorona, entre la nieve, el eclipse, el suicidio de esa puta...",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_011"] = "Ojalá pudiera irme lo más lejos posible de Arcadia Bay. El pueblo entero se desmorona, entre la nieve, el eclipse, una puta que intenta suicidarse...",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_014"] = "Conozco a todos estos pendejos incapaces de Blackwell. Como esa otra perdedora que veía por aquí... Rachel.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_015"] = "Lo haría si pudiera. Hasta esa pinche rarita de Rachel me pidió una vez que la llevara a Los Ángeles...",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_017"] = "Nop. Por Dios, ¿por qué no te consigues un trabajo real en vez de comerte libros? ¡Me encantaría ver a alguno de ustedes, pendejos de Blackwell, intentar conducir mi Needham modelo 1977 de dieciocho ruedas! Ya te lo dije, fin de la entrevista.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_018"] = "¿Cómo diablos sabías eso?",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_021"] = "No lo puedo creer, una estudiante Blackwell con materia gris. La próxima que vez me salga un trabajo por aquí, te dejaré viajar conmigo. Cuídate.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_022"] = "¿Conocías a Rachel? A ella le valían madre los camioneros... o encontrar trabajo de verdad.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Phase01_Trucker_024"] = "Solo por el restaurante. Era una cazafortunas, pertenecía a California con todos esos... ya sabes... ¡Qué bueno que se fue! Pero tú puedes tomar fotos de mi camión cuando quieras. Cuídate.",
  ["Cue_E3_6B_DinerPark_CHTrucker_QuickPhase01_Trucker_001"] = "Ah, ¿te enseñan español en esa pinche escuela fresa? Ya terminé de hablar. Cambio y fuera.",
  ["Cue_E3_6B_DinerPark_CHTrucker_QuickPhase02_Trucker_001"] = "Hablemos de mi sesión de fotos más tarde. Mensaje recibido.",
  ["Cue_E3_6B_DinerPark_CHTrucker_Trucker_010"] = "¡Ey! ¡No tomes fotos, niña!",
  ["Cue_E3_6B_DinerPark_FrankRV_Chloe_010"] = "Ah, podríamos viajar por todos lados en esta bestia. ¿Nos imaginas viajando por la costa hasta Big Sur, y más allá?",
  ["Cue_E3_6B_DinerPark_GarbageSearch_Chloe_010"] = "¿Qué pedo? Asqueroso...",
  ["Cue_E3_6B_DinerPark_GarbageSearch_Chloe_020"] = "Más cosas asquerosas...",
  ["Cue_E3_6B_DinerPark_GarbageSearch_Chloe_030"] = "Maldita sea, debe haber algo de comida para ti en alguna parte…",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_010"] = "Vamos a ver la puerta. Frank se pone tan chocho que a veces se olvida de cerrarla.",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_030"] = "Ya no.",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_040"] = "Tenemos que ser ninjas camufladas...",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_050"] = "Chingado. Bueno, este es el plan. Yo voy al restaurante y distraigo a Frank. Le digo que tengo su dinero, pero que debe venir conmigo. Luego, tú apareces y rebobinas para que no me vea, y entonces le dices que debe echarle un vistazo a su casa rodante, y, una vez que tengamos la llave, rebobinas, y... eh... y...",
  ["Cue_E3_6B_DinerPark_Insertion_Chloe_070"] = "Por favor, no dejes que mi padrísimo plan se interponga en el tuyo. Voy a tratar de conseguir una galleta Scooby para distraer a su perro sarnoso...",
  ["Cue_E3_6B_DinerPark_Insertion_Max_020"] = "No puedo creer que hayas estado con él.",
  ["Cue_E3_6B_DinerPark_Insertion_Max_060"] = "Chloe, yo me encargo. Ya regreso.",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_010"] = "Debí haberlo sabido. La increíble Max Maravilla.",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_030"] = "¡Necesitarás esto, Max!",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_040"] = "En sus marcas, listos...",
  ["Cue_E3_6B_DinerPark_OpenDoor_Chloe_050"] = "...¡lanza!",
  ["Cue_E3_6B_DinerPark_OpenDoor_Max_020"] = "Jamás podría haberlo logrado sin Frank. Ahora entremos y salgamos de pedo.",
  ["Cue_E3_6B_DinerPark_ThrowMeatFence_Chloe_020"] = "Creo que ese perro es nuestra nueva perra... ¿entiendes?",
  ["Cue_E3_6B_DinerPark_ThrowMeatFence_Max_010"] = "¡Vamos, perrito! Mira lo que hay para ti.",
  ["Cue_E3_6B_DinerPark_ThrowMeatFence_Max_030"] = "Ahora puedo husmear en paz. Pero no perdamos tiempo.",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Chloe_020"] = "La carne está en la calle...",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Chloe_050"] = "Seguro que está bien, seguro... Apúrate, ahora sí que no tenemos tiempo que desperdiciar.",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Max_010"] = "¡Vamos, perrito! Mira lo que hay para ti.",
  ["Cue_E3_6B_DinerPark_ThrowMeatStreet_Max_040"] = "Ay, no. Por favor, por favor, que no hayan atropellado a ese pobre perro...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_001"] = "¿Cómo estás, Maxine? Lamento que hayas tenido que estar en la azotea con Kate cuando ella... ya sabes. Solo quiero que sepas que estamos orgullosos de ti por subir hasta allí.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_002"] = "Y aquí está, SuperMaxine. Ese es tu nuevo apodo por aquí. Lo lamento, pero te lo ganaste. Estamos muy orgullosos de ti por ayudar a que Kate bajara.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_005"] = "Me alegro de que tú representes a la Academia Blackwell.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_006"] = "No me hagas vomitar este tocino. Sabes lo que los Prescott representan...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_007"] = "No estás muy equivocada, Max. Escuché que los Prescott están por comprar varios terrenos...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_008"] = "El Sr. Prescott ayudó a mi familia una vez, hace mucho tiempo. Así que hice un trato con él... del que parece que no puedo salir. Vaya, si pudiera repetir un solo momento de mi vida... Mejor, primero termino mi desayuno.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_012"] = "A veces. Creo que están más interesados comprar grandes cantidades de tierra...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_014"] = "Preferiría estar en una ciudad normal con problemas normales... Me enferma solo pensar en ello…",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_016"] = "No por mucho. Es un bala perdida. Todos lo respetamos por haber prestado servicio, pero se entusiasma demasiado.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_019"] = "Es verdad. Estaba gritando y quejándose de un arma robada, pero dejé de escucharlo... Siempre hay alguien que quiere fastidiarlo.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_021"] = "Una pena... Horrible...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_022"] = "Y tú, por ayudarla. Ese es el tipo de espíritu escolar que necesitamos.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_024"] = "Bowers ya no es estudiante. Lamentablemente, sí representa un lado de Arcadia Bay... Quiero que te mantengas bien alejada, ¿de acuerdo? De él y de su perro rabioso...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_026"] = "Especialmente cuando el perro se transforma en un guardaespaldas rabioso. Seguro que entrenó a ese pobre animal a golpes...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_028"] = "Frank solía participar en peleas de perros. Se lo voy a reconocer: tuvo una revelación y salvó a muchos de los perros. Y se quedó con uno. Igual, sigue siendo un cabrón. Tú y esa chica Chloe deben mantenerse alejadas, ¿entiendes?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_030"] = "Dios, ¿este pueblo tiene algún secreto?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Cop_032"] = "Mira, a veces paso a visitar a los Prescott para asegurarme de que todo esté en orden... Incluido Nathan... Que quede entre nosotros, Max.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_003"] = "Gracias, oficial Berry. Sé que ustedes se ocupan de esta clase de cosas mucho más seguido que yo, pero no es algo fácil de lidiar.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_004"] = "Gracias, oficial Berry. Solo tuve suerte... y llegué a tiempo. Kate es la que importa.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_009"] = "Pensé que Nathan Prescott representaba a Blackwell.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_010"] = "¿Apoderarse de Arcadia Bay?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_011"] = "¿Proteger a Nathan?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_013"] = "¿Cree que Arcadia Bay es una ciudad extraña?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_015"] = "Siento que David Madsen representa a Blackwell.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_017"] = "Se entusiasma en ser un pendejo con Chloe y conmigo.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_018"] = "Parece entusiasmado en ayudar a encontrar a Rachel...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_020"] = "Supongo que Kate Marsh será el rostro de Blackwell durante un tiempo...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_023"] = "Según Nathan, Rachel Amber representa a Blackwell... con Frank Bowers.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_025"] = "Me contaron algo sobre Frank Bowers y su cachorro. El tipo ama a su perro...",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_027"] = "Qué asco. No hace falta apostar. ¿Dónde consiguió al cachorro?",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_029"] = "Bueno, escuché un rumor de que hacía encargos para los Prescott.",
  ["Cue_E3_6B_Diner_CHCop_Puzzle_Max_031"] = "No lo culpo por buscar trabajo adicional.",
  ["Cue_E3_6B_Diner_CHCop_QPhase01_Cop_001"] = "Hablamos luego, Max.",
  ["Cue_E3_6B_Diner_CHCop_QPhase02_Cop_001"] = "¿Qué puedo hacer por ti, Max?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_001"] = "¿Qué carajo ? ¿Por qué llevas la ropa de Rachel? ¿Eh?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_006"] = "¡Ay, qué miedo! No necesito su pequeña pieza de museo.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_007"] = "Porque ella se ve preciosa en ella, y tú te ves horrible. Apuntarme con un arma no te hace más atractiva.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_008"] = "Porque ella se ve preciosa en ella, y tú te ves bien culera. Tienes suerte de que solo te haya quitado el arma.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_010"] = "Mejor no. Me asustas, carajo.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_016"] = "¿No se supone que eres una estudiante inteligente?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_019"] = "Gracias, madrina. Pero no necesito tus favores... Y Chloe no recibirá ninguno de mí.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_020"] = "Bueno, ¡qué buen intento! Chloe puede pagar sus propias deudas.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_022"] = "¿Qué sabes tú de eso?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_024"] = "Sí, le di Nathan algunos medicamentos aunque no tenga la receta... como amigo. ¿Quién vuela a tu edad? ¡Chingón!",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_026"] = "¡Jaja! Eh, sí, claro. ¿Quieres el \"especial para colegiales\" con eso? Dios... Mira, yo no vendo nada más que botellas para que mi perro y yo podamos comer. Trabajo para ganarme la vida, no como ustedes, pendejos malcriados de Blackwell con demasiado tiempo que desperdiciar.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_028"] = "Pero nada. No vuelvas a pedirme nada nunca más. Jamás. Ahora sácate a la chingada.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_030"] = "Ah... ¿Cómo te enteraste? ¿Eh? Chloe, ¿verdad?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_032"] = "¿En serio? Sí, quiero decir, es lo que pensé. No era más que una belleza natural, ¿sabes? Espera, espera un minuto, déjame... déjame encontrarla... aquí está, júzgala por ti misma.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_035"] = "Primero, no es una actuación. Segundo, ¿quién te dijo sobre los perros?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_039"] = "No tanto como a mí. ¿Cómo puedo confiarle mi perro a una mentirosa de mierda?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_040"] = "Ni siquiera te dejaría recoger su cagada.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Frank_041"] = "Además, no te interesa la cadena, solo quieres estas llaves. Mira cómo se te dilatan las pupilas. Eres peor que un drogón, Max. Pero no vas a tener tu dosis.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_002"] = "¿Cómo sabes que es la ropa de Rachel?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_005"] = "David Madsen está buscando esa arma. Puede que vaya a visitarte a tu casa rodante...",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_009"] = "Toma tus llaves y vamos a ver tu casa rodante...",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_015"] = "¿Podrías considerar saldada la deuda de Chloe?",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_017"] = "Lo averiguarás si me haces este favor...",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_018"] = "No todo el tiempo. Pero debo intentar todo...",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_021"] = "Apuesto a que Nathan y tú podrían ir a disparar botellas como valedores... atiborrados de chochos.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_023"] = "Experiencia personal. Además, estoy en la secundaria. Los adolescentes hablan.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_025"] = "Por cierto, Frank... Me preguntaba si tenías algo de... em... \"educación superior\".",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_027"] = "Pero...",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_029"] = "Sabes, vi la foto que te dio Rachel.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_031"] = "Solo me dijo que una de las fotos favoritas de Rachel fue la que te había regalado.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_033"] = "Actúas aterrador, pero... a fin de cuentas, salvaste a todos esos perros...",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_036"] = "Es una gran historia. Eres un amante de los animales.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_037"] = "Me encantan los perros. Soy una buena paseadora... Puedo ir a buscarlo a tu casa rodante ahora mismo. Me encantan.",
  ["Cue_E3_6B_Diner_CHFrank_Puzzle_Max_038"] = "¿Puedo acariciar al cachorrito? Podría ir a buscarlo a tu casa rodante ahora mismo...",
  ["Cue_E3_6B_Diner_CHFrank_QPhase01_Frank_001"] = "Deja de usar esa ropa y déjame en paz.",
  ["Cue_E3_6B_Diner_CHFrank_QPhase02_Frank_001"] = "¿Qué chingados quieres ahora?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_002"] = "Considerando que estamos en un restaurante público, con un policía bien cerquita, no deberías publicar tanto tu muina... Prescott.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_004"] = "Papá y su dinero siempre te protegerán, y me amenazarán.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_006"] = "Eres su esclavo, ¿no?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_007"] = "Entonces dime lo que debo saber.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_010"] = "Puedo darme ese lujo. Tú no. Así que tal vez podamos llegar a un acuerdo...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_011"] = "Tal vez te podría ayudar.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_019"] = "Si lo hubiera querido, ya hubiera mencionado que sé que Frank te dio chochos recetados...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_021"] = "Tengo mis fuentes.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_023"] = "Apuesto a que Frank les dio a Rachel Amber y a ti suministros para las fiestas...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_025"] = "Lo dudo.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_026"] = "¿Según quién? ¿Frank?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_029"] = "Escucha, Nathan, me retractaré de todo lo que dije sobre ti, pero si me conectas con Frank... ¿me entiendes?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_031"] = "¿Cómo te crees que me mantengo despierta estudiando toda la noche? ¿Es un trato o no?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_033"] = "Seguro que esperabas que Kate Marsh no dijera nada...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_035"] = "¿La violaste?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_036"] = "¿La drogaste?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_039"] = "Cálmate, güey. Estamos en un restaurante...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_043"] = "Me enteré de que tu padre contrató a un policía local para mantener un ojo sobre ti y Frank Bowers... como una niñera.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_045"] = "¿Frank lo sabe? Apuesto a que su papi no puede protegerlo.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_047"] = "¿De verdad? Que no lo tuerzan a Frank...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_049"] = "¿Cómo podría olvidar un \"pacto de sangre\"?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_051"] = "No digas ni una palabra más sobre ella. O te arrepentirás. En serio.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_053"] = "¿No se suponía que mantendrías la boca cerrada sobre el pacto de sangre que Frank hizo por Rachel?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Max_055"] = "Sin embargo, Rachel Amber pasaba más tiempo con él que contigo.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_001"] = "Me estás madreando... ¿Dónde conseguiste esa ropa? Ni siquiera conoces a Rachel... ¿Qué estás tramando? ¿Eh? ¡Dímelo ya, Caulfield!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_003"] = "Ah, ¿en serio? Tú no debiste haber echado un pitazo sobre mí y acusarme ante ese estúpido director.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_005"] = "No sabes un carajo sobre mi padre ni sobre mí. ¡Nadie aquí sabe nada!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_008"] = "Ah, Max, pagarás por eso.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_009"] = "¿Por qué? Así puedes fingir que te importa, ¿eh? Alerta de spoiler: es un cabrón.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_012"] = "No te necesito para absolutamente nada, solo para que te alejes de mis asuntos, ¿te queda claro? ¡Ahora sal de mi vista!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_020"] = "¿Cómo? ¿Cómo lo sabes?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_022"] = "No te preocupes. Tú eres la que intenta ser algo que nunca será. Por lo menos fuiste lo suficientemente inteligente como para callarte el hocico en la oficina del director…",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_024"] = "Buen intento. Rachel se enfiestaba por su cuenta. Más que yo.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_027"] = "Como si tú lo supieras, virgen. Hasta ese marrano de allí sabe que Rachel se juntaba más con Frank... Quiero decir, no hables con el policía sobre eso, pendeja.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_028"] = "Todos lo saben. Hasta ese marrano de allí. Como sea. Sal de mi vista, carajo.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_030"] = "Parece que nunca siquiera tomaste una aspirina.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_032"] = "Cálmate. Es un trato. Tendrás tus suministros escolares. Solo tienes que ir a Frank y susurrarle \"educación superior\". Y te va a dar lo que quieres...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_034"] = "El idiota dice:\"¿qué?\".",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_037"] = "Eres una cabrona, Max, ¿no tienes madre para preguntarme eso? ¡Nunca la toqué y nunca lo haría! Acabas de pasar el límite de mi paciencia, pendeja...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_038"] = "Eres tan estúpida, Max. ¡Y encima también te crees tan inteligente! No me presiones, pendeja. No me deseas como enemigo, ¿te queda claro? ¿No?",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_040"] = "Está bien... además, eres mayor de edad. Puedo demandarte por difamación y hasta dejarte sin tampones. Gracias. ¡Ahora sácate a la chingada, tortillera!",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_044"] = "Mamadas. Mi papá no contrata, se apodera. Y estos marranos saben muy bien que no deben meterse en mi vida ni con mis drogas.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_046"] = "Qué lástima, qué novela triste. El tipo está metido en una chingadera rara. Mira, me dijo que una vez hizo un pacto de sangre muy raro por Rachel... Ah, olvídate de eso. En serio.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_048"] = "Con el tiempo, lo atraparán. El tipo está metido en una chingadera rara. Me dijo que una vez hizo un pacto de sangre muy raro por Rachel... Ah, olvídate de eso. En serio.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_050"] = "Si le dices algo a Frank, te juro que te joderé tanto que nunca lo olvidarás. A ti y esa puta de Chloe.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_052"] = "Ahora déjame en paz, piruja. Mantén la boca cerrada.",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_054"] = "¿Pacto de sangre? ¿Quién...? ¿Qué carajo...? Nunca le dije a nadie sobre esas chingaderas extrañas... Además, todo el mundo sabe que Frank es un mentiroso y un perdedor. Hasta Rachel lo sabía...",
  ["Cue_E3_6B_Diner_CHNathan_Puzzle_Nathan_056"] = "¿Y? Rachel quería la mercancía de Frank. Dejó que le tomara fotos... Ahora lleva la foto consigo como si ella hubiera posado por amor. Qué menso.",
  ["Cue_E3_6B_Diner_CHNathan_QPhase01_Nathan_001"] = "¿Eres tan estúpida, carajo? ¡Sal de mi vista!",
  ["Cue_E3_6B_Diner_CHNathan_QPhase02_Nathan_001"] = "¡Chingado! ¿Qué quieres ahora?",
  ["Cue_E3_6B_Diner_CHNathan_QPhaseMax_Max_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E3_6B_Diner_CHNathan_QPhaseMax_Max_001",
  ["Cue_E3_6B_Diner_DinerTV_DrHedorah_020"] = "No, pero tenemos que plantear la hipótesis de que el cambio climático es una causa parcial de este clima tan disparejo. Eso no explica todo, por supuesto. Sinceramente, no lo sabemos todavía.",
  ["Cue_E3_6B_Diner_DinerTV_DrHedorah_040"] = "Espero que veamos más patrones, así podremos obtener una plantilla atmosférica...",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_010"] = "... pero eso no explica los patrones extremos recientes del clima.",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_030"] = "Dr. Hedorah, ¿su equipo podrá brindarnos más información sobre los resultados de sus últimas pruebas?",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_060"] = "Muchos residentes de Arcadia Bay se han estado preguntando qué provoca este clima tan impredecible.",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_070"] = "Ayer tuvimos un eclipse, una tormenta de nieve hace dos días, lo que, como la mayoría de ustedes sabe, no es común en esta época del año.",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_080"] = "Para serle sincero, nunca sucedió algo así. La última vez que tuvimos una tormenta de nieve de este calibre fue hace más de cien años.",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_090"] = "Todos nos estamos preguntando qué está sucediendo en Arcadia Bay.",
  ["Cue_E3_6B_Diner_DinerTV_KBay7Host_100"] = "Por favor, no duden en llamarnos y contarnos cuáles fueron sus experiencias. Lo que crean que pueda ser. ¿Será el calentamiento global? ¿Qué es lo que causa todo este tiempo loco?",
  ["Cue_E3_6B_Diner_MeetFrank_Frank_010"] = "¿Te apareces aquí después de que casi me disparas? Sí que tienes huevos, pendeja. Pero juntarte con Chloe, jugar con pistolas y vestirte como Rachel no te hace ni chingona ni dura. ¿Qué carajo quieres?",
  ["Cue_E3_6B_Diner_MeetFrank_Frank_030"] = "Sí que tienes huevos, pendeja. Pero juntarte con Chloe, jugar con pistolas y disfrazarte de Rachel no te hace ni chingona ni dura. ¿Qué carajo quieres? Si me tomas una fotografía, romperé tu maldita cámara en pedazos.",
  ["Cue_E3_6B_Diner_MeetNathan_Max_020"] = "Ah...",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_010"] = "¿Rachel? ¿Qué mierda?",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_030"] = "Ah, mira, \"Max Amber\"... Linda ropa. Se ve horripilante en ti. Espero que no me estés siguiendo. Ya tienes suficientes problemas por haber hecho despedir a David...",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_040"] = "Ah, mira, \"Max Amber\". Linda ropa. Por cierto, gracias por hacer que me expulsen, puta cursi. Tienes suerte de que estemos en un lugar público...",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_050"] = "Ah, mira, \"Max Amber\". ¿Este es tu disfraz de \"punketa\" ahora que te suspendieron? Gracias por tratar de meterme en problemas, perra hipócrita...",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_060"] = "Ah, mira, \"Max Amber\". ¿Este es tu disfraz de \"punketa\" ahora que te suspendieron? Ya estás metida en suficientes problemas con David Madsen...",
  ["Cue_E3_6B_Diner_MeetNathan_Nathan_070"] = "Ah, mira, \"Max Amber\". ¿Este es tu disfraz de \"punketa\"? ¡Qué chido fue verte ponerte en contra de tu \"héroe cotidiano\" Jefferson!",
  ["Cue_E3_6B_Diner_SpillFood_Frank_020"] = "Me estaba comiendo los frijoles, ¿estás zafada? ¡ME ESTABA COMIENDO ESOS FRIJOLES!",
  ["Cue_E3_6B_Diner_SpillFood_Max_010"] = "Comes como un cerdo. Prueba comer del suelo.",
  ["Cue_E3_6B_Diner_TakeKeys_Frank_020"] = "¡No acabas de hacer eso...!",
  ["Cue_E3_6B_Diner_TakeKeys_Frank_030"] = "¡Devuélveme mis llaves, perra!",
  ["Cue_E3_6B_Diner_TakeKeys_Frank_040"] = "¡Devuélveme las llaves ahora!",
  ["Cue_E3_6B_Diner_TakeKeys_Max_010"] = "Me temo que voy a tener que tomar tus llaves ahora, pendejo.",
  ["Cue_E3_6B_Diner_ThrowWater_Frank_020"] = "¡Voy a matarte!",
  ["Cue_E3_6B_Diner_ThrowWater_Max_010"] = "Solo quería saber qué pasaba si hacía esto.",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_010"] = "Qué pinche conexión que hay aquí. Debe tomarle días descargar porno.",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_030"] = "Epa, ¿qué chingados está haciendo con el perro...?",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_050"] = "Jamás hubiera creído que se pondría una collar y una máscara peluda...",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Chloe_070"] = "Max, nunca me dijiste que tomaste fotos de Frank in fraganti...",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_020"] = "Qué asco.",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_040"] = "Basta.",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_060"] = "¡Eres tan tonta!",
  ["Cue_E3_6B_FrankRV_ChloeComputer_Max_080"] = "Ni siquiera voy a oírte.",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_010"] = "Me enferma que Rachel haya posado así para Frank... o que le haya escrito cartas de amor... ¡No puedo creer que se estaba cogiendo a Frank! ¡Rachel me mintió en la cara! ¿Por qué no dijo nada?",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_030"] = "¿Qué clase de amiga era? Solo otra persona que me traiciona. ¿Por qué todos en mi vida terminan por defraudarme? Mi padre muere, tú me abandonas, mamá decide casarse con ese hijo de la chingada... y ahora Rachel me traiciona…",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_070"] = "¡Mamadas!, ¿quién no lo hizo? ¡Ojalá se vayan todos al carajo!",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Chloe_080"] = "Mamadas. ¡Encima defendiste al acosador de mi padrastro! ¡Ojalá se vayan todos al carajo!",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Max_020"] = "Porque sabía cómo ibas a reaccionar.",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Max_040"] = "Chloe, Rachel está desaparecida. Nadie te traicionó.",
  ["Cue_E3_6B_FrankRV_ChloeDisgusted_Max_090"] = "¡Chloe!",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Chloe_020"] = "¿un cuarto de bacha hermosa?",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Chloe_030"] = "Ah, eres lo máximo, Max. Gracias. Me siento mucho mejor ahora.",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Chloe_050"] = "Sí, claro, estoy en ello.",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Max_010"] = "Tengo un regalo horrible para ti...",
  ["Cue_E3_6B_FrankRV_GiveGunToChloe_Max_040"] = "Será mejor que se la devuelvas a David de inmediato.",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_010"] = "¡A la chingada! Y yo que pensaba que mi habitación era una porquería.",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_030"] = "Frank tendrá sus problemas, pero no es un psicópata...|Por lo menos, eso creía hasta que lo vi con el brazalete de Rachel.",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_040"] = "Ahh, ¡podríamos viajar a todos lados en esta maravilla, como Walter y Jesse! ¿Nos imaginas viajando por la costa hasta Big Sur, California, y más allá?",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_070"] = "Lo sé. Solo sueño despierta.",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Chloe_080"] = "Revisa un poco, mientras, yo hackeo esta computadora para ver si puedo obtener información.",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Max_020"] = "Tú no eres una traficante psicópata.",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Max_050"] = "Sí, causaríamos estragos por la carretera. Y probablemente querrías que te besara de nuevo... Chloe, estamos apuradas. Necesitamos pistas sobre Rachel.",
  ["Cue_E3_6B_FrankRV_InsideRV_Insertion_Max_060"] = "Sí, causaríamos estragos por la carretera. Y me desafiarías a conducirlo, como me retaste a besarte... Chloe, estamos apuradas. Necesitamos pistas sobre Rachel.",
  ["Act_E3_7A_CampusA_BeforeMeetingMark_Max_010"] = "Necesito tomarme un descanso de la montaña rusa que es Chloe... Y solo quiero ayudarla...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_001"] = "Max, ¿puedo hablar contigo un momento?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_004"] = "Solo quería ver cómo estabas.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_007"] = "Lo sé. Realmente siento mucho lo de Kate, y que hayas tenido que presenciarlo. Si lo deseas, hay consejeros que pueden ayudarte.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_008"] = "Solo quería recordarte lo orgullosos de ti que estamos todos por haber ayudado a Kate.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_011"] = "Eres realmente modesta, Max. Sin contar las selfis. Pero date un poco de crédito. Oye, ¿estás bien?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_012"] = "¿Cuándo me acusaste de hacer llorar a Kate?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_014"] = "Puede que seas la estudiante más entrometida en la historia de Blackwell.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_015"] = "Max, si yo estuviera tan confundido como tú, probablemente habría hecho lo mismo. Pero, sinceramente, solo intentaba ayudar a Kate.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_016"] = "¿En serio, Max? Me estaba agotado con lo del concurso. Si piensas que soy un artista pretencioso por lo que viste aquí, imagínate lo que seré en San Francisco... Aun así, sigo deseando que ganes tú.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_020"] = "¿Quién necesita un sistema de vigilancia cuando se tiene a Max Caulfield y su lente? Y no es de tu incumbencia.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_021"] = "Max, no soy un \"héroe cotidiano\". Solo traté de ayudar a Kate, pero ella no quería que la aconsejara, ¿entiendes?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_023"] = "Espero que eso no se considere como un defecto fatal... No querría privar de tu visión al mundo del arte.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_024"] = "El remordimiento y la nostalgia pueden ser una combinación peligrosa. No se puede cambiar el pasado, Max. Uno debe aceptar las decisiones que tomó y \"seguir adelante\". Con esa frase, me retiro, y que se cierre el telón.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_025"] = "¿Te refieres a acusar a Nathan Prescott de drogar a Kate?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_026"] = "¿Te refieres a hacer que expulsaran Nathan Prescott?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_029"] = "Ya que también lo denunciaste por portar un arma de fuego, quiero que tengas con cuidado por aquí. No quiero asustarte.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_030"] = "Bueno, creo que Nathan ladra mucho, pero no muerde. No dejes que te asuste.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_032"] = "¿Cuándo acusaste a David Madsen de ser un bravucón con Kate?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_033"] = "¿Te refieres a que David Madsen perdió sus privilegios en Blackwell?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_036"] = "Estoy completamente de tu lado; como imaginarás, no soy fanático de su trabajo. No dejes que te asuste.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_037"] = "Porque tienes un buen corazón, Max. Y no debes siente culpable de eso. Pero no desperdicies ese sentimiento en Madsen. Perdona mi lenguaje, pero es un pinche cabrón. No dejes que te asuste.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_043"] = "Una vez que vuelvas de tu suspensión, vamos a hablar sobre tu futuro en el mundo de la fotografía, ¿te parece bien?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Jefferson_044"] = "Pronto debemos hablar en serio sobre tu futuro en el mundo de la fotografía, ¿te parece?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_003"] = "Ah, suena bien, Sr. Jefferson.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_005"] = "Gracias, pero la verdad es que no hice demasiado... Ella solo necesitaba alguien a su lado...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_006"] = "Estoy bien. Es difícil concentrarme en algo luego de lo que pasó...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_009"] = "No... pero no sé por qué lo hice...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_010"] = "Es solo que me siento mal por lo que pasó ayer en la oficina del director de ayer...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_013"] = "Sí... Y me siento de mierda porque lo sacaron del concurso Héroes Cotidianos. ¿Ahora me odia?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_017"] = "Lo sé, Sr. Jefferson. Sin embargo, ahora la idea de una carrera en fotografía parece tan distante como San Francisco... No tengo esa confianza.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_018"] = "También los vi a usted y a Victoria conversando anoche...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_019"] = "¿Cómo intentó ayudar a Kate? Se escapó llorando...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_022"] = "Lo sé, lo sé, es una mala costumbre.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_031"] = "Demasiado tarde. No siempre soy tan valiente.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_034"] = "Sí. A pesar de que realmente lo hizo.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_035"] = "Se lo merecía. Entonces, ¿por qué me siento culpable?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_038"] = "Ah, ¿se refiere a mis tontas selfis retro? El mundo del arte no haría más que reírse.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_039"] = "¿Qué \"visión\"?",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_040"] = "Yo tampoco. Solo que parece otro mundo.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_042"] = "Es tan difícil para mí ver el futuro cuando no puedo dejar de mirar hacia atrás...",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_045"] = "Sí. Lo sé. Ahora sé que va a venir a buscarme.",
  ["Cue_E3_7A_CampusA_CHJefferson_JeffersonCrossMax01_Max_046"] = "Él drogó a Kate. Lo sé.",
  ["Cue_E3_7A_CampusA_SmallTalk_Chloe_010"] = "No importa, Max. Mi vida claramente no es digna de tu valioso tiempo...",
  ["Cue_E3_7A_CampusA_SmallTalk_Chloe_020"] = "No puedes hacer nada, Max. A menos que puedas rebobinar cinco años para salvar a papá... Que tengas un buen día.",
  ["Cue_E3_7A_CampusA_SmallTalk_Chloe_030"] = "No puedes hacer nada, Max. A menos que puedas rebobinar cinco años para salvar a papá... Que tengas un buen día en la escuela.",
  ["Cue_E3_7B_MaxRoom_Insertion_Max_010"] = "Chloe, me gustaría poder rebobinar hasta este día y cambiar todo...",
  ["Cue_E3_7B_MaxRoom_Insertion_Max_020"] = "Ay, Dios mío. ¿Qué está pasando?",
  ["Cue_E3_7B_MaxRoom_PolaRewind_Chloe_010"] = "¡No antes de que la vea! ¡Ya conoces las reglas, papá!",
  ["Cue_E3_7B_MaxRoom_PolaRewind_Chloe_020"] = "¿Quieres decir hot cakes?",
  ["Cue_E3_7B_MaxRoom_PolaRewind_Chloe_030"] = "Max, dile...",
  ["Cue_E3_7B_MaxRoom_PolaRewind_PolarewindVoices_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E3_7B_MaxRoom_PolaRewind_PolarewindVoices_010",
  ["Cue_E3_7B_MaxRoom_PolaRewind_William_010"] = "¿Quién quiere ayudarme a hacer crepas?",
  ["Cue_E3_7B_MaxRoom_PolaRewind_William_020"] = "En Francia, las llaman \"crêpes\".",
  ["Cue_E3_7C_CHouseFront_HouseReveal_Max_010"] = "Vamos... Cálmate...",
  ["Cue_E3_7C_CHouseFront_HouseReveal_Max_020"] = "De ninguna manera...",
  ["Cue_E3_7C_CHouseFront_HouseReveal_Max_040"] = "No, nunca le haría eso a Chloe...",
  ["Cue_E3_7C_CHouseFront_HouseReveal_William_030"] = "¡Max Caulfield! Tomando un descanso tras arrasar con Seattle... Pensamos que nunca te volveríamos a ver una vez que conocieras la gran ciudad.",
  ["Cue_E3_7C_CHouseFront_HouseReveal_William_050"] = "Hablando del rey de Roma... Sé que se moría por verte. Espera.",
  ["Cue_E3_7C_CHouseFront_HouseReveal_William_060"] = "Chloe, ¡tienes visitas!",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF1_010"] = "No es que Blackwell sea una escuela tan diversa.",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF1_030"] = "Se ven más Pies Grandes que minorías...",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF2_020"] = "No lo sé. Hay muchos tipos diferentes de personas aquí.",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF3_040"] = "¡Eres una cualquiera! ¡Sabía que te engancharías con ese perdedor!",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF4_050"] = "Escuché que las fiestas del club Vortex son salvajes.",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF6_090"] = "Todos mis amigos en Los Ángeles me dijeron que Oregón iba a ser frío y húmedo todos los días. Pero hace 24 °C, y no llovió ni una vez este verano. ¿Será el cambio climático?",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenF7_100"] = "No, son las personas de Oregón tratando de deshacerse de los californianos.",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM1_010"] = "Odio esa clase. Es tan aburrida.",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM2_020"] = "Te pone una marca si estás mirando tu teléfono.",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM3_030"] = "No voy a pagar 150 dólares por un concierto.",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM3_130"] = "Los espejos convexos a veces se llaman espejos convergentes... una imagen es la ubicación en el espacio donde la luz se desvía...",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM4_040"] = "¡Amigo, la tarifa del servicio es como la mitad de eso!",
  ["Cue_E3_7D_CampusA_AnotherReality_CitizenM7_090"] = "Por eso se ríe tanto.",
  ["Cue_E3_7D_CampusA_AnotherReality_Courtney_010"] = "Creo que Max está por las nubes...",
  ["Cue_E3_7D_CampusA_AnotherReality_Courtney_030"] = "Nadie me escuchó cuando dije que no deberíamos dejarla entrar al Vortex...",
  ["Cue_E3_7D_CampusA_AnotherReality_Courtney_050"] = "Me vale madre, perra.",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_020"] = "Max, nunca Maxine.",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_035"] = "... Lo siento. Debo irme.",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_040"] = "Warren... ¿Stella y él, juntos?",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_050"] = "Oye, Warren... Stella...",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_060"] = "Victoria es mi mejor amiga... Warren cree que soy un bicho raro...",
  ["Cue_E3_7D_CampusA_AnotherReality_Max_070"] = "¡Oh, no... esto está de la chingada! ¿Qué más cambié? ¡Chloe!",
  ["Cue_E3_7D_CampusA_AnotherReality_Taylor_020"] = "Está actuando tan rara, o sea... ¿Estás bien, Max?",
  ["Cue_E3_7D_CampusA_AnotherReality_Taylor_040"] = "Courtney, no quieres que nadie entre en el club.",
  ["Cue_E3_7D_CampusA_AnotherReality_Taylor_060"] = "Chida. Tal vez Max está loca...",
  ["Cue_E3_7D_CampusA_AnotherReality_Victoria_010"] = "Hola, Tierra a Maxine, ¿estás ahí?",
  ["Cue_E3_7D_CampusA_AnotherReality_Victoria_030"] = "Lo sé, lo siento, Mad Max. No estás enojada conmigo, ¿no? ¿Cierto? ¿Quieres que vayamos al baño y fumemos la pipa de la paz?",
  ["Act_E3_8A_Kitchen_CHCloeKitchen_Look02_Max_010"] = "Chloe se ve tan feliz y despreocupada, carajo... y no va a durar mucho así a menos que cambie las cosas.",
  ["Act_E3_8A_Kitchen_CHWilliamKitchen_Look01_Max_010"] = "Quiero a William como si fuese de mi propia familia... No voy a dejar que muera hoy. No lo haré.",
  ["Act_E3_8A_Kitchen_CHWilliamKitchen_Look02_Max_010"] = "Es tan extraño ver a William vivo de nuevo... Se ve igual... pero tan distante...",
  ["Act_E3_8A_Kitchen_ChloeMagazine1_Look01_Max_010"] = "Vaya, aún recuerdo cuando Chloe leyó esto... pero no después de hoy.",
  ["Act_E3_8A_Kitchen_Note2_Look01_Max_010"] = "Lo había olvidado... El faro de nuevo...",
  ["Act_E3_8A_Kitchen_Polaroids_Look01_Max_010"] = "Sé que ya vi esas fotos...",
  ["Act_E3_8A_Kitchen_StashSink_Look01_Max_010"] = "Podría esconder las llaves en los platos sucios...",
  ["Act_E3_8A_Kitchen_Table_Interact01_Max_010"] = "Mierda, las llaves no están aquí.",
  ["Act_E3_8A_Kitchen_Table_Look01_Max_010"] = "¡Qué relajo que hicimos! Recuerdo aquellos dibujos chidos que dibujé con Chloe...",
  ["Act_E3_8A_Kitchen_WilliamCamera_Max_010"] = "Se puede notar el vínculo entre Chloe y su padre... el amor. Está sí que es una foto.",
  ["Act_E3_8A_LivingRoom_ChloeMagazine2_Look01_Max_010"] = "Chloe estaba tan loca por el manga... ¡qué cabello!",
  ["Act_E3_8A_LivingRoom_FamilyPortrait_Look01_Max_010"] = "Mi familia nunca se tomó fotos tan divertidas...",
  ["Act_E3_8A_LivingRoom_Graffiti_Interact01_Max_010"] = "Es demasiado obvio, pero no hay muchas opciones..",
  ["Act_E3_8A_LivingRoom_Graffiti_Look01_Max_010"] = "Podría dejar un mensaje en este pasado y ver si está en el futuro...",
  ["Act_E3_8A_LivingRoom_Note01_Max_010"] = "Joyce ama tanto a William.",
  ["Act_E3_8A_LivingRoom_NotePadWithPhoneNumbers_Look01_Max_010"] = "¡Sí! ¡Aquí está el número de Two Whales! Ahora puedo advertir a Joyce.",
  ["Act_E3_8A_LivingRoom_Object3_Look01_Max_010"] = "Ah, sí, echo de menos las noches de cine que pasábamos aquí, con galletas y palomitas...",
  ["Act_E3_8A_LivingRoom_Object4_Look01_Max_010"] = "Sé que nunca hicieron ese gran viaje.",
  ["Act_E3_8A_LivingRoom_PhonePowerPlug_Interact01_Max_010"] = "¡Bum! ¡Desconectada!",
  ["Act_E3_8A_LivingRoom_PhonePowerPlug_Look01_Max_010"] = "¡Ahh! Si desconecto el teléfono, ¡William no podrá recibir ninguna llamada!",
  ["Act_E3_8A_LivingRoom_Phone_Look01_Max_010"] = "Podría llamar a Joyce al restaurante Two Whales y advertirle... ¡Si tan solo tuviera el número!",
  ["Act_E3_8A_LivingRoom_Phone_Look02_Max_010"] = "Max, tienes el número, así que llame Joyce, ¡ahora!",
  ["Act_E3_8A_LivingRoom_SnowDoe_Look01_Max_010"] = "Esa venada de nieve está genial...",
  ["Act_E3_8A_LivingRoom_SnowDoe_Look02_Max_010"] = "¡Por supuesto! ¡La venada de nieve le pertenecía a William!",
  ["Act_E3_8A_LivingRoom_WilliamCap_Interact01_Max_010"] = "¡En el blanco!",
  ["Act_E3_8A_LivingRoom_WilliamCap_Look01_Max_010"] = "¿Por qué las llaves estarían bajo una gorra?",
  ["Act_E3_8A_LivingRoom_WilliamCoat_Interact01_Max_010"] = "Mierda. No están las llaves.",
  ["Act_E3_8A_LivingRoom_WilliamCoat_Look01_Max_010"] = "Rápido, revisa en el interior del abrigo de William.",
  ["Act_E3_8A_Polarewind_Scripted_Max_010"] = "Qué sucede aquí... ¡William está aquí! Y Chloe es tan solo una niña... ¿Retrocedí tanto en el tiempo?",
  ["Act_E3_8A_Polarewind_Scripted_Max_025"] = "Tengo 18 años, pero en el cuerpo la Max de 13 años... ¿Cómo?",
  ["Act_E3_8A_Polarewind_Scripted_Max_030"] = "Entonces, si llego a cambiar algo aquí, ¿estaría cambiando todo el pasado y el futuro?",
  ["Act_E3_8A_Polarewind_Scripted_Max_040"] = "Debo intentarlo, debo hacerlo... Estoy aquí para utilizar este poder y salvar a William. Por Chloe...",
  ["Act_E3_8A_Polarewind_Scripted_Max_070"] = "¡Recuerda que estás aquí por una razón! ¡Piensa, maldita sea!",
  ["Act_E3_8A_Polarewind_Scripted_Max_090"] = "Tengo que evitar que William conduzca su carro hoy.",
  ["Act_E3_8A_Polarewind_Scripted_Max_130"] = "Vaya, se ve todo borroso aquí. Como que no puedo salir de los límites de la fotografía...",
  ["Act_E3_8A_Polarewind_Scripted_Max_160"] = "Mierda, ¡tengo que esconder las llaves en un lugar donde William no pueda oír el estúpido bíper!",
  ["Act_E3_8A_Polarewind_Scripted_Max_180"] = "La casa de Chloe era tan animada cuando William estaba vivo...",
  ["Act_E3_8A_Polarewind_Scripted_Max_190"] = "Este es el momento más extraño de mi vida... nada parece real... pero lo es.",
  ["Act_E3_8A_Polarewind_Scripted_Max_210"] = "Cuidado, Max, ¡William puede verte sin problemas!",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_020"] = "Mamá dijo que depende.",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_040"] = "Entonces, ¿cuántos huevos?",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_060"] = "Claro, como si tú fueras el cocinero aquí.",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_Chloe_080"] = "Se lo diré.",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_010"] = "¿Recuerdas cuántos huevos?",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_030"] = "Es verdad.",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_050"] = "No te atrevas a cuestionar al chef.",
  ["Cue_E3_8A_Kitchen_CookingSmallTalk_William_070"] = "Lo soy cuando tu mamá no está.",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_020"] = "¡Max necesita más harina en el rostro!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_050"] = "¡Toma un primer plano de Max!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_070"] = "¡Oblígame! ¡Te ves graciosísima!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Chloe_090"] = "\"¡Leche!\".",
  ["Cue_E3_8A_Kitchen_FocusPicture_Max_030"] = "¡Ni siquiera puedo ver!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Max_060"] = "¡Basta, Chloe!",
  ["Cue_E3_8A_Kitchen_FocusPicture_Max_100"] = "¡Odio como salgo en las fotos!",
  ["Cue_E3_8A_Kitchen_FocusPicture_William_010"] = "Vamos, niñas, ¡hora de una foto!",
  ["Cue_E3_8A_Kitchen_FocusPicture_William_040"] = "¡Pareces un fantasma!",
  ["Cue_E3_8A_Kitchen_FocusPicture_William_080"] = "Vamos, ¡digan whisky!",
  ["Cue_E3_8A_Kitchen_MaxPhoto_Chloe_020"] = "¡Hazme famosa!",
  ["Cue_E3_8A_Kitchen_MaxPhoto_Max_010"] = "Ahora me toca a mí usar la cámara... ¡Posa para mí!",
  ["Cue_E3_8A_Kitchen_MaxPhoto_William_030"] = "¡Solo hazme ver joven!",
  ["Cue_E3_8A_Kitchen_WarnChloe_Max_010"] = "Mira, no dejes que tu papá use el carro hoy. Sé que suena raro, pero, por favor, debes creerme, algo terrible sucederá si lo hace. ¡Debes evitar que conduzca a cualquier lado!",
  ["Cue_E3_8A_Kitchen_WilliamFindingkeys_William_010"] = "¡Ajá! ¡No se pueden esconder de mí por siempre!",
  ["Cue_E3_8A_LivingRoom_ChloeDial_Chloe_020"] = "Lo que quieras, friki. ¿Cómo vas a decir algo así sobre papá?",
  ["Cue_E3_8A_LivingRoom_ChloeDial_Chloe_040"] = "Entonces tú detenlo, SuperMax.",
  ["Cue_E3_8A_LivingRoom_ChloeDial_Max_030"] = "No estoy bromeando...",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_020"] = "Algún día papá obtendrá una de esas computadoras ultramodernas.",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_050"] = "¡No antes de que la vea! ¡Ya conoces las reglas, papá!",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_060"] = "Max, dile... Epa, oye, te ves totalmente pálida. ¿Estás bien?",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_090"] = "Bueno, quizás permita que esta entre en el álbum de fotos familiar...",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_110"] = "Pero no la cocinera... guiño guiño, papá.",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_130"] = "¿Quieres decir hot cakes?",
  ["Cue_E3_8A_LivingRoom_Insertion_Chloe_150"] = "Oui. ¡Me ofrezco para romper los huevos!",
  ["Cue_E3_8A_LivingRoom_Insertion_Max_070"] = "Sí, es que... Ah, sí, estoy bien...",
  ["Cue_E3_8A_LivingRoom_Insertion_William_030"] = "Espero que el flash no te haya asustado, Max.",
  ["Cue_E3_8A_LivingRoom_Insertion_William_040"] = "Esta se queda para la posteridad.",
  ["Cue_E3_8A_LivingRoom_Insertion_William_080"] = "Dime, Chloe, ¿vive o muere?",
  ["Cue_E3_8A_LivingRoom_Insertion_William_100"] = "Eres lo máximo.",
  ["Cue_E3_8A_LivingRoom_Insertion_William_120"] = "Sí, no podemos pretender que tu mamá se apresure a volver y nos prepare algo feúcho. ¿Quién quiere ayudarme a hacer crêpes?",
  ["Cue_E3_8A_LivingRoom_Insertion_William_140"] = "En Francia los llaman \"crêpes\". Y todo buen chef francés necesita de sus ayudantes. Si desean tomar el desayuno.",
  ["Cue_E3_8A_LivingRoom_MaxPhonDiner_Max_010"] = "Eh... hola... hola, ¿podría hablar con Joyce Price?",
  ["Cue_E3_8A_LivingRoom_MaxPhonDiner_Max_020"] = "Oh, ¿se fue? Carajo. Eh... ¿está segura? Entiendo, lo siento. Gracias.",
  ["Cue_E3_8A_LivingRoom_MaxPickUpPhone_Max_010"] = "Perdón, número equivocado...",
  ["Cue_E3_8A_LivingRoom_MaxPickUpPhone_William_020"] = "Max, vamos, sabes mentir mejor.",
  ["Cue_E3_8A_LivingRoom_MaxPickUpPhone_William_030"] = "¿Hola?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_Chloe_020"] = "¡Otro dólar para el frasco de malas palabras!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_010"] = "Mierda, ¿dónde están las llaves?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_030"] = "¡Me estás dejando en bancarrota!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_040"] = "Sabía que esto iba a ser útil... ¿Cómo llegaron aquí las llaves?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_050"] = "Sabía que esto iba a ser útil... ¿Cómo carajo llegaron aquí las llaves?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepKeys_William_060"] = "Sabía que esto iba a ser útil... ¿Cómo llegaron aquí las llaves hasta aquí?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Chloe_090"] = "Max, estás comportándote tan extraña. ¿Te sientes bien?",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Max_040"] = "Puedes tomar el autobús, ¿verdad? ¡La parada está justo en la esquina!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Max_060"] = "¡Oh, sí, el autobús es genial!|Viene cada 15 minutos, y tiene mucho espacio para Joyce y las compras, y además, ayudará al medio ambiente...",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_Max_100"] = "Chloe, soy... lo máximo. ¡Somos lo máximo!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_010"] = "Sé que tenía las llaves por aquí... Lo sé...",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_020"] = "Me olvidé de ti, amiguito... ¡Liberen las llaves!",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_030"] = "Por supuesto. Es la última vez que compro algo de la tienda de espías...",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_050"] = "Sí, es cierto. Bien pensado, Max.",
  ["Cue_E3_8A_LivingRoom_WilliamBeepNoKeys_William_070"] = "Ya me convenciste. Emprenderé mi travesía hasta la parada del autobús. A Joyce le encantará.",
  ["Cue_E3_8A_LivingRoom_WilliamKeysOnMax_Max_050"] = "Eh, solo estaba..., eh ¿está seguro que Joyce ya está lista? Eh, mejor... mejor esperemos un poco... Yo, eh... Lo siento. Aquí...",
  ["Cue_E3_8A_LivingRoom_WilliamKeysOnMax_William_040"] = "Max, este no es un buen momento para bromas. Las llaves, vamos.",
  ["Cue_E3_8A_LivingRoom_WilliamKeysOnMax_William_060"] = "Algún día me vengaré de esto.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeysMobilePhone_William_010"] = "¡Hola, amor! No tengo ni idea por qué el teléfono de casa no sonaba. Solo preparamos un desayuno fabuloso con Chloe y Max. Vamos a trabajar en el Two Whales... Oh, no sabía que ibas a buscar las compras. Por supuesto que iré a recogerte. Ahora tengo una excusa para tomar un mocachino. Ya salgo para ahí. Te quiero.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_030"] = "Eres ridículo.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_050"] = "¡Papá!",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_070"] = "¡Nunca me abandonará!",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_Chloe_100"] = "¡Otro dólar para el frasco de malas palabras!",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_010"] = "¡Hola, amor! Preparando un desayuno fabuloso con Chloe y Max. Vamos a trabajar todos en el Two Whales...",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_015"] = "¿Qué? Oh, no sabía que ibas a buscar las compras. Por supuesto que iré a recogerte. Ahora tengo una excusa para tomar un mocachino. Ya salgo para ahí. Te amo...",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_020"] = "Discúlpenme, señoritas, debo partir al rescate de vuestra reina de Sav-Mart.|Traerá consigo muchos manjares para vuestro deleite.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_040"] = "Un día me lo vas a agradecer.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_045"] = "Cierren con llave cuando salga, jueguen sano,|e intenten no destruir demasiado la casa.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_060"] = "Si se portan bien, tu mamá me prometió que esta noche nos iba a sorprender con su salmón de fama mundial y un delicioso pastel de chocolate para el postre. Max, te quedas a cenar, ¿verdad?",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_080"] = "Eso significa que estaremos todos.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_090"] = "Carajo, ¿dónde están mis llaves?",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_110"] = "Quieres decir, tu fondo para la universidad... las llaves, por favor.",
  ["Cue_E3_8A_LivingRoom_WilliamNeedCarKeys_William_140"] = "Y sepan que la cata de vinos está terminantemente prohibida para Chloe y Max...",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_Max_010"] = "Eh, Sr. Price, en caso de que piense usar su carro... Me enteré que hay un tránsito horrible, y hay muchas carreteras cerradas por obras... Así que no debería conducir en absoluto.",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_Max_030"] = "En realidad, no... Solo sé que no es buen momento para conducir y eso... Entonces, entonces...",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_William_020"] = "Max, eres la guerrera de la carretera. Te prometo que, a cualquier lugar que vaya, conduciré como si me tuvieran a prueba. ¿Razonable?",
  ["Cue_E3_8A_Polarewind_BeforeJoycecall_William_040"] = "Y, como obviamente eres mi GPS personal, ya me haces sentir más seguro. ¡Así que quita esa cara de preocupada, Max!",
  ["Cue_E3_Previously_Bink_Voices_Max_010"] = "Anteriormente en Life Is Strange…",
  ["Cue_E3_Previously_Bink_Voices_Max_020"] = "En el episodio anterior de Life Is Strange…",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_002"] = "No quiero que nadie me tenga lástima.|Para eso estoy yo... junto con mis padres.|Mi papá aún se siente culpable por comprarme el auto.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_003"] = "Nunca lo hemos hecho, ¿verdad?|No hay mucho que decir. Un idiota en una SUV se cerró y salí disparada hacia una zanja.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_005"] = "Después de la nieve y el eclipse, es más como el fin del mundo.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_006"] = "¿Por darme el auto híbrido que quería de cumpleaños? No, culpo al idiota que se cerró y me sacó hacia la zanja.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_009"] = "Vi todo en cámara lenta. Sentí cómo se me destrozaba la espalda... Fue lo último que sentí en el cuerpo. Cuando desperté en el hospital, no podía mover un solo músculo.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_010"] = "No, nunca. Solo leí sobre ella en las noticias. Ni siquiera sabía su nombre. ¿Tú sí?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_011"] = "No sé su nombre, solo lo vi en las noticias. Pobre de su familia...",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_018"] = "Tengo más tiempo libre que tú... además, me gusta la ciencia. Pero nada de esto tiene sentido.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_019"] = "Me gustaría pensar igual... pero no guardo muchas esperanzas estos días.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_020"] = "No te quiero deprimir. Es que parece que Arcadia Bay se está yendo al diablo.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_022"] = "Pasar tiempo contigo me hace sentir como una niña de nuevo. Ni siquiera te imaginas...",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Chloe_025"] = "No digas nada. Me alegra que nos hayamos visto de nuevo.|Pude haber desaparecido por completo, como aquella chica de Blackwell.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_001"] = "Eres una verdadera sobreviviente, Chloe. Sé que tienes que lidiar con muchas cosas.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_004"] = "¿Cómo te sientes para hablar del accidente?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_007"] = "No culpas a William, ¿o sí?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_008"] = "¿Recuerdas... todo?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_012"] = "¿Te refieres a Rachel Amber? ¿Cuándo fue la última vez que hablaste con ella?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_013"] = "¿Cuál chica?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_014"] = "Es un mundo muy diferente de cuando éramos pequeñas, ¿no lo crees?",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_015"] = "¿Eso piensas? No me he mantenido al tanto.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_016"] = "Puede ser, pero... quiero pensar que aún podemos mejorar las cosas.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_017"] = "No digas eso.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_021"] = "Sé que las cosas parecen fuera de control, pero... mientras estemos juntas, no tengo miedo.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_023"] = "Escucha, Chloe... siento mucho haberme alejado. Eso estuvo mal. Eres mi mejor amiga.",
  ["Cue_E4_1A_Beach_CHChloe_Phase01_Max_024"] = "¡Dios! No sé qué decir.",
  ["Cue_E4_1A_Beach_Extraction_Chloe_010"] = "Max, gracias por venir a verme. Te ves... Luces muy bien.",
  ["Cue_E4_1A_Beach_Extraction_Chloe_030"] = "Ugh. Comienzo a... sentir frío en la nariz. Tal vez deberíamos regresar a casa.",
  ["Cue_E4_1A_Beach_Extraction_Chloe_050"] = "¿\"Poca madre\"? No te ofendas, pero odio esa expresión.",
  ["Cue_E4_1A_Beach_Extraction_Max_020"] = "No lo creo.",
  ["Cue_E4_1A_Beach_Extraction_Max_040"] = "Es cierto, qué poca madre.",
  ["Cue_E4_1A_Beach_Extraction_Max_060"] = "No me ofendo.",
  ["Cue_E4_1A_Beach_Insertion_Chloe_010"] = "Es extraño pasar tiempo contigo de nuevo.",
  ["Cue_E4_1A_Beach_Insertion_Chloe_030"] = "Me gustó que me enviaras cartas. Es más de lo que cualquiera de mis otros amigos ha hecho... Incluso usaste papel pergamino. Es tan típico de ti.",
  ["Cue_E4_1A_Beach_Insertion_Chloe_050"] = "Probablemente es más fácil escribir que visitarme.|No es queja. No por completo.|Probablemente querías evitar conversaciones incómodas como esta.",
  ["Cue_E4_1A_Beach_Insertion_Chloe_070"] = "Mira, lo peor que puedes hacer es tratarme como a una bebé. Todavía quiero reírme y decir estupideces con mi mejor amiga.",
  ["Cue_E4_1A_Beach_Insertion_Chloe_080"] = "¿Podemos parar?",
  ["Cue_E4_1A_Beach_Insertion_Chloe_085"] = "En serio, esta es la mejor vista del atardecer. ¿Cómo la llaman los fotógrafos?",
  ["Cue_E4_1A_Beach_Insertion_Chloe_100"] = "¿Ves? Sin ti no sabría eso. Apuesto a que podrías tomar fotografías espectaculares...|Qué tristeza, pobres ballenas encalladas.|Entiendo cómo deben sentirse...|Al menos estoy viva y estás conmigo.",
  ["Cue_E4_1A_Beach_Insertion_Max_020"] = "Lo sé... me alegra que lo hagamos.",
  ["Cue_E4_1A_Beach_Insertion_Max_040"] = "Es algo pretencioso. Pero me encanta escribir en él, como una poetisa inglesa. Mereces lo mejor.",
  ["Cue_E4_1A_Beach_Insertion_Max_060"] = "Eh... Más o menos. Sí.",
  ["Cue_E4_1A_Beach_Insertion_Max_090"] = "“La hora dorada”.",
  ["Act_E4_2A_Bathroom_Drawer02_Max_010"] = "Nada por aquí.",
  ["Act_E4_2A_Bathroom_E4Mirror_Max_010"] = "¿Cómo te va, viajera del tiempo? Es gracioso, creo que me veo más vieja...",
  ["Act_E4_2A_Bathroom_MedecineCabinet01_Max_010"] = "Aquí está.|Nunca pensé que le inyectaría morfina a mi mejor amiga.",
  ["Act_E4_2A_Bathroom_Scripted04_Max_010"] = "No tengo visión nocturna.",
  ["Act_E4_2A_Bathroom_Scripted04_Max_020"] = "El baño se ve casi igual, solo hay más medicamentos.",
  ["Act_E4_2A_Bathroom_TeaTreeOilBootle_Max_010"] = "Me parece bien que Chloe use medicina natural también.",
  ["Act_E4_2A_ChloeRoom_AuntLetter_Max_010"] = "Es una lástima que Joyce y William no puedan recibir ayuda de la Fundación Prescott...",
  ["Act_E4_2A_ChloeRoom_Box02_Max_010"] = "\"Juguetes\".|Me dan ganas de abrirlo y ver qué hay dentro.",
  ["Act_E4_2A_ChloeRoom_Box03_Max_010"] = "\"Zapatos\".|A Chloe siempre le gustaron las botas.",
  ["Act_E4_2A_ChloeRoom_Closet_Max_010"] = "Al menos nunca tuvimos que escondernos del padrastúpido.",
  ["Act_E4_2A_ChloeRoom_Crutches_Max_010"] = "Le compraron muletas a Chloe, esperando que pudiera caminar de nuevo.",
  ["Act_E4_2A_ChloeRoom_E4Poster_Max_010"] = "¿Una mariposa azul? Estoy segura de que es una mera coincidencia...",
  ["Act_E4_2A_ChloeRoom_E4Window_Max_010"] = "Al parecer, lo único que no ha cambiado es la vista.",
  ["Act_E4_2A_ChloeRoom_MesuringMarks_Max_010"] = "Supongo que dejamos de crecer juntas.",
  ["Act_E4_2A_ChloeRoom_Scripted03_Max_010"] = "Mejor no hago esperar a Chloe, necesito calmar su dolor.",
  ["Act_E4_2A_ChloeRoom_Scripted03_Max_020"] = "La habitación de Chloe era un área de desastre, pero estaba viva... Ahora mírala.",
  ["Act_E4_2A_ChloeRoom_Scripted03_Max_030"] = "Todo lo que queda de la vieja vida de Chloe son cajas de cartón... atrapadas en el tiempo.",
  ["Act_E4_2A_ChloeRoom_UncleLetter_Max_010"] = "Nunca escuché mucho sobre el hermano de William.",
  ["Act_E4_2A_ChloeRoom_Zen_Max_010"] = "Sigo abrumada por esta nueva realidad.",
  ["Act_E4_2A_ChloeRoom_Zen_Max_020"] = "Me siento tan culpable por hacer pasar por esto a Chloe y a su familia.",
  ["Act_E4_2A_ChloeRoom_Zen_Max_030"] = "Podría darle a Chloe la opción de mantener a William con vida, pero eso sería cruel.",
  ["Act_E4_2A_ChloeRoom_Zen_Max_040"] = "Aunque luego veo que son una familia de nuevo, y... ¿quién soy para juzgar?",
  ["Act_E4_2A_Corridor_scripted_Max_010"] = "Necesito ir al baño por la medicina.",
  ["Act_E4_2A_LivingRoom_Scripted02_Max_010"] = "Se siente igual, y al mismo tiempo, completamente diferente...",
  ["Act_E4_2A_LivingRoom_Scripted02_Max_030"] = "Modificar el tiempo y el espacio no hace la vida más fácil, ¿verdad Max?",
  ["Act_E4_2A_LivingRoom_Scripted02_Max_040"] = "Chloe y yo tenemos un nuevo conjunto de viejos recuerdos... Aun así, no tengo idea qué hicimos en ese tiempo...",
  ["Act_E4_2A_ParentsRoom_ArcadiaBayPoster_Max_010"] = "Eres el centro de todo, ¿verdad, Arcadia Bay?",
  ["Act_E4_2A_ParentsRoom_Ashtray_Max_010"] = "Mmmm, Joyce odiaba a los fumadores en el restaurante.",
  ["Act_E4_2A_ParentsRoom_CHJoyce_Max_010"] = "Joyce se ve tan cansada... ¿Quién podría culparla?",
  ["Act_E4_2A_ParentsRoom_ChloeDoor_Max_010"] = "La puerta de Chloe ya no tiene una señal de advertencia.",
  ["Act_E4_2A_ParentsRoom_ChloePicture_Max_010"] = "Es una foto magnífica de Chloe. Me pregunto quién la tomó.",
  ["Act_E4_2A_ParentsRoom_DoctorLetter_Max_010"] = "Ay, no... No había asimilado lo terrible que fue la lesión de Chloe...",
  ["Act_E4_2A_ParentsRoom_E4Drawer01_Max_010"] = "William se está esforzando tanto. Sigue siendo genial.",
  ["Act_E4_2A_ParentsRoom_E4Drawer02_Max_010"] = "Joyce es una supermamá.",
  ["Act_E4_2A_ParentsRoom_JoyceWilliamPicture_Max_010"] = "Míralos...|No tienen idea de lo que les depara el futuro.",
  ["Act_E4_2A_ParentsRoom_Scripted05_Max_010"] = "Incluso la habitación de Joyce y William está decorada de forma diferente.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_001"] = "Buenos días, Max. Chloe y tú son mucho más tranquilas ahora que cuando eran niñas.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_003"] = "Nos alegra mucho a William y a mí verte de nuevo con Chloe, después de tantos años... después del accidente...",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_005"] = "No tengo quejas.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_011"] = "Max, por algo eres la mejor amiga de Chloe. Estás aquí precisamente cuando te necesita.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_014"] = "Max, el estado de Chloe no está mejorando. Su sistema respiratorio está muy débil... ella... está... ¿entiendes lo que digo?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_015"] = "Hacemos lo que podemos... ella se harta de sus padres. Por eso es tan importante que vengas a pasar tiempo con ella.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_016"] = "Tenemos una serie de enfermeras y cuidadoras que se rotan... Aunque no puede moverse, Chloe sigue siendo problemática...",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_017"] = "Bueno o malo, atesoro cada momento con mi hija y mi esposo. Somos una familia... Y siempre seremos una, sin importar lo que suceda.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_019"] = "Es un héroe, ha vivido todo esto con nosotras. Chloe y yo somos muy afortunadas.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_022"] = "En las buenas y en las malas... pero siempre para bien. Nunca imaginé amar a alguien al grado de no imaginarme la vida sin él. Suena cursi, lo sé.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_023"] = "Sí, esos dos se llevan mejor ahora que nunca. Chloe de hecho escucha a William, mientras que a mí me ignora. Me dan ternura cuando hacen equipo contra mí...",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_025"] = "Mierda, las cosas serían mejor si lo fuera... Me gusta cómo piensas, niña.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_026"] = "Estoy lo mejor que puedo, Max. No te mentiré, es difícil... pero la vida no es fácil para nadie en Arcadia Bay.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_027"] = "También contigo, querida.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_029"] = "Bill y yo no tenemos tiempo para nosotros, trabajamos más de lo que vivimos. Incluso tomé un trabajo de medio tiempo en Pan Estates. Qué asco.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_031"] = "Sé que Sean Prescott no estará feliz hasta que sea dueño de todo en Arcadia Bay. Procura no juntarte con su hijo Nathan.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_034"] = "Quizás Arcadia Bay solo quiere que la dejen en paz... Conozco esa sensación. Honestamente, me importa un carajo lo que suceda afuera de nuestra casa.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_035"] = "Okey, eso fue raro. Sí, es conductor de autobús. A veces lo vemos. Es lindo y callado. ¿Por qué?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_038"] = "Siempre lo fuiste. Es bueno ver que no todo cambia.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Joyce_039"] = "Excepto que ahora hay aves muertas y ballenas encalladas en nuestra puerta... Quizá eso debería importarme, por el bien de Chloe.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_002"] = "Lo recuerdo. Es bonito despertar en tu casa de nuevo.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_004"] = "Hola de nuevo, Joyce.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_007"] = "Ojalá fuera mejor como amiga. Sé que Chloe no recibe muchas visitas.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_008"] = "Necesito decirte cuánto me encanta verlos a William y a ti juntos.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_009"] = "¿Cómo estás Joyce?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_010"] = "Mejor regreso con Chloe. Es bueno hablar contigo, Joyce.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_012"] = "Eso espero. Ustedes hacen un gran trabajo cuidando de ella.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_013"] = "¿Quién atiende a Chloe cuando ustedes trabajan?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_018"] = "Joyce, lamento profundamente que estén viviendo todo esto.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_020"] = "¿William es el mismo, después de todo lo que ocurrió?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_021"] = "Parece que Chloe y William todavía se llevan muy bien.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_024"] = "Eres la mejor, Joyce.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_028"] = "Además necesitan trabajar también.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_030"] = "¿Conoces a los Prescott?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_032"] = "¿Conoces a un David Madsen?|Quizá... lo veas en Two Whales.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_033"] = "¿Qué piensas que desató el caos ecológico?",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_036"] = "Ah, pues... mera curiosidad.",
  ["Cue_E4_2A_ParentsRoom_CHJoyce_Phase01_Max_037"] = "No te culpo, Joyce.",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_010"] = "Max, es tan maravilloso tenerte en casa.",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_020"] = "Es bueno para Chloe mantenerse en contacto con sus amigos.",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_030"] = "William y yo no podemos creer lo mucho que has crecido.",
  ["Cue_E4_2A_ParentsRoom_JoyceBed_IGE_Joyce_040"] = "Sé que las cosas no están tan limpias y ordenadas como solían...",
  ["Act_E4_2B_Garage_Bathroom_Look01_Max_010"] = "Dios, Joyce y William construyeron un nuevo baño para Chloe. Son geniales.",
  ["Act_E4_2B_Garage_Bracelet_Look01_Max_010"] = "Esa es la misma Chloe.",
  ["Act_E4_2B_Garage_CHChloe_Look04_Max_040"] = "Detente, Max. Necesitas llevar el medicamento a tu amiga.",
  ["Act_E4_2B_Garage_ChloeCHair_Look01_Max_010"] = "Aún no puedo creer que por mi culpa, Chloe terminara en esa silla...",
  ["Act_E4_2B_Garage_ComputerSP01_Interact01_Max_010"] = "Chloe sigue siendo una punk por dentro... pero ya no puede saltar del escenario.",
  ["Act_E4_2B_Garage_ComputerSP02_Interact01_Max_010"] = "Me parece genial que Chloe haya hecho amigos por internet.",
  ["Act_E4_2B_Garage_Computer_Look01_Max_010"] = "Vaya, Chloe puede controlar su computadora por completo... Es fabuloso que la gente obtenga esta ayuda de alta tecnología.",
  ["Act_E4_2B_Garage_Drawer_Max_010"] = "Solo productos médicos...",
  ["Act_E4_2B_Garage_E4Drawer02_Look01_Max_010"] = "Tiene que usar mucha crema para mantener la sangre circulando.",
  ["Act_E4_2B_Garage_E4Drawer04SP01_Interact01_Max_010"] = "Dios, hice este CD para ella cuando teníamos doce años.",
  ["Act_E4_2B_Garage_E4Drawer05SP01_Interact01_Max_010"] = "Qué hijo de puta. Me alegra que Chloe haya robado tu fondo de mierda. Aun si fue en otra realidad...",
  ["Act_E4_2B_Garage_E4Drawer05SP01_Interact02_Max_020"] = "Qué hijo de puta. Debería haber dejado que Chloe robara tu estúpido fondo. Aunque sea en otra realidad...",
  ["Act_E4_2B_Garage_E4Drawer05_Interact01_Max_010"] = "Increíble, Chloe era alumna de excelencia. Podría haber entrado a cualquier universidad.",
  ["Act_E4_2B_Garage_E4Drawer06SP01_Interact01_Max_010"] = "A pesar de todo, son una familia feliz de nuevo...",
  ["Act_E4_2B_Garage_E4Drawer06SP02_Interact01_Max_010"] = "Me parece bien que en esta realidad a Chloe también le fascinen las patinetas.",
  ["Act_E4_2B_Garage_HeatLamp_Look01_Max_010"] = "Es una lámpara de calor gigante.",
  ["Act_E4_2B_Garage_MakeUp_Look01_Max_010"] = "Debería ofrecerme para maquillar a Chloe. No sé hacerlo, pero sería divertido.",
  ["Act_E4_2B_Garage_MedicalVentilator_Look01_Max_010"] = "Vaya, necesita usar ese ventilador solo para respirar.",
  ["Act_E4_2B_Garage_MouthJoystick_Look01_Max_010"] = "Es increíble... Y puede ver videos de gatos en la red.",
  ["Act_E4_2B_Garage_PatientLifter_Look01_Max_010"] = "Al menos Chloe no pesa tanto.",
  ["Act_E4_2B_Garage_Perfusion_Look01_Max_010"] = "Esa debe ser su poderosa máquina de morfina...|No más pipas de marihuana para ella.",
  ["Act_E4_2B_Garage_PhotoAlbum_Look01_Max_010"] = "Así que Chloe tiene su propio álbum de fotos.",
  ["Act_E4_2B_Garage_PhotoChloeWilliam_Max_010"] = "Me alegra haber tomado esta fotografía. Chloe tiene un nuevo recuerdo de William y ella juntos.",
  ["Act_E4_2B_Garage_PinboardSP01_Interact01_Max_010"] = "Qué buen detalle de mis padres mandar una postal.",
  ["Act_E4_2B_Garage_PinboardSP02_Interact01_Max_010"] = "Me pregunto de quién es esta. Es una postal genérica.",
  ["Act_E4_2B_Garage_PinboardSP03_Interact01_Max_010"] = "No estuve con Chloe. Bien hecho.",
  ["Act_E4_2B_Garage_PinboardSP04_Interact01_Max_010"] = "Al menos le mandé selfies de mis viajes a Chloe. Seguramente se sintió genial con eso.",
  ["Act_E4_2B_Garage_Pinboard_Look01_Max_010"] = "El tablero de mensajes de Chloe está vacío desde el accidente.|Y yo no ayudé demasiado. Mal, Max.",
  ["Act_E4_2B_Garage_Scripted_Max_010"] = "Dios, Chloe siente mucho dolor. Necesito encontrar su analgésico.",
  ["Act_E4_2B_Garage_Scripted_Max_020"] = "Chloe dijo que la morfina estaba arriba.",
  ["Act_E4_2B_Garage_Scripted_Max_040"] = "Hablando de teorías del caos... Mandé todo al carajo...",
  ["Act_E4_2B_Garage_Scripted_Max_050"] = "Nada en esta realidad parece estar bien...",
  ["Act_E4_2B_Garage_Scripted_Max_060"] = "¿Entonces esto es lo que querías, Max? ¿Estás feliz ahora?",
  ["Act_E4_2B_Garage_Scripted_Max_080"] = "¿Cómo puedo decidir si la vida de William es un precio justo por la salud de Chloe? ¿O viceversa?",
  ["Act_E4_2B_Garage_Scripted_Max_110"] = "Este es el hogar de Chloe ahora... para siempre. Es increíble lo que damos por sentado.",
  ["Act_E4_2B_Garage_SnowDoe_Look01_Max_010"] = "Aaaah, la venada de nieve... Supongo que no todo ha cambiado.",
  ["Act_E4_2B_Garage_SnowGlobes_Look01_Max_010"] = "Los globos de nieve nos invaden...",
  ["Act_E4_2B_Garage_ToyBear_Look01_Max_010"] = "\"Hola, Chloe\".|Ahora le gustan los peluches.",
  ["Act_E4_2B_Garage_Window_Look01_Max_010"] = "¿Chloe verá su jardín y pensará en su infancia? Ahora no puede ni sentir el pasto...",
  ["Act_E4_2B_Garden_DeadBirds_Look01_Max_010"] = "Mira todas estas aves muertas... ¿También está ocurriendo aquí?",
  ["Act_E4_2B_Garden_Drawing_Look01_Max_010"] = "Chloe movió nuestro dibujo para que pudiera verlo desde su habitación... Chloe...",
  ["Act_E4_2B_Garden_Grave_Look01_Max_010"] = "Lo siento, gatito Bongo, pero moriste antes de que cambiara esta realidad...",
  ["Act_E4_2B_Garden_House_Look01_Max_010"] = "La casa se ve muy bien. William al fin tuvo tiempo para pintarla y arreglar el jardín.",
  ["Act_E4_2B_Garden_Swing_Look01_Max_010"] = "Vaya, el columpio ya no está... Debió ser triste para Chloe cuando William lo quitó.",
  ["Act_E4_2B_Garden_Window_Look01_Max_010"] = "Me alegra que Chloe tenga una habitación con vista.",
  ["Act_E4_2B_LivingRoom_Bills_Look01_Max_010"] = "Wow, esto es solo para los suministros básicos de Chloe...",
  ["Act_E4_2B_LivingRoom_CHWilliam_Look01_Max_010"] = "Cada vez que veo a William, pienso que es un replicante...",
  ["Act_E4_2B_LivingRoom_CookieJar_Look01_Max_010"] = "Ya no hay cambio. Ahora galletas.",
  ["Act_E4_2B_LivingRoom_EiffelTower_Look01_Max_010"] = "¡Bonjour! ¡Por fin fueron a París, qué maravilla!",
  ["Act_E4_2B_LivingRoom_FoodCoupons_Look01_Max_010"] = "Joyce domina los cupones de comida.",
  ["Act_E4_2B_LivingRoom_Graffiti_Look01_Max_010"] = "Sí, es el mismo grafiti de antes...",
  ["Act_E4_2B_LivingRoom_Keys_Look01_Max_010"] = "Y pensar que nuestro destino está ligado a los estúpidos autos...",
  ["Act_E4_2B_LivingRoom_Mail_Look01_Max_010"] = "Están hasta el cuello de deudas por atender a su hija... Qué mierda.",
  ["Act_E4_2B_LivingRoom_Mortgage_Look01_Max_010"] = "Podrían quitarles la casa a consecuencia de las deudas médicas... Qué terrible.",
  ["Act_E4_2B_LivingRoom_Newspaper_Look01_Max_010"] = "Las ballenas solo son un aviso del caos que nos depara... ¿Y la Fundación Prescott? Dios.",
  ["Act_E4_2B_LivingRoom_Newspaper_Look02_Max_020"] = "Rachel Amber está extraviada incluso en esta realidad... Supongo que no puedo cambiar todo.",
  ["Act_E4_2B_LivingRoom_OldTV_Look01_Max_010"] = "Le dieron a Chloe la enorme TV HD y ellos usan su televisión vieja.",
  ["Act_E4_2B_LivingRoom_SaleFlyer_Look01_Max_010"] = "Joyce y William nunca habían hecho una venta de garage...",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_001"] = "¿Segura que no es muy raro para ti pasar tiempo conmigo como ahora?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_002"] = "Mi vida es tan diferente de la tuya. Me refiero a que no podemos irnos de aquí... Estaré drogada la mitad del día por el dolor. Pero no importa.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_003"] = "No, estabas ocupada siendo genial. No culpo a nadie por abandonarme. La gente apesta. Es broma.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_009"] = "Claro, un poco de sexo desenfrenado no estaría mal.|¡Ah, Maxine se sonrojó!|¿Sales con alguien en Blackwell?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_010"] = "Pero me siento agradecida por ver el mar, tener a mis padres, que me aman, y porque mi mejor amiga esté hoy aquí, conmigo.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_012"] = "Lo que me parece estúpido, porque eres genial. Debe haber más de uno enamorado de ti.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_013"] = "Por favor. No serás una artista si no experimentas la vida... Eso incluye chicos, chicas... ¡lo que sea!",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_014"] = "Él se lo pierde. Necesitas superarlo. Hay muchos peces en el mar... Carajo, sueno a mi papá.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_019"] = "Por supuesto, él es mi héroe. Te juro que haría lo que fuera por mí o mi mamá. Ojalá pudiera yo hacer algo por él...",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_020"] = "Mete el dedo en la llaga. ¿Cómo podría enojarme con el tonto? Hace tanto por mí... y yo no puedo ayudarle en un carajo.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Chloe_021"] = "Mejor dicho, ellos están conmigo. Pero tú también... así que todo está bien.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_004"] = "Más o menos, pero solo porque no te he visto en mucho tiempo... Fui egoísta.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_005"] = "De ninguna manera. No quiero que sea extraño para ti.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_006"] = "No, en realidad no. Hay algunos chicos lindos, pero ya me conoces... soy demasiado tímida.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_007"] = "Exactamente. Así que, ¿qué más necesitas?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_008"] = "Iba a salir con un chico llamado Warren, pero creo que ya no está interesado...",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_011"] = "Estoy muy ocupada con la escuela y la fotografía.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_015"] = "Un tal Warren me invitó a salir, pero lo rechacé. Ahora está con alguien más...",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_016"] = "¿Cómo está William? ¿Te agrada que esté aquí?",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_018"] = "Está bien que suenes a William. Realmente le importas.",
  ["Cue_E4_2B_Garage_CHChloe_Phase01_Max_022"] = "Lo has hecho. Estás aquí con tu familia.",
  ["Cue_E4_2B_Garage_CHChloe_Quick01_Chloe_001"] = "Lo siento, necesito descansar por un momento. ¿Está bien?",
  ["Cue_E4_2B_Garage_CHChloe_Quick01_Chloe_002"] = "Lo siento, Max. Necesito descansar.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_010"] = "Me alegra mucho que tuviéramos nuestra noche de películas. Aunque te hayas quedado dormida.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_020"] = "Es raro que te quedes a dormir conmigo después de todos estos años.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_030"] = "Espero que no estés celosa de todos mis juguetes de última tecnología...",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_040"] = "Me pregunto cómo se vería mi habitación arriba...",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_050"] = "Me estallará la cabeza, Max. Necesito el medicamento...",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_060"] = "Toma ese álbum de fotos y tráelo acá, para revivir viejos recuerdos.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Chloe_070"] = "Max, gracias por ser una verdadera amiga.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_015"] = "Por eso se dice \"quedarse a domir\".",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_025"] = "Sí, pero se siente igual...",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_035"] = "Estoy impresionada, Tony Stark...",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_045"] = "Un lugar del carajo, probablemente.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_055"] = "Lo siento. Enseguida.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_065"] = "No sería la primera vez.",
  ["Cue_E4_2B_Garage_ChloeBed_IGE_Max_075"] = "Dicen que \"Dios los hace y ellos se juntan\"...",
  ["Cue_E4_2B_Garage_ChloeTurnPage_IGE_Chloe_010"] = "Max, ¿te importaría cambiar de página? Estoy muy ocupada, como puedes ver...",
  ["Cue_E4_2B_Garage_ChloeTurnPage_IGE_Chloe_020"] = "Estas fotografías son geniales Max. ¿Podemos ver más?",
  ["Cue_E4_2B_Garage_ChloeTurnPage_IGE_Chloe_030"] = "Muy bien, Max, cambia la página, por favor.",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_010"] = "Al fin. Dame la píldora azul...",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_030"] = "Anda, conéctala. Es fácil. Y sin dolor.",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_050"] = "Confía en mí, lo haré.",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_060"] = "Por su puesto, mi dolor sigue empeorando... pero hoy es un buen día. Max, estoy tan agradecida de pasar tiempo contigo. Mírame, ya me puse sentimental, ya estoy un poco drogada.",
  ["Cue_E4_2B_Garage_GiveMedicine_Chloe_080"] = "Um, quizá suene muy \"emo\", pero ¿puedes darme uno de los álbumes de fotos que están allá? Me gustaría ver viejas fotos de cuando éramos pequeñas.",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_020"] = "Lo siento. La precisión no es mi fuerte.",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_040"] = "Emm, muy bien, pero prepárate para gritarle a tus papás si no lo hago bien.",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_070"] = "Eres tan tierna. ¿Quieres algo más?",
  ["Cue_E4_2B_Garage_GiveMedicine_Max_090"] = "Por favor. Mi diario es una bomba atómica emo. Además, a Max Caulfield siempre le gusta ver fotos, especialmente con Chloe Price.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_020"] = "Perfecto.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_025"] = "Dios mío, ¡mira qué pequeñas éramos! ¡Parecemos juguetes!",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_040"] = "Mi papá estaba muy enojado con nosotras. ¡Hasta quiso castigarnos!",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_060"] = "Vaya, qué foto tan genial. Nos vemos cabronas como piratas.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_080"] = "Aún tienes tiempo para hacerlo...",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_085"] = "Mira, ahí estamos haciendo hot cakes. Me encanta esa foto de nosotras. Es increíble que mi papá nos tomó esa foto hace apenas cinco años.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_100"] = "Ojalá lo fuera.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_120"] = "Escucha, Max, mi sistema respiratorio está fallando y... y solo está empeorando.|He escuchado a los doctores hablar cuando creían que estaba desmayada.|Así que solo están posponiendo lo inevitable,|y mis padres sufren todo este proceso... al igual que yo.|Así no es como quiero que termine.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Chloe_140"] = "Estoy diciendo que estar contigo de nuevo ha sido muy especial. Solo quería sentir como cuando éramos niñas corriendo por Arcadia Bay... y todo era posible.|Y me hiciste sentir así hoy. Quiero que este tiempo contigo sea mi último recuerdo...|¿Entiendes?",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_010"] = "¿Así está bien?",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_030"] = "Me acuerdo de ese día cerca del faro.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_050"] = "Y te reíste de él. Mi papá me hubiera exiliado.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_070"] = "Debimos adueñarnos de Arcadia Bay cuando tuvimos la oportunidad.",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_090"] = "Literalmente parece que fue ayer...",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_110"] = "Yo también...",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_130"] = "¿Qué? ¿Qué estás diciendo?",
  ["Cue_E4_2B_Garage_GivePhotoAlbum_Max_150"] = "Sí, lo entiendo.",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_010"] = "Lo único que debes hacer es subir la intravenosa hasta once...",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_030"] = "Solo me quedaré dormida poco a poco... soñando contigo y conmigo... juntas para siempre.",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_040"] = "Muchas gracias.|Estoy tan orgullosa de ti por seguir tus sueños.|No me olvides.",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Chloe_060"] = "Te quiero, Max.|Hasta pronto.",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Max_020"] = "Chloe...",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Max_050"] = "Jamás.",
  ["Cue_E4_2B_Garage_MedicineChoice_Accept_Max_070"] = "Más pronto de lo que crees...",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Chloe_020"] = "Max, estuviste con tu amiga sin importar nada. Ahora te pido que me ayudes también a mí.",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Chloe_040"] = "Al menos tienes una opción. Cuando quieres tomar una decisión, la tomas y ya. En cambio yo, estoy a merced de... todos.|Por primera vez, quiero tomar una decisión propia... La más importante de mi vida.|Por favor... ayúdame, Max.",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Max_010"] = "Chloe... Realmente no sé si pueda hacer esto. Tuve otra amiga que quiso que... terminara todo e hice todo lo que pude para salvar su vida. ¿Cómo puedo ser responsable de terminar con la tuya? ¿Es que en verdad no hay otra salida?",
  ["Cue_E4_2B_Garage_MedicineChoice_Dontknow_Max_030"] = "Quiero ayudarte, Chloe, pero creo que mi ayuda te lastima peor.",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_010"] = "Lo único que debes hacer es subir la intravenosa hasta once...",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_030"] = "Soy un adulto. Te estoy dando el derecho.",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_050"] = "Ya me despedí de ellos, pero no respetarán mis deseos. Tú lo harás, ¿verdad?",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_070"] = "Max, estoy muriendo a causa de mi estado, no la dosis. Esto acelera el proceso. Preferiría hacerlo a mi manera. Pero necesito ayuda de mi mejor amiga...",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Chloe_090"] = "¿Por qué, Max? ¡Solo estás abandonándome como todos los demás! ¿Por qué no te vas ya? ¿Lo has querido hacer desde que llegaste, no? Así que vete y ya no regreses.",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_020"] = "Chloe... No puedo. Me parte el alma verte sufriendo, pero no tengo el derecho de hacer esto.",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_040"] = "Pero Joyce... y William...",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_060"] = "No puedo... matarte con una sobredosis.",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_080"] = "Te ayudaré, pero no así. Tienes que creerme, Chloe.",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_100"] = "Chloe, nunca te dejaré otra vez.",
  ["Cue_E4_2B_Garage_MedicineChoice_Refuse_Max_110"] = "Lo lamento, William...",
  ["Cue_E4_2B_Garage_PolaRewind_Chloe_010"] = "¡No antes de que la vea! ¡Ya conoces las reglas, papá!",
  ["Cue_E4_2B_Garage_PolaRewind_Chloe_020"] = "¿Quieres decir hot cakes?",
  ["Cue_E4_2B_Garage_PolaRewind_Chloe_030"] = "Max, dile...",
  ["Cue_E4_2B_Garage_PolaRewind_PolarewindVoices_010"] = "\"Leche!\"\nVamos, ¡digan \"whisky\"!\n¡Ni siquiera puedo ver!",
  ["Cue_E4_2B_Garage_PolaRewind_William_010"] = "¿Quién quiere ayudarme a hacer crepas?",
  ["Cue_E4_2B_Garage_PolaRewind_William_020"] = "En Francia, las llaman \"crêpes\".",
  ["Cue_E4_2B_Garage_TurnPage_Max_010"] = "Esta foto... Tal vez podría...",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_020"] = "Sé que estabas agotada después de todo el día conmigo. Y Blade Runner no es fácil de ver por la noche. ¿Crees que Deckard es un replicante?",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_030"] = "Lo siento, creo que no estás tan despierta como yo.",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_050"] = "Sí, mamá y papá te relevan cuando te quedas dormida.",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_070"] = "Ya me conoces...",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_080"] = "Ayer fue un día genial.",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_100"] = "Sé que las cosas eran diferentes cuando solo éramos un par de niñas tontas, pero estar contigo me hizo sentir como cuando éramos pequeñas piratas, jugando en el bosque. Significó mucho para mí pasar este rato contigo.",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_110"] = "Ah... Mierda. Me está dando uno de mis regulares dolores de cabeza... Uh, ¿podrías ser un amor y subir por mi... mi inyector de morfina que está en el baño?",
  ["Cue_E4_2B_Garage_WakeUp_Chloe_130"] = "Es una porquería como de Star Trek. Ni se ve la aguja. En serio, lo necesito. Mis padres guardan mis cosas arriba porque piensan que no puedo alcanzarlas... Pero tú sí, Max. Como un pirata ¿no?",
  ["Cue_E4_2B_Garage_WakeUp_Max_010"] = "No puedo creer que te quedaras dormida tan rápido. ¿Cómo te atreves?",
  ["Cue_E4_2B_Garage_WakeUp_Max_040"] = "No, lamento haberme dormido. ¿Estuviste bien?",
  ["Cue_E4_2B_Garage_WakeUp_Max_060"] = "Eres una perra por las mañanas.",
  ["Cue_E4_2B_Garage_WakeUp_Max_090"] = "Verte fue genial.",
  ["Cue_E4_2B_Garage_WakeUp_Max_120"] = "¿Inyector de morfina?",
  ["Cue_E4_2B_Garage_WakeUp_Max_140"] = "Estoy en eso, Chloe.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_002"] = "Hola, William. ¿Te interrumpo?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_008"] = "Hola de nuevo, William.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_009"] = "Imagino que la parte económica debe ser difícil para ustedes.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_010"] = "No sé cómo decir esto, pero siento mucho lo que le ocurrió a Chloe.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_013"] = "Me impresionó la habitación de Chloe, con tanto equipo de alta tecnología.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_017"] = "Lo sé. Te ves exactamente igual. Me parece genial.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_018"] = "William, quiero que sepas que no importa lo que pase,|siempre estaré aquí para Chloe. Siempre.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_019"] = "¿Está enojada conmigo por no mantenerme en contacto?|Tiene razón, no tengo excusa.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_020"] = "Es increíble. Me alegra tanto que estés aquí para ayudarla... y que seas su padre.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_023"] = "Debo ver si Chloe necesita algo. Me agradó hablar contigo de nuevo.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_024"] = "Estar contigo y Joyce de nuevo es tan nostálgico.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_025"] = "Estaba leyendo sobre esa chica extraviada... ¿Rachel Amber?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_026"] = "¿Qué estará ocurriendo con este clima tan raro y tantos animales muertos?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_027"] = "Quizás la familia Prescott no sea de fiar. ¿Qué opinas de ellos?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_028"] = "Debería regresar con Chloe...",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_029"] = "¿Así que finalmente pudieron ir a París?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_030"] = "Me puedo imaginar que le encantó. Son geniales por haber ido en una aventura familiar así.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_Max_037"] = "Suena a que los conoces bien.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_001"] = "Sí, Max, me encanta revisar cuentas. Es broma.|¿Por qué me molestaría verte? Hace mucho que no nos juntábamos.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_003"] = "Es bueno verte de nuevo.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_005"] = "Qué bien, me asustaría si no me viera como yo... Por supuesto, te ves más adulta ahora. ¿Qué ocurre?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_006"] = "A mí me alegra que Joyce esté aquí para ayudarnos a ambos. Max, odio pensar qué sería de Chloe si yo no estuviera aquí...",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_007"] = "Yo también. En unos cuantos minutos, la vida de una chica puede cambiar por completo. Pero está viva. Y es muy valiente.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_011"] = "Las deudas nos asfixian. Necesitamos hipotecar la casa y eso nos asusta... Pero lo superaremos, a cualquier \"Price\". ¿Lo entendiste? ¿No?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_012"] = "Y debería impresionarte. Podríamos comprar mansiones con todo lo que costó. El seguro ayuda pero... no lo sé, Max.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_014"] = "Se sintió decepcionada, pero sabe que le importas.|Y yo sé lo difícil que es procesar todo esto. Nos ha tomado años.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_016"] = "Como en los viejos tiempos. Me parece muy bien que Chloe te vea. También a Joyce le da gusto. Así que no todo son malas noticias en Arcadia Bay, ¿verdad?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_021"] = "Lo sé, Max.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_022"] = "Ah, sí, estudiaba en Blackwell ¿no? Pobre. Debe ser una verdadera pesadilla para la familia... Me asusta el solo pensar en que... llegue el día en que perdamos a Chloe.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_031"] = "Ella quería estudiar allí... Pero ya no es posible. No es justo, Max...",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_032"] = "\"Oui\", como dicen, o algo así, no sé francés... Pero fue una experiencia increíble, en especial para Chloe.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_033"] = "Actúas como si fuera la última vez. Si quieres destruir esas facturas, por mí, fantástico.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_034"] = "Dicen que nadie sabe. Como si se tratara de una profecía de Nostradamus. Pero quienes me importan son Chloe y Joyce. Mi familia.",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_035"] = "Son malvados. ¿Siguiente pregunta?",
  ["Cue_E4_2B_LivingRoom_CHWilliam_Phase01_William_036"] = "Más de lo que quisiera. Pero Joyce necesita trabajar para esos cabrones codiciosos en Pan Estates. Odio que tenga que ser así.",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_010"] = "(suspiro)",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_020"] = "(suspiro)",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_030"] = "(suspiro)",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_040"] = "(canto)",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_050"] = "espera, ¿si hago esto?",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_060"] = "(suspiro)",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_070"] = "No digas groserías, no digas groserías...",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_080"] = "Maravilloso...",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_090"] = "Ugh genial.",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_100"] = "(suspiro y risa)",
  ["Cue_E4_2B_LivingRoom_WilliamOno_IGE_William_110"] = "¡Genial!",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_010"] = "Maldición, las deudas nunca terminan...",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_020"] = "Ya dispárenme.",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_030"] = "En pocas palabras, todas estas deudas dicen: \"Estimado señor, está jodido\".",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_040"] = "Este seguro no sirve para nada...",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_050"] = "Definitivamente necesito un tercer trabajo...",
  ["Cue_E4_2B_LivingRoom_WilliamTable_IGE_William_060"] = "No, no creo que las propinas que gana Joyce cubran todo esto...",
  ["Cue_E4_2C_Kitchen_WilliamFindingkeys_William_010"] = "¡Ajá! ¡No se pueden esconder de mí por siempre!",
  ["Cue_E4_2C_LivingRoom_EditedVoices_William_010"] = "Hola cariño...",
  ["Cue_E4_2C_LivingRoom_EditedVoices_William_020"] = "¿Qué?",
  ["Cue_E4_2C_LivingRoom_EditedVoices_William_030"] = "Ah, no sabía que irías de compras. Por su puesto que iré a recogerte.",
  ["Cue_E4_2C_LivingRoom_Insertion_Chloe_020"] = "Algún día papá comprará una de esas nuevas computadoras.",
  ["Cue_E4_2C_LivingRoom_Insertion_William_030"] = "Espero que el flash no te haya asustado, Max.",
  ["Cue_E4_2C_LivingRoom_Insertion_William_040"] = "Esta se queda.",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Chloe_030"] = "Max, estás comportándote tan extraña, como si nunca fueses a vernos de nuevo.",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Chloe_050"] = "No sé exactamente de qué estás hablando. Has cambiado muchas cosas. Mi vida entera, por ejemplo.|Eres mi mejor amiga. Te tengo a ti y a una gran familia. ¿De qué hay que lamentarse? Seremos mejores amigas por siempre. Y cuando crezcamos, conquistaremos el mundo.",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Max_040"] = "Chloe, lo siento tanto...|Traté de hacer las cosas diferentes para ti...|En serio lo intenté... Lo siento.",
  ["Cue_E4_2C_LivingRoom_MaxDoesNothing_Max_055"] = "Escucha, sin importar lo que pase, quiero que seas fuerte. Incluso si sientes que no estuve para ti... porque nunca te abandonaré, Chloe. Siempre podrás contar conmigo. Siempre.",
  ["Cue_E4_2C_LivingRoom_MaxPickUpPhone_William_030"] = "¿Bueno?",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_Chloe_050"] = "¡Papá!",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_Chloe_070"] = "¡Nunca me abandonará!",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_Chloe_100"] = "¡Otro dólar para el frasco de malas palabras!",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_060"] = "Si se portan bien, tu mamá me prometió que nos sorprendería con su famoso salmón y un delicioso pastel de chocolate como postre. Max, ¿te quedas a cenar?",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_080"] = "Eso significa que estaremos todos.",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_090"] = "Carajo, ¿dónde están mis llaves?",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_110"] = "Quieres decir, tu fondo para la universidad. Las llaves, por favor...",
  ["Cue_E4_2C_LivingRoom_WilliamNeedCarKeys_William_140"] = "Y sepan que la cata de vinos está terminantemente prohibida para Chloe y Max...",
  ["Act_E4_2D_Garage_Bathroom_Look01_Max_010"] = "Dios, Joyce y William construyeron un nuevo baño para Chloe. Son geniales.",
  ["Act_E4_2D_Garage_Bracelet_Look01_Max_010"] = "Esa es la misma Chloe.",
  ["Act_E4_2D_Garage_CHChloe_Look01_Max_010"] = "No es justo para mí sentir lástima por Chloe... y tampoco es justo para ella. Sigue siendo valiente.",
  ["Act_E4_2D_Garage_ChloeChair_Look01_Max_010"] = "Aún no puedo creer que por mi culpa, Chloe terminara en esa silla...",
  ["Act_E4_2D_Garage_ComputerSP01_Interact01_Max_010"] = "Chloe sigue siendo una punk por dentro... pero ya no puede saltar del escenario.",
  ["Act_E4_2D_Garage_ComputerSP02_Interact01_Max_010"] = "Me parece genial que Chloe haya hecho amigos por internet.",
  ["Act_E4_2D_Garage_Computer_Look01_Max_010"] = "Vaya, Chloe puede controlar su computadora por completo... Es fabuloso que la gente obtenga esta ayuda de alta tecnología.",
  ["Act_E4_2D_Garage_CupWater_Look01_Max_010"] = "En lugar de pasarle a Chloe una pipa de marihuana, le estoy dando agua... No le di opción.",
  ["Act_E4_2D_Garage_DVDPlayer_Look01_Max_010"] = "Aquí está el reproductor de DVD. Ahora necesito encontrar el DVD.",
  ["Act_E4_2D_Garage_DVDPlayer_Look02_Max_020"] = "Ahora tendremos una noche de películas.",
  ["Act_E4_2D_Garage_Drawer_Max_010"] = "Solo productos médicos...",
  ["Act_E4_2D_Garage_E4Drawer02_Look01_Max_010"] = "Tiene que usar mucha crema para mantener la sangre circulando.",
  ["Act_E4_2D_Garage_E4Drawer03_Interact01_Max_010"] = "Ajá, aquí está el DVD.",
  ["Act_E4_2D_Garage_E4Drawer04SP01_Interact01_Max_010"] = "Dios, hice este CD para ella cuando teníamos doce años.",
  ["Act_E4_2D_Garage_E4Drawer05SP01_Interact01_Max_010"] = "Qué hijo de puta. Me alegra que Chloe haya robado tu fondo de mierda. Aun si fue en otra realidad...",
  ["Act_E4_2D_Garage_E4Drawer05SP01_Interact02_Max_020"] = "Qué hijo de puta. Debería haber dejado que Chloe robara tu estúpido fondo. Aunque sea en otra realidad...",
  ["Act_E4_2D_Garage_E4Drawer05_Interact01_Max_010"] = "Increíble, Chloe era alumna de excelencia. Podría haber entrado a cualquier universidad.",
  ["Act_E4_2D_Garage_E4Drawer06SP01_Interact01_Max_010"] = "A pesar de todo, son una familia feliz de nuevo...",
  ["Act_E4_2D_Garage_E4Drawer06SP02_Interact01_Max_010"] = "Me parece bien que en esta realidad a Chloe también le fascinen las patinetas.",
  ["Act_E4_2D_Garage_HeatLamp_Look01_Max_010"] = "Es una lámpara de calor gigante.",
  ["Act_E4_2D_Garage_MakeUp_Look01_Max_010"] = "Debería ofrecerme para maquillar a Chloe. No sé hacerlo, pero sería divertido.",
  ["Act_E4_2D_Garage_MedicalVentilator_Look01_Max_010"] = "Vaya, necesita usar ese ventilador solo para respirar.",
  ["Act_E4_2D_Garage_MouthJoystick_Look01_Max_010"] = "Es increíble... Y puede ver videos de gatos en la red.",
  ["Act_E4_2D_Garage_PatientLifter_Look01_Max_010"] = "Al menos Chloe no pesa tanto.",
  ["Act_E4_2D_Garage_Perfusion_Look01_Max_010"] = "Esa debe ser su poderosa máquina de morfina...|No más pipas de marihuana para ella.",
  ["Act_E4_2D_Garage_PhotoChloeWilliam_Max_010"] = "Me alegra haber tomado esta fotografía. Chloe tiene un nuevo recuerdo de William y ella juntos.",
  ["Act_E4_2D_Garage_PinboardSP01_Interact01_Max_010"] = "Qué buen detalle de mis padres mandar una postal.",
  ["Act_E4_2D_Garage_PinboardSP02_Interact01_Max_010"] = "Me pregunto de quién es esta. Es una postal genérica.",
  ["Act_E4_2D_Garage_PinboardSP03_Interact01_Max_010"] = "No estuve con Chloe. Bien hecho.",
  ["Act_E4_2D_Garage_PinboardSP04_Interact01_Max_010"] = "Al menos le mandé selfies de mis viajes a Chloe. Seguramente se sintió genial con eso.",
  ["Act_E4_2D_Garage_Pinboard_Look01_Max_010"] = "El tablero de mensajes de Chloe está vacío desde el accidente.|Y yo no ayudé demasiado. Mal, Max.",
  ["Act_E4_2D_Garage_Scripted_Max_010"] = "Sé que Chloe tiene sed, será mejor que le lleve agua.",
  ["Act_E4_2D_Garage_Scripted_Max_020"] = "Debo ayudar a Chloe como pueda.",
  ["Act_E4_2D_Garage_Scripted_Max_030"] = "Es un poco extraño descansar y ver una película con Chloe como en los viejos tiempos... pero ya que estoy aquí, ¿por qué no?",
  ["Act_E4_2D_Garage_SnowDoe_Look01_Max_010"] = "Aaaah, la venada de nieve... Supongo que no todo ha cambiado.",
  ["Act_E4_2D_Garage_SnowGlobes_Look01_Max_010"] = "Los globos de nieve nos invaden...",
  ["Act_E4_2D_Garage_Tissues_Look01_Max_010"] = "Me alegra ayudar a Chloe a limpiar la arena de su rostro. Ella haría lo mismo por mí.",
  ["Act_E4_2D_Garage_ToyBear_Look01_Max_010"] = "\"Hola, Chloe\".|Ahora le gustan los peluches.",
  ["Act_E4_2D_Garage_Window_Look01_Max_010"] = "¿Chloe verá su jardín y pensará en su infancia? Ahora no puede ni sentir el pasto...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_001"] = "Sé que solo intentas ayudar.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_005"] = "Ahora suenas como un adulto. Parece que fuimos niñas en otra vida.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_008"] = "Pienso en nosotras como pequeñas piratas, corriendo y brincando por Arcadia Bay.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_009"] = "Ojalá pudiera construirnos un... DeLorean.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_010"] = "Dios mío, llenamos todo de harina, incluso a mis padres.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_011"] = "Además, tendrías que ser mi guapa asistente y ayudarme a construir una máquina.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_016"] = "Como ves, no logro alejar a todos mis amigos.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_018"] = "Megan Weaver, pero no la conoces. Me caía bien. Pero después de mi accidente... era \"demasiado\" popular para estar conmigo.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_019"] = "Pero hace mucho tiempo. Eres la única persona de mi infancia que me visita...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_020"] = "Sí, claro. Véanme, \"Chloe del Caribe\". No me subiría a ningún puto barco ahora. A menos que estés conmigo.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_027"] = "Bueno, tampoco me visitaste mucho. Quiero decir, me encantaron tus postales y fotos, pero...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_028"] = "Sí, pregunta estúpida.|No me importa estar sola. No es como que pueda irme de fiesta como una estrella de rock...|o meterme en problemas con mis padres.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_029"] = "Lo sé. Mis papás son maravillosos. Siempre vienen para ver si estoy bien.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_030"] = "¿Cómo? Vamos, no eres SuperMax. Y no es mi intención hacerte sentir culpable. Para eso están mis padres...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_038"] = "¿Así que eres la Dra. Corazón? Creo que están bien, aun lidiando conmigo. Se ríen y se toman de la mano... espero que tengan vida íntima...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_039"] = "Max, el accidente fue muy duro para ellos. Nuestro seguro es pésimo y las cuentas médicas son ridículamente altas.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_040"] = "Entre medicamentos, enfermeras, consumibles... Mis papás nunca tienen dinero y están muy estresados... ¿Vale la pena?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_041"] = "Para nada. Me ocultan las cuentas, pero habría que ser idiota para no imaginar que les estoy costando casi un millón de dólares al año.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_042"] = "Reconozco a una cerebrito porque yo también lo soy.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Chloe_043"] = "Eres una cerebrito. Por eso te quiero.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_002"] = "Sí, se me ha vuelto un mal hábito...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_003"] = "Tienes razón... Ojalá pudiera llevarnos hasta allá otra vez.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_004"] = "¿Con qué amigos pasabas más el tiempo?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_006"] = "¿Qué es lo que recuerdas de nosotras cuando éramos niñas? Todos tenemos recuerdos diferentes...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_007"] = "Para mí, es como si hubiera sido ayer mismo cuando éramos unas pequeñas malcriadas, viendo los \"Power Rangers\" y destrozando la cocina.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_012"] = "¡Fue tan divertido!",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_013"] = "Yo también. Pero, seguimos siendo piratas, a nuestra forma.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_014"] = "Bueno, mmm, con tu mente científica, podrías hacer eso. Pero el viaje por el tiempo también puede joder las cosas...",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_021"] = "Me tienes a mí. No te abandonaré, Chloe.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_031"] = "Sé que no estuve a tu lado. No tengo excusa, soy de lo peor. Pero intento remediar las cosas.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_032"] = "Sé que es una pregunta estúpida, pero... ¿No te sientes sola aquí?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_033"] = "¿Están bien? Quiero decir... entre ellos, ¿son felices juntos?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_034"] = "Te aman muchísimo.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_035"] = "Ya lo creo. Esta tecnología debe ser muy costosa.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_036"] = "¿Y pueden pagar tantas deudas?",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_037"] = "Creo que Joyce y William son increíbles.",
  ["Cue_E4_2D_Garage_CHChloe_Phase01_Max_044"] = "Chloe, tu vida no tiene \"precio\". Y no hablo de tu apellido...",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_010"] = "Max, es genial que estés aquí de nuevo.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_020"] = "Tú eres la única amiga con la que mantuve contacto.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_030"] = "Me alegra saber que eres tan entrometida como siempre.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_040"] = "Mi habitación se ve diferente ahora, ¿no?",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_050"] = "Uh, ¿podrías pasarme el agua, Max?",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_060"] = "Tengo muchas ganas de ver una película contigo. Los DVD están cerca de la TV.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Chloe_070"] = "Max, tengo mucha sed. Necesito... necesito agua.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_015"] = "Me alegra que lo pienses.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_025"] = "Debí mantenerme en contacto.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_035"] = "No quiero decepcionarte.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_045"] = "Sí... pero sigues siendo tú.",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_055"] = "¡Por supuesto!",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_065"] = "¡Ups! ¡Permiso para husmear!",
  ["Cue_E4_2D_Garage_ChloeBed_IGE_Max_075"] = "¡Muéstrame!",
  ["Cue_E4_2D_Garage_Cloth_Chloe_010"] = "Gracias. Creo que te faltó un grano de arena en el ojo.",
  ["Cue_E4_2D_Garage_Cloth_Chloe_030"] = "Es como el proverbio chino: \"Sólo hace falta una chispa para iniciar un incendio\". Ya sabes, como la cosa esa de la mariposa...",
  ["Cue_E4_2D_Garage_Cloth_Max_020"] = "Es difícil de creer cómo un poco de arena puede causar tanto problema.",
  ["Cue_E4_2D_Garage_Cloth_Max_040"] = "Eso he escuchado...",
  ["Cue_E4_2D_Garage_Insertion_Chloe_020"] = "Se siente más bien como una \"celda\" de alta tecnología. Pero tengo suerte de que mis padres se partan en mil pedazos para cuidarme. Sé que es difícil para ellos...",
  ["Cue_E4_2D_Garage_Insertion_Chloe_040"] = "Seguro. En especial cuando no pueden ni salir a caminar solos. A veces actúo como una adolescente consentida, solo para que se desahoguen y me griten. Es patético.",
  ["Cue_E4_2D_Garage_Insertion_Chloe_060"] = "Créeme, siento mucha ira. En especial cuando la enfermera me ve defecar para luego limpiarme el trasero. O cuando los doctores me dan vueltas como si fuera un maniquí...",
  ["Cue_E4_2D_Garage_Insertion_Chloe_080"] = "Gracias de nuevo por venir, Max. Necesito... ingerir líquidos. ¿Puedes traerme un poco de agua?",
  ["Cue_E4_2D_Garage_Insertion_Max_010"] = "Es una \"guarida\" de alta tecnología.",
  ["Cue_E4_2D_Garage_Insertion_Max_030"] = "Ellos están agradecidos de que estés aquí.",
  ["Cue_E4_2D_Garage_Insertion_Max_050"] = "Chloe, eres una hija maravillosa. Eres amable y sensible, cuando ni siquiera tienes que serlo.",
  ["Cue_E4_2D_Garage_Insertion_Max_070"] = "Ni siquiera puedo imaginarlo...|Pero eres genial. Siempre lo has sido, desde que éramos niñas.",
  ["Cue_E4_2D_Garage_Movie_Chloe_010"] = "Mira, soy como un sistema de entretenimiento humano. Estaría bien si te quedaras a ver una peli, como en los viejos tiempos...",
  ["Cue_E4_2D_Garage_Movie_Chloe_030"] = "Mmm, creo que tengo humor para \"Blade Runner\". Siempre lloro al final. Además, ya sabes que siempre quise un fleco de color como el de Pris.",
  ["Cue_E4_2D_Garage_Movie_Chloe_050"] = "Lo sé, te prometo que no me quedaré dormida.|No mientras estés aquí. Aún no.",
  ["Cue_E4_2D_Garage_Movie_Max_020"] = "¿Qué quieres ver?",
  ["Cue_E4_2D_Garage_Movie_Max_040"] = "Lo sé. Te verías genial con cabello azul.|Comencemos con el espectáculo.|Y no te quedes dormida, como siempre cuando vemos películas.",
  ["Cue_E4_2D_Garage_Water_Chloe_020"] = "Con razón tengo seca la garganta. No creo que haya hablado tanto en todo el año.",
  ["Cue_E4_2D_Garage_Water_Chloe_040"] = "Ojalá pudiera golpearte en la cara. ¿Un podcast?|No lo escucharía ni yo misma. Aburrido...",
  ["Cue_E4_2D_Garage_Water_Max_010"] = "Toma, querida.",
  ["Cue_E4_2D_Garage_Water_Max_030"] = "¿Has pensado hacer un podcast o algo?",
  ["Cue_E4_2D_Garage_Water_Max_050"] = "Lo siento. Era solo una idea...",
  ["Act_E4_3A_Bathroom_HairDye_Look01_Max_010"] = "Ese tinte azul me hace muy feliz. Significa que la verdadera Chloe está de regreso... conmigo.",
  ["Act_E4_3A_Bathroom_Sink_Look01_Max_010"] = "La última vez que quise mojarme la cara, mi vida entera cambió...",
  ["Act_E4_3A_ChloeRoom_AshTray_Look01_Max_010"] = "Sí, Chloe Price estuvo aquí.",
  ["Act_E4_3A_ChloeRoom_ButterflyPicture_Look01_Max_010"] = "Esta foto de mariposa parece de hace un millón de años... ¿Cuánto tiempo he alterado desde entonces?",
  ["Act_E4_3A_ChloeRoom_CashBox_Look01_Max_010"] = "Ahí está el dinero de Chloe... Lo siento, director Wells.",
  ["Act_E4_3A_ChloeRoom_ChChloe_Look02_Max_020"] = "Ojalá pudiera decirle a Chloe cuánto le importaba a William...",
  ["Act_E4_3A_ChloeRoom_ChloeRoomWindow_Look01_Max_010"] = "Es un día muy bonito y con buen tiempo. ¿Cómo podría arrasar una tormenta asesina de la nada mañana?",
  ["Act_E4_3A_ChloeRoom_Coffecups_Look01_Max_010"] = "Estar despierta toda la noche es buena excusa para beber mucho café.",
  ["Act_E4_3A_ChloeRoom_CrumbledPapers_Look01_Max_010"] = "Ni siquiera Holmes y Watson usaban todas las pistas que encontraban.",
  ["Act_E4_3A_ChloeRoom_GunMagazine_Look01_Max_010"] = "Esa es mi Chloe.",
  ["Act_E4_3A_ChloeRoom_Gun_Look01_Max_010"] = "Todavía me siento mal de regresar el arma a Chloe.",
  ["Act_E4_3A_ChloeRoom_InvestigationBoard_Look01_Max_010"] = "Es increíble lo inocentes que eran nuestros dibujos en comparación a lo que hacemos ahora.",
  ["Act_E4_3A_ChloeRoom_MagazineClipping_Look01_Max_010"] = "Diablos, esta es una exposición seria de los Prescott... ¡Al fin!",
  ["Act_E4_3A_ChloeRoom_PrintedEmail_Look01_Max_010"] = "Debí suponer que borrar el mensaje no bastaría para detener a la policía...",
  ["Act_E4_3A_ChloeRoom_PrintedEmail_Look03_Max_010"] = "Genial, atraparon a Chloe de nuevo. Fui su cómplice, pero... no esta vez...",
  ["Act_E4_3A_ChloeRoom_Scripted02_Max_020"] = "No puedo abusar de mi poder de rebobinar a este nivel... Es muy peligroso, y necesito navegar el presente sin alterar el pasado...",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_010"] = "Debería revisar la pizarra grande...",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_020"] = "Se ve como un laberinto de pistas... o un completo desastre.",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_030"] = "Ahora mejor voy al garage y reviso los archivos de David...",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_040"] = "Debo ajustarme a estar aquí...",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_050"] = "Sí, estoy de vuelta pero no tengo idea qué pasó en esta zona horaria...",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_060"] = "Nunca vi a Chloe tan concentrada en algo en toda mi vida...",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_070"] = "Para ser dos inadaptadas, creo que estamos muy cerca de encontrar a Rachel Amber.",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_080"] = "¿Habrá otra realidad con Chloe y el accidente?",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_090"] = "Max, deja de pensar en vidas alternas y concéntrate en la que estás.",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_100"] = "Chloe, nunca sabrás lo feliz que estoy de estar de vuelta contigo.",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_110"] = "Chloe, no podría dejarte morir jamás.",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_120"] = "Y si estás en un mundo alterno, perdóname por no inyectarte la morfina...",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_130"] = "Vaya, pasamos de la habitación antiséptica de Chloe al búnker de David.",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_140"] = "Wow, con esta mejora de poderes puedo viajar en el tiempo con cualquier fotografía... o selfie.",
  ["Act_E4_3A_ChloeRoom_Scripted_Max_150"] = "Si comienzo a viajar en el tiempo con mis fotografías, podría joder las cosas aún más...",
  ["Act_E4_3A_ChloeRoom_ShoeBox_Look01_Max_010"] = "Lo lamento mucho, William... Es tan injusto que tuvieras que morir dos veces.",
  ["Act_E4_3A_ChloeRoom_SnowDoe_Look01_Max_010"] = "La venada de nieve sigue rota. Tal como William para Chloe...",
  ["Act_E4_3A_ChloeRoom_SnowDoe_Look02_Max_010"] = "Esa venada de nieve siempre me hace pensar en William y Chloe.",
  ["Act_E4_3A_ChloeRoom_zen_Max_010"] = "Bienvenida de regreso al mundo real Max...",
  ["Act_E4_3A_ChloeRoom_zen_Max_020"] = "No creo que pueda decirle jamás a Chloe lo que ocurrió.",
  ["Act_E4_3A_ChloeRoom_zen_Max_030"] = "¿Cómo le explico a mi mejor amiga que terminó en silla de ruedas por mi culpa, que le practiqué eutanasia y después dejé morir a su papá de nuevo?",
  ["Act_E4_3A_ChloeRoom_zen_Max_040"] = "¿Cómo le explico a mi mejor amiga que terminó en silla de ruedas por mi culpa, que no le ayudé en su último deseo y después dejé morir a su papá de nuevo?",
  ["Act_E4_3A_ChloeRoom_zen_Max_050"] = "Así que... de ninguna puta manera. Chloe tiene suficientes razones para odiar al mundo.",
  ["Act_E4_3A_ChloeRoom_zen_Max_060"] = "Pero si mi visión del tornado es cierta, entonces será el fin del mundo esta semana...",
  ["Act_E4_3A_Corridor_ArcadiaBayPoster_Look01_Max_010"] = "Puede que este sea el último cartel que anuncie a Arcadia Bay después de mañana...",
  ["Act_E4_3A_Corridor_BlueBird_Look01_Max_010"] = "¡Ay, no, el pobre pajarillo está atrapado!",
  ["Act_E4_3A_Corridor_BlueBird_VoiceOver01_Max_010"] = "¡Vuela! ¡Sé libre!",
  ["Act_E4_3A_Corridor_BlueBird_VoiceOver01_Max_020"] = "¡Carajo! Pobrecito...",
  ["Act_E4_3A_Corridor_ParentsDoor_Look01_Max_010"] = "Ya que David quizá esté aquí, mejor me voy, para variar.",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Chloe_010"] = "Me estoy perdiendo en tanta mierda...",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Chloe_020"] = "Siento que hay algo que no estamos viendo...",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Chloe_030"] = "Max, estamos muy cerca de encontrar a Rachel...",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Max_033"] = "Sigue buscando, Chloe...",
  ["Cue_E4_3A_ChloeRoom_ChloeDesk_IGE_Max_036"] = "Chloe, vas bien...",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Chloe_010"] = "“El Tobanga es quizás el tótem original más antiguo de Arcadia Bay”.",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Chloe_020"] = "“A pesar de la controversia, ninguna tribu ha reclamado la propiedad del Tobanga”.",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Chloe_030"] = "Lo siento, Max, pero esto es muy interesante. Además me encanta decir Tobanga... Tobanga...",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Max_025"] = "Nathan Prescott ya lo intentó.",
  ["Cue_E4_3A_ChloeRoom_ChloeTobanga_IGE_Max_035"] = "Espero que el Tobanga también.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_020"] = "Claro... eh, ¿qué cosas?",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_040"] = "Tres: golpear a Padrastúpido hasta que hable sobre Frank, Nathan, y el \"cuarto oscuro\".",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_050"] = "Y ahora tengo un arma...",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_080"] = "Es una lástima que ya no tenga un arma...",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_100"] = "Oye, déjame golpearlo, después rebobina.|En fin, como sea, es tu poder.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_120"] = "Al menos me dejaste tomar el dinero para pagarle a Frank.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_140"] = "Ni siquiera me dejaste tomar el dinero para pagarle a Frank.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_160"] = "Lo sé. Deberías comenzar a trabajar en el garage para ver qué encuentras. Yo ciber-acosaré a algunas personas y ver a dónde llegamos... o a quién.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_170"] = "Y ten cuidado con el padrastro loco... a menos que quieras pasar tiempo con él después de defenderlo ayer.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Chloe_190"] = "Ten cuidado con el padrastro loco. No estará feliz después de que lo regañaste ayer y de que mamá lo corrió...",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_010"] = "Tan cerca, y tan lejos...|Tenemos tres cosas importantes que hacer.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_030"] = "Primera, descifrar el diario de Frank. Segunda, conseguir el teléfono de Nathan para descubrir dónde ha estado durante las fiestas del club Vortex con Kate y Rachel. Y ver qué carajo ocultan sus mensajes.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_060"] = "Mantenla en tus pantalones. Tendremos que hacer esto por nuestra cuenta.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_090"] = "Sí, esa es la solución. Tendremos que hacer esto por nuestra cuenta.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_110"] = "El cual no puedo desperdiciar en esas mamadas. O Blackwell estaría en grandes problemas.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_130"] = "No me lo recuerdes. Solo quiero que deje de molestarte. De molestarnos...",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_150"] = "Y me alegra. Debemos ser mejores personas.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_180"] = "Ay, por favor.",
  ["Cue_E4_3A_ChloeRoom_GoSearchDavid_Max_200"] = "Estoy en eso, compañera.",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_030"] = "¡Tranquila, Max! Un beso y ya estás sobre mí...",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_040"] = "Sí, claro, ¿y de pronto quieres besarme? Tuviste tu oportunidad.",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_060"] = "Suenas drogada, pero gracias por las caricias. Ya que estuvimos despiertas toda la noche jugando a&nbsp;\"CSI:&nbsp;Arcadia Bay\", estaba intentando conectar toda la información.",
  ["Cue_E4_3A_ChloeRoom_Insertion_Chloe_080"] = "Max, ¿ya se te olvidó que hicimos esto? Espero que no hayas estado jugando con el tiempo mientras dormía...",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_010"] = "Chloe... estás de vuelta.",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_020"] = "Chloe... estás viva. ¡Sí!",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_050"] = "Yo solo... yo solo, ¡estoy tan contenta de que estés aquí!",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_090"] = "Ya no. Solo estoy algo ausente.",
  ["Cue_E4_3A_ChloeRoom_Insertion_Max_095"] = "Veamos el tablero y todas las piezas del rompecabezas que tenemos hasta ahora.",
  ["Act_E4_3B_Corridor_FamilyPictures_Look01_Max_010"] = "David no es muy diferente a mí cuando mira las fotos familiares.",
  ["Act_E4_3B_Corridor_FrontDoor_Look01_Max_010"] = "Ayudé a Joyce a perder a William y ahora a David.",
  ["Act_E4_3B_Corridor_FrontDoor_Look02_Max_020"] = "Renuncio a William, pero defiendo a David...|¿Me odiaría Chloe si supiera?",
  ["Act_E4_3B_Garage_Box_Look01_Max_010"] = "Dios, David está empacando cosas de su boda.",
  ["Act_E4_3B_Garage_CrowBar_Look01_Max_010"] = "No puedo forzar la cerradura sin hacer ruido, no con esta barreta y David cerca...",
  ["Act_E4_3B_Garage_CrowBar_Look02_Max_010"] = "Muy bien, puedo usar esta barreta para abrir la cerradura.",
  ["Act_E4_3B_Garage_DavidsFolder_Look01_Max_010"] = "Qué bien que arrojaste esos archivos al aceite, Max. Qué asco...",
  ["Act_E4_3B_Garage_FuseBox_Interact02_Max_010"] = "David definitivamente vendrá si empiezo a jugar con la caja de fusibles de nuevo. Mejor empiezo otra vez.",
  ["Act_E4_3B_Garage_FuseBox_Look01_Max_010"] = "Mmmm, esta caja de fusibles parece la distracción perfecta para David.",
  ["Act_E4_3B_Garage_GunRack02_Look01_Max_010"] = "O Chloe robó otra arma o David anda por ahí armado...",
  ["Act_E4_3B_Garage_GunRack02_Look02_Max_010"] = "La \"cueva\" de David se ve mejor que la habitación de hospital de Chloe.",
  ["Act_E4_3B_Garage_Keys_Take_Max_010"] = "¡Te tengo!",
  ["Act_E4_3B_Garage_Laptop02_Look01_Max_010"] = "¿Debería haber firmado la petición? Es un hecho que Blackwell ya no es “segura y privada”...",
  ["Act_E4_3B_Garage_Laptop02_Look02_Max_020"] = "Prometo que ayudaré a la Sra. Grant la siguiente vez... si hay una.",
  ["Act_E4_3B_Garage_Laptop02_Look03_Max_030"] = "Vaya, Sra. Grant. El dedo en la llaga.",
  ["Act_E4_3B_Garage_Laptop02_Look04_Max_040"] = "Al menos tiene un admirador raro...",
  ["Act_E4_3B_Garage_Laptop02_Look05_Max_050"] = "Ojalá tuviera un video de esa conversación.",
  ["Act_E4_3B_Garage_Laptop02_Look06_Max_060"] = "David realmente protegió a Chloe... me alegra haberlo defendido.",
  ["Act_E4_3B_Garage_Lock_Interact01_Max_030"] = "¡Muy bien! ¡Ábrete, sésamo!",
  ["Act_E4_3B_Garage_Lock_Interact03_Max_050"] = "¡Mierda!",
  ["Act_E4_3B_Garage_Lock_Look01_Max_020"] = "Conozco este candado...",
  ["Act_E4_3B_Garage_Locker02_Look01_Max_010"] = "Parece que se necesita un código. Debe haber una forma de entrar...",
  ["Act_E4_3B_Garage_Locker02_Look01_Max_015"] = "Parece que necesito una llave o un código...",
  ["Act_E4_3B_Garage_Locker02_Take01_Max_010"] = "Ah, sí, sabía que ese número sería importante.",
  ["Act_E4_3B_Garage_Locker02_Take02_Max_020"] = "Soy la ama de llaves.",
  ["Act_E4_3B_Garage_Locker02_Take03_Max_030"] = "Lo lamento David, apuesto a que harías lo mismo que yo.",
  ["Act_E4_3B_Garage_LockerKeys_Interact02_Max_010"] = "Las llaves al reino... o al menos, al casillero de David.",
  ["Act_E4_3B_Garage_LockerKeys_Look01_Max_010"] = "Ya que el casillero está abierto, no necesito la llave...",
  ["Act_E4_3B_Garage_Nest_Interact01_Max_010"] = "¡Clic! Otra foto para mi “Serie de vida silvestre de Arcadia Bay”.",
  ["Act_E4_3B_Garage_Nest_Look01_Max_010"] = "¡Qué ternura! ¡Mira los huevitos de urraca azul en el nido! Será mejor mover esta tabla para tomar la foto...",
  ["Act_E4_3B_Garage_Nest_Look02_Max_010"] = "Por favor, que estos pajaritos no mueran como los demás...",
  ["Act_E4_3B_Garage_Nest_Look03_Max_010"] = "Max, lo mejor sería que pusieras esa tabla de regreso para proteger el nido.",
  ["Act_E4_3B_Garage_Plank_Interact01_Max_010"] = "Perdonen, solo una foto, por favor.",
  ["Act_E4_3B_Garage_Plank_Interact02_Max_010"] = "¡Gracias! Duerman bien, huevitos.",
  ["Act_E4_3B_Garage_Plank_Look01_Max_010"] = "Esta tabla es buena para proteger el nido, pero mala para tomar la foto.",
  ["Act_E4_3B_Garage_PrescottLink01_Look01_Max_010"] = "¿Cámaras de vigilancia en Pan Estates? David debe estar trabajando para los Prescott también.",
  ["Act_E4_3B_Garage_PrescottLink02_Look01_Max_010"] = "Mmmm, ¿qué diablos haría David por Nathan? ¿Y qué haría su papá por David?",
  ["Act_E4_3B_Garage_ScriptedCar_Max_010"] = "Parece que David terminó las reparaciones de su auto. Tal vez hay nuevas pistas por ahí.",
  ["Act_E4_3B_Garage_ScriptedCar_Max_020"] = "¿Qué haría David si apago todas las luces?",
  ["Act_E4_3B_Garage_ScriptedCar_Max_030"] = "Tal vez pueda solo cortar la electricidad...",
  ["Act_E4_3B_Garage_ScriptedDavidStuff_Max_010"] = "No puedo permitir que David me vea mientras le quitó sus llaves. ¡Modo ninja!",
  ["Act_E4_3B_Garage_ScriptedFilesFound_Max_010"] = "Wow... Mapas, notas, coordenadas, fotos de Kate, Nathan... ¡Genial!",
  ["Act_E4_3B_Garage_ScriptedObjectiveDavid_Max_010"] = "David no se marchará si se lo pido \"por favor\", así que necesito distraerlo...",
  ["Act_E4_3B_Garage_ScriptedObjectiveDavid_Max_020"] = "David definitivamente no podría trabajar a oscuras...",
  ["Act_E4_3B_Garage_ScriptedObjectiveDavid_Max_030"] = "Quizá debería solo cortar la corriente...",
  ["Act_E4_3B_Garage_ScriptedPadlock_Max_010"] = "¡Vaya, es un candado enorme para un casillero! ¿Qué ocultas, David?",
  ["Act_E4_3B_Garage_ScriptedRewind_Max_010"] = "Max, rebobina para que David no te vea.",
  ["Act_E4_3B_Garage_ScriptedStayHidden_Max_010"] = "Sería mejor que David no me vea...",
  ["Act_E4_3B_Garage_Scripted_Max_010"] = "Por primera vez, no tengo tiempo de buscar el código... Necesito abrir el candado de alguna forma.",
  ["Act_E4_3B_Garage_Scripted_Max_020"] = "No confío por completo en David, pero tampoco es un dictador. Tal vez Chloe se dé cuenta algún día...",
  ["Act_E4_3B_Garage_Scripted_Max_030"] = "Es mi culpa que Joyce haya echado a David... Max Caulfield, rompehogares.",
  ["Act_E4_3B_Garage_Scripted_Max_040"] = "Será mejor examinar esos casilleros.",
  ["Act_E4_3B_Garage_Scripted_Max_050"] = "¡Lotería! De regreso con Chloe.",
  ["Act_E4_3B_Garage_Scripted_Max_060"] = "Por primera vez, no tengo tiempo para buscar el código... Necesito encontrar la llave.",
  ["Act_E4_3B_Garage_Trash_Look01_Max_010"] = "David Madsen es más de lo que aparenta. Debería terminar su carta para Joyce...",
  ["Act_E4_3B_Garage_VortexFlyer_Look01_Max_010"] = "Me pregunto si David irá a la fiesta...",
  ["Act_E4_3B_Garage_WilliamStuff_Look01_Max_010"] = "Qué triste. Fue tan genial ver a William de nuevo. Ojalá Chloe pudiera verlo también.",
  ["Act_E4_3B_Garden_DeadBirds_Look01_Max_010"] = "Pobres aves... Supongo que David no estaba de humor para limpiar.",
  ["Act_E4_3B_Garden_DeadBirds_Look02_Max_020"] = "David puso en bolsas a los pájaros muertos...",
  ["Act_E4_3B_Garden_HouseWall_Look01_Max_010"] = "William nunca terminó de pintar la pared...",
  ["Act_E4_3B_LivingRoom_BayWindow_Look01_Max_010"] = "¿Cómo podría una tormenta acabar con Arcadia Bay mañana, con este clima?",
  ["Act_E4_3B_LivingRoom_BrokenClock_Interact01_Max_010"] = "Oh... Hay un insecto atorado en los indicadores.",
  ["Act_E4_3B_LivingRoom_BrokenClock_Look01_Max_010"] = "¿De verdad provoqué que el reloj se detuviera?",
  ["Act_E4_3B_LivingRoom_BrokenClock_Look02_Max_020"] = "El tiempo sigue su curso.",
  ["Act_E4_3B_LivingRoom_ButterflyDrawing_Look01_Max_010"] = "Mi dibujo de la mariposa no existe en esta línea de tiempo... como William. “Max, la bandida del tiempo”, ataca de nuevo.",
  ["Act_E4_3B_LivingRoom_CookieJar_Look01_Max_010"] = "Parece que están de nuevo en camino a París.",
  ["Act_E4_3B_LivingRoom_Door02_Interact01_Max_010"] = "Sí, cerrado por el otro lado.",
  ["Act_E4_3B_LivingRoom_FridgeNote_Look01_Max_010"] = "Eso dolió.",
  ["Act_E4_3B_LivingRoom_FridgeNote_Look02_Max_020"] = "Joyce realmente quiere que David y Chloe sean una familia.",
  ["Act_E4_3B_LivingRoom_KitchenTV_Look01_Max_010"] = "Joyce solía ver las noticias mientras hacía la cena.",
  ["Act_E4_3B_LivingRoom_MotelList_Look01_Max_010"] = "Parece que David ya reservó una habitación.",
  ["Act_E4_3B_LivingRoom_Newspaper_Look01_Max_010"] = "Y pensar que todo esto empezó con mi visión de un tornado...",
  ["Act_E4_3B_LivingRoom_RestaurantBill_Look01_Max_010"] = "¡Es el restaurante más caro de la ciudad! David sabe cómo consentir a Joyce.",
  ["Act_E4_3B_LivingRoom_Scripted02_Max_010"] = "Es impresionante cuánto drama ha visto esta sala.",
  ["Act_E4_3B_LivingRoom_Scripted02_Max_020"] = "Vamos, Max, encuentra una forma para sacar a David de su lugar...",
  ["Act_E4_3B_LivingRoom_ScriptedCantGo_Max_010"] = "No puedo irme antes de buscar en el garage de David.",
  ["Act_E4_3B_LivingRoom_ScriptedCantGo_Max_020"] = "No puedo ir con Chloe sin antes revisar el casillero de David.",
  ["Act_E4_3B_LivingRoom_Stool_Max_010"] = "De alguna forma yo existí en esta otra realidad, pero no sé cómo ocurrió...",
  ["Act_E4_3B_LivingRoom_Stool_Max_020"] = "Mientras más uso mi poder, más me doy cuenta del poco control que tengo sobre lo que pasa.",
  ["Act_E4_3B_LivingRoom_Stool_Max_030"] = "Max Caulfield existe en dos o quizá tres realidades distintas... ¿Cómo puedo tener un solo destino?",
  ["Act_E4_3B_LivingRoom_Stool_Max_040"] = "Si estas vidas alternas existen, odio que William y Joyce encuentren a Chloe así.",
  ["Act_E4_3B_LivingRoom_Stool_Max_050"] = "Me pregunto si Chloe me odia por mantenerla con vida... pero no pude hacerlo.",
  ["Act_E4_3B_LivingRoom_Stool_Max_060"] = "Pensar sobre todo esto hace que me duela la cabeza más que al rebobinar.",
  ["Act_E4_3B_LivingRoom_TV_Look01_Max_010"] = "Esas pobres ballenas son como ángeles encallados. ¿Qué está ocurriendo aquí?",
  ["Act_E4_3B_LivingRoom_TornPhoto_Look01_Max_010"] = "Joyce debe estar molesta... ¿Estás ayudando a alguien Max?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_001"] = "No puedo decirte todo lo que sucede en Blackwell. Ya has visto mucho. Así que, por favor, mantente fuera de esto, Max.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_007"] = "¿Qué? ¡¿Quién te dijo eso?! ¿Nathan Prescott? ¡Ese imbécil tuvo suerte de que solo lo suspendieran!",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_008"] = "¿Qué? ¡¿Quién te dijo eso?! ¿Nathan Prescott? ¡Ese imbécil tuvo suerte de que no lo suspendieran!",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_011"] = "Y tú hiciste que me despidieran, así que estamos a mano. Casi.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_012"] = "No tenía todas las pruebas en su momento. Lo... lo lamento, Max.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_013"] = "¿Entonces me dirás por qué crees que trabajo para Sean Prescott?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_014"] = "Ese imbécil de Nathan Prescott tiene suerte de que solo lo suspendieran...",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_015"] = "¿Nathan Prescott? Ese imbécil tiene suerte de que no lo suspendieran.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_018"] = "Demonios, eres una buena detective. Pero no me contrataron. Le di a Sean Prescott un estimado. Por mis propios motivos.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_019"] = "Supongo que yo tampoco confiaría en mí. Pero nunca trabajaría para Sean Prescott y su jodida familia.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_020"] = "De cualquier forma, creo que podemos acordar que ha sido una semana difícil para todos... En especial para la pobre Kate Marsh.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_023"] = "Tú lo hiciste, Max. La salvaste, eres una heroína. Mientras que yo dejé abierta la maldita puerta de la azotea... Sabía que Kate se sentía muy mal.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_024"] = "Tú intentaste ayudarla más que nadie, Max, a diferencia de mí. Además, dejé abierta la maldita puerta de la azotea... Sabía que Kate se sentía muy mal.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_025"] = "Incluso llegaste al techo antes que yo o que nadie más.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_028"] = "Ese es un pendejo elitista. Estoy fuera de servicio, así que lo puedo decir. Como cuando Chloe me llama \"padrastúpido\". Estos \"artistas\" viven en un mundo de fantasía.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_031"] = "Justamente a eso me refiero: elitista.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_032"] = "Estos supuestos artistas viven en su propio mundo. Cuando estaba en el ejército, odiaba a los fotógrafos que intentaban usarnos para sus estupideces pacifistas.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_034"] = "Tengo una familia, Max. Y creo que Blackwell es el mejor sitio para mí, porque solo yo sé lo que ocurre.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_035"] = "Por supuesto, gracias a la señora Grant y su petición antivigilancia \"hippie\"|todos están más seguros... como Rachel Amber y Kate Marsh.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_037"] = "Es por eso que trabajo en el nuevo plan de vigilancia de Blackwell, para proteger a los futuros estudiantes y que no terminen como Rachel Amber o Kate Marsh...",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_038"] = "Aunque es cierto, eres como un sistema de vigilancia ambulante. Agradezco que me defendieras, pero tengo que ser inflexible y decirte a ti y a Chloe que no se involucren. Las cosas se pondrán peor.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_David_040"] = "Si me permites, Max, debo continuar con mi cámara. ¿Lo ves? También soy artista.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_004"] = "¿A qué te refieres con “lugares oscuros”?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_005"] = "Demasiado tarde. Ya sé mucho. Como el hecho de que quizá trabajes para Sean Prescott...",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_006"] = "Demasiado tarde. Ya sé mucho. Así que tú y Nathan Prescott...",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_009"] = "Sí, y yo tuve suerte de que solo me suspendieran... gracias a ti.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_010"] = "No creo que la suerte haya tenido algo que ver. Podrían haberme suspendido también.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_016"] = "Vi documentos que dicen que te contrataron para llevar la seguridad de Pan Estates.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_017"] = "No, David. Pero sé lo poderosa que es la familia Prescott... y tú trabajas con ellos.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_021"] = "Es una lástima que nadie la ayudó cuando lo necesitaba.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_022"] = "Intenté ayudar a Kate.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_026"] = "También sabía que Kate estaba mal. Igual el profesor Jefferson. ¿Por qué hice que lo suspendieran?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_027"] = "Yo también sabía que Kate estaba mal. Igual el profesor Jefferson.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_029"] = "Quizá Jefferson sea pretencioso, pero también yo... Él ha sido una gran influencia en mi fotografía.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_030"] = "¿Por qué lo dices?",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_033"] = "Mira, la Academia Blackwell es una escuela para artistas,|así que tal vez no es el mejor lugar para ti.",
  ["Cue_E4_3B_Garage_CHDavid_Phase01_Max_039"] = "Chloe y yo nos podemos cuidar solas.",
  ["Cue_E4_3B_Garage_CHDavid_Phase02_David_002"] = "Lo siento, Max, no puedo hablar y trabajar.",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_010"] = "Oye, señorita, ¿sí sabes que puedo verte husmeando verdad?",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_020"] = "Claro que es difícil trabajar en privado con alguien observándote.",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_030"] = "Lo siento, pero esta es mi \"cueva\" oficial de soltero, así que...|No se permiten mujeres.",
  ["Cue_E4_3B_Garage_DavidGarage_IGE_David_040"] = "Oye, Max, aprecio que me defendieras.",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_Chloe_030"] = "¡Mierda! ¡Que alguien arregle el fusible!",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_010"] = "Max, no me gusta la gente en mi espacio personal. Lo digo en serio.",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_020"] = "¡Con un carajo, acabo de arreglar los fusibles!",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_050"] = "¡Oye, Max! ¡No toques nada, carajo!",
  ["Cue_E4_3B_Garage_DavidPuzzle_IGE_David_060"] = "¡Oye!",
  ["Cue_E4_3B_Garage_Extraction_RTC_Max_010"] = "¿Chloe, ya estás lista? ¡Debo regresar a la residencia!",
  ["Cue_E4_3B_Garage_Extraction_RTC_Max_030"] = "Muy feliz. Encontré los archivos secretos más buscados: Kate, Nathan... y Rachel. Además, las coordenadas de algún lugar. David es como un ejército de vigilancia. Ahora, larguémonos antes de que nos atrapen.",
  ["Cue_E4_3B_Garage_Extraction_RTC_Max_035"] = "Muy feliz. Encontré los archivos secretos más buscados: Kate, Nathan... y Rachel. Además, las coordenadas de algún lugar. David es como un ejército de vigilancia. Ahora, larguémonos antes de que nos atrapen.",
  ["Cue_E4_3B_LivingRoom_DavidLeaving_David_010"] = "Ganaste esta batalla, Max. Destrozaste mi familia. Te felicito.",
  ["Cue_E4_3B_LivingRoom_DavidLeaving_David_030"] = "Demasiado tarde, ¿no? Más te vale tener cuidado con ella. No te pierdas en la oscuridad...",
  ["Cue_E4_3B_LivingRoom_DavidLeaving_Max_020"] = "David, no fue mi intención herirte. Nunca. Pero no permitiré que nadie lastime a Chloe.",
  ["Cue_E4_3B_LivingRoom_DavidWorking_David_010"] = "¿Hay algo en lo que te pueda ayudar, Max?",
  ["Cue_E4_3B_LivingRoom_DavidWorking_David_030"] = "Te debo una, así que fingiré que lo que dices es verdad, pequeña.",
  ["Cue_E4_3B_LivingRoom_DavidWorking_David_050"] = "Así es. Será mejor que tú y Chloe anden con cuidado. Hay muchos lugares oscuros en Arcadia Bay.",
  ["Cue_E4_3B_LivingRoom_DavidWorking_Max_020"] = "Estaba... Solo esperaba a que Chloe saliera del baño para irnos.",
  ["Cue_E4_3B_LivingRoom_DavidWorking_Max_040"] = "Querrás decir señorita Caulfield...",
  ["Cue_E4_3B_LivingRoom_Extraction_Chloe_010"] = "¿Estamos felices?",
  ["Cue_E4_3B_LivingRoom_Extraction_Chloe_040"] = "Ahora veamos qué oculta Nathan en su habitación.",
  ["Cue_E4_3B_LivingRoom_Extraction_Chloe_070"] = "Max, es hora de que Nathan Prescott tenga miedo de nosotras.",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_020"] = "Ah, sí. Larguémonos de aquí.",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_030"] = "Pero necesito ver a Kate en el hospital ahora mismo. Quiero saber cómo está.",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_050"] = "Debemos tener mucho cuidado.",
  ["Cue_E4_3B_LivingRoom_Extraction_Max_055"] = "Debemos tener mucho cuidado...",
  ["Act_E4_3C_ChloeRoom_CHChloe_Look01_Max_010"] = "Chloe, lamento tanto que estés pasando por esto.",
  ["Act_E4_3C_ChloeRoom_CHChloe_Look02_Max_020"] = "Chloe ha encontrado tantas pistas para dar con Rachel. Estamos muy cerca...",
  ["Act_E4_3C_ChloeRoom_Computer_Look01_Max_010"] = "Hemos impreso todo lo que necesitamos, ahora es tiempo de concentrarse en la pizarra...",
  ["Act_E4_3C_ChloeRoom_DavidClue01Step1_Look01_Max_010"] = "David debió hacer mucho más que tomar fotos de Kate.",
  ["Act_E4_3C_ChloeRoom_DavidClue01Step2_Look01_Max_010"] = "Muy bien, averigüemos de quién es ese auto.",
  ["Act_E4_3C_ChloeRoom_DavidClue01Step3_Look01_Max_010"] = "Sin duda, Nathan usa su dormitorio... podría ocultar pistas ahí también.",
  ["Act_E4_3C_ChloeRoom_DavidClue02Step1_Look01_Max_010"] = "Mira todas estas placas de auto. Espero que estuviera siguiendo a Nathan.",
  ["Act_E4_3C_ChloeRoom_DavidClue02Step2_Look01_Max_010"] = "Sí. Otro auto que David rastreaba.",
  ["Act_E4_3C_ChloeRoom_DavidClue02Step3_Look02_Max_020"] = "Esa playa era como la oficina principal de Frank.",
  ["Act_E4_3C_ChloeRoom_DavidClue03Step1_Look01_Max_010"] = "Necesitas deshacerte de esas malditas cámaras David.",
  ["Act_E4_3C_ChloeRoom_DavidClue03Step2_Look01_Max_010"] = "Mmmm, ¿a quién más estaba rastreando David?",
  ["Act_E4_3C_ChloeRoom_DavidClue03Step3_Look01_Max_010"] = "Ah, sin duda es la propiedad Prescott. Millonario, pero... pobre Nathan.",
  ["Act_E4_3C_ChloeRoom_DavidClue04Step1_Look01_Max_010"] = "Al menos David iba tras el sospechoso correcto.",
  ["Act_E4_3C_ChloeRoom_DavidClue04Step2_Look01_Max_010"] = "Por supuesto, Nathan maneja una SUV. Consentido, como siempre.",
  ["Act_E4_3C_ChloeRoom_DavidClue04Step3_Look02_Max_020"] = "No hay mucho que ver.",
  ["Act_E4_3C_ChloeRoom_DavidClue05Step1_Look01_Max_010"] = "¿David sabe lo que ocurrió con Rachel, o solo es paranoico con todos?",
  ["Act_E4_3C_ChloeRoom_DavidClue05Step2_Look01_Max_010"] = "¿Por qué diablos estás siguiendo a esta gente? ¿Y a dónde?",
  ["Act_E4_3C_ChloeRoom_DavidClue05Step3_Look01_Max_010"] = "¿Acumulando gasolina...? ¿Por qué?",
  ["Act_E4_3C_ChloeRoom_DavidClue06Step1_Look01_Max_010"] = "Por supuesto, soy una de los sospechosos. Prueba de que David es un pésimo detective. Lo siento.",
  ["Act_E4_3C_ChloeRoom_DavidClue06Step2_Look01_Max_010"] = "Definitivamente ese es el auto de Chloe.",
  ["Act_E4_3C_ChloeRoom_DavidClue06Step3_Look01_Max_010"] = "Sé que Nathan no estaba buscando a Pies Grandes en el bosque...",
  ["Act_E4_3C_ChloeRoom_DavidClue07Step1_Look01_Max_010"] = "David realmente ha seguido pistas sobre Rachel por un buen tiempo. Eso debió haberla molestado.",
  ["Act_E4_3C_ChloeRoom_DavidClue07Step2_Look01_Max_010"] = "Mmm, ¿de quién es este carro?",
  ["Act_E4_3C_ChloeRoom_DavidClue07Step3_Look01_Max_010"] = "¿Frank se veía con Nathan en el depósito de chatarra?",
  ["Act_E4_3C_ChloeRoom_DavidClue08Step1_Look01_Max_010"] = "Espero que David sea hábil para rastrear, en especial ahora.",
  ["Act_E4_3C_ChloeRoom_DavidClue08Step2_Look01_Max_010"] = "Me alegra que Warren se vengara.",
  ["Act_E4_3C_ChloeRoom_DavidClue08Step2_Look02_Max_020"] = "¿Y si dejo que Warren ponga en su lugar a Nathan? Solo esta vez.",
  ["Act_E4_3C_ChloeRoom_DavidClue08Step3_Look01_Max_010"] = "Si Joyce supiera lo que Nathan le hizo a Chloe... lo freiría.",
  ["Act_E4_3C_ChloeRoom_DavidClue09Step1_Look01_Max_010"] = "Mmmm, tal vez él trataba de ayudar a Kate en su propia forma retorcida.",
  ["Act_E4_3C_ChloeRoom_DavidClue09Step2_Look01_Max_010"] = "Vaya, esta parece una máquina muy cara.",
  ["Act_E4_3C_ChloeRoom_DavidClue10Step2_Look01_Max_010"] = "Ahí está Nathan, vendiendo droga a los niños a plena vista.",
  ["Act_E4_3C_ChloeRoom_DavidClue11Step2_Look01_Max_010"] = "Interesante... ¿Es el auto de Nathan?",
  ["Act_E4_3C_ChloeRoom_DeadBlueBird_Look01_Max_010"] = "Dios mío, atrapé a ese pájaro aquí y murió tratando de escapar. Bien hecho Max.",
  ["Act_E4_3C_ChloeRoom_Flyer_Look01_Max_010"] = "Entonces, esta infame fiesta fue el 4...",
  ["Act_E4_3C_ChloeRoom_FrankClue01Step1_Look01_Max_010"] = "Libro de cuentas de Frank. Pero los nombres de los clientes están encriptados.",
  ["Act_E4_3C_ChloeRoom_FrankClue01Step2_Look01_Max_010"] = "Muy bien, Max, recuerda estos nombres y veamos cómo encaja Nathan en todo esto.",
  ["Act_E4_3C_ChloeRoom_FrankClue02Step1_Look01_Max_010"] = "Sin duda, Frank es el \"vendedor local\", pero dudo que Rachel la distribuyera... ¿o sí?",
  ["Act_E4_3C_ChloeRoom_FrankClue02Step2_Look01_Max_010"] = "Es un hecho que Frank mantiene a sus clientes satisfechos. Podría abrir una tienda.",
  ["Act_E4_3C_ChloeRoom_FrankClue03Step1_Look01_Max_010"] = "¿Entonces qué ocurrió con Rachel? Dejó a Frank, pero no creo que él le hiciera daño.",
  ["Act_E4_3C_ChloeRoom_FrankClue03Step2_Look01_Max_010"] = "Todos en Arcadia Bay deben estar drogados. Eso explica mucho.",
  ["Act_E4_3C_ChloeRoom_FrankClue04Step1_Look01_Max_010"] = "\"Rott\" debe ser por Rottweiler. Le quedaría mejor ponerle \"Cerdo\".",
  ["Act_E4_3C_ChloeRoom_FrankClue04Step2_Look01_Max_010"] = "Si Frank aplicara este nivel de detalle a su vida...|¿Quién soy yo para opinar?",
  ["Act_E4_3C_ChloeRoom_FrankClue05Step1_Look01_Max_010"] = "Tal vez Rachel se fue de paseo con Frank, pero sí regresó.",
  ["Act_E4_3C_ChloeRoom_FrankClue05Step2_Look01_Max_010"] = "Mmmm, dos operaciones con Nathan el mismo día...|\"Suministros para la fiesta\" sin dudas.",
  ["Act_E4_3C_ChloeRoom_FrankClue06Step1_Look01_Max_010"] = "Es extraño que fueran tan cercanos. Pero Frank perdió a Rachel... o no pudo protegerla.",
  ["Act_E4_3C_ChloeRoom_FrankClue06Step2_Look01_Max_010"] = "Estoy volando con solo leer esto.",
  ["Act_E4_3C_ChloeRoom_FrankClue07Step1_Look01_Max_010"] = "No hay duda que ella lo amaba de alguna forma...",
  ["Act_E4_3C_ChloeRoom_FrankClue07Step2_Look01_Max_010"] = "¿Qué nombre de perro me pondría Frank?",
  ["Act_E4_3C_ChloeRoom_Gun_Look01_Max_010"] = "Lo siento Frank... Debo enterrar esta basura.",
  ["Act_E4_3C_ChloeRoom_Gun_Look02_Max_020"] = "¿Nuestro plan tenía que incluir dispararle a Frank en la pierna?",
  ["Act_E4_3C_ChloeRoom_Gun_Look03_Max_030"] = "Lo lamento, tenemos a Frank de nuestro lado y no te necesitamos.",
  ["Act_E4_3C_ChloeRoom_NathanClue01Step1_Look01_Max_010"] = "Cuántos números.",
  ["Act_E4_3C_ChloeRoom_NathanClue02Step1_Look01_Max_010"] = "Carajo, Nathan está realmente trastornado... pero los números pueden ser útiles.",
  ["Act_E4_3C_ChloeRoom_NathanClue03Step1_Look01_Max_010"] = "¡Lo tengo! Es bueno ver que los Prescott no pueden borrar todas sus huellas...",
  ["Act_E4_3C_ChloeRoom_NathanClue04Step1_Look01_Max_010"] = "Es la fiesta del club Vortex donde Nathan drogó a Kate. ¿Le hizo lo mismo a Rachel en otra?",
  ["Act_E4_3C_ChloeRoom_NathanClue05Step1_Look01_Max_010"] = "¿Y si este NIP sirve de algo?",
  ["Act_E4_3C_ChloeRoom_NathanClue06Step1_Look01_Max_010"] = "Ah, debe haber algo útil en su teléfono... solo necesito desbloquearlo.",
  ["Act_E4_3C_ChloeRoom_NathanClue07Step1_Look01_Max_010"] = "Si hay un \"Cuarto oscuro\", será mejor encontrarlo. Al menos Chloe pasó todos estos archivos a su memoria USB.",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhoneSMS01_Look01_Max_010"] = "Nathan quería algo la noche de la fiesta...¿No tendría suficientes drogas?",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhoneSMS02_Look01_Max_010"] = "Sí, todo fue porque Nathan trataba de ligar en la fiesta del club Vortex...",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhoneSMS04_Look01_Max_010"] = "Drama de traficantes...",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhoneSMS05_Look01_Max_010"] = "Por Dios, Nathan... estás fuera de control.",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhoneSMS06_Look01_Max_010"] = "Así que eras tú... Oficialmente te puedo llamar \"acosador psicópata\".",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhoneSMS07_Look01_Max_010"] = "No, Nathan. Es tu turno de tener miedo, cabrón...",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhoneSMS08_Look01_Max_010"] = "¿Esto es del padre de Nathan? Es brutal.",
  ["Act_E4_3C_ChloeRoom_NathanUnlockedPhone_Look01_Max_010"] = "¡Lotería! Veamos todos los mensajes de la semana en que drogaron a Kate.",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid01Hint01_Scripted_Max_010"] = "Parece que David estaba rastreando el auto de alguien... tal vez incluso el de Nathan. Buena pista.",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid01Hint02_Scripted_Max_010"] = "Necesito revisar las placas y coordenadas para ver si David|estaba vigilando a Nathan...|Juego de espías...",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid01Win_Scripted_Max_010"] = "Eso es todo, amigos. Veamos qué pistas sobre Nathan hay aquí...",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid01_Scripted_Max_010"] = "Gracias a la propia investigación de David, debería ser capaz de averiguar lo que Nathan hizo la semana de la fiesta.",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid02Hint01_Scripted_Max_010"] = "Vamos, deduce las placas de Nathan y después ve cuáles corresponden con las coordenadas.",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid02Hint02_Scripted_Max_010"] = "Okey, la luz trasera de Nathan no sirve. Estoy segura de que vi eso en una de las fotos...",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid02Win_Scripted_Max_010"] = "¡Elemental, mi querida Max! ¡Este es el auto de Nathan! Ahora veamos dónde estaba este hijo de puta el día del club Vortex.",
  ["Act_E4_3C_ChloeRoom_ObjectiveDavid02_Scripted_Max_010"] = "Genial, ahora ¿cómo sé cuál es el auto de Nathan para ver las coordenadas?",
  ["Act_E4_3C_ChloeRoom_ObjectiveEnd_Scripted_Max_010"] = "Creo que ya puedo unir todas las piezas...",
  ["Act_E4_3C_ChloeRoom_ObjectiveEnd_Scripted_Max_020"] = "Vamos, Max... lo tienes...",
  ["Act_E4_3C_ChloeRoom_ObjectiveEnd_Scripted_Max_030"] = "Eso es... Vamos por ti Rachel...",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank01Hint01_Scripted_Max_010"] = "Apuesto que podría revisar mejor algunas pistas en el libro de cuentas de Frank... si pudiera descifrar los estúpidos nombres...",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank01Hint02_Scripted_Max_010"] = "Podría usar el código que Frank nos dio para descifrar los nombres en el libro de cuentas.",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank01Win_Scripted_Max_010"] = "¡Sí! ¡Vamos por buen camino! Vamos, libro de cuentas, cuéntanos lo que sabes...",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank01_Scripted_Max_010"] = "Veamos los negocios de droga de Frank durante la semana de la fiesta.",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank02Hint01_Scripted_Max_010"] = "Si Nathan drogó a Kate, seguro compró las drogas a Frank...",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank02Hint02_Scripted_Max_010"] = "Max, lo único que falta es encontrar si Frank y Nathan hicieron negocios esa semana...",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank02Win_Scripted_Max_010"] = "Ah, sí, estos son todos los lugares y horas de los negocios de Frank y Nathan. Perfecto, Max.",
  ["Act_E4_3C_ChloeRoom_ObjectiveFrank02_Scripted_Max_010"] = "Mmmm, veamos si puedo encontrar algún negocio que Frank haya hecho con Nathan o el club Vortex.",
  ["Act_E4_3C_ChloeRoom_ObjectiveMiddle_Scripted_Max_010"] = "Finalmente llegamos a algo...",
  ["Act_E4_3C_ChloeRoom_ObjectiveMiddle_Scripted_Max_020"] = "No te detengas, Max... casi lo logramos...",
  ["Act_E4_3C_ChloeRoom_ObjectiveMiddle_Scripted_Max_030"] = "Tan cerca... estamos tan cerca...",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan01Hint01_Scripted_Max_010"] = "Debe haber alguna pista o números que pudieran ser su NIP...",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan01Hint02_Scripted_Max_010"] = "¿Me pregunto si hay fechas o números importantes en su archivo escolar?",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan01Win_Scripted_Max_010"] = "Muy bien, Max, descifremos el código y vayamos a casa.",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan01_Scripted_Max_010"] = "Necesito analizar los mensajes de Nathan. ¿Con qué podría desbloquear el teléfono?",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02Win_Scripted_Max_010"] = "¡Genial! Veamos qué es lo que Nathan Prescott intenta ocultar...",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02Wrong01_Scripted_Max_010"] = "Ups. Código equivocado.",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02Wrong02_Scripted_Max_010"] = "Sí, sabía que no sería fácil.",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02Wrong03_Scripted_Max_010"] = "¡Lo bloqueaste, mensa!",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02WrongPuk_Scripted_Max_010"] = "Código incorrecto... ¡Carajo contigo!|Ya verás, porquería...",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02WrongPuk_Scripted_Max_020"] = "Piensa, piensa. Revisa esta basura de nuevo, omitiste algo.",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02WrongPuk_Scripted_Max_030"] = "No es tan difícil. Anota el código o memorízalo. Puedes hacerlo, Max.",
  ["Act_E4_3C_ChloeRoom_ObjectiveNathan02_Scripted_Max_010"] = "¡A investigar!",
  ["Act_E4_3C_ChloeRoom_ObjectiveStart_Scripted_Max_010"] = "Necesito descubrir qué pasó con Kate en la fiesta y a dónde la llevo Nathan exactamente...",
  ["Act_E4_3C_ChloeRoom_ObjectiveStart_Scripted_Max_020"] = "Mejor me concentro en este tablero y comienzo a atar cabos sueltos...",
  ["Act_E4_3C_ChloeRoom_ObjectiveStart_Scripted_Max_030"] = "Es un laberinto de pistas... ¿dónde estamos?",
  ["Act_E4_3C_ChloeRoom_ObjectiveStep03Hint01_Scripted_Max_010"] = "Si puedo encontrar la correspondencia entre los mensajes de texto y los negocios con Frank... podría encontrar la ubicación exacta.",
  ["Act_E4_3C_ChloeRoom_ObjectiveStep03Hint02_Scripted_Max_010"] = "Kate se fue de la fiesta temprano con Nathan... debo buscar mensajes, ubicaciones y negocios temprano por la noche...",
  ["Act_E4_3C_ChloeRoom_ObjectiveStep03Hint03_Scripted_Max_010"] = "Max, solo encuentra el mensaje correcto que corresponde con la entrada correcta en el libro de cuentas. Entonces descubrirás a dónde llevó Nathan a Kate...",
  ["Act_E4_3C_ChloeRoom_ObjectiveStep03Hint04_Scripted_Max_010"] = "Estoy segura de que todo ocurrió durante la última fiesta del club Vortex. ¿Qué fecha era?",
  ["Act_E4_3C_ChloeRoom_ObjectiveStep03Hint05_Scripted_Max_010"] = "Kate estaba completamente fuera de sí esa noche. Nathan debió usar algo muy fuerte para noquearla.",
  ["Act_E4_3C_ChloeRoom_ObjectiveStep03_Scripted_Max_010"] = "Respira, Max... ¡Revisa todos los datos y descubrirás a dónde llevó Nathan a Kate después de la fiesta!",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_010"] = "No, no funciona...",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_020"] = "Diablos, hay algo que pasé por alto...",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_030"] = "No avancé nada. Va de nuevo.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_040"] = "Error. Abortar. Pistas equivocadas.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_050"] = "Apesto... justo como en matemáticas.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_060"] = "Bueno, esto es triste, Max.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_070"] = "Esto no tiene sentido, Max.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_080"] = "No hay conexión lógica entre esas pistas, Max.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_090"] = "Nop... tal vez si uno otras pistas...",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_100"] = "Parece que esto no es relevante.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_110"] = "Estas pistas no tienen relación.",
  ["Act_E4_3C_ChloeRoom_ObjectiveWrong_Scripted_Max_120"] = "Parece que esta combinación no es correcta.",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Chloe_030"] = "A la orden, capitán.",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Chloe_040"] = "Vamos por ti, Rachel.",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Max_010"] = "Por fin tenemos algo...",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankAlive_Max_020"] = "Chloe, investiga estos números y veamos si son de una dirección real...",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Chloe_050"] = "Sí... tienes razón. Debemos enfocarnos en Rachel. Todo es por Rachel ahora. Claro.",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Chloe_070"] = "Y con respecto a Frank, a él también lo arrastraron a esta mierda.",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_020"] = "Chloe... Chloe, por favor, escúchame... Sé que es horrible, pero estoy contigo, ¿está bien? Jamás te dejaría sola. No llores, por favor...",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_060"] = "Lo haremos. Sé que esta semana ha sido extraña y un asco, pero Chloe... este debe ser nuestro destino. O al menos uno de ellos. Averigüemos dónde termina todo esto, ¿de acuerdo? Por Rachel... por Kate.",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_080"] = "Bien hecho Chloe. Convirtámonos en un equipo de investigación austero, pero cruel. Ve a la computadora y ayúdame a descifrar estas coordenadas... tal vez al fin nos lleven a Rachel.",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDeadAlternate_Max_090"] = "¡Gracias, Chloe!",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDead_Max_010"] = "Por fin tenemos algo.|Chloe, necesito que te conectes y me ayudes a descifrar esto.|¿Chloe?",
  ["Cue_E4_3C_ChloeRoom_AskChloeHelp_FrankDead_Max_030"] = "Chloe, fue en defensa propia. Sé que te sientes mal, pero intenta bloquear todo y seguir adelante. Rachel nos espera.",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_010"] = "Max, maté a alguien...",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_020"] = "¿Qué será de mí ahora?",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_030"] = "No puedo creer que ocurra esto... No puedo...",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_040"] = "Frank intentó matarte... ¿qué más podía hacer?",
  ["Cue_E4_3C_ChloeRoom_ChloeBed_IGE_Chloe_050"] = "Vamos, vamos, ayúdanos a encontrar a Rachel...",
  ["Cue_E4_3C_ChloeRoom_ChloeComputerBed_IGE_Chloe_010"] = "Max, sé que podemos conectar todas estas piezas...",
  ["Cue_E4_3C_ChloeRoom_ChloeComputerBed_IGE_Chloe_020"] = "Me alegra tanto que estés conmigo en esto.",
  ["Cue_E4_3C_ChloeRoom_ChloeComputerBed_IGE_Chloe_030"] = "Veo que sí sabes usar ese tablero.",
  ["Cue_E4_3C_ChloeRoom_ChloeQuickphase01_IGE_Chloe_010"] = "Oye, Max, conectar estas piezas es más difícil que armar un cubo Rubik... Dime si necesitas algo más, yo me conecto para verificar que no olvidemos nada.",
  ["Cue_E4_3C_ChloeRoom_ChloeRecover_Chloe_040"] = "Vamos por ti, Rachel.",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_060"] = "Alguien de nombre \"Harry Aaron Prescott.\"",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_080"] = "No es buena idea. Sabes que la policía es la seguridad privada de Nathan, ¿cierto?",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_100"] = "Como pudiste ver, esta ciudad es un desastre. No podemos confiar en nadie... Excepto nosotras. Debemos ir solas a esa granja.",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_130"] = "Solo tú y yo. Nadie más. Y no tengo miedo porque tú eres la de los poderes. Siento que estamos muy cerca de Rachel... Debemos encontrarla, Max.",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Chloe_150"] = "Sí, capitán.",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_070"] = "Qué sorpresa.",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_071"] = "¿Llamamos a la policía?",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_090"] = "Eso está muy enredado...",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_110"] = "Temía que dijeras eso. Podríamos llamar a Warren, ya viste que le partió la cara a Nathan...",
  ["Cue_E4_3C_ChloeRoom_DiscoverOldFarm_Max_140"] = "Lo haremos. Pero te recuerdo que mi poder no es infinito y debemos tener cuidado... ¿me escuchaste, Chloe?",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Chloe_020"] = "Déjame buscar más pistas aquí.",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Chloe_030"] = "No... nada, Max. No hay nada. Solo un puto granero en ruinas...",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Chloe_050"] = "Déjamelo a mí. Espera.",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Max_010"] = "Chloe, definitivamente este es el lugar.",
  ["Cue_E4_3C_ChloeRoom_ExtractionBis_Max_040"] = "Sigamos buscando, tal vez sepamos a quién pertenece el granero embrujado.",
  ["Cue_E4_3C_ChloeRoom_FrankDeadBis_Chloe_010"] = "Max... iré con la policía después de encontrar a Rachel.|No puedo vivir con algo así... y no quiero ser una adolescente fugitiva.|Juro que no diré tu nombre, ¿está bien? Yo soy la responsable de todo esto.",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_020"] = "Me alegra que las cosas salieran bien con Frank. Es bueno tener un enemigo menos en Arcadia Bay.",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_040"] = "Lo siento, sigo pensando en que le disparé a Frank en la pierna.",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_045"] = "Lo siento, aún pienso en Frank...",
  ["Cue_E4_3C_ChloeRoom_Insertion_Chloe_060"] = "Lo siento, yo... sigo viendo a Frank... muerto. Y yo lo maté.",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_010"] = "Chloe, ¿estás bien?",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_030"] = "Amén.",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_050"] = "No te culpes. Tú nos salvaste. Frank tiene suerte. Debemos seguir avanzando.",
  ["Cue_E4_3C_ChloeRoom_Insertion_Max_070"] = "Escucha, salvaste mi vida. Y la tuya. Debemos seguir avanzando.",
  ["Cue_E4_3C_ChloeRoom_MaxAnswers_IGE_Max_010"] = "Escúchame, Chloe. Me haré cargo de todo, ¿de acuerdo? Estudiaré el tablero e intentaré conectar los puntos...",
  ["Cue_E4_3C_ChloeRoom_MaxAnswers_IGE_Max_015"] = "Entendido, estudiaré el tablero e intentaré conectar todos los puntos...",
  ["Act_E4_3E_Hospital_Balloons_Look01_Max_010"] = "No creo que \"Mejórate pronto\" sea apropiado.",
  ["Act_E4_3E_Hospital_Book_Look01_Max_010"] = "Qué alivio es ver que Kate sigue trabajando en su reporte de lectura.",
  ["Act_E4_3E_Hospital_CHKate_Look01_Max_010"] = "Después de todo lo que le ha pasado, duerme como un ángel.",
  ["Act_E4_3E_Hospital_CHKate_Look02_Max_020"] = "Es un alivio saber que Kate volvió a dibujar.",
  ["Act_E4_3E_Hospital_CatholicStuff_Look01_Max_010"] = "Si esto ayuda a Kate por la noche, amén.",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_010"] = "Es increíble sentarse aquí tranquilamente con Kate otra vez...",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_020"] = "Si no pudiera congelar el tiempo, ¿realmente habría saltado?",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_030"] = "Creo que nunca sabré cuánto estoy cambiando el destino...",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_040"] = "¿Pero quién dijo que solo tenemos un destino?",
  ["Act_E4_3E_Hospital_Chair_ZEN_Max_050"] = "Viajar en el tiempo te jode el cerebro...",
  ["Act_E4_3E_Hospital_Curtains_Look01_Max_010"] = "La luz es perfecta, así que tal vez deje las cortinas abiertas.",
  ["Act_E4_3E_Hospital_FamilyPortrait_Look01_Max_010"] = "Gracias, hermanas. Realmente salvaron a Kate.",
  ["Act_E4_3E_Hospital_Flowers_Look01_Max_010"] = "Qué flores tan lindas... ¿son de Taylor? Se ganó mi respeto.",
  ["Act_E4_3E_Hospital_GetWellSoon_Look01_Max_010"] = "Qué lindos... incluso Victoria la firmó. Nathan fue la única excepción...",
  ["Act_E4_3E_Hospital_KateDrawings_Look01_Max_010"] = "¡Qué lindo! Me encantan los dibujos alegres de Kate.",
  ["Act_E4_3E_Hospital_MedicalBed_Look01_Max_010"] = "Esto me recuerda a la cama de Chloe... excepto que no tuve que poner a dormir a Kate.",
  ["Act_E4_3E_Hospital_MedicalBed_Look01_Max_020"] = "Esto me recuerda a la cama de Chloe... ni loca la pondría a dormir para siempre.",
  ["Act_E4_3E_Hospital_Scripted_Max_010"] = "Me alegro de verte, Kate Marsh...",
  ["Act_E4_3E_Hospital_Scripted_Max_020"] = "Lo siento, pero odio los hospitales... son muy fríos...",
  ["Act_E4_3E_Hospital_Scripted_Max_030"] = "Me pregunto cómo se siente la familia de Kate con todo esto...",
  ["Act_E4_3E_Hospital_Scripted_Max_040"] = "Tal vez Kate tiene más información que podamos usar sobre Nathan...",
  ["Act_E4_3E_Hospital_VictoriaPostcard_Look01_Max_010"] = "Victoria Chase puede ser la Abeja reina de las perras, pero no es una mala persona.",
  ["Act_E4_3E_Hospital_WellsLetter_Look01_Max_010"] = "El director Wells sabe cómo intervenir cuando quiere hacerlo...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_001"] = "Max, te debo tanto... Siento que quieres decirme algo.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_003"] = "Eso me hace feliz.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_005"] = "Lo sé. Por eso te quiero, Max. Y gracias por cuidar a mi conejito. Dile a Alice que la veré pronto.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_007"] = "Nathan Prescott debe pagar por lo que hizo. Y debemos detenerlo antes de que lastime a alguien más.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_009"] = "¿En serio? ¡Bien hecho, Max! Me encanta que seas tan valiente.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_012"] = "Yo también. Pero su papá nunca habría permitido que eso pasara... y yo creí que mi familia era difícil...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_013"] = "¿Y qué es de su vida ahora?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_017"] = "Y después de lo que hizo, nadie puede tocarlo.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_020"] = "¡Déjame ayudar, Max! Puedo conseguir el número y te enviaré un mensaje, ¿está bien?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_021"] = "Nunca digo esto de las personas... pero Max, hay algo siniestro sobre los Prescott. Están relacionados con la muerte.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_023"] = "Es momento de que Nathan se cuide de nosotras...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_024"] = "¡Oh, sí! Y podrías traer a Warren también...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_028"] = "Nos perdimos la sesión de té de esta semana.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_029"] = "Qué graciosa eres, Max. Y tienes toda la razón.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_030"] = "Ay, inteligente y bobo... tiene buen corazón. Además es muy lindo. ¿Sabes que le gustas?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_034"] = "No, te lo mereces.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_035"] = "¿De verdad? Qué mal, serían una linda pareja...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_036"] = "Incluso los ángeles necesitan ángeles, Max.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_039"] = "Max, sé que Victoria puede ser una... ya sabes... no muy agradable. Pero creo en el perdón y la redención. Quizá sea ingenua, pero entiendo su pesar.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_042"] = "Todos tenemos nuestros momentos. ¿Por qué crees que actúa de forma tan malvada?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_045"] = "Debe haber una razón. Si Victoria pudo escribirme una carta tan sincera...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_046"] = "Victoria no parece que tenga muchas razones para ser insegura...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Kate_048"] = "No, creo que se necesita mucho más, Max.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_002"] = "Kate, me alegra poder estar contigo otra vez.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_004"] = "Aquí estoy de nuevo, Kate.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_006"] = "Debo regresar a... nuestra misión. No sabes lo mucho que significa poder verte otra vez.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_008"] = "Estoy a punto de obtener la información que necesito sobre Nathan...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_010"] = "Ojalá hubiera conseguido que botaran su trasero de Blackwell.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_011"] = "Al menos conseguí que lo suspendieran, por algo se empieza...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_015"] = "Supongo que aparecerá en la fiesta esta noche, como si nada hubiera pasado.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_016"] = "Creo que su familia lo tiene muy bien protegido... o peor.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_018"] = "Siempre quiero platicar contigo...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_019"] = "Vamos a detenerlo. Solo debo conseguir el número del cuarto de Nathan, entrar y conseguir pistas.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_022"] = "No se permiten chicos.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_025"] = "¡Claro, Kate! ¡No puedo hacer esto sin ti!",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_026"] = "Eso no estuvo bien. Necesitamos un plan, como, un tour en Portland para visitar tiendas de té.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_031"] = "¿Qué piensas de Warren?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_032"] = "Iré al autocinema con él, ya veremos. Con todo lo que está ocurriendo, una cita parece algo extraño...",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_033"] = "Eso he escuchado. Me invitó al autocinema, pero lo rechacé.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_037"] = "Kate Marsh, la casamentera. Me alegra que alguien esté cuidando de mi vida amorosa.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_038"] = "Vi la carta de Victoria... ¿cómo te hace sentir eso?",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_040"] = "No fui amable con ella esta semana, y le tomé una foto cubierta en pintura. No me siento orgullosa de eso.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_041"] = "Yo también. En vez de tomar una foto de ella cubierta en pintura, no lo hice y compartimos un momento sincero.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_043"] = "Es una perra. Lo siento... Tiene dinero, belleza y talento, pero eso no le da derecho a tratar a los demás como basura.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_044"] = "Es insegura. Si te sientes cómoda contigo misma, no actúas como si fueras superior a los demás.",
  ["Cue_E4_3E_Hospital_CHKate_Phase01_Max_047"] = "Si alguien puede hacer que Victoria vea la luz, es Kate Marsh.",
  ["Cue_E4_3E_KateRoom_Extraction_Chloe_010"] = "¿Y... cómo está?",
  ["Cue_E4_3E_KateRoom_Extraction_Chloe_030"] = "Me alegra que hayamos venido a verla.",
  ["Cue_E4_3E_KateRoom_Extraction_Chloe_050"] = "Ahora visitemos a Nathan Prescott. A ese maldito cabrón le agradará vernos...",
  ["Cue_E4_3E_KateRoom_Extraction_Max_020"] = "Sigue siendo Kate Marsh.|Gracias a Dios.",
  ["Cue_E4_3E_KateRoom_Extraction_Max_040"] = "Gracias por acompañarme.",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_010"] = "Detesto los hospitales...",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_030"] = "No, le encantará verte. ¿A quién no?",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_050"] = "Solo entra y sé su amiga. Yo esperaré aquí para que puedan relajarse juntas.",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_060"] = "Fui una idiota por ponerme tan loca cuando contestaste la llamada de Kate|el otro día. Me alegra que me ignoraras.|No tenía idea de la mierda que ocurría en su vida. Y tú la salvaste...|como a mí. Lo siento.",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_070"] = "Fui una... gran idiota por ponerme tan loca cuando Kate te llamó el otro día.|No tenía idea de la mierda que ocurría en su vida.|No dejé que te acercaras a ella. Pero tú la salvaste...|como a mí. Lo siento.",
  ["Cue_E4_3E_KateRoom_Insertion_Chloe_090"] = "Embarcación Max. Dile a Kate que colgaremos a Nathan de las bolas.",
  ["Cue_E4_3E_KateRoom_Insertion_Max_005"] = "Definitivamente este es el piso donde está Kate.",
  ["Cue_E4_3E_KateRoom_Insertion_Max_020"] = "Entiendo. Pero imagina cómo se siente Kate... me alegra verla de nuevo. Espero que no sea muy extraño para ella.",
  ["Cue_E4_3E_KateRoom_Insertion_Max_040"] = "Aquí es. Estoy un poco nerviosa...",
  ["Cue_E4_3E_KateRoom_Insertion_Max_080"] = "Gracias, Chloe, pero no te preocupes. Estamos en el mismo barco.",
  ["Cue_E4_3E_KateRoom_Insertion_Max_100"] = "Oh, sí, sin duda.",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_010"] = "Espero que no sea muy aburrido para ti todo esto...",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_020"] = "Es agradable tan solo tenerte cerca.",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_030"] = "Gracias por visitarme, Max.",
  ["Cue_E4_3E_KateRoom_KateHospital_IGE_Kate_040"] = "Max, incluso mi madre me escribió una carta realmente hermosa...",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_010"] = "¡Max!",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_030"] = "Creí que nunca te volvería a ver. Me siento tan ridícula... Lo siento.",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_050"] = "Estoy mejor ahora que estás aquí. Te agradezco tanto por haber subido al techo a disuadirme... Max, me sentía tan perdida y sola... pero cuando vi lo mucho que te preocupabas, todo tu esfuerzo... me di cuenta de que no estaba sola. Gracias.",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_070"] = "Sé que deberías ver todas las cartas y postales. Regalé la mayor parte de las flores a otros pacientes porque las necesitan más que yo. Aunque conservé los globos. Una de las enfermeras me dio pluma y papel para hacer algunos dibujos.",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_090"] = "Se volvieron un poco oscuros por un momento, pero tengo una idea para un libro para niños acerca del bullying... estaba pensando en agregar unas fotografías ahí también.",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_110"] = "¿Sutil? Más te vale hacerlo, Max. Estaré aquí otro día hasta que mi familia venga a visitarme.",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_130"] = "Como si necesitaran protegerme toda la vida. Están muy tristes, y sé que se sienten culpables, aunque no hayan hecho nada. Me sorprendió ver cuántos alumnos de Blackwell me escribieron. Daniel, el Sr. Jefferson... incluso Victoria me escribió una nota muy linda... y creo que era honesta.",
  ["Cue_E4_3E_KateRoom_MeetKate_Kate_150"] = "Trabajo en ello, Max. Solo rezo por que este dibujo me salga bien...",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_020"] = "¡Oh, Kate!",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_040"] = "Kate, escúchame... no tienes nada de qué disculparte... a diferencia de otros. No sabes lo feliz que estoy de verte. Te ves muy bien. ¿Es muy tonto si te pregunto cómo estás?",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_060"] = "Kate, hay tantas personas que te aman y quieren ayudarte.",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_080"] = "Me encantan tus ilustraciones.",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_100"] = "Espero que haya sido una sutil indirecta para que yo participe...",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_120"] = "¿Cómo te tratan?",
  ["Cue_E4_3E_KateRoom_MeetKate_Max_140"] = "Yo también. Qué bueno que recobres la esperanza, Kate.",
  ["Act_E4_4A_Beach_Boardwalk_Look01_Max_010"] = "Es increíble que estuve exactamente aquí con Chloe, en una realidad alternativa...",
  ["Act_E4_4A_Beach_CHChloe_Look01_Max_010"] = "Chloe parece estar lista para la acción.",
  ["Act_E4_4A_Beach_DeflatedBeachBall_Look01_Max_010"] = "Oh... Pobre pelota de playa.",
  ["Act_E4_4A_Beach_DogPlate_Look01_Max_010"] = "¡Ooh, carne fresca! Así que Pompidou debe estar bien. Buen perro...",
  ["Act_E4_4A_Beach_EmptyBottles_Look01_Max_010"] = "He ahí el jardín cervecero de Frank.",
  ["Act_E4_4A_Beach_FranksCorpse_Look01_Max_010"] = "No puedo creer que Frank esté... muerto... en el piso.",
  ["Act_E4_4A_Beach_Garbage_Look01_Max_010"] = "No te haría daño sacar la basura de vez en cuando...",
  ["Act_E4_4A_Beach_NoCampingSign_Look01_Max_010"] = "No te preocupes, acepta.",
  ["Act_E4_4A_Beach_NoSwimmingSign_Look01_Max_010"] = "Al menos no hay policías alrededor...",
  ["Act_E4_4A_Beach_PanEstatesFlyer_Look01_Max_010"] = "Tal vez Pan Estates no exista para el sábado...",
  ["Act_E4_4A_Beach_Path_Look01_Max_010"] = "Aquí comenzó mi pesadilla...",
  ["Act_E4_4A_Beach_Pompidou_Look01_Max_010"] = "Oh, no... Pompidou... Lo siento...",
  ["Act_E4_4A_Beach_RVWindow01_Look01_Max_010"] = "No creo que Frank haya escuchado mi dispositivo de limpieza. De todas formas no es gracioso.",
  ["Act_E4_4A_Beach_RVWindow01_Look02_Max_010"] = "Frank no necesita ventanas polarizadas con tanta suciedad encima...",
  ["Act_E4_4A_Beach_RVWindow02_Look01_Max_010"] = "No puedo ver qué hay adentro con toda esta basura bloqueando la vista.",
  ["Act_E4_4A_Beach_ScriptedFrankDead_Max_010"] = "Dios, Chloe mató a Frank... nunca se perdonará... ni olvidará esto... y solo yo puedo cambiarlo...",
  ["Act_E4_4A_Beach_ScriptedFrankHurt_Max_010"] = "Mierda. Y pudo ser peor... Aunque tal vez Frank sea más peligroso para Chloe ahora... Sí, Max, tú puedes cambiar todo esto si quieres...",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_010"] = "Así que ahora debemos ver a Frank acá...",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_030"] = "Debería salir de la ciudad, pero no sin Chloe... Debemos terminar lo que empezamos.",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_070"] = "Respira y ve a ver a Frank. Tienes el poder...",
  ["Act_E4_4A_Beach_ScriptedParkingLot_Max_100"] = "Frank estuvo genial al darnos los códigos... Rachel debió ver algo bueno en él.",
  ["Act_E4_4A_Beach_TableAndChair_Look01_Max_010"] = "Aquí es donde Frank piensa sobre su vida... y se embriaga.",
  ["Act_E4_4A_Beach_Whales_Look01_Max_010"] = "Las ballenas encalladas se ven tan mal... y a la vez tan majestuosas.",
  ["Act_E4_4A_Beach_Whales_Look02_Max_010"] = "Tal vez no sea muy inteligente, pero debe haber una explicación...",
  ["Act_E4_4A_Beach_Whales_Look03_Max_010"] = "¿Cómo no puede estar todo esto relacionado con una gran tormenta?",
  ["Act_E4_4A_Beach_WildLifeSign_Look01_Max_010"] = "El bosque parece muerto, no hay señales de vida... o venados.",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_005"] = "Sabía que serías un amor y rebobinarías... Dime exactamente lo que debo hacer.",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_006"] = "No creo que sea buena idea, Max... pero confío en ti. Si llego a necesitar esa arma, más te vale rebobinar rápido...",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_007"] = "Esto te empieza gustar, ¿verdad? Entiendo, para variar seré como tú. O como solías ser...",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Chloe_008"] = "Sabes que no soy un total desastre. A veces puedo ser cuidadosa y tranquila... como ahora, ¿de acuerdo?",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_001"] = "Escucha, Chloe, sé de buena fuente que esto no irá bien.",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_002"] = "No te gustará esto, pero debes deshacerte de esa arma.",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_003"] = "Cuida lo que dices. No tienes habilidades sociales y harás enojar a Frank rápidamente.",
  ["Cue_E4_4A_Beach_CHChloe_AlternateBegin_Max_004"] = "Ten cuidado, ¿de acuerdo? No le des excusas a Frank para que saque su arma. Necesitamos su ayuda, Chloe.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_001"] = "Okey, estamos bien por ahora... pero mi perro no. Se salió de la casa rodante y un imbécil lo atropelló. Le di una paliza al infeliz.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_002"] = "No, solo hice lo correcto. No soporté ver a esos pobres animales tratados como esclavos. Así fue como adopté a Pompidou.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_003"] = "Sí, antes tenía un mal entrenador. En verdad era malo. Pero ya murió. Y yo entrené a Pompidou para ser mi amigo.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_004"] = "Okey, estamos bien por ahora... pero mi perro no. Y si intentan cualquier estupidez, les hará pedazos el cráneo. Ya lo ha hecho antes.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_007"] = "El cabroncito tiene suerte de estar con vida. Aunque a ustedes no les importe.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_008"] = "Diablos, no tendrías el tiempo... ¿Te gustan los perros?",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_015"] = "¡Así que ustedes lo dejaron salir! ¡Entran sin permiso y dejan salir a mi perro! ¿Qué carajo pasa con ustedes?",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_016"] = "Solo podrían saber el nombre de mi perro si entraron a mi casa rodante... ¡Por eso se escapó! ¡Fue su culpa! ¿Están locas? ¡Es mi perro!",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Frank_017"] = "¿Crees que abuso de mi propio perro? ¡Yo salvé a Pompidou, idiota!",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_005"] = "Por Dios, Frank... Eso es terrible. ¿Cómo está?",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_006"] = "Solo estamos aquí para hablar. No quiero meterme con tu perro.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_009"] = "Qué bien, Frank. Tu perro tiene suerte de que estés en su vida.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_010"] = "¡Claro que sí! Escuché que incluso rescataste a un grupo de perros de pelea. ¡Increíble!",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_011"] = "Amo a los perros. Es todo. Ojalá tuviera uno tan bien entrenado como el tuyo.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_012"] = "Chloe y yo le dimos un hueso a tu perro cuando...",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_013"] = "¡Aaah, Pompidou es muy lindo!",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_014"] = "No me interesan los perros entrenados para matar o pelear... eso es abuso animal.",
  ["Cue_E4_4A_Beach_CHFrank_Dog_Max_018"] = "¡Espera! Eso no es lo que...",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_001"] = "Sí, claro, cómo no. Ustedes dos son un dolor de cabeza. No hay trato.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_002"] = "Sí, claro... Si no recuerdo mal, me apuntaste con una puta arma.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_003"] = "¿Tú... vienes en paz? ¿Después de que me apuntaste con un arma y jalaste del gatillo?",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_004"] = "Al fin les creo... pero no vuelvas a jalar el gatillo cuando le apuntas a alguien, a menos que intentes matarlo. Aunque parece que no matas ni a una mosca...",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_005"] = "Lo deduje por cómo sostenías esa pistolita de juguete...|Con ambas manos, como si fuera una Magnum.|Tal vez debí llevar algo más que una navaja.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_008"] = "Al fin te creo... pero no vuelvas a apuntarle a alguien a menos que trates de matarlo. Aunque parece que no matas ni a una mosca...",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_015"] = "Tienes suerte de que solo tenía una navaja, o tu novia y tú ya no me estarían molestando. ¿Te crees muy ruda, no?",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_016"] = "¿\"Escondite\"? ¿Qué son, Los Goonies? Aún puedo arruinarlas por lo que hicieron. Aléjense de mí, ¿entienden?",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Frank_017"] = "Estás loca, niñita... ¿Jalaste el gatillo para mostrarme que venías en paz?",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_006"] = "Frank, no vinimos a pelear. Esto es mucho más importante que nosotras.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_007"] = "Lamento eso... Debe ser la cosa más tonta que haya hecho. Y esta semana ya hice varias.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_009"] = "Eso Intento. Y nunca habría jalado el gatillo. Yo solo...",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_010"] = "Lamento eso... Debe ser la cosa más tonta que haya hecho. Y esta semana ya hice varias.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_011"] = "La verdad, Frank... me asustaste. Tenías una navaja contra mi amiga. No quería jalar del gatillo.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_012"] = "Estaba ayudando a Chloe después de que intentaste lastimarla, ¿recuerdas?",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_013"] = "Ese era nuestro escondite. No debiste fastidiarnos ahí.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_014"] = "No había balas en esa arma. Estabas a salvo, muchachote.",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_018"] = "Lo único que disparo es mi cámara, lo juro. Pregúntale a Chloe...",
  ["Cue_E4_4A_Beach_CHFrank_Gun_Max_019"] = "Yo solo... no sabía lo que hacía.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_001"] = "No, no pareces del tipo. No como Chloe. ¿Y qué buscan Sherlock y Watson por aquí?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_002"] = "No sé de qué hablan, pero las escucho. Será mejor que no se metan conmigo.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_003"] = "Sí, sí... Todo es importante. Pero, bueno, veo que no se están burlando de mí.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_006"] = "¿Ah, eso es todo? ¿Por qué no lo dijeron antes? ¿Les doy las llaves de mi casa rodante también?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_007"] = "¿Uh? ¿Estás loca? Perdí mis llaves pero cambié la cerradura. Será mejor que no anden husmeando por aquí.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_008"] = "¿En verdad te atreves a amenazarme otra vez, mocosa?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_009"] = "No, \"viejo\", no entiendo... especialmente lo que dice una rara como tú.|¿Sabes? Odio la forma en que me hablas, como si... como si supieras más que yo.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_017"] = "Sí, claro... Siempre se empieza con un poco. Chloe sabe muy bien de eso, ¿no es cierto?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_018"] = "Dios, odio a los idiotas de Blackwell. Esperan recibir todo gratis. No obtendrán nada de mí. Trabajo para mantenerme, ¿entienden?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_022"] = "Me apuntas con un arma pero te asusta mi perro. Claro...",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_023"] = "No, esa mierda terminaría muy pronto. No se metan conmigo y no les devolveré el favor. ¿Qué quieren?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_024"] = "¿Después de que me apuntaste con tu maldita arma quieres negociar mi seguridad? Si no confiaba en ti antes, ahora menos.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_025"] = "Por cierto, nunca me digas qué hacer en mi casa. Tal vez no sea tan sofisticada como las demás en Arcadia Bay, pero es mi techo, ¿entiendes? Tienes la maldita suerte de haberme pagado. ¿Qué quieren?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_026"] = "Ya, estás a salvo. ¿Qué quieren?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Frank_027"] = "Dios, odio a estos idiotas de Blackwell. Actúan como si fueran dueños de la ciudad... como si yo fuera su títere. No le pertenezco a nadie, ¿entienden?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_004"] = "Frank, no estamos aquí por droga.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_005"] = "Solo los nombres de algunos de tus clientes...",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_010"] = "No estaríamos aquí frente a ti si no fuera importante. Es decir, ¿qué truco podría esconderte? No queremos que nos ayudes... queremos ayudarte.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_011"] = "Escucha, Frank, lamento ser una molestia, pero esto es importante.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_012"] = "Ya lo hiciste.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_013"] = "Ayúdanos... o ya verás.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_014"] = "No lo entiendes, viejo. Esto es por una buena causa.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_015"] = "No hay tiempo para eso, Frank. Solo necesito un poco de información.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_016"] = "No, yo no, yo...",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_019"] = "Frank, eh... tu perro me asusta un poco, ¿podrías cerrar la puerta?",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_020"] = "Gracias por escucharme, Frank. Solo queremos hablar, y no de ti... No vinimos a pelear.",
  ["Cue_E4_4A_Beach_CHFrank_Negotiation_Max_021"] = "Frank, um... No quiero que involucremos armas esta vez. ¿Podrías guardar en la casa rodante la navaja o... lo que sea que tengas mientras estemos aquí?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_001"] = "¿Rachel? ¿Por eso están aquí?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_002"] = "¿Cómo diablos sabías de la foto? Es mi favorita de ella... Puedo verla en cualquier momento y siempre conmigo.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_004"] = "Cuando Rachel desapareció, prácticamente lo perdí todo...",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_006"] = "Chloe y tú no conocen a Rachel como yo, mucho menos podrán ayudarle. Se creen mucho. ¿Por qué no van a jugar en su casita del árbol?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_013"] = "No me levanten falsos. No me conocen ni saben quién soy. O de lo que soy capaz. ¿Entienden? ¿Eh?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_014"] = "¿Leíste esa carta? ¿La que estaba en mi RV? ¡¿Estás loca?! ¡¿Leíste mi correspondencia privada?!",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_015"] = "Nunca llegues a mi casa a decirme lo que tengo que hacer, ¿entiendes?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_017"] = "No tolero no saber dónde está... sin escuchar su voz... o su risa... nunca más.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Frank_018"] = "Viejo, hay algo muy mal contigo... no confío en ti para nada. Ahora aléjate de mí.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_005"] = "Sí, Frank, estamos muy cerca de encontrarla. Necesitamos toda la ayuda que podamos conseguir... Especialmente la tuya.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_007"] = "Podemos cambiar todo eso... Depende de ti.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_008"] = "Rachel dijo que te dio una de sus fotos favoritas. Eso prueba lo mucho que se preocupa por ti... y tú por ella. Por eso debes ayudarnos.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_009"] = "Frank, tú conocías a Rachel mejor que casi todos. Y sabes más que nosotras. Juntos podemos encontrarla... ¿Tienes algo que perder?",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_010"] = "Frank, ¿qué ocultas? Deberías ayudarnos, no corrernos.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_011"] = "Verás, leí la carta de Rachel... sé cuánto se preocupa por ti.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_012"] = "Tienes el brazalete de Rachel. Obviamente sabes más de lo que nos dices. Habla.",
  ["Cue_E4_4A_Beach_CHFrank_Rachel_Max_019"] = "No tenemos mucho tiempo, Frank. Rachel te necesita.",
  ["Cue_E4_4A_Beach_DogDial_ChloeBadChoice_Chloe_010"] = "No seas psicótico, Frank, en serio. Vinimos para encontrar a Rachel.",
  ["Cue_E4_4A_Beach_DogDial_ChloeBadChoice_Frank_010"] = "¡Rachel no está aquí! ¡Haré lo que me dé la gana y les daré una paliza! ¿Y qué carajo planean ustedes dos, par de idiotas? ¡Esta vez me hicieron enfurecer, perra!",
  ["Cue_E4_4A_Beach_DogDial_ChloeGoodChoice_Chloe_010"] = "¿Podemos enfocarnos en rescatar a Rachel?",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_020"] = "Maté a Frank Bowers...",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_040"] = "Max... Frank realmente esta muerto.",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_060"] = "Antes de que venga la... la policía...",
  ["Cue_E4_4A_Beach_FrankDead_Chloe_080"] = "Lo siento mucho, Frank... perdón...",
  ["Cue_E4_4A_Beach_FrankDead_Max_010"] = "Dios...",
  ["Cue_E4_4A_Beach_FrankDead_Max_030"] = "Me salvaste, Chloe. Fue en defensa propia de las dos.",
  ["Cue_E4_4A_Beach_FrankDead_Max_050"] = "Lo sé. Pero no podemos detenernos ahora. Debemos encontrar ese código, ya.",
  ["Cue_E4_4A_Beach_FrankDead_Max_070"] = "Eso es. Vámonos de aquí.",
  ["Cue_E4_4A_Beach_FrankHurt_Chloe_020"] = "Lo sé...",
  ["Cue_E4_4A_Beach_FrankHurt_Chloe_050"] = "Ahora.",
  ["Cue_E4_4A_Beach_FrankHurt_Chloe_110"] = "Larguémonos de aquí.",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_030"] = "¡Ustedes dos están locas! ¿Qué quieren?",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_060"] = "¡Bien, basta, solo baja el arma! Ya me disparaste, ¿no?",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_070"] = "Ahí tienen. Ahora déjenme en paz, ¿quieren? Desaparezcan de mi vida.",
  ["Cue_E4_4A_Beach_FrankHurt_Frank_090"] = "No, gracias... ¿Sabes qué? me las arreglaré sin la policía de alguna forma.",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_010"] = "Ay, diablos, necesito un trago... y algo de hierba.",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_020"] = "Dios, no puedo creer que unas adolescentes me dispararon.",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_030"] = "Necesito a mi Pompidou…",
  ["Cue_E4_4A_Beach_FrankHurt_IGE_Frank_040"] = "Okey, muy bien, saquemos a este bebé de mi pierna... con cuidado, Frank.",
  ["Cue_E4_4A_Beach_FrankHurt_Knife_Max_010"] = "Chloe, lo acuchillaste...",
  ["Cue_E4_4A_Beach_FrankHurt_Max_010"] = "Chloe, le disparaste...",
  ["Cue_E4_4A_Beach_FrankHurt_Max_040"] = "Solo... solo queremos el código de tu libreta de cuentas.",
  ["Cue_E4_4A_Beach_FrankHurt_Max_080"] = "¿Llamamos a una ambulancia? O...",
  ["Cue_E4_4A_Beach_FrankHurt_Max_100"] = "Ah, claro.",
  ["Cue_E4_4A_Beach_GunDial_ChloeBadChoice_Chloe_010"] = "¡Déjala en paz! ¡Solo me protegía! ¡Tienes un cuchillo y quién sabe qué más! ¿Y tú le temes a Max?",
  ["Cue_E4_4A_Beach_GunDial_ChloeBadChoice_Chloe_020"] = "Vamos, Frank... ¿todo bien?",
  ["Cue_E4_4A_Beach_GunDial_ChloeGoodChoice_Chloe_010"] = "¡Entiende, Frank! Max no necesita un arma de todas formas... ¿todos calmados? ¿Por favor?",
  ["Cue_E4_4A_Beach_GunDial_ChloeNoChoice_Chloe_010"] = "Viejo, estaba asustada, ¿okey?|Me amenazaste con la navaja. Todos estábamos confundidos.|¿Ahora podemos calmarnos... por favor?",
  ["Cue_E4_4A_Beach_GunDial_FrankBadChoice_Frank_010"] = "¡Solo le temo a mi Creador! ¿Y ustedes par de putas se creen mejores que yo? ¿Por qué? ¿Porque soy un Don Nadie? ¡Ustedes son basura de Blackwell! Y es momento de ponerlas en su lugar...",
  ["Cue_E4_4A_Beach_Insertion_Chloe_020"] = "Yo también. Solo pienso en sus familias en el océano que las buscan.",
  ["Cue_E4_4A_Beach_Insertion_Chloe_030"] = "Bueno, ese imbécil nos ayudará a encontrar a Rachel.",
  ["Cue_E4_4A_Beach_Insertion_Chloe_050"] = "Obviamente no cuento contigo. Por eso tengo un arma. Y tal vez te salve algún día.",
  ["Cue_E4_4A_Beach_Insertion_Chloe_070"] = "Te daré tu merecido.",
  ["Cue_E4_4A_Beach_Insertion_Chloe_080"] = "¿Sabes qué estaría increíble? Todavía tener el arma.",
  ["Cue_E4_4A_Beach_Insertion_Chloe_100"] = "Frank se asustaría. Es un marica. Además, si acabo con él, puedes rebobinar...",
  ["Cue_E4_4A_Beach_Insertion_Chloe_120"] = "No hay forma de que supiéramos que esto es lo que nos pasaría al crecer.",
  ["Cue_E4_4A_Beach_Insertion_Chloe_140"] = "Sin duda. Tú, yo... y Rachel.",
  ["Cue_E4_4A_Beach_Insertion_Chloe_160"] = "Entiendo. Debo concentrarme.",
  ["Cue_E4_4A_Beach_Insertion_Max_010"] = "Dios... odio ver esas pobres ballenas así.",
  ["Cue_E4_4A_Beach_Insertion_Max_040"] = "¿O qué? ¿Vas a dispararle? Chloe, no cuentes con que rebobine... lo digo en serio.",
  ["Cue_E4_4A_Beach_Insertion_Max_060"] = "Ya era tiempo.",
  ["Cue_E4_4A_Beach_Insertion_Max_090"] = "Claro, seguro que meternos en un tiroteo nos ayudaría.",
  ["Cue_E4_4A_Beach_Insertion_Max_110"] = "Chloe, no cuentes con que rebobine... Lo digo en serio.",
  ["Cue_E4_4A_Beach_Insertion_Max_115"] = "Después de lo de Kate, siento que cada vez que lo hago es la última...",
  ["Cue_E4_4A_Beach_Insertion_Max_130"] = "Ojalá un día solo salgamos de viaje de paseo a Portland.",
  ["Cue_E4_4A_Beach_Insertion_Max_150"] = "Absolutamente. Así que hagamos esto tranquilas, ¿está bien? Solo dale a Frank su dinero y él nos dará ese código para el libro. Eso es todo.",
  ["Cue_E4_4A_Beach_Insertion_Max_151"] = "Absolutamente. Así que hagamos esto tranquilas, ¿está bien? Solo habla con Frank para que nos dé ese código para el libro. Eso es todo.",
  ["Cue_E4_4A_Beach_Insertion_Max_170"] = "Vamos.",
  ["Cue_E4_4A_Beach_Money_Chloe_020"] = "Frank, ¿podemos hacerte unas cuantas preguntas?",
  ["Cue_E4_4A_Beach_Money_Frank_010"] = "Oh, vaya, gracias. No fue tan difícil, ¿o sí? Ya no hagamos más negocios.",
  ["Cue_E4_4A_Beach_Money_Frank_015"] = "Ahora, si me disculpas...",
  ["Cue_E4_4A_Beach_Money_Frank_030"] = "Sí que tienen pelotas.",
  ["Cue_E4_4A_Beach_Money_Frank_035"] = "No.",
  ["Cue_E4_4A_Beach_Money_Frank_040"] = "Dios, muy bien, calma...",
  ["Cue_E4_4A_Beach_Money_Frank_045"] = "Pero no les daré productos.",
  ["Cue_E4_4A_Beach_NegotiationDial_ChloeBadChoice_Chloe_010"] = "Sí, Frank. Sin esos idiotas de Blackwell como clientes ni siquiera tendrías trabajo. ¡Viejo, eres un narcotraficante!",
  ["Cue_E4_4A_Beach_NegotiationDial_ChloeBadChoice_Frank_010"] = "¡Perras pretenciosas! ¡No vengan a mi casa a juzgarme! ¡Para eso voy a la iglesia! ¿Quieren algo de mí? ¿Qué les parece un navajazo en el culo, eh?",
  ["Cue_E4_4A_Beach_NegotiationDial_ChloeGoodChoice_Chloe_010"] = "Basta, Frank. Esto no se trata de mí.",
  ["Cue_E4_4A_Beach_NoMoney_Chloe_010"] = "No tengo el dinero... aún.",
  ["Cue_E4_4A_Beach_NoMoney_Chloe_030"] = "Quería decírtelo en persona.",
  ["Cue_E4_4A_Beach_NoMoney_Chloe_050"] = "Solo queremos hacerte unas preguntas.",
  ["Cue_E4_4A_Beach_NoMoney_Frank_020"] = "¿Ah, sí? ¿Y por qué me enviaste un mensaje diciendo que sí?",
  ["Cue_E4_4A_Beach_NoMoney_Frank_040"] = "Oh, qué linda, Chloe. En serio, perdedoras, ¿por qué vinieron?",
  ["Cue_E4_4A_Beach_RVDoor_Chloe_020"] = "Es mi socia.",
  ["Cue_E4_4A_Beach_RVDoor_Frank_010"] = "Qué tal... Las Gemelas fantásticas.",
  ["Cue_E4_4A_Beach_RVDoor_Frank_011"] = "Debiste venir sola.",
  ["Cue_E4_4A_Beach_RVDoor_Frank_030"] = "Sí, claro, o guardaespaldas. A lo que nos toca, ¿dónde está mi maldito dinero?",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Chloe_050"] = "¡Hijo de puta!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Frank_010"] = "Nunca me digas lo que tengo que hacer.",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Frank_040"] = "¡Aléjate de mí!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Frank_080"] = "¡Perras!",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Max_020"] = "Whoa...",
  ["Cue_E4_4A_Beach_RageBattle_Dog_Max_070"] = "¡Chloe!",
  ["Cue_E4_4A_Beach_RageDog_Max_010"] = "¡Oh, por Dios!",
  ["Cue_E4_4A_Beach_RageGun_Chloe_040"] = "¡Atrás, imbécil, atrás!",
  ["Cue_E4_4A_Beach_RageGun_Chloe_090"] = "Acabo de disparar a un hombre y a su perro...",
  ["Cue_E4_4A_Beach_RageGun_Frank_020"] = "Nunca me digas lo que tengo que hacer. ¿Entiendes, perra? ¿Entendiste?",
  ["Cue_E4_4A_Beach_RageGun_Frank_050"] = "¡Pompidou!",
  ["Cue_E4_4A_Beach_RageGun_Frank_070"] = "¡Mataste a mi maldito perro!",
  ["Cue_E4_4A_Beach_RageGun_Max_010"] = "Cálmate, Frank. Hablemos…",
  ["Cue_E4_4A_Beach_RageGun_Max_060"] = "Ay, no...",
  ["Cue_E4_4A_Beach_RageGun_Max_080"] = "Chloe...",
  ["Cue_E4_4A_Beach_RageKnife_Frank_010"] = "En... en serio me disparaste. No iba a lastimarte. Auch, carajo, esto duele... ¡duele!",
  ["Cue_E4_4A_Beach_RageNoGun_Frank_010"] = "¿Te gusta mi navaja, pequeña? ¿huh?",
  ["Cue_E4_4A_Beach_RageRachel_Chloe_020"] = "¿Como tú? Yo la amaba, idiota. Y ella a mí, lo sé.",
  ["Cue_E4_4A_Beach_RageRachel_Frank_010"] = "¡Es muy tarde! ¡Se fue! ¡Ni siquiera la conoces!",
  ["Cue_E4_4A_Beach_RageRachel_Frank_030"] = "Chloe, no sabes ni un carajo. Eras parte de su problema. Siempre intentabas alejarla de mí... ¡Siempre!",
  ["Cue_E4_4A_Beach_Success_Chloe_010"] = "Ayúdanos a encontrarla, Frank. En verdad necesitamos tu lista de clientes, por favor...",
  ["Cue_E4_4A_Beach_Success_Chloe_060"] = "Sí, gracias, Frank. En serio.",
  ["Cue_E4_4A_Beach_Success_Frank_020"] = "Si hay una mínima posibilidad de que ustedes, par de idiotas, encuentren a Rachel... la tomaré.",
  ["Cue_E4_4A_Beach_Success_Frank_030"] = "Y avísenme si descubren quién lastimó a mi perro, ¿está bien?",
  ["Cue_E4_4A_Beach_Success_Frank_040"] = "Mi perro no les ladra, así que creo que es una buena señal.",
  ["Cue_E4_4A_Beach_Success_Frank_070"] = "Es difícil tomarlas en serio... pero lo haré. Buena suerte.",
  ["Cue_E4_4A_Beach_Success_Max_050"] = "Gracias.",
  ["Act_E4_5A_Corridor_BigFoot_Interact01_Max_010"] = "Todo fotógrafo debe tener una toma borrosa de Pies Grandes...",
  ["Act_E4_5A_Corridor_BigFoot_Look01_Max_010"] = "¿Por qué no me sorprendería si Pies Grandes apareciera?",
  ["Act_E4_5A_Corridor_BigfootPoster_Look01_Max_010"] = "Oh, Pies Grandes por todos lados.",
  ["Act_E4_5A_Corridor_CHChloe_Look01_Max_010"] = "He ahí \"Chloe ojo de águila\" analizando el área en busca de Nathan...",
  ["Act_E4_5A_Corridor_CatPicturesPoster_Look01_Max_010"] = "¿Quién robaría fotos de gatos?",
  ["Act_E4_5A_Corridor_CondomPoster_Look01_Max_010"] = "Aparentemente Logan no vio este póster.",
  ["Act_E4_5A_Corridor_DanielDrawings_Look01_Max_010"] = "Idiotas. Al menos nadie se metió con el retrato de Kate.",
  ["Act_E4_5A_Corridor_DanielSlate_Look01_Max_010"] = "A pesar de lo que pasó con Kate, nadie aprendió nada sobre el acoso.",
  ["Act_E4_5A_Corridor_Door109Slate_Interact01_Max_010"] = "Puedo divertirme un poco con Warren para variar. Él es el que quiere salir conmigo... y a veces debes aprovechar la oportunidad y ver qué pasa...",
  ["Act_E4_5A_Corridor_Door109Slate_Interact01_Max_020"] = "Puedo divertirme un poco con Warren para variar.|Digo, hace su mejor esfuerzo y rechacé su invitación al autocinema... ¿lo estoy pensando mucho?",
  ["Act_E4_5A_Corridor_Door109Slate_Look01_Max_010"] = "Espero que Nathan no crea que es muy bobo... Digo, no es que no lo sea. Le dará risa, ¿cierto?",
  ["Act_E4_5A_Corridor_Door109Slate_Look02_Max_020"] = "Espero que Warren no tome esto a mal... Pero es mi amigo. Hmmm. Decisiones.",
  ["Act_E4_5A_Corridor_DormMap_Look01_Max_010"] = "¿Quién necesita un mapa de la residencia? Al menos sé que Nathan no está en el cuarto 106 o 108.",
  ["Act_E4_5A_Corridor_EvanSlate_Look02_Max_020"] = "Evan, claro. Obviamente no le importa un carajo... Evan es el rey.",
  ["Act_E4_5A_Corridor_GamerGuysPoster_Look01_Max_010"] = "Les queda una reunión más...",
  ["Act_E4_5A_Corridor_HaydenSlate_Look01_Max_010"] = "Marihuana y videojuegos... creo que Hayden está cerca...",
  ["Act_E4_5A_Corridor_LoganSlate_Look02_Max_020"] = "Parece que uno de los atletas se preocupaba por Kate...",
  ["Act_E4_5A_Corridor_NathanDoor_Interact01_Max_010"] = "¡Súper! Está abierta.",
  ["Act_E4_5A_Corridor_NathanSlate_Look01_Max_010"] = "Este tiene que ser el cuarto de Nathan.",
  ["Act_E4_5A_Corridor_NathanSlate_Look02_Max_020"] = "El número de cuarto de Nathan; La venganza de Kate.",
  ["Act_E4_5A_Corridor_ScriptedIdle_Max_010"] = "Recuerda, Max, ahora estás en territorio enemigo...",
  ["Act_E4_5A_Corridor_ScriptedIdle_Max_020"] = "Vamos, vamos, por favor, quédate lejos, Nathan...",
  ["Act_E4_5A_Corridor_ScriptedIdle_Max_030"] = "Bienvenida al dormitorio de los chicos...",
  ["Act_E4_5A_Corridor_ScriptedKate_Max_010"] = "¡Kate es genial! Así que Cuarto 111 es el número mágico...",
  ["Act_E4_5A_Corridor_ScriptedKate_Max_020"] = "¡Oh, Kate me envío un mensaje! Será mejor leerlo ahora.",
  ["Act_E4_5A_Corridor_ScriptedMajorChoice_Max_010"] = "Carajo, Warren se emocionó con Nathan... y fue estupendo. Pero dio miedo...",
  ["Act_E4_5A_Corridor_ScriptedMajorChoice_Max_020"] = "Aunque Nathan definitivamente se merecía una paliza... somos mejor que eso.",
  ["Act_E4_5A_Corridor_ScriptedNathanDoor01_Max_010"] = "Por eliminación experta, el número de cuarto de Nathan solo puede ser 111...",
  ["Act_E4_5A_Corridor_ScriptedObjective01_Max_010"] = "Okey, definitivamente hay un mapa de dormitorio aquí.",
  ["Act_E4_5A_Corridor_ScriptedObjective01_Max_020"] = "¡Max, apúrate y encuentra la habitación de Nathan!",
  ["Act_E4_5A_Corridor_ScriptedObjective03_Max_010"] = "Causé mucho alboroto en el dormitorio de los chicos... será mejor que busque a Chloe y a Warren.",
  ["Act_E4_5A_Corridor_StopBullyingPoster_Look01_Max_010"] = "Esto me hace pensar en Kate...",
  ["Act_E4_5A_Corridor_ToiletDoor_Look01_Max_010"] = "/!\\ WARNING /!\\ Text not localized : Act_E4_5A_Corridor_ToiletDoor_Look01_Max_010",
  ["Act_E4_5A_Corridor_ToiletPaper_Look01_Max_010"] = "¿Es obligatorio que haya guerras de papel higiénico?",
  ["Act_E4_5A_Corridor_TrevorSlate_Look01_Max_010"] = "Hola, Trevor... y Dana.",
  ["Act_E4_5A_Corridor_WarrenDoor_Look01_Max_010"] = "Pobre Warren. Esto debió ser obra de Nathan. Tiene suerte de que sea una pacifista...",
  ["Act_E4_5A_Corridor_WarrenSlate_Look01_Max_010"] = "¡Hola, cuarto de Warren! Hawking y él hacen un buen equipo.",
  ["Act_E4_5A_Corridor_ZachSlate_Look01_Max_010"] = "¿Zach o Logan? ¿Quién sabe? Los hermanos siempre serán hermanos.",
  ["Act_E4_5A_NathanRoom_Bed_Look01_Max_010"] = "Creo que alguna vez leí que un cuarto limpio es señal de una mente enferma... el cuarto de Nathan está impecable.",
  ["Act_E4_5A_NathanRoom_BluRayCollection_Look01_Max_010"] = "Todas estas películas son oscuras...",
  ["Act_E4_5A_NathanRoom_BondagePoster_Look01_Max_010"] = "Espero que todas los modelos dieran su consentimiento...",
  ["Act_E4_5A_NathanRoom_Book_Look01_Max_010"] = "No creo que un libro pueda guiar a los Prescott.",
  ["Act_E4_5A_NathanRoom_BrokenLamp_Look01_Max_010"] = "Esa debe ser la lámpara que Chloe rompió cuando Nathan la drogó...",
  ["Act_E4_5A_NathanRoom_Camera_Look01_Max_010"] = "Esa cámara monocromática es nueva y cuesta seis mil dólares. Bastardo.",
  ["Act_E4_5A_NathanRoom_Computer_Look01_Max_010"] = "Veamos qué oculta Nathan aquí.",
  ["Act_E4_5A_NathanRoom_DeadBirdsPicture_Look01_Max_010"] = "Es totalmente escalofriante, pero tiene su propio estilo.",
  ["Act_E4_5A_NathanRoom_DogPicture_Look01_Max_010"] = "Dios... Nathan está enfermo.",
  ["Act_E4_5A_NathanRoom_Drawer01_Look01_Max_010"] = "Eso es tan Chloe...",
  ["Act_E4_5A_NathanRoom_Drawer02_Look01_Max_010"] = "Dios mío... Chloe...|Oh, Chloe...",
  ["Act_E4_5A_NathanRoom_ExhibitionPoster_Look01_Max_010"] = "Parece un programa divertido. Incluso Nathan tiene un lado amable.",
  ["Act_E4_5A_NathanRoom_KatePicture_Look01_Max_010"] = "¿Por qué Nathan tomó esto del altar de Kate...? ¿Qué está pensando?",
  ["Act_E4_5A_NathanRoom_Lens_Look01_Max_010"] = "Pensé que Victoria tenía el glamour de las fotos, pero otra vez, el poder es de los Prescotts.",
  ["Act_E4_5A_NathanRoom_Marks_Look01_Max_010"] = "¿Qué diablos son esas marcas en el suelo?",
  ["Act_E4_5A_NathanRoom_MaxPhoto_Look01_Max_010"] = "Oh, no, ese idiota robó una de mis selfies.",
  ["Act_E4_5A_NathanRoom_Mp3Player_Interact01_Max_020"] = "¿Cantos de ballena? Tal vez sea lo único reconfortante que escucha Nathan...",
  ["Act_E4_5A_NathanRoom_Mp3Player_Look01_Max_010"] = "Escuchemos algo de música...",
  ["Act_E4_5A_NathanRoom_NathanArt01_Look01_Max_010"] = "Carajo, Nathan, esa es una buena toma... Si tan solo enfocaras toda tu energía en la fotografía.",
  ["Act_E4_5A_NathanRoom_NathanCellphone_Look01_Max_010"] = "Te tengo telefonito, eres todo mío.",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact01_Max_010"] = "Nathan está muy metido en esta fiesta... Es una mala señal.",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact02_Max_020"] = "Bastardo. Ahora recuerdo por qué te odio... y por lo que Kate tendrá justicia.",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact03_Max_030"] = "Oh, vaya, tal vez Sean Prescott sea el verdadero problema de Nathan...",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact04_Max_040"] = "Qué pena que Nathan no se parece más a su hermana. Parece agradable... y lejana.",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact05_Max_050"] = "Sí, Nathan realmente necesita las pastillas para adelgazar. Esto es muy fuerte...",
  ["Act_E4_5A_NathanRoom_NathanLaptop_Interact06_Max_060"] = "Wow... ¿Quedando bien, director Wells?",
  ["Act_E4_5A_NathanRoom_Pills_Look01_Max_010"] = "No creo que esta prescripción le ayude a Nathan.",
  ["Act_E4_5A_NathanRoom_PornMagazine_Look01_Max_010"] = "Nathan Prescott. Típico adolescente americano...",
  ["Act_E4_5A_NathanRoom_Projector_Look01_Max_010"] = "Claro, yo sería genial con este proyector de alta tecnología...",
  ["Act_E4_5A_NathanRoom_ScriptedGoToChloe_Max_010"] = "Ahora que tengo el teléfono de Nathan debo mostrárselo a Chloe... antes de que él regrese.",
  ["Act_E4_5A_NathanRoom_ScriptedGoToChloe_Max_020"] = "Bien, Chloe me espera con el teléfono. Debo salir de aquí antes de que regrese Nathan.",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_010"] = "Vamos, Max, estás en la boca del lobo. ¡Busca en todas partes!",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_020"] = "Este cuarto se parece a la mente de Nathan...",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_030"] = "Tiene de todo aquí, excepto paz interior.",
  ["Act_E4_5A_NathanRoom_ScriptedIdle_Max_040"] = "Puedo rebobinar si aparece, pero no puedo contar con ello...",
  ["Act_E4_5A_NathanRoom_ScriptedLightChange_Max_010"] = "¡Que se haga la luz!",
  ["Act_E4_5A_NathanRoom_ScriptedObjective01_Max_010"] = "Ahora debo encontrar el teléfono de Nathan o algo con pistas.",
  ["Act_E4_5A_NathanRoom_Sofa_Interact01_Max_020"] = "Descubramos qué escondes...",
  ["Act_E4_5A_NathanRoom_Sofa_Look01_Max_010"] = "Parece que han movido mucho este sillón de atrás hacia adelante...",
  ["Act_E4_5A_NathanRoom_StuffAboutFather01_Look01_Max_010"] = "Es tierno e irónico. No puedo creer que Nathan aún lo conserve.",
  ["Act_E4_5A_NathanRoom_StuffAboutFather02_Look01_Max_010"] = "¡Carajo! Esa es el arma que Nathan usó con Chloe. ¿Quién se la habrá regalado...?",
  ["Act_E4_5A_NathanRoom_StuffAboutFather03_Look01_Max_010"] = "Yo también habría llorado si él fuera mi padre y tuviera que usar ese trajecito...",
  ["Act_E4_5A_NathanRoom_ThreePosters_Look01_Max_010"] = "A Nathan le encantan sus sujetos torturados, un poco demasiado...",
  ["Cue_E4_5A_Corridor_CHChloe_QuickPhase_Chloe_001"] = "Max, ¿qué haces? ¡Apúrate!",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Dana_010"] = "Qué bueno que te quedaste...",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Dana_030"] = "Y después de lo que pasó con Kate...",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Dana_050"] = "Que te preocupes tanto es lo que te hace sexy.",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Trevor_020"] = "Al demonio ese estúpido toque de queda en los dormitorios. Tenemos 18 años.",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Trevor_040"] = "Me siento mal por ella... y su familia...",
  ["Cue_E4_5A_Corridor_DanaTrevor_IGE_Trevor_060"] = "Estoy aquí contigo, ¿no?",
  ["Cue_E4_5A_Corridor_Insertion_Chloe_010"] = "Qué aburridos, no tienen dormitorios mixtos.",
  ["Cue_E4_5A_Corridor_Insertion_Chloe_030"] = "Buen punto.",
  ["Cue_E4_5A_Corridor_Insertion_Chloe_050"] = "No te decepcionaré, Bat-Max.",
  ["Cue_E4_5A_Corridor_Insertion_Max_020"] = "Sí, claro, porque quiero de vecino a Nathan Prescott.",
  ["Cue_E4_5A_Corridor_Insertion_Max_040"] = "Espérame aquí. Dame la señal si aparece Nathan o alguien más.",
  ["Cue_E4_5A_Corridor_Insertion_Max_060"] = "Ahora solo debo encontrar la habitación de Nathan...",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_010"] = "¡Ya verás, marica!",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_020"] = "Oh, eso es increíble",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_030"] = "¡Vamos, dame un poco de eso!",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_040"] = "¡Oye, viejo!...",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_050"] = "¡Oh! Con gusto le patearía el trasero a ese imbécil",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_060"] = "\"¡Mira, está rompiendo esa bola como una hogaza de pan!\"",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_070"] = "¡Ooohhh!... ¡Hazlo!",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_080"] = "¡Ohhh, oh, oooh!",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_090"] = "¡Corre! ¡Corre! ¡Corre! ¡Así! ¡Muy bien! ¡Nooo!...",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_100"] = "Noo... ¡Oh Ohhh!...",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_110"] = "¡Oh, más te vale agarrar eso! Te mataré si no lo haces",
  ["Cue_E4_5A_Corridor_Logan_IGE_Logan_120"] = "¡Yeah!... Ooooohh... ¡Ese es mi muchacho!...",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Chloe_060"] = "¡Sí, debemos irnos!",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Chloe_090"] = "¿Quién es la perra ahora?",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Max_040"] = "¡Cayó! Ey... vamos...",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Max_100"] = "¡Chloe!",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Nathan_030"] = "Ale... aléjate de mí...|Por favor...|¡Detente!",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Nathan_050"] = "Detente... perdón...",
  ["Cue_E4_5A_Corridor_NathanBack_BeatHim_Warren_020"] = "Te gusta lastimar a las personas, ¿huh?|¿Como a Max? ¿Y a Kate? ¿Como a mí? ¿Hah?|¡Siente esto, hijo de puta!",
  ["Cue_E4_5A_Corridor_NathanBack_Chloe_020"] = "¡Bum! Nathan, te tenemos de las pelotas, idiota.",
  ["Cue_E4_5A_Corridor_NathanBack_Max_010"] = "Mira esto...",
  ["Cue_E4_5A_Corridor_NathanBack_Max_070"] = "¡Detente ahí, Nathan!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_050"] = "¿Qué hacen en mi residencia?",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_051"] = "¡Eres una perra entrometida, Max!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_080"] = "Oblígame, puta.",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_090"] = "¡Argh!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_091"] = "¡Sal de mi vista, carajo!",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_120"] = "Están muertos...",
  ["Cue_E4_5A_Corridor_NathanBack_Nathan_130"] = "¡Aléjate de mí, amigo!",
  ["Cue_E4_5A_Corridor_NathanBack_RTC_Chloe_002"] = "Carajo, Max, te tardaste. Me estaba preocupando. ¿Qué encontraste?",
  ["Cue_E4_5A_Corridor_NathanBack_RTC_Max_004"] = "Su cuarto estaba limpio y escalofriante.",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Chloe_040"] = "¡Vámonos, ya!",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Max_010"] = "¡Warren, detente! Por favor.",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Nathan_015"] = "Auch... mi cabeza. ¿Por qué me ven todos ustedes así, huh? ¡Tú... y tú... todos están muertos!",
  ["Cue_E4_5A_Corridor_NathanBack_SaveHim_Nathan_030"] = "Además, ¡mi padre no tarda en llegar! ¡Se los llevará la chingada! ¡Ustedes le pertenecen!",
  ["Cue_E4_5A_Corridor_NathanBack_Warren_110"] = "Max, yo me encargo.",
  ["Cue_E4_5A_Corridor_NathanBeaten_IGE_Nathan_010"] = "Carajo, viejo... esto duele...",
  ["Cue_E4_5A_Corridor_NathanBeaten_IGE_Nathan_020"] = "Creo que mi cara tiene algo roto...",
  ["Cue_E4_5A_Corridor_NathanBeaten_IGE_Nathan_030"] = "Todos me odian... todos...",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_010"] = "Vamos, nena...",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_020"] = "Dame esos puntos, maldito pulpo...",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_030"] = "Un encuentro más y eres mío...",
  ["Cue_E4_5A_Corridor_WarrenToilet_IGE_Warren_040"] = "¡Siguiente nivel, idiota!",
  ["Act_E4_5B_CampusB_BirdGrave_Look01_Max_010"] = "Okey, ¿de dónde vienen estas rocas? Esto se parece demasiado a la Bruja de Blair.",
  ["Act_E4_5B_CampusB_BirdGrave_Look02_Max_020"] = "Qué bueno que Samuel me contó lo de estas rocas... descansen en paz, avecillas.",
  ["Act_E4_5B_CampusB_BirdGrave_PHOTO_Max_030"] = "Una foto... para la posteridad.",
  ["Act_E4_5B_CampusB_BrokenWindow_Look01_Max_010"] = "Eso me pasa por ayudar a Alyssa... una ventana rota.",
  ["Act_E4_5B_CampusB_CHBrooke_Look01_Max_010"] = "Brooke se ve feliz de salir con Warren.",
  ["Act_E4_5B_CampusB_CHBrooke_Look02_Max_020"] = "Brooke no se ve feliz de que yo salga con Warren...",
  ["Act_E4_5B_CampusB_CHChloe_Look01_Max_010"] = "Chloe se entiende tan bien con Justin...",
  ["Act_E4_5B_CampusB_CHDaniel_Look01_Max_010"] = "Pobre Daniel. Parece que necesita un abrazo.",
  ["Act_E4_5B_CampusB_CHGrant_Look01_Max_010"] = "La Sra. Grant parece estar interesada en lo que sea que esté diciendo Samuel…",
  ["Act_E4_5B_CampusB_CHJustin_Look01_Max_010"] = "Es obvio que a Justin le interesa Chloe.",
  ["Act_E4_5B_CampusB_CHSamuel_Look01_Max_010"] = "Es bueno ver que por una vez Samuel no está solo.",
  ["Act_E4_5B_CampusB_CHSquirrelFemale_Look01_Max_010"] = "¿No te gustaría un compañero para una toma rápida?",
  ["Act_E4_5B_CampusB_CHSquirrelFemale_Look02_Max_020"] = "¡Coman! El alimento es el idioma universal.",
  ["Act_E4_5B_CampusB_CHSquirrelMale_Look01_Max_010"] = "¿Pensaste que te escaparías de Max Caulfield, \"Paparazzi de ardillas\"?",
  ["Act_E4_5B_CampusB_CHSquirrelMale_Look02_Max_020"] = "Pon esa comida en tu estómago.",
  ["Act_E4_5B_CampusB_CHSquirrelMale_Look03_Max_030"] = "¿Dos tiernas ardillas posando para mí? Si insisten...",
  ["Act_E4_5B_CampusB_CHSquirrelMale_PHOTO_Max_040"] = "Ahora sonrían y digan “nueces”.",
  ["Act_E4_5B_CampusB_CHZachary_Look01_Max_010"] = "Disfruta el gran juego, Zachary... espero que no sea el último.",
  ["Act_E4_5B_CampusB_KateAltar_Look01_Max_010"] = "Oh... mi dulce Kate.",
  ["Act_E4_5B_CampusB_PermitPanel_Look01_Max_010"] = "Fiu, qué bueno fue evitar que Chloe tomara el dinero del director Wells...",
  ["Act_E4_5B_CampusB_PermitPanel_Look02_Max_020"] = "Oh, genial. Chloe se robó el dinero del fondo para minusválidos... Vamos a arder en el infierno.",
  ["Act_E4_5B_CampusB_PrincipalQuarterDoor_Look01_Max_010"] = "El director Wells estaba tan mal aquí la otra noche.",
  ["Act_E4_5B_CampusB_ScriptedObjective01_Max_010"] = "Averigüemos dónde está Nathan.",
  ["Act_E4_5B_CampusB_ScriptedObjective01_Max_020"] = "Entonces, ¿a quién le pregunto...?",
  ["Act_E4_5B_CampusB_ScriptedObjective02_Max_010"] = "Bien, Nathan no está cerca. Debo regresar con Chloe.",
  ["Act_E4_5B_CampusB_Tobanga_Look01_Max_010"] = "No creo que Tobanga nos diga nunca sus secretos.",
  ["Cue_E4_5B_CampusB_BrookeGoApe_IGE_Brooke_010"] = "Qué ironía que Warren invitara a Max al autocinema...",
  ["Cue_E4_5B_CampusB_BrookeGoApe_IGE_Brooke_020"] = "No es que no tenga todas las películas originales de los simios...",
  ["Cue_E4_5B_CampusB_BrookeGoApe_IGE_Brooke_030"] = "Tal vez debí pedirle a Warren ir...",
  ["Cue_E4_5B_CampusB_BrookeNoApe_IGE_Brooke_010"] = "Espero que Max no esté molesta porque Warren me invitó al autocinema...",
  ["Cue_E4_5B_CampusB_BrookeNoApe_IGE_Brooke_020"] = "Después de esta semana, definitivamente necesito un descanso de Blackwell.",
  ["Cue_E4_5B_CampusB_BrookeNoApe_IGE_Brooke_030"] = "Me pregunto si Warren prefiere ir con Max que conmigo...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_010"] = "Aquí, como siempre. Por cierto, gracias por ayudar a Kate a bajar. ¿Estás bien?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_019"] = "Considerando lo que le pasó a Kate, podría estar mejor. ¿Estás bien?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_021"] = "¿Segura que estás bien?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_023"] = "La Sra. Grant finalmente cedió y me dejó volarlo otra vez. Pero tú tienes una cita con Warren, así que no tienes tiempo para volarlo.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_024"] = "La Sra. Grant cedió y me dejó volarlo otra vez. Así que diviértete. Tengo que ver a qué hora iré al autocinema con Warren el sábado.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_027"] = "Qué perceptiva eres, Max. Ahora, si me disculpas. Mi drone me necesita.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_028"] = "Diviértete en tu salida. ¿Me disculpas, Max? Mi drone me necesita.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_029"] = "Warren tiene un auto nuevo. O uno viejo pero nuevo. Así que estoy planeando seriamente en un paseo fuera de aquí esta semana.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_030"] = "Me encanta el autocinema en Newberg. Tan a la antigua, pero muy divertido... como Warren.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_034"] = "Pregúntale a Warren. Digo, ya que van a ir a ver películas y eso...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_035"] = "Warren me distrajo al invitarme al autocinema.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_040"] = "De hecho, trató de recuperar mi drone hace poco. Fue muy extraño. Luego me preguntó si iría a la fiesta del club Vortex... sí lo haré. Pero no sé...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_041"] = "¿Warren no es suficientemente bueno para ti? Bien. Vi a Nathan furioso hace rato saliendo del campus... Buena suerte consiguiendo esa cita, Max.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_042"] = "De hecho, trató de recuperar mi drone hace poco. Fue muy extraño. Luego me preguntó si iría a la fiesta del club Vortex... sí lo haré. Pero no sé...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_043"] = "Lo vi esta mañana salir del campus. Parecía más molesto de lo usual... Yo no lo buscaría si fuera tú.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_044"] = "Se supone que Warren y yo compartiríamos notas y teorías este fin de semana.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_045"] = "Obtendríamos el premio Nobel si pudiéramos explicar este fenómeno... pero ni la señora Grant tiene idea...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Brooke_046"] = "Ya sabes, los nerds de la ciencia siempre juntos. Pero en serio, ninguno de nosotros puede explicar este fenómeno... da mucho miedo.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_001"] = "Hola, Brooke, ¿cómo estás?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_020"] = "De regreso, Brooke.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_022"] = "Tal vez me sienta mejor volando un rato tu drone.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_025"] = "¿En serio? ¿No puedo volar tu drone porque iré a ver películas de simios con Warren?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_026"] = "Basta, Brooke. Deja de ser tan mala. Solo iré a ver unas películas de simios con mi amigo...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_031"] = "Suena divertido. Sería bueno que tú y Warren den un paseo en auto después de esta semana...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_032"] = "Ah, ¿te pidió que fueras con él al autocinema? Bien... genial.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_033"] = "Necesito encontrar a Nathan, ¿lo has visto por aquí?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_036"] = "Nathan fue suspendido, pero debe seguir en el campus.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_037"] = "Es día de escuela, Nathan debe estar por aquí.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_038"] = "Muy bien Brooke. Pero en este momento intento encontrar a Nathan...",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_039"] = "Vamos, Brooke, no seas así. Nathan fue suspendido, pero debe seguir en el campus.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_047"] = "Mi limitado cerebro no entiende el eclipse y las ballenas encalladas... esperaba que el departamento de ciencia tuviera algunas ideas.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_048"] = "Eso tiene sentido. Dos cerebros son mejores que uno... o el mío.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_049"] = "Oh, ¿te invitó?",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeDial_Max_050"] = "Debo irme. Hablamos después, Brooke.",
  ["Cue_E4_5B_CampusB_CHBrooke_BrookeQP_Brooke_001"] = "Hablamos después, Max.",
  ["Cue_E4_5B_CampusB_CHChloe_ChloeQP_Chloe_001"] = "¡Avísame si descubres algo!",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_028"] = "Hola, Max. Acabo de darme cuenta de que mis fotos básicamente apestan. Soy un intento de artista...",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_030"] = "Me siento mejor ahora, Max. Eres buena.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_032"] = "¿Alejarme de mi cuaderno de dibujo? No me conoces, Max. Es como si tú te mantuvieras lejos de tu cámara. Creo que solo me sentaré aquí triste, gracias.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_034"] = "Tiene sentido, pero no soy yo quien elige las consignas. Si tan solo pudiera dibujar mis fotografías... Creo que me quedaré aquí sentado y triste, gracias.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_036"] = "“Lente-pluma”... entiendo eso, Max. Eso funcionaría para mí...",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_039"] = "Para tu suerte, Max, me agrada que me molestes.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_043"] = "Lo sería si voy, ¿sabes? La gente aquí me empuja a los casilleros, no a la pista de baile.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_045"] = "No se merecen nada... Digo, ¿qué hacen en realidad por Blackwell? Tienes razón, Max, que se vayan al diablo.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_046"] = "No contigo como refuerzo, Max. Diablos, ¡iré a la fiesta como si fuera el fin del mundo! Okey, tal vez no vaya, pero... No, no lo haré, pero iré.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_048"] = "Oh, oí el rumor de que realmente está suspendido...",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_049"] = "¿Dices últimamente?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_052"] = "Eso explica por qué se veía tan molesto cuando lo vi salir del campus hace unos momentos...",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_053"] = "Vi a Jefferson hablando con Nathan hace poco, pero trato de mantenerme alejado de él. Tengo suficientes idiotas con los cuales lidiar aquí.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_055"] = "No hablo con nadie, Max. Pero tuve una conversación con Brooke. Estaba muy triste por lo de Kate.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_056"] = "No hablo con nadie, Max. Pero tuve una conversación agradable con Brooke. No podía dejar de hablar de lo valiente que fuiste en la azotea.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_059"] = "Deberíamos dejar de ir a clases y hacer una protesta. Pero eso no pasaría en Blackwell. Aún...",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_060"] = "Estoy de acuerdo, Max. Ella es la persona más dulce y genuina que haya conocido... No me importa que me moleste esa hermandad de idiotas de Blackwell, pero que no se metan con Kate.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Daniel_062"] = "Solo si puedo comenzar la revolución desde mi cuaderno de dibujo, Max.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_027"] = "Hola, Daniel. Pareces triste. ¿Estás bien?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_029"] = "No estás aquí para ser fotógrafo. Eso es lo mío. Pero mira el dibujo que hiciste de mí... Increíble. Ese es tu arte; tu don.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_031"] = "No te rindas tan pronto. Solo aléjate de tu libreta de dibujo por un tiempo. No dejes de tomar fotografías,|como dice el Sr. Jefferson.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_033"] = "Tal vez debas intentar con objetos diferentes... algo más como retratos.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_035"] = "Daniel, tus dibujos son tus fotografías.|Dibuja tus fotos con los ojos y que la cámara sea tu lente-pluma.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_037"] = "Pensé que te molestaría otra vez, Daniel.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_040"] = "Hablemos después. ¿Está bien, Daniel?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_041"] = "¿Irás en la noche a la fiesta del \"Fin del mundo\"?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_042"] = "Al diablo el club Vortex. No te merecen, Daniel.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_044"] = "Por eso debes ir a esa fiesta. Debemos enfrentarnos a los abusadores de Blackwell por Kate. No estarás solo, Daniel.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_047"] = "Por cierto ¿has visto a Nathan Prescott?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_050"] = "Sí, pero debe seguir en el campus.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_051"] = "En cualquier momento hoy.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_054"] = "¿Haz hablado con alguien sobre lo que pasó con Kate?",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_057"] = "Yo también. Y enojada...",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_058"] = "No creo que hacer lo correcto sea \"valiente\", pero aprecio lo que quiso decir. Lo más importante es que Kate se recupere... y se haga justicia.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielDial_Max_061"] = "Me agrada este Daniel DaCosta revolucionario.",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielQP1_Daniel_001"] = "Gracias de nuevo por ayudarme a sentirme mejor. ¡Al diablo el club Vortex! ¡Nos vemos luego, Max!",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielQP2_Daniel_002"] = "Gracias de nuevo por ayudarme a sentirme mejor y animarme a ir a la fiesta. ¡Nos vemos luego, Max!",
  ["Cue_E4_5B_CampusB_CHDaniel_DanielQP3_Daniel_001"] = "Ah, ey, Max. Perdona, sigo con mis lamentos. Hablaremos cuando no sea tan patético.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_002"] = "Max, siempre apareces cuando estoy hablando de ti. Aún presumo de ti y los otros estudiantes que se oponen al sistema de vigilancia.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_015"] = "Max, siempre apareces cuando estoy hablando de ti. Y juro que no se trata de la petición que no firmaste.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_017"] = "El Sr. Prescott no está tomando ninguna clase... hasta que termine su suspensión. No sabía que eran amigos.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_018"] = "Qué sorpresa, Max. No creí que ustedes dos fueran exactamente amigos.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_027"] = "Eso depende de tu definición... Pero me gustaría ver más amistades en Blackwell y menos bullying. En especial después de esta semana.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_028"] = "Ya estás grande, puedes maldecir, carajo. Y me alegra que lo hicieras.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_029"] = "Lo intenté. Nathan es un Prescott, y con ello tiene una gran carga. Es demasiado para un adolescente. Esta semana fue la prueba de eso... el director Wells hizo lo correcto.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_030"] = "Lo vi salir del campus más enojado de lo normal. Pero para ser honestos, Max, Nathan no ha estado muy bien últimamente. Tal vez tú sepas más de eso que yo.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_031"] = "Digamos que intento que no sea así, Max. Pero lo vi saliendo muy enfadado del campus. Después de lo que pasó esta semana, espero que no lo hayas visto tampoco... No eres la mejor estudiante aquí, pero sí la más sabia.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_032"] = "Sí, así es, Max. Lo intenté una vez... pero el Sr. Prescott no apreció mi ayuda. Vi a Nathan salir del campus, se veía más enojado de lo usual... Así que tal vez sea mejor que no lo hayas visto.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_033"] = "Se nota. Pero parece que tienes más de una pregunta en tu cabeza. Tal vez preguntarle a Nathan no sea tan buena idea en este momento, ¿entiendes, Max?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_034"] = "Lo vi salir del campus enojado hace poco. Pero parece que tienes en mente algo más que una pregunta...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_036"] = "Si pudiera, estaría recogiendo el premio Nobel de ciencia hoy. No he podido entender ese eclipse, mucho menos la nieve y las ballenas...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_039"] = "Cuando mis amigos de la NASA dicen que no pueden explicar un eclipse solar|sin una sola teoría de cómo o por qué, tal vez sea momento de preocuparnos... como ellos.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_040"] = "Nada está más allá de la ciencia, a excepción de nuestra falta de conocimiento. Tal vez nunca sepamos por qué, pero eso no cambia la realidad.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_042"] = "Samuel piensa igual. Estábamos hablando de eso antes de que vinieras. Nuestro planeta está cambiando, pero no es místico. Es erosión.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_045"] = "Bueno, nuestra línea costera ha estado retrocediendo,|y la contaminación diaria del océano no ayuda.|Es todo lo que necesitas para matar la vida salvaje y marina aquí...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_046"] = "Max, sabes cuánto me fascinan las leyendas de Arcadia Bay, pero no he visto ninguna señal apocalíptica aún... a menos que cuenten esos pósteres del \"Fin del mundo\".",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_047"] = "¿A menos que sepas algo que yo no?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_050"] = "Los únicos agujeros de gusano aquí, están bajo tierra. Y la teoría del caos es solo eso... Pero en cuanto a viajes en el tiempo, estoy a bordo.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_051"] = "Oh, Max, nadie ni siquiera sabe quién trajo a Tobanga aquí. Probablemente unos pescadores locales lo robaron del Pacífico Sur... Pero sé lo que dices. Hay mucha energía aquí.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_053"] = "No después de leer esa historia de Bradbury, \"El ruido de un trueno\". No te contaré todo, pero involucra dinosaurios y mariposas. El tiempo es como un hilo, Max. Un tirón y se derenrollará.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_056"] = "Siempre es agradable platicar contigo, Max.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_058"] = "Bienvenida al laboratorio, Max.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_059"] = "Oh, Max, lamento tanto que hayas pasado por eso... Kate era la estudiante más dulce que haya conocido en Blackwell... y ellos pueden ser tan crueles unos con otros... ¿necesitas hablar con el consejero?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_060"] = "¿Quién necesita vigilancia cuando tenemos a Max Caulfield? Estuviste increíble. Ahora solo debemos seguir ayudando a Kate. ¿Necesitas hablar con un consejero?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_063"] = "Me alegra escuchar eso, Max. Solo no temas hablar con alguien nunca, ¿está bien? Ojalá Kate se hubiera acercado a mí... no tenía idea de lo que le estaba pasando.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_064"] = "Esta semana no ha sido la mejor de Blackwell. Pero algunos miembros de la escuela y yo no descansaremos hasta que los estudiantes se sientan seguros, sin ser acosados.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_066"] = "Cerrando ese maldito club Vortex, por empezar. No quiero sonar como una loca, pero esa fiesta debería posponerse... Es de muy mal gusto considerando lo que le pasó a Kate.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_069"] = "Claro que no. Pero pertenecer tiene sus privilegios... Especialmente cuando tu padre es el mayor patrocinador de Blackwell. No debemos tolerar estas tonterías elitistas.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_070"] = "Raymond Wells salvó a esta escuela de la ruina financiera y se preocupa de verdad.|Eres sabia, pero no te apresures al juzgar a alguien.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Grant_072"] = "Te entiendo, Max. Me encanta verte a ti, a Warren y a todos mis estudiantes dando lo mejor de sí. Eres muy joven para ser tan cínica... Pero en realidad me das esperanza.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_001"] = "Hola, Sra. Grant.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_016"] = "Estaba buscando a Nathan Prescott y pensé que podría estar en su clase...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_019"] = "Probablemente usted lo conoce mejor...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_020"] = "Ni loca. Solo debo... hacerle una pregunta.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_021"] = "Solo, compañeros de clase. No puedo creer que tenga amigos.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_022"] = "Carajo, no... perdón, Sra. Grant.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_023"] = "¿Así que no has visto a Nathan para nada?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_024"] = "Lo sé. Nathan necesita ayuda.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_025"] = "Demasiado...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_026"] = "Yo también, Sra. Grant. ¿Entonces no sabe dónde está Nathan?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_035"] = "Esperaba que pudiera explicarme algo|de estas cosas tan locas que están pasando en Arcadia Bay...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_037"] = "Debe haber una explicación científica... ¿cierto?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_038"] = "Creo que esto va más allá de la ciencia.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_041"] = "Me preocupa la realidad... Siento que está cambiando justo en frente de nosotros.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_043"] = "¿Cree que por eso todos estos animales están muriendo aquí?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_044"] = "¿Así que no cree que esto sea una especie de profecía o algo así?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_048"] = "Podría tener algo que ver con los agujeros de gusano y la teoría del caos... Viajes en el tiempo y esas cosas...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_049"] = "Me pregunto si Tobanga sabe más que todos aquí...",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_052"] = "¿Realmente cambiaría el tiempo?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_054"] = "No creo que la vigilancia habría ayudado a Kate Marsh.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_055"] = "Lo siento, Sra. Grant, debo irme. La veré después.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_057"] = "Hola otra vez, Sra. Grant.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_061"] = "No, gracias, Sra. Grant. Tengo a mi mejor amiga y a mis padres... por ahora.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_062"] = "La Academia Blackwell es la que necesita ayuda. Algo terrible ocurre aquí. Lo ve ¿cierto?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_065"] = "A Kate la drogaron en el club Vortex y luego ellos la acosaron,|hasta que terminó en la azotea.|¿Cómo detiene eso?",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_067"] = "¿Los Prescott tienen algo que ver con el club Vortex? No sacan todo su dinero de los autolavados.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_068"] = "¿Y por qué el director Wells no detiene la fiesta? Para ser honesta, no parece importarle lo que ocurre aquí.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantDial_Max_071"] = "Tiene razón... Ojalá esta fuera la escuela que soñé antes de venir.",
  ["Cue_E4_5B_CampusB_CHGrant_GrantQP_Grant_001"] = "Nos vemos después, Max.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_016"] = "Así es, Samuel. ¿Cómo estás?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_018"] = "Perdón por molestarte otra vez, Samuel.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_020"] = "Más preguntas que respuestas...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_023"] = "Definitivamente tengo preguntas sobre qué ocurre con los animales de Arcadia Bay.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_024"] = "Aún tengo un millón de preguntas sobre qué ocurre en Arcadia Bay.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_026"] = "Lo siento, será mejor que me vaya ahora.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_029"] = "¿Has visto a Nathan Prescott por aquí?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_030"] = "No pareces triste, Samuel.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_031"] = "Se lo merecía. Eso y más.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_032"] = "Whoa, realmente no te agrada Nathan. ¿Por qué?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_033"] = "¿Y qué sabes de Nathan?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_038"] = "¿Qué sabe en realidad de él?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_039"] = "Bien, okey, entiendo. Conoces muchos secretos de Blackwell, así que pensé que podrías ayudarme.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_042"] = "Blackwell está tan triste y tranquilo desde que Kate... ya no está con nosotros.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_043"] = "De hecho acabo de hablar con Kate Marsh en el hospital. Está mucho mejor.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_049"] = "Samuel, tú eres los ojos de Blackwell. ¿Sabías que acosaban a Kate?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_050"] = "Podría haber ocurrido de cualquier forma... Samuel, ¿crees que cada uno tiene un destino?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_052"] = "Te creo...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_054"] = "¿Alguna vez has hablado con David Madsen?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_057"] = "Así funciona David.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_059"] = "¿Por qué lo dices?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_060"] = "Ya quisiera.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_063"] = "Yo creo que tú observas mejor que él o yo.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_065"] = "¿Qué piensas de todas esas aves que están muriendo?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_067"] = "¿Eso no le importa a Tobanga?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_068"] = "¿Qué les pasó?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_071"] = "Es tan siniestro.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_073"] = "¿Cómo puede alguien explicar todas esas ballenas encalladas...?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_074"] = "Me alegra ver que tus ardillas siguen sanas y felices en el campus.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_077"] = "No mientras esté aquí para cuidarlas, Samuel.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_078"] = "¿Cree que sea una especie de desastre ecológico, o...?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_079"] = "No son las únicas estos días... me siento tan impotente.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_084"] = "¿Eso crees, Samuel?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_085"] = "Aún creo que si encontramos a Rachel Amber tendremos algunas respuestas...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_086"] = "Aunque le agrado a la señora Grant,|tengo cero habilidades científicas para explicar ese eclipse.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_087"] = "Preferiría estar en su clase que en el club Vortex.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_091"] = "No es la única.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_093"] = "¿Cómo sabes eso? En verdad me da curiosidad.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_094"] = "¿El inicio de qué?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_098"] = "¿Crees que esté viva?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_099"] = "Ese es el verdadero secreto... ¿Dónde está?",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Max_102"] = "Pero...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_015"] = "¿Cómo estás, Max? Ha sido una semana muy dura, lo sé.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_017"] = "Triste y confundido, como todos en Arcadia Bay. Parece que tú también tienes muchas preguntas...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_019"] = "Por mí no hay problema, Max.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_021"] = "Samuel siempre está aquí para platicar.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_022"] = "Oh, no eres la única. Estas pobres criaturas no tienen opinión sobre lo que les pasa...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_025"] = "Tal vez por eso la señora Grant dice que eres una de sus estudiantes favoritas.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_027"] = "Sería difícil, después de que lo suspendieron...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_028"] = "Trato de que no sea así.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_034"] = "Nathan lastima gente. El fin.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_035"] = "Samuel trata de no juzgar a las personas, pero Nathan no debería estar aquí. Tal vez se supone que debería estar aquí.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_036"] = "A Samuel le agradan todos... hasta que le den una razón para no hacerlo. Él le dio una.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_037"] = "Sé suficiente como para no querer saber más.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_040"] = "No lo suficiente para ayudarte, Max. Ojalá pudiera... Entiendo lo que estás haciendo...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_041"] = "Max, soy personal de limpieza, no psíquico... solo puedo advertirte que seas cuidadosa.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_044"] = "Sí, se nota que el campus es diferente ahora... y tú te acercaste a ella cuando todos le dieron la espalda.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_045"] = "Por ti, Max. Eso fue todo un rescate.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_048"] = "Casi todos se burlan de Samuel... pero Samuel les advirtió de Kate. Odio a los acosadores, Max.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_051"] = "Así es, Max. En muchas diferentes vidas. Claro, Kate Marsh creía en algo diferente, así que ese es su destino...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_053"] = "Kate solo necesitaba más espíritus bondadosos, como el de su amiga Max. Espero que ahora los encuentre.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_055"] = "No desde que lo suspendieron. Pero no hablaría con él. Solo lo escucharía.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_056"] = "Él me habla. Yo escucho.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_058"] = "Ve cosas, no personas. Pero creo que te ve a ti, Max...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_061"] = "Ya que ambos ven con cámaras.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_062"] = "El Sr. Madsen tiene toda la vigilancia del mundo, pero sigue estando ciego.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_064"] = "No, Max, solo veo las cosas desde un ángulo diferente.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_066"] = "Samuel tuvo que enterrar docenas cerca de Tobanga...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_069"] = "Veremos si las almas de las aves avanzan. No es que podamos comprobarlo, pero...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_070"] = "Diría que el cielo es muy sucio para sus alas, pero hay algo peor en el aire...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_072"] = "A menos que sea el destino... entonces no importa.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_075"] = "Mi padre era pescador y me llevaba a escuchar el canto de las ballenas... Ahora solo lloran.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_076"] = "Yo también. Si algo les llegara a pasar...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_080"] = "Lo único que las calma es la comida. Mucha. Lo que me recuerda que debo alimentarlas ahora.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_081"] = "Creo que es más que eso... alguien está causando que todo esto pase.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_082"] = "Oh, no. Eres todo lo contrario a impotente, Max.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_083"] = "Tú y Arcadia Bay están conectadas por el tiempo y el oleaje... Así que cuando tenga una pregunta, acudiré a ti.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_088"] = "Si Rachel quiere que la encuentren.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_089"] = "Como le decía, eso es porque la ciencia no tiene explicación.|Sin ofender a la Sra. Grant. Pero este solo es el comienzo...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_090"] = "Claro que sí. Rachel vio a través de ellos rápidamente.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_092"] = "Nadie debe ser atrapado en el club Vortex. Sal ahora, Max... mientras el tiempo está de tu lado.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_095"] = "Solo debes abrir los ojos... y verás lo que viene.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_096"] = "Oh, creo que nada termina... en especial el tiempo...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_097"] = "Por eso puedo sentir que algo grande se acerca a Arcadia Bay... y debo decirte, Max, que no me agrada para nada.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_100"] = "Siempre vivirá en nuestros corazones... A veces eso es todo lo que nos queda.",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_101"] = "Si alguien lo descubrirá, serás tú. Eso dicen mis sueños...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelDial_Samuel_103"] = "Max, solo puedo decirte que si sigues tu camino, descubrirás lo que buscas... Rachel Amber te espera...",
  ["Cue_E4_5B_CampusB_CHSamuel_SamuelQP_Samuel_001"] = "Solo somos polvo en el viento.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_010"] = "Justin, hace mucho que no te veo...",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_030"] = "Hay demasiada mierda sucediendo, viejo...",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_050"] = "Eso he escuchado...",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_070"] = "Oye, eso quisiera. En eso estoy.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_090"] = "Probablemente estaba drogada.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Chloe_110"] = "Qué buen dado. Okey, debo irme.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_020"] = "Porque eres demasiado genial para nosotros, Chloe.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_040"] = "Trata de ir a Blackwell. Es una locura.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_060"] = "¿Sabes algo de Rachel?",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_080"] = "Extraño su risa cuando me bajaba de mi tabla.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_100"] = "Sí, ella tenía la hierba.",
  ["Cue_E4_5B_CampusB_ChloeJustin_IGE_Justin_120"] = "Únanse a nosotros alguna vez en el parque.",
  ["Cue_E4_5B_CampusB_Daniel_IGE_Daniel_010"] = "Bueno, Daniel, la fotografía no es tu fuerte.",
  ["Cue_E4_5B_CampusB_Daniel_IGE_Daniel_020"] = "Solo seguiré dibujando...",
  ["Cue_E4_5B_CampusB_Daniel_IGE_Daniel_030"] = "Ojalá tuviera el talento del Sr. Jefferson...",
  ["Cue_E4_5B_CampusB_Drone_Max_010"] = "Gracias.",
  ["Cue_E4_5B_CampusB_Extraction_Chloe_020"] = "Pero ahora el Sr. Jefferson es todo tuyo...",
  ["Cue_E4_5B_CampusB_Extraction_Max_010"] = "No hay moros en la costa.|Sería increíble si fuéramos a la escuela juntas aquí.",
  ["Cue_E4_5B_CampusB_Extraction_Max_030"] = "Apestas. Vamos, entremos en modo ninja de Blackwell.",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_TeenBoy02_020"] = "¡Ese es tu trabajo, Zach!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_TeenBoy02_040"] = "¡Debemos destruir a los Razorbacks!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_Zachary_010"] = "¡Mándalo a casa, hermano!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_Zachary_030"] = "¡Espera al juego!",
  ["Cue_E4_5B_CampusB_FootballGuys_IGE_Zachary_050"] = "¡PISADA DE PIES GRANDES!",
  ["Cue_E4_5B_CampusB_GrantCallsMax_IGE_Grant_010"] = "Hola, Max, ¡gracias otra vez por ayudarme a pelear contra el poder!",
  ["Cue_E4_5B_CampusB_GrantCallsMax_IGE_Grant_020"] = "Es bueno verte bien, Max.",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_040"] = "Qué hay.",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_060"] = "Era demasiado genial para esta escuela. Una larga historia que está en archivos reales aquí.",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_240"] = "Yo también. Seré la cita de Max. Será mejor que baile con nosotras al menos una vez.",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_260"] = "¡Así será!",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_270"] = "Muy sexy para ser un maestro.",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_290"] = "Aún no. Ya me verás esta noche...",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_310"] = "No te pongas celosa solo porque Mark Jefferson piensa que soy genial...",
  ["Cue_E4_5B_CampusB_Insertion_Chloe_330"] = "Bien. Veré si puedo sacarle algo a Justin. Hace mucho que no platico con él.",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_010"] = "Hola, Max. ¿Cómo estás?",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_050"] = "Chloe, ¿por qué no hay nadie tan genial como tú en Blackwell?",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_100"] = "Max, ¿segura que estás bien?",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_110"] = "Me imagino.",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_140"] = "Bueno, ya eres adulta y esto no es una prisión, ¿o sí?",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_170"] = "Lo sé. Tan tonto como suene, la vida debe seguir.",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_190"] = "Sobre eso, el deber de Blackwell llama. Recuerda que hoy anunciaré al ganador del concurso Héroes Cotidianos por la noche en la fiesta, así que espero que estés ahí para celebrar. Aunque me apena que no hayas concursado con una foto, comprendo tus razones. No puedes forzar a un artista a trabajar...",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_220"] = "Me enorgullece que te preocupes tanto por una amiga en problemas. Y deseo que tengas suficiente tiempo para encontrar tu camino... Solo adquiere el hábito de sacar tu trabajo a la luz.",
  ["Cue_E4_5B_CampusB_Insertion_Jefferson_250"] = "Nadie debe verme bailar. Además, no querrán ver al hipster viejo tratando de llevarle el paso a los jóvenes. Tengo mi orgullo. Nos vemos.",
  ["Cue_E4_5B_CampusB_Insertion_Max_020"] = "Oh, hola, Sr. Jefferson. Estoy bien...",
  ["Cue_E4_5B_CampusB_Insertion_Max_030"] = "Ah... y ella es mi amiga, Chloe.",
  ["Cue_E4_5B_CampusB_Insertion_Max_130"] = "Es raro que te suspendan y solo caminar por el campus.",
  ["Cue_E4_5B_CampusB_Insertion_Max_150"] = "No hasta que tengamos los trajes naranjas.",
  ["Cue_E4_5B_CampusB_Insertion_Max_160"] = "Es extraño estar en el campus como si todo estuviera normal.",
  ["Cue_E4_5B_CampusB_Insertion_Max_180"] = "Creo que están ocurriendo muchas cosas en mi vida.",
  ["Cue_E4_5B_CampusB_Insertion_Max_200"] = "Entonces, ¿no me odia por lo que le dije al director?",
  ["Cue_E4_5B_CampusB_Insertion_Max_210"] = "Me siento como una perdedora, pero no ha sido una buena semana para enfocarme.|No va con segunda intención.",
  ["Cue_E4_5B_CampusB_Insertion_Max_230"] = "Gracias, Sr. Jefferson. Definitivamente estaré ahí en la noche.",
  ["Cue_E4_5B_CampusB_Insertion_Max_280"] = "Qué asco. Estás fuera de control.",
  ["Cue_E4_5B_CampusB_Insertion_Max_300"] = "Cállate.",
  ["Cue_E4_5B_CampusB_Insertion_Max_320"] = "Voy a ignorarte.",
  ["Cue_E4_5B_CampusB_Insertion_Max_340"] = "¡Ése es un buen plan!",
  ["Cue_E4_5B_CampusB_SamuelBench_IGE_Samuel_010"] = "Samuel extraña sus ardillas…",
  ["Cue_E4_5B_CampusB_SamuelBench_IGE_Samuel_020"] = "Parece que el cielo quisiera gritarnos...",
  ["Cue_E4_5B_CampusB_SamuelBench_IGE_Samuel_030"] = "Es momento de limpiar el grafiti de esos malditos.",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Grant_020"] = "Me pone furiosa. Que el cambio climático no es real, idiotas.",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Grant_040"] = "Como científica, estoy fascinada. Como Michelle Grant, estoy muy preocupada.",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Grant_060"] = "Sin mencionar a la pobre Kate Marsh...",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_010"] = "Tuve que limpiar otro grupo de aves muertas hoy... fue muy triste.",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_030"] = "Creo que todo está cambiando aquí.",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_050"] = "Arcadia Bay también tiene miedo. Mira el clima y a los animales...",
  ["Cue_E4_5B_CampusB_SamuelGrant_IGE_Samuel_070"] = "Todos necesitamos cuidarnos de unos a otros estos días.",
  ["Cue_E4_5B_CampusB_Skater_IGE_TeenBoy01_010"] = "¡A movernos, Perras!",
  ["Cue_E4_5B_CampusB_Skater_IGE_TeenBoy01_020"] = "Hey, ¿ya son las 4:20?",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_010"] = "En realidad le dio una paliza a Nathan.",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_030"] = "Ahora citémonos con Frank.",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_070"] = "Frank siempre contesta cuando quiere dinero.",
  ["Cue_E4_5C_CampusA_Extraction_Chloe_080"] = "Como dije, Frank quiere verme ahora.",
  ["Cue_E4_5C_CampusA_Extraction_Max_020"] = "Me asustó un poco verlo hacer eso.",
  ["Cue_E4_5C_CampusA_Extraction_Max_040"] = "Espero que no mencione a su perro...",
  ["Cue_E4_5C_CampusA_Extraction_Max_050"] = "Espero que mantenga lejos a su perro...",
  ["Cue_E4_5C_CampusA_Extraction_Max_060"] = "¿Alguna vez te va a contestar?",
  ["Cue_E4_5C_CampusA_Extraction_Max_090"] = "No lo hagamos esperar mucho...",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_030"] = "Por darle su merecido a Nathan Prescott. Viejo, eres increíble.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_050"] = "Por darle ese cabezazo a Nathan Prescott. Fue fantástico.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_100"] = "Warren, Max y yo debemos hacer esto por nuestra cuenta. No te ofendas.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Chloe_170"] = "Oye, ese chico está perdido por ti.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_010"] = "Carajo, eso fue intenso.|Muchas gracias, Warren.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_070"] = "No eres como él en absoluto.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_090"] = "Sin policía. No aún. Ah... así que mejor tú... ah...",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_120"] = "Lo que puedes hacer es meterte a tu cuarto y descubrir si hay más advertencias de tormenta.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_121"] = "Lo que puedes hacer es descubrir lo que puedas del padre de Nathan...",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_140"] = "Y en verdad, gracias.|Te llamaré después.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_160"] = "Claro que lo eres.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Max_180"] = "Lo sé...",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_020"] = "¿Por qué?",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_040"] = "No lo sé. Me puse un poco loco ahí... como Nathan.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_060"] = "No lo sé. Casi me vuelvo loco ahí... como Nathan.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_080"] = "Mejor así. ¿Y adónde van? Será mejor que vaya con ustedes... Por si me necesitan en versión Hulk otra vez. ¿O acuso a Nathan con la Policía?",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_110"] = "Está bien. Lo que sea por ayudar.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_130"] = "Lo haré. Entre la nieve y el eclipse, asumo que el apocalipsis está cerca.",
  ["Cue_E4_5C_CampusA_ThanksWarren_Warren_150"] = "Más te vale. Me siento poderoso ahora.",
  ["Act_E4_6A_Corridor_Digicode_Fail_Max_010"] = "Ups. Código equivocado.",
  ["Act_E4_6A_Corridor_Digicode_Fail_Max_020"] = "¡Tú puedes Max!",
  ["Act_E4_6A_Corridor_Digicode_Fail_Max_030"] = "¡Piensa, Max, piensa!",
  ["Act_E4_6A_Corridor_Digicode_Fail_Max_040"] = "Código incorrecto",
  ["Act_E4_6A_Corridor_Digicode_Interact01_Max_020"] = "Algunos números están borrosos, solo necesito un poco de suerte.",
  ["Act_E4_6A_Corridor_Digicode_Interact02_Max_030"] = "¡Genial! ¡Creí que esto solo funcionaba en las películas!",
  ["Act_E4_6A_Corridor_Digicode_Interact03_Max_040"] = "Demonios, eso no funcionó.",
  ["Act_E4_6A_Corridor_Digicode_Locked_Max_010"] = "¡Lo bloqueaste, mensa!",
  ["Act_E4_6A_Corridor_Digicode_Locked_Max_020"] = "Está bloqueado...",
  ["Act_E4_6A_Corridor_Digicode_Look01_Max_010"] = "Primero un candado, luego un código digital... Alguien en verdad no quiere visitas.",
  ["Act_E4_6A_Corridor_ReinforcedDoor_Look01_Max_010"] = "Es muy duro como para romperlo, necesitaré un código.",
  ["Act_E4_6A_Corridor_ScriptedIdle_Max_010"] = "La única razón para construir un búnker secreto bajo una granja abandonada es para hacer alguna chingadera malvada.",
  ["Act_E4_6A_Corridor_ScriptedIdle_Max_020"] = "Este búnker es totalmente surrealista.",
  ["Act_E4_6A_Corridor_ScriptedObjective01_Max_010"] = "Esa es una puerta resistente. ¿Dónde está Gandalf cuando lo necesitas...?",
  ["Act_E4_6A_Corridor_ScriptedObjective01_Max_020"] = "Vamos, Max, descubre el código de esta cosa.",
  ["Act_E4_6A_Corridor_ScriptedObjective01_Max_030"] = "Código, números, rebobina... respira y trata de nuevo.",
  ["Act_E4_6A_DarkRoom_Alcohol_Look01_Max_010"] = "A alguien le gusta su whiskey...",
  ["Act_E4_6A_DarkRoom_Cans_Look01_Max_010"] = "Mira esas latas... David debe ir a la misma tienda.",
  ["Act_E4_6A_DarkRoom_Computer_Interact01_Max_010"] = "Veamos qué hay aquí...|Oh por Dios... no...",
  ["Act_E4_6A_DarkRoom_Computer_Look01_Max_010"] = "Esta computadora sí que debió costarle.",
  ["Act_E4_6A_DarkRoom_ConstructionPapers_Look01_Max_010"] = "Ese hijo de puta...",
  ["Act_E4_6A_DarkRoom_CupBoard02_Look01_Max_010"] = "Veamos qué hay detrás de esta puerta...",
  ["Act_E4_6A_DarkRoom_Cupboard01_Look01_Max_010"] = "Ah, el sistema de entretenimiento del apocalipsis.",
  ["Act_E4_6A_DarkRoom_DrugBottles_Look01_Max_010"] = "Frank no estará cerca para empujar esto...",
  ["Act_E4_6A_DarkRoom_DrugBottles_Look01_Max_020"] = "Esta debe ser la basura que Nathan le compra a Frank.",
  ["Act_E4_6A_DarkRoom_DuctTape_Look01_Max_010"] = "La cinta de aislar en un búnker siempre es mala señal.",
  ["Act_E4_6A_DarkRoom_Food_Look01_Max_010"] = "Más suministros de supervivencia...",
  ["Act_E4_6A_DarkRoom_InstructionNote_Look01_Max_010"] = "Wow. ¿Qué pasa entre Nathan y su padre?",
  ["Act_E4_6A_DarkRoom_KateFile_Look01_Max_010"] = "Kate se ve tan fuera de sí. No tiene idea de que la están haciendo posar.",
  ["Act_E4_6A_DarkRoom_KateFile_Look02_Max_020"] = "Por lo menos Kate estuvo dormida durante esa estúpida sesión.",
  ["Act_E4_6A_DarkRoom_NewspapersPile_Look01_Max_010"] = "Todos estos periódicos son sobre Rachel y Kate...",
  ["Act_E4_6A_DarkRoom_PhotoCrate_Look01_Max_010"] = "Nunca había visto tanto equipo tan caro antes.",
  ["Act_E4_6A_DarkRoom_PhotoPrinter_Look01_Max_010"] = "Supongo que Nathan necesita la impresora más cara del mundo.",
  ["Act_E4_6A_DarkRoom_Picture02_Look01_Max_010"] = "Hablando de tortura...",
  ["Act_E4_6A_DarkRoom_Picture03_Look01_Max_010"] = "Esa es una ilustración original autografiada. Queda perfecta aquí.",
  ["Act_E4_6A_DarkRoom_PsychiatristLetter_Look01_Max_010"] = "Vaya, esto dice todo sobre Nathan... Necesita ayuda.",
  ["Act_E4_6A_DarkRoom_RachelFile_Look01_Max_010"] = "Esta foto parece diferente. Rachel está despierta y furiosa.",
  ["Act_E4_6A_DarkRoom_RachelFile_Look02_Max_020"] = "Rachel se desmayó y tiene algo en la boca. ¿Qué le pasó?",
  ["Act_E4_6A_DarkRoom_RachelFile_Look03_Max_030"] = "Esta foto está tan montada que... No puedo creer que sea real, simplemente no puedo.",
  ["Act_E4_6A_DarkRoom_ScriptedChloeLeft_Max_010"] = "Oh, Dios mío... Rachel... Kate... Todos estos archivos...|En verdad hay un aura de maldad en este lugar.",
  ["Act_E4_6A_DarkRoom_ScriptedChloeLeft_Max_020"] = "Si Chloe reconoció un lugar en el depósito de chatarra, es mejor que vaya con ella| y prepararnos para lo peor... nos necesitaremos mutuamente.",
  ["Act_E4_6A_DarkRoom_ScriptedChloeLeft_Max_030"] = "Tal vez haya más pistas por aquí, pero debo regresar pronto con Chloe...",
  ["Act_E4_6A_DarkRoom_ScriptedIdle01_Max_010"] = "¿Qué mierda es esto...?",
  ["Act_E4_6A_DarkRoom_ScriptedIdle01_Max_020"] = "¿Cómo consiguió Nathan este lugar? ¿Será un regalo de su padre?",
  ["Act_E4_6A_DarkRoom_ScriptedIdle01_Max_030"] = "No creo que este lugar sea solo un estudio fotográfico.",
  ["Act_E4_6A_DarkRoom_ScriptedIdle01_Max_040"] = "Oh, no... ¿Esta es la habitación blanca y brillante de la que Kate me habló?",
  ["Act_E4_6A_DarkRoom_ScriptedIdle01_Max_050"] = "Ni siquiera podría inventar estas cosas sobre los Prescott...",
  ["Act_E4_6A_DarkRoom_ScriptedObjective_Max_010"] = "Exploremos este cuarto, Max. Debe haber evidencia aquí.",
  ["Act_E4_6A_DarkRoom_ScriptedObjective_Max_020"] = "Sé que aquí habrá algo perturbador.",
  ["Act_E4_6A_DarkRoom_SealedNeedles_Look01_Max_010"] = "Jeringas... Qué horror...",
  ["Act_E4_6A_DarkRoom_SeanLetter_Look01_Max_010"] = "Oh, sí, la suspensión escolar es tradición en la familia Prescott.",
  ["Act_E4_6A_DarkRoom_Tripod_Look01_Max_010"] = "¿Quién usa el moderno tripie?",
  ["Act_E4_6A_DarkRoom_Water_Look01_Max_010"] = "Suministros de agua. Es como el búnker en el garage de David...",
  ["Act_E4_6A_OldFarm_Crate01_Interact01_Max_020"] = "Mmm... parece una típica granja.",
  ["Act_E4_6A_OldFarm_Crate01_Interact02_Max_030"] = "Ah, los viejos tiempos...",
  ["Act_E4_6A_OldFarm_Crate02_Interact01_Max_020"] = "Al parecer los Prescott son unos cabrones de nacimiento...",
  ["Act_E4_6A_OldFarm_Crate02_Interact02_Max_030"] = "Hasta a Harry Aaron Prescott le gustaban las selfis...",
  ["Act_E4_6A_OldFarm_ElectricBox_Look01_Max_010"] = "¿Por qué necesita alguien tanta electricidad en un viejo granero?",
  ["Act_E4_6A_OldFarm_Fork_Look01_Max_010"] = "Seguro esta horquilla no abrirá el candado. Sigue intentando, Max.",
  ["Act_E4_6A_OldFarm_Hatch_Look01_Max_010"] = "Vaya, ¿qué es esto...? suena hueco...",
  ["Act_E4_6A_OldFarm_Hatch_Look02_Max_020"] = "¿Pero qué es esto?|Esto es totalmente nuevo. ¿Por qué?",
  ["Act_E4_6A_OldFarm_Haystack02_Look01_Max_010"] = "Tantos pajares y tan pocas agujas...",
  ["Act_E4_6A_OldFarm_Hook01_Look02_Max_020"] = "El gancho está amarrado con fuerza a la soga, puedo usarlo para abrir la compuerta...",
  ["Act_E4_6A_OldFarm_Hook02_Look01_Max_010"] = "Aquí está el otro extremo de la soga...",
  ["Act_E4_6A_OldFarm_Hook_Look01_Max_010"] = "Hmmm, usan estos ganchos para levantar pajares... los vi en la película de “Viernes 13”.",
  ["Act_E4_6A_OldFarm_NoTrespassingSign_Look01_Max_010"] = "Mírennos.",
  ["Act_E4_6A_OldFarm_OldButton_Look01_Max_010"] = "No hay forma de que este viejo botón active estas cuerdas o poleas...",
  ["Act_E4_6A_OldFarm_OldCar_Look01_Max_010"] = "Watson, podemos asumir con seguridad que este vehículo viejo no es nuestro sospechoso.",
  ["Act_E4_6A_OldFarm_OldFork_Look01_Max_010"] = "Si aparece un zombie, ya sé con qué matarlo.",
  ["Act_E4_6A_OldFarm_OldMotor_Look01_Max_010"] = "Hablando de metales pesados... puedo usar eso para abrir la compuerta.",
  ["Act_E4_6A_OldFarm_OldMotor_Look02_Max_020"] = "Esto parece suficientemente resistente como para subirme.",
  ["Act_E4_6A_OldFarm_OldMotor_Look03_Max_030"] = "Bueno, esto no sirvió de nada.",
  ["Act_E4_6A_OldFarm_OldMotor_Look04_Max_040"] = "No, Max, inténtalo de nuevo.",
  ["Act_E4_6A_OldFarm_OldPliers_Interact01_Max_030"] = "No tengo nada que perder, excepto todo este óxido.",
  ["Act_E4_6A_OldFarm_OldPliers_Look01_Max_010"] = "No creo que me sirvan esta herramientas polvosas.",
  ["Act_E4_6A_OldFarm_OldTractor_Look01_Max_010"] = "Este tractor dio lo mejor de sí.",
  ["Act_E4_6A_OldFarm_OldWoodenChest_Look01_Max_010"] = "Chloe también sería una excelente detective...",
  ["Act_E4_6A_OldFarm_Owl_Look01_Max_010"] = "Qué hay, \"Doctor Buuu\". Perdón.",
  ["Act_E4_6A_OldFarm_Padlock_Interact01_Max_030"] = "No, SuperMax, no puedes abrir esto solo con tus manos.",
  ["Act_E4_6A_OldFarm_Padlock_Interact02_Max_040"] = "Están demasiado oxidados...",
  ["Act_E4_6A_OldFarm_Padlock_Look01_Max_010"] = "Primero debo romper ese enorme candado.",
  ["Act_E4_6A_OldFarm_Padlock_Look02_Max_020"] = "¡Ojalá Warren hubiera visto ese truco de física!",
  ["Act_E4_6A_OldFarm_Platform01_Look01_Max_010"] = "Hmmm, la soga lleva a esa plataforma... debo subirme.",
  ["Act_E4_6A_OldFarm_Pliers_Look01_Max_010"] = "Diablos, esas pinzas están fosilizadas. Necesito algo fuerte para romper el candado.",
  ["Act_E4_6A_OldFarm_Rope_Interact01_Max_010"] = "No, si jalo de esta cuerda acabaré con mi pellejo. Necesito engancharla a algo más pesado...",
  ["Act_E4_6A_OldFarm_RustyPlank01_Look01_Max_010"] = "Solo madera podrida...",
  ["Act_E4_6A_OldFarm_ScriptedChloe_Max_010"] = "Chloe no le teme a nada... ¿De dónde saca esa fuerza?",
  ["Act_E4_6A_OldFarm_ScriptedIdle_Max_010"] = "Este lugar es más que tétrico.",
  ["Act_E4_6A_OldFarm_ScriptedIdle_Max_020"] = "Espero que este sea el lugar correcto y que no nos hayamos equivocado con las coordenadas.",
  ["Act_E4_6A_OldFarm_ScriptedIdle_Max_030"] = "Y sí, tengo un mal presentimiento sobre esto.",
  ["Act_E4_6A_OldFarm_ScriptedIdle_Max_040"] = "Es curioso pensar que los Prescott comenzaron con una granja...|Nathan sigue actuando como un orco.",
  ["Act_E4_6A_OldFarm_ScriptedObjective01_Max_010"] = "Ahora debo encontrar una forma de entrar al granero.",
  ["Act_E4_6A_OldFarm_ScriptedObjective01_Max_020"] = "No podemos tirar la puerta, debemos encontrar otra forma de entrar.",
  ["Act_E4_6A_OldFarm_ScriptedObjective02_Max_010"] = "Tiene que haber algo más aquí que solo unos recortes sobre los Prescott.",
  ["Act_E4_6A_OldFarm_ScriptedObjective02_Max_020"] = "Mejor sigo viendo qué hay por aquí...",
  ["Act_E4_6A_OldFarm_ScriptedObjective02_Max_030"] = "Puedo buscar debajo de todas esas placas de metal o esa paja...",
  ["Act_E4_6A_OldFarm_ScriptedPreviousChoice_Max_010"] = "Chloe y yo realmente matamos a alguien...|¿Qué nos va a pasar ahora?",
  ["Act_E4_6A_OldFarm_ScriptedPuzzle_Max_020"] = "Tal vez si arrojamos algo muy pesado sobre eso...",
  ["Act_E4_6A_OldFarm_ScriptedPuzzle_Max_030"] = "Revisa el área, Max, tal vez encuentres algo pesado que podamos usar.",
  ["Act_E4_6A_OldFarm_ScriptedPuzzle_Max_040"] = "Debo subir y pedirle ayuda a Chloe.",
  ["Act_E4_6A_OldFarm_ScriptedPuzzle_Max_060"] = "Puedo usar este motor viejo con esa soga y el gancho...",
  ["Act_E4_6A_OldFarm_ScriptedPuzzle_Max_070"] = "Creo que puedo utilizar el viejo motor como contrapeso para romper el candado.",
  ["Act_E4_6A_OldFarm_ScriptedPuzzle_Max_080"] = "Max, rebobina y haz que el motor suba a donde estaba.",
  ["Act_E4_6A_OldFarm_ScriptedSuccess_Max_010"] = "¡MaxGyver lo hizo de nuevo!",
  ["Act_E4_6A_OldFarm_TireTracks01_Look01_Max_010"] = "Mmm... estas son huellas de llantas gruesas... y definitivamente son recientes, ¿serán de la SUV de Nathan?",
  ["Act_E4_6A_OldFarm_TireTracks02_Look01_Max_010"] = "Debe haber una razón por la que alguien maneja hasta este lugar... pero no se me ocurre ninguna...",
  ["Act_E4_6A_OldFarm_WoodenPlank_Look01_Max_010"] = "Nada por aquí.",
  ["Cue_E4_6A_DarkRoom_ChloeShelf_IGE_Chloe_010"] = "Por Dios, ya odio este lugar.",
  ["Cue_E4_6A_DarkRoom_ChloeShelf_IGE_Chloe_020"] = "Mira toda esta basura tan rara...",
  ["Cue_E4_6A_DarkRoom_ChloeShelf_IGE_Chloe_030"] = "Sigue buscando, Chloe...",
  ["Cue_E4_6A_DarkRoom_ChloeShelf_IGE_Chloe_040"] = "¿Qué tienen los Prescott con ese arte tétrico?",
  ["Cue_E4_6A_DarkRoom_ChloeShelf_IGE_Chloe_050"] = "¿Puedes imaginarte relajándote en esta habitación?",
  ["Cue_E4_6A_DarkRoom_ChloeShelf_IGE_Chloe_060"] = "Todo esto es muy sospechoso, pero no hay nada sobre Rachel.",
  ["Cue_E4_6A_OldFarm_ChloeBarnLock_Chloe_010"] = "Creo que veo algo ahí. Esto tiene que ser.",
  ["Cue_E4_6A_OldFarm_ChloeBarnLock_Chloe_020"] = "Debe haber alguna otra forma de entrar, Max. Apuesto a que puedes encontrarla.",
  ["Cue_E4_6A_OldFarm_ChloeBarnLock_IGE_Chloe_010"] = "¡A la chingada con esto!",
  ["Cue_E4_6A_OldFarm_ChloeBarnLock_IGE_Chloe_020"] = "¡Ábrete, maldita sea, ábrete!",
  ["Cue_E4_6A_OldFarm_ChloeBarnLock_IGE_Chloe_030"] = "¡Ven acá antes de que le prenda fuego a este lugar, Max!",
  ["Cue_E4_6A_OldFarm_ChloeHook2_IGE_Chloe_020"] = "Sí que eres lista. Yo me encargo de esto.",
  ["Cue_E4_6A_OldFarm_ChloeHook2_IGE_Chloe_030"] = "Hágase tu voluntad.",
  ["Cue_E4_6A_OldFarm_ChloeHook2_IGE_Max_010"] = "Oye, Chloe, ¿puedes poner el gancho en el candado?",
  ["Cue_E4_6A_OldFarm_ChloeHook2_IGE_Max_040"] = "¡Es mejor que te alejes de esa compuerta!",
  ["Cue_E4_6A_OldFarm_ChloeMax_IGE_Chloe_010"] = "Ten cuidado allá arriba, Max.",
  ["Cue_E4_6A_OldFarm_ChloeMax_IGE_Chloe_020"] = "Avísame si necesitas ayuda.",
  ["Cue_E4_6A_OldFarm_ChloeMax_IGE_Chloe_030"] = "¡No vayas a caerte!",
  ["Cue_E4_6A_OldFarm_ChloeSearchCrate_IGE_Chloe_010"] = "Basta de secretos, Sean Prescott.",
  ["Cue_E4_6A_OldFarm_ChloeSearchCrate_IGE_Chloe_020"] = "Maldición, hay mucha información aquí...",
  ["Cue_E4_6A_OldFarm_ChloeSearchCrate_IGE_Chloe_030"] = "Aquí no hay nada interesante...",
  ["Cue_E4_6A_OldFarm_ChloeSearchCrate_IGE_Chloe_040"] = "Viejo... viejo...",
  ["Cue_E4_6A_OldFarm_ChloeSearchCrate_IGE_Chloe_050"] = "Revisa el perímetro, Max. Debe haber algo más que esta caja.",
  ["Cue_E4_6A_OldFarm_EnterDarkRoom_Chloe_020"] = "Lleno de provisiones y listo para el apocalipsis. Sin duda esto costó una fortuna.",
  ["Cue_E4_6A_OldFarm_EnterDarkRoom_Chloe_030"] = "Vamos.",
  ["Cue_E4_6A_OldFarm_EnterDarkRoom_Max_010"] = "Ábrete sésamo.",
  ["Cue_E4_6A_OldFarm_EnterDarkRoom_Max_020"] = "¡Genial! ¡Creí que esto solo funcionaba en las películas!",
  ["Cue_E4_6A_OldFarm_EnterFarm_Chloe_020"] = "Tranquila, SuperMax.",
  ["Cue_E4_6A_OldFarm_EnterFarm_Chloe_025"] = "¡Oye! ¡Mira este vejestorio!",
  ["Cue_E4_6A_OldFarm_EnterFarm_Chloe_040"] = "¡Lotería! Solo cosas viejas.",
  ["Cue_E4_6A_OldFarm_EnterFarm_Chloe_060"] = "\"Harry Aaron Prescott y su familia donan una nueva biblioteca a Arcadia Bay...\". \"Las industrias Prescott celebran la gran apertura...\". \"Los Prescott traen a la ciudad los famosos refugios antibombas\".",
  ["Cue_E4_6A_OldFarm_EnterFarm_Max_010"] = "Por Dios, esto es demasiado Bruja de Blair... Me eriza la piel.",
  ["Cue_E4_6A_OldFarm_EnterFarm_Max_030"] = "¿Por qué no haces más ruido, Chloe?",
  ["Cue_E4_6A_OldFarm_EnterFarm_Max_035"] = "Sí que es antiguo...",
  ["Cue_E4_6A_OldFarm_EnterFarm_Max_050"] = "No, observa con atención.",
  ["Cue_E4_6A_OldFarm_EnterFarm_Max_070"] = "Lindo álbum de recortes. Sigue buscando pistas mientras yo reviso el lugar.",
  ["Cue_E4_6A_OldFarm_EnterHatch_Chloe_020"] = "¿Pero qué... es esto?",
  ["Cue_E4_6A_OldFarm_EnterHatch_Chloe_050"] = "Justo lo acabas de hacer. ¿Qué clase de persona construye un lugar como este?",
  ["Cue_E4_6A_OldFarm_EnterHatch_Max_010"] = "Carajo, esto pesa mucho...",
  ["Cue_E4_6A_OldFarm_EnterHatch_Max_030"] = "Lotería.",
  ["Cue_E4_6A_OldFarm_EnterHatch_Max_040"] = "No creo que necesite decir lo extraño que es esto...",
  ["Cue_E4_6A_OldFarm_EnterHatch_Max_060"] = "Tenía que ser un Prescott.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Chloe_010"] = "Muy bien, veamos de qué demonios se trata todo esto.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Chloe_040"] = "Mira, la siguiente carpeta dice \"Kate\".",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Chloe_060"] = "Carajo, debí de haber matado a ese cabrón aquella vez.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Chloe_090"] = "¡Rachel...!",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Chloe_100"] = "Esto no puede ser real... Ella... ella posó... en estas fotos ¿verdad? ¿VERDAD?",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Chloe_120"] = "Tal vez... Tal vez Nathan le ofreció una puta fortuna para hacer esto. Ella habría aceptado.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Chloe_140"] = "¡El depósito de chatarra, Max! ¡Tenemos que encontrar ese lugar ahora mismo! Entonces podremos ver lo que él hizo... No es posible que ella esté muerta. ¡No! Ella posó para esas fotos, lo sé. Te lo ruego... ¡Vamos!",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Max_020"] = "Hágamoslo.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Max_030"] = "Mira, hay una carpeta que dice \"Victoria\", pero está vacía...",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Max_050"] = "Oh no, Kate... No puede ser...",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Max_070"] = "Kate no fue la primera... Todas esas carpetas están llenas de otras víctimas.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Max_080"] = "Victoria debe ser la siguiente. Apuesto a que Nathan planea drogarla en la fiesta del club Vortex esta noche.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Max_110"] = "Chloe, mira su cara... Ella está... totalmente fuera de sí.",
  ["Cue_E4_6A_OldFarm_FileDiscovery_Max_130"] = "No lo creo, Chloe. ¿Por qué él la estaría colocando en el suelo de esa manera? ¿En dónde...?",
  ["Cue_E4_6A_OldFarm_Insertion_Chloe_020"] = "Lo sé, pero ya estamos aquí. Busquemos la mejor forma de entrar.",
  ["Cue_E4_6A_OldFarm_Insertion_Chloe_040"] = "Oye, alguien estuvo aquí hace poco.",
  ["Cue_E4_6A_OldFarm_Insertion_Max_010"] = "Maldición, esto asusta.",
  ["Cue_E4_6A_OldFarm_Insertion_Max_030"] = "Hey, mira esto... Hay marcas recientes de llantas.",
  ["Cue_E4_6A_OldFarm_Insertion_Max_050"] = "Debemos entrar al granero...",
  ["Cue_E4_6A_OldFarm_LegUp_IGE_Chloe_020"] = "¡Aquí llega la ayuda!",
  ["Cue_E4_6A_OldFarm_LegUp_IGE_Chloe_030"] = "¡Al infinito y más allá, SuperMax!",
  ["Cue_E4_6A_OldFarm_LegUp_IGE_Max_010"] = "Chloe, ¿me puedes ayudar?",
  ["Cue_E4_6A_OldFarm_LegUp_IGE_Max_040"] = "Me encanta tener ayudantes.",
  ["Cue_E4_6A_OldFarm_MaxCallsChloe_Chloe_020"] = "¡Perfecto! ¡Maximus es la mejor!",
  ["Cue_E4_6A_OldFarm_MaxCallsChloe_Max_010"] = "¡Mira, Chloe! ¡Encontré la puerta principal! ¡Ven!",
  ["Cue_E4_6A_OldFarm_MaxFoundHatch_Chloe_020"] = "¡Avísame si necesitas ayuda!",
  ["Cue_E4_6A_OldFarm_MaxFoundHatch_Max_010"] = "Chloe, acabo de encontrar una especie de compuerta en el suelo, pero está cerrada. Creo que puedo con esto...",
  ["Cue_E4_7A_Junkyard_Insertion_Chloe_020"] = "¡Sé exactamente a dónde voy!",
  ["Cue_E4_7A_Junkyard_Insertion_Chloe_030"] = "¡Mira! ¡Es aquí, es aquí!",
  ["Cue_E4_7A_Junkyard_Insertion_Chloe_050"] = "¿Me ayudas, Max?",
  ["Cue_E4_7A_Junkyard_Insertion_Chloe_070"] = "No, por favor, no...",
  ["Cue_E4_7A_Junkyard_Insertion_Chloe_100"] = "Rachel...|Por Dios, Rachel...|No... no... no...|Por favor, no... no ella...",
  ["Cue_E4_7A_Junkyard_Insertion_Chloe_120"] = "¡Rachel! No... ¡¿Por qué?!",
  ["Cue_E4_7A_Junkyard_Insertion_Chloe_140"] = "Yo la amaba tanto...|No puede haber muerto.|¿En qué mundo pasa esto?|¡¿Quién hizo esto?!",
  ["Cue_E4_7A_Junkyard_Insertion_Max_010"] = "¡Chloe, despacio, espérame!",
  ["Cue_E4_7A_Junkyard_Insertion_Max_040"] = "Ay, no...",
  ["Cue_E4_7A_Junkyard_Insertion_Max_060"] = "Chloe, ¡detente! Mira...",
  ["Cue_E4_7A_Junkyard_Insertion_Max_080"] = "Qué peste...",
  ["Cue_E4_7A_Junkyard_Insertion_Max_090"] = "¡Oh, por Dios!",
  ["Cue_E4_7A_Junkyard_Insertion_Max_110"] = "Chloe...",
  ["Cue_E4_7A_Junkyard_Insertion_Max_130"] = "Lo siento mucho Chloe, lo siento...",
  ["Act_E4_8B_MenToilets_Bra_Look01_Max_010"] = "Qué asco... ¿cómo demonios llegó esto aquí?",
  ["Act_E4_8B_MenToilets_CHJustin_Look01_Max_010"] = "Justin solo está un poco intoxicado.",
  ["Act_E4_8B_MenToilets_ClosedDoor_Look01_Max_010"] = "Deben estar cogiendo o vomitando... o las dos cosas. ¡Puaj!",
  ["Act_E4_8B_MenToilets_DrunkGuy_Look01_Max_010"] = "Buenas noches, príncipe encantador...",
  ["Act_E4_8B_MenToilets_Graffiti01_Look01_Max_010"] = "Comienza la contracorriente...",
  ["Act_E4_8B_MenToilets_Graffiti03_Look01_Max_010"] = "Chloe debe de andar por aquí...",
  ["Act_E4_8B_MenToilets_Graffiti04_Look01_Max_010"] = "Ya no más...",
  ["Act_E4_8B_MenToilets_ToiletPaper_Look01_Max_010"] = "Parece que Blackwell tiene un serio fetiche con el papel de baño.",
  ["Act_E4_8B_Pool_BigfootGraffiti_Look01_Max_010"] = "Los Bigfoot contra los Otter...",
  ["Act_E4_8B_Pool_Bouncer_Max_010"] = "No me impresiona nada toda esta mierda VIP.",
  ["Act_E4_8B_Pool_CHAlyssa_Look01_Max_010"] = "No puede ser... ¿es una broma?",
  ["Act_E4_8B_Pool_CHAlyssa_Look02_Max_020"] = "Mira a Alyssa mover ese trasero.",
  ["Act_E4_8B_Pool_CHBrooke_Look01_Max_010"] = "Brooke está harta de esta fiesta y lista para salir con Warren.",
  ["Act_E4_8B_Pool_CHBrooke_Look02_Max_020"] = "¿Está enojada porque Warren me invitara a salir?",
  ["Act_E4_8B_Pool_CHBrooke_Look03_Max_030"] = "¿Están coqueteando Daniel y Brooke? Chido.",
  ["Act_E4_8B_Pool_CHCourtney_Look01_Max_010"] = "Ahí está Courtney bebiendo sola, sin Taylor ni Victoria... ¿Por qué será?",
  ["Act_E4_8B_Pool_CHCourtney_Look02_Max_020"] = "Mejor voy a ver si ella me puede meter a esa estúpida sección VIP.",
  ["Act_E4_8B_Pool_CHCourtney_Look03_Max_030"] = "No te estreses, Courtney, aún pienso a entrar a la sección VIP.",
  ["Act_E4_8B_Pool_CHCourtney_Look04_Max_040"] = "Así que solo tuve que adular a Courtney para entrar. ¡Bien hecho, Max!",
  ["Act_E4_8B_Pool_CHDaniel_Look01_Max_010"] = "Me alegra haber convencido a Daniel de venir, justo para verlo coquetear con Brooke.",
  ["Act_E4_8B_Pool_CHLuke_Look01_Max_010"] = "Los días de escuela...",
  ["Act_E4_8B_Pool_Chips_Look01_Max_010"] = "Papas y galletas... el club Vortex no escatima en gastos.",
  ["Act_E4_8B_Pool_LightStick_Look01_Max_010"] = "¿Qué sería de una fiesta de mierda sin varitas luminosas?",
  ["Act_E4_8B_Pool_NoRunningNoDivingSign_Look01_Max_010"] = "Ah, claro, el agudo ingenio del club Vortex.",
  ["Act_E4_8B_Pool_OxygenKit_Look01_Max_010"] = "Este kit de oxígeno puede ser útil si alguien se excede.",
  ["Act_E4_8B_Pool_PilesOfBottles_Look01_Max_010"] = "Bebidas energizantes, refresco, bebidas energizantes... Sé que alguien por aquí tiene alcohol.",
  ["Act_E4_8B_Pool_RejectedMember_Look01_Max_010"] = "Créeme, no te estás perdiendo de nada.",
  ["Act_E4_8B_Pool_VIPKeeper_Look01_Max_010"] = "¿Por qué Courtney no está vigilando la lista de la sección VIP?",
  ["Act_E4_8B_Pool_VortexCLubLogo_Look01_Max_010"] = "Sí, sin duda apestas.",
  ["Act_E4_8B_SwimPool_DJ_Look01_Max_010"] = "El club Vortex incluso contrató a \"DJ Doom\" para la fiesta...",
  ["Act_E4_8B_SwimPool_LineDrum_Look01_Max_010"] = "Mmm... Podría apartar esto y oficialmente infiltrarme en la zona VIP.",
  ["Act_E4_8B_SwimPool_Poster02_Look01_Max_010"] = "Me encantaría arrancar toda esa basura...",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_010"] = "Espero que Chloe pueda manejar todo esto...",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_020"] = "Después de todo esto, Rachel está muerta...",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_030"] = "Todos tienen ganas de festejar mientras Nathan se sale con la suya...",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_040"] = "Tenemos que evitar que Nathan lastime a alguien más esta noche.",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_050"] = "Siento como si estuviera en alguna clase de pesadilla...",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_060"] = "Todo en Blackwell parece maligno para mí en este momento.",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_070"] = "El director Wells debió haber cancelado esta fiesta... pero le llegaron al precio.",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_080"] = "Voy a vengar a Kate y a Rachel, así sea lo último que haga.",
  ["Act_E4_8B_SwimPool_ScriptedIdle_Max_090"] = "Hey, chicos, ¡vamos a emborracharnos y a nadar! ¿Qué puede pasar?",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_010"] = "Por Dios, Chloe, ¿dónde demonios estás?",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_020"] = "Necesitamos encontrar a Nathan y acabar con él.",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_030"] = "Sé que Victoria es la siguiente en la lista de Nathan... ¿Debería prevenirle?",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_040"] = "Nathan ES el club Vortex, así que seguro lo encontraré aquí.",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_050"] = "Necesito encontrar la forma de entrar a este maldito club.",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_060"] = "Nadie parece saber dónde está Nathan. ¿Se estará escondiendo o algo así?",
  ["Act_E4_8B_SwimPool_ScriptedObjective_Max_080"] = "Gran idea, Max. Es hora de encontrar otra forma de entrar a la sección VIP.",
  ["Act_E4_8B_SwimPool_ScriptedPhoto_Max_010"] = "No estoy de humor, pero de todos modos... esta podría ser una foto interesante.",
  ["Act_E4_8B_VIP_Barman_Max_010"] = "Por lo visto los Vortex VIP consiguen alcohol verdadero en su bar para menores de edad... de nuevo.",
  ["Act_E4_8B_VIP_Bottles_Max_010"] = "No. Más. Botellas.",
  ["Act_E4_8B_VIP_CHChloe_Look01_Max_010"] = "Perfecto, aquí está Chloe. Evidentemente no encontró a Nathan.",
  ["Act_E4_8B_VIP_CHDana_Max_010"] = "Me alegra que Dana y Trevor terminaran juntos.",
  ["Act_E4_8B_VIP_CHHayden_Look01_Max_010"] = "Vaya sorpresa, Hayden está perdido. Seguro comenzó a beber antes que todos...",
  ["Act_E4_8B_VIP_CHJuliet_Max_010"] = "Por lo visto Juliet se enredó con Zachary de nuevo... es mejor que tenga cuidado para que él no vuelva a grabar un video porno como venganza o algo así...",
  ["Act_E4_8B_VIP_CHLogan_Look01_Max_010"] = "No, Logan, nadie te va a dar acción esta noche. Ni siquiera un baile.",
  ["Act_E4_8B_VIP_CHLogan_Look02_Max_020"] = "Después de nuestra plática, tal vez Logan comience a tomar sus decisiones con seriedad... o tal vez no.",
  ["Act_E4_8B_VIP_CHTaylor_Max_010"] = "Taylor en verdad muestra su espíritu del club Vortex.",
  ["Act_E4_8B_VIP_CHTrevor_Max_010"] = "Me encanta que a Trevor no le importe lo mal que baila en la sección VIP...",
  ["Act_E4_8B_VIP_CHVictoria_Look01_Max_010"] = "Aquí está la abeja reina...",
  ["Act_E4_8B_VIP_CHVictoria_Look02_Max_010"] = "Esto no salió tan mal como creí. Al parecer Victoria creyó en mi advertencia, tal vez.",
  ["Act_E4_8B_VIP_CHVictoria_Look03_Max_010"] = "Carajo, ella no me creyó para nada... lo intenté... en verdad lo intenté...",
  ["Act_E4_8B_VIP_CHVictoria_Look04_Max_010"] = "Maldición, tal vez debía advertir a Victoria. ¿Nathan se atrevería a molestarla?",
  ["Act_E4_8B_VIP_CHZachary_Max_010"] = "Zachary, te lo advierto, si le haces algo a Juliet te voy a patear las pelotas por toda la eternidad.",
  ["Act_E4_8B_VIP_DrunkGirl_Max_010"] = "Está tan perdida y nadie la está cuidando... Nadie aprende en Blackwell.",
  ["Act_E4_8B_VIP_Graffiti01_Look01_Max_010"] = "Eso me hace querer hacer un \"Carrie\" en el club Vortex...",
  ["Act_E4_8B_VIP_Graffiti02_Look01_Max_010"] = "Victoria y sus imitaciones estuvieron aquí.",
  ["Act_E4_8B_VIP_Pipe_Look01_Max_010"] = "Un bong... increíble, denme un respiro.",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_010"] = "Un sillón de piel y una alfombra persa... ¿serán de verdad?",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_020"] = "Esto los debe de hacer sentir súper mega ultra especiales.",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_030"] = "Apuesto a que Rachel odiaba salir con estas personas...",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_040"] = "Por Dios, esta maldita fiesta es tan insensible y de mal gusto.",
  ["Act_E4_8B_VIP_ScriptedIdle_Max_050"] = "Bailen, monos amaestrados, bailen para los Prescott... ustedes les pertenecen.",
  ["Act_E4_8B_VIP_ScriptedMajorChoice_Max_010"] = "¿Debí advertirle a Victoria sobre Nathan? Ella es una mala persona, pero...",
  ["Act_E4_8B_VIP_ScriptedMajorChoice_Max_020"] = "De acuerdo, lo intenté... Ella no va a creerme por encima de su compañero del club Vortex...",
  ["Act_E4_8B_VIP_ScriptedMajorChoice_Max_030"] = "Tal vez aún hay esperanza para Victoria y para mí... Me alegro de haberla prevenido. Espero que esté bien.",
  ["Act_E4_8B_VIP_ScriptedObjective_Max_010"] = "Ese hijo de puta no está aquí... ¿Dónde estás, Nathan? Es mejor que encuentre a Chloe.",
  ["Act_E4_8B_VIP_ScriptedObjective_Max_020"] = "Nathan ha de estar escondido en su habitación después de la paliza de Warren... es tiempo de encontrar a Chloe e ir a buscarlo...",
  ["Act_E4_8B_VIP_ZenVIP_Max_010"] = "Kate está muerta... Rachel está muerta... Bienvenido al club Vortex.",
  ["Act_E4_8B_VIP_ZenVIP_Max_015"] = "Kate casi muere... Rachel está muerta... bienvenido al club Vortex.",
  ["Act_E4_8B_VIP_ZenVIP_Max_020"] = "Miren a estos pobres idiotas... les importa un carajo lo que le pase a otros.",
  ["Act_E4_8B_VIP_ZenVIP_Max_030"] = "Si ese tornado azotara en este momento, simplemente me sentaría aquí a observar un rato.",
  ["Act_E4_8B_VIP_ZenVIP_Max_040"] = "Debo de asegurarme de que Chloe no haga su propia masacre...",
  ["Act_E4_8B_VIP_ZenVIP_Max_050"] = "Detesto sentirme así... sombría y enojada...",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_001"] = "Hola, Stella.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_003"] = "No, Stella, gracias. ¿Has visto a Nathan?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_005"] = "¿Por qué te da miedo Nathan? Es decir, te entiendo, pero dime el motivo.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_007"] = "¿Qué chica?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_009"] = "¿Entonces por qué trabajas en la fiesta del club Vortex? No creí que quisieras entrar al club.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_011"] = "¿Quién te contrató?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_013"] = "¿Has notado algo raro en el club Vortex esta noche?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_015"] = "Sí, lo eres Stella. Eres inteligente, honesta y lo das todo por Blackwell. Espero que todo mejore para ti al final.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Max_017"] = "En realidad, no. Debo encontrar a Nathan.|No te le acerques mucho si lo ves.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_002"] = "Hola, Max, bienvenida al \"Fin del mundo\". ¿Quieres dejar algo aquí?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_004"] = "Gracias a Dios, no. Nathan me da miedo... Pero una chica pasó preguntando por él.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_006"] = "Es un abusivo y además golpeó a Warren... ¿Has visto sus ojos? Vidriosos y llenos de ira. No me agrada nada.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_008"] = "Cabello azul, punketa... La que pone los carteles de Rachel.|Ojalá pudiera ayudarte más, pero tengo que quedarme aquí.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_010"] = "Al carajo con eso. Estoy aquí por el trabajo.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_012"] = "El Sr. Jefferson me comentó de este trabajo porque sabe que no tengo mucho dinero,|aún con mi trabajo y mi beca.|No soy lo suficientemente genial para esta escuela.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_014"] = "Sí, noté que a nadie le importa Kate Marsh. Me alegra trabajar, pero deberían haber cancelado la fiesta. Supongo que no soy buena onda.",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_016"] = "Oh, Max... gracias, aprecio tus palabras.|Oye, traes una cara muy... intensa... ¿estás bien?",
  ["Cue_E4_8B_Cloakroom_CHStella_Phase01_Stella_019"] = "Claro que no, solo vine a trabajar. Te aviso si lo veo. Suerte, Max.",
  ["Cue_E4_8B_Cloakroom_CHStella_Quickphase_Stella_001"] = "Aún no veo a Nathan, pero prometo avisarte.",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_Stella_010"] = "Odio tocar todas esta ropa...",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_Stella_030"] = "Además, algunos de los del club Vortex siempre me tratan mal.",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_TeenFemale04_020"] = "Es algo desagradable.",
  ["Cue_E4_8B_Cloakroom_Stella01_IGE_TeenFemale04_040"] = "Para eso están aquí, Stella.",
  ["Cue_E4_8B_Cloakroom_Stella02_IGE_Stella_010"] = "¡Hola! ¿Te ayudo con tu abrigo o necesitas algo?",
  ["Cue_E4_8B_Cloakroom_Stella02_IGE_Stella_020"] = "No, no he visto ninguna tablet con fotos de gatos...",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_001"] = "¿Qué hay, \"Máxima velocidad\"? Justo a tiempo para salvar la fiesta... ¿Quieres marearte un poco?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_003"] = "¿A dónde más podría ir un jueves por la noche en Arcadia Bay? Además, Dana está aquí... pero no conmigo... Así que sí, esta fiesta apesta.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_005"] = "Oh, debe estar haciendo pendejadas en la sala VIP de ese tal club \"Putex\". Detesto a esos snobs hijos de puta... En especial a Nathan. Ese güey es una bomba de tiempo a punto de estallar.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_008"] = "Traté de aparentar que no me importaba, pero entonces los vi juntos y vine aquí a llorar como una niñita.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_011"] = "Maldición, esta noche estuve pensando en Rachel y Chloe... si ambas se presentaran juntas en este momento, todas las estupideces terminarían. Rachel siempre pudo aplacar a Victoria.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_013"] = "Max, sé que estoy loco, pero tu cara se ve súper intensa.|Y tu voz... suena diferente. ¿Estás bien? ¿No quieres un toque?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Justin_015"] = "¡Tienes toda la razón, Maximus! Solo me estoy torturando aquí. Además, estoy muy borracho... es hora de tomar mi tabla y sonreír.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_002"] = "Ya te ves bastante mareado, Justin. Y no te ves feliz. ¿Por qué viniste?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_004"] = "Hablando de... ¿Has visto a Nathan?",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_006"] = "Tal vez tengas razón. Mantente lejos de él ¿sí? y dile lo mismo a los demás.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_007"] = "Evidentemente no te agrada que Trevor y Dana salgan juntos.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_009"] = "No, más bien es como alguien que está sufriendo. Lo lamento, Justin. Pero tú eres un chico genial y considerado. Estoy segura de que encontrarás a alguien tan genial, pero sin dramas.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_010"] = "Rachel Amber tampoco va a venir.",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_012"] = "Bravo por Rachel. Desearía poder haber visto eso...",
  ["Cue_E4_8B_MenToilets_CHJustin_Phase01_Max_014"] = "Oh, no, Justin, estoy bien. Debo irme, tal vez deberías intentar relajarte en algún otro lugar.",
  ["Cue_E4_8B_MenToilets_CHJustin_Quickphase_Justin_001"] = "No, de verdad, yo me largo... cuando todo esté menos borroso...",
  ["Cue_E4_8B_Pool_AlyssaFall_IGE_Alyssa_010"] = "¡Por Dios! ¡Denle un descanso a la pobre chica!",
  ["Cue_E4_8B_Pool_AlyssaFall_IGE_TeenBoy01_007"] = "o ganar...",
  ["Cue_E4_8B_Pool_AlyssaFall_IGE_TeenBoy02_006"] = "Wow... ¡Epic Fail!",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_020"] = "Estoy en eso.",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_030"] = "¿De nuevo?",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_040"] = "¡Vaya!",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_050"] = "¡Pero claro! Mi ángel guardián aparece cada vez para protegerme de este mundo cruel. ¡Gracias de nuevo, Mística Max!",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_060"] = "Sin duda, llegaste para protegerme de otro momento humillante. Gracias, Max.",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Alyssa_070"] = "Eso estuvo muy cerca. ¡Gracias Max! Ojalá hubieras estado cerca al principio de la semana...",
  ["Cue_E4_8B_Pool_AlyssaWarn_RTC_Max_010"] = "¡Alyssa, ten cuidado!",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Alyssa_002"] = "Sí, me acaban de pegar con uno de esos tubos salvavidas y me caí a la alberca. Estoy bien. Es la primera vez que no me adviertes, Max.",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Alyssa_003"] = "Sí, justamente me pegaron con uno de esos tubos salvavidas y caí a la alberca. Estoy muy bien, supongo que no puedo contar con que me adviertas como la última vez, Max.",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Alyssa_004"] = "Sí, me acaban de pegar con uno de esos tubos salvavidas y me caí a la alberca. Soy la \"reina del mundo\"... y siempre estás cerca cuando soy el blanco de algo. Tal vez puedas advertirme uno de estos días, Max.",
  ["Cue_E4_8B_Pool_CHAlyssa_NotWarned_Max_001"] = "Oh, carajo, ¡Alyssa! ¿estás bien?",
  ["Cue_E4_8B_Pool_CHAlyssa_Quickphase_Alyssa_001"] = "Gracias otra vez, Max, ahora puedo disfrutar de este asco de fiesta.",
  ["Cue_E4_8B_Pool_CHAlyssa_Quickphase_Alyssa_002"] = "Ahora no, Max. Estoy empapada, gracias a estos idiotas y su estúpido tubo salvavidas.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_001"] = "Qué sorpresa verte aquí.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_003"] = "Me asustaste por un momento, estaba lista para agacharme. No creí que volverías.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_005"] = "Lo sé... solo vine porque Warren iba a venir y necesitaba a algo para distraerme. Esta fiesta sin duda es un homenaje a Kate.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_007"] = "Me da mucho gusto que esté dibujando de nuevo. Se ve mucho mejor y su mamá por fin la está apoyando... Kate realmente se lo merece.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_009"] = "Ve lo rápido que todos se olvidaron de Kate. Ya encontrarán más drama en Blackwell y se olvidarán del video... así funciona.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_011"] = "Por tu cara se nota que sabes algo muy grave. No necesitas decírmelo, pero avísame si te puedo ayudar de alguna forma, como tú me ayudaste a mí.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_019"] = "Realmente no lo sé, pero seguramente en la sección VIP... como si se tratara de un club neoyorquino.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_021"] = "¿Por qué? Tengo a Max Caulfield de mi lado. Buena suerte.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_023"] = "Lo sé. Esta semana fue tan horrible que al final solo quería estar rodeada de un montón de personas deseando pasar un buen rato... aunque odio a la mayoría de ellos.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_025"] = "Ella debe saber que la golpearía directo en la cara. Quizá debería hacerlo, para que el club Vortex lo recuerde en el futuro...",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_027"] = "No la conocí, pero espero que esté sana y salva.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_029"] = "Te ves algo tensa, Max. Deberías descansar. Has tenido una semana muy difícil junto con Kate, además de que has cuidado mi trasero todo el tiempo.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_031"] = "Eres como un superhéroe. Siempre eliges ayudarme. Eso me recuerda al único poema que me sé, de Robert Frost.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_033"] = "Bueno, pero te advierto que esto es como karaoke de poesía, así que no te apenes: \"Debo estar diciendo esto con un suspiro. De aquí a la eternidad: Dos caminos se bifurcaban en un bosque y yo... Yo tomé el menos transitado. Y eso hizo toda la diferencia\".",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_035"] = "Gracias por no avergonzarte. Y gracias de nuevo por cuidarme. Blackwell sería un lugar mucho mejor si todos hiciéramos eso por los demás... pero sin duda eres un gran comienzo, Max.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Alyssa_037"] = "Eso sonó mal ¿sabes? Pero te lo prometo. Ten cuidado, Max.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_002"] = "Sí, ya regresé.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_004"] = "Me sorprende ver a todos aquí, tomando en cuenta que Kate casi se mata frente a todos.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_006"] = "Me sorprende que Blackwell organice una fiesta después de lo de Kate. Supongo que la gente está feliz de que esté \"bien\"|y de que pueden salir de fiesta otra vez...",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_008"] = "Vi que quitaron el video, así que espero que nadie lo suba de nuevo... ¿o es inocente de mi parte esperar eso?",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_010"] = "Kate merece venganza. Tenemos que asegurarnos de que esto no le pase a nadie más en Blackwell...",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_012"] = "Alyssa, necesito encontrar a Nathan, ¿lo has visto por aquí?",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_020"] = "Muchas gracias, Alyssa. Cuídate.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_022"] = "Quién lo hubiera imaginado... estoy en mi primera y única fiesta del club Vortex.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_024"] = "Parece que Victoria no te molesta como a mí... o a Kate.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_026"] = "Creo que Rachel Amber estaría de acuerdo.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_028"] = "Sí... En fin. Hablamos después, Alyssa.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_030"] = "Me alegro mucho de haberte podido prevenir de todos esos ataques furtivos.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_032"] = "Creo que me vendría bien un poco de poesía en este momento.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_034"] = "Eso fue hermoso, Alyssa. Era exactamente lo que necesitaba escuchar en este momento.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_036"] = "Ojalá tuviera el tiempo para escucharlo... prométeme que me lo recitarás... la próxima vez que nos veamos.",
  ["Cue_E4_8B_Pool_CHAlyssa_Warned_Max_038"] = "Sin duda. Lo siento Alyssa, pero debo irme ya. Hablamos después.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_002"] = "Max, no esperaba verte en una fiesta del club Vortex.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_004"] = "No, no lo he visto, y tampoco lo estoy buscando. Así que no creo que eso pase esta noche. Odio a ese maldito y a su club...",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_006"] = "No tengo tarea. Aburrimiento. Esperar.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_008"] = "Bien, entonces ya no tengo que fingir que me importa.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_010"] = "Lo haré. Él ya se fue, pero más tarde planearemos nuestra cita al autocinema. Warren quiere ir a comer primero, así que será divertido ¿O te molestaría de alguna forma, Max?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_013"] = "Gracias, Max. Aunque me siento egoísta hablando sobre un chico, tomando en cuenta lo de Kate y la crisis ambiental de Arcadia Bay...",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_014"] = "¿Por qué? Tú eres el que sale con él.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_016"] = "Lo sé... Me pongo de mal humor cuando las cosas no salen como quiero. Yo soy egoísta mientras tú corres al techo a ayudar a salvar a tu amiga.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_017"] = "No, estuve hablando con Daniel... Me invitó al Museo de Arte de Portland este fin de semana...",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_019"] = "Prefiero la ciencia, pero ¿qué clase de fan egoísta se perdería una exhibición de Miyazaki?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_020"] = "No, pero más tarde planearemos nuestra cita al autocinema. Estaba hablando con Daniel sobre un viaje al Museo de Arte de Portland de la próxima semana.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_022"] = "Prefiero la ciencia, pero ¿qué clase de fan egoísta se perdería una exhibición de Miyazaki?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_024"] = "Pareces muy sabia y... casi invencible esta semana. Creo que la nieve y el eclipse te dieron superpoderes. Deberías ver si puedes volar.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_026"] = "Max, si hubiera visto una luna doble, asumiría que en verdad es el fin del mundo.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_028"] = "No lo sé... sería totalmente genial pelear contra supervillanos por todo Arcadia Bay.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Brooke_030"] = "Y también nosotras, Max. Deberíamos juntarnos para volar el drone la próxima semana.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_001"] = "Hola, Brooke.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_003"] = "Yo tampoco lo esperaba, pero realmente necesito encontrar a Nathan, ¿lo has...?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_005"] = "¿Entonces, por qué estás aquí?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_007"] = "No eres la única que siente eso. Es probable que esta fiesta sea el \"Fin del club Vortex\"...",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_009"] = "¿Has visto a Warren esta noche?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_011"] = "Está muy bien, Brooke. Me da mucho gusto por ti. Y por Warren. Me gusta verte feliz en lugar de siempre estar esperando.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_015"] = "Brooke, ya basta. Lamento que Warren me haya invitado al cine, pero no tienes por qué ser hostil conmigo. Me gusta pensar que somos amigas.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_018"] = "Oh, qué lindo. Apuesto a que Daniel será un gran guía de museo...",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_021"] = "Wow, eso es genial. Él necesita una amiga. Apuesto a que Daniel será un gran guía de museo...",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_023"] = "No eres egoísta, Brooke. Solo intentas vivir tu vida sin toda esta mierda, como todos aquí...",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_025"] = "Solo lo intentaré con tu drone. Por cierto ¿de casualidad viste la luna doble hace rato?",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_027"] = "No creo que tener superpoderes hiciera mi vida más fácil... con un gran poder viene una gran pila de mierda.",
  ["Cue_E4_8B_Pool_CHBrooke_Phase01_Max_029"] = "Bueno, Brooke, la noche aún es joven.",
  ["Cue_E4_8B_Pool_CHBrooke_Quickphase_Brooke_001"] = "Hagamos planes con más calma después ¿te parece?",
  ["Cue_E4_8B_Pool_CHBrooke_Quickphase_Brooke_002"] = "Lo siento, Max, ahora no puedo hablar, estoy esperando a un chico...",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_002"] = "¡Oh, sí! ¡Max hace su entrada! ¡Solo vine a esta fiesta por ti!",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_004"] = "No, he estado aquí con Brooke desde que llegué.|¿Estás bien, Max? Te ves muy... seria.",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_006"] = "Parece que estás en una misión secreta...",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_008"] = "Parece que no tiene fin, ¿verdad?",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_010"] = "Bueno, si tienes ganas de salir con Brooke y conmigo, aquí estamos para ti.",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_011"] = "Vaya, Max. Necesitas tomarte un descanso de Blackwell. Voy a llevar a Brooke a un espectáculo de Miyazaki en Portland. ¿Quieres venir? Cuantos más seamos, mejor.",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Daniel_013"] = "Bueno, Max, celebraré un día de estos en un museo. Bye.",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_001"] = "Hola, Daniel.",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_003"] = "Me alegra mucho verte aquí. Por cierto ¿has visto a Nathan Prescott esta noche?",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_005"] = "Lo sé, no estoy en modo fiesta, digamos.",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_007"] = "No es nada. Es solo un remanente de todo el drama en Blackwell...",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_009"] = "Aquí es donde termina... por el bien de Rachel.",
  ["Cue_E4_8B_Pool_CHDaniel_Phase01_Max_012"] = "Gracias Daniel. Debo continuar con lo que estaba haciendo. Espero que tú sigas con lo tuyo y te conviertas en un gran artista.",
  ["Cue_E4_8B_Pool_CHDaniel_Quickphase_Daniel_001"] = "Debo ir al \"bathroom\", ¡hablamos luego, Max!",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_002"] = "¿Sabes, Max? Eres la única persona a la que no me molesta ver en este momento...",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_004"] = "Prácticamente estoy evitando a todos esta noche. Y... ¿por qué andas buscando a Nathan?",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_006"] = "Como lo que pasó con Kate...",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_008"] = "¿De verdad? Te ves súper intensa. ¿Nathan te está molestando?",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_009"] = "Hey, espera... vi a Nathan hoy con la cara hecha pedazos. Estuve soñando que alguien por fin le daba una paliza...",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_011"] = "He soñado que un día alguien por fin le da su merecido.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_013"] = "¡Genial! ¡Bien por nuestro hermano Warren! Solo queda echar a los malditos vampiros Prescott de la ciudad.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_015"] = "Yo le llamo el \"culto Vortex\". Ve toda esta mierda... ¿código de vestimenta? ¿sección VIP? Pura mierda elitista.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_017"] = "Lo vi una vez en un juego de los Pies Grandes... maldito hijo de puta. Entiendo mejor a Nathan.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Luke_019"] = "No, gracias. Por ayudar a Kate. Y por seguir siendo quien eres. Paz.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_001"] = "Luke, por poco no te veo.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_003"] = "Estaba buscando a Nathan...",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_005"] = "Tan solo quiero asegurarme de que él no vaya a... hacer algo esta noche.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_007"] = "No es gran cosa.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_010"] = "¿Sabes, Luke? A veces los sueños se hacen realidad. Warren le dio una paliza épica.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_012"] = "¿Sabes, Luke? A veces los sueños se hacen realidad. Hoy vi a Warren dándole una paliza épica a Nathan.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_014"] = "Eso será algo complicado de lograr considerando que los Prescott son dueños de la ciudad... y del club Vortex.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_016"] = "Creo que Sean Prescott quiere echarnos a todos de la ciudad... o meternos a Pan Estates.",
  ["Cue_E4_8B_Pool_CHLuke_Phase01_Max_018"] = "Amén, hermano Luke. Bueno, debo irme, gracias por hablar conmigo...",
  ["Cue_E4_8B_Pool_CHLuke_Quickphase_Luke_001"] = "Aún trato de pasar desapercibido, Max.",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_010"] = "¡Tú no mereces ganar!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_020"] = "¡Buuuu, Victoria!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_030"] = "Victoria Boloña!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_Stella_040"] = "¡Apestas, Victoria!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_TeenMale01_010"] = "¡Buuuu! ¿Vamos, qué carajo? ¡Conéctalo de nuevo!",
  ["Cue_E4_8B_SwimPool_BooingVictoria_TeenMale01_020"] = "¡Vamos!",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Brooke_010"] = "Es muy agradable platicar con otro fanático del anime...",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Brooke_030"] = "Es verdad. Eso es lo que me gusta de Warren...",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Brooke_050"] = "Sí, y yo también.",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Daniel_020"] = "Oh sí, soy un geek multiusos.",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Daniel_040"] = "Por lo visto está más interesado en la ciencia ¿verdad?",
  ["Cue_E4_8B_SwimPool_BrookeDaniel_IGE_Daniel_060"] = "Me gusta la ciencia ficción...",
  ["Cue_E4_8B_SwimPool_Brooke_IGE_Brooke_010"] = "Esta fiesta necesita un drone.",
  ["Cue_E4_8B_SwimPool_Brooke_IGE_Brooke_020"] = "¿Y exactamente cuál es el punto de esta fiesta?",
  ["Cue_E4_8B_SwimPool_DJSpeakerStops_IGE_DJ_010"] = "Hey, hey... ¿qué carajos está pasando?",
  ["Cue_E4_8B_SwimPool_DJSpeakerStops_IGE_DJ_020"] = "¡OK, OK! ¡Hey, hey! ¿Quién apagó la música?",
  ["Cue_E4_8B_SwimPool_DJSpeakerStops_IGE_DJ_030"] = "¡Hey, tú! ¡Sí, tú! ¿Qué demonios haces ahí?",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Dana_010"] = "¡Bailas peor que mi papá!",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Dana_030"] = "Wow, eso sí que es bueno. ¡Muévete así!",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Trevor_020"] = "Sí, pero ¿puede hacer esto?",
  ["Cue_E4_8B_SwimPool_DanaTrevor_IGE_Trevor_040"] = "¡Trevor parte 2: Boogaloo eléctrico!",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_010"] = "No importa. Como siempre, fue un placer platicar contigo, Victoria.",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_030"] = "Por lo menos dime dónde está Nathan.",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_050"] = "El director Wells quiere vernos el lunes, no es gran cosa.",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Max_070"] = "Au revoir...",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Victoria_020"] = "Vete al carajo, Max. Solo estás celosa porque yo hago lo que tú no puedes. Yo publico mis fotografías mientras tú te escondes detrás de tus patéticas retro-selfies.",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Victoria_040"] = "Ajá... y ¿por qué quieres saberlo?",
  ["Cue_E4_8B_SwimPool_DontWarnVictoria_Victoria_060"] = "¿Entonces por qué me preguntas? No lo he visto esta noche. Bye.",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenBoy_010"] = "¡Conecta esa mierda de nuevo! ¡Queremos el bajo, el jodido bajo, quiero escucharlo! ¡Ah, esto son estupideces, vamos! ¡Venimos a una fiesta\" ¡Venga ese ritmo pesado!",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_010"] = "¡Oh, por Dios!",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_020"] = "¿Dónde está el alcohol?",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_030"] = "¡¡Me encanta esta canción!!",
  ["Cue_E4_8B_SwimPool_EnjoyingParty_TeenGirl_040"] = "¡Marcia! ¡Marcia!",
  ["Cue_E4_8B_SwimPool_GirlTalkMax_IGE_TeenGirl03_010"] = "Me impresiona verte por aquí esta noche, Max... pero mereces disfrutar de una fiesta.",
  ["Cue_E4_8B_SwimPool_Hayden_IGE_Hayden_010"] = "¿Soy yo o todos aquí están borrosos?",
  ["Cue_E4_8B_SwimPool_Hayden_IGE_Hayden_020"] = "¿Soy yo, o todos están distorsionados aquí?",
  ["Cue_E4_8B_SwimPool_Hayden_IGE_Hayden_030"] = "Estoy bien pedo. Pero ustedes también.",
  ["Cue_E4_8B_SwimPool_JeffArrive_Chloe_100"] = "Larguémonos de aquí, Max.",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_010"] = "Así que sí viniste, Max.",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_030"] = "Mmmm... ¿Las dos están bien? Parece que estuvieran en una misión.",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_050"] = "Ajá... no sabía que fueran amigos. No lo he visto desde la tarde... se veía bastante molesto. Creo que sigue bastante molesto por todo lo que pasó con Kate.",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_070"] = "Hablaremos después, Max. Debo anunciar al ganador del concurso. Ojalá hubieras entrado. Deberías hacerte de un currículo y un portafolio, pero sé que lo harás eventualmente.",
  ["Cue_E4_8B_SwimPool_JeffArrive_Jefferson_090"] = "De acuerdo. Lo siento, debo irme...",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_020"] = "Oh, hola, Sr. Jefferson...",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_040"] = "Ah, solo estaba buscando a Nathan...",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_060"] = "Sí, tiene sentido.",
  ["Cue_E4_8B_SwimPool_JeffArrive_Max_080"] = "Gracias, eso espero.",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Chloe_020"] = "¿A quién chingados le importa? Rachel sigue muerta, y quiero el maldito cuello de Nathan... ¡Ahora!",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Courtney_010"] = "¡Genial, Sr. Jefferson! ¡Está buenísimo!",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Dana_010"] = "¡Aquí! ¡Sr. Jefferson! ¡¡Sexy!!",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Max_010"] = "Victoria ganó. Qué sorpresa. No puedo creer que chantajeara a Jefferson...|Bueno, sí... Sí puedo.",
  ["Cue_E4_8B_SwimPool_JeffSpeechReaction1_Max_030"] = "Igual yo. Vamos a revisar en los dormitorios.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_010"] = "Muy bien, tranquilos todos.|Gracias, gracias... Se los agradezco.|No me quiero entrometer en la fiesta, pero es hora de anunciar al ganador del concurso Héroes Cotidianos.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_030"] = "Antes de hacer el anuncio, quiero agradecer a todos los que metieron una fotografía al concurso... y a todos los que consideraron entrar.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_040"] = "Este es el paso más importante para un artista. Compartir su trabajo con el mundo. Todos ustedes representan a la Academia Blackwell y su legado.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_050"] = "En lo que a mí respecta, ¡todos ustedes son \"héroes cotidianos\"!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_060"] = "El sobre, por favor...",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_070"] = "Y el ganador es...",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_080"] = "Vaya, qué gran sorpresa... ¡Victoria Chase!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_140"] = "Gracias, Victoria. Y hablando de Kate...",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_150"] = "Como ustedes saben, esta fiesta casi se cancela por lo que pasó esta semana.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_160"] = "Pero la administración decidió sabiamente que se merecían esta reunión... además de que el club Vortex ha hecho mucho por Blackwell.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_170"] = "Pero quiero que estén conscientes de que todo lo que hagan esta noche está siendo vigilado minuciosamente, así que deben de comportarse como adultos responsables.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Jefferson_180"] = "Ahora que el viejo terminó de hablar, disfruten de la fiesta. Esta noche de octubre es perfecta para una loca fiesta de alberca. ¡Se acabo la clase!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Taylor_020"] = "¡Eres un bombón!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_090"] = "¡Oh, por Dios!",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_100"] = "Muchas gracias, Sr. Jefferson. Fueron sus increíbles fotografías las que me trajeron a Blackwell y espero poder hacerle honor a su nombre... y a su fama. También quiero agradecer a todos los estudiantes por su dedicación.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_110"] = "Quisiera dedicar este premio a la memoria de Kate Marsh... Ella fue la verdadera \"heroína cotidiana\" de Blackwell...",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_120"] = "Quisiera dedicar este premio a Kate Marsh... ella es parte de los \"héroes cotidianos\" de Blackwell. Tengo muchas ganas de que regrese.",
  ["Cue_E4_8B_SwimPool_JeffSpeech_Victoria_130"] = "Gracias.",
  ["Cue_E4_8B_SwimPool_JustinDrunk_IGE_Justin_010"] = "Hey, Max. ¿Qué andas haciendo por aquí?",
  ["Cue_E4_8B_SwimPool_JustinDrunk_IGE_Justin_020"] = "Si vomito en este momento, podré seguir bebiendo más después...",
  ["Cue_E4_8B_SwimPool_Luke_IGE_Luke_010"] = "Pagaría por ver a Warren rompiéndole la madre a Nathan...",
  ["Cue_E4_8B_SwimPool_Luke_IGE_Luke_020"] = "Realmente deseo que alguien le parta la madre a Nathan...",
  ["Cue_E4_8B_SwimPool_MeetVictoria_Max_020"] = "Lo siento, estoy en la lista de invitados.",
  ["Cue_E4_8B_SwimPool_MeetVictoria_Victoria_010"] = "Lo siento, Max. Solo miembros del club Vortex.",
  ["Cue_E4_8B_SwimPool_MeetVictoria_Victoria_030"] = "Yo me encargo de sacarte.",
  ["Cue_E4_8B_SwimPool_NoNameSpeakerStops_IGE_TeenBoy01_010"] = "¿Quién es ese?",
  ["Cue_E4_8B_SwimPool_Party01_IGE_TeenBoy01_050"] = "Viejo... ¡Estoy muy borracho!",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenBoy03_010"] = "Esa sección VIP es una basura...",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenBoy03_030"] = "¿Quién paga por toda esta mierda?",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenBoy03_050"] = "Hermano, ¡Nathan Prescott está completamente drogado!",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenFemale01_020"] = "Escuché que no admitirían a Kate Marsh en el club Vortex...",
  ["Cue_E4_8B_SwimPool_Party02_IGE_TeenFemale01_040"] = "Me siento egoísta por salir de fiesta después de lo de esta semana...",
  ["Cue_E4_8B_SwimPool_Party03_IGE_TeenGirl01_030"] = "Justin dijo que alguien vio dos lunas allá afuera... pero es Justin.",
  ["Cue_E4_8B_SwimPool_Party03_IGE_TeenGirl02_020"] = "Se siente como si estuviera por ocurrir algo terrible...",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale01_010"] = "Hola, ¿podrías terminar y jalarle de una vez?",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale01_030"] = "¿Tal vez no eres la única persona que necesita vomitar?",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale02_020"] = "Sí, ¡has estado vomitando como por una hora!",
  ["Cue_E4_8B_SwimPool_PartyDrunk01_IGE_TeenFemale02_040"] = "Si no terminas pronto, vamos a entrar, amiga.",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenBoy03_010"] = "¿Qué carajo fue eso?",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenBoy03_030"] = "No voy a salir jamás de este baño...",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenMale01_020"] = "Bebida energizante y Everclear... oh por Dios... mi estómago...",
  ["Cue_E4_8B_SwimPool_PartyDrunk04_IGE_TeenMale01_040"] = "Esta es mi última fiesta del club Vortex... oh no... no de nuevo...",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenBoy01_010"] = "¡Oh, vamos!",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenBoy02_020"] = "¡Esta es pura chingadera!",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenFemale02_050"] = "¡Es el fin de la música!",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenFemale05_080"] = "¡Oh, por Dios! ¡DJ Doom se me quedó viendo!",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenGirl03_030"] = "¿Qué está pasando?",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenMale01_070"] = "Esta fiesta es tan patética...",
  ["Cue_E4_8B_SwimPool_PartyStop_IGE_TeenMale04_100"] = "¿DJ, qué carajo?",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Chloe_020"] = "Bueno, es un hecho que no está arriba o en los casilleros.",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Chloe_040"] = "Larguémonos entonces. Nathan no puede seguir escondiéndose.",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Max_010"] = "Ahí estás.|Chloe, Nathan no está aquí. Nadie lo ha visto esta noche.",
  ["Cue_E4_8B_SwimPool_SpeakChloe_Max_030"] = "Maldición, tal vez se está escondiendo en su dormitorio.",
  ["Cue_E4_8B_SwimPool_SpeakStella_Stella_010"] = "Hola, Max, bienvenida al \"Fin del mundo\". ¿Quieres dejar algo aquí?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_020"] = "¡Max! ¡Nuestra estrella invitada llega tarde como una celebridad! ¡Dile \"Bonsoir\" al \"Fin del mundo\"! Aunque te escapaste de que te arreglara para la fiesta, tienes acceso a la sala VIP del club Vortex.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_040"] = "Tarada, acaba de cometer su último error. La pobre se siente Victoria. Para nada. ¡Ven, hagamos una entrada VIP oficial para Max Factor! ¿Sí lo entendiste...?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_050"] = "Oye, Sarah, ¿sabías que yo personalmente puse el nombre de Max en la lista? ¿Y tú simplemente decides prohibirle la entrada mientras yo me tomo un descanso? Tú no estás a cargo aquí.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Courtney_070"] = "Oh, por Dios, hasta aquí llegaste. Quedas fuera de la lista... permanentemente. Bienvenida al club Vortex.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Max_010"] = "Hola, Courtney. ¿Cómo estás?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_Max_030"] = "Es mejor que le digas eso a tu ayudante que no me deja pasar.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList01_VIPKeeper_060"] = "No, espera, yo... yo solo...",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_020"] = "¿Qué hace Max Caulfield en una fiesta del club Vortex?|De verdad que ha de ser el fin del mundo... ¿sí me entiendes? No, en serio, ¿qué necesitas?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_040"] = "¿Tú en la lista? Eso es bastante... improbable, pero vamos a revisar. Sígueme.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_050"] = "Oye, Sarah, nuestra amiguita Max dice que está en la lista. Solo por reírnos de ella, vamos si es verdad.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_060"] = "De ningún modo...",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Courtney_080"] = "Oh. Por. Dios. ¿En serio me crees tan estúpida? ¡Esa ni siquiera es mi letra y yo estoy a cargo de la lista! Victoria tiene razón, ¡eres un bicho raro! Bueno, una vez máso, esto es lo más cerca que llegaste del club Vortex. Te lo aseguro. Sí, ya te puedes largar, Max. Se acabó la fiesta.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Max_010"] = "Hola, Courtney. ¿Cómo estás?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Max_030"] = "No tenía ganas de estar sola esta noche después de todo lo que pasó en la semana e incluso estoy en la lista de invitados. Pero Zuul, el Guardián de la Puerta, no me deja pasar.",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList02_Max_070"] = "Oh sí. Ese es mi nombre justo ahí...",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Courtney_020"] = "¿Qué hace Max Caulfield en una fiesta del club Vortex?|De verdad que ha de ser el fin del mundo... ¿sí me entiendes? No, en serio, ¿qué necesitas?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Courtney_040"] = "Sí, es muy agradable, si eres parte del club Vortex, cosa que no eres y jamás serás. Ahora, si me disculpas...",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Max_010"] = "Hola, Courtney. ¿Cómo estás?",
  ["Cue_E4_8B_SwimPool_VIPCourtneyList03_Max_030"] = "No tenía ganas de estar sola esta noche después de todo lo que pasó esta semana... y creí que sería buena idea pasar un rato en la sección VIP.",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_Bouncer_010"] = "Lo siento, tu nombre no está en la lista.",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_Bouncer_030"] = "Entonces seguro ella lo borró después.",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_Bouncer_050"] = "No, porque tu nombre no está en la lista, idiota.",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_TeenBoy01_020"] = "Oh sí, ahí está. Vi a Victoria escribirlo.",
  ["Cue_E4_8B_SwimPool_VIPDenied_IGE_TeenBoy01_040"] = "¡Qué tontería! ¿Acaso sabes quien soy yo?",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_030"] = "Lo siento, pero voy a entrar.",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_050"] = "Lo siento, pero estoy en la lista ¿de acuerdo?",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_070"] = "Oye, escúchame...",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_090"] = "No me importa ser o no miembro. Solo necesito hablar con Nathan...",
  ["Cue_E4_8B_SwimPool_VIPEntrance_Max_110"] = "Oye, escúchame...",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_040"] = "Lo siento, esta es la sección VIP. Solo para miembros, ¿de acuerdo?",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_060"] = "Yo lo que sé es que Max Caulfield no está en ninguna lista del club Vortex. Buen intento.",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_080"] = "No, tú escúchame. Se supone que Courtney se encarga de la entrada a la zona VIP, no yo. Así que lárgate.",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_100"] = "Victoria me dijo específicamente que no te dejara entrar. Buen intento. Lástima que no eres miembro del club.",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_120"] = "No, tú escúchame. Se supone que Courtney se encarga de la entrada a la zona VIP, no yo. Así que lárgate.",
  ["Cue_E4_8B_SwimPool_VIPEntrance_VIPKeeper_130"] = "Por Dios, ¿estás mal de la cabeza? ¡No puedes entrar!",
  ["Cue_E4_8B_SwimPool_VIPListYES_Hayden_060"] = "¡Hey, SuperMax! ¡Ven con nosotros! ¡Necesitamos a nuestra heroína!",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Logan_030"] = "Oh si, ¡eso sería retorcido!",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Logan_060"] = "Oh, ya entiendo. Muy divertido ¿no?",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Taylor_020"] = "Victoria, tu foto definitivamente tiene que ganar.",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Taylor_050"] = "Intento que no...",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Victoria_010"] = "Creo que mi foto es bastante buena, pero ya veremos...",
  ["Cue_E4_8B_SwimPool_VictoriaTaylorLogan_IGE_Victoria_040"] = "¿Eh? ¿Escuchaste algo?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_010"] = "Victoria, escúchame bien. Tu vida está en serio peligro. Sé que Nathan es tu amigo, pero es inestable y peligroso, te lo aseguro. Drogó a Kate en la fiesta para poder llevarla a un sitio... oscuro...",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_030"] = "Eso aún no lo sé, pero fue suficiente para hacer que Kate quisiera morir... y creo que eres la siguiente.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_050"] = "Ya no son \"pequeñas crisis\". Son mortales. Mira, no me importa si me odias o no, pero tienes que creerme.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_090"] = "Solo asegúrate de mantenerte lejos de él y cerca de tus amigos esta noche ¿de acuerdo?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_110"] = "Descuida, tengo mi propia protección.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Max_130"] = "Lo haré. Gracias, Victoria.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_020"] = "¿Pero qué...? Ah, Buen intento Max. No te creo nada. ¿Por qué él haría algo así?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_040"] = "Max, esto es una locura. Digamos que Nathan es uno de mis mejores amigos. Sí, toma medicamentos muy fuertes, pero no es su culpa, su familia lo trata como a un fenómeno solo porque tiene pequeñas crisis.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_060"] = "Cuando me cayó esa pintura podrías haberte comportado como una maldita conmigo... y me lo habría merecido.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_070"] = "Max, yo no te odio... de hecho creo que eres genial... rara, pero genial, aunque no lo sepas. Tal vez estoy celosa porque a ti te vale madre lo que piensen los demás, no como yo.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_080"] = "Para serte honesta, Nathan me ha dado algo de miedo últimamente... no está aquí y no lo he visto.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_100"] = "Voy a permitirte decirme qué hacer solo por esta vez. Por suerte tengo a quién recurrir si necesito protección. Gracias por decirme esto, Max. Si lo que dices es verdad... entonces tú ten cuidado también.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_120"] = "Mmmm, envíame un mensaje si necesitas algo...",
  ["Cue_E4_8B_SwimPool_WarnVictoria_Believe_Victoria_140"] = "Au revoir.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_010"] = "Victoria, basta de esta mierda. Somos adultas, así que escúchame bien. Tu vida está en serio peligro. Sé que Nathan es tu amigo, pero es inestable y peligroso, te lo aseguro. Drogó a Kate en la fiesta para poder llevarla a un sitio... oscuro...",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_030"] = "Touché. Pero no estoy diciendo mamadas.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_050"] = "Ya no son \"pequeñas crisis\". Son mortales. Mira, no me importa si me odias o no, pero tienes que creerme.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_070"] = "¿Me puedes escuchar ahora?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_100"] = "Por favor, Victoria, no hagas esto. Especialmente después de lo que pasó con Kate... Hablo en serio.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Max_120"] = "Au revoir...",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_020"] = "Oh, por Dios... ¿Y yo soy la reina del drama aquí?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_040"] = "Lo siento, pero no, de ninguna forma. Digamos que Nathan es uno de mis mejores amigos. Sí, toma medicamentos muy fuertes, pero no es su culpa, su familia lo trata como a un fenómeno solo porque tiene pequeñas crisis.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_060"] = "No creo una sola palabra de lo que dices. Eres una maldita mentirosa: \"Ah, hola a todos, soy Max Caulfield y soy una chica tan sensible que hasta las mariposas me hacen llorar\".",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_080"] = "No, no lo hare.",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_090"] = "Tan solo estás enojada porque no metiste una foto para el concurso,|y porque el Sr. Jefferson me va a elegir a mí. Un artista de verdad se habría partido el lomo para ganar... pero a ti solo te interesan tus tontas retro-selfies. Eso es tan patético y perezoso. ¿Por qué mejor entras a un colegio comunitario?",
  ["Cue_E4_8B_SwimPool_WarnVictoria_DontBelieve_Victoria_110"] = "Ese es tu problema, Max. Esta es una fiesta. Y es el \"fin del mundo\", así que me voy a emborrachar tanto que ni tú me vas a molestar. Le avisaré a Nathan si se aparece. Bye.",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_001"] = "¡Que buena onda, Max! ¡No puedo creer que vinieras! ¿Por qué no me avisaste? ¡Pudimos habernos arreglado juntas!",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_003"] = "¡Para nada! He estado bailando con Trevor. ¡Ven y baila con nosotros! ¡Mira a Trevor intentando bailar!",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_005"] = "Creo que lo somos. Él es muy diferente a Logan. Podemos hablar incluso sobre la vida... y sabe cómo andar con cuidado.",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_007"] = "¡Genial! Sin duda esta ha sido la peor semana de toda mi vida, me hacía falta actuar como una estudiante despreocupada esta noche... por Kate ¿sabes?...",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_009"] = "Lo haré si quiero divertirme... lo siento por él. Necesita ayuda, pero no de su familia...",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_011"] = "Mmmm es millonario. Y mucho. Y un hijo de puta, según lo que dice Nathan. Los Prescott no pueden comprar una familia feliz... o un club feliz.",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_014"] = "Lo sé... Juliet escribió una historia describiéndolo como un culto, y comienzo a pensar que tiene razón... ya no es divertido.",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_016"] = "No necesito de ningún club para sentirme bien o tener amigos. Mírate... además, me gusta salir con Trevor y sus amigos patinadores. ¡Sin dramas!",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Dana_018"] = "Gracias. Como sea, el hombre no sabe bailar... ¡míralo!",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_002"] = "Como puedes notar por mi ropa, tenía prisa... Dime, Dana, ¿viste a Nathan por aquí?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_004"] = "Se ven realmente muy felices juntos...",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_006"] = "¿Cómo va el \"Fin del mundo\"?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_008"] = "Te entiendo, Dana. Pero te pido que evites a Nathan a toda costa si lo ves ¿de acuerdo?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_010"] = "¿Qué sabes sobre su padre, Sean Prescott?",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_012"] = "El club Vortex también lo está solapando.",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_015"] = "Suena como que estás lista para un cambio.",
  ["Cue_E4_8B_VIP_CHDana_Phase01_Max_017"] = "Estoy de acuerdo, Dana. Me alegra que Trevor esté contigo esta noche.",
  ["Cue_E4_8B_VIP_CHDana_Quickphase_Dana_001"] = "¡Si no vas a mover el trasero, hablaremos después de que yo lo haga! ¡Te quiero!",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_002"] = "¡Miren, en el cielo! ¡Es SuperMax, que viene a salvar esta fiesta!",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_004"] = "Wow, ¡qué sorpresa, Max! No creí que vinieras esta noche...",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_006"] = "Acabo de inhalar una hierba muy fuerte, así que apenas y puedo verte... o a este sexi par a mi lado. ¿Quieres un toque?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_008"] = "Oh, vamos... me encantaría verte pacheca. Tienes que relajarte. Tú más que nadie necesita ponerse hasta atrás... cerca de mí.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_010"] = "Yo también. Se supone que él iba a traer regalos... espero... para la fiesta... uno realmente quiere divertirse en una fiesta.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_012"] = "Supongo que tienes que ir a preguntarle a todos... o sencillamente podrías sentarte y darte un toque rápido.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_014"] = "Por Dios, vele a preguntar tú misma. Yo lo haría, pero como te dije... estoy muy aturdido.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_017"] = "¿Y él qué no paga? Los Prescott cagan dinero... ¿De qué otra forma podríamos pagar a DJ Doomsday?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_019"] = "Sí, como sea... estoy en este mundo para divertirme. Deberías intentarlo alguna vez, Max. Por fin logré que Dana y tú vinieran a una fiesta del club Vortex, pero solo te interesa sermonearme... Por Dios, gracias \"Sr. Madsen\".",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Hayden_021"] = "Creo que ese es tu trabajo, Max. Regresa conmigo cuando estés lista para divertirte...",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_001"] = "¿Qué hay de nuevo, Hayden?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_003"] = "¿Has visto a Nathan?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_005"] = "No imaginé que alguien estuviera de humor para ir de fiesta | después de que Kate Marsh se suicidara esta semana... ¿Has visto a Nathan?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_007"] = "No, gracias.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_009"] = "No, quiero encontrar a Nathan.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_011"] = "Esta semana no. Y... ¿Alguien aquí ha visto a Nathan?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_013"] = "¿Y qué me dices de Victoria?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_015"] = "Tal vez sea buena idea que te la lleves tranquila esta noche.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_016"] = "Dime Hayden, ¿Sean Prescott paga las fiestas del club Vortex?",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_018"] = "La familia Prescott te esta haciendo bailar, literalmente.",
  ["Cue_E4_8B_VIP_CHHayden_Phase01_Max_020"] = "Dime, ¿y cuánto se divirtió Kate durante la última fiesta? Escúchame, Hayden... solo cuídate de Nathan esta noche.",
  ["Cue_E4_8B_VIP_CHHayden_Quickphase_Hayden_001"] = "¿Eres tú, Max? Luces muy borrosa... Waw, estoy a medio viaje...",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_002"] = "De acuerdo, Max, ¡hablaré después de que muevas ese trasero para mí!",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_004"] = "Ni siquiera puedo hacer que Victoria o Taylor perreen... ¿y tú estás buscando pasar el rato con Nathan? ¿Por qué?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_006"] = "Entonces tienes que hablar con su papá. Tiene más dinero que Dios... y lo gasta en el club Vortex, no en los perdedores de allá con sus asientos baratos.",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_008"] = "Wow, ¡las cosas se ponen serias cuando Max llega a la pista de baile!",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_010"] = "Pregúntale a Victoria, ella siempre sabe dónde está. ¿Por qué nunca quieres verme, Max? Eres muy linda y nunca platicamos realmente...",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_012"] = "Me estás haciendo sentir realmente mal... me siento como una basura por haber dejado sola a Dana, ¿pero como puedo remediarlo?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_015"] = "En el próximo juego de los Pies Grandes, podríamos ir al campo, te podría mostrar algunos movimientos... Un touchdown...",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Logan_017"] = "Vaya, eso fue mucho más excitante que un baile... ¡Nos vemos luego, Max!",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_001"] = "Logan, ¿puedo hablar contigo un momento?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_003"] = "No, paso. ¿Has visto a Nathan?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_005"] = "Negocios.",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_007"] = "No es asunto tuyo.",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_009"] = "Logan, esto es una alberca. En otras palabras, no has visto a Nathan.",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_011"] = "Logan, eres un imbécil. Abandonaste a Dana estando embarazada, justo cuando más te necesitaba. ¿Ahora intentas seducirme? ¿Te sientes orgulloso de ti mismo?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_013"] = "Podrías comenzar por no intentar acostarte con cada chica que pasa frente a ti. El resto es tu decisión... úsala sabiamente.",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_014"] = "¿Hablar sobre qué?",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_016"] = "Logan, no me hagas lastimarte.",
  ["Cue_E4_8B_VIP_CHLogan_Phase01_Max_018"] = "Ah, y no te atrevas a tocar a Daniel DaCosta de nuevo o te arrepentirás. Nos vemos...",
  ["Cue_E4_8B_VIP_CHLogan_Quickphase_Logan_001"] = "No puedo hablar ahora, Max. Realmente me dejaste pensando...",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_003"] = "Taylor, ¿aún no has visto a Nathan?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_006"] = "¿Qué dice Victoria sobre eso?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_008"] = "¿Por qué Nathan te ha dado miedo?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_010"] = "¿Es por eso que quieres pertenecer al club Vortex?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_012"] = "Nathan drogó a Kate en la última fiesta del club Vortex, por lo que te recomiendo que evites cualquier bebida de aquí esta noche.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_014"] = "¿Por qué viniste esta noche? ¿Es tu deber como miembro?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_016"] = "Debo irme ahora, pero cuídate, Taylor. Y mándale mis saludos a tu mamá.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_018"] = "Tú sigue bailando para Victoria, Taylor. Y mantente lejos de Nathan.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Max_020"] = "Vete al carajo, Taylor. Disfruta del fin del mundo.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_001"] = "¡Vaya, Max! ¡Mírate!",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_002"] = "Oh, por Dios, Max... No puedo creerlo. ¿Qué haces aquí?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_004"] = "No... y está bien por mí. Ha actuado muy raro últimamente... me da un poco de miedo. Victoria debe saber algo...",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_005"] = "Si así fuera, no es asunto tuyo. Esta es un área VIP, así que mejor regresa con el montón.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_007"] = "Ella prefiere ignorarlo, pero Vic es cercana a Nathan. Son algo así como hermanos, o algo... ella en verdad se preocupa por él.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_009"] = "Siempre pensé que era un tipo raro. Divertido, pero... puedes darte cuenta que a él no le importa nadie.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_011"] = "No, Max. Estoy lejos de casa en una escuela increíble. Quiero aprender, hacer amigos, divertirme... Pero cuando vi a Kate en la azotea supe que había ido muy lejos...",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_013"] = "Confía en mi, no bebería mi propia agua cuando Nathan está cerca. El hombre es una farmacia andante.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_015"] = "No te vayas a reír, pero tengo la extraña sensación de que esta podría ser la última fiesta del club Vortex... Fin del mundo, ¿cierto?",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_017"] = "Oh, gracias, Max. Se está recuperando muy bien. Es un lindo gesto que preocupes por nosotras...",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_019"] = "Gracias por preocuparte, Max.",
  ["Cue_E4_8B_VIP_CHTaylor_Phase01_Taylor_021"] = "Ok, sí, supongo que lo haré. Mmmm...",
  ["Cue_E4_8B_VIP_CHTaylor_Quickphase_Taylor_001"] = "¿Está bien si hablamos después de esta canción?",
  ["Cue_E4_8B_VIP_CHTaylor_Quickphase_Taylor_002"] = "No te voy a enseñar a bailar. Vete.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_001"] = "Vete al demonio, Victoria. No tengo tiempo para estas estupideces.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_004"] = "¿Tienes idea de lo que está pasando en Blackwell?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_005"] = "Kate Marsh se suicidó enfrente de ti, de mí... ¡de todos los que están aquí!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_006"] = "Kate Marsh intentó suicidarse enfrente de ti, de mí... ¡de todos los que están aquí!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_008"] = "Ah, claro que te culpo. No ayudaste a Kate durante la fiesta. Sabías que estaba completamente perdida. Y encima le enviaste el video a todos, solo para meter el dedo más hondo en la llaga.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_010"] = "¡Debería darte vergüenza! Sabes que Kate estaba drogada, aunque lo niegues. Por eso terminó en la azotea... Y encima te aseguraste de grabarla una vez más ¿no?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_013"] = "Sí, seguro que eso reconforta a la familia de Kate... no sé cómo haces para poder dormir por las noches.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_014"] = "Culpo a Nathan de drogar a Kate, pero a nadie en esa fiesta si quiera le importó un poco que ella estuviera tan intoxicada.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_016"] = "Ten un poco de compasión, Victoria.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_020"] = "Se trata de mucho más que eso.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_021"] = "No te culpo, Victoria, pero sabías que Kate iba a la Iglesia y que no salía de fiesta. ¿Por qué enviaste ese video, entonces?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_023"] = "Más que estúpido, es cruel... mezquino. Kate jamás te hizo nada.|Y aún así tomaste ese último video de ella en la azotea.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_026"] = "Te creo, Victoria. Vi la postal que le enviaste a Kate, fue un buen gesto, pero no te entiendo...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_027"] = "Te creo, Victoria, pero no te entiendo...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_030"] = "Tus fotos apestan, Victoria. Te burlas de mis selfies, pero la mayoría de tus fotos son básicamente caras. No creo que Richard Avedon tenga nada de qué preocuparse contigo.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_032"] = "Ah, claro, anoche te vi intentando chantajear al Sr. Jefferson porque eres tan increíble. Eso fue tan patético, Victoria...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_035"] = "Como si le importaras un carajo al Sr. Jefferson. Es decir, ¿has visto su lenguaje corporal cuando intentas acercártele? Pobre de ti.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_038"] = "¿Eso es lo que intentabas decirle al Sr. Jefferson anoche?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_040"] = "Visto... y escuchado.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_042"] = "Espero que ganes limpiamente.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_044"] = "Victoria, tienes talento. No necesitas quitar a las personas de tu camino.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_046"] = "No lo es. Tan solo es arte. No necesitas entrar en su juego. Mírame, hice que suspendieran al juez del concurso.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_047"] = "No lo es. Tan solo es arte. No necesitas entrar en su juego.|El Sr. Jefferson no se comporta así y es famoso.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_050"] = "Yo tampoco, pero esa es tu decisión.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_051"] = "Sí, lo eres. Pero no deberíamos tener que elegir entre el talento y la bondad. Al menos eso espero.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_053"] = "Genial. Tengo amigos de verdad, y no necesito a una falsa a mi lado.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_055"] = "¿Quién crees que preparó la lata de pintura para que te cayera encima? No fue Samuel, tonta.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_057"] = "¿Quién crees que preparó la lata de pintura para que te cayera encima? No fue Samuel, tonta. Y destrozaste mi habitación después de eso, así que deja de quejarte.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_059"] = "Y eso habría estado mal. Tienes razón Victoria, por primera vez.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_062"] = "Supongo que nunca seré miembro del club Vortex...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_064"] = "Quizá, pero ¿quién dice que debemos ser enemigas?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_066"] = "Eso lo decidimos nosotras, Victoria.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_068"] = "No creo que eso pase... pero no por las razones que te imaginas.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_070"] = "¿Y por qué no? A ambas nos encanta el arte y la fotografía, ambas somos algo raras y pretenciosas. Si pudiéramos juntarnos sin hostilidades, nos llevaríamos bien.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_072"] = "Me hubieras dicho. Me habría gustado comparar nuestros apuntes sobre las fotos.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_076"] = "Tal vez tengas razón.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Max_078"] = "De verdad eso espero, Victoria.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_002"] = "Qué tierna, Max... y después de que me disculpé contigo el otro día...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_003"] = "Qué tierna, Max. ¿Sigues enojada porque te tomé una foto?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_007"] = "¡No es mi culpa, Max! ¡Ni siquiera te atrevas a culparme por eso!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_009"] = "Guau, ¿estás bromeando? ¡Yo no la hice tomar ese vino! Nadie la obligó a meter su lengua en la boca de todos. Yo la vi, Max.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_011"] = "Borré ese video de mi teléfono, Max. No sabía qué hacer, ¿sí? Realmente lo siento.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_012"] = "Borré ese video de mi teléfono, Max.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_015"] = "Es una maldita fiesta, ¡todos están borrachos! ¿Qué demonios quieres de mí?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_017"] = "Tú eres a quien suspendieron, Max. ¡Y yo soy la única a quien le importa lo que le ocurre a Nathan! Por lo visto no soy la única niña problema aquí.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_018"] = "Yo soy la única a quien le importa lo que le ocurre a Nathan... No soy la única niña problema en Blackwell.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_019"] = "Bueno, conseguiste que suspendieran a Nathan de Blackwell, así que deberías estar feliz. Yo soy la única a quien le importa lo que le ocurre a Nathan.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_022"] = "Oh, por Dios... te juro que ni siquiera pensaba hacerlo. Pero entonces bebimos vino e hicimos estupideces.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_024"] = "Borré eso de mi teléfono. Max, vi morir a Kate Marsh...|Te juro que no me parecía verdad.|No dejo de pensar si acaso yo causé eso.|Me he sentido de la chingada desde entonces.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_025"] = "Borré eso de mi teléfono. Tal vez no soy su amiga, pero no me deja de afectar que Kate haya intentado suicidarse. No soy malvada, Max.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_028"] = "No soy perfecta, ¿de acuerdo? Solo soy una adolescente en una escuela de arte. Solo estoy aquí para convertirme en una fotógrafa y volverme famosa.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_029"] = "Somos dos, Max. Todo el tiempo siento la necesidad de sobrecompensar. No tengo la menor idea de por qué. Estoy aquí solamente para convertirme fotógrafa, no presidente.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_031"] = "¿Cómo te atreves a decir eso?|No puedo esperar a ver tu cara cuando el Sr. Jefferson elija mi increíble foto para el concurso Héroes Cotidianos.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_033"] = "Mmmm no, perdedora. Estábamos hablando del concurso.|Tan solo estás celosa otra vez porque lograste evitar que el Sr. Jefferson se fuera a San Francisco.|Como si le importaras.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_034"] = "Mmmm no, perdedora. Estábamos hablando del concurso. Ni siquiera metiste una foto al concurso, así que deja de actuar como si te importara.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_036"] = "Qué risa.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_037"] = "Por cierto, nadie dice que tenemos que ser amigas, Max.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_039"] = "¿Me has visto hablando con él?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_041"] = "Solo hablábamos de lo emocionado que está por el concurso Héroes Cotidianos. Eso no significa que yo vaya a ganar o algo así.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_043"] = "Ya veremos... Y Max, sé que no te agrado, así que no es que tengamos que ser amigas o algo.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_045"] = "No lo entiendes. Mis padres tienen una galería de arte. Sé cómo es este juego... Es despiadado.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_048"] = "Tienes un punto, Max...|Gracias por admitir de nuevo que tengo algo de talento. No es que crea que lo tengo siempre.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_049"] = "Sí, es probable que el Sr. Jefferson no elija mi foto. No tengo tanto talento como creí.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_052"] = "Es difícil de creer, pero no siempre tomo las mejores decisiones. ¿Crees que estamos, no sé, destinadas a no ser amigas?",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_054"] = "Oh, sí, claro. Tú eres la falsa, actuando como si te importara cuando me cubrieron de pintura.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_056"] = "Tratas de actuar como si fueras tímida y humilde... ¡pero me tomaste una foto cubierta de pintura!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_058"] = "¿Fuiste tú? Eres una maldita. Pudiste haberme matado con esa maldita lata. ¡Casi hago que corrieran al loco de Samuel!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_060"] = "De verdad te crees mejor que yo... ¡de ninguna manera!",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_063"] = "No, perra. Nunca.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_065"] = "Quien tome esa decisión.",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_067"] = "Bueno, Max Caulfield, podría decidir dejarte entrar al club Vortex...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_069"] = "Cielos, te ves muy seria...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_071"] = "Estuve a punto de pedirte que saliéramos juntas. Entonces dijiste que mis fotos eran \"Avedon-escas\", y entonces recordé quién soy...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_075"] = "Tal vez nos parecemos demasiado...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_077"] = "Bueno, Max Caulfield, aún estás a tiempo de entrar al club Vortex...",
  ["Cue_E4_8B_VIP_CHVictoria_Phase01_Victoria_079"] = "¿Por qué lo dices de esa forma?",
  ["Cue_E4_8B_VIP_CHVictoria_Quickphase_Victoria_001"] = "Gracias, Max. Tendré cuidado por dónde piso.",
  ["Cue_E4_8B_VIP_CHVictoria_Quickphase_Victoria_002"] = "Gracias por el drama, Max. Ahora regresa a donde perteneces.",
  ["Cue_E4_8B_VIP_CHVictoria_Quickphase_Victoria_003"] = "Déjame disfrutar de esta fiesta lejos de ti.",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_010"] = "Por ninguna razón en especial. Me alegra que finalmente habláramos, Victoria. Ahora te entiendo mejor.",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_030"] = "Eso es lo que nos dicen... hablando de, ¿has visto a Nathan?",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_050"] = "Ah, el Director Wells quiere vernos el lunes, no es gran cosa.",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Max_070"] = "Au revoir...",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Victoria_020"] = "No te importa y no te culpo por ello. Sé que soy una cabrona... eso es algo que me quedó de mis antiguos compañeros en mis otras escuelas. Se supone que somos adultos ahora ¿cierto?",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Victoria_040"] = "¿Nathan Prescott? ¿Y por qué quieres saber eso?",
  ["Cue_E4_8B_VIP_DontWarnVictoriaNice_RTC_Victoria_060"] = "Espero que no te de algo. De hecho, no he visto a Nathan en toda la noche. Lo juro.",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_010"] = "Vamos, nena..",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_030"] = "Oh, vamos... ¡por mí!",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_050"] = "Está bien... ¡hey! ¡hey!",
  ["Cue_E4_8B_VIP_HotScene_TeenBoy_070"] = "Oh, por favor... ¡No voy a lastimarte!",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_020"] = "Jajaja... ¡basta!",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_040"] = "Jajaja... ¡basta!",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_060"] = "Alguien puede vernos",
  ["Cue_E4_8B_VIP_HotScene_TeenGirl_080"] = "Ah, ah...",
  ["Cue_E4_8B_VIP_MaxCallsChloe_Max_010"] = "¡Chloe, ven!",
  ["Cue_E4_8C_CampusPark_InsertionCar_Chloe_010"] = "Espero que Nathan disfrute su última fiesta.",
  ["Cue_E4_8C_CampusPark_InsertionCar_Chloe_030"] = "Al carajo con la Policía.|Rachel quiso que la encontremos para obtener justicia... y venganza.|Los Prescott se lo han merecido por años,|y nadie se va a poner en mi camino.|Y menos con tu ayuda... ¿Verdad?",
  ["Cue_E4_8C_CampusPark_InsertionCar_Max_020"] = "Chloe, podemos ir directamente con la Policía. Tenemos evidencia.",
  ["Cue_E4_8C_CampusPark_InsertionCar_Max_040"] = "Chloe, sabes que estoy contigo hasta el final.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Chloe_050"] = "¿En dónde está?",
  ["Cue_E4_8C_CampusPark_InsertionParty_Chloe_090"] = "Vámonos, Max.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Chloe_150"] = "No tenemos tiempo para estas estupideces. Vámonos Max.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_020"] = "Te ves muy bien, Warren. ¿Todo bien después de lo de hoy?",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_070"] = "Oye, ¿has estado bebiendo?",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_110"] = "Bueno.... no te culpo, Warren.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_140"] = "¡Acción!",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_170"] = "Oye, siempre necesitaremos tu gran ayuda. Si ves a Nathan, mándame un mensaje inmediatamente ¿de acuerdo? Y no dejes que te vea.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Max_190"] = "No para mí, Warren. Escríbeme pronto.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_010"] = "Bienvenidas al fin del mundo, señoritas. Me da mucho gusto que decidieran acompañarme...",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_030"] = "Realmente me desquité con Nathan. Odio a la gente abusiva... y Max, él es muy peligroso.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_040"] = "Gracias por detenerme... Nathan es peligroso.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_060"] = "No lo volví a ver en los dormitorios. Estuve escondido en mi habitación.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_080"] = "Bueno, si consideras media cerveza como \"beber\"...",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_100"] = "Esperen... Sé que es mal momento, pero, ¿nos tomamos una foto?|He sentido que éste realmente podría ser el fin del mundo...|Quisiera tener algo para la \"prosperidad\".",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_120"] = "Lo sé, lo sé, soy un dolor de cabeza. Solo una foto.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_130"] = "Veamos...",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_160"] = "Lo siento...|Solo quería sentirme como un estudiante normal por un instante después de la ultraviolencia de esta semana. Nunca había golpeado a alguien de esa forma... Siempre era yo al que golpeaban.",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_180"] = "Descuida, no lo hará. Sé cómo ser invisible aquí...",
  ["Cue_E4_8C_CampusPark_InsertionParty_Warren_200"] = "/!\\ WARNING /!\\ Text not localized : Cue_E4_8C_CampusPark_InsertionParty_Warren_200",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Chloe_020"] = "Sí, sí, hermoso. Me importa un carajo. El mundo se está acabando, genial...",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Chloe_040"] = "Así es. Nathan Prescott está a punto de caer.",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Max_010"] = "¿Qué es eso...? Por Dios, Chloe, ¡mira el cielo!",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Max_030"] = "¡Escúchame! ¡Algo importante va a pasar!",
  ["Cue_E4_8C_CampusPark_InsertionTwoMoons_Max_050"] = "¿Se está acabando el mundo?",
  ["Cue_E4_8C_CampusPark_TextMessage_Chloe_010"] = "Oh, por Dios. Nathan acaba de escribirme... dice que no quedará ni un rastro de evidencia cuando termine.",
  ["Cue_E4_8C_CampusPark_TextMessage_Max_020"] = "Maldición, ¡tenemos que ir al depósito de chatarra ahora mismo!",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy01_010"] = "No sé qué demonios es eso, pero veo dos lunas...",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy01_030"] = "No, no, no... de ninguna manera, debe ser una ilusión atmosférica o algo por el estilo...",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy02_020"] = "Igual yo, hermano... y ni siquiera me metí tanto... ¿eso es real?",
  ["Cue_E4_8C_CampusPark_TwoMoons01_IGE_TeenBoy02_040"] = "Nieve, un eclipse, pájaros muertos, ballenas... ¿y ahora dos lunas? Es posible que esto sea real.",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenBoy03_010"] = "¡Increíble! Mira... Esto es como en aquel eclipse.",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenBoy03_030"] = "No puedo distinguirlas.",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenGirl02_020"] = "Es cierto, mira el contorno...",
  ["Cue_E4_8C_CampusPark_TwoMoons02_IGE_TeenGirl02_040"] = "No es posible que haya dos lunas... no puede ser...",
  ["Cue_E4_9B_Junkyard_End_Chloe_010"] = "Oh, Dios, Max, mira... sigue ahí.",
  ["Cue_E4_9B_Junkyard_End_Chloe_060"] = "¿Qué carajo...?",
  ["Cue_E4_9B_Junkyard_End_Max_020"] = "No mires, Chloe...",
  ["Cue_E4_9B_Junkyard_End_Max_030"] = "Ay, no...",
  ["Cue_E4_9B_Junkyard_End_Max_040"] = "¡Chloe! ¡Cuidado!",
  ["Cue_E4_9B_Junkyard_End_Max_050"] = "Tú...",
  ["Cue_E4_9B_Junkyard_End_Max_070"] = "Chloe...",
  ["Cue_E4_9B_Junkyard_Grave_Max_010"] = "Chloe, ven aquí, ¡rápido!",
  ["Cue_E4_9B_Junkyard_Insertion_Chloe_020"] = "Está bien, solo mantente preparada para rebobinar si Nathan intenta atacarnos.",
  ["Cue_E4_9B_Junkyard_Insertion_Max_010"] = "¡No hagas tanto ruido, Chloe!",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_010"] = "¡Chloe, detente! ¡Espérame!",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_020"] = "Por Dios, ¡silencio! Debemos ser invisibles...",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_030"] = "Oye, no me puedo concentrar si estás gritando... Por favor.",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_040"] = "Chloe, no podemos seguirle el rastro a Nathan si no te calmas...",
  ["Cue_E4_9B_Junkyard_ScriptedAnswer_IGE_Max_050"] = "Por el amor de Dios, Chloe, ¡baja la voz! Podríamos morir, ¿sabes?",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_010"] = "Está muy tétrico allá afuera...",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_020"] = "¿Dónde diablos estás, Nathan Prescott?",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_030"] = "Rachel... por Dios, Rachel...",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_040"] = "Vas a sufrir, Nathan, te lo juro...",
  ["Cue_E4_9B_Junkyard_ScriptedChloeShort_IGE_Chloe_050"] = "Vamos, vamos...",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_010"] = "Vamos, vamos. Nathan tiene que morir ahora...",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_020"] = "Debí de hacerlo pedazos con mi camioneta...",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_030"] = "Sé que él anda cerca, me llega su olor a mierda...",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_040"] = "Max, cuando atrapemos a Nathan espero que rebobines para que pueda matarlo una y otra vez...",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_050"] = "Todos los Prescott caerán...",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_060"] = "Rachel, te vengaré... te lo juro...",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_070"] = "Dios... Quiero matar a ese pinche psicópata.",
  ["Cue_E4_9B_Junkyard_ScriptedIdle_IGE_Chloe_080"] = "Max, tenemos que hacer esto juntas. Tu poder es lo que va a acabar con Nathan.",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_010"] = "No debemos hacer ruido...",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_020"] = "¿Pero qué demonios...? ¡Qué asco!",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_030"] = "Tal vez debimos llamar a la policía...",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_040"] = "Odio este lugar...",
  ["Cue_E4_9B_Junkyard_ScriptedMaxShort_IGE_Max_050"] = "Lo siento mucho, Rachel.",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_010"] = "¡Max, espera!",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_020"] = "¡Güey, no me dejes!",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_030"] = "Max, quédate cerca para que podamos actuar como equipo...",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_040"] = "¿Lo ves ahí, Max? ¡Espera!",
  ["Cue_E4_9B_Junkyard_ScriptedTooFast_IGE_Chloe_050"] = "¡Regresa! ¡No me dejes sola!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_010"] = "¡Vamos, Max! ¡Apúrate!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_020"] = "¡Quítate, Max! ¡Nathan está muerto!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_030"] = "¿Qué buscas allá? ¡Ven acá!",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_040"] = "Max, quédate a mi lado antes de que se acabe la batería de tu teléfono...",
  ["Cue_E4_9B_Junkyard_ScriptedTooSlow_IGE_Chloe_050"] = "¿Estás bien? ¡Debemos apurarnos y atrapar a ese hijo de puta!",
  ["Act_E5_1A_DarkRoom_Binder_Look01_Max_010"] = "Debe haber otras fotos ahí adentro...",
  ["Act_E5_1A_DarkRoom_BorkenStuff_Look01_Max_010"] = "Bien, rompí los frascos cuando pateé el carrito...",
  ["Act_E5_1A_DarkRoom_CHVictoria1_Look01_Max_010"] = "Ah, mierda, Jefferson también secuestró a Victoria... esto está muy mal.",
  ["Act_E5_1A_DarkRoom_CHVictoria1_Look02_Max_020"] = "Victoria, te juro que te sacaré de aquí... de algún modo.",
  ["Act_E5_1A_DarkRoom_CHVictoria2_Look01_Max_010"] = "Te advertí acerca de Nathan... Acudiste a Jefferson en busca de ayuda... todo es mi culpa. Dios, lo siento... Por favor, perdóname...",
  ["Act_E5_1A_DarkRoom_Camera_Look01_Max_010"] = "Realmente me gustaría romperle la cámara en la cara a Jefferson... ",
  ["Act_E5_1A_DarkRoom_GuiltLines_Scripted_Max_010"] = "Prometí que nunca volvería en el tiempo así de nuevo... Pero es la única manera...",
  ["Act_E5_1A_DarkRoom_MaxPhone_Look01_Max_010"] = "Por supuesto... y justo delante de mí...",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look01_Max_010"] = "Oh, mierda... Soy yo... Tomó esa foto anoche... ",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look01_Max_015"] = "No puedo enfocarme... Está demasiado lejos...",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look02_Max_030"] = "Esto podría funcionar. Por favor, funciona...",
  ["Act_E5_1A_DarkRoom_MaxPic01_Look03_Max_040"] = "Odio verme a mí misma así... Pagarás por esto, Jefferson...",
  ["Act_E5_1A_DarkRoom_MaxPic02_Look01_Max_010"] = "Vaya... Definitivamente estoy más despierta en esta foto... Podría probar con esta.",
  ["Act_E5_1A_DarkRoom_MaxPicFailed_Look01_Max_010"] = "No, esa foto no ayudará... y no puedo vivir todo eso de nuevo. No lo haré.",
  ["Act_E5_1A_DarkRoom_MaxStuff_Look01_Max_010"] = "Genial... Puedo ver todas mis cosas pero no las alcanzo.",
  ["Act_E5_1A_DarkRoom_NeedleDrugs1_Look01_Max_010"] = "Dios, no recuerdo nada de lo que ocurrió... Debe ser la misma droga que Nathan usó con Kate.",
  ["Act_E5_1A_DarkRoom_NeedleDrugs2_Look01_Max_010"] = "Así que definitivamente tiré esas jeringas mientras me enfocaba... ¡cambié algo! ¡sigue adelante, Max!",
  ["Act_E5_1A_DarkRoom_PhotoTrolley_Look01_Max_010"] = "Si pudiera moverlo hacia mí...",
  ["Act_E5_1A_DarkRoom_Polaroid_Look01_Max_010"] = "Mi pequeña cámara se ve tan frágil ahora...",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_020"] = "No pude salvarla... de nuevo...",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_040"] = "Chloe... después de todo lo que vivimos esta semana...",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_050"] = "Cómo pudo Jefferson hacer esto... está enfermo... loco...",
  ["Act_E5_1A_DarkRoom_ScriptedIdle1_Scripted_Max_070"] = "No puedo creer que Jefferson era uno de mis héroes...",
  ["Act_E5_1A_DarkRoom_ScriptedIdle2_Scripted_Max_010"] = "Jefferson era demasiado bueno para ser verdad... ¿Cómo pude no ver las señales?",
  ["Act_E5_1A_DarkRoom_ScriptedIdle2_Scripted_Max_030"] = "Todavía puedo salir de esto y salvar a Chloe... debo hacerlo.",
  ["Act_E5_1A_DarkRoom_ScriptedObjective1_Scripted_Max_010"] = "Max, debes encontrar una forma de salir de aquí.",
  ["Act_E5_1A_DarkRoom_ScriptedObjective1_Scripted_Max_020"] = "Necesito una foto de mí misma... así podré regresar...",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_010"] = "Dios mío. No puedo creer que eso ocurriera. Aterrador...",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_020"] = "Me drogó para sus fotos degeneradas... Solo para tomar fotos...",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_030"] = "¿Cuánto tiempo ha estado ocultando todo esto?",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_040"] = "No vas a morir aquí...",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_060"] = "Podría intentar con otra foto... Me enferma solo pensar en él...",
  ["Act_E5_1A_DarkRoom_ScriptedObjective2_Scripted_Max_070"] = "Bien, cambié algunas cosas... Podría usar algunas de estas nuevas fotos...",
  ["Act_E5_1A_DarkRoom_Straps2_Look01_Max_010"] = "Estas correas lastiman...",
  ["Act_E5_1A_DarkRoom_TornFolder_Look01_Max_010"] = "Espera... Jefferson no soportaba ver manchas en sus fotos... ¡Bien, ahora me pueden servir!",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_001"] = "Oye, ¿sigues aquí?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_003"] = "Victoria... Por favor, escucha... Tengo un plan.",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_005"] = "Yo también. Pero no tenemos tiempo de asustarnos. Tenemos que defendernos.",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_007"] = "No permitiré que ese imbécil se salga con la suya... solo necesito que seas fuerte. No puedo hacer esto sola...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_008"] = "¡Silencio, Victoria! No queremos que Jefferson regrese... por favor... déjame pensar...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_009"] = "Resiste, Victoria. No morirá nadie más...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_011"] = "Lo sé, lo sé... pero debemos concentrarnos...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_012"] = "Me equivoqué... debí saber que Nathan no podía hacer esto él solo...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_017"] = "Eso es una estupidez. Nathan y Jefferson mataron a Kate. Y ella se merece justicia...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_018"] = "Las dos estamos aquí, ¿okey?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_019"] = "Kate quiere que nos larguemos de aquí... y después iremos a verla de nuevo, ¿está bien?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_023"] = "Victoria, encontraremos una manera de escapar. Lo prometo.",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Max_025"] = "Necesitamos actuar mientras todavía podamos pensar... si nos droga de nuevo olvidaremos todo...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_002"] = "No quiero morir así... apenas tengo 18 años...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_004"] = "¿En serio? ¿Cómo? Max... tengo mucho miedo...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_006"] = "Max... no puedo ni mover los brazos... ¿cómo se supone que pelearemos?",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_010"] = "¿Estás bromeando? Estamos atrapadas...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_013"] = "Max... ¿qué ocurre? Pensaba que decías que Nathan era peligroso... pero en realidad era Mark... el Sr. Jefferson...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_014"] = "¿Hacer qué? ¿Qué nos ocurrirá? Ay, por favor, sácanos de aquí...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_015"] = "Entonces Kate Marsh decía la verdad. Aunque sabía que no mentía... y pude haberla ayudado, Max. Pero la lastimé. Ahora... es mi turno.",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_016"] = "No soy fuerte, Max... mírame... mira lo que le hice a Kate Marsh... ahora ella está en el hospital y yo aquí...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_020"] = "No puedo creer que Jefferson hiciera esto... incluso lo chantajeé para que me hiciera ganar el concurso... ¡soy una estúpida!",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_021"] = "No puedo creer lo que está ocurriendo... que Jefferson me hiciera esto a mí... a nosotros...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_022"] = "Haría lo que fuera por ver a Kate una vez más... para decirle que lamento...",
  ["Cue_E5_1A_DarkRoom_CHVictoria_Phase01_Victoria_024"] = "Max... te creo.",
  ["Cue_E5_1A_DarkRoom_CHVictoria_QPhase01_Victoria_001"] = "Por favor... Por favor, sácanos de aquí, Max...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_020"] = "Espera, estoy pensando...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_040"] = "Solo... intentaré calmarme...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_070"] = "Yo tampoco.. pero ahora sí. Encontraré una manera de salir.",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_090"] = "No sabías nada. No pienses en eso ahora.",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_110"] = "Sssh. No fue así. No pienses en eso ahora.",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_130"] = "Victoria, nadie morirá aquí. Escaparemos. Te lo prometo.",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Max_150"] = "Necesito que me ayudes, ¿sí?",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_010"] = "¿Max... qué podemos hacer? ¿qué?",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_030"] = "¡Por favor, sácanos de aquí!",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_050"] = "¡Debes sacarnos de aquí! ¡Debes lograrlo!",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_060"] = "Ay, Max... lo siento tanto... no tenía idea...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_080"] = "Ahora sé por lo que pasó Kate... y yo ayudé a matarla...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_100"] = "Ahora sé por lo que pasó Kate... y yo casi la mato...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_120"] = "Por favor, no me odies... Por favor, no me dejes morir aquí...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_140"] = "Esto no puede ser real... Quiero despertar...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_160"] = "Dios, eso fue tan estúpido...",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_170"] = "¿Por qué el Sr. Jefferson está haciendo esto? ¿POR QUÉ?",
  ["Cue_E5_1A_DarkRoom_DosedVictoria2_IGE_Victoria_180"] = "Max... tienes que ayudarnos... tienes que hacerlo...",
  ["Cue_E5_1A_DarkRoom_InsertionBack_Max_010"] = "Max... vamos... piensa... por favor...",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_010"] = "Ayuden... me.",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_020"] = "¿Qué...? ¿Dónde...? El cuarto oscuro.",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_030"] = "¿Chloe...?",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_040"] = "Vamos... No...",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_050"] = "Oh, Dios mío... Vic... Victoria... despierta... por favor...",
  ["Cue_E5_1A_DarkRoom_Insertion_Max_060"] = "¡Victoria, despierta! ¡despierta!",
  ["Cue_E5_1A_DarkRoom_Insertion_Victoria_070"] = "Mhhhhh...",
  ["Cue_E5_1A_DarkRoom_MaxFreeLeg_IGE_Max_010"] = "¡Al fin! ¡Estoy libre! Casi...",
  ["Cue_E5_1A_DarkRoom_MaxHelp_IGE_Max_010"] = "¡Auxilio! ¡Ayúdenme!",
  ["Cue_E5_1A_DarkRoom_MaxHelp_IGE_Max_020"] = "¿Hay alguien ahí? ¡Ayuda, por favor!",
  ["Cue_E5_1A_DarkRoom_PolaRewind_Jefferson_030"] = "Oh, Max...",
  ["Cue_E5_1A_DarkRoom_PolaRewind_Jefferson_050"] = "Oh, eso es increíble...",
  ["Cue_E5_1A_DarkRoom_PolaRewind_Jefferson_100"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_1A_DarkRoom_PolaRewind_Jefferson_100",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Max_020"] = "Victoria... ey, Victoria... soy Max...¿puedes oírme?",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Max_040"] = "Te drogaron como a Kate... y a mí. ¿Recuerdas cómo llegaste aquí?",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Max_080"] = "Escúchame bien: Mark Jefferson nos secuestró. También está usando a Nathan. Jefferson es muy peligroso, así que debemos salir de aquí antes de que regrese...",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Victoria_030"] = "Max... ay, Dios, dónde... ¿dónde estamos? ¿qué ocurre?",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Victoria_050"] = "No... no sé... espera... me advertiste. Me advertiste sobre Nathan. Después fui con Jefferson para pedirle ayuda y actuaba tan raro... es lo último que recuerdo... y no puedo mover las manos... ayúdame, Max... por favor, lamento todo esto...",
  ["Cue_E5_1A_DarkRoom_VictoriaAwake_Victoria_090"] = "Max... no puedo creer que esto sea real... no quiero morir así... apenas tengo 18 años...",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_010"] = "Están saliendo unas tomas espectaculares, Max. Sí, Victoria mataría por estar en tu lugar, pero ella no entiende nuestra... conexión.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_020"] = "La perra malcriada intentó chantajearme para que eligiera su foto para el concurso Héroes Cotidianos.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_030"] = "Eres... la ganadora, Max. Te elijo a ti... Tu retrato.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_060"] = "Deja de fingir. Sé que estás asustada... Todas se ven como inocentes venadas al despertar aquí... Hasta que se aterran al darse cuenta de lo que les va a ocurrir.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_080"] = "Eso es todo. En los 90, podíamos hacer una sesión de revista con meta y coca... ahora es Kombucha y vitamina C... Mierda, ya casi ni siquiera hacen revistas... Extraño los 90... Esa era mi época... Mi momento...",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_100"] = "Oh, Max, qué bueno que preguntas... En pocas palabras,|estoy obsesionado con la idea de capturar el momento en que se pierde la inocencia...|Ese cambio de negro a blanco, luego gris... y más allá.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_110"] = "Las modelos suelen ser cínicas y nada ingenuas. Pero, algunas estudiantes de Blackwell|llevan su esperanza y optimismo con ellas como un aura... Y esas pocas afortunadas se convierten en mis modelos... Mis temas.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_140"] = "Bien, veamos cómo salieron estas tomas. Veo por qué te gusta tanto tu cámara instantánea. No necesitas una computadora para imprimir tu trabajo.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_160"] = "No supliques, nunca supliques... odio eso. Mejor disfrutemos nuestro momento final antes de que nuestra memorable sesión llegue a su fin... con tu muerte...",
  ["Cue_E5_1B_DarkRoom_Insertion2_Jefferson_170"] = "Significa mucho para mí que estuvieras aquí, Max... y que la última imagen que verás realmente sea la tuya propia, a través de mi visión... eso sí que es un regalo...",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_040"] = "Jódete.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_050"] = "Vete a la mierda.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_070"] = "Qué... ¿qué está a punto de ocurrir?",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_090"] = "Sr. Jefferson... ¿Por qué hace esto?",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_130"] = "Eres... un psicópata. Y esta es tu última sesión.",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_150"] = "Déjeme ir y le ayudaré... Déjeme ayudarle, por favor...",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_151"] = "Déjeme ir, yo... podría ayudarle... por favor...",
  ["Cue_E5_1B_DarkRoom_Insertion2_Max_152"] = "Déjeme ir... por favor... por favor...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_010"] = "Este ángulo resalta tu pureza, ¿ves? Una modelo ligeramente inconsciente suele ser más abierta y honesta... Sin vanidad ni poses... Solo expresión.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_012"] = "Dios mío, mira qué rostro tan perfecto.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_014"] = "¡Mantén esa mirada! ¡Ahí!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_016"] = "¡Quédate quieta!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_020"] = "¡Ay, Max! ¡Arruinaste la toma! Pero no te preocupes, tenemos todo el tiempo del mundo. Por ahora.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_030"] = "Sabía que eras especial desde el momento en que vi tu primer \"selfi\". Sí, odio esa palabra.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_040"] = "Pero amo la pureza de tu imagen... No como Rachel, que siempre buscaba ser algo que no era... Pobre Rachel... Espera, déjame probar este ángulo.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_050"] = "¡No te muevas!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_060"] = "Oh, mucho... mejor.|Gracias, Max. Ojalá Nathan pudiera ver este arreglo.|Hizo un gran esfuerzo, pero no puedes hacer unas cuantas tomas|y esperar tener un estilo o tema coherente.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_070"] = "Pero tenía visión para las sombras. Y visión para mucho más, como su propia familia descubrirá... al igual que toda Arcadia Bay...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_080"] = "Lindo... bien... Ah, esos ojos...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_090"] = "Tan sabios, pero tan inocentes...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_100"] = "Qué mal que seas tan entrometida, Max.|Pero este cuarto está bajo vigilancia las 24 horas, así que solo|te envié un mensaje con el teléfono de Nathan y caíste en mis manos.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_110"] = "Deberías haberte enfocado en la escuela, no en jugar a los detectives con tu amiguita.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_130"] = "Chloe, cierto.|Lamento haberla mata... que Nathan la matara en defensa propia.|Pero era una niña problemática, como la mayoría de los alumnos expulsados en Arcadia Bay.|A nadie le sorprenderá. Ni le importará.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_140"] = "Pero tú sí le importarás a la gente cuando mueras esta noche, Max. No mentía cuando te dije que tenías un \"don\".",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_145"] = "Hay un motivo por el que regresé a este pueblucho para turistas. Para encontrar la inocencia perfecta... como tú.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_150"] = "Genial, esto se ve bien... Quizá unos cuantos acercamientos más...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_160"] = "Max, por favor, no te muevas tanto. ¡Necesito que poses y retratarte a mi manera!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_165"] = "Quizás una nueva dosis te calme...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_170"] = "Ahora no te muevas o esto... dolerá... mucho.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_180"] = "¡Estúpida perra!",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_190"] = "Nunca escuchas, ¿verdad? De hecho, nunca me escuchaste en clase... si lo hubieras hecho, habrías visto venir todo esto...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_200"] = "Pero no podrías haber salvado ni siquiera a la pobre Kate Marsh... ¿o sí?",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_210"] = "Como si hubieras podido salvar a Kate Marsh... de algún modo...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_220"] = "Bah, estas sustancias químicas son difíciles de obtener y son costosas, Max... no tengo un patrocinador y Blackwell no paga nada. Esa era la función de Nathan...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_230"] = "Demonios, vaya que das pelea. Te he estado observando y he visto que te has vuelto más valiente esta semana que quizás en toda tu vida.",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_240"] = "Me gustas, Max, soy una cámara. Y como algunas culturas creen, usaré mi cámara para capturar tu alma. Para siempre... ahora descansa, nuestra sesión apenas comienza...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_245"] = "Me gustas, Max, soy una cámara. Y como algunas culturas creen, usaré mi cámara para capturar tu alma... para siempre. Ahora descansa, primero necesito encargarme de Nathan. No te preocupes, nuestra sesión apenas comienza...",
  ["Cue_E5_1B_DarkRoom_Insertion_Jefferson_250"] = "Recuerda mi regla número uno: nunca... dejes pasar... una oportunidad.",
  ["Cue_E5_1B_DarkRoom_Insertion_Max_120"] = "Chloe...",
  ["Cue_E5_1B_DarkRoom_Insertion_Max_130"] = "No... No...",
  ["Act_E5_1C_DarkRoom_ArtClassSelfie_Look01_Max_010"] = "Dios mío... Podría regresar hasta el momento en que todo esto comenzó... Max, esta puede ser tu mejor oportunidad para arreglar todo... de una vez por todas.",
  ["Act_E5_1C_DarkRoom_CHJefferson_Look01_Max_010"] = "Odio mirarte, Jefferson...",
  ["Act_E5_1C_DarkRoom_CHVictoria_Look01_Max_010"] = "Por lo menos Victoria no está despierta... no puedo con todo esto...",
  ["Act_E5_1C_DarkRoom_Diary_Look01_Max_010"] = "Tengo todas esas fotos en mi diario... esa podría ser una salida.",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_010"] = "Lo siento, esto no es arte...",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_020"] = "Vamos, Max... ¡Piensa!",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_030"] = "Si hablo con él y lo distraigo, quizás me dé una foto...",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_040"] = "Mejor le pregunto otra cosa...",
  ["Act_E5_1C_DarkRoom_ScriptedObjective_Scripted_Max_050"] = "Mierda, ahí está mi diario... si pudiera alcanzarlo...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_001"] = "Au contraire, Max. Estoy tan cuerdo que nadie sabe dónde estás ahora.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_004"] = "Como verás, la Bella Durmiente de aquí es demasiado dura para mi lente tan suave...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_005"] = "Y no me hagas hablar de tu compañera... Ya tuve suficiente de falsas zorras punk cuando estuve en Seattle...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_006"] = "A diferencia de la pura y dulce Kate Marsh, no creo en esa mierda. Ella podría haber sido mi obra maestra... El mundo es lo que un artista hace de él... y mi musa...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_007"] = "Tenía un arma cargada. Claramente fue defensa propia.|Pero eso es lo que ocurre cuando juegas con armas... o cuando intentas joderme.|Es mejor cuando no saben nada, como la pura y dulce Kate.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_011"] = "Deberías disfrutarla, ya que es lo último que escucharás. Ah, ¿toqué un tema sensible? Tu cara cambió de color... Hermosa.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_012"] = "Ciertamente vivirá más que tú. ¿Quién sabe? Quizá visitaré pronto a Kate y probaré su fe de nuevo...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_013"] = "Eso me entristece, Max. La extrañaré... Kate tenía un espíritu tan fuerte... fue muy satisfactorio haberlo quebrado.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_015"] = "Cuando le dijiste al director que hice llorar a Kate, pensé que casi me tenías. Por suerte, el querido director Wells es como la mayoría de los administradores: un ebrio sin remedio.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_016"] = "Qué mal que ya acusaste convincentemente a Nathan en la oficina del Director. Muchas gracias por ese favor.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_017"] = "Entonces, ¿por qué culpaste a David Madsen por acosar a Kate? Por supuesto, él era la única persona que intentaba descubrir la verdad... ¡qué ironía!",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_018"] = "Sé que los Prescott vivirán un escándalo colosal una vez que se sepa lo que su hijo pródigo ha estado haciendo de \"tarea\"...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_021"] = "Prefiero el término \"manipulado\". Como con una figura... Nathan fue fácil de moldear.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_022"] = "No juzgues a las personas, Max. Es por eso mismo que Nathan no debió entrar en Blackwell.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_025"] = "Te equivocas de nuevo. Realmente tenía talento. Y su padre es un verdadero imbécil, como bien sabes.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_026"] = "Ayudé a Nathan a encontrar una visión... muy pocas personas tienen esa oportunidad.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_029"] = "Me convertí en algo así como una \"figura paterna\" para Nathan. Ocurre a menudo en las relaciones maestro-estudiante. Fue conmovedor por un tiempo...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_031"] = "No seas estúpida, Max. Le dije lo que necesitaba escuchar. A cambio, tuve acceso a la fortuna de los Prescott. Adivina quién pagó por este glorioso cuarto oscuro y el equipo. ¿Cómo podría obtener todas estas drogas tan costosas para mis modelos?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_033"] = "Ah, Rachel Amber... una verdadera tragedia. Nathan pensó que podía ser un artista, como yo... pero el idiota le causó una sobredosis.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_036"] = "Ahora cogen juntas en el cielo, ¿eso es lo que querías oír?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_037"] = "No tengo tiempo de contarte todo, pero ella era... especial. Un camaleón humano. Tantas posibilidades visuales... Teníamos una conexión real.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_039"] = "\"¿Por qué? ¿Por qué?\" ¡Escúchame bien, perra idiota!",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_040"] = "Lo siento, Max. Eso no fue amable.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_044"] = "Seamos honestos, estaba jugando con el clásico \"chico malo\". Había superado a Frank antes de que comenzara. Él simplemente no lo sabía.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_045"] = "Rachel estaba enamorada de mí, y no lo digo por mi ego. Entenderías si vieras nuestras sesiones, lo que por supuesto no sucederá. Ella amaba ser fotografiada.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_046"] = "En fin... Rachel está muerta. Pero no importa, Los Ángeles la habría matado de todos modos, así que le hice un favor.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_048"] = "Sí, claro. Tú y tus amigos casi matan a Nathan a golpes. ¿Ves? No somos tan diferentes.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_049"] = "Ah, ya veo... eres \"buena\" porque detuviste a tu amigo para que no golpeara a Nathan.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_052"] = "¡No es cierto! Fue una pena que se obsesionara con Rachel. Creía que podía imitar lo que yo hago con una cámara y una modelo. De tal palo, pero no...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_054"] = "Muerto y enterrado.|Después de lo que le hizo a Rachel, sabía que no podía conservarlo como mi pupilo.|La policía nunca encontrará su cuerpo. ¿Finalmente lo entiendes, Max? No puedo arriesgar mi visión por culpa de novatos...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_056"] = "Me encanta tu espíritu, Max, pero llegaste aquí por tu propia elección... me gusta que vean a mis modelos, no me interesa que las escuchen... así que debo asegurarme de que no quede ni rastro de ti...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_058"] = "Bien. Gracias por recordarme... no hay nada más inocente que el diario de una adolescente... mira, este es el último selfi que tomaste en mi clase... nunca escuchas, como siempre...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_059"] = "Qué desperdicio de talento... mira esta foto Max... puedes hacerlo mucho mejor...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_060"] = "Bien. Gracias por recordarme... no hay nada más inocente que el diario de una adolescente...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Jefferson_062"] = "Yo doy las órdenes... buen selfi de la clase... qué desperdicio de talento...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_002"] = "Vete al diablo. Ya verás. Por todos los que has lastimado...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_003"] = "¡Mataste a Chloe! Asesinaste a mi mejor amiga.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_008"] = "Bla, bla, bla... Dios, cómo odio tu voz ahora...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_009"] = "Kate tuvo fe y sobrevivió. No pudiste quebrarla, ella es más fuerte que nunca. Y vivirá más que tú.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_010"] = "Los artistas no conducen a adolescentes al suicidio por una puta obra. Tú entrenaste a Nathan para drogar a Kate... Para tomar fotos de ella... Por eso está muerta.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_014"] = "No te saldrás con la tuya. Quiero que lo sepas.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_019"] = "Usaste a Nathan.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_020"] = "Él está tan enfermo como tú.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_023"] = "Te importaba un carajo.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_024"] = "Tampoco tú.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_027"] = "Lo sé.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_028"] = "Le lavaste el cerebro…",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_030"] = "¿Le dijiste todo acerca de tus planes en Blackwell?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_032"] = "Rachel Amber fue tu víctima, no tu \"modelo\".",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_034"] = "Chloe y Rachel... ¡Las mataste!",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_035"] = "¿Por qué Rachel?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_038"] = "¿Por qué?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_041"] = "¿Ella se dejó fotografiar?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_042"] = "¿Sabías que ella también tenía una \"conexión\" con Frank?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_047"] = "Eres malvado.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_050"] = "Sí... sí, lo somos.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_051"] = "Nathan me importaba más a mí que a ti.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_053"] = "¿Dónde está Nathan ahora?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_055"] = "Tú eres peor que un novato. Mira las muertes que has dejado.|No puedes culpar a Nathan de todo esto. No me importa lo hagas conmigo.|Vas a morir, hijo de puta. Por Chloe, Rachel, y todos los demás.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_057"] = "Todavía tienes mi diario...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_061"] = "Yo... todavía tengo una fotografía allí... por favor, ¿puedo verla...?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Phase01_Max_063"] = "¿Ella te dejó... tomarle fotografías? Leí una nota donde decía que había conocido a alguien...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_002"] = "Max, me encantaría hablar de trabajo, pero necesito revisar estas fotos. Especialmente cuando aún las tengo frescas en la mente. Creo que nuestra sesión fue un logro en mi carrera.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_009"] = "Es la primera vez que una de mis modelos me pide eso aquí. Por supuesto. Me encanta que lo último que veas sea a ti misma... a través de mi cámara. Cuánta perfección.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_010"] = "No supliques, jamás supliques... Lo detesto. En fin, disfrutemos los últimos instantes antes de que esta memorable sesión concluya... con tu muerte.",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_011"] = "No te preocupes, nadie lo leerá. Gracias por recordármelo.|No hay nada más inocente que el diario de una adolescente. Ah, mira tus selfis...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_012"] = "¿Estoy \"enfermo\"? ¿Acaso ves el mundo? ¿Tu escuela? ¿Tus amigos? Al carajo todo eso. Yo veo la belleza de la juventud... de los sueños, antes de convertirse en pesares...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_013"] = "Vivirás para siempre en mis fotografías.|Es todo lo que quedará de Maxine Caulfield.|Ni siquiera encontrarán tu bolsa...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_014"] = "Gracias por recordármelo... no hay nada más inocente que el diario de una adolescente...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_016"] = "¿Cómo puedo no leerlo ahora? La prosa de una colegiala es tan... ingenua... ¡apuesto a que te gusta un cierto maestro de arte! Ahora, veamos tus selfis...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_017"] = "Qué desperdicio de talento... Mira esa toma, Max... Puedes hacerlo mucho mejor...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_019"] = "Buen intento, Max. Mis sueños terminaron hace mucho tiempo... pero ahora estoy en paz... ahora me enfoco en moldear mi propio nicho de arte privado...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Jefferson_020"] = "Qué desperdicio de talento... esa toma es terrible, Max... puedes hacerlo mucho mejor...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_001"] = "¡Espere! Por favor, Sr. Jefferson...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_003"] = "¿Podría...? ¿Podría mostrarme las fotos?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_004"] = "Déjeme ir y le ayudaré... Déjeme ayudarle, por favor...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_005"] = "Aún tiene mi diario...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_006"] = "Estás enfermo, Mark... Sr. Jefferson... necesita ayuda. Hay personas que querrán ayudarle... solo déjeme ir y...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_007"] = "¿Qué... hará conmigo?",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_008"] = "Yo sé que... se deshará de mí, pero... no deje que nadie vea mi diario...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_015"] = "Por favor, no lo lea...",
  ["Cue_E5_1C_DarkRoom_CHJefferson_Puzzle01_Max_018"] = "Entonces déjeme ir... para que no lamente esto...",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_010"] = "Qué hermosa... esta es la pureza personificada...",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_020"] = "Max... ojalá pudieras verte ahora...",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_030"] = "Está fuera de foco... pero es mi culpa, Max.",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_040"] = "Max, ojalá hubieras vivido en mis mejores tiempos...",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_050"] = "Tus ojos están tan abiertos... tan perdidos... hermoso.",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_060"] = "Vaya, me encantaría compartir esto con el mundo...",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_070"] = "Ahora veamos esta... definitivamente pieza para galería.",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_080"] = "Max, verdaderamente es una pena que yo sea el único que pueda tomar tus fotos...",
  ["Cue_E5_1C_DarkRoom_JeffersonDesk_IGE_Jefferson_090"] = "Ah... esto sí es arte...",
  ["Cue_E5_1C_DarkRoom_PolaRewind_Jefferson_010"] = "Ella veía a la humanidad como criaturas torturadas, ¿cierto? Y, francamente, es algo patético. ¡No digan que dije eso! Pero, en serio, podría poner a cualquiera de ustedes en un rincón oscuro y plasmarlos en un momento de desesperación.",
  ["Cue_E5_1C_DarkRoom_PolaRewind_Victoria_010"] = "Por sus imágenes de rostros sin esperanza. Uno se siente totalmente atrapado por los ojos de las madres e hijos tristes.",
  ["Act_E5_2A_ArtClass_ArcadiaPicture01_Look01_Max_010"] = "Todavía queda algo de belleza en Arcadia Bay...",
  ["Act_E5_2A_ArtClass_ArcadiaPicture02_Look01_Max_010"] = "Siento que el faro me llama...",
  ["Act_E5_2A_ArtClass_BagHint_Scripted_Max_010"] = "Tengo un montón de cosas de Blackwell en mi bolso, quizá podría encontrar lo que necesito.",
  ["Act_E5_2A_ArtClass_Books_Look01_Max_010"] = "Hace una semana, era tan ingenua acerca del arte... la vida... el mundo...",
  ["Act_E5_2A_ArtClass_CHJefferson_Look01_Max_010"] = "Sé toda la mierda que cargas, Jefferson... Todos te conocerán.",
  ["Act_E5_2A_ArtClass_CHKate_Look01_Max_010"] = "Me da tristeza Kate, pero me alegra que esté viva...",
  ["Act_E5_2A_ArtClass_CHKate_Look01_Max_015"] = "Pobre Kate...",
  ["Act_E5_2A_ArtClass_CHKate_Look02_Max_020"] = "Ten fe, Kate. Esta vez estoy aquí para ti...",
  ["Act_E5_2A_ArtClass_CHKate_Look02_Max_025"] = "Por lo menos Kate sabe que muchos la apoyan...",
  ["Act_E5_2A_ArtClass_CHVictoria_Look01_Max_010"] = "Victoria, lamento que tengas que estar junto a este psicópata.",
  ["Act_E5_2A_ArtClass_CHVictoria_Look01_Max_020"] = "Victoria, si supieras quién era Jefferson en realidad...",
  ["Act_E5_2A_ArtClass_ContestPhoto_Look01_Max_010"] = "Okey, Jefferson, aquí está mi estúpida foto para el concurso.",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_020"] = "Regresé... justo adonde comenzó esta semana de locura...",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_030"] = "Y nadie volverá a lastimar a Chloe...",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_040"] = "No lo arruines, Max...",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_050"] = "Cálmate... respira... un cambio a la vez... para siempre.",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_060"] = "Primero, hagamos que capturen a Mark Jefferson.",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_070"] = "Debo advertirle a David acerca de Jefferson y el Cuarto Oscuro. ",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_100"] = "Esto no debería alterar el tiempo y el espacio... demasiado... espero.",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_120"] = "El pasado dentro del pasado... ¿Estoy exigiéndome demasiado?",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_130"] = "No importa lo que me ocurra... ¡salvaré a Chloe!",
  ["Act_E5_2A_ArtClass_ContextLines_Scripted_Max_140"] = "Bastardo.",
  ["Act_E5_2A_ArtClass_DanielTable_Look01_Max_010"] = "Ah, Rachel... lo siento...",
  ["Act_E5_2A_ArtClass_FocusBoundaries_Look01_Max_010"] = "No puedo pasar los límites de estas fotos, necesito arreglar todo desde aquí.",
  ["Act_E5_2A_ArtClass_FocusWithinFocus_Scripted_Max_010"] = "Vaya, así que estoy dentro de una fotografía que está... dentro de una fotografía.",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_010"] = "Es tan extraño estar de regreso a donde comenzó todo...",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_020"] = "Quisiera estar despertando de un sueño...",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_030"] = "Solo ha pasado una semana, pero siento como si fueran cinco años...",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_040"] = "No puedo ni ver a Jefferson... cabrón prepotente...",
  ["Act_E5_2A_ArtClass_IdleLines_Scripted_Max_070"] = "Si pudiera decirle a toda la clase acerca de Jefferson y verlo retorcerse... pero es mejor dejar a David encargarse de todo...",
  ["Act_E5_2A_ArtClass_Ipad_Look01_Max_010"] = "Con gusto lo arreglo para que estés aquí y recibas tu cámara sofisticada, Victoria...",
  ["Act_E5_2A_ArtClass_Ipad_Look02_Max_015"] = "Una cámara sofisticada no te da talento, Victoria... ni excusas. No lastimarás a Kate Marsh esta vez.",
  ["Act_E5_2A_ArtClass_JeffersonCamera_Look01_Max_010"] = "Me gustaría acabar con esto justo ahora.",
  ["Act_E5_2A_ArtClass_MaxBag_Interact01_Max_020"] = "Debería poder encontrar el número de David en este folleto escolar...",
  ["Act_E5_2A_ArtClass_MaxBag_Look01_Max_010"] = "Tengo un montón de folletos de Blackwell, así que espero que el número de David esté allí...",
  ["Act_E5_2A_ArtClass_MaxBag_Look02_Max_030"] = "Fracaso.",
  ["Act_E5_2A_ArtClass_MaxBag_Look03_Max_040"] = "¡Te encontré!",
  ["Act_E5_2A_ArtClass_MaxCamera_Look01_Max_010"] = "¿Sabías que algún día tus fotos de verdad alterarían el tiempo y el espacio?",
  ["Act_E5_2A_ArtClass_MaxDiary_Look01_Max_010"] = "Este diario literalmente salvó mi vida...",
  ["Act_E5_2A_ArtClass_MaxNotes_Look01_Max_010"] = "Espero que aún me guste la fotografía cuando esto termine... \"No confundan el arte con el artista\"... bastardo.",
  ["Act_E5_2A_ArtClass_MaxPhone_Look01_Max_010"] = "Solo necesito el número de David y Jefferson estará a un solo mensaje de ser sentenciado a cadena perpetua...",
  ["Act_E5_2A_ArtClass_ObjectiveLines_Scripted_Max_010"] = "Sí, puedo advertirle a David justo ahora... sólo necesito su estúpido número...",
  ["Act_E5_2A_ArtClass_ObjectiveLines_Scripted_Max_020"] = "Por primera vez, David... rezo para que reacciones exageradamente como siempre... y acabes con Jefferson rápido.",
  ["Act_E5_2A_ArtClass_ObjectiveLines_Scripted_Max_030"] = "Necesito darle la última foto que evaluará en su vida para el concurso Héroes Cotidianos... y después viviremos felices para siempre. O lo intentaremos...",
  ["Act_E5_2A_ArtClass_PaperBall_Look01_Max_010"] = "Esta es la última vez que alguien abusa de ti, Kate.",
  ["Act_E5_2A_ArtClass_PhotoStuff01_Look01_Max_010"] = "Ya no me impresiona.",
  ["Act_E5_2A_ArtClass_PhotoStuff02_Look01_Max_010"] = "No puedo culpar a las cámaras, me recuerdan a Jefferson...",
  ["Act_E5_2A_ArtClass_Poster01_Look01_Max_010"] = "Un \"Héroe Cotidiano\" te partirá el cráneo, Jefferson.",
  ["Act_E5_2A_ArtClass_Poster02_Look01_Max_010"] = "Me pregunto a cuántas víctimas habrá sacrificado Jefferson en su carrera...",
  ["Act_E5_2A_ArtClass_Poster03_Look01_Max_010"] = "Los 90 terminaron para ti, imbécil...",
  ["Act_E5_2A_ArtClass_TextBook_Look01_Max_010"] = "Ay, Victoria... Pudimos haber sido amigas...",
  ["Act_E5_2A_ArtClass_TextBook_Look01_Max_015"] = "Victoria... es bueno saber cómo te sientes realmente...",
  ["Cue_E5_2A_ArtClass_BellRing_Hayden_030"] = "Espera a ver lo que estoy fotografiando. Man Ray se fusiona con manga...",
  ["Cue_E5_2A_ArtClass_BellRing_Jefferson_010"] = "Y no se olviden del plazo para presentar una foto en el concurso Héroes Cotidianos. Viajaré con el ganador a San Francisco, donde el mundo del arte los agasajará. Es buena publicidad y puede catapultar una carrera en la fotografía. Así que, Stella y Alyssa, espabílense. Taylor, no te ocultes, todavía espero tu foto. Y, sí, Max, ya deja de fingir que no me ves.",
  ["Cue_E5_2A_ArtClass_BellRing_Taylor_020"] = "...no hay tiempo. Sabes que Victoria ingresó para ganar. Como siempre.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_003"] = "Bah. Eso fue fácil, Max.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_007"] = "Eh... ¿A qué te refieres?",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_008"] = "Eh... Parece que alguien no ha tomado su café. ¿Quieres intentar de nuevo?",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_009"] = "Fingiré que no dijiste eso y te dejaré responder una vez más...",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_014"] = "Bien... entonces... el proceso de Daguerre hizo al retrato muy popular, sobre todo porque proporcionó a los modelos rasgos claros y definidos. Podrían aprender más si terminan de leer los capítulos asignados. Obviamente... Max los ha leído.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_015"] = "No estoy seguro de captar la relación pero... sí, el proceso de Daguerre hizo al retrato muy popular, sobre todo porque proporcionó a los modelos rasgos claros y definidos. Podrían aprender más si terminan de leer los capítulos asignados. Max claramente ha leído más sobre ello que yo...",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_016"] = "Bien... Continuemos.|Eh... El proceso de Daguerre hizo al retrato muy popular, sobre todo porque proporcionó a los modelos rasgos claros y definidos. Podrían aprender más si terminan de leer los capítulos asignados.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_017"] = "Ah, bien... gracias por la advertencia, Max... entonces, el proceso de Daguerre hizo al retrato muy popular, sobre todo porque proporcionó a los modelos rasgos claros y definidos. Podrían aprender más si terminan de leer los capítulos asignados. Claramente Max no tiene tiempo para ello...",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_018"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_2A_ArtClass_CHJefferson_Phase01_Jefferson_018",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_002"] = "El daguerrotipo.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_004"] = "El daguerrotipo. Él era un visionario... no un hipócrita.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_005"] = "No intento \"captar\" el interés de nadie. Eso sería bastante retorcido, ¿no?",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_006"] = "¿A quién le importa? Esta clase es una basura.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_010"] = "¿Ah, sí? Bueno.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_011"] = "Quiero decir que en realidad creó algo. No solo tomaba fotografías de modelos y pretendía que eran arte.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_012"] = "Okey, okey, el daguerrotipo, bla, bla, bla.",
  ["Cue_E5_2A_ArtClass_CHJefferson_Phase01_Max_013"] = "Lo siento, ya no queda tiempo. Quiero decir, su clase ya casi termina.",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Jefferson_010"] = "Sí, Victoria, tienes que hacer los deberes esta semana aunque vayas a presentar una foto al concurso. Vamos, como todo el mundo.",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Jefferson_030"] = "Solo debes participar, salir al mundo y que te vean. Bueno, no importa quién gane; es solo una batalla en una guerra más grande. No quiero que nadie se sienta excluido de este proceso. Pero también quiero que sepan que el mundo de la fotografía no es para todos. Tuve mi momento con la cámara, y todos deberían tener esa oportunidad, ¿no?",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Victoria_020"] = "Lo sé, Sr. Jefferson. Es solo que trabajé tan duro para esta foto, y estoy segura de que sabe lo que se siente estar consumido por el trabajo. En verdad creo que Héroes Cotidianos es un evento cultural importante y quiero representar a la Academia Blackwell.",
  ["Cue_E5_2A_ArtClass_DiscussionLoop_Victoria_040"] = "Ah, claro. Solo quiero compartir mi talento con el mundo...",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_020"] = "Eh...",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_060"] = "Un momento, Victoria. ¿Estás bien, Max?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_120"] = "Pienso que debería permanecer fuera de esto, Victoria...",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Jefferson_150"] = "No entiendo, Max. ¿Qué quieres decir...?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_010"] = "Sr. Jefferson... necesitamos hablar.",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_040"] = "Sí, puedo verlo. Pero quizás no deberías...",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_070"] = "Será cuando Victoria entienda que ocultarse tras una pantalla y publicar videos de otras personas es increíblemente injusto y cruel. Eres lo bastante inteligente para saber qué fácil es destruir la vida de alguien.",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_080"] = "Solo quiero que pienses en cuánto dolería si alguien te hiciera eso a ti. Siempre puedes tomar la decisión correcta, Victoria. Sé que tienes un buen corazón. Lo he visto.",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_100"] = "No tienes que explicar nada. No hay motivo para que seas tan insegura que no puedas estar contenta con tu propio talento. ¿No sería mejor ayudar a otros a volar en lugar de derribarlos? Podrías inspirar a otros...",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Max_140"] = "Y eso también está bien.",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_030"] = "¿No ves que estoy hablando con el Sr. Jefferson?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_050"] = "¿Eh? ¿Y por qué no?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_090"] = "Escucha... yo... yo no...",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_110"] = "Okey, no sé de hablas... ¿usted sí, Sr. Jefferson?",
  ["Cue_E5_2A_ArtClass_GivePhotoNice_Victoria_130"] = "Entonces supongo que ya terminé de hablar.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_020"] = "Eh...",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_060"] = "Un momento, Victoria. ¿Estás bien, Max?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_120"] = "Bien, parece que ya lo hiciste, Victoria...",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_150"] = "No diré que no disfruté eso, pero, ¿por qué?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_170"] = "Oh... Eso fue fácil.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_190"] = "Bueno... No puedo prejuzgar pero me da mucho gusto que decidieras entrar.|Esto significa mucho para mí... y para Blackwell. El primer paso para cualquier artista es salir al mundo sin miedo. Ser... inocente.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_210"] = "Ah, bien... Gracias por la foto. Quizás viajemos como estrellas a San Francisco el próximo viernes.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Jefferson_230"] = "No seas tan modesta, Max. Todo puede pasar en una semana...",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_010"] = "Sr. Jefferson... necesitamos hablar.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_040"] = "Veo que de nuevo estás lamiendo botas. Nada nuevo.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_070"] = "No hasta que Victoria sepa que esconderse detrás de una pantalla y publicar videos de otras personas es pura mierda.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_080"] = "¿Sabes qué fácil es lastimar a alguien? ¿Destruir su vida? ¿Y te enorgulleces de ti misma? Si aún tienes algo de corazón, deberías pensar en tus actos.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_100"] = "Por supuesto que lo hiciste. Eres tan insegura que no podías ser feliz con tu propio talento. Debías rebajar a todos a tu miserable nivel.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_140"] = "Así lo espero.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_160"] = "Aquí está mi fotografía para el concurso Héroes Cotidianos.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_180"] = "No, no fue fácil para nada.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_200"] = "O culpable.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_220"] = "O quizá solo uno de nosotros irá...",
  ["Cue_E5_2A_ArtClass_GivePhoto_Max_240"] = "Como ya lo descubrirá, Sr. Jefferson.",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_030"] = "¿Ves que estoy hablando con el Sr. Jefferson ahora?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_050"] = "¿Qué dijiste?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_090"] = "Escucha... Yo... no...",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_110"] = "Okey, no tengo por qué escuchar estas estupideces... ¿O sí, Sr. Jefferson?",
  ["Cue_E5_2A_ArtClass_GivePhoto_Victoria_130"] = "Entonces supongo que ya terminé de hablar.",
  ["Cue_E5_2A_ArtClass_JeffGivingLesson_Jefferson_050"] = "Podría poner a cualquiera de ustedes en un rincón oscuro|y plasmarlos en un momento de desesperación.",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_020"] = "Ah... Hola, Max.",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_040"] = "Te escucho.",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_060"] = "Max... Me haces sentir bendecida por primera vez esta semana... No sé qué decir...",
  ["Cue_E5_2A_ArtClass_KateHug_Kate_080"] = "Gracias, siempre sabes qué es lo correcto.",
  ["Cue_E5_2A_ArtClass_KateHug_Max_010"] = "Hola, Kate...",
  ["Cue_E5_2A_ArtClass_KateHug_Max_030"] = "Kate, escúchame.",
  ["Cue_E5_2A_ArtClass_KateHug_Max_050"] = "Siempre recuerda que no estás sola. Yo te apoyo sin importar lo que ocurra. Igual que muchas otras personas. Todos estamos aquí para ti. No lo olvides.",
  ["Cue_E5_2A_ArtClass_KateHug_Max_070"] = "Está bien, tampoco yo. Quizás las dos necesitamos un abrazo.",
  ["Cue_E5_2A_ArtClass_Polaroid_Picture01_Jefferson_010"] = "Shhh, creo que Max se ha tomado lo que ustedes llaman una \"selfi\"... Una palabra tonta para una maravillosa tradición fotográfica. Y Max... tiene un don.",
  ["Cue_E5_2A_ArtClass_Polaroid_Picture01_Jefferson_020"] = "Como todos saben, el retrato fotográfico ha sido popular desde el siglo XIX. Su generación no fue la primera en \"selfi-expresarse\". Lo siento. No me pude resistir. El retrato siempre fue y sigue siendo un aspecto vital del arte y de la fotografía, desde que se creó.",
  ["Cue_E5_2A_ArtClass_Polaroid_Picture01_Jefferson_030"] = "Bueno, Max, ya que captaste nuestro interés y claramente quieres participar,|¿puedes decirnos el nombre del proceso que dio origen a los primeros autorretratos?",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_010"] = "Es hora de cambiar el tiempo.",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_015"] = "¡Sí! Regresé. Funcionó.",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_020"] = "Ah, Kate...",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_030"] = "Tú querías que entrara al concurso, imbécil.",
  ["Cue_E5_2A_ArtClass_TextMessage_Max_040"] = "Así que quizás yo iré a San Francisco y Jefferson irá a prisión.",
  ["Act_E5_3A_Plane_CHPrincipal_Look01_Max_010"] = "Apuesto a que este es un buen descanso para el director Wells después de todo lo que sucedió esta semana en Blackwell.",
  ["Act_E5_3A_Plane_CHPrincipal_Look02_Max_020"] = "Y pensar que podría haber terminado junto a Jefferson en su lugar... repugnante.",
  ["Act_E5_3A_Plane_ContestInvit_Look01_Max_010"] = "Debo admitirlo, me encanta que me consideren una \"artista\"...",
  ["Act_E5_3A_Plane_IdleAnnouncementLines_Scripted_Max_010"] = "¿Así se siente ser un verdadero artista? ¿Te codeas con la alta sociedad en las galerías?",
  ["Act_E5_3A_Plane_IdleAnnouncementLines_Scripted_Max_020"] = "Ten cuidado... aún estoy entre realidades... y no puedo enfocarme en esta realidad durante demasiado tiempo...",
  ["Act_E5_3A_Plane_IdleLines_Scripted_Max_010"] = "Espero haber hecho todo bien esta vez...",
  ["Act_E5_3A_Plane_IdleLines_Scripted_Max_030"] = "¡Pero Chloe está viva! Enfócate en eso, Max... ahora, a esperar hasta después de mi viaje para verla de nuevo... y no la perderé de vista otra vez...",
  ["Act_E5_3A_Plane_IdleLines_Scripted_Max_070"] = "Dios, ¿otra vez me sangra la nariz? Max... no solo estás jugando con el tiempo...",
  ["Act_E5_3A_Plane_MaxScreen_Interact01_Max_010"] = "Casi llegamos a San Francisco... Estoy muy nerviosa, pero también muy entusiasmada...",
  ["Act_E5_3A_Plane_ObjectiveLines_Scripted_Max_010"] = "Bien... Estás bien, Max... Estás segura... en un avión.",
  ["Act_E5_3A_Plane_PlaneNewsPaper_Look01_Max_010"] = "Buen trabajo, David.",
  ["Act_E5_3A_Plane_PlaneNewsPaper_Look01_Max_015"] = "El inicio del fin para Jefferson y los Prescott...",
  ["Act_E5_3A_Plane_PrincipalScreenSausage_Look01_Max_010"] = "Aaaah, no he visto Hawt Dawg Man en mucho tiempo... Chloe y yo solíamos jugar el videojuego y verlo... cuando éramos inocentes...",
  ["Act_E5_3A_Plane_Window_Look01_Max_010"] = "Es tan raro estar entre realidades. Todo está fuera de foco y distante.",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger01_010"] = "Vaya, ¿viste la publicación acerca del clima tan extraño en Oregon?",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger01_030"] = "Eh, está en todas las noticias. Eclipse, ballenas muertas y algunas personas en este pueblo costero vieron dos lunas. La NASA también está investigando.",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger02_020"] = "No creo todo lo que leo en Internet...",
  ["Cue_E5_3A_Plane_ChitChat01_IGE_Passenger02_040"] = "Son mentiras, nada más. Despiértame si lo ves...",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger03_010"] = "¿Por qué hicieron tan pequeños estos asientos?",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger03_030"] = "Me gustaría que el Director General probara volar en clase turista durante 24 horas.",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger04_010"] = "¿Tan caro y me restringen el servicio de bebidas? Al carajo...",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger04_020"] = "Si las aerolíneas pudieran salirse con la suya.",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger04_040"] = "Pienso que podemos convertir esto en un reality show... \"Vuela o muere\"",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger05_010"] = "Ya quiero aterrizar en \"Frisco\".",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger06_020"] = "Ya nadie le dice \"Frisco\". No uses ese apodo.",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger07_010"] = "Aterrizaremos pronto... pronto... pronto...",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger07_020"] = "Por favor, que aterricemos pronto...",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger08_010"] = "(silbando)",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger08_030"] = "¿Te importaría no hablarme?",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger09_020"] = "¿Te importaría no silbar?",
  ["Cue_E5_3A_Plane_ChitChat02_IGE_Passenger10_010"] = "Veamos... 10 horizontal, seis letras... \"Azul\". ¿Cómo demonios se supone que adivine eso?",
  ["Cue_E5_3A_Plane_Extraction_Captain_010"] = "Abróchense el cinturón y guarden sus equipos electrónicos hasta que el avión aterrice y se encuentre en la puerta. Gracias. Comenzaremos nuestro descenso en pocos minutos...",
  ["Cue_E5_3A_Plane_Extraction_Captain_020"] = "Es un día hermoso en San Francisco, con cielo despejado y temperatura fresca de 15 grados. Esperamos que hayan disfrutado su viaje y les agradecemos elegir a PacificWest Air. Viajen con nosotros cuando gusten.",
  ["Cue_E5_3A_Plane_Extraction_Max_040"] = "¿Qué tal durmió?",
  ["Cue_E5_3A_Plane_Extraction_Max_060"] = "Solo un poco.",
  ["Cue_E5_3A_Plane_Extraction_Max_080"] = "Lo entiendo perfectamente, director Wells.",
  ["Cue_E5_3A_Plane_Extraction_Max_100"] = "Ya lo es, y ni siquiera hemos llegado.",
  ["Cue_E5_3A_Plane_Extraction_Principal_030"] = "Oh, no lo creo...|Espero que hagan los asientos tan pequeños, que ya nadie tenga que viajar en esta aerolínea.",
  ["Cue_E5_3A_Plane_Extraction_Principal_050"] = "Espero no haber roncado demasiado, Max...",
  ["Cue_E5_3A_Plane_Extraction_Principal_070"] = "Ha sido una semana difícil en Blackwell, espero que me perdones.|Entre el Sr. Jefferson y los Prescott, las cosas han sido agitadas... por decir poco.",
  ["Cue_E5_3A_Plane_Extraction_Principal_090"] = "Es una manera inteligente de decirme que deje de quejarme. Nos enorgullece que representes a Blackwell en el concurso Héroes Cotidianos. Sé que no soy precisamente el mentor que querías en San Francisco. Pero todos te deseamos una gran experiencia aquí.",
  ["Cue_E5_3A_Plane_Insertion_Max_010"] = "Wow...",
  ["Cue_E5_3A_Plane_Insertion_Max_020"] = "Chloe... Oh, estás viva... Estás viva...",
  ["Cue_E5_3A_Plane_Insertion_Max_025"] = "Lo hice...",
  ["Cue_E5_3A_Plane_Insertion_Max_030"] = "Arreglé todo.",
  ["Cue_E5_3A_Plane_Insertion_Max_040"] = "Vaya...",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Passenger09_020"] = "¿Por qué? no es como si fuéramos a chocar.",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Passenger09_040"] = "Uy, espero que no me arresten.",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Stewardness_010"] = "Discúlpeme, señor, debe apagar su teléfono antes de que descendamos.",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Stewardness_030"] = "Son las reglas de la FCC, señor.",
  ["Cue_E5_3A_Plane_Stewardness_IGE_Stewardness_050"] = "Por favor, apague el teléfono, señor.",
  ["Act_E5_3B_ArtGallery_ArtBook01_Look01_Max_010"] = "La Galería Zeitgeist tiene una historia genial en \"Frisco\"... quiero decir, San Francisco.",
  ["Act_E5_3B_ArtGallery_ArtBook02_Look01_Max_010"] = "Quisiera tener tiempo para ver aquellos murales...",
  ["Act_E5_3B_ArtGallery_ArtFlyer01_Look01_Max_010"] = "¡Mierda! Este folleto se diseñó justo para Chloe. Me pregunto si estoy lista para el \"moshing\"...",
  ["Act_E5_3B_ArtGallery_ArtFlyer02_Look01_Max_010"] = "¡Qué divertido! Warren sí se volvería chango con este programa.",
  ["Act_E5_3B_ArtGallery_ArtFlyer03_Look01_Max_010"] = "La revolución no será televisada...",
  ["Act_E5_3B_ArtGallery_ArtFlyer04_Look01_Max_010"] = "Me encanta cuántas obras de arte hay en toda la bahía... no como en Arcadia Bay.",
  ["Act_E5_3B_ArtGallery_ArtFlyer05_Look01_Max_010"] = "¿Pero qué me podría?",
  ["Act_E5_3B_ArtGallery_ArtFlyer06_Look01_Max_010"] = "Es mejor que algunos misterios sigan siendo misterios...",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_010"] = "No puedo creer que estoy en San Francisco...",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_020"] = "¿Cómo puedo procesar esto después de toda la muerte que he visto esta semana?",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_030"] = "Quisiera que Chloe estuviera conmigo ahora...",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_040"] = "Sin ella no podría haber peleado contra Jefferson...",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_050"] = "Y ella siempre me impulsó a no ser tímida sobre mis fotos...",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_060"] = "Aún si eso se siente tan trivial después de lo que le pasó a Rachel... y a Kate.",
  ["Act_E5_3B_ArtGallery_Bench_Zen_Max_070"] = "Pero sea cual sea el motivo por el que tengo este poder,|espero finalmente haberlo usado bien.",
  ["Act_E5_3B_ArtGallery_CHPrincipalWells_Look01_Max_010"] = "Fue genial que el director Wells viniera. Podría haber cancelado nuestras inscripciones después de lo que ocurrió con Jefferson.",
  ["Act_E5_3B_ArtGallery_Camera_Look01_Max_010"] = "Mhhh, se ve familiar... Podría ser demasiado meta-metafórico...",
  ["Act_E5_3B_ArtGallery_Champagne_Look01_Max_010"] = "La champaña me recuerda cuando Chloe y yo nos embriagamos...",
  ["Act_E5_3B_ArtGallery_DifficultFocus_Scripted_Max_010"] = "Literalmente, no tengo tiempo para tratar con todos...",
  ["Act_E5_3B_ArtGallery_DifficultFocus_Scripted_Max_020"] = "¡Enfócate, Max! ¡Chloe te necesita ahora!",
  ["Act_E5_3B_ArtGallery_DifficultFocus_Scripted_Max_030"] = "Zen, Max, zen... No hay nadie aquí más que tú... nadie...",
  ["Act_E5_3B_ArtGallery_DonationBox_Look01_Max_010"] = "Debería aportar mucho dinero para la causa.",
  ["Act_E5_3B_ArtGallery_DownstairExhibitText_Look01_Max_010"] = "Eso se ve genial... pero no sé mucho acerca de escultura...",
  ["Act_E5_3B_ArtGallery_DownstairExhibitWork01_Look01_Max_010"] = "Me encantaría tener esto en una repisa... algún día.",
  ["Act_E5_3B_ArtGallery_DownstairExhibitWork02_Look01_Max_010"] = "Esa pieza es algo tonta...",
  ["Act_E5_3B_ArtGallery_DownstairExhibitWork03_Look01_Max_010"] = "Me gusta. ¿Pero cuánto tiempo tomará hacer una escultura?",
  ["Act_E5_3B_ArtGallery_ExhibitIntro_Look01_Max_010"] = "Aún no puedo creer que me incluyeran en esta muestra...",
  ["Act_E5_3B_ArtGallery_Food01_Look01_Max_010"] = "Supongo que tengo que acostumbrarme a la idea de comida elegante que no quiero comer.",
  ["Act_E5_3B_ArtGallery_Food02_Look01_Max_010"] = "Aaaah, ese postre de fruta se ve delicioso...",
  ["Act_E5_3B_ArtGallery_GuestBook_Look01_Max_010"] = "Es genial leer todos esos comentarios... Incluso los negativos.",
  ["Act_E5_3B_ArtGallery_Hipster01_Look01_Max_010"] = "Quizá sea un hipster, pero aprecia las fotos...",
  ["Act_E5_3B_ArtGallery_Hipster02_Look01_Max_010"] = "Es linda. Me pregunto qué tipo de estilo tendrá en unos cuantos años...",
  ["Act_E5_3B_ArtGallery_IntroLines_Scripted_Max_010"] = "Vaya, Max... lo hiciste. De algún modo...",
  ["Act_E5_3B_ArtGallery_IntroLines_Scripted_Max_020"] = "Vine desde el cuarto oscuro... a esta galería. He estado en varias realidades en una semana. La vida es... rara.",
  ["Act_E5_3B_ArtGallery_MaxLabel_Look01_Max_010"] = "\"Ventanas\"... por Maxine Caulfield... 2013... ¿MAXINE? Les dije que era \"Max\".",
  ["Act_E5_3B_ArtGallery_MaxPicture_Look01_Max_010"] = "Lo hiciste, Max... Eres una verdadera artista. Por lo menos hoy.",
  ["Act_E5_3B_ArtGallery_NeonArt_Look01_Max_010"] = "No es mi estilo, pero el neón es una buena representación...|Mierda, alerta de pretenciosas.",
  ["Act_E5_3B_ArtGallery_Newspaper01_Look01_Max_010"] = "Joven grunge... Recordará esos días el resto de su vida en prisión.|Bien.",
  ["Act_E5_3B_ArtGallery_Newspaper02_Look01_Max_010"] = "Vaya, un artículo de Danny Lee...",
  ["Act_E5_3B_ArtGallery_Newspaper02_Look02_Max_020"] = "Vaya, un artículo de Danny Lee...",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_010"] = "Tranquila, Max. Sonríe y no digas nada estúpido.",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_020"] = "No sé si me agrada tanta atención...",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_030"] = "Vamos, Max. Chloe finalmente está segura, Jefferson está acabado y tu foto está en una exposición en San Francisco.",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_040"] = "¿Cómo dicen en Blade Runner? \"Deléitate en tu vida...\"",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_050"] = "Probablemente debería por lo menos ver mi foto y cómo se ve en la pared de una galería real. ¿Quién sabe cuándo podría ocurrir de nuevo?",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_060"] = "Siempre puedo acudir al director Wells si necesito hablar con alguien... Me sorprende lo agradable que es fuera del campus...",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_070"] = "Tengo que apreciar mi vida después de todo lo que ocurrió esta semana.",
  ["Act_E5_3B_ArtGallery_ObjectiveLines01_Scripted_Max_080"] = "Quizás necesito darle un \"tiempo fuera\" a mi poder de rebobinado... al diablo.",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_010"] = "De ningún modo... Chloe no puede morir de nuevo... tengo que salvarla.",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_020"] = "No, por favor... tengo que estar en Arcadia Bay para ayudar a Chloe... no aquí.",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_040"] = "Mi foto del concurso... Puede que sea la única forma de regresar.",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_060"] = "Habrá otro concurso, Max... pero no otra Chloe...",
  ["Act_E5_3B_ArtGallery_ObjectiveLines02_Scripted_Max_070"] = "Si rebobino hasta la foto del concurso y la destruyo... definitivamente terminaré en Arcadia Bay, no en San Francisco...",
  ["Act_E5_3B_ArtGallery_Receptionist_Look01_Max_010"] = "Nunca pensé que hablaría con una recepcionista de una galería acerca de mi propia obra. Genial.",
  ["Act_E5_3B_ArtGallery_SFCityMap_Look01_Max_010"] = "Me encanta esta mapa de la ciudad... es tan romántico...",
  ["Act_E5_3B_ArtGallery_SFLook_Look01_Max_010"] = "Podría tomar tantas fotos épicas en cualquier lugar de la ciudad...",
  ["Act_E5_3B_ArtGallery_SubmarineFlyer_Look01_Max_010"] = "Me pregunto cómo sería vivir en un submarino como ese... Debe ser realmente claustrofóbico...",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_010"] = "Ah, vaya, esto es increíble.",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_020"] = "No puedo creer que mi foto esté en la misma sala que todas estas fotografías increíbles.",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_030"] = "Quiero mudarme a esta galería.",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_040"] = "Me encanta que Jack Kerouac y la Generación del Beat recorrieran este mismo vecindario. Qué padre.",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_050"] = "Todo es tan amplio y espacioso... la iluminación es perfecta.",
  ["Act_E5_3B_ArtGallery_ThoughtLines_Scripted_Max_060"] = "Cuánto cobraría si alguien quisiera comprar mi foto... cálmate, \"Max Warhol\".",
  ["Act_E5_3B_ArtGallery_WinnerList_Look01_Max_010"] = "Aquí estoy. Junto con los demás ganadores. Debería decir \"artistas\".",
  ["Act_E5_3B_ArtGallery_ZeitgeistLogo_Look01_Max_010"] = "\"La Galería Zeitgeist... presenta a Max Caulfield\". En fin, esto es realmente genial.",
  ["Cue_E5_3B_ArtGallery_ArtTalk01_IGE_Woman02_020"] = "¿Cuánto pagaría por eso?",
  ["Cue_E5_3B_ArtGallery_ArtTalk01_IGE_Woman02_040"] = "Supongo que ahora todos se sienten fotógrafos.",
  ["Cue_E5_3B_ArtGallery_ArtTalk03_IGE_Man05_010"] = "Esto me hace sentir tan triste...",
  ["Cue_E5_3B_ArtGallery_ArtTalk03_IGE_Man05_020"] = "Como si volviera a la preparatoria...",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Man06_010"] = "¿Cómo pueden costear la renta estas galerías?",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Man09_010"] = "Me pregunto si puedo comprar estas fotografías de Héroes Cotidianos...",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Woman05_010"] = "De verdad no entiendo el arte.",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Woman06_010"] = "Dios, amo el arte...",
  ["Cue_E5_3B_ArtGallery_ArtTalk04_IGE_Woman07_010"] = "Siempre me inspiro cuando vengo aquí...",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Man01_010"] = "Disculpa, me encantaría hacerte algunas preguntas acerca de tu trabajo...",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Man02_030"] = "Ah, hola... me encanta tu fotografía.",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Woman01_020"] = "Ah, eres Max Caulfield, ¿cierto? ¡Dime qué tipo de cámara instantánea usas!",
  ["Cue_E5_3B_ArtGallery_Babblers_IGE_Woman02_040"] = "Ay, Dios mío, ¿tienes una hora libre para hablar conmigo?",
  ["Cue_E5_3B_ArtGallery_CHMan01_QPhase01_Man01_001"] = "Eh, hola... Tú eres la que inscribió el autorretrato. ¿Una \"selfi\", no?|En fin, me impresionó cómo la presentaste, para hacer que todos tus modelos fueran el foco de tu obra... Brillante.",
  ["Cue_E5_3B_ArtGallery_CHMan02_QPhase01_Man02_001"] = "Vaya, tú tomaste ese selfi... muy bueno. Si quieres, podemos fumar un poco de hierba después de la muestra...",
  ["Cue_E5_3B_ArtGallery_CHMan04_QPhase01_Man04_001"] = "¿Eres Max Caulfield? Bravo por tu obra. Soy crítico de arte para la revista Iris-In y nos encantaría incluirte en un artículo sobre los futuros íconos de la fotografía. Te enviaré la información esta semana, si te parece. Felicitaciones por tu obra.",
  ["Cue_E5_3B_ArtGallery_CHMan05_QPhase01_Man05_001"] = "Normalmente, este tipo de concursos... eh... me dan mucho sueño... pero me gusta cómo esta exposición se trata de acciones específicas, ¿sabes? No solo \"abstracciones\". Zeitgeist está creando obras únicas este año.",
  ["Cue_E5_3B_ArtGallery_CHMan06_QPhase01_Man06_001"] = "Eres una de los finalistas, ¿cierto? ¡Yo también! Esto es increíble, ¿no? Será un impulso muy fuerte para nuestra obra.",
  ["Cue_E5_3B_ArtGallery_CHMan09_QPhase01_Man09_001"] = "Lo siento, no sé tu nombre, pero vi tu foto en el folleto de la galería y quería decirte que tu pieza es genial.",
  ["Cue_E5_3B_ArtGallery_CHMan10_QPhase01_Man10_001"] = "Bien, debo admitir que esta es la mejor exposición de Héroes Cotidianos que he visto desde que comenzó. Todas las fotografías dicen mucho acerca de nuestros tiempos... Bravo.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_MaxUnderwear_012"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_MaxUnderwear_012",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_001",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_004"] = "Aún no me siento como una fotógrafa famosa...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_007"] = "Es algo irreal estar aquí después de todo lo que pasó en Blackwell...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_008"] = "No lo sé... Es solo suerte. No soy una fotógrafa de verdad aún.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_010"] = "Quizás me siento culpable por celebrar...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_013"] = "Mark Jefferson era bueno para ocultar sus huellas... Nos engañó a todos.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_016"] = "No es su culpa. No sabía lo que ocurría realmente.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_017"] = "Le dije que Nathan estaba involucrado... Aunque no esperaba que me creyera...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_018"] = "Debí haberle dicho que Nathan trajo una pistola a la escuela esta semana. Quizá las cosas habrían sido diferentes.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_022"] = "Al menos ahora está en la cárcel con Nathan, por secuestro y asesinato...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_024"] = "Ahora bien, si supiéramos qué ocurre con el clima... quizás todo sería como antes...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_025"] = "Me gustaría pensar que se trata del karma... Los Prescott se lo merecían.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Max_028"] = "Espero que esto sea un nuevo comienzo, director Wells.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_003"] = "Entonces, ¿qué tal llevas tu nueva fama de fotógrafa estrella?",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_005"] = "Cada viaje comienza con el primer paso. Solo soy un burócrata de Blackwell, no un artista, pero nos enorgulleces a todos con la gran repercusión de tu obra.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_006"] = "Otro motivo más para celebrar tu éxito...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_009"] = "No te subestimes, Max.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_011"] = "Eso déjamelo a mí...|Debí haber sido más proactivo sobre Kate Marsh y su espantosa situación.|Ella es fuerte y me da gusto que lograra salir de ese infierno. Debí haber sido más duro con Nathan Prescott... Mejor dicho, haberlo golpeado duro.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_014"] = "Sobre todo a mí. Como sabrás, tengo una debilidad por el prestigio.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_015"] = "Y Jefferson tenía una reputación excelente.|Nadie esperaba que estuviera tan... trastornado. No podía creer que la policía encontrara fotografías tan psicóticas en su \"cuarto oscuro\". Pobres chicas...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_019"] = "Lo sé, pero... no es una buena excusa para un Director.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_020"] = "Lamentaré eso durante el resto de mi vida, Max. Los Prescott sabían proteger a los suyos.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_021"] = "Quizás no... probablemente no habría creído que lo hizo... los Prescott tienen una manera de conseguir lo que quieren... ¿o debería decir, \"tenían\"?",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_023"] = "Y Sean Prescott ahora está bajo investigación por todos sus años de corrupción.|El dinero y el poder solo te protegen durante un tiempo en Arcadia Bay.|Lo irónico es que esta vez Sean Prescott no tenía idea de quién era Jefferson en realidad...|Incluso lo trajo a Blackwell.",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_026"] = "La ciencia ambiental está más allá de mi entendimiento, Max. Pero seguramente sería bueno que la Academia Blackwell fuera como antes...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_027"] = "Creo que \"lo que siembras, cosechas\". Solo espero que sea algo bueno, para variar...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_Phase01_Principal_029"] = "Como dije antes, eres adulta, Max. Puedes llamarme Ray. Por lo menos durante este evento. Ahora, si me disculpas, el buffet clama mi presencia...",
  ["Cue_E5_3B_ArtGallery_CHPrincipal_QPhase01_Principal_001"] = "Discúlpame, Max. Debo llamar a mi esposa y decirle que no he roto la dieta. No me acuses, por favor.",
  ["Cue_E5_3B_ArtGallery_CHReceptionist_QPhase01_Receptionist_002"] = "¡Buenos días! Tú debes ser Max Caulfield. ¡Felicidades por tu foto en Héroes Cotidianos! La exhibición es bastante impresionante, especialmente con tu participación.",
  ["Cue_E5_3B_ArtGallery_CHWoman01_QPhase01_Woman01_001"] = "¿Vienes de la Academia Blackwell? Quería entrar allí, pero no pude hacerlo... Tienen un programa genial. Apuesto a que estás aprendiendo mucho.",
  ["Cue_E5_3B_ArtGallery_CHWoman04_QPhase01_Woman04_001"] = "Señorita Caulfield, soy de la oficina de admisiones en UC Berkeley y me encantaría hablar con usted acerca de un nuevo entorno académico más tarde el día de hoy... de ser posible.",
  ["Cue_E5_3B_ArtGallery_CHWoman06_QPhase01_Woman06_001"] = "Debes ser la heroína cotidiana de Blackwell...|Mi nombre es Lauren Francis y estoy a cargo del Departamento de Medios de la Escuela de Artes Visuales de Detroit. Me encantaría hablar contigo acerca de una residencia la próxima primavera... No le digas nada al director Wells. Aún.",
  ["Cue_E5_3B_ArtGallery_CHWoman07_QPhase01_Woman07_001"] = "Oye, me encanta tu toma. Solo quería felicitarte. ¡Espero que recibas mucha atención!",
  ["Cue_E5_3B_ArtGallery_CHWoman08_QPhase01_Woman08_001"] = "Disculpa, solo quería decirte cuánto me encanta tu fotografía. He visto mucho hoy, pero hay algo poderoso y subestimado en la tuya. No puedo esperar a ver mucho más de tu trabajo en el futuro...",
  ["Cue_E5_3B_ArtGallery_CHWoman10_QPhase01_Woman10_001"] = "Te ves como si estuvieras perdida. Sé que una ciudad tan grande como San Francisco puede ser intimidante si vienes de un lugar tan pequeño como Arcadia Bay. Sin ánimo de ofender.",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Daughter_040"] = "Eh, papá, la tarjeta dice que esta es una impresión de una cámara desechable, ¿de qué hablas?",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Daughter_060"] = "como sea...",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Father_010"] = "Mira esta impresión, la profundidad de campo, los colores, mira la forma de bokeh... definitivamente fue tomada con una cámara de formato medio y una lente Leica de 35 mm. Puedes encontrar todos esos detalles, la historia de una fotografía... si sabes cómo ver los detalles de una imagen.",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Father_030"] = "Emma, ¿alguna vez te conté que cuando era más joven hice muchos estudios fotográficos? Era bastante bueno, pero decidí dejar la fotografía para dedicarme a un trabajo que me diera un mejor sueldo... de cualquier modo, es interesante estar aquí y tienes suerte de estar aquí conmigo. Así puedo compartir todo esto contigo.",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Father_050"] = "Ah, sí, por supuesto, quise decir una cámara desechable Leica, claro... y de todos modos no me contradigas...",
  ["Cue_E5_3B_ArtGallery_FamilyDiscussion_Wife_020"] = "Ah, qué interesante, Matthew, no pensé que supieras tanto sobre el tema.",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_010"] = "San Francisco es tan genial... y esta galería es tan grande...",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_030"] = "Siempre que no me obliguen a comer caviar...",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_050"] = "No lo sé... Me siento tan rara. Como una niña pequeña entre adultos.",
  ["Cue_E5_3B_ArtGallery_Insertion_Max_090"] = "Vamos, Max... Después de todo lo que ha ocurrido, esto debería ser lo menos atemorizante de tu vida.",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_020"] = "También el buffet. Si un evento escatima en comida, sabes que no vale la pena.",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_040"] = "Este es tu día, Max. Haz lo que quieras. Aprovecha tu status y habla con tantas personas influyentes como puedas. Relaciónate con ellos.",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_060"] = "Max, después de esta semana, ciertamente ya no eres una niña pequeña. De hecho, eres una adulta notable y honrada por sus pares. Ahora debes comenzar a actuar como la fotógrafa que quieres ser.",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_070"] = "Demonios, yo quería estar a cargo de una escuela importante algún día,|así que comencé a trabajar en ello de joven. Pregunta a mis pobres compañeros de clase.",
  ["Cue_E5_3B_ArtGallery_Insertion_Principal_080"] = "Max, voy a hacerte un favor e ir a comer el caviar. Ve a codearte con los famosos. Como sabes, no siempre estaré aquí para hacerme cargo. Pero estoy a tu servicio cuando me necesites.",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Man04_010"] = "Se suponía que Mark Jefferson estaría aquí hoy...",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Man04_030"] = "Fue tan impactante... también tengo una de sus monografías...",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Woman04_020"] = "Ya no.",
  ["Cue_E5_3B_ArtGallery_JeffersonTalk_IGE_Woman04_040"] = "Consérvala... su trabajo valdrá mucho dinero...",
  ["Cue_E5_3B_ArtGallery_Journalist_Danny_010"] = "Hola, disculpa, eres Max Caulfield, ¿cierto?",
  ["Cue_E5_3B_ArtGallery_Journalist_Danny_030"] = "Siento molestarte, mi nombre es Danny Lee, del Berkeley People’s Herald. Soy editor de la sección de arte y me encanta tu trabajo.",
  ["Cue_E5_3B_ArtGallery_Journalist_Danny_040"] = "Sé que todo el asunto del \"selfi irónico\" está algo desgastado, pero hay algo... atemporal en tus imágenes. Así que me encantaría concertar una cita o una entrevista cuando tengas oportunidad. Ten mi tarjeta... fue un honor, Max.",
  ["Cue_E5_3B_ArtGallery_Journalist_Max_020"] = "Eh... sí, claro. Sí...",
  ["Cue_E5_3B_ArtGallery_Journalist_Max_050"] = "Igualmente, Danny.",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_010"] = "Lo siento, pero...",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_020"] = "¿Podemos hablar después? Gracias...",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_030"] = "Ahora no puedo...",
  ["Cue_E5_3B_ArtGallery_MaxAnswers_IGE_Max_050"] = "Gracias, pero estoy ocupada...",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Man01_010"] = "Sé que es simple, pero lo encuentro cautivador...",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Man01_030"] = "¿Quién es el artista?",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Man01_050"] = "Es genial. Parece muy madura...",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Woman01_020"] = "¿Verdad? La impresión instantánea hace que parezca atemporal... melancolía nostálgica.",
  ["Cue_E5_3B_ArtGallery_MaxWork_IGE_Woman01_040"] = "Una chica adolescente... creo que es para algún concurso.",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer1_010"] = "... es diferente... me encanta la vibra retro...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer1_050"] = "Ey, y aquí está para salvar el día...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer1_090"] = "Oye, ¿estás bien? Te perdimos durante un segundo...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer2_020"] = "A mí también. Me hace querer ir a comprar una cámara instantánea. Pero, diablos, apuesto a que la película cuesta una fortuna...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer2_100"] = "¡Ay, tu nariz!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Admirer4_040"] = "Aquí en la placa dice: \"Max Caulfield: Héroe Cotidiano\"...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Chloe_150"] = "¡Max! ¡Carajo! ¡Tu visión! ¡Es verdad! ¡Viste el tornado! ¡Está llegando!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Chloe_170"] = "¡Estoy tan asustada! Estoy... Estoy en la playa. No puedo salir de...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_060"] = "Hola.",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_080"] = "¡Chloe!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_110"] = "Estoy bien... El cambio de horario... La altitud...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_130"] = "¡Dejaste apagado el timbre, idiota!",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_140"] = "Vamos... Por favor, contesta...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_160"] = "¿Qué? Ay, no, Chloe... ¿dónde estás?",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_180"] = "¡Chloe! ¿Puedes oírme? ¿Hola?",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_190"] = "¿Hola?",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_200"] = "Dios mío, el tornado era real... No arreglé nada...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_210"] = "Chloe morirá... Arcadia Bay será destruida...",
  ["Cue_E5_3B_ArtGallery_PhotoLook_Max_220"] = "Tiene que haber una forma de detener esto... de una buena vez.",
  ["Cue_E5_3B_ArtGallery_Weirdo_IGE_Man11_010"] = "Mala exposición... mal encuadre... mala fotografía...",
  ["Cue_E5_3B_ArtGallery_Weirdo_IGE_Man11_020"] = "A mí me habría salido mucho mejor...",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_010"] = "Siento que se me parte la cabeza... pero debo hacer esto... Tengo que hacerlo...",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_020"] = "Solo necesito estar allí para salvar a Chloe de la tormenta.",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_040"] = "Max, no arruines esta línea de tiempo... Ya casi terminas.",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_050"] = "Dios, me siento tan débil... Más me vale hacer esto antes de desmayarme...",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_060"] = "Mi línea de tiempo anterior era tan perfecta... excepto que necesitaba estar en Arcadia Bay, no en San Francisco.",
  ["Act_E5_4A_MaxRoom_ObjectiveLines_Scripted_Max_070"] = "¿Qué sucede ahora? Se siente como si la realidad... se rompiera... ¿Qué le estoy haciendo al tiempo?",
  ["Act_E5_4A_MaxRoom_Photo_Look01_Max_010"] = "Claro, no ganaré el concurso si destruyo la foto... pero podré salvar a Chloe.",
  ["Act_E5_4A_MaxRoom_Photo_Look02_Max_020"] = "Solo tengo que hacer un simple cambio para no terminar en San Francisco... Simple.",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_010"] = "Oh, mierda... Oh, mi cabeza...",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_020"] = "Seré aplastada en el tiempo...",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_030"] = "¡Haz algo, Max!",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_050"] = "Ahora definitivamente no entraré al concurso...",
  ["Cue_E5_4A_MaxRoom_Insertion_Max_060"] = "Lo siento, San Francisco, Chloe es más importante.",
  ["Cue_E5_5A_TownDestroy_NathanMessage_AnsweringMachine_010"] = "Tiene un nuevo mensaje. Mensaje recibido ayer a las 21:00.",
  ["Cue_E5_5A_TownDestroy_NathanMessage_Limpbow_010"] = "... ¡Lo advertí! ¡Durante años he anunciado que nuestros pecados y arrogancia desatarían la ira de Dios contra nosotros!",
  ["Cue_E5_5A_TownDestroy_NathanMessage_Limpbow_020"] = "¡Y ahora soy la única persona atrapada en esta puta estación de radio! ¡Que alguien me saque de aquí! ¡Rápido, con un carajo! ¿Para qué pago impuestos...?",
  ["Cue_E5_5A_TownDestroy_NathanMessage_Nathan_030"] = "Max... soy Nathan, solo quería decir... lo siento... no quería lastimar a... Kate... o a Rachel... no quería lastimar a nadie... Todos me usaron... El Sr. Jefferson viene por mí ahora. Toda esta mierda acabará pronto... Cuídate, Max... él te lastimará... lo siento mucho...",
  ["Act_E5_5C_DinerPark_BlockedEntrance_Scripted_Max_010"] = "Maldición, por aquí está bloqueado... Ahora necesito encontrar otra forma de entrar al restaurante.",
  ["Act_E5_5C_DinerPark_DeadWhale_Look01_Max_010"] = "Mira eso... Este tornado podría ser el fin del mundo... pero no si puedo cambiarlo.",
  ["Act_E5_5C_DinerPark_ExplosionLines_Scripted_Max_010"] = "¡No! ¡No!",
  ["Act_E5_5C_DinerPark_ExplosionLines_Scripted_Max_020"] = "¡Esto no puede pasar! ¡Tengo que apagar ese incendio!",
  ["Act_E5_5C_DinerPark_FireWarn_Scripted_Max_010"] = "Espera, un incendio viene hacia aquí, primero necesito hacer algo al respecto.",
  ["Act_E5_5C_DinerPark_Fire_Look01_Max_010"] = "¡Vamos, Max! ¡Apaga ese incendio!",
  ["Act_E5_5C_DinerPark_HomelessWoman_Look01_Max_010"] = "Oh, no... No ella... Debí advertirle... Ni siquiera le pregunté su nombre... Qué egoísta.",
  ["Act_E5_5C_DinerPark_HomelessWoman_Look01_Max_015"] = "Vaya, no está aquí... Espero que esté en un refugio... Ni siquiera le pregunté su nombre...",
  ["Act_E5_5C_DinerPark_Newspaper01_Look01_Max_010"] = "Acábalos, Juliet...",
  ["Act_E5_5C_DinerPark_Newspaper02_Look01_Max_010"] = "Los monstruos en realidad son las personas que están aquí...",
  ["Act_E5_5C_DinerPark_NewspaperDispenser_Look01_Max_010"] = "Malas noticias...",
  ["Act_E5_5C_DinerPark_ObjectiveLines04_Scripted_Max_010"] = "¡Ay no... ese incendio se propaga al restaurante! ¡Haz algo!",
  ["Act_E5_5C_DinerPark_OfficerBerry_Look01_Max_010"] = "Ay, no... el oficial Berry murió antes de que pudiera ayudarle... ahora es demasiado tarde.",
  ["Act_E5_5C_DinerPark_Sand_Look01_Max_010"] = "Por favor, que esta arena apague el fuego...",
  ["Act_E5_5C_DinerPark_Trucker_Look01_Max_010"] = "¡Hey, ese tipo está atrapado! Tengo que ayudar a todos los que pueda...",
  ["Act_E5_5C_DinerPark_TwoWhalesBoard_Look01_Max_010"] = "Quisiera que la vida fuera de nuevo simples huevos con tocino...",
  ["Act_E5_5C_DinerPark_TwoWhalesNeon_Look01_Max_010"] = "Nunca pensé que vería así el Two Whales...",
  ["Act_E5_5C_DinerPark_WarrenCar_Look01_Max_010"] = "El auto de Warren es prácticamente lo único intacto... Bien.",
  ["Act_E5_5C_Diner_Booth_Zen_Max_010"] = "Max... date un momento para no hacer nada...",
  ["Act_E5_5C_Diner_Booth_Zen_Max_020"] = "Aquí es donde convencí a Chloe de que podía rebobinar el tiempo.",
  ["Act_E5_5C_Diner_Booth_Zen_Max_030"] = "Entonces cuál es la razón de este poder... cuál es la lección...",
  ["Act_E5_5C_Diner_Booth_Zen_Max_040"] = "¿Seguir corrigiendo lo que sigo arruinando?",
  ["Act_E5_5C_Diner_Booth_Zen_Max_050"] = "No, porque yo no pedí este \"don\"...",
  ["Act_E5_5C_Diner_Booth_Zen_Max_060"] = "Pero pude detener a Mark Jefferson...",
  ["Act_E5_5C_Diner_Booth_Zen_Max_070"] = "Y ahora puedo evitar que Chloe muera...",
  ["Act_E5_5C_Diner_Booth_Zen_Max_080"] = "... por última vez.",
  ["Act_E5_5C_Diner_CHFrank_Look01_Max_010"] = "Es bueno tener a Frank en nuestro equipo...",
  ["Act_E5_5C_Diner_CHFrank_Look01_Max_015"] = "Quisiera que Frank estuviera en nuestro equipo... no es un mal tipo.",
  ["Act_E5_5C_Diner_CHJoyce_Look01_Max_010"] = "Joyce apoya a todos... incluso a Frank.",
  ["Act_E5_5C_Diner_CHJoyce_Look01_Max_015"] = "Joyce apoya a todos...",
  ["Act_E5_5C_Diner_CHWarren_Look01_Max_010"] = "Mira a Warren, siempre intentando ayudar...",
  ["Act_E5_5C_Diner_CHWarren_Look02_Max_015"] = "Por lo menos besé a Warren una vez para que sepa lo que siento...",
  ["Act_E5_5C_Diner_CHWarren_Look02_Max_020"] = "Espero que Warren sepa cuánto significa su amistad para mí...",
  ["Act_E5_5C_Diner_CHWarren_Look02_Max_025"] = "Me gusta cómo Warren solo hace lo que debe sin importar lo que pase...",
  ["Act_E5_5C_Diner_CanStock_Look01_Max_010"] = "Por lo menos nadie va a morir de hambre aquí...",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_010"] = "Joyce es la veradera santa de Arcadia Bay... Apoya a todos...",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_020"] = "Quisiera que Joyce estuviera con David ahora... Los dos merecen algo de paz.",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_030"] = "Me gusta que Warren solo hace lo que debe... sin importar los obstáculos.",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_040"] = "Me cuesta creer que mi gran dilema hace unos días era \"¿un waffle o un omelette?\"...",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_050"] = "He pasado por tantas vidas esta semana...",
  ["Act_E5_5C_Diner_DinerIdleLines_Scripted_Max_060"] = "Bien, no lo pienses más, obtén esa foto...",
  ["Act_E5_5C_Diner_FirstAidSupplies_Look01_Max_010"] = "Buen trabajo, Warren... espero que esos suministros sean suficientes...",
  ["Act_E5_5C_Diner_Jukebox_Look01_Max_010"] = "No más música...",
  ["Act_E5_5C_Diner_Menu_Look01_Max_010"] = "Es difícil creer que había gente desayunando aquí hace solo unas horas...",
  ["Act_E5_5C_Diner_NoExitLines_Scripted_Max_010"] = "Max, no puedes irte hasta ver a Warren y obtener esa foto.",
  ["Act_E5_5C_Diner_ObjectiveLines05_Scripted_Max_010"] = "Me alegra que todos estén a salvo, ¡pero necesito la foto de Warren para ayudar a Chloe!",
  ["Act_E5_5C_Diner_Pompidou_Look01_Max_010"] = "Por lo menos Frank todavía tiene a Pompidou a su lado...",
  ["Act_E5_5C_Diner_VortexFlyer_Look01_Max_010"] = "La fiesta terminó... Este vortex es mucho más grande...",
  ["Act_E5_5C_StoreRoom_ArcadiaFlyer_Look01_Max_010"] = "Créeme, averiguaré cómo... Lo juro.",
  ["Act_E5_5C_StoreRoom_FisherMan_Look01_Max_010"] = "Quiero ayudar a ese pescador... pero está en shock y podría no oírme...",
  ["Act_E5_5C_StoreRoom_FisherMan_Look02_Max_020"] = "Oh, no...",
  ["Act_E5_5C_StoreRoom_Flyer01_Look01_Max_010"] = "Ay, esto me pone tan triste...",
  ["Act_E5_5C_StoreRoom_FuseBox_Look01_Max_010"] = "No me fallen, fusibles...",
  ["Act_E5_5C_StoreRoom_Magazine01_Look01_Max_010"] = "Si salimos de esta, Chloe...",
  ["Act_E5_5C_StoreRoom_ObjectiveLines02_Scripted_Max_010"] = "¿Cómo puedo salir de aquí?",
  ["Act_E5_5C_StoreRoom_ObjectiveLines03_Scripted_Max_010"] = "Bien, mejor voy rápido al restaurante. Necesito la foto de Warren.",
  ["Act_E5_5C_StoreRoom_Sprinkler_Look01_Max_010"] = "Bien, necesito encender la electricidad para activar el rociador...",
  ["Act_E5_5C_StoreRoom_StoreLines_Scripted_Max_010"] = "No, no puedo cruzar por aquí. ¿Podré rodear por otro lado?",
  ["Act_E5_5C_StoreRoom_StoreRoomFire_Look01_Max_010"] = "Maldición, estoy atorada aquí a menos que primero apague el incendio...",
  ["Act_E5_5C_Street_BrokenTablet_Look01_Max_010"] = "Misterio resuelto... pero nadie obtiene una recompensa...",
  ["Act_E5_5C_Street_CHAlyssa_Look01_Max_010"] = "Alyssa está atrapada en esa casa... ¡Tengo que sacarla rápido!",
  ["Act_E5_5C_Street_CHEvan_Look01_Max_010"] = "¿Evan, estás loco? ¡Sal ya de ahí!",
  ["Act_E5_5C_Street_CHEvan_Look02_Max_020"] = "Ay no... no, Evan... ¿Por qué no te agarré?",
  ["Act_E5_5C_Street_ChildrenDrawing_Look01_Max_010"] = "No... Me duele pensar en todos los niños que habrán por allí...",
  ["Act_E5_5C_Street_DeadPerson02_Look01_Max_010"] = "Oh, no soporto ver estos cuerpos...",
  ["Act_E5_5C_Street_DeadPerson03_Look01_Max_010"] = "La muerte está en todos lados... siguiéndome...",
  ["Act_E5_5C_Street_DerailedTrain_Look01_Max_010"] = "Mierda, ese tren podría haberse descarrilado contra el restaurante...",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_010"] = "¡Mierda, Alyssa necesita ayuda de nuevo!",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_020"] = "No Evan... tengo que evitar que se lastime...",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_030"] = "Está muerto... electrocutado...",
  ["Act_E5_5C_Street_HelpLines_Scripted_Max_040"] = "Tengo que sacar a este tipo de aquí o morirá...",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_020"] = "Sabes cómo usar tu poder... hazlo.",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_030"] = "Esta tormenta es... enorme. Sigue adelante...",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_040"] = "¡Necesito la foto de Warren para salvar a Chloe!",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_050"] = "De ningún modo dejaré morir a Chloe...",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_060"] = "Pero toda la ciudad está muriendo... ¿también soy responsable de eso?",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_070"] = "Tengo que aceptar que cambié más que el tiempo...",
  ["Act_E5_5C_Street_IdleLines_Scripted_Max_080"] = "Por favor, que Warren y Joyce estén bien... por favor...",
  ["Act_E5_5C_Street_ObjectiveLines01_Scripted_Max_010"] = "¡Warren está en el restaurante Two Whales, apúrate!",
  ["Act_E5_5C_Street_PanEstateFlyer_Look01_Max_010"] = "Ya no más...",
  ["Act_E5_5C_Street_Plank_Look01_Max_010"] = "Vamos, encuentra algún modo de ayudar a Alyssa.",
  ["Act_E5_5C_Street_StormStart_Scripted_Max_010"] = "Mira toda esta gente... toda esta destrucción... ¡Max, tú puedes ayudar!",
  ["Act_E5_5C_Street_WatchmenLogo_Look01_Max_010"] = "\"Que tengas un gran día\"... sí, claro. Pero alguien tiene que salvar al mundo.",
  ["Cue_E5_5C_Diner_AskPhoto_Max_020"] = "Está bien, lo importante es que estás a salvo... Después de lo que pasó con Nathan, sé que te sabes cuidar.",
  ["Cue_E5_5C_Diner_AskPhoto_Max_050"] = "Warren, vine por todos ustedes. Solo dime que tienes la fotografía.",
  ["Cue_E5_5C_Diner_AskPhoto_Max_070"] = "Cállate y escucha.",
  ["Cue_E5_5C_Diner_AskPhoto_Max_110"] = "Gracias por estar aquí. Como siempre.",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_010"] = "Odio decir que me da gusto verte, pero me da tanto gusto verte...",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_040"] = "Debí hacer eso hace mucho tiempo. Pero diablos, Max, no puedo creer que vinieras hasta aquí a mitad de un puto tornado E6 solo por una foto... Quiero decir, sé que no viniste por mí.",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_060"] = "Solo quiero...",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_080"] = "Ah, sí, finalmente me dirás lo que nunca terminaste de decir en el estacionamiento...",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_090"] = "Max... siento haberte metido en este... en este... no tengo la más remota idea de qué carajo ocurre. Pero tengo fe absoluta en que harás lo correcto cuando llegue el momento. Estoy tan orgulloso de ti, Max.",
  ["Cue_E5_5C_Diner_AskPhoto_Warren_100"] = "¿Qué momento podría ser más importante en la historia? Y estoy justo aquí... contigo. Así que gracias por confiar en mí...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_002"] = "Ya somos dos... si tan solo tuviera a Pompidou... y a Rachel...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_003"] = "Ya somos dos... si tan solo tuviera a Rachel de vuelta...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_006"] = "Oye, Max, ¿qué hay de la información que te di? ¿Chloe y tú encontraron qué le ocurrió?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_008"] = "Entonces aún hay esperanza... necesito descansar... estoy \"acabado\"... como Arcadia Bay... espero que Rachel esté muy lejos, tomando el sol... feliz... gracias por intentarlo, Max... En fin, solo nos resta esperar que el Señor nos acepte en Su Reino... o no.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_010"] = "¿Qué? Fuera del tornado, el agujero en mi pierna y la muerte de mi perro... por no mencionar que podría morir en el piso de un restaurante y que tú serías la última persona que vería... estoy genial. Cielos.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_011"] = "¿Qué? Fuera del tornado y el agujero en mi pierna... por no mencionar que podría morir en el piso de un restaurante y que tú serías la última persona que vería... estoy genial. Cielos.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_012"] = "Dios, no. Por favor, no... No Rachel... Ella no puede estar... ¿Estás segura? ¿Cómo lo sabes?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_013"] = "Jódete, Max. No. No es posible. Ella se fue del pueblo... se fue... ¿cómo lo sabes? ¿CÓMO?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_015"] = "¿Prescott? ¡Mierda, mierda! ¡Lo sabía! ¡Sabía que no debía juntarme con ese pinche cabrón! ¡Pompidou lo odiaba! ¿La viste? ¿Viste Rachel?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_016"] = "Y apuesto a que la ladrona Chloe y tú no encontraron a Rachel, ¿verdad?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_017"] = "Y apuesto a que Chloe y tú no encontraron a Rachel, ¿verdad?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_019"] = "¿A quién le importa una mierda ahora? Párate ahí para no ver cuando el Señor me lleve. Por favor, Max.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_022"] = "¿Cómo? ¿Cómo la mató?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_024"] = "¿Sobredosis? La única forma en que Nathan pudo hacer eso fue... porque le vendí. ¡Maté a mi leona! No...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_025"] = "¿Qué he hecho?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_027"] = "¿Dónde está el hijo de puta de Jefferson?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_030"] = "Rachel... Dios mío. Ella fue lo único bueno en mi vida, Max. Sé que era muy joven, y... sabía que terminaríamos, pero... no así. Jamás le habría impedido ir en busca de sus sueños.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_032"] = "Sabía que Chloe y ella... eran muy unidas. Estaba celoso.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_034"] = "A Rachel le importaban muchas personas... especialmente Chloe...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_035"] = "Pero... veo por qué le agradaba a Rachel... y ella era lo suficientemente valiente como para pedir ayuda después de toda la mierda que vivimos...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_037"] = "La única vez que hablé con mi padre, el bastardo citó la Biblia y dijo que quería \"entrar a casa justificado\"... en otras palabras, hacer lo correcto... yo también... y quizás me estás ayudando a lograrlo, Max...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Frank_038"] = "No me malinterpretes, aún pienso que eres rara... pero sí eres buena onda.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_001"] = "Frank... qué bueno que estás aquí...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_004"] = "Lo siento... no tuvimos tiempo de investigar cuando comenzó la tormenta...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_005"] = "Frank... no sé cómo decir esto... así que seré breve. Rachel está muerta.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_007"] = "Usamos los nombres que nos diste para encontrar una granja. Mi profesor, Mark Jefferson, tiene una sala fotográfica de tortura... y descubrimos que usaba a Nathan Prescott para drogar y fotografiar a las estudiantes de Blackwell.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_009"] = "Frank... me alegra tanto que estés aquí... ¿estás bien?",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_014"] = "Todas nuestras pistas condujeron al profesor Mark Jefferson... tenía una escalofriante sala fotográfica de tortura... descubrimos que... estaba usando a Nathan Prescott para drogar y fotografiar a las estudiantes de Blackwell...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_018"] = "No... no sabemos... las cosas se salieron de control y aquí estamos... Frank, lo siento...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_020"] = "Sí... ojalá no lo hubiera hecho... Lo siento, Frank. Nathan quería impresionar a Jefferson y él... la mató...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_021"] = "No... no ví a Rachel Amber, pero Nathan quería impresionar a Jefferson y sé que él... la mató.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_023"] = "Usó alguna droga... y le dio una sobredosis...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_026"] = "No importa... Ella merece estar en paz ahora.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_028"] = "Está muerto. Ya no lastimará a nadie más...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_029"] = "Irá a la cárcel. Ya no lastimará a nadie más...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_031"] = "Lo sé... Tampoco Chloe.",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_033"] = "Lo sé... obviamente le importabas, Frank...",
  ["Cue_E5_5C_Diner_CHFrank_FrankDial_Max_036"] = "Chloe apreciaría eso...",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Frank_001"] = "Max... no puedo creer que mi Rachel esté... no puedo hablar...",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Frank_004"] = "Lo siento, Max... no puedo hablar... espero que tengamos otra oportunidad algún día...",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Frank_005"] = "Max, ¿me escuchaste? No quiero ver tu cara antes de morir.",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_002"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_002",
  ["Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_003"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_CHFrank_FrankQuickPhase_Max_003",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_002"] = "Justo cuando pensaba que ya había terminado lo peor... ¿dónde está Chloe?",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_007"] = "No, no en esta tormenta. Y no saldrás, Max. Rezaré para que Chloe... y David... estén en un lugar seguro...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_008"] = "Ah, gracias a Dios... me estaba torturando a mí misma antes de que llegaran... si algo le hubiera ocurrido a Chloe mientras yo estaba en el restaurante...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_009"] = "No te sientas así, linda. No es como si tú hubieras invocado este tornado por ti misma...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_011"] = "No tienes control sobre nada de eso... David es un adulto y tiene más edad y experiencia bajo la manga. Aunque no siempre lo demuestra...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_013"] = "Sé que intentas ver el lado bueno de todos... y David también lo intenta. Pero eso no importa ahora...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_015"] = "Con todo lo que ha ocurrido esta semana, creo que tienes razón.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_017"] = "Hiciste lo correcto. David sobrepasó el límite. Sospechaba que se tomaba su vigilancia privada demasiado en serio... pero lo lamenta y quisiera que estuviera aquí ahora...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_019"] = "Con todo lo que ha ocurrido esta semana, creo que tienes razón. Y mírame, intento mantener unida a mi familia... de nuevo. Max... ¿cometí un error al echar a David?",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_021"] = "Me da gusto que David estuviera con ustedes... pero no siempre me gusta su actitud... y honestamente, no creo poder perdonarlo por golpear a Chloe... si lo hizo una vez, podría repetirse...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_023"] = "Estoy acostumbrada a que mi vida sea difícil... Chloe tuvo que aprenderlo demasiado pronto. Y no pienso que necesitemos a David por aquí como recordatorio. Tienes razón, Max. Pienso que ahora tomaré mi decisión...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_024"] = "Me da mucho gusto que David estuviera con ustedes... pero no siempre me gusta su actitud... algunas veces me asusta...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_026"] = "Con todo lo que ha ocurrido esta semana, creo que tienes razón. Y mírame, tratando de mantener unida a mi familia... de nuevo.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_028"] = "Muchas gracias, linda. Tus padres deberían sentirse muy orgullosos de ti. Incluso David me dijo lo fuerte que eres... y no hace muchos cumplidos, como sabes.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_030"] = "Me da mucho gusto que David estuviera con ustedes... carga muchas cosas desde la guerra, pero realmente quiere ayudar a las personas. Incluso aceptó tomar una clase de terapia familiar después de golpear a Chloe...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_031"] = "Me da mucho gusto que David estuviera con ustedes... carga muchas cosas desde la guerra, pero realmente quiere ayudar a las personas. Incluso aceptó tomar una clase de terapia familiar.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_033"] = "Nada me haría más feliz que David y Chloe hicieran las paces, no la guerra... pero no sé qué hacer... Quisiera que esta tormenta terminara de una vez y para siempre... quizá es hora de salir de Arcadia Bay... si podemos...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_035"] = "Lo sé... y sí, no es William, pero es bueno. No se supone que sean iguales. Me recordaste cuando él llegó a mi vida... estaba lista para rendirme... el amor de David me dio fuerza. Incluso me dijo que yo era su héroe... Y no puedo dejar de amarlo... Quiero que regrese a casa... espero poder decirle eso pronto...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_038"] = "Más le vale... como dije, la gente no siempre ve al verdadero David Madsen. Espero que Chloe lo haga algún día...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Joyce_039"] = "Me da tanto gusto oírte decir eso, Max... Sé que no siempre es una persona fácil de defender... la mayoría de las personas solo ven su peor lado... pero tú viste el mejor. Y ese es el hombre que quiero en mi vida.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_001"] = "Joyce, ¿cómo estás?",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_003"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_003",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_004"] = "La... La encontraré.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_005"] = "Ella está... a salvo, Joyce. Me envió un mensaje poco antes de que mi teléfono se apagara.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_006"] = "Siento todo esto, Joyce.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_010"] = "Eh... quiero decir, también siento todo lo que pasó con David...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_012"] = "Bueno... no quería tomar partido por David contra ti o Chloe...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_014"] = "Lo sé... solo siento que todo lo que está ocurriendo es la tormenta perfecta para Arcadia Bay...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_016"] = "Siento haber causado tantos problemas con David y Chloe...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_018"] = "Solo quiero que nuestras vidas sean normales de nuevo…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_020"] = "David salvó mi vida… de la tormenta… tiene buenas intenciones, incluso si no sabe cómo demostrarlo. Pero debe ser tu decisión…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_022"] = "Eh... entiendo...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_025"] = "Sé que es difícil para ti y para Chloe...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_027"] = "Joyce, has vivido tantas cosas por Chloe y David... si fueras mi mamá, estaría muy orgullosa.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_029"] = "David salvó mi vida… de la tormenta… vi lo mucho que le importa Chloe, incluso si no sabía demostrarlo… David te necesita más que nunca, puedo ver por qué lo amas.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_032"] = "Seguramente también fue difícil para él… eso demuestra lo mucho que le importan tú y Chloe...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_034"] = "David es un verdadero héroe, Joyce. Sé que lo que más desea es verlas felices… se que haría cualquier cosa por ti… y por Chloe.",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_036"] = "Le importas. Es tan obvio que te necesita en su vida...",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceDial_Max_037"] = "David es un verdadero héroe… no sé a qué se enfrentó en la guerra, pero puedo imaginarlo… incluso me mostró cómo recurrir a mi propia fuerza en condiciones extremas…",
  ["Cue_E5_5C_Diner_CHJoyce_JoyceQuickPhase_Joyce_001"] = "Max, debemos cuidar a todos los están aquí ahora, así que regresaré a mi doble turno…",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDialQuickPhase_Warren_001"] = "Demonios, Max, esta semana el mundo ha estado en tus manos.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_001"] = "Ojalá lo hubiera hecho entonces. Te lo diré sin más explicaciones, ¿okey? Confía en mí, ¿sí?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_003"] = "Pienso que esta tormenta... todo comenzó... cuando descubrí que podía rebobinar el tiempo... Todo esto no puede ser una simple coincidencia... ¿o sí?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_004"] = "Debo rebobinar el tiempo... Jefferson ya mató a... a Chloe... no puedo dejar que eso ocurra... ¡necesito hacer algo, Warren!",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_005"] = "Nathan accidentalmente mató a Rachel Amber, al intentar impresionar a Jefferson... solo necesitaba ayuda mental... ahora ambos están... muertos.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_010"] = "Todo debido... ¿debido a mí? ¿Cómo?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_013"] = "Usó a Nathan para obtener drogas y dinero. Jefferson me ató y... me dio alguna droga y tomó fotografías de mí. Fue horrible.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_015"] = "Pero todavía puedo cambiar las cosas... ¿qué piensas que ocurrirá?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_016"] = "Nathan accidentalmente mató a Rachel Amber, al intentar impresionar a Jefferson... solo necesitaba ayuda mental... ahora está muerto... y Jefferson, acabado.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_018"] = "Tuve una visión en la clase de Jefferson de un tornado que destruía Arcadia Bay. Fui al baño y vi a Nathan Prescott dispararle a mi mejor amiga, Chloe... ¿Me sigues?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_020"] = "Después descubrí que podía rebobinar el tiempo... y en pocas palabras, Mark Jefferson está loco y es peligroso.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_024"] = "Muerto. Acabado. Lo cual necesito cambiar rápido para arreglar las cosas de nuevo... ¿eso es malo?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_025"] = "Atrapado. Acabado. Lo cual necesito cambiar rápido para arreglar las cosas de nuevo... ¿Está mal?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_026"] = "Eres mi amigo, Warren. Me crees, ¿verdad? No le he contado a nadie, además de Chloe... y ella... no puede ayudarme ahora...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_027"] = "Toda esta destrucción... ¿es mi culpa?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_028"] = "Warren, todo esto suena tan loco... Pero eres la única otra persona con quien puedo contar ahora... desearía que hubiéramos pasado más tiempo juntos... ¿me crees?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_032"] = "Solo quisiera confiar en mis poderes...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_033"] = "Siempre. Solo quisiera confiar en mis poderes...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_034"] = "Supongo que nunca sabremos si es magia o ciencia...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Max_035"] = "Con eso ya somos dos, Warren...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_002"] = "Siempre. Quizás deberías decírmelo rápido...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_006"] = "Max, no solo la tormenta, también el eclipse, las aves, las ballenas... ¡todo!",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_007"] = "¡Max, regresar en el tiempo es lo que causó la tormenta!",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_008"] = "No soy un científico experto, aunque lo finja en la escuela,|pero parace ser causa y efecto, o la teoría del caos... Eh... ¿Qué pasó con Jefferson? Él... ¿Te lastimó?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_014"] = "Max... siento que hayas tenido que vivir todo esto... eres la persona más valiente que conozco... Ahora mataré a ese hijo de puta... ¿Dónde está?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_019"] = "¡Obviamente! ¡Continúa!",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_021"] = "Vaya... ¿eso es todo?",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_022"] = "Dios mío, Max... quiero escuchar toda la historia, pero de verdad se agota el tiempo...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_023"] = "A cada acción corresponde una reacción... Si revertiste o alteraste el tiempo, quizá causaste una reacción en cadena... Incluso en el ambiente.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_029"] = "Sé que puedo ser un dolor de cabeza, pero tú... siempre me has tratado como tu igual, no como... un nerd beta. Ya lo sabes, siempre te creeré...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_030"] = "Por favor... No es que uno se conceda a sí mismo poderes para viajar en el tiempo....",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_031"] = "Max, por supuesto que te creo. Eres la persona más asombrosa que conozco... Te agradezco que confíes en mí.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_036"] = "Aun si fuera por un mago o un agujero de gusano... eres parte de algo más grande...|No creo en el destino, pero después de esta semana, me doy cuenta de que no sé nada.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenDial_Warren_037"] = "Sé que estás aquí por una razón... y creo que solo tú puedes descubrir cuál es.",
  ["Cue_E5_5C_Diner_CHWarren_WarrenMinorChoiceQuickPhase_Warren_001"] = "Max, desearía que pasáramos más tiempo juntos, pero hay cosas más importantes que hacer ahora...",
  ["Cue_E5_5C_Diner_CHWarren_WarrenMinorChoiceQuickPhase_Warren_002"] = "Max, tienes cosas más importantes que hacer ahora que hablar con tu amigo...",
  ["Cue_E5_5C_Diner_ChoiceHug_Max_010"] = "Necesito un abrazo antes de hacer esto...",
  ["Cue_E5_5C_Diner_ChoiceHug_Max_040"] = "No eres patético. Eres uno de mis héroes... y tomaré las decisiones correctas de aquí en adelante... lo juro.",
  ["Cue_E5_5C_Diner_ChoiceHug_Warren_020"] = "Yo también.",
  ["Cue_E5_5C_Diner_ChoiceHug_Warren_030"] = "Mejor vete, antes de que me ponga patético y te diga que no me dejes.",
  ["Cue_E5_5C_Diner_ChoiceHug_Warren_050"] = "Por eso eres SuperMax.",
  ["Cue_E5_5C_Diner_ChoiceKiss_Max_010"] = "Para tener suerte.",
  ["Cue_E5_5C_Diner_ChoiceKiss_Max_030"] = "Lo sé, Warren...",
  ["Cue_E5_5C_Diner_ChoiceKiss_Max_050"] = "Tomaré las decisiones correctas de aquí en adelante... lo juro.",
  ["Cue_E5_5C_Diner_ChoiceKiss_Warren_020"] = "En caso de que no salgamos de esto... quería decirte que...",
  ["Cue_E5_5C_Diner_ChoiceKiss_Warren_040"] = "Por supuesto que sí.",
  ["Cue_E5_5C_Diner_ChoiceKiss_Warren_060"] = "Por eso eres SuperMax.",
  ["Cue_E5_5C_Diner_ChoiceNothing_Max_010"] = "Cuida a Joyce... y a Frank.",
  ["Cue_E5_5C_Diner_ChoiceNothing_Max_015"] = "Cuida a Joyce... y a todos los demás.",
  ["Cue_E5_5C_Diner_ChoiceNothing_Max_030"] = "Tomaré las decisiones correctas de aquí en adelante... lo juro.",
  ["Cue_E5_5C_Diner_ChoiceNothing_Warren_020"] = "Yo me encargo, Max. Adelante.",
  ["Cue_E5_5C_Diner_ChoiceNothing_Warren_040"] = "Por eso eres SuperMax.",
  ["Cue_E5_5C_Diner_Focus_Warren_010"] = "Oye... ten mucho cuidado.",
  ["Cue_E5_5C_Diner_FrankDialogIntro_IGE_Joyce_010"] = "Okey, Max. Con permiso, debo ayudar a este otro caballero.",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_010"] = "Dios, no quiero morir aquí...",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_020"] = "También estaba a punto de conducir hacia Los Ángeles...",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_030"] = "Siempre que tenga a mi Pompidou conmigo...",
  ["Cue_E5_5C_Diner_Frank_IGE_Frank_035"] = "Si solo tuviera a mi Pompidou conmigo...",
  ["Cue_E5_5C_Diner_HealFrank_IGE_Frank_020"] = "¡Demonios, Joyce!",
  ["Cue_E5_5C_Diner_HealFrank_IGE_Frank_040"] = "No, solo soy cobarde... lo siento...",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_Joyce_010"] = "Espera... sentirás un piquete...",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_Joyce_030"] = "Lo siento, lo siento...",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_Joyce_050"] = "Saldremos de esto, ¿okey?",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_OldMan_020"] = "¡Ay! ¡Mierda!",
  ["Cue_E5_5C_Diner_HealOldMan_IGE_OldMan_040"] = "No, lo lamento... gracias...",
  ["Cue_E5_5C_Diner_InsertionDiner_Announcer_020"] = "...evacuación. Repito, esto no es una prueba. Esto no es una prueba. Alerta de tornado E6 para Arcadia Bay y condados aledaños. El Sistema de Transmisión de Emergencia está en funcionamiento...",
  ["Cue_E5_5C_Diner_InsertionDiner_Frank_040"] = "Pompidou…",
  ["Cue_E5_5C_Diner_InsertionDiner_Frank_045"] = "Pompidou... Buen perro guardián…",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_030"] = "Shhh, Frank... Está bien.",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_060"] = "¡Max!",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_070"] = "¡Ay, Dios, me alegra mucho verte, cielito! ¿Estás bien?",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_090"] = "El Two Whales apenas se mantiene en pie, no sé si resistirá el tornado... Pobre oficial Berry, pobre gente allí afuera...",
  ["Cue_E5_5C_Diner_InsertionDiner_Joyce_110"] = "De acuerdo, entra y quédate ahí... debo regresar a ayudar... Warren reunió todo el material de primeros auxilios...",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_080"] = "Sí, ¿qué hay de ustedes?",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_100"] = "Lo sé...",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_130"] = "¿Estás bien, Warren?",
  ["Cue_E5_5C_Diner_InsertionDiner_Max_150"] = "No había nada que pudieras hacer al respecto, Warren.",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_050"] = "¡Max!",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_120"] = "No es mucho, Joyce. Pero es todo lo que tenemos.",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_140"] = "¿Por qué carajo ignoré todas las advertencias, Max? La nieve... el eclipse...",
  ["Cue_E5_5C_Diner_InsertionDiner_Warren_160"] = "Qué estupidez... debí saberlo...",
  ["Cue_E5_5C_Diner_JoyceDialogIntro_IGE_Joyce_010"] = "Vamos, Max... hablemos aquí y démosle a Frank espacio para descansar...",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_010"] = "Por favor, Chloe, necesito que estés bien... no puedo perderte...",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_020"] = "Max... ¿crees que este... sea el fin?",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_030"] = "Parece que no puedo escapar del Two-Whales...",
  ["Cue_E5_5C_Diner_Joyce_IGE_Joyce_040"] = "Vamos, Joyce... enfócate en la gente que está aquí...",
  ["Cue_E5_5C_Diner_PolaRewind_Max_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_PolaRewind_Max_010",
  ["Cue_E5_5C_Diner_PolaRewind_Max_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_PolaRewind_Max_020",
  ["Cue_E5_5C_Diner_PolaRewind_Max_030"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_PolaRewind_Max_030",
  ["Cue_E5_5C_Diner_PolaRewind_Warren_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_PolaRewind_Warren_010",
  ["Cue_E5_5C_Diner_PolaRewind_Warren_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_PolaRewind_Warren_020",
  ["Cue_E5_5C_Diner_PolaRewind_Warren_030"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Diner_PolaRewind_Warren_030",
  ["Cue_E5_5C_Street_AlyssaSaved_IGE_Alyssa_020"] = "¡Lo estoy!",
  ["Cue_E5_5C_Street_AlyssaSaved_IGE_Alyssa_030"] = "¡Aquí voy!",
  ["Cue_E5_5C_Street_AlyssaSaved_IGE_Max_010"] = "¡Vamos, Alyssa! ¡Toma mi mano!",
  ["Cue_E5_5C_Street_AlyssaSavesMax_IGE_Alyssa_010"] = "¡Cuidado, Max!",
  ["Cue_E5_5C_Street_AlyssaSavesMax_IGE_Alyssa_030"] = "¡Ahora estamos a mano! ¡Cuídate mucho!",
  ["Cue_E5_5C_Street_AlyssaSavesMax_IGE_Max_020"] = "Demonios... eso estuvo cerca... ¡gracias Alyssa!",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Alyssa_010"] = "¡Lo lograste, Max!",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Alyssa_030"] = "¡Ahora sí! ¡Necesito salir de aquí!",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Max_020"] = "¿Estás bien?",
  ["Cue_E5_5C_Street_AlyssaThanks_IGE_Max_040"] = "¡Alyssa, tú sigue adelante! ¡Debo ayudar a otras personas!",
  ["Cue_E5_5C_Street_AlyssaWarnDies_IGE_Alyssa_020"] = "¡Al carajo con eso, Max! ¡Siempre que apareces tengo que hacerme a un lado!",
  ["Cue_E5_5C_Street_AlyssaWarnDies_IGE_Alyssa_030"] = "Así que solo trae -- Aaaaaaaaaaaaaaaaaaaaaaaaaaaaahhhhhhhh",
  ["Cue_E5_5C_Street_AlyssaWarnDies_IGE_Max_010"] = "¿Alyssa, estás bien? ¡Déjame ayudarte a bajar!",
  ["Cue_E5_5C_Street_AlyssaWarnNothing_IGE_Alyssa_020"] = "¡Sí, sí, por favor, Max! ¡No quiero morir así!",
  ["Cue_E5_5C_Street_AlyssaWarnNothing_IGE_Alyssa_030"] = "¡Encuentra algo para bajarme!",
  ["Cue_E5_5C_Street_AlyssaWarnNothing_IGE_Max_010"] = "¿Alyssa, estás bien? ¡Déjame ayudarte a bajar!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_010"] = "¡Alguien ayúdeme!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_020"] = "¡No puedo escapar!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_030"] = "¡Demonios, necesito ayuda!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_040"] = "¡Por favor!... ¡Ayúdame a bajar!",
  ["Cue_E5_5C_Street_AlysssaHelp_IGE_Alyssa_050"] = "¡Ayúdame a bajar, Max!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_010"] = "¡Robert Capa, muérete de envidia!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_030"] = "¡Max, no hay forma en que deje pasar estas imágenes! ¡Míralas!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_050"] = "Bien, si insistes...",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_060"] = "Vaya, Max... ¡sabes mucho! Soy una idiota...",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_080"] = "Ahora debería escuchar al Héroe Cotidiano... ¡ven conmigo!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Evan_100"] = "Es mejor que te ayudes a ti misma ahora, Max... ¡debemos sobrevivir a esto!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_020"] = "¡Evan! ¿Ves ese tornado? ¡Lárgate de aquí!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_040"] = "¡No puedes tomar una fotografía si mueres! ¡Muévete, carajo!",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_070"] = "Solo si no encuentras un lugar seguro hasta que esto termine, ¿sí?",
  ["Cue_E5_5C_Street_EvanSaved_IGE_Max_090"] = "Primero tengo que ayudar a alguien más.",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_010"] = "¡Robert Capa, muérete de envidia!",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_020"] = "La mejor. Toma. De mi vida.",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_030"] = "Vamos, nena, una fotografía más...",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_040"] = "Justo en el ojo de la tormenta...",
  ["Cue_E5_5C_Street_Evan_IGE_Evan_050"] = "Esta será mi obra maestra.",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_010"] = "Por favor, por favor, por favor...",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_020"] = "No más tormentas...",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_030"] = "Este no puede ser el final...",
  ["Cue_E5_5C_Street_FishermanAfraid_IGE_Fisherman_040"] = "No puedo morir en este cuarto... no puedo...",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Fisherman_020"] = "Necesito respirar... necesito aire...",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Fisherman_040"] = "Toda la ciudad está muriendo...",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Max_010"] = "Vamos, tienes que salir de aquí ahora.",
  ["Cue_E5_5C_Street_FishermanSaved_IGE_Max_030"] = "Deberías irte de aquí...",
  ["Cue_E5_5C_Street_Panic_IGE_Girlfriend_010"] = "Por favor, por favor, por favor...",
  ["Cue_E5_5C_Street_Panic_IGE_Girlfriend_020"] = "No, no puedes haber muerto... no puedes...",
  ["Cue_E5_5C_Street_Panic_IGE_Man05_030"] = "Arrghh, por favor... sácame de aquí...",
  ["Cue_E5_5C_Street_Panic_IGE_Man07_010"] = "Este es el fin... todo acabó...",
  ["Cue_E5_5C_Street_Panic_IGE_Woman01_010"] = "No... no puedo creer que esto sea real...",
  ["Cue_E5_5C_Street_Panic_IGE_Woman03_010"] = "¿Qué está pasando? ¿QUÉ ESTÁ PASANDO?",
  ["Cue_E5_5C_Street_Panic_Man01_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Street_Panic_Man01_020",
  ["Cue_E5_5C_Street_Panic_Man01_030"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5C_Street_Panic_Man01_030",
  ["Cue_E5_5C_Street_TruckerHelpClose_IGE_Trucker_010"] = "¡Hey... tú... eh... Matt!",
  ["Cue_E5_5C_Street_TruckerHelpClose_IGE_Trucker_020"] = "Por favor, ¿puedes... ayudarme?",
  ["Cue_E5_5C_Street_TruckerHelpClose_IGE_Trucker_030"] = "¡Por favor! ¡No me dejes aquí!",
  ["Cue_E5_5C_Street_TruckerHelpFar_IGE_Trucker_010"] = "¡Eh! ¿Hay alguien ahí?",
  ["Cue_E5_5C_Street_TruckerHelpFar_IGE_Trucker_020"] = "Por favor, alguien... quien sea... ¡Ayúdenme!",
  ["Cue_E5_5C_Street_TruckerHelpFar_IGE_Trucker_030"] = "¡No quiero morir aquí!",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Max_020"] = "¿Estás bien?",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Max_040"] = "Es mejor que te vayas ahora...",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Max_060"] = "No, gracias... necesito encontrar a un amigo...",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_010"] = "Ay, Señor... Gracias, amiga...",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_030"] = "Una vez que me largue de aquí... me quedé en este agujero de mierda haciendo entregas después de que cerraron el tren...",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_050"] = "Y nunca regresaré aquí... ¿necesitas que te lleve?",
  ["Cue_E5_5C_Street_TruckerSavedRailroad_IGE_Trucker_070"] = "Vete tú. Anda.",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Max_020"] = "¿Estás bien?",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Max_040"] = "Es mejor que te vayas ahora...",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Max_060"] = "No, gracias... necesito encontrar a un amigo...",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_010"] = "Ay, Señor... Gracias, amiga...",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_030"] = "Una vez que me largue de aquí... He estado transportando carga demasiado tiempo en este pueblo de mierda...",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_050"] = "Y nunca regresaré aquí... ¿necesitas que te lleve?",
  ["Cue_E5_5C_Street_TruckerSaved_IGE_Trucker_070"] = "Vete tú. Anda.",
  ["Act_E5_5D_DarkRoom_BigChair_Look01_Max_010"] = "Todavía puedo sentir las correas... Basta, Max. Estás libre.",
  ["Act_E5_5D_DarkRoom_BondagePicture01_Look01_Max_010"] = "Muchas mujeres habrían posado para Jefferson con mucho gusto... pero no quería que sus modelos tuvieran poder de decisión...",
  ["Act_E5_5D_DarkRoom_BondagePicture02_Look01_Max_010"] = "Nadie verá el trabajo de Jefferson igual que antes...",
  ["Act_E5_5D_DarkRoom_BurntDiary_Look01_Max_010"] = "Carajo, Jefferson incendió todo. Ahora la única foto que puedo obtener es la que tomó Warren.",
  ["Act_E5_5D_DarkRoom_BurntDiary_Scripted_Max_010"] = "¡Mierda! ¡Quemó mi diario! Es por eso que sigo atorada aquí.",
  ["Act_E5_5D_DarkRoom_BusTicketReceipt_Look01_Max_010"] = "Nadie habría buscado el cuerpo de Nathan con esto...",
  ["Act_E5_5D_DarkRoom_CHDavid_Look02_Max_020"] = "Resiste, David... arreglaré todo.",
  ["Act_E5_5D_DarkRoom_CHDavid_Look02_Max_025"] = "David Madsen está en el caso... Aún busca evidencia.",
  ["Act_E5_5D_DarkRoom_CHJefferson_Look01_Max_010"] = "Jefferson se ve tan patético ahora.",
  ["Act_E5_5D_DarkRoom_CHJefferson_Look02_Max_030"] = "No puedo creer que Jefferson esté muerto.",
  ["Act_E5_5D_DarkRoom_CHJefferson_Look02_Max_035"] = "Me alegra que ese loco esté amarrado. Aún así... todavía estoy en shock. No puedo creer que esto sea real.",
  ["Act_E5_5D_DarkRoom_Camera_Look01_Max_010"] = "Tanto equipo tan costoso, solo para... sus gustos degenerados.",
  ["Act_E5_5D_DarkRoom_ChloeNecklace_Interact01_Max_020"] = "De ninguna forma dejaré tu collar aquí...",
  ["Act_E5_5D_DarkRoom_ChloeNecklace_Look01_Max_010"] = "Ah, Chloe... te salvaré... por última vez.",
  ["Act_E5_5D_DarkRoom_DavidDeadLine_Scripted_Max_010"] = "¡Max! ¡Rebobina y ayuda a David!",
  ["Act_E5_5D_DarkRoom_DavidDeadLine_Scripted_Max_020"] = "¡De ninguna manera, Jefferson!",
  ["Act_E5_5D_DarkRoom_DuctTape_Look01_Max_010"] = "Qué repugnante... Me pregunto si compró esa cinta adhesiva a cuenta de Blackwell. Basura...",
  ["Act_E5_5D_DarkRoom_GHBBottle_Look01_Max_010"] = "Frank no es una mala persona, pero no puede negar que vendía drogas...",
  ["Act_E5_5D_DarkRoom_InsertionLine_Scripted_Max_010"] = "Dios, no... ¿Estoy aquí de nuevo? ¡Creí que había arreglado todo!",
  ["Act_E5_5D_DarkRoom_InsertionLine_Scripted_Max_020"] = "¿Qué? Jefferson debería estar en la cárcel, no aquí...",
  ["Act_E5_5D_DarkRoom_JeffDeadLines_Scripted_Max_010"] = "He visto a muchas personas morir esta semana... ahora Jefferson... estoy muy aturdida...",
  ["Act_E5_5D_DarkRoom_JeffDeadLines_Scripted_Max_020"] = "Dios, tantas vidas destruidas... Rachel... Chloe... Kate... incluso Nathan.",
  ["Act_E5_5D_DarkRoom_JeffDeadLines_Scripted_Max_030"] = "Jefferson ahora está muerto... pero aún puedo regresar a Chloe a la vida.",
  ["Act_E5_5D_DarkRoom_JeffersonsGlasses_Look01_Max_010"] = "Ya no necesitará los lentes...",
  ["Act_E5_5D_DarkRoom_JeffersonsGun_Look01_Max_010"] = "No más putas armas.",
  ["Act_E5_5D_DarkRoom_LieDavidLine_Scripted_Max_010"] = "No te saldrás con la tuya, Jefferson.",
  ["Act_E5_5D_DarkRoom_LieDavidLine_Scripted_Max_020"] = "Jefferson terminará en la cárcel... pero Chloe está muerta... aunque no por mucho tiempo...",
  ["Act_E5_5D_DarkRoom_LieDavidLine_Scripted_Max_030"] = "Podría haberle dicho la verdad a David... se lo merece.",
  ["Act_E5_5D_DarkRoom_MaxReactions_Scripted_Max_010"] = "¿Qué es ese ruido? Hay alguien más aquí...",
  ["Act_E5_5D_DarkRoom_MaxReactions_Scripted_Max_020"] = "¡David!",
  ["Act_E5_5D_DarkRoom_MaxReactions_Scripted_Max_030"] = "¡No, David! ¡No!",
  ["Act_E5_5D_DarkRoom_NathanLetter_Look01_Max_010"] = "Pobre Nathan... Jefferson definitivamente debería haber quemado esta carta...",
  ["Act_E5_5D_DarkRoom_Picture01_Look01_Max_010"] = "Odio verme así...",
  ["Act_E5_5D_DarkRoom_Picture03_Look01_Max_010"] = "Puaj... Quiero quemar todas estas fotos.",
  ["Act_E5_5D_DarkRoom_Receipt_Look01_Max_010"] = "Parece que Jefferson planeaba una renovación de seguridad... con dinero de los Prescott.",
  ["Act_E5_5D_DarkRoom_SaveTimeLine_Scripted_Max_010"] = "Podría rebobinar hasta el inicio, hablar con Jefferson y ayudar a poner una trampa...",
  ["Act_E5_5D_DarkRoom_Stereo_Look02_Max_020"] = "Todas las canciones que escucharás en prisión serán tu tortura... Nunca serás libre de nuevo.",
  ["Act_E5_5D_DarkRoom_Syringe_Look01_Max_010"] = "Solo ver eso me hace querer vomitar...",
  ["Act_E5_5D_DarkRoom_VicBracelet_Look01_Max_010"] = "Ah, es el brazalete de Victoria. Apuesto a que Jefferson iba a usarlo para inculpar a Nathan.",
  ["Act_E5_5D_DarkRoom_WarningLines_Scripted_Max_010"] = "¡Mal momento, Max! ¡Demasiado pronto!",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_020"] = "Quemó todo... incluso todas mis fotos...",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_030"] = "¡Warren! ¡Sí! ¡Puedo usar esa foto que tomó de nosotros!",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_050"] = "Tengo que arriesgarme y salvar a Chloe usando la foto de Warren... será difícil.",
  ["Act_E5_5D_DarkRoom_WarrenPicture_Scripted_Max_060"] = "Mejor salgo y llamo a Warren... Por favor, contesta...",
  ["Act_E5_5D_DarkRoom_ZeitgeistFlyer_Look01_Max_010"] = "Nunca más, Jefferson... irás a exposiciones.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_001"] = "Mira este lugar... Así debe ser el infierno.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_006"] = "Siempre sospeché de ese hijo de puta.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_009"] = "Ay no...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_010"] = "Me alegro...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_011"] = "Sí, y esto es lo que obtengo por desperdiciar tantas horas con los Prescott... Quise abarcar demasiado, falta de enfoque.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_012"] = "Nadie espera que sospeches de tus profesores.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_015"] = "Hiciste muy bien al informar al Director que Jefferson actuaba raro con Kate Marsh...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_016"] = "No me sorprendió cuando acusaste a Nathan de drogar a Kate Marsh. Yo también lo pensé...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_017"] = "Supongo que me veía igual de sospechoso cuando le dijiste al director Wells que yo estaba... acosando a Kate Marsh. Y no te culpo.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_018"] = "Y Max, traté a Kate como basura... Sé que es una buena persona, pero yo no. Espero poder decirle eso pronto.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_019"] = "Y, Max, nunca me perdonaré por lo que le pasó a Kate. Siento como si la hubiera ayudado a saltar de esa azotea.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_023"] = "Sabía que Nathan Prescott era una amenaza. Esperé demasiado para neutralizarlo.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_024"] = "Todos tomamos decisiones que lamentamos... pero admito que tú y Chloe me impresionaron. Yo tengo mis juguetes de alta tecnología, pero ustedes se tienen la una a la otra.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_025"] = "Ese pervertido hacía toda su mierda de porquería bajo mis narices... Pude haberlo detenido a él y a Nathan, pero... fui tan estúpido.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_033"] = "Pienso que ella solo aprendió a odiarme... estoy seguro de que sabes que... le pegué el otro día.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_034"] = "Pienso que ella solo aprendió a odiarme...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_035"] = "Es uno de mis problemas... No soy bueno en equipo. Nunca lo fui, ni siquiera en el servicio.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_037"] = "No daré excusas por mi conducta. Intenté ser un buen soldado... pero no fui tan bueno...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_038"] = "También intenté ser un buen padre... pero ya viste cómo resultó.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_039"] = "También intenté ser un buen padre... pero cuando Joyce me echó, me quedé sin nada...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_044"] = "Me alegra que tengamos algo en común...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_045"] = "Bien jodidos. Lo sé.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_046"] = "Nunca debí instalar esas cámaras de vigilancia. Ni conservar esos archivos...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_047"] = "Sí, sé lo que se siente. Es demasiado.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_050"] = "Intento no usar mi pasado como excusa, pero es difícil llegar a casa después de la guerra. La mayoría no sabe o no les importa de dónde vienes... excepto Joyce. Ella me dio nuevas esperanzas. Una nueva vida.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_David_052"] = "Solo quiero verla a salvo con su madre... Le prometí a Joyce que vería a un terapeuta familiar... y comenzaría por disculparme con Chloe... No espero que me llame \"papá\", pero si al menos dejara de llamarme \"padrastúpido\".",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_004"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_004",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_005"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_5D_DarkRoom_CHDavid_Phase01_Jefferson_005",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_002"] = "Jefferson iba... iba a matarme... como a Victoria Chase...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_003"] = "Jefferson iba a matarme... Llegaste justo a tiempo.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_007"] = "Sospechabas prácticamente de todos...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_008"] = "Yo no... hasta que fue demasiado tarde.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_013"] = "Sé lo que se siente...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_014"] = "No era un profesor... Solo quería adoctrinar. Era parte de sus planes enfermos.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_020"] = "Yo también. Creo que eso la haría muy feliz.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_021"] = "Kate subió a esa azotea por el acoso que sufrió... pero ante todo fue culpa de Nathan y Jefferson.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_022"] = "No te culpes. Nathan y Jefferson son quienes la llevaron a esa situación...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_026"] = "Jefferson ya lo había hecho. Tenían una extraña relación padre-hijo. Nathan mató a Rachel y Jefferson lo usó como chivo expiatorio.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_027"] = "No...|Le dije al director Wells que Nathan tenía un arma y que... casi llegó a usarla.|Pero no me creyó. Debí insistir más.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_028"] = "No... Debí decirle al director Wells que Nathan tenía una pistola y que... casi la usa. Puse a la escuela en peligro...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_029"] = "Quizás aprendió de ti.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_030"] = "Somos... Somos un gran equipo.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_031"] = "Sé que lo lamentas...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_032"] = "Las dos tuvieron un comienzo difícil... Sé que no fue fácil.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_036"] = "No puedo ni imaginar por lo que has pasado.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_040"] = "Chloe es fuerte... como tú.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_041"] = "Lo intentaste. Es obvio que te importa, aún si tus métodos son...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_042"] = "Lo siento mucho... No quería que eso ocurriera...",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_043"] = "Solo estaba enojada y quería desquitarme.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_048"] = "Me alegro de haberte defendido.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_049"] = "Le diré a Joyce que me equivoqué respecto a ti... ella te ama, es evidente.",
  ["Cue_E5_5D_DarkRoom_CHDavid_Phase01_Max_051"] = "Y tú salvaste la mía. Chloe... Ella... Ella estaría orgullosa de ti.",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_030"] = "Ah, gracias a Dios. Por primera vez me alegra que Chloe fume hierba.",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_040"] = "Bien, profesor, veamos qué tipo de evidencia fotográfica tienes en esta computadora...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_080"] = "Por supuesto, adelante, Max.",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_David_090"] = "Eres una soldado valiente... Me alegro que Chloe tenga una amiga como tú... Ahora vete... Ya tuviste suficiente de este cuarto...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_Max_020"] = "David... Ella estaba muy estresada y se fue a... eh... medicarse antes de que yo terminara aquí. Así que, está bien.",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceLie_Max_070"] = "David, necesito salir al aire fresco... y usar mi teléfono.",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_010"] = "Espera, Max.",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_015"] = "¿Y dónde está Chloe?",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_030"] = "Esto no está ocurriendo... No puede ser... No, Dios... No Chloe... Max, ¿estás segura?",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_050"] = "Anoche... cuando me autocompadecía en la habitación del hotel...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_055"] = "Anoche... cuando estaba tan cerca de encontrar la verdad...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_060"] = "Le prometí a Joyce que la protegería a ella y a Chloe... ¿Cómo puedo explicarle esto...? Nunca le dije a Chloe que yo... yo.... ¡Carajo!",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_070"] = "¿Mataste a la hija de mi esposa, cabrón hijo de puta?",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_080"] = "Te llevaste a mi hijastra...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_100"] = "Max.. lo siento... siento que tuvieras que ver eso...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_120"] = "Qué desastre... ¿qué he hecho? Tanto tiempo desperdiciado vigilando... Chloe... lo siento... Joyce... te fallé... Mi familia...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_David_140"] = "Max... Mejor vete... Ya viste suficiente de este cuarto.",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_020"] = "David... Chloe está... está muerta…",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_040"] = "Sí, la vi... Vi a Jefferson matarla en el depósito de chatarra... Anoche...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_090"] = "David... ¡Espera!",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_110"] = "El Sr. Jefferson decía que nunca hay que dejar pasar una oportunidad...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_130"] = "No fallaste, hiciste lo mejor que pudiste...",
  ["Cue_E5_5D_DarkRoom_ChloeChoiceTruth_Max_150"] = "David... gracias por salvarme.",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_010"] = "Ay, no... no…",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_020"] = "Con un carajo...",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_030"] = "Te freirán por esto.",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_040"] = "¿Cómo pudiste...? ¿Cómo?",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_050"] = "Estás jodido, Jefferson.",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_060"] = "Ah, Rachel... ¿Cómo pudo alguien...?",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_070"] = "Enfermo y pervertido...",
  ["Cue_E5_5D_DarkRoom_ChloeLie_David_080"] = "Jefferson, tienes suerte de que la policía te saque de aquí en una pieza.",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_010"] = "Justo debajo de mi nariz...",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_020"] = "Mataste a mi Chloe...",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_030"] = "Dios mío... ¿qué le digo a Joyce? ¿Qué?",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_040"] = "¿Por qué no puedo despertar? Debe ser una pesadilla...",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_050"] = "Perdí de nuevo... siempre pierdo...",
  ["Cue_E5_5D_DarkRoom_ChloeTruth_David_060"] = "Quisiera poder seguir matándote... para siempre.",
  ["Cue_E5_5D_DarkRoom_DavidFight_David_080"] = "¡Jefferson! ¡Todo acabó!",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_010"] = "Ahora... ¿qué demonios es este lugar?",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_020"] = "Santo Dios... es un estudio...",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_030"] = "No tenía idea que estaba tan demente...",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_040"] = "Max, siento que terminaras aquí...",
  ["Cue_E5_5D_DarkRoom_DavidIdle_David_050"] = "Los Prescott debían saber sobre esto...",
  ["Cue_E5_5D_DarkRoom_DavidIntro_Max_010"] = "¿David?",
  ["Cue_E5_5D_DarkRoom_DavidIntro_Max_020"] = "¿Estás bien?",
  ["Cue_E5_5D_DarkRoom_DavidJeffersonFaceOff_Jefferson_010"] = "Sin pistola no tienes agallas...",
  ["Cue_E5_5D_DarkRoom_DavidSpeak_BeforeDial_Max_010"] = "Oye...",
  ["Cue_E5_5D_DarkRoom_DavidSpeak_BeforeDial_Max_020"] = "¿Estás bien?",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_010"] = "Ay, Dios... Max... ¿estás bien? ¿Estás herida? ¿Puedes moverte?",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_030"] = "No me lo agradezcas. Tú me has traído aquí.",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_040"] = "Primero terminemos con este hijo de puta.",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_060"] = "No irá a ninguna parte cuando despierte.",
  ["Cue_E5_5D_DarkRoom_DavidUntie_David_070"] = "Excepto a prisión para siempre. Y eso es solo el principio.",
  ["Cue_E5_5D_DarkRoom_DavidUntie_Max_020"] = "Sí... Gracias, David. Gracias...",
  ["Cue_E5_5D_DarkRoom_DavidUntie_Max_080"] = "¿Sr. Jefferson? Ahora es su turno de ser capturado en un momento.",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_010"] = "¡De acuerdo, Max!",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_030"] = "¡Gracias!",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_050"] = "Entiendo...",
  ["Cue_E5_5D_DarkRoom_DavidWarn_David_060"] = "¡Sí, señor!",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_030"] = "¿Qué dijiste, Max?",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_040"] = "Diablos, es como si estuvieras en clase. Siempre te distraes. Quizás deberías tomar una de tus famosas selfis ahora... La transformación entre la antigua y la nueva Max... En fin, responde mi pregunta. Por favor.",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_050"] = "Señorita Caulfield, le hice una pregunta. Responda. O la lastimaré.",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_070"] = "Buena respuesta, buena respuesta.",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Jefferson_080"] = "Oye, estás sangrando de la nariz... Quizá te di una dosis demasiado grande. Lo siento, Max. Aunque, considerando que estás a punto de morir, eso es como un problema de primer mundo.",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_010"] = "¡Oh, mierda!",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_020"] = "¿Quemó mi diario?",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_060"] = "Vete a la mierda.",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_063"] = "Vete a la mierda...",
  ["Cue_E5_5D_DarkRoom_InsertionPart1_Max_066"] = "Jódete.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_David_120"] = "ESPERA -",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_010"] = "Tu iris... dilatado, como un obturador... Las fotografías que tomas de mí ahora. Lástima que desaprovechaste tu don. Pudiste haber ganado el concurso, pero destruiste tu propia fotografía... Qué desperdicio.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_020"] = "Siento haber quemado todas tus cosas, me dejé llevar un poco. Sabes que siempre he creído en tu visión...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_030"] = "Especialmente desde que pasaste de nerd a heroína en una semana... Algo extraño ocurre contigo...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_040"] = "¡Vaya! ¡Mira cómo se ha puesto fuera! Como dije, pasa algo... raro.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_050"] = "Ahí está el miedo... Oh, Max, es un honor trabajar contigo en estas sesiones finales... Espero que estas imágenes se aprecien por lo que verdaderamente capturan... la pérdida de la juventud.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_060"] = "Por lo menos esa es la última lección que escucharás de mí...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_065"] = "Por lo menos será la última lección que escucharás de mí...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_070"] = "Y te prometo que no te sangrará más la nariz...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_090"] = "Shhh, silencio... Silencio... Max...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_100"] = "Te prometo que esta dosis final no dolerá...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_110"] = "¿Qué?",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_130"] = "Diablos... ¡David Madsen! Está fuera de combate.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_131"] = "David Madsen... por supuesto. Esto te ganas por jugar al policía: una bala de verdad.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_132"] = "¡Diablos! David Madsen, eres un estúpido hijo de puta, así que no me culpes.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_133"] = "Lo siento, Madsen.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_135"] = "Bien. Siempre odié a ese jodido fascista. Todos en Blackwell lo odiaban, ¿cierto, Max?",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_137"] = "Siempre odié ese bigote... ¿tú también lo odiabas, Max?",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_140"] = "Okey...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_142"] = "Déjà vu. ",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_144"] = "Intentemos esto una última vez...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_150"] = "Deberías haberte quedado acosando estudiantes.",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Jefferson_160"] = "David Madsen...",
  ["Cue_E5_5D_DarkRoom_InsertionPart2_Max_080"] = "Sr. Jefferson... Por favor... No haga esto. No sabe lo que está ocurriendo.",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_010"] = "Ah, tuve que dejar ir a Victoria Chase.",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_030"] = "No seas idiota, ¿de acuerdo? Está exactamente donde merece estar.",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_050"] = "Oh, como si te importara.",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Jefferson_060"] = "Aún así, la perra idiota intentó chantajearme... así que estamos mejor ahora. Excepto cuando culpen a Nathan. Para ser honestos, el chico es un puto psicópata.",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Max_020"] = "Tú la dejaste...",
  ["Cue_E5_5D_DarkRoom_InsertionPartVic_Max_040"] = "No…",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_010"] = "(llanto)",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_020"] = "¡Por favor!",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_040"] = "No haga esto...",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_050"] = "(Llanto)",
  ["Cue_E5_5D_DarkRoom_Insertion_MaxBegs_Max_060"] = "(Llanto)",
  ["Cue_E5_5D_DarkRoom_JeffersonFight_Jefferson_020"] = "¡No me detendrás!",
  ["Cue_E5_5D_DarkRoom_JeffersonFight_Jefferson_060"] = "¡Estás muerto, David!",
  ["Cue_E5_5D_DarkRoom_JeffersonWarn_Jefferson_010"] = "¿Cómo... sabías eso?",
  ["Cue_E5_5D_DarkRoom_JeffersonWarn_Jefferson_020"] = "Cierra la puta boca, ¿sí?",
  ["Cue_E5_5D_DarkRoom_MaxFree_David_040"] = "Deben llamar a la policía pronto...",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_020"] = "Salva a Chloe...",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_030"] = "Nada...",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_050"] = "¡Warren!",
  ["Cue_E5_5D_DarkRoom_MaxFree_Max_060"] = "¡Mierda! ¡No hay señal!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_010"] = "¡David, cuidado!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_050"] = "¡Esconde una pistola allá!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_060"] = "¡David, patea la mesa!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_070"] = "¡Toma la cámara junto a ti!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_080"] = "¡Toma tu pistola ahora!",
  ["Cue_E5_5D_DarkRoom_MaxWarn_Max_090"] = "¡Toma esa botella!",
  ["Cue_E5_5D_DarkRoom_MaxWishDrink_Jefferson_020"] = "Por supuesto, no quiero que estés incómoda.",
  ["Cue_E5_5D_DarkRoom_MaxWishDrink_Max_010"] = "Eh... Disculpe, pero tengo la garganta reseca... ¿Puedo tomar agua?",
  ["Cue_E5_5D_DarkRoom_MaxWishLight_Jefferson_020"] = "Ahora piensas como una verdadera fotógrafa... y no quiero que tu último recuerdo sea una mala iluminación...",
  ["Cue_E5_5D_DarkRoom_MaxWishLight_Max_010"] = "¿Le importaría apagar las luces? Me encandilan, y no me veré bien en las fotos.",
  ["Cue_E5_5D_DarkRoom_MaxWishMusic_Jefferson_020"] = "Incluso en tus últimos instantes, eres una soñadora, Max... qué belleza...",
  ["Cue_E5_5D_DarkRoom_MaxWishMusic_Max_010"] = "Por favor, ¿podría poner un poco de música...? Para morir en paz.",
  ["Cue_E5_5D_DarkRoom_MaxWishPicture_Jefferson_020"] = "Casi no lo creo, pero al parecer, al fin aprendiste de mí...",
  ["Cue_E5_5D_DarkRoom_MaxWishPicture_Max_010"] = "¿Podría tomar... una última fotografía de mí? Quiero... ser su mejor modelo...",
  ["Cue_E5_5D_DarkRoom_MaxWish_Jefferson_020"] = "Si quieres algo, solo pídelo, ¿de acuerdo?",
  ["Cue_E5_5D_DarkRoom_MaxWish_Jefferson_040"] = "Bah, me atrapaste, Max. ¿Cómo puedo decirle que no a ese rostro?",
  ["Cue_E5_5D_DarkRoom_MaxWish_Max_010"] = "¡Un momento!",
  ["Cue_E5_5D_DarkRoom_MaxWish_Max_030"] = "¿Puedo...? ¿Puedo hacer una última... petición?",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_010"] = "Libertad...",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_020"] = "¡Sí!",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_030"] = "¡Warren! ¿Puedes oírme?",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_050"] = "Olvídalo... Oye, ¿tienes la fotografía que tomaste aquella noche en el estacionamiento?",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_070"] = "¡Sí! ¡La quiero! ¿Dónde estás?",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_090"] = "Voy para allá.",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_110"] = "Está bien, yo también. Pero todavía no acaba, Warren... ¡Resiste!",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_130"] = "Bien, SuperMax... Necesitas llegar allí tan rápido como una bala.",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_140"] = "Gracias, Sr. Jefferson. Pero no necesitará esto en el infierno.",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_145"] = "Gracias, Sr. Jefferson. Pero ya no necesitará esto.",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_150"] = "Casi tan bueno como un DeLorean...",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_155"] = "Espero poder conducir esta cosa...",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_160"] = "¡Mierda! Sí que es una tormenta.",
  ["Cue_E5_5E_OldFarm_CallWarren_Max_165"] = "Necesito encontrar a Warren...",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_040"] = "¡¿Max?! ¡Carajo! ¿Dónde estás?",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_060"] = "Emmh, sí, ¿por qué? No era tan buena toma...",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_080"] = "Estoy en el restaurante Two Whales,|atrapado con Joyce por este clima del Apocalipsis.|Siento que el mar se va a volver rojo en cualquier momento...",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_100"] = "Vamos, es una locura. Apenas se puede caminar en la acera... En serio, Max, quédate donde estés. No creo que esta tormenta termine pronto. Estoy asustado.",
  ["Cue_E5_5E_OldFarm_CallWarren_Warren_120"] = "Espera...",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_010"] = "Vaya, sencillamente no escucha... Mejor rebobino e intento de nuevo...",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_020"] = "Casi la tenías, Max... ¡Todavía puedo lograrlo!",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_030"] = "Si soy fuerte y honesta, me escuchará... soy su mejor amiga...",
  ["Act_E5_6A_CampusPark_FailedLines_Scripted_Max_040"] = "Chloe sabe que tengo este poder... tiene que creerme.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_002"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_002",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_004"] = "¿Ese cabrón ya está muerto? ¿Cómo lo sabes?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_008"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_008",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_009"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_009",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_016"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_016",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_017"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_017",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_021"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_021",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_022"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_022",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_023"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_023",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_026"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_026",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_027"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_027",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_028"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_028",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_031"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_031",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_033"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_033",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_037"] = "No importa. Haré que Nathan pague por lo que le hizo a Rachel... Y sé que me apoyas.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_038"] = "Por favor, ¿me puedes decir exactamente qué pasó? ¿Por favor?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_042"] = "Bueno, Max, ¡vayamos en equipo a patearle el trasero de inmediato!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_043"] = "Entonces ahora es el turno de Jefferson para morir.|Entiendo por qué no quieres hacer esto y no te culpo por no venir conmigo.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_044"] = "Oh... Max... Lo siento...|Fui yo quien te arrastró a esta mierda...|Nadie, especialmente tú, debería pasar por eso...|Ahora debemos detener a Jefferson... con una bala.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_046"] = "Se dice fácil... no sabes cómo ha sido mi vida estos últimos cinco años...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_048"] = "¡Max, no estoy huyendo de ti! Ahora es cuando te necesito más... así es como me compensarás todo... con tu poder y mi pistola. ¡Nada en el universo puede detenernos, Max!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_050"] = "¿Realidades alternativas? ¿Qué quieres decir, Max? ¿Qué hiciste?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_054"] = "¡Entonces no puedes estar segura de nada! Por eso acabaré con Jefferson... y esa será nuestra realidad.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_056"] = "Max, ¿de qué demonios estás hablando?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_060"] = "Por supuesto que sí. ¿Crees que sabría cómo manejar esa situación? Nadie sabría... Lo importante es que estamos juntas de nuevo.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_062"] = "Ya sé, Max... ¿pero entonces dejamos que Jefferson continúe con sus torturas y asesinatos?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_064"] = "¿Quiénes son dueños de la policía aquí? ¡Y entonces probablemente nos pondrían en una maldita celda! Max, sé que te impacta lo que ocurrió... pero debo enfrentar esta realidad... ¡vamos por él!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_066"] = "Me gustaría pensar eso y solo irme contigo justo ahora... pero Max, ya no confío en el karma... Rachel se merece justicia. Ahora. Con tu ayuda...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_069"] = "No lo entiendo... ¿por qué confías en él después de que lo pusiste en su lugar el otro día? ¡Ya ni siquiera está en nuestra casa!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_070"] = "¿Por eso lo defendiste? ¿Porque pensabas que podía ayudarnos? ¿En serio?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_075"] = "Sí, una bofetada en la cara es una señal segura de amor rudo.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_076"] = "Por favor... ¿crees que le importó cuando te gritoneó por fumar hierba?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_077"] = "Por favor... como si le importara cuando irrumpió en mi cuarto.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_078"] = "Vaya, Max... No tenía idea...|Debí ser yo quien te salvara, pero... aún así estoy tan agradecida de que David estuviera allí.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_079"] = "Claro, porque en realidad investigaba a todos, incluso a tu amiga Kate...|Lo siento, pero no confío en él... Depende de nosotras, Max.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_085"] = "¿En serio? No lo imagino mostrando sentimientos. Excepto hacia mi mamá.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_086"] = "Entonces, ¿cuál es tu plan?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_090"] = "Algo que aprendí en Blackwell es el dicho:|\"Aquellos que no aprenden de la historia están condenados a repetirla\". Debo hacer esto. Por mi cuenta... otra vez.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_091"] = "Max. Por favor, dime... no me enojaré contigo...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_093"] = "¿Viste a mi papá de nuevo?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_095"] = "Por Dios, Max... Debió ser horrible para ti. Siento tanto haberte pedido algo así.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_096"] = "Vaya. Has pasado por tanto... Te creo, Max. Después de todo, aún soy tu compañera fiel.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_097"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Chloe_097",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_David_067"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_David_067",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_073"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_073",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_081"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_MaxUnderwear_081",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_001",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_003"] = "Nathan está muerto... y tú estás en peligro.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_005"] = "Porque... estaba allí...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_006"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_006",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_007"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_007",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_010"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_010",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_011"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_011",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_012"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_012",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_013"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_013",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_014"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_014",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_015"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_015",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_018"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_018",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_019"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_019",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_020",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_024"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_024",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_025"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_025",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_029"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_029",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_030"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_030",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_032"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_032",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_034"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_034",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_035"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_6A_Parking_CHChloe_Phase01_Max_035",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_036"] = "¡Chloe, no puedes vengarte si estás muerta!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_039"] = "Jefferson secuestró a Rachel y a otras chicas. También estaba manipulando a Nathan... y lo mató.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_040"] = "Chloe...&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;|&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;Jefferson me drogó y me secuestró. Estaba atada en su búnker. No tienes idea del infierno que atravesé para regresar aquí... pero no podía dejarte morir. Tú me trajiste de regreso aquí, y no puedo perderte de nuevo. ¡No!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_041"] = "Mark Jefferson resultó ser un psicópata...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_045"] = "Chloe, sé que esto no es fácil pero es momento de que tú... y yo... aceptemos el pasado. Debemos enfocarnos en nuestro futuro... mientras aún tengamos uno.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_047"] = "Chloe, nunca debí alejarme de ti como lo hice cuando me fui de Arcadia Bay... Sé que te herí... Solo quería compensarte. Por favor, no te alejes de mí...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_049"] = "No, no así, Chloe...|No puedo seguir corrigiendo todo si lo único que hago es romperlo una y otra vez... Sé cómo resultará esto y temo estar arruinando todas esas realidades alternas...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_051"] = "Chloe... Te diré la verdad sin importar lo que ocurra... cambié tu pasado y tuve que tomar una decisión terrible... yo... yo...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_052"] = "Lo arruiné, Chloe. Quise corregir las cosas, pero todo salió mal.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_053"] = "Eh... Nada... Es decir... Cuando uso mi poder de rebobinar, abro nuevas líneas de tiempo... Nuevos destinos...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_055"] = "No, no... ¡Chloe, espera!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_057"] = "Y lo hice... por ti. No quería que sufrieras en ninguna otra línea de tiempo o realidad alterna... No podía soportar que sintieras más dolor...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_058"] = "Pero Chloe, jamás podría hacer eso... tenía que regresar a esta línea de tiempo... para verte de nuevo. Tenía que hacerlo...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_059"] = "Era peor para ti... pero no tenía idea de qué pasaría... y como siempre, arruiné todo... pero nunca quise lastimarte, jamás... tienes que creerme...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_061"] = "Tienes razón. Por eso debes venir conmigo, para que podamos permanecer juntas... y vivas.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_063"] = "No, vamos con la policía y que ellos se encarguen. Tenemos mucha evidencia...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_065"] = "Siempre que estés viva, no me importa... el karma lo alcanzará algún día.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_068"] = "¡Por supuesto que no! Si le decimos a David, nos creerá y podría detenerlo... ¿cierto?",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_071"] = "Chloe, David me salvó de Jefferson...|Si no hubiera rastreado el cuarto oscuro... ahora estaría muerta.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_072"] = "Chloe, aunque se haya comportado como un idiota, a David verdaderamente le importas.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_074"] = "David ya estaba investigando a Jefferson. Estaba muy adelantado a nosotras.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_080"] = "Sé que ha sido difícil pero él es el único que sabe lo que ocurre... el único que nos ayudará ahora.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_082"] = "No, no, escúchame... ¡espera, Chloe!",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_083"] = "Debiste ver su reacción cuando le dije que Jefferson... te había matado... estaba devastado.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_084"] = "Debiste ver qué alivio sintió cuando le dije que no moriste... habría quedado devastado.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_087"] = "Le diré todo, incluso que Victoria está en peligro.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_088"] = "Sí, lo eres. Así que escucha: en unos minutos, no sabré nada de lo que pasó... nada. Dime exactamente lo que hice y dije... solo explícame que viajé a través del tiempo usando la foto... debemos permanecer en tu habitación sin hacer nada. Después le explicamos todo a David... y finalmente dejamos que haga su trabajo.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_089"] = "Vamos, por supuesto que sí... pero en algún momento necesitas seguir adelante...",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_092"] = "Pude regresar en el tiempo... al último día en que William estaba vivo.|Evité que se fuera pero... a cambio de eso tú terminaste en un choque de autos.",
  ["Cue_E5_6A_Parking_CHChloe_Phase01_Max_094"] = "Tú... estabas completamente paralizada por el choque... y morías lentamente... entonces me pediste que... terminara con tu sufrimiento...",
  ["Cue_E5_6A_Parking_DialChloeFail_Max_010"] = "¡Chloe!",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Chloe_020"] = "Te creo, Max... después de todo, soy tu compañera fiel...",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Chloe_050"] = "¿Me creerás?",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Max_040"] = "Sí, lo eres. Mira... En unos minutos, no sabré nada de lo que pasó... Nada. Debemos quedarnos en tu habitación y no hacer nada. Luego le explicamos todo a David y dejamos que él haga su parte. Dime exactamente todo lo que hice y dije. Solo explícame que viajé a través del tiempo usando la foto.",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Max_060"] = "Siempre te creeré, Chloe.",
  ["Cue_E5_6A_Parking_DialChloeSuccess_Max_070"] = "Ahora sígueme...",
  ["Cue_E5_6A_Parking_Insertion_Chloe_010"] = "No tenemos tiempo para esta mierda. Vamos, Max.",
  ["Cue_E5_6A_Parking_Insertion_Chloe_040"] = "Oye, güey, ¿qué te pasa?",
  ["Cue_E5_6A_Parking_Insertion_Chloe_070"] = "También me alegra que estés conmigo. ¿Qué ocurre, Max? Debemos encontrar a Nathan. Pagará por lo que le hizo a Rachel. Vamos. Ya.",
  ["Cue_E5_6A_Parking_Insertion_Chloe_100"] = "Puedo caminar y escuchar, ¿sí?",
  ["Cue_E5_6A_Parking_Insertion_Chloe_120"] = "Bien, Max, escucho.",
  ["Cue_E5_6A_Parking_Insertion_Chloe_140"] = "Usaste tus poderes, ¿cierto? Y jugaste con el puto tiempo y morí.",
  ["Cue_E5_6A_Parking_Insertion_Chloe_160"] = "Se supone que me apoyas. No puede ser que el imbécil punk de Nathan Prescott acabe conmigo.",
  ["Cue_E5_6A_Parking_Insertion_Chloe_190"] = "¿Jefferson, el maestro de arte? ¡Déjate de pendejadas! ¡Nathan es el pinche asesino! ¡Vimos las pruebas!",
  ["Cue_E5_6A_Parking_Insertion_Chloe_195"] = "Ahora discúlpame,|iré a la fiesta para asegurarme de que nunca más lastime a nadie. ¿Vienes?",
  ["Cue_E5_6A_Parking_Insertion_Max_020"] = "¡Chloe!",
  ["Cue_E5_6A_Parking_Insertion_Max_050"] = "Me... alegra que estemos aquí, juntas...",
  ["Cue_E5_6A_Parking_Insertion_Max_080"] = "Lo siento, Warren...",
  ["Cue_E5_6A_Parking_Insertion_Max_090"] = "¡Chloe, espera! ¡Escucha!",
  ["Cue_E5_6A_Parking_Insertion_Max_110"] = "¡Detente y escúchame por una vez!",
  ["Cue_E5_6A_Parking_Insertion_Max_130"] = "Chloe, no puedes ir a esa fiesta. Si lo haces... morirás.",
  ["Cue_E5_6A_Parking_Insertion_Max_150"] = "No así...",
  ["Cue_E5_6A_Parking_Insertion_Max_170"] = "Tienes razón. No lo hará.",
  ["Cue_E5_6A_Parking_Insertion_Max_180"] = "Mark Jefferson te mató... a ti y a otros..",
  ["Cue_E5_6A_Parking_Insertion_Warren_030"] = "Di \"¡Whisky!\", cabrón.",
  ["Cue_E5_6A_Parking_Insertion_Warren_060"] = "Veo que necesitan hablar. No te preocupes... No hay problema.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_010"] = "Max... es hora...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_030"] = "Max... ahora siempre estaré a tu lado.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_050"] = "Para siempre...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Chloe_060"] = "Max... siempre estaré a tu lado.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Max_020"] = "Ya no.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Max_040"] = "Lo sé... eres mi mejor amiga...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveChloe_Max_070"] = "Para siempre...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_010"] = "Max... es hora...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_030"] = "Lo sé, Max. Pero debemos hacerlo. Debemos salvar a todos, ¿sí?|Y tú harás que esos cabrones paguen por lo que le hicieron a Rachel.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_040"] = "Estar juntas esta semana fue el mejor regalo de despedida que podría tener... eres mi héroe, Max.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Chloe_060"] = "Más te vale... Y siempre te querré... ahora vete de aquí. Por favor. Hazlo antes de que pierda el control... y Max Caulfield, no te olvides de mí...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Max_020"] = "Chloe... lo siento tanto... no quiero hacer esto...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Max_050"] = "Chloe. Te quiero.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTownKissChloe_Max_070"] = "Jamás.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_010"] = "Max... es hora...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_030"] = "Lo sé, Max. Pero debemos hacerlo. Debemos salvar a todos, ¿sí?|Y tú harás que esos cabrones paguen por lo que le hicieron a Rachel.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_040"] = "Estar juntas esta semana fue el mejor regalo de despedida que podría tener... eres mi héroe, Max.",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Chloe_060"] = "Y siempre te querré... ahora vete de aquí. Por favor. Hazlo antes de que pierda el control... y Max Caulfield, no te olvides de mí...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Max_020"] = "Lo sé. Chloe... lo siento tanto... no quiero hacer esto... pero tenemos que hacerlo...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Max_050"] = "Chloe... te extrañaré tanto...",
  ["Cue_E5_7A_CliffFuture_ChoiceSaveTown_Max_070"] = "Jamás.",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_003"] = "¿Max? ¿Max, me oyes? Por favor, di algo.",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_010"] = "Ah, gracias a Dios... ¡nunca hagas eso de nuevo!",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_040"] = "Al carajo con todo. Te dieron un poder, tú no lo pediste. Y me salvaste. Ha ocurrido todo lo que tenía que suceder. Todo, excepto lo que le pasó a Rachel...",
  ["Cue_E5_7A_CliffFuture_Insertion_Chloe_050"] = "Pero sin tu poder, no la habríamos encontrado. No eres el Amo del puto Tiempo, pero sí eres Maxine Caulfield y eres asombrosa.",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_007"] = "¿Chloe? Me... Me debo haber desmayado... Lo siento.",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_020"] = "Lo juro... pero esa pesadilla era tan real... tan horrible...",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_030"] = "Esta es mi tormenta. Todo es mi culpa... Todo. Cambié tanto el destino que... alteré el curso de todo. ¡Y lo único que ocasioné fue muerte y destrucción!",
  ["Cue_E5_7A_CliffFuture_Insertion_Max_060"] = "Max... no Maxine. Lo sabes.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_020"] = "Max, esta es la única solución.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_040"] = "Podrías usar esa fotografía para rebobinar todo a como era cuando la tomaste... Lo único que necesitamos es que yo... Yo...",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_060"] = "Lo sé... me lo probaste una y otra vez... aunque no lo merezco. Soy tan egoísta... no como mi mamá... mira a lo que tuvo que renunciar y por lo que tuvo que pasar... y lo hizo.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_070"] = "Se merece mucho más que morir por una tormenta en un estúpido restaurante... aun mi padrastro merece que ella viva. Hay muchas personas más en Arcadia Bay que merecen vivir... más que yo...",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_090"] = "No estás cambiándome... quizás solo has estado retrasando mi destino real... mira cuántas veces casi he muerto o he muerto mientras estás conmigo... Mira lo que ocurre en Arcadia Bay desde que me salvaste por primera vez... sé que he sido egoísta, pero por una vez, creo que debería aceptar mi destino... nuestro destino...",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_094"] = "Max, por fin regresaste a mi vida esta semana y... no hiciste nada más que demostrarme cariño y amistad. Me hiciste sonreír y reír como no lo había hecho en años.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_096"] = "Donde sea que termine después de esto, en cualquier realidad, todos esos momentos entre nosotras fueron reales y siempre serán nuestros. No importa lo que elijas, sé que tomarás la decisión correcta.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_098"] = "Este también es tu destino, Max... y no te abandonaré. Siempre estaré a tu lado, como siempre has estado tú para mí. Recuerda, somos amigas por siempre.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_110"] = "No, Max...",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Chloe_115"] = "Eres la única que puede hacerlo.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_030"] = "Siento que tomé esta fotografía hace mil años.",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_050"] = "Al carajo con eso. No. De ningún modo. Tú eres mi prioridad número uno... eres lo único que me importa ahora...",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_080"] = "No digas eso... no te cambiaré...",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_092"] = "Chloe...",
  ["Cue_E5_7A_CliffFuture_IntroChoice_Max_100"] = "Chloe... no puedo tomar esta decisión...",
  ["Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_001"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_001",
  ["Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_002"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_002",
  ["Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_003"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7A_Cliff_CHChloe_Phase01_Chloe_003",
  ["Act_E5_7B_ArtClass_AloneLines_Scripted_Max_010"] = "Todos se fueron ahora... ¿arruiné totalmente el tiempo?",
  ["Act_E5_7B_ArtClass_AloneLines_Scripted_Max_030"] = "Esto no tiene sentido...",
  ["Act_E5_7B_ArtClass_ArcadiaBayPic01_Look01_Max_010"] = "Oh, no...",
  ["Act_E5_7B_ArtClass_ArcadiaBayPic02_Look01_Max_010"] = "Rachel no merecía nada de esto...",
  ["Act_E5_7B_ArtClass_BirdLines_Scripted_Max_020"] = "¿Espera, qué pasa? ¿qué, a nadie le importa?",
  ["Act_E5_7B_ArtClass_BirdLines_Scripted_Max_030"] = "Mierda... mira todos estos pájaros muertos... esto no puede ser real...",
  ["Act_E5_7B_ArtClass_BloodStains_Look01_Max_010"] = "Lo siento, Kate...",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_010"] = "Oh por favor, no quiero decir eso...",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_020"] = "De ningún modo diré eso... de ningún modo.",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_030"] = "¿Por qué pasa esto?",
  ["Act_E5_7B_ArtClass_ComplimentWaitingLines_Scripted_Max_040"] = "No puedo decir esto...",
  ["Act_E5_7B_ArtClass_Computer_Look01_Max_010"] = "Es demasiado escalofriante...",
  ["Act_E5_7B_ArtClass_ContestPoster_Look01_Max_010"] = "No voy a caer en la trampa... no lo haré.",
  ["Act_E5_7B_ArtClass_DanielTable_Photo_Max_020"] = "No me importa si es un sueño o una pesadilla, tomaré esta foto...",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_010"] = "Regresé a la clase... ¿qué demonios?",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_020"] = "Bien, esto está mal... ¿estoy atorada en un círculo en el tiempo?",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_030"] = "¿Tengo que escuchar la clase de Jefferson de nuevo? Esto podría ser el infierno...",
  ["Act_E5_7B_ArtClass_DisturbedLines_Scripted_Max_040"] = "Cálmate y no te vuelvas loca... todavía.",
  ["Act_E5_7B_ArtClass_GroupPhoto_Look01_Max_010"] = "Puaj, eso es horrible...",
  ["Act_E5_7B_ArtClass_JeffersonPoster01_Look01_Max_010"] = "Esa... soy yo... ¿es una broma?",
  ["Act_E5_7B_ArtClass_JeffersonPoster02_Look01_Max_010"] = "Esto definitivamente no es real...",
  ["Act_E5_7B_ArtClass_KateEtchings_Look01_Max_010"] = "No moriste, Kate... estás viva.",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_010"] = "Esto no puede ser real... No lo creo...",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_020"] = "Si esto es una pesadilla... quiero despertar...",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_030"] = "Por favor, Chloe... ¿Dónde estás?",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_060"] = "Más vale que no aparezca Freddy Krueger o gritaré...",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_080"] = "Chloe... ayúdame...",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_090"] = "¿Qué tal si no me puedo despertar y esto es... real?",
  ["Act_E5_7B_ArtClass_NightmareLines_Scripted_Max_110"] = "Sé fuerte... tienes que serlo.",
  ["Act_E5_7B_ArtClass_PaperBall_Look01_Max_010"] = "Todavía no, maldito bastardo.",
  ["Act_E5_7B_ArtClass_VictoriaTablet_Look01_Max_010"] = "Victoria... intentaba ayudarte...",
  ["Act_E5_7B_ArtClass_VictoriaTablet_Look02_Max_020"] = "Victoria es una perra aún en mis sueños...",
  ["Act_E5_7B_Corridor_Alyssa_Look01_Max_010"] = "Alyssa siempre está enviando mensajes de texto, pero no se junta con mucha gente.",
  ["Act_E5_7B_Corridor_BigfootBanner_Look01_Max_010"] = "El pisotón de los Pies Grandes... Debería desarrollar un poco de espíritu escolar. Vamos, equipo.",
  ["Act_E5_7B_Corridor_Board01_Look01_Max_010"] = "No necesito una PC; me perdí las pruebas para el recital de poesía, y no robé esa mochila.",
  ["Act_E5_7B_Corridor_Board02_Look01_Max_010"] = "Se puede aprender mucho sobre una escuela por la basuar que publican en los tableros.",
  ["Act_E5_7B_Corridor_Brooke_Look01_Max_010"] = "He visto a Brooke con Warren. Ella parece ser su tipo.",
  ["Act_E5_7B_Corridor_Courtney_Look01_Max_010"] = "Creo que esa es Courtney. Actúa como la esclava de Taylor y Victoria...",
  ["Act_E5_7B_Corridor_Dana_Look01_Max_010"] = "Dana también está en mi piso. Es una hermosa porrista arquetípica. Seguro que las fabrican en serie. ... No debería ser tan maliciosa. Dana es amable conmigo.",
  ["Act_E5_7B_Corridor_Daniel_Look01_Max_010"] = "Pobre Daniel. Es tan amable. Desearía poder moler a golpes a Logan.",
  ["Act_E5_7B_Corridor_Evan_Look01_Max_010"] = "Evan no me habla mucho, pero sus fotos son muy buenas.",
  ["Act_E5_7B_Corridor_Halloween01_Look01_Max_010"] = "¡Sí, Halloween, mi época favorita del año!",
  ["Act_E5_7B_Corridor_Halloween01_Look02_Max_010"] = "Nunca me canso de ver fantasmas y esqueletos en el pasillo.",
  ["Act_E5_7B_Corridor_Halloween01_Look03_Max_010"] = "Desearía que octubre durara para siempre...",
  ["Act_E5_7B_Corridor_Hayden_Look01_Max_010"] = "Allí está Hayden, otro miembro del club Vortex. Aunque él no es un idiota.",
  ["Act_E5_7B_Corridor_Juliet_Look01_Max_010"] = "Allí esta Juliet, de mi residencia. Otra discípula del club Vortex.",
  ["Act_E5_7B_Corridor_Justin_Look01_Max_010"] = "Es... Dana hablando con... Creo que se llama Justin.",
  ["Act_E5_7B_Corridor_Logan_Look01_Max_010"] = "Odio a los deportistas machitos, como Logan. Y es miembro del club Vortex.",
  ["Act_E5_7B_Corridor_MPA01_Look01_Max_010"] = "¡Si no me apresuro a ese baño, otra muchacha estará en problemas!",
  ["Act_E5_7B_Corridor_MPA01_Look02_Max_010"] = "Me pregunto qué le ocurrió en verdad...",
  ["Act_E5_7B_Corridor_MPA01_Look03_Max_010"] = "Parece que lleva meses desaparecida.",
  ["Act_E5_7B_Corridor_MPA01_Look04_Max_010"] = "Me pregunto qué le ocurrió en verdad...",
  ["Act_E5_7B_Corridor_MaxLocker_Look01_Max_010"] = "Odio que todos vean el interior de mi casillero.",
  ["Act_E5_7B_Corridor_Plan01_Look01_Max_010"] = "¿Quién pierde el tiempo en memorizar esto? Aunque supongo que hoy en día, todos deberíamos hacerlo.",
  ["Act_E5_7B_Corridor_Poster01_Look01_Max_010"] = "Es un horror. Debería contactarlos para averiguar qué puedo hacer. Mejor lo dejamos.",
  ["Act_E5_7B_Corridor_Poster02_Look01_Max_010"] = "Ahí está el faro otra vez...",
  ["Act_E5_7B_Corridor_Poster03_Look01_Max_010"] = "No debería ser tan tacaña con mi sangre.",
  ["Act_E5_7B_Corridor_Poster04_Look01_Max_010"] = "Qué bueno que dejé mi rifle en casa.",
  ["Act_E5_7B_Corridor_Poster05_Look01_Max_010"] = "Sí, este cartel debe dejar fríos a los bullies.",
  ["Act_E5_7B_Corridor_Poster06_Look01_Max_010"] = "¡Alerta de nerds! ¡Este cartel tiene \"Warren\" escrito por todas partes!",
  ["Act_E5_7B_Corridor_Poster07_Look01_Max_010"] = "Uy, apenas puedo esperar que llegue el día en que sea tan genial como Nathan o Victoria. Aburrido.",
  ["Act_E5_7B_Corridor_PrincipalDoor_Look01_Max_010"] = "El director no sale mucho de su oficina.",
  ["Act_E5_7B_Corridor_Samuel_Look01_Max_010"] = "Samuel es un poco extraño, pero me cae bien.",
  ["Act_E5_7B_Corridor_Stella_Look01_Max_010"] = "Stella siempre está concentrada en sus notas. No vino a Blackwell a perder el tiempo.",
  ["Act_E5_7B_Corridor_Taylor_Look01_Max_010"] = "Allí está Taylor, siempre esperando a Victoria.",
  ["Act_E5_7B_Corridor_Trevor_Look01_Max_010"] = "Es lindo. Me gustan los patinadores. Es una lástima que no les guste yo.",
  ["Act_E5_7B_Corridor_Trophy01_Look01_Max_010"] = "Mira esos trofeos. Debo reconocer eso de los Pies Grandes. Sí que pisotean.",
  ["Act_E5_7B_Corridor_Trophy02_Look01_Max_010"] = "Blackwell sí que se toma la natación en serio. Pero las nutrias son lindas. ¡Vamos, Nutrias!",
  ["Act_E5_7B_Corridor_VendingMachine_Look01_Max_010"] = "Deberían llamarla \"Máquina de azúcar\"... Sería asombroso si pusieras dinero allí y saliera una bolsa de azúcar.",
  ["Act_E5_7B_Corridor_Zachary_Look01_Max_010"] = "Parece que Juliet está saliendo con Zachary. El club Vortex atrae a los atletas.",
  ["Act_E5_7B_DarkRoom_DarkLines_Scripted_Max_080"] = "¿Cuánto durará esta pesadilla?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_010"] = "Genial, números por todo el lugar. ¿Cómo encontraré el código correcto?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_020"] = "¿Por qué el espejo no refleja los números?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_030"] = "¿Qué demonios le pasa a este espejo?",
  ["Act_E5_7B_Diner_DinerLines_Scripted_Max_040"] = "¡Los diseñadores la pagarán por todos estos acertijos de códigos estúpidos!",
  ["Act_E5_7B_Diner_digicode_Look01_Max_010"] = "Estaré muy agradecida si este es el último código digital...",
  ["Act_E5_7B_DormsCorridor_HintKey_Scripted_Max_010"] = "Este pasillo nunca termina... Más vale que encuentre algo.",
  ["Act_E5_7B_DormsCorridor_HintMaxRoom_Scripted_Max_010"] = "Oh, gracias a Dios soy yo misma de nuevo... ahora sé dónde ir.",
  ["Act_E5_7B_DormsCorridor_HintRachelRoom_Scripted_Max_010"] = "¿Me pregunto si Rachel tiene una habitación por aquí?",
  ["Act_E5_7B_DormsCorridor_HintStealth_Scripted_Max_010"] = "Bien, entonces mi poder de rebobinado sí funciona aquí... puedo usarlo si tengo cuidado.",
  ["Act_E5_7B_DormsCorridor_HintStealth_Scripted_Max_020"] = "Sí, Max, también puedes manipular el tiempo.",
  ["Act_E5_7B_DormsCorridor_HintVictoriaRoom_Scripted_Max_010"] = "La habitación de Victoria tiene que estar cerca...",
  ["Act_E5_7B_DormsCorridor_LostLines_Scripted_Max_010"] = "¿Donde estoy exactamente?",
  ["Act_E5_7B_DormsCorridor_LostLines_Scripted_Max_030"] = "Demasiadas puertas para elegir...",
  ["Act_E5_7B_DormsCorridor_LostLines_Scripted_Max_040"] = "No quedarás atrapada aquí... ¡Encuentra la puerta correcta, Max!",
  ["Act_E5_7B_DormsCorridor_Squirrels_Photo_Max_010"] = "Esta va por Samuel...",
  ["Act_E5_7B_LabyStealth_BottleRange_Look01_Max_010"] = "Parece que aun hay botellas que encontrar... qué felicidad.",
  ["Act_E5_7B_LabyStealth_BottleRange_Look02_Max_020"] = "Chloe, esto es culpa tuya... Me las pagarás.",
  ["Act_E5_7B_LabyStealth_BottleRange_Photo_Max_010"] = "Necesito una prueba de que las botellas querían acabar conmigo, solo por si acaso...",
  ["Act_E5_7B_LabyStealth_Bottle_Interact01_Max_010"] = "Ay, no... Botellas. Esto podría ser el infierno.",
  ["Act_E5_7B_LabyStealth_Bottle_Interact02_Max_020"] = "Bueno, estas no son demasiado difíciles de encontrar.",
  ["Act_E5_7B_LabyStealth_Bottle_Interact03_Max_030"] = "¿Cuándo adquirí mal karma con las botellas?",
  ["Act_E5_7B_LabyStealth_Bottle_Interact04_Max_040"] = "¿Queda una más?",
  ["Act_E5_7B_LabyStealth_Bottle_Interact05_Max_050"] = "Por favor, que sea la última...",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_010"] = "Jefferson viene por mí de nuevo... No...",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_030"] = "Esto es como un laberinto malvado...",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_040"] = "¡El faro está allá!",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_050"] = "Quizás esté más segura en el faro... Quizá despertaré...",
  ["Act_E5_7B_LabyStealth_IdleLines_Scripted_Max_060"] = "Maldición, Max, ¡despierta!",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_010"] = "Max, siéntate. Tómate un 'tiempo fuera' sin importar lo que pase...",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_020"] = "Si esta es mi pesadilla, déjenme tener un santuario...",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_030"] = "Por supuesto aquí es donde Chloe... y Rachel... solían ocultarse del mundo...",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_040"] = "Pero no puedo ocultarme durante mucho tiempo. En cualquier realidad que estoy se siente como un mal sueño...",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_050"] = "¿Qué, no estoy aprendiendo mi lección?",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_060"] = "Quizás tu lección real es salir de este lugar…",
  ["Act_E5_7B_LabyStealth_ZenSequence_Zen_Max_070"] = "Sólo no se asustes, Max. Que ellos te teman.",
  ["Act_E5_7B_LivingRoom_WilliamLines_Scripted_Max_010"] = "Oh, mierda, Warren. Eso es demasiado extraño... y jodidamente escalofriante.",
  ["Act_E5_7B_LivingRoom_WilliamLines_Scripted_Max_020"] = "Sólo por si necesito evidencia…",
  ["Act_E5_7B_Nightmare_RachelGraffiti_Look02_Max_010"] = "¿Eso es todo? La tercera claramente no es la vencida.",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_004"] = "Llámame \"Mark.\" Necesitamos ponernos al corriente sobre todo el tiempo que hemos desperdiciado...",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_005"] = "Quisiera preguntarte si... ¿Te gustaría pasar el resto de tu vida en mi cuarto oscuro? Tu pureza me inspira tanto y podríamos ser tan felices juntos... ¿Quién necesita selfis cuando podemos hacer retratos?",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_008"] = "Por supuesto, Max... puedo retratarte una y otra vez... serás mi modelo para toda la vida... y la muerte...",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_009"] = "Sí, estarás posando... para mí. Hay tantos ángulos tuyos que quiero exponer ante el mundo...",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_010"] = "Chloe nunca te podría apreciar en la misma forma que yo, Maxine...",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_015"] = "Especialmente porque no hay nadie más en tu vida... Yo también te amo, Max.",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_016"] = "Seremos tan felices en la oscuridad. Solo asegúrate de permanecer pura... No me gustaría que te ensucies como Rachel o Chloe.",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_017"] = "Espero que no te importen las agujas o la cinta adhesiva...",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Jefferson_018"] = "Y sí, insisto en llamarte Maxine... para siempre.",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_002"] = "He soñado con el día en que finalmente me digas... lo amo, Sr. Jefferson.",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_003"] = "Prefiero llamarlo \"nuestro cuarto oscuro\". Es el único lugar en el que me siento a salvo y protegida de la tormenta.",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_006"] = "Mis selfis son una porquería... necesito que me fotografíe un verdadero artista... soy una farsa...",
  ["Cue_E5_7B_ArtClass_CHJefferson_Phase01_Max_007"] = "Ya era hora de que alguien matara a Chloe... De solo pensar cuántas veces esa perra casi hizo que me maten... ¡Nos has hecho un favor a los dos!",
  ["Cue_E5_7B_ArtClass_Dial04_REV_Courtney_010"] = "¿Por qué alguien querría llevar una estúpida cámara Instamatic?",
  ["Cue_E5_7B_ArtClass_Dial04_REV_Taylor_020"] = "Porque Max quiere que todo el mundo vea lo genial que es.",
  ["Cue_E5_7B_ArtClass_Dial04_REV_Taylor_040"] = "Es tan tímida que se saca selfis con una cámara gigante.",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_010"] = "Ahora, ¿me pueden dar un ejemplo de un fotógrafo que capturó perfectamente la condición humana en blanco y negro? ¿Alguien? ¿Bueller?",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_030"] = "¡Bien, Victoria! ¿Por qué Arbus?",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_050"] = "Veía a la humanidad como una especie torturada, ¿verdad? Y, francamente, eso es pura mierda. Shhh, no lo comenten. Hablando en serio, podría poner a cualquiera de ustedes en un rincón oscuro y plasmarlos en un momento de desesperación. ",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_070"] = "Yo también, Victoria. Él capturó la esencia de los Estados Unidos de posguerra, la generación beat. Y había sinceridad sobre las condiciones económicas de la época, pero también belleza en la lucha. No hay belleza sin el beat. Lo que explica por qué Frank fue la musa fotográfica de Kerouac, y ambos fueron los grandes cronistas de la década de 1950. Bueno... Todos hemos visto esa foto icónica de Kerouac en el balcón —y si no la vieron, mal, mal— que captura la soledad urbana romántica del poeta del siglo XX. ¿Me siguen?",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_080"] = "Ahora, contrasten la profunda Americana de Frank, con fotografías surrealistas de Salvador Dalí. Al igual que Cocteau, era un verdadero hombre renacentista, y sus famosos autorretratos son ejemplos tempranos de esa palabra tan horrible que ustedes aman tanto, la \"selfi\"... Es una gran tradición, y yo lucho con pasión a favor de su derecho a la libre expresión. O selfi-expresión. Eh, lo siento, lo sé.",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Jefferson_090"] = "Así que, si alguien quiere denunciar el retrato como narcisismo moderno, que vuelvan cientos de años atrás para culpar a la sociedad. Hablando de preguntas, apuesto a que pensaron que iba a hablar sin parar hasta que sonara la campana. Es su turno de enseñarnos. Ahora, según los capítulos que seguro que memorizaron, ¿quién me puede decir el nombre del proceso que llevó al nacimiento del autorretrato?",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Victoria_020"] = "Diane Arbus.",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Victoria_040"] = "Por sus imágenes de rostros sin esperanza. Uno se siente totalmente atrapado por los ojos de esas madres e hijos tristes.",
  ["Cue_E5_7B_ArtClass_JeffGivingLesson_Victoria_060"] = "Tengo que admitir que no soy una gran fanática de su trabajo. Prefiero a... Robert Frank.",
  ["Cue_E5_7B_ArtClass_JeffersonTalks_Jefferson_010"] = "Te veo, Max Caulfield. No pienses en irte de aquí hasta que hablemos de tu participación.",
  ["Cue_E5_7B_ArtClass_MaxAwake01_Jefferson_030"] = "El famoso Alfred Hitchcock dijo que las películas eran \"pequeños trozos de tiempo\", pero podría estar hablando de fotografía, y es probable que lo hiciera. Estos trozos de tiempo nos pueden enmarcar en la gloria y en el dolor; de la luz a la sombra; del color al claroscuro...",
  ["Cue_E5_7B_ArtClass_MaxAwake01_Max_010"] = "¡Vaya!",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Alyssa_030"] = "Los abusadores nunca cambian.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Alyssa_100"] = "Si fuera un miembro del club Vortex, nunca lo harían...",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Alyssa_170"] = "A Blackwell le sobran idiotas.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Evan_070"] = "A menos que pudiera viajar en el tiempo, McCurry nació cinco años después de la foto del \"Soldado cayendo\".",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Evan_080"] = "Veamos si lo mereces, Max. Tienes que responder una pregunta simple: ¿Quién fotografió el famoso \"Soldado cayendo\"?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Evan_090"] = "Caray, no puedes diferenciar entre la fotografía callejera y el fotoperiodismo...",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_010"] = "Espera, Max. Ven aquí.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_020"] = "Te ves un poco estresada. ¿Estás bien?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_030"] = "Estás sudando. ¿Seguro que no pasa nada más? Puedes ser sincera conmigo, Max.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Principal_040"] = "¿O hiciste algo malo...?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Alyssa_030"] = "Los abusadores nunca cambian.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Alyssa_100"] = "Si fuera un miembro del club Vortex, nunca lo harían...",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Alyssa_170"] = "Blackwell tiene una reserva de imbéciles.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Evan_070"] = "A menos que pudiera viajar en el tiempo, McCurry nació cinco años después de la foto del \"Soldado cayendo\".",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Evan_080"] = "Veamos si lo mereces, Max. Debes responder una pregunta simple: ¿Quién fotografió al famoso \"Soldado cayendo\"?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Evan_090"] = "Caray, no puedes diferenciar entre la fotografía callejera y el fotoperiodismo...",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_010"] = "Espera, Max. Ven aquí.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_020"] = "Te ves un poco estresada. ¿Estás bien?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_030"] = "Estás sudando. ¿Eso es lo único que piensas?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Principal_040"] = "¿O hiciste algo malo...?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Samuel_180"] = "Las ardillas siempre vienen en la mañana... por comida. Puedo oírlas susurrar... ¿qué animales ven en el bosque?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Samuel_360"] = "Mi padre era pescador y me llevaba a escuchar el canto de las ballenas... Ahora escucho su llanto.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_010"] = "¡Oye! ¡Te conozco! Eres la chica nueva, de la clase de Jefferson. Es un tipo fabuloso, ¿no?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_020"] = "Apuesto a que en todas esas galerías pretenciosas envidian que Mark Jefferson enseñe fotografía en Blackwell... además es bastante sexy para un hombre de su edad.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_030"] = "El Sr. Jefferson tiene su propio estilo.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Stella_040"] = "La he visto con otros chicos populares, como Victoria... pero no es mi ambiente.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Trevor_010"] = "Pensé que me mirabas fijamente a la cara. Creo que ahora lo sabes... y también Justin.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_REV_Trevor_020"] = "Lo reprendí, él estaba tranquilo. De cualquier forma, nadie tiene secretos en Blackwell... te veo en clase, Max.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Samuel_180"] = "Las ardillas siempre vienen por la mañana... a buscar comida. Puedo oír que me susurran... ¿Qué animales viste en el bosque?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Samuel_360"] = "Mi padre era pescador y me llevaba a escuchar el canto de las ballenas... Ahora escucho su llanto.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_010"] = "¡Oye! ¡Te conozco! Eres la chica nueva, de la clase de Jefferson. Es un tipo fabuloso, ¿no?",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_020"] = "Apuesto a que en todas esas galerías pretenciosas envidian que Mark Jefferson enseñe fotografía en Blackwell... además es bastante sexy para un hombre de su edad.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_030"] = "El Sr. Jefferson tiene su propio estilo.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Stella_040"] = "La he visto con otros chicos populares, como Victoria... pero no es mi ambiente.",
  ["Cue_E5_7B_Corridor_BackgroundVoices_Trevor_010"] = "Pensé que me mirabas fijamente a la cara. Creo que ahora lo sabes... y también Justin.",
  ["Cue_E5_7B_Corridor_Dial05_REV_Juliet_010"] = "Todavía no me dijiste lo linda que me veo.",
  ["Cue_E5_7B_Corridor_Dial05_REV_Juliet_030"] = "¿Solo linda?",
  ["Cue_E5_7B_Corridor_Dial05_REV_Juliet_050"] = "Entonces, podría enviarte una foto especial durante la clase.",
  ["Cue_E5_7B_Corridor_Dial05_REV_Zachary_020"] = "Estaba por hacerlo. Siempre te ves bien.",
  ["Cue_E5_7B_Corridor_Dial05_REV_Zachary_040"] = "Sexi.",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_010"] = "Ay, vamos, ten paciencia...",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_020"] = "Dobla esa esquina...",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_030"] = "¡Uuuh, mierda! Lo siento, granjeros.",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_040"] = "¡Vamos, cambia!",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_050"] = "Sal de mi camino, Ferrari, ¿sí?",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_060"] = "Ya casi llegamos...",
  ["Cue_E5_7B_Corridor_Dial06_Brooke_070"] = "¿Tercer lugar? ¡Es una porquería! ¡Imbéciles!",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_010"] = "Ay, vamos, ten paciencia...",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_020"] = "Dobla esa esquina...",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_030"] = "¡Uuuh, mierda! Lo siento, granjeros.",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_040"] = "¡Vamos, cambia!",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_050"] = "Sal de mi camino, Ferrari, ¿sí?",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_060"] = "Ya casi llegamos...",
  ["Cue_E5_7B_Corridor_Dial06_REV_Brooke_070"] = "¿Tercer lugar? ¡Es una porquería! ¡Imbéciles!",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_010"] = "No me molesta fregar, pero ¿podrían levantar sus malditos pies?",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_020"] = "Dejando huellas sucias por todos lados...",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_030"] = "Aunque me encanta este trapeador, lo deja como los chorros del oro.",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_040"] = "Me siento un fantasma para estos chicos. Apenas me ven.",
  ["Cue_E5_7B_Corridor_Dial07_REV_Samuel_050"] = "Pobre muchacha. Nadie debería desaparecer así...",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_010"] = "No me molesta fregar, pero ¿podrían levantar sus malditos pies?",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_020"] = "Dejando huellas sucias por todos lados...",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_030"] = "Aunque me encanta este trapeador, lo deja como los chorros del oro.",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_040"] = "Me siento un fantasma para estos chicos. Apenas me ven.",
  ["Cue_E5_7B_Corridor_Dial07_Samuel_050"] = "Pobre muchacha. Nadie debería desaparecer así...",
  ["Cue_E5_7B_Corridor_Dial08_CitizenM1_020"] = "Muy gay.",
  ["Cue_E5_7B_Corridor_Dial08_CitizenM1_060"] = "Sí.",
  ["Cue_E5_7B_Corridor_Dial08_CitizenM1_090"] = "Es un sabihondo.",
  ["Cue_E5_7B_Corridor_Dial08_Daniel_040"] = "Soy español.",
  ["Cue_E5_7B_Corridor_Dial08_Daniel_070"] = "Logan, solo déjame en paz.",
  ["Cue_E5_7B_Corridor_Dial08_Daniel_100"] = "No, solo intento ir a clase.",
  ["Cue_E5_7B_Corridor_Dial08_Logan_010"] = "Daniel, te ves especialmente gay el día de hoy.",
  ["Cue_E5_7B_Corridor_Dial08_Logan_030"] = "¿También hay mexicanos gay?",
  ["Cue_E5_7B_Corridor_Dial08_Logan_050"] = "Oh, \"mucho grande diferencia\".",
  ["Cue_E5_7B_Corridor_Dial08_Logan_080"] = "No eres mi jefe, hermano.",
  ["Cue_E5_7B_Corridor_Dial08_REV_CitizenM1_020"] = "Muy gay.",
  ["Cue_E5_7B_Corridor_Dial08_REV_CitizenM1_060"] = "Sí.",
  ["Cue_E5_7B_Corridor_Dial08_REV_CitizenM1_090"] = "Es un sabihondo.",
  ["Cue_E5_7B_Corridor_Dial08_REV_Daniel_040"] = "Soy español.",
  ["Cue_E5_7B_Corridor_Dial08_REV_Daniel_070"] = "Logan, solo déjame en paz.",
  ["Cue_E5_7B_Corridor_Dial08_REV_Daniel_100"] = "No, solo intento ir a clase.",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_010"] = "Daniel, te ves especialmente gay el día de hoy.",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_030"] = "¿También hay mexicanos gay?",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_050"] = "Oh, \"mucho grande diferencia\".",
  ["Cue_E5_7B_Corridor_Dial08_REV_Logan_080"] = "No eres mi jefe, hermano.",
  ["Cue_E5_7B_Corridor_Dial09_REV_Dana_060"] = "¿Cuál es el punto de venir a clase si estás fumado?",
  ["Cue_E5_7B_Corridor_Dial09_REV_Justin_050"] = "Dana, ya lo he hecho. No fumo desde... que me desperté a las siete.",
  ["Cue_E5_7B_Corridor_Insertion_REV_Max_010"] = "Bienvenida al mundo real...",
  ["Cue_E5_7B_Corridor_Insertion_REV_Max_020"] = "Realmente necesito ir al baño. Lavarme la cara y asegurarme de que no me veo como una perdedora total.",
  ["Cue_E5_7B_DarkRoom_ChloeDark_IGE_Chloe_020"] = "¿Por qué te tocó a ti tener el poder de rebobinar? Ni siquiera sabes cómo usarlo...",
  ["Cue_E5_7B_DarkRoom_ChloeDark_IGE_Chloe_040"] = "Rachel está muerta y tú todavía vives. La vida es... tan injusta.",
  ["Cue_E5_7B_DarkRoom_ChloeDark_IGE_Chloe_060"] = "Desearía que nunca hubieras regresado a Arcadia Bay... Tú eres la verdadera tormenta.",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Chloe_030"] = "Max es una niña imbécil...",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Chloe_060"] = "Estoy harta de sus idioteces hipster.",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_010"] = "Creo que serías perfecta para mi nueva serie de fotografías sobre el retro-grunge…",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_020"] = "Tienes las mismas cualidades que me encantaban de Rachel Amber... pero no Max...",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_040"] = "Ay, Dios, lo sé... y nunca se calla, ¿verdad?",
  ["Cue_E5_7B_DarkRoom_JeffersonDark_IGE_Jefferson_070"] = "Creo que todos en Blackwell se cansaron de Max... Probémoslo.",
  ["Cue_E5_7B_DarkRoom_NathanDark_IGE_Chloe_020"] = "Aburrimiento. Además, es como mi marioneta personal.",
  ["Cue_E5_7B_DarkRoom_NathanDark_IGE_Nathan_010"] = "¡Carajo, eres una perra sexy! ¿Por qué eres amiga de Max?",
  ["Cue_E5_7B_DarkRoom_NathanDark_IGE_Nathan_030"] = "Oí que... ¿quieres divertirte? Tengo una farmacia en mi cuarto...",
  ["Cue_E5_7B_DarkRoom_VictoriaDark_IGE_Chloe_010"] = "Vaya, Victoria... Eres una verdadera mujer... No una niñita, como Max...",
  ["Cue_E5_7B_DarkRoom_VictoriaDark_IGE_Victoria_040"] = "Me encantan tus tatuajes, Chloe. Se ven taaaan sexy.",
  ["Cue_E5_7B_DarkRoom_VictoriaDark_IGE_Victoria_060"] = "No puedo creer que tardamos tanto en estar juntas...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_020"] = "¡Órale, Warren! Pensé que andabas tras Max...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_021"] = "¡Bravo, Warren! Pensé que te gustaba Max...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_022"] = "¡Mierda, Warren! ¡Max nos tira la onda a los dos!",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_023"] = "¡Bravo, Warren! Pensé que te gustaba Max...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_040"] = "La hubieras visto intentar tirarme la onda en mi habitación... Qué poca madre.",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_041"] = "Escuché eso. Los... nerds no son mi tipo, pero tú eres muy lindo...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_042"] = "Ahora está tratando de enredarse con nosotros dos...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_043"] = "Supongo que \"no somos su tipo\"... ¿como si Max tuviera un puto tipo?",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Chloe_060"] = "Mierda, mira a Max espiándonos... ¡Toma una puta foto, perra! ¡O tómate una selfi!",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_030"] = "Ella no es gran cosa... De modo que, ¿a quién le importa si no me besa?",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_031"] = "No después de que me besó... Tenía un aliento bien culero  y no usó lengua...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_032"] = "Parece que no es tan inocente como actúa...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_033"] = "Seguramente a ella no le gusto nada... ¿qué importa?",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_050"] = "Max debería verme hacer esto... Ven aquí.",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_051"] = "De cualquier forma, no me interesa Max, así que sigamos...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_052"] = "Solo quiero volverme chango contigo, Chloe... Ven aquí...",
  ["Cue_E5_7B_DarkRoom_WarrenDark_IGE_Warren_053"] = "Pero así es... Le gusta el Sr. Jefferson... Ahora ven aquí...",
  ["Cue_E5_7B_Diner_AlyssaDiner_IGE_Alyssa_010"] = "¿Siempre me has apoyado y ahora me dejas morir? Gracias, Max.",
  ["Cue_E5_7B_Diner_AlyssaDiner_IGE_Alyssa_020"] = "Pensé que eras de las pocas personas en quienes podía confiar en Blackwell. De verdad...",
  ["Cue_E5_7B_Diner_AlyssaDiner_IGE_Alyssa_030"] = "Aun si yo muero, ¿cómo puedes dejar que tantas personas mueran? No lo merecen...",
  ["Cue_E5_7B_Diner_BinkNightmare_MaxGhost_010"] = "Ah, vaya, hablando de Roma...",
  ["Cue_E5_7B_Diner_BrookeDiner_IGE_Brooke_020"] = "Max, espero que hagas lo correcto. Espero...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_001"] = "¿Mierda, \"de verdura\"? Yo soy tú, estúpida. O soy una de las muchas Max que has dejado atrás.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_003"] = "Oh, así que quieres ayuda... Pensaste que podrías controlar a todos y a todo, ¿eh? ¿Controlar el tiempo con solo un dedo?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_006"] = "Deja de hacerte la inocente. Has dejado un rastro de muerte detrás de ti. Incluso dejaste a ese acosador de Madsen matar a Jefferson... Eso es enfermo. Eres una asesina a sangre fría, peor que él o Nathan.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_008"] = "No, solo quería ser popular. Y una vez que tuviste estos poderes asombrosos, tu gran plan fue engañar a la gente para que pensara que te importaba un comino.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_009"] = "No, pero no te importó usarlo para agradarle a la gente. Como si te importaran.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_012"] = "Eso no te hace menos una asesina.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_013"] = "Oh, al jurado le encantará saber sobre tus asombrosas habilidades de viaje en el tiempo.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_016"] = "¿Diciéndole a la gente lo que quiere oír? Solo buscabas un atajo porque no puedes hacer amigos por ti misma.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_017"] = "Ya era hora de que admitieras eso. Pero es demasiado tarde después de todo lo que hiciste...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_020"] = "Eres una maldita hipócrita. Solo mira todo el dolor que has causado...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_021"] = "Por favor, deja de hacerte la inocente. Eres una maldita hipócrita. Dejaste un rastro de muerte y sufrimiento detrás de ti...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_023"] = "No te atrevas a hablar de nuestra mamá así... ¡ja! ¿y qué hay de Frank? ¿esa bala que le metiste no fue tu culpa?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_024"] = "No te atrevas a hablar de nuestra mamá así... ¡Ja!|¿Y qué hay de toda esa mierda que sí fue tu culpa?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_025"] = "Espera, déjame adivinar... Jodiste el tiempo y el espacio por tu preciosa punk Chloe. ¿Piensas que ella vale todo eso?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_029"] = "Vaya, eres tan estúpida. Me da pena que tengamos el mismo nombre. Y algún día Chloe destruirá...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_030"] = "¡Dios, eres tan desinteresada ahora, Mahatma Max! Qué mal que gastaras tu poder en dramas escolares.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_031"] = "No bromeo. Chloe te atrapó con su drama... Armas, drogas, Rachel... Incluso robar dinero del fondo para discapacitados. Solo te está usando, güey.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_032"] = "Oh, sí, ignoraste a tu \"mejor amiga\" durante cinco años mientras ella pasaba por un infierno... Vaya amiga.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_033"] = "No bromeo. Chloe te atrapó con su drama... armas, drogas, Rachel... Solo te está usando, chica.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_035"] = "Porque dejas que abuse de ti. Eso se llama \"Síndrome de Estocolmo\".|Pero ya que no quieres aprender por las buenas... lo harás por las malas. Como Rachel.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_037"] = "Me cuidaría más de que no nos mate Chloe que Jefferson... Max, ¿realmente piensas que es nuestra amiga? ¿Que te respeta aunque sea un poco?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_038"] = "Me cuidaría más de que no nos mate Chloe que Jefferson... Max, ¿realmente piensas que siente algo por nosotras? Solo eres otra marioneta...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_MaxGhost_039"] = "Como cuando ella te pidió que pusieras fin a su vida e hicieras lo que ella no pudo hacer por sí misma.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_002"] = "¿Quién...? ¿Quién eres?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_004"] = "Yo no lo elegí. ¡No pedí rebobinar el tiempo!",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_005"] = "Intenté ayudar... solo quería hacer lo correcto...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_007"] = "¿Puedes sacarme de aquí?",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_010"] = "¡Mentira, eso fue defensa propia! ¡Nunca tuve la intención de matar a nadie!",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_011"] = "No, soy una sobreviviente. No tengo experiencia en viajes por el tiempo o detener psicópatas como Jefferson. Hice lo que tenía que hacer.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_014"] = "Es verdad... desperdicié mi poder en intentar ser amiga de todos...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_015"] = "Me importa... es por eso que intenté hacer amigos...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_018"] = "Eso no es verdad... tengo grandes amigos. Y usé mis poderes para el bien...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_019"] = "Sé lo qué soy... Solo estás intentando lastimarme.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_022"] = "Eso no fue mi culpa, hija de puta.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_026"] = "Por supuesto. Es mi mejor amiga.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_027"] = "Todos lo valemos. Esto ya no solo se trata de Chloe... o de mí.",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_028"] = "Tiene que ser mi destino salvarla... No estaría atrapada aquí si no creyera eso...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_034"] = "Chloe hace un mejor trabajo para hacer que me sienta culpable que tú...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_036"] = "Solo cállate. Ya no me asustas...",
  ["Cue_E5_7B_Diner_CHMaxGhost_Phase01_Max_041"] = "Pero... todavía tengo grandes amigos. Y mi poder ayudó a varias personas...",
  ["Cue_E5_7B_Diner_CourtneyDiner_IGE_Courtney_010"] = "No nos mates, Max.",
  ["Cue_E5_7B_Diner_CourtneyDiner_IGE_Courtney_020"] = "Por favor, sálvanos.",
  ["Cue_E5_7B_Diner_DanaDiner_IGE_Dana_010"] = "Supongo que jamás bailaré de nuevo, Max...",
  ["Cue_E5_7B_Diner_DanielDiner_IGE_Daniel_010"] = "Max, quiero que sepas cuánta confianza me diste en mí misma... nadie hizo algo así por mí.",
  ["Cue_E5_7B_Diner_DavidDiner_IGE_David_010"] = "Max, eres exactamente la clase de soldado que quisiera tener a mi lado en una guerra.",
  ["Cue_E5_7B_Diner_EvanDiner_IGE_Evan_010"] = "Oh, Max, ¿qué sentido tenía salvarme para luego dejarme morir?",
  ["Cue_E5_7B_Diner_EvanDiner_IGE_Evan_020"] = "Ah, déjame entender: ¿no te molestaste en salvarme a mí o a Arcadia Bay? Qué niña más patética.",
  ["Cue_E5_7B_Diner_FishermanDiner_IGE_Fisherman_010"] = "Max, salvaste mi vida y me diste la oportunidad de atrapar un último pez...",
  ["Cue_E5_7B_Diner_FishermanDiner_IGE_Fisherman_020"] = "Como te dije antes... los pescadores viejos nunca mueren... hasta ahora.",
  ["Cue_E5_7B_Diner_FrankDiner_IGE_Frank_010"] = "¿Así que me dejas morir? ¿Y también a todos mis clientes? ¿Qué te pasa, Max?",
  ["Cue_E5_7B_Diner_FrankDiner_IGE_Frank_020"] = "Sé que las cosas estaban mal entre nosotros, pero eso no quiere decir que merezca morir...",
  ["Cue_E5_7B_Diner_FrankDiner_IGE_Frank_030"] = "Mierda, Max, pensé que éramos un equipo... ahora moriré sola...",
  ["Cue_E5_7B_Diner_HomelessDiner_IGE_Homeless_010"] = "Gracias por la advertencia, Max... me trataste como a un ser humano, no como basura... ojalá hagas lo mismo por todos en la ciudad...",
  ["Cue_E5_7B_Diner_HomelessDiner_IGE_Homeless_020"] = "Ya viví para siempre... quizás también puedas ayudar a otros a vivir...",
  ["Cue_E5_7B_Diner_JoyceDiner_IGE_Joyce_010"] = "Linda, siempre pensé en ti como en una hija... No nos dejes morir.",
  ["Cue_E5_7B_Diner_JulietDiner_IGE_Juliet_020"] = "Max, por favor, sálvanos.",
  ["Cue_E5_7B_Diner_JustinDiner_IGE_Justin_030"] = "Matarme no es genial, naaada genial.",
  ["Cue_E5_7B_Diner_KateDiner_IGE_Kate_020"] = "Por favor, Max. No me mates, así podemos finalmente salir a tomar el té.",
  ["Cue_E5_7B_Diner_LoganDiner_IGE_Logan_010"] = "¿Así es como Max toma venganza?",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_010"] = "Max, espero que puedas vivir contigo misma después de esto.",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_020"] = "Hijo de puta, esto dolerá...",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_030"] = "Max, ¿puedes llamar a mi madre en Portland y decirle que la amo?",
  ["Cue_E5_7B_Diner_MenVoicesDiner_IGE_Male01_040"] = "Justo cuando estaba por iniciar una nueva vida en California...",
  ["Cue_E5_7B_Diner_NathanDiner_IGE_Nathan_010"] = "Max... en serio lamento ser un bastardo. Habría sido genial ser amigos... únicamente quiero que los demás no sufran como yo...",
  ["Cue_E5_7B_Diner_SamuelDiner_IGE_Samuel_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7B_Diner_SamuelDiner_IGE_Samuel_020",
  ["Cue_E5_7B_Diner_StellaDiner_IGE_Stella_010"] = "Por favor, no me dejes morir.",
  ["Cue_E5_7B_Diner_TrevorDiner_IGE_Trevor_010"] = "Vaya, Max, cuando finalmente encontré una chica genial para salir... tenías que matarnos. Esto apesta.",
  ["Cue_E5_7B_Diner_TruckerDiner_IGE_Trucker_010"] = "Breaker, Breaker... Gracias por salvarme y llevar la carga, amiga. Ese es un gran 10-4.",
  ["Cue_E5_7B_Diner_TruckerDiner_IGE_Trucker_020"] = "Está bien si me voy... pagué mis deudas... es hora de pagar las tuyas.",
  ["Cue_E5_7B_Diner_VictoriaDiner_IGE_Victoria_020"] = "Ojalá hubiéramos sido amigas, Max. Pero, por favor... no me dejes morir así... todavía soy una adolescente...",
  ["Cue_E5_7B_Diner_WarrenDiner_IGE_Warren_020"] = "No puedo creer que te dejara besarme... ahora me matarás...",
  ["Cue_E5_7B_Diner_WarrenDiner_IGE_Warren_050"] = "Yo era feliz solo siendo tu amigo... ¿por qué quieres que todos tus amigos mueran?",
  ["Cue_E5_7B_Diner_WellsDiner_IGE_Wells_010"] = "No sé si he sido el mejor Director para ti... pero has sido un gran Héroe Cotidiano para nosotros...",
  ["Cue_E5_7B_Diner_WomenVoicesDiner_IGE_Female01_030"] = "Supongo que mi esposo y mi bebé tendrán que seguir adelante sin mí...",
  ["Cue_E5_7B_Diner_WomenVoicesDiner_IGE_Female01_040"] = "No es así como quería pasar mi última hora en la Tierra...",
  ["Cue_E5_7B_Diner_ZacharyDiner_IGE_Zachary_020"] = "/!\\ WARNING /!\\ Text not localized : Cue_E5_7B_Diner_ZacharyDiner_IGE_Zachary_020",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Chloe_040"] = "Redoble de tambor, por favor... he aquí la copia de las llaves de Blackwell. Gracias, padrastro idiota.",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Chloe_050"] = "Bien, podrías buscar la llave... solo por si acaso.",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Frank_060"] = "¡Regrésame las llaves, perra!",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Max_010"] = "Tiene que haber una llave por aquí... ¡la encontré, Max!",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Max_020"] = "No pasa nada, oficial... solo estoy aquí para robar las llaves de un traficante de drogas.",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_Max_030"] = "Soy la ama de llaves.",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_070"] = "Me olvidé de ti, amiguito... ¡suelta las llaves!",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_080"] = "Bien, ¿dónde pusiste las llaves la vez anterior...? Piensa, piensa... al diablo.",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_090"] = "Max, este no es el mejor momento para una broma. La llave, por favor.",
  ["Cue_E5_7B_Dormitory_KeyDoor_Rdm_William_100"] = "Ah, ¿eso es todo? Haberlo dicho antes. ¿Qué te parece si también te doy las llaves de mi RV?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm02_Jefferson_030"] = "También extraño a Rachel. Pero piensa en ti, Max. El director Wells me comentó acerca de lo que dijiste que ocurrió en el baño...",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Chloe_030"] = "¡Dios, estaba jodiendo con el cerdo de Frank! ¡La perra me mintió en mi cara, Max! No puedo confiar en nadie nunca más. Todos pretenden que les importo, hasta que no es así. ¡Incluso tú!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Chloe_060"] = "Solo tú y yo. Nadie más. Y no tengo miedo porque tú eres la de los poderes. Siento que estamos muy cerca de Rachel... Debemos encontrarla, Max.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_David_020"] = "Me imaginé que estarías aquí. ¿Es tu disfraz de Halloween de Rachel Amber?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Frank_040"] = "Porque ella se ve preciosa en ella, y tú te ves horrible. Apuntarme con un arma no te hace más atractiva.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Joyce_010"] = "Max Caulfield, ¿estás celosa de Rachel?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Rdm03_Nathan_050"] = "¿Rachel? ¡Me vale madre!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_010"] = "Rachel Amber. Era mi... ángel. Después de que papá muriera y tú te mudaras, me sentí abandonada. Rachel me salvó la vida.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_030"] = "Hace seis meses... simplemente se fue de Arcadia. Sin decir una palabra. Sin mí...",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_050"] = "A diferencia de ti, ella me lo hubiera dicho, ¿sabes? Algo le ocurrió.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Chloe_060"] = "Antes de que Rachel se fuera, dijo haber conocido a alguien que le cambió la vida... Entonces, desapareció.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Max_020"] = "Así que Rachel tomó mi lugar. Me alegro que ella haya estado para ti.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq01_Max_040"] = "¿Cómo sabes que desapareció? Quizás quería comenzar una vida completamente nueva...",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq02_Chloe_010"] = "Es el brazalete de Rachel. ¿Por qué carajo tienes su brazalete?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq02_Frank_020"] = "Cálmate, ¿sí? Fue un regalo.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq03_Chloe_020"] = "No son tan distintas. Ella tenía... tiene muy buen ojo para la fotografía y el arte. Además, es una sabelotodo, como tú. Seguro que las tres seríamos \"mejores amigas por siempre\".",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq03_Max_010"] = "¿Crees que Rachel y yo habríamos sido amigas?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq05_Chloe_020"] = "Tú también lo hubieras pensado. Inteligente, sexy y atrevida... como yo, ¿no?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq05_Max_010"] = "Parece que sentías algo muy especial por Rachel.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq05_Max_030"] = "¡Obvio! Tal vez Rachel se habría peleado por nosotras.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Chloe_050"] = "¿Como tú? Yo la quería, idiota. Y ella a mí. Lo sé.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_010"] = "Cuando Rachel desapareció, perdí prácticamente todo...",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_020"] = "No tolero no saber dónde está... sin escuchar su voz... o su risa... nunca más.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_040"] = "¡Es demasiado tarde! ¡Se fue! ¡Ni siquiera la conoces!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Frank_060"] = "Chloe, no sabes ni un carajo. Eras parte de su problema. Siempre intentabas alejarla de mí... ¡Siempre!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq06_Max_030"] = "No tenemos mucho tiempo, Frank. Rachel te necesita.",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_020"] = "¡No, por favor!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_030"] = "Rachel...|Por Dios, Rachel...|No... no... no...|Por favor, no... no ella...",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_050"] = "Rachel... ¿por qué?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Chloe_070"] = "La quería tanto... ¡No puede haber muerto! ¿En qué mundo vivimos? ¿¡Quién haría algo así!?",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Max_010"] = "Chloe... ¡detente! ¡Mira!",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Max_040"] = "Chloe…",
  ["Cue_E5_7B_Dormitory_RachelDoor_Seq08_Max_060"] = "Lo siento, Chloe. Lo siento tanto...",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_010"] = "Creo que mi fotografía para el concurso quizás sea demasiado buena.",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_020"] = "Por sus imágenes de rostros sin esperanza. Uno se siente totalmente atrapado por los ojos de las madres e hijos tristes.",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_030"] = "Ahora estás atrapada por completo en la Zona Retro. Cara triste.",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_040"] = "¡Agh! ¡Agua en mi casimir! ¿Sabes cuánto cuesta este maldito atuendo?",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_050"] = "Ah, mira, es Max Caulfield, la perra del selfi de Blackwell",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_060"] = "¿Por qué no te vas a la mierda con tu selfi?",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_070"] = "¡No me toques, loco!",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_080"] = "No seas tímida. Es genial que hayas marcado un récord de lengua en video...",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_090"] = "Ay, pobre de ti, siento mucho que seas una zorra viral. Seguro se divirtió.",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_100"] = "¡Shh! Creo que puede oírnos...",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_110"] = "¿Pensabas que éramos mejores amigas para siempre o algo así?",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_120"] = "Sé que fue un día horrible; sepa que puede hablar conmigo siempre que lo necesite, Sr. Jefferson.",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_130"] = "Será mejor que me elija... si no, podría contarle a todos que me ofreció seleccionar mi foto a cambio de ciertos \"favores\" o algo así...",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_140"] = "Bien, Max Caulfield, podría decidir dejarte entrar al club Vortex...",
  ["Cue_E5_7B_Dormitory_VictoriaDoor_Rdm_Victoria_150"] = "Es difícil de creer, pero no siempre tomo las mejores decisiones. ¿Crees que estamos como destinadas a no ser amigas?",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_010"] = "Max, ¿cómo pudiste dejarme saltar de la azotea?",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_020"] = "Eres la única persona en quien confiaba...",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_030"] = "Pero nunca me escuchaste realmente...",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_040"] = "Ahora nunca iré al paraíso...",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_050"] = "En lugar de eso, me enviaste al infierno... Sola, para siempre...",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_070"] = "Max, ¿por qué impediste que saltara?",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_080"] = "¿Qué clase de amiga eres?",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_090"] = "Nunca me entendiste... ni lo que me pasaba...",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_100"] = "Ahora mi familia nunca me dejará en paz...",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Kate_110"] = "Y eso significa que siempre estaré sola... gracias a ti.",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Max_010"] = "Hola, Kate.",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Max_060"] = "No, Kate, solo intentaba salvarte...",
  ["Cue_E5_7B_DormsCorridor_KateDialCorridor_RTC_Max_120"] = "¡Kate, eso no es cierto! Siempre he sido tu amiga...",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_Chloe_060"] = "Claro, como si tú fueras el cocinero aquí.",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_Chloe_080"] = "Se lo diré.",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_William_050"] = "No te atrevas a cuestionar al chef.",
  ["Cue_E5_7B_Kitchen_CookingSmallTalk_William_070"] = "Lo soy, cuando tu mamá no está.",
  ["Cue_E5_7B_Kitchen_WilliamFindingkeys_William_010"] = "¡Ajá! ¡No se pueden esconder de mí por siempre!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_010"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_020"] = "¡Oye!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_030"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_040"] = "¡Hola, Max!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_050"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_060"] = "¡Disculpa, Max!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_070"] = "¡Oye!",
  ["Cue_E5_7B_LabyStealth_DavidCaught_IGE_David_080"] = "¡Ey, señorita!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_010"] = "¡No puedes escapar de mi vigilancia, señorita!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_020"] = "¿Qué te da el derecho de destruir a mi familia? ¡Responde! ¡Es una orden!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_030"] = "Admítelo, Max: ¡eres una drogadicta! ¡Una marihuanera! ¡Una fuma-porro!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_040"] = "¡Pensabas que acosaba a Kate, pero la estaba ayudando! ¿Tú qué carajo hiciste por ella?",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_070"] = "Mi bella esposa Joyce me odia por tu culpa, Max... ¿estás orgullosa?",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_080"] = "Eres una hipócrita, Max. Seré un cabrón, pero al menos soy honesto. Tú usas tu poder para beneficiarte en la vida... y joder a tus amigos hasta matarlos.",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_090"] = "Oye, Max, qué irónico que al final, yo tenga razón acerca de todo y tú termines destruyendo la ciudad.",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_100"] = "Vamos, Max, solo admite que estás celosa de mi expediente de servicio. ¡Admítelo!",
  ["Cue_E5_7B_LabyStealth_DavidMaze03_IGE_David_110"] = "Ey, Max, por favor, ven aquí. ¡Para que pueda golpearte!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_010"] = "¡Hey, espera! ¡Espera!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_020"] = "¡Maaaax!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_030"] = "¡Detente!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_040"] = "¡Te tengo!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_050"] = "¡Aquí estás!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_060"] = "Vamos, niñita.",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_070"] = "¡Maax!",
  ["Cue_E5_7B_LabyStealth_FrankCaught_IGE_Frank_080"] = "¡Aquí, Max!",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_010"] = "¡Ven acá, flacucha de mierda! ¡Te partiré en dos, fenómeno!",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_020"] = "Esos eran mis frijoles, Max... ¡Mis pinches frijoles!",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_040"] = "Imagino que no pensarás que somos amigos...",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_050"] = "Ahora estás en primer lugar en mi lista de carajos, Max.",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_080"] = "¿Cómo puedo irme al Cielo si sigues haciéndome pasar por un Infierno?",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_090"] = "Si hubieras tomado algunas de mis drogas, quizás hubieras sido mucho más feliz.",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_100"] = "Ahora que Rachel está muerta... es hora de que tú también mueras, perra...",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_110"] = "Max, necesitas ponerte en onda como Rachel... ¿Quieres drogas?",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_120"] = "Vaya, deberías haber escuchado a Chloe hablando de ti. Fue brutal. Por supuesto, ahora veo de qué hablaba...",
  ["Cue_E5_7B_LabyStealth_FrankMaze04_IGE_Frank_130"] = "¡Pssst, Max! Rachel y yo estamos flotando aquí abajo en el drenaje... ¡baja con nosotros!",
  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_010"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_020"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_040"] = "¡Hola, Max!",
  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_050"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_070"] = "Oye...",
  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_080"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_JeffersonCaught_IGE_Jefferson_100"] = "¡Oh, Max!",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_010"] = "Max... eras tan pura... tan inocente... ahora tienes que morir...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_020"] = "No intentes ocultarte, Max. ¡Ven aquí! Déjame capturarte.",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_030"] = "No puedo creer que dejaras a ese pueblerino asesinarme a sangre fría...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_040"] = "Después de todo lo que hice por ti... me acusas de hacer llorar a nuestra dulce e inocente Kate Marsh... Se supone que el arte te haga llorar... y lo hará.",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_050"] = "¿Qué le ocurrió a tu chispa, Max? Pensé que podría ser tu profesor... para toda la vida...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_060"] = "Max, recuerda lo que dijo John Lennon: \"La felicidad es un arma caliente\".|Espero que estés feliz de verme muerto...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_070"] = "Por favor, entiende, Max... el único lugar donde puedo ser yo mismo es en el cuarto oscuro...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_080"] = "Extraño esos días cuando me veías en clase con tus ojos grandes... quiero ser tu profesor de nuevo... puedo enseñarte tanto...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze01_IGE_Jefferson_090"] = "Ahora entiendo que nunca serás una artista, mucho menos fotógrafa... Ven aquí, Max. La clase terminó.",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_010"] = "Max... Max... Quiero compartir mi don contigo...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_020"] = "Ahora que Chloe está muerta, no te distraerás más en clase...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_030"] = "Ya que Kate no está más por aquí, necesito una voluntaria para el cuarto oscuro... ¿Max?",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_040"] = "Mira la lente, Max... Voltea a la derecha... Ahora a la izquierda... Muéstrame tu amor... y tu odio.",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_050"] = "Si hubieras visto a Rachel... mi ángel manchado de sangre...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_060"] = "Tú serás mi más grande retrato, Max...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_070"] = "Max... Max... Quiero compartir mi don contigo... No te atrevas a huir.",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_090"] = "Max... Max... Quiero compartir mi don contigo...",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_110"] = "Rachel, Rachel Amber... Ámbar, como su apellido... Finalmente puedo ver a través de su piel... y sentir su carne fría en descomposición.",
  ["Cue_E5_7B_LabyStealth_JeffersonMaze04_IGE_Jefferson_120"] = "Max, Rachel no solo me dio buenas tomas de sus labios... también hacía maravillas con ellos. Especialmente después de que desenterré su cuerpo para estar con ella una última vez. ¿Por qué me ves así?",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_010"] = "¡Detente! ¡Justo ahora!",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_020"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_030"] = "¡Detente!",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_040"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_050"] = "¡Oye!",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_060"] = "¡Detente, Max!",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_070"] = "¡Detente!",
  ["Cue_E5_7B_LabyStealth_NathanCaught_IGE_Nathan_080"] = "¡Ven aquí!",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_010"] = "Oye, perra, puedes hacer que me expulsen, pero no puedes escapar.",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_020"] = "¿Te excitó cuando el flacucho de tu novio me golpeó? Max, estás más trastornada y eres más peligrosa que yo...",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_040"] = "¿Mierda, realmente crees que Victoria será tu mejor amiga por siempre? ¡Te odiará toda la vida!",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_050"] = "¡Los soplones consiguen moretones!",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_060"] = "Solo una feminazi intentaría enfrentarse a un Prescott... ¡Blackwell es mi territorio, zorra!",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_070"] = "¡Admítelo, Max... solo estás celosa porque Victoria y yo hacemos todo el trabajo mientras tú no haces más que quejarte!",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_080"] = "¡La única manera en que entrarás al club Vortex es si un tornado se traga tu trasero!",
  ["Cue_E5_7B_LabyStealth_NathanMaze03_IGE_Nathan_090"] = "Chloe es una perdedora, como tú, Max. Y no puedes salvarla una y otra vez...",
  ["Cue_E5_7B_LabyStealth_NathanMaze04_IGE_Nathan_020"] = "¡Tengo un trastorno mental! ¿Merezco morir por eso, Max?",
  ["Cue_E5_7B_LabyStealth_NathanMaze04_IGE_Nathan_070"] = "Nunca nadie me ayudó, Max. Tú menos que nadie.",
  ["Cue_E5_7B_LabyStealth_NathanMaze04_IGE_Nathan_110"] = "Oye, Max, ¿qué demonios harás ahora que estoy muerto?",
  ["Cue_E5_7B_LabyStealth_NathanMaze04_IGE_Nathan_120"] = "Mierda, Max...|¡Sí que fue gracioso cuando desenterraron el cuerpo de Rachel!|\"Buuu, Rachel es comida de gusanos...\". Comedia pura. ¡Genial!",
  ["Cue_E5_7B_LabyStealth_NathanMaze04_IGE_Nathan_130"] = "Será tan genial cuando entierre tu cuerpo junto a Rachel y haga una sesión de fotos épica...",
  ["Cue_E5_7B_LabyStealth_NathanMaze04_IGE_Nathan_140"] = "Oye, Max, ¿quisieras saludar a Rachel? ¡Está posando para mí en el infierno!",
  ["Cue_E5_7B_LabyStealth_NathanMaze04_IGE_Nathan_150"] = "Vaya, Rachel se veía como una modelo zombie en ese pozo... Solo hueso, carne y gusanos. Como a mí me gusta. ¿Quieres tomarle fotos?",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze02_IGE_Wells_010"] = "Atención... Lamento informar que una de sus compañeras de clase, Maxine Caulfield, murió bajo circunstancias trágicas que prometo investigar después de terminar mi trago.",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze02_IGE_Wells_020"] = "Max Caulfield, repórtese al cuarto oscuro de inmediato. Repito, Max Caulfield, al cuarto oscuro... ¡Ahora!",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze02_IGE_Wells_030"] = "Buenas noches, Blackwell. Habla el director Wells y estoy aquí para arrojar luz sobre Max Caulfield.",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze02_IGE_Wells_040"] = "Disculpen, ¿pueden oírme?|Si saben dónde está la Srta. Caulfield, por favor, captúrenla e infórmenme a mí o a David Madsen. Se la busca por la muerte de Chloe Price y Rachel Amber. Gracias.",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_010"] = "Pobre Kate Marsh... Es como si Max la hubiera empujado ella misma de la azotea... El pobre Samuel tuvo que limpiar la sangre toda la noche.",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_020"] = "Si tan solo Kate Marsh hubiera saltado de esa azotea...|podría culpar a la Srta. Caulfield y finalmente sacarla de Blackwell. Es una mala influencia.",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_030"] = "¿Qué clase de mente enferma robaría dinero de los discapacitados? Nadie extrañará a Max ni a Chloe cuando revele su robo...",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_050"] = "La Srta. Price no puede presentarse en Blackwell en una silla de ruedas y pensar que cumpliremos todos sus caprichos...",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_060"] = "Sabía que debía darle la beca a Victoria en lugar de a Max...",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_080"] = "¿Cómo decirle a los padres de Max que su hija es una perra entrometida?",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_090"] = "Desearía poder oprimir un botón y volar esta maldita escuela en pedazos...",
  ["Cue_E5_7B_LabyStealth_PrincipalWellsMaze03_IGE_Wells_100"] = "Si descubro quiénes revisaron mis archivos... Les enviaré al cabrón de David Madsen.",
  ["Cue_E5_7B_LabyStealth_SamuelCaught_IGE_Samuel_010"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_SamuelCaught_IGE_Samuel_020"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_SamuelCaught_IGE_Samuel_030"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_SamuelCaught_IGE_Samuel_040"] = "¡Uh! ¡Oh!",
  ["Cue_E5_7B_LabyStealth_SamuelCaught_IGE_Samuel_050"] = "¡Ven aquí, joven Max!",
  ["Cue_E5_7B_LabyStealth_SamuelMaze03_IGE_Samuel_010"] = "Ven aquí, joven Max... eres mi espíritu animal...",
  ["Cue_E5_7B_LabyStealth_SamuelMaze03_IGE_Samuel_020"] = "Samuel quiere asegurarse de que nunca registres su cuarto de nuevo...",
  ["Cue_E5_7B_LabyStealth_SamuelMaze03_IGE_Samuel_030"] = "¿Tienes una bufanda que me prestes, Max?",
  ["Cue_E5_7B_LabyStealth_SamuelMaze03_IGE_Samuel_040"] = "Las ardillas ahora te odian... y tienen hambre.",
  ["Cue_E5_7B_LabyStealth_SamuelMaze03_IGE_Samuel_050"] = "Qué mal que no te hiciste amiga del Tobanga...",
  ["Cue_E5_7B_LabyStealth_WarrenCaught_IGE_Warren_010"] = "¡¡Max!!",
  ["Cue_E5_7B_LabyStealth_WarrenCaught_IGE_Warren_020"] = "¡¡Max!!",
  ["Cue_E5_7B_LabyStealth_WarrenCaught_IGE_Warren_030"] = "¡Hey!",
  ["Cue_E5_7B_LabyStealth_WarrenCaught_IGE_Warren_040"] = "¡Detente!",
  ["Cue_E5_7B_LabyStealth_WarrenCaught_IGE_Warren_050"] = "¡Hey!",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_010"] = "Max... ¿Dónde estás? Max... Sal a jugar... ¡Sal a jugar!",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_020"] = "Chango, chango, chango... ¿Quién se quiere volver chango? ¡Chango! ¡Chango, chango, chango!",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_030"] = "¿Te gusta mi auto, Max? Sube, te daré un paseo. ¡Sube al auto!",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_040"] = "Brooke me ama, ¿por qué tú no, eh? ¿Qué te hace tan especial?",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_050"] = "Max, sé que estas aquí... Puedes correr... pero no ocultarte de tu Caballero Blanco... ríndete...",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_060"] = "¿Qué pasa contigo y esa perdedora de cabello azul? ¡Necesitas un macho alfa, nena!",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_070"] = "¿Te excitó verme golpear a Nathan? A mí sí.",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_080"] = "Max... Imagina si estuviéramos en el cuarto oscuro juntos... He soñado con eso...",
  ["Cue_E5_7B_LabyStealth_WarrenMaze_IGE_Warren_090"] = "Dije \"Entra en el auto\". Ya... Iremos al autocinema y estarás cerca de mí para siempre... ¡Y nos volveremos changos, changos, changos!",
  ["Cue_E5_7B_LabyStealth_WellsCaught_IGE_Wells_010"] = "Señorita Caulfield...",
  ["Cue_E5_7B_LabyStealth_WellsCaught_IGE_Wells_020"] = "¡Espera, Max!",
  ["Cue_E5_7B_LabyStealth_WellsCaught_IGE_Wells_030"] = "¡Mírame!",
  ["Cue_E5_7B_LabyStealth_WellsCaught_IGE_Wells_040"] = "¿Max?",
  ["Cue_E5_7B_LabyStealth_WellsCaught_IGE_Wells_050"] = "¡Max!",
  ["Cue_E5_7B_LabyStealth_WellsCaught_IGE_Wells_060"] = "¡Espera, Max!",
  ["Cue_E5_7B_LabyStealth_WellsStatueCaught_IGE_Wells_010"] = "Señorita Caulfield...",
  ["Cue_E5_7B_LabyStealth_WellsStatueCaught_IGE_Wells_020"] = "¡Espera, Max!",
  ["Cue_E5_7B_LabyStealth_WellsStatueCaught_IGE_Wells_030"] = "¡Hola, Max!",
  ["Cue_E5_7B_LabyStealth_WellsStatueCaught_IGE_Wells_040"] = "¿Max?",
  ["Cue_E5_7B_LabyStealth_WellsStatueCaught_IGE_Wells_050"] = "¡Max!",
  ["Cue_E5_7B_LivingRoom_MaxPickUpPhone_William_030"] = "¿Hola?",
  ["Cue_E5_7B_LivingRoom_WilliamBeepKeys_Chloe_020"] = "¡Otro dólar para el frasco de malas palabras!",
  ["Cue_E5_7B_LivingRoom_WilliamBeepKeys_William_010"] = "Mierda, ¿dónde están las llaves?",
  ["Cue_E5_7B_LivingRoom_WilliamBeepKeys_William_030"] = "¡Me estás dejando en bancarrota!",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_Chloe_030"] = "Eres ridículo.",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_Chloe_050"] = "¡Papá!",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_Chloe_100"] = "¡Un dólar para el frasco de malas palabras!",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_010"] = "Hola cariño... Solo haciendo un fabuloso desayuno con Chloe y Max. Trabajaremos todos en Two Whales.",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_015"] = "¿Qué? Oh, no sabía que ibas a buscar las compras. Por supuesto que iré a recogerte. Ahora tengo una excusa para tomar un mocachino. Ya salgo para ahí. Te amo...",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_020"] = "Discúlpenme, señoritas, debo partir al rescate de vuestra reina de Sav-Mart.|Traerá consigo muchos manjares para vuestro deleite.",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_040"] = "Algún día me lo agradecerás.",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_045"] = "Cierren con llave cuando salga, jueguen sano,|e intenten no destruir demasiado la casa.",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_090"] = "Carajo, ¿dónde están mis llaves?",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_110"] = "Quieres decir, tu fondo para la universidad... las llaves, por favor.",
  ["Cue_E5_7B_LivingRoom_WilliamNeedCarKeys_William_140"] = "Y sepan que la cata de vinos está terminantemente prohibida para Chloe y Max...",
  ["Cue_E5_7B_Nightmare_ChloeDarkRoom_Chloe_010"] = "Ves, así es como se baila, Max… ¡No hay \"moshing\" para ti, pequeña!",
  ["Cue_E5_7B_Nightmare_ChloeDiner_Chloe_015"] = "¡Oye, no intentes meterte con su mente! ¡Ella sabe por lo que hemos pasado juntas esta semana y tú no! ¡No hay manera de que dividas nuestro equipo! ¡Esta es la realidad!",
  ["Cue_E5_7C_Beach_Insertion_Chloe_020"] = "Veo que la verdadera Max está de vuelta. Ya dime, güey, ¿cómo fue tu viaje en el tiempo?",
  ["Cue_E5_7C_Beach_Insertion_Chloe_040"] = "Parece que hasta el destino no quiere que nos separemos... Viajaste entre realidades para salvar mi desagradecido trasero una y otra vez... Espero que haya valido la pena, pero no te culpo por quererme fuera de tu vida después de todo el drama.",
  ["Cue_E5_7C_Beach_Insertion_Chloe_060"] = "Eres Max Caulfield, una valiente Guerrera del Tiempo. Aun si no lo fueras, eres amable y bondadosa... Nadie podría tener una mejor amiga... nadie. Tú no pediste que todo esto ocurriera, solo sucedió... por favor, necesitas aceptar lo increíble que eres...",
  ["Cue_E5_7C_Beach_Insertion_Chloe_080"] = "Entonces, por cualquier motivo científico místico que jamás conoceremos... debíamos estar juntas en este momento exacto de la historia... quizá es solo el poder del amor sobre toda la mierda del mundo... quiero pensar que Rachel estaba detrás de cámaras, luchando por la justicia... para finalmente impedir que Jefferson lastimara a más personas...",
  ["Cue_E5_7C_Beach_Insertion_Chloe_100"] = "Bien... salimos de la fiesta y nos aseguramos de que Jefferson no pudiera encontrarnos. Por primera vez me alegró vivir en una fortaleza... después la tormenta se salió de control y dijiste que estaríamos a salvo en el faro...",
  ["Cue_E5_7C_Beach_Insertion_Chloe_120"] = "¡Detente! ¡Deja de reprocharte! Ya pagamos nuestras deudas... mira eso... Dios, qué monstruoso... quién sabe... esta tormenta podría ser la venganza de Rachel... nuestra venganza...",
  ["Cue_E5_7C_Beach_Insertion_Chloe_130"] = "¡Max, tenías razón!",
  ["Cue_E5_7C_Beach_Insertion_Chloe_135"] = "¡El faro está fuera de la trayectoria del tornado! ¡Vamos!",
  ["Cue_E5_7C_Beach_Insertion_Chloe_150"] = "Te apoyo, Max.",
  ["Cue_E5_7C_Beach_Insertion_Max_010"] = "Ah, Chloe....",
  ["Cue_E5_7C_Beach_Insertion_Max_030"] = "Silencio. Estamos vivas... ahora dime todo lo que ocurrió... ¿lo recuerdas?",
  ["Cue_E5_7C_Beach_Insertion_Max_050"] = "Vamos, esta semana soy \"el Rey y la Reina del Drama\" en Arcadia Bay. Solo mira lo que causaron mis poderes en... tan poco tiempo. Es decir... no soy nadie.",
  ["Cue_E5_7C_Beach_Insertion_Max_070"] = "Quizás lo invoqué inconscientemente, o algo así. Siempre quise que mi vida fuera especial... una aventura... pero no sin ti. Y no ocurrió hasta que me mudé de regreso aquí, así que... sin ti, mi poder ni siquiera existiría.",
  ["Cue_E5_7C_Beach_Insertion_Max_090"] = "También me gustaría pensar que... todos estamos en deuda con Rachel Amber... ahora dime todo lo que ocurrió... ¿lo recuerdas?",
  ["Cue_E5_7C_Beach_Insertion_Max_110"] = "Chloe, mira... la tormenta está creciendo ahora. Se está acercando, oh... no puedo creer que esto sea real, pero está ocurriendo por mi culpa.",
  ["Cue_E5_7C_Beach_Insertion_Max_140"] = "Chloe…",
  ["Cue_E5_7Z_LabyChloe_Bink_Chloe_010"] = "Después de cinco años, sigues siendo Max Caulfield.",
  ["Cue_E5_7Z_LabyChloe_Bink_Max_020"] = "De verdad me alegra verte...",
  ["Cue_E5_7Z_LabyChloe_E1ChloeCar_Chloe_010"] = "Bienvenida a casa, Max.",
  ["Cue_E5_7Z_LabyChloe_E1ChloeCar_Chloe_020"] = "Ajústate el cinturón.",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_010"] = "Estabas aquí hoy, Max. ¡Me salvaste! Todavía estoy intentando entenderlo... Verte después de todos estos años se siente como...",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_030"] = "Si esto es el destino, espero que podamos encontrar a Rachel. La extraño, Max.",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_040"] = "¿Qué mierda es esto?",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_070"] = "Max, comienza desde el principio.",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Chloe_080"] = "Cuéntame todo...",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Max_020"] = "¿Destino?",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Max_050"] = "Copos de nieve...",
  ["Cue_E5_7Z_LabyChloe_E1Cliff_Max_060"] = "O una tormenta acercándose.",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_010"] = "¡Esta canción es lo máximo! ¿No puedes bailar, hippie? ¡Vamos!",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_020"] = "¡Muévete, nena!",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_030"] = "¡Oh, apágalo, apágalo!",
  ["Cue_E5_7Z_LabyChloe_E1DavidHome_Chloe_040"] = "Debes esconderte. ¡Ahora! ¡Mi padrastro me matará si te encuentra aquí!",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_010"] = "Yo, eh... Sé que fue tu cumpleaños el mes pasado.",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_020"] = "Esta era la cámara de papá... Quiero que la tengas.",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_040"] = "¡Suficientes cursilerías, siento ganas de arrojarme de un escenario! ¡Destrocemos este lugar!",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Chloe_050"] = "¡Sip, estoy loca de remate! ¡Bailemos! ¡Mueve el trasero! ¡O toma una foto con tu nueva cámara!",
  ["Cue_E5_7Z_LabyChloe_E1FriendAgain_Max_030"] = "¡Sí, claro que es estupendo! Gracias... Esta cámara es fantástica.",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_010"] = "Hablemos de tu superpoder...",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_020"] = "¡Épico!",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_030"] = "Juro lealtad a Max y al poder que representa...",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_040"] = "Puedes rebobinar el tiempo, Max. Es demasiado loco. ¡Tenemos que jugar!",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Chloe_050"] = "Necesitas una mano derecha que te guíe.",
  ["Cue_E5_7Z_LabyChloe_E2Diner_Max_060"] = "Muy bien, muchacha maravilla... Muéstrame el camino hacia la Cueva de Chloe.",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_010"] = "Bienvenida a American Rust, mi refugio del infierno.",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_030"] = "Max, ¿entiendes lo asombroso que es esto? Mi mejor amiga volvió... y mejorada.",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_050"] = "Max, espera, déjame buscar un lugar para que descanses...",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Chloe_060"] = "Sí que me asustaste. ¿Te sientes mejor?",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Max_020"] = "Salvaje y áspero. Te queda...",
  ["Cue_E5_7Z_LabyChloe_E2Junkyard_Max_040"] = "Yo... no... me siento tan súper...",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Chloe_020"] = "Siempre y cuando seamos compañeras en el tiempo.",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Chloe_030"] = "Quizás te gane al otro lado de la puerta, Lupin.",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Chloe_060"] = "Eres magistral. No tengo ni idea de cómo diablos llegaste ahí, pero lo hiciste, ¡maravilloso!",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Max_010"] = "Estoy tan contenta de que seamos compañeras en el crimen.",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Max_040"] = "Arranca la carrera. Nos vemos pronto.",
  ["Cue_E5_7Z_LabyChloe_E2PrinDoor_Max_050"] = "Bienvenida a mi humilde morada.",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Chloe_010"] = "Max, mejor ven a ver estos archivos...",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Chloe_040"] = "Max, ¿por casualidad tus poderes te permiten leer la mente? ¿O simplemente retrocediste porque intenté robar la silla? Mierda, estoy confundida.",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Max_020"] = "No es un dibujo... Mira: \"Rachel en el cuarto oscuro... Rachel en el cuarto oscuro...\". Una y otra vez. Solo eso.",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Max_030"] = "No, esa silla tan cómoda no será tuya.",
  ["Cue_E5_7Z_LabyChloe_E2PrinOffice_Max_050"] = "Son los beneficios de las mejores amigas. Ya veo cómo eres...",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Chloe_010"] = "Volviste a salvarme. Qué loco. ¡Ahora estamos unidas para siempre!",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Chloe_020"] = "Ya que tú eres la superheroína misteriosa... Yo seré tu chofer y compañera fiel.",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Chloe_040"] = "No importa... nosotras sí. Para siempre.",
  ["Cue_E5_7Z_LabyChloe_E2Railroad_Max_030"] = "Tal vez mis poderes no duren mucho, Chloe.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomKiss_Chloe_010"] = "Te requetedesafío. Bésame ahora.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomKiss_Chloe_020"] = "¡Órale, eres intensa, Max! Voy a mensajear a Warren y decirle que no tiene oportunidad alguna... a menos que disfrute ver tortilleras.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomKiss_Max_030"] = "Eres tan ñoña.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Chloe_010"] = "Te requetedesafío. Bésame ahora.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Chloe_030"] = "Ah, claro, ¿yo sí? ¡Solo admite que ya intentaste ligarme y luego te rajaste! Ahora puedo mensajear a Warren y contarle que te estás reservando para él...",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Max_020"] = "Lo siento, pero no soy tan fácil.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomNoKiss_Max_040"] = "Eres tan ñoña.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Chloe_010"] = "¡Photobomb!",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Chloe_040"] = "Dejamos una marca en el asfalto en Blackwell anoche.",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Max_020"] = "Robando cámara...",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Max_030"] = "Parece un mundo distinto al de ayer…",
  ["Cue_E5_7Z_LabyChloe_E3ChloeRoomWakeUp_Max_050"] = "Ojalá pudiéramos pasar toda la mañana juntas como hacíamos antes... Tal vez deberíamos levantarnos, tengo que regresar a Blackwell pronto.",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_010"] = "Ahh, ¡podríamos viajar a todos lados en esta maravilla! ¿Nos imaginas viajando por la costa hasta Big Sur y más allá?",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_020"] = "Lo sé. Solo sueño despierta.",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_030"] = "Me enferma que Rachel haya posado así para Frank... o que le haya escrito cartas de amor... ¡No puedo creer que se estaba cogiendo a Frank! ¡Rachel me mintió en la cara! ¿Por qué no dijo nada?",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Chloe_050"] = "¿Qué clase de amiga era? Solo otra persona que me traiciona. ¿Por qué todos en mi vida terminan por defraudarme? Mi padre muere, tú me abandonas, mamá decide casarse con ese hijo de la chingada... y ahora Rachel me traiciona…",
  ["Cue_E5_7Z_LabyChloe_E3FrankRV_Max_040"] = "Porque sabía cómo ibas a reaccionar.",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Chloe_010"] = "¡No antes de que la vea! ¡Ya conoces las reglas, papá!",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Chloe_020"] = "Vaya, soy tan afortunada de tener a un padre tan buena onda...",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Chloe_030"] = "Max, estás comportándote tan extraña. ¿Te sientes bien?",
  ["Cue_E5_7Z_LabyChloe_E3Polarewind_Max_040"] = "Chloe, soy... lo máximo. ¡Somos lo máximo!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Chloe_020"] = "Te ves linda con el pelo empapado en químicos.",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Chloe_040"] = "¡Escóndete!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Chloe_050"] = "No puedes volver a la residencia ahora, ¡eres una fugitiva! Quédate en mi casa esta noche.",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Max_010"] = "Digamos que fue un empate. Me voy a poner chinita cuando salga...",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolRun_Max_030"] = "¡Escóndete!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Chloe_020"] = "Mira, ¡una nutria en el agua!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Chloe_030"] = "Tu poder está cambiando todo, Max. Especialmente a ti. Ya me di cuenta. Ya no eres tan rajona.",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Chloe_050"] = "Y me haces sentir como que tengo una razón para quedarme un tiempo en Arcadia Bay.",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Max_010"] = "¡Cowabunga!",
  ["Cue_E5_7Z_LabyChloe_E3SwimPoolSwim_Max_040"] = "Gracias nena.",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_010"] = "Es extraño pasar tiempo contigo de nuevo.",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_030"] = "Mira, lo peor que puedes hacerme es tratarme como a una bebé. Todavía quiero reírme y decir estupideces con mi mejor amiga.",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_040"] = "¿Podemos parar?",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Chloe_050"] = "En serio, esta es la mejor vista del atardecer. ¿Cómo la llaman los fotógrafos?",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Max_020"] = "Lo sé... me alegra que lo hagamos.",
  ["Cue_E5_7Z_LabyChloe_E4Beach_Max_060"] = "“La hora dorada”.",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Chloe_030"] = "¡Rachel...!",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Chloe_040"] = "Esto no puede ser real... Ella... ella posó... en estas fotos ¿verdad? ¿VERDAD?",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Chloe_050"] = "¡El depósito de chatarra, Max! ¡Tenemos que encontrar ese lugar ahora mismo! Entonces podremos ver lo que él hizo... No es posible que ella esté muerta. ¡No! Ella posó para esas fotos, lo sé. Te lo ruego... ¡Vamos!",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Max_010"] = "Kate no fue la primera... todas esas carpetas están llenas de otras víctimas.",
  ["Cue_E5_7Z_LabyChloe_E4DarkRoom_Max_020"] = "Victoria debe ser la siguiente. Apuesto a que Nathan planea drogarla en la fiesta del club Vortex esta noche.",
  ["Cue_E5_7Z_LabyChloe_E4DetectiveBoard_Chloe_030"] = "Suenas drogada, pero gracias por las caricias. Ya que estuvimos despiertas toda la noche jugando a&nbsp;\"CSI:&nbsp;Arcadia Bay\", estaba intentando conectar toda la información.",
  ["Cue_E5_7Z_LabyChloe_E4DetectiveBoard_Max_010"] = "Chloe... estás de vuelta.",
  ["Cue_E5_7Z_LabyChloe_E4DetectiveBoard_Max_020"] = "Yo solo... yo solo, ¡estoy tan contenta de que estés aquí!",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Chloe_010"] = "Rachel...|Por Dios, Rachel...|No... no... no...|Por favor, no... no ella...",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Chloe_030"] = "¡Rachel! No... ¡¿Por qué?!",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Chloe_050"] = "Yo la amaba tanto...|No puede haber muerto.|¿En qué mundo pasa esto?|¡¿Quién hizo esto?!",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Max_020"] = "Chloe...",
  ["Cue_E5_7Z_LabyChloe_E4JunkyardRachel_Max_040"] = "Lo siento mucho Chloe, lo siento...",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Chloe_010"] = "Vaya, qué foto tan genial. Nos vemos cabronas como piratas.",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Chloe_030"] = "Escucha, Max, mi sistema respiratorio está fallando y... y solo está empeorando.|He escuchado a los doctores hablar cuando creían que estaba desmayada.|Así que solo están posponiendo lo inevitable,|y mis padres sufren todo este proceso... al igual que yo.|Así no es como quiero que termine.",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Chloe_050"] = "Estoy diciendo que estar contigo de nuevo ha sido muy especial. Solo quería sentir como cuando éramos niñas corriendo por Arcadia Bay... y todo era posible.|Y me hiciste sentir así hoy. Quiero que este tiempo contigo sea mi último recuerdo...|¿Entiendes?",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Max_020"] = "Debimos adueñarnos de Arcadia Bay cuando tuvimos la oportunidad.",
  ["Cue_E5_7Z_LabyChloe_E4MedicalBed_Max_040"] = "¿Qué? ¿Qué estás diciendo?",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_010"] = "¡Vamos, Max, ya casi llegamos!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_020"] = "¡Por favor, despierta!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_030"] = "Max, ¿puedes oírme?",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_040"] = "¡Resiste Max, podemos lograrlo!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_050"] = "¡Escúchame! ¡Max!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_060"] = "¡Estamos cerca del faro! ¡Despierta!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_070"] = "¡Demonios, Max! ¡No me decepciones!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_080"] = "¡Max, vamos, ahora!",
  ["Cue_E5_7Z_LabyChloe_End_Chloe_090"] = "No te preocupes, estaremos bien.",
  ["Cue_E5_9A_Toilets_Ending_Chloe_010"] = "Espero que hayas verificado el perímetro, como diría el idiota de mi padrastro.",
  ["Cue_E5_9A_Toilets_Ending_Chloe_020"] = "Ahora, hablemos de negocios—",
  ["Cue_E5_9A_TownEnd_CliffEndChloeDead_Max_010"] = "Chloe... Au revoir…",
  ["Cue_E5_9A_TownEnd_NathanArrested_David_020"] = "Tú... ¡Hijo de puta!",
  ["Cue_E5_9A_TownEnd_NathanArrested_David_040"] = "Chloe... no... Por favor…",
  ["Cue_E5_9A_TownEnd_NathanArrested_David_050"] = "Chloe... siento no haber llegado a tiempo... perdón...",
}
